INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(0, '580489', 'en', 'https://image.tmdb.org/t/p/w500/pzKsRuKLFmYrW5Q0q8E8G78Tcgo.jpg', 'Venom: Let There Be Carnage', '5401.308', '2021-09-30', 6.8, '1736', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'After finding a host body in investigative reporter Eddie Brock, the alien symbiote must face a new enemy, Carnage, the alter ego of serial killer Cletus Kasady.'),
(1, '524434', 'en', 'https://image.tmdb.org/t/p/w500/lFByFSLV5WDJEv3KabbdAF959F2.jpg', 'Eternals', '3365.535', '2021-11-03', 7.1, '622', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\']', 'The Eternals are a team of ancient aliens who have been living on Earth in secret for thousands of years. When an unexpected tragedy forces them out of the shadows, they are forced to reunite against mankind’s most ancient enemy, the Deviants.'),
(2, '438631', 'en', 'https://image.tmdb.org/t/p/w500/d5NXSklXo0qyIYkgV94XAgMIckC.jpg', 'Dune', '2911.423', '2021-09-15', 8, '3632', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet\'s exclusive supply of the most precious resource in existence-a commodity capable of unlocking humanity\'s greatest potential-only those who can conquer their fear will survive.'),
(3, '796499', 'en', 'https://image.tmdb.org/t/p/w500/j04Oepj3LGTWSb1ltXm0pcy50Xq.jpg', 'Army of Thieves', '2552.437', '2021-10-27', 6.9, '555', '[\'Action\', \'Crime\', \'Thriller\']', 'A mysterious woman recruits bank teller Ludwig Dieter to lead a group of aspiring thieves on a top-secret heist during the early stages of the zombie apocalypse.'),
(4, '550988', 'en', 'https://image.tmdb.org/t/p/w500/dxraF0qPr1OEgJk17ltQTO84kQF.jpg', 'Free Guy', '1850.47', '2021-08-11', 7.8, '3493', '[\'Comedy\', \'Action\', \'Adventure\', \'Science Fiction\']', 'A bank teller called Guy realizes he is a background character in an open world video game called Free City that will soon go offline.'),
(5, '574060', 'en', 'https://image.tmdb.org/t/p/w500/56ofGPMOZCwlTjTao5fB7vnGOoj.jpg', 'Gunpowder Milkshake', '1453.423', '2021-07-14', 6.5, '347', '[\'Action\', \'Thriller\', \'Crime\']', 'In her turbulent life as a professional assassin, Sam has no choice but to go rogue to save the life of an innocent 8-year-old girl in the middle of the gang war she has unleashed.'),
(6, '335983', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'Venom', '1212.352', '2018-09-28', 6.8, '12126', '[\'Science Fiction\', \'Action\']', 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.'),
(7, '610253', 'en', 'https://image.tmdb.org/t/p/w500/4CclCDyQXBBgz62Qtp3CoflQE5g.jpg', 'Halloween Kills', '1023.024', '2021-10-14', 7, '1134', '[\'Horror\', \'Thriller\']', 'Minutes after Laurie Strode, her daughter Karen and granddaughter Allyson left masked monster Michael Myers caged and burning in Laurie\'s basement, Laurie is rushed to the hospital with life-threatening injuries, believing she finally killed her lifelong tormentor. But when Michael manages to free himself from Laurie\'s trap, his ritual bloodbath resumes. As Laurie fights her pain and prepares to defend herself against him, she inspires all of Haddonfield to rise up against their unstoppable monster. The Strode women join a group of other survivors of Michael\'s first rampage who decide to take matters into their own hands, forming a vigilante mob that sets out to hunt Michael down, once and for all.'),
(8, '871964', 'pl', 'https://image.tmdb.org/t/p/w500/6QvepemlDGIiiYsVs0Y1ieFuG7N.jpg', 'W lesie dziś nie zaśnie nikt 2', '1089.852', '2021-10-27', 4.1, '72', '[\'Horror\', \'Thriller\']', 'When something horrible happens to the only survivor of a bloody massacre, an insecure rookie cop must overcome his fears to stop further carnage.'),
(9, '768449', 'en', 'https://image.tmdb.org/t/p/w500/xoNWf2GnEF87a8SbpB1NvhX2zr0.jpg', 'American Badger', '1148.822', '2021-03-05', 6.3, '14', '[\'Action\', \'Thriller\']', 'A seemingly cold-blooded hitman is assigned to befriend a call girl, but all hell breaks loose when he is assigned to kill her.'),
(10, '639721', 'en', 'https://image.tmdb.org/t/p/w500/ld7YB9vBRp1GM1DT3KmFWSmtBPB.jpg', 'The Addams Family 2', '1031.821', '2021-10-01', 7.4, '562', '[\'Animation\', \'Comedy\', \'Family\']', 'The Addams get tangled up in more wacky adventures and find themselves involved in hilarious run-ins with all sorts of unsuspecting characters.'),
(11, '843241', 'ja', 'https://image.tmdb.org/t/p/w500/k0ThmZQl5nHe4JefC2bXjqtgYp0.jpg', '劇場版 七つの大罪 光に呪われし者たち', '1108.815', '2021-07-02', 8.4, '210', '[\'Animation\', \'Action\']', 'With the help of the \"Dragon Sin of Wrath\" Meliodas and the worst rebels in history, the Seven Deadly Sins, the \"Holy War\", in which four races, including Humans, Goddesses, Fairies and Giants fought against the Demons, is finally over. At the cost of the \"Lion Sin of Pride\" Escanor\'s life, the Demon King was defeated and the world regained peace. After that, each of the Sins take their own path.'),
(12, '566525', 'en', 'https://image.tmdb.org/t/p/w500/d08HqqeBQSwN8i8MEvpsZ8Cb438.jpg', 'Shang-Chi and the Legend of the Ten Rings', '1327.18', '2021-09-01', 7.7, '1414', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.'),
(13, '568620', 'en', 'https://image.tmdb.org/t/p/w500/uIXF0sQGXOxQhbaEaKOi2VYlIL0.jpg', 'Snake Eyes: G.I. Joe Origins', '1052.222', '2021-07-22', 6.9, '786', '[\'Action\', \'Adventure\']', 'After saving the life of their heir apparent, tenacious loner Snake Eyes is welcomed into an ancient Japanese clan called the Arashikage where he is taught the ways of the ninja warrior. But, when secrets from his past are revealed, Snake Eyes\' honor and allegiance will be tested – even if that means losing the trust of those closest to him.'),
(14, '630004', 'en', 'https://image.tmdb.org/t/p/w500/eMXA8Mbl9P9kNVGhMKqwr5Xni8C.jpg', 'The Vault', '1046.86', '2021-03-03', 7.1, '392', '[\'Crime\', \'Action\', \'Thriller\']', 'When an engineer learns of a mysterious, impenetrable fortress hidden under The Bank of Spain, he joins a crew of master thieves who plan to steal the legendary lost treasure locked inside while the whole country is distracted by Spain\'s World Cup Final. With thousands of soccer fans cheering in the streets, and security forces closing in, the crew have just minutes to pull off the score of a lifetime.'),
(15, '672582', 'en', 'https://image.tmdb.org/t/p/w500/52E0LGcMKHOO91P4j6hdHKVwITP.jpg', 'The Deep House', '848.536', '2021-06-30', 5.5, '112', '[\'Horror\']', 'While diving in a remote French lake, a couple of YouTubers who specialize in underwater exploration videos discover a house submerged in the deep waters. What was initially a unique finding soon turns into a nightmare when they discover that the house was the scene of atrocious crimes. Trapped, with their oxygen reserves falling dangerously, they realize the worst is yet to come: they are not alone in the house.'),
(16, '760747', 'no', 'https://image.tmdb.org/t/p/w500/ebG8W3shUDBqhOz3VmB4m02HkFf.jpg', 'I onde dager', '863.019', '2021-07-30', 6.8, '118', '[\'Action\', \'Comedy\', \'Thriller\', \'Horror\']', 'A dysfunctional couple head to a remote lakeside cabin under the guise of reconnecting, but each has secret designs to kill the other. Before they can carry out their respective plans, unexpected visitors arrive and the couple is faced with a greater danger than anything they could have plotted.'),
(17, '675319', 'en', 'https://image.tmdb.org/t/p/w500/fjtlMqX1QfiMvk8IgkKJR1vXzZ7.jpg', 'Zone 414', '797.785', '2021-09-03', 5.8, '86', '[\'Science Fiction\', \'Thriller\', \'Mystery\']', 'In the near future on a colony of state-of-the-art robots, a private investigator is hired by the colony\'s creator to bring his missing daughter home.'),
(18, '635302', 'ja', 'https://image.tmdb.org/t/p/w500/h8Rb9gBr48ODIwYUttZNYeMWeUU.jpg', '劇場版「鬼滅の刃」無限列車編', '897.913', '2020-10-16', 8.4, '1833', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\']', 'Tanjirō Kamado, joined with Inosuke Hashibira, a boy raised by boars who wears a boar\'s head, and Zenitsu Agatsuma, a scared boy who reveals his true power when he sleeps, boards the Infinity Train on a new mission with the Fire Hashira, Kyōjurō Rengoku, to defeat a demon who has been tormenting the people and killing the demon slayers who oppose it!'),
(19, '645788', 'en', 'https://image.tmdb.org/t/p/w500/iQUj7MptHUlcXpaMLrqRNZRxGA9.jpg', 'The Protégé', '832.048', '2021-08-19', 6.8, '330', '[\'Action\', \'Crime\', \'Thriller\']', 'Rescued as a child by the legendary assassin Moody and trained in the family business, Anna is the world’s most skilled contract killer. When Moody, the man who was like a father to her and taught her everything she needs to know about trust and survival, is brutally killed, Anna vows revenge. As she becomes entangled with an enigmatic killer whose attraction to her goes way beyond cat and mouse, their confrontation turns deadly and the loose ends of a life spent killing will weave themselves ever tighter.'),
(20, '879163', 'pt', 'https://image.tmdb.org/t/p/w500/nH0EycssY8aFJxElTsGSRirP9qr.jpg', 'Peçanha Contra o Animal', '943.619', '2021-10-22', 5.4, '13', '[\'Comedy\', \'Crime\']', ''),
(21, '589754', 'ru', 'https://image.tmdb.org/t/p/w500/5VJSIAhSn4qUsg5nOj4MhQhF5wQ.jpg', 'Последний богатырь: Корень зла', '835.043', '2021-01-01', 7, '63', '[\'Fantasy\', \'Adventure\', \'Comedy\']', 'Peace and tranquility have set in Belogorie. The evil was defeated and Ivan is now enjoying his well-deserved fame. He is surrounded by his family, friends and small wonders from the modern world that help him lead a comfortable life. Luckily, he has his Magic Sword to cut a gap between the worlds to get some supplies quite regularly. But when an ancient evil rises and the existence of the magic world is put to danger, Ivan has to team up with his old friends and his new rivals. They will set out on a long journey beyond the known world to find a way to defeat the enemies and to return peace to Belogorie.'),
(22, '846167', 'pl', 'https://image.tmdb.org/t/p/w500/i4CLIpT1lEOtVvOsF3dajDTXxuc.jpg', 'W jak morderstwo', '957.866', '2021-06-18', 5.8, '25', '[\'Crime\', \'Mystery\', \'Drama\', \'Comedy\']', 'A stay-at-home mom and avid reader of crime stories discovers the deepest secrets of a small town\'s residents while investigating a woman\'s murder.'),
(23, '436969', 'en', 'https://image.tmdb.org/t/p/w500/q61qEyssk2ku3okWICKArlAdhBn.jpg', 'The Suicide Squad', '807.497', '2021-07-28', 7.8, '4695', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Supervillains Harley Quinn, Bloodsport, Peacemaker and a collection of nutty cons at Belle Reve prison join the super-secret, super-shady Task Force X as they are dropped off at the remote, enemy-infused island of Corto Maltese.'),
(24, '703771', 'en', 'https://image.tmdb.org/t/p/w500/vFIHbiy55smzi50RmF8LQjmpGcx.jpg', 'Deathstroke: Knights & Dragons - The Movie', '787.704', '2020-08-04', 7, '294', '[\'Animation\', \'Action\', \'Adventure\', \'Science Fiction\']', 'The assassin Deathstroke tries to save his family from the wrath of H.I.V.E. and the murderous Jackal.'),
(25, '459151', 'en', 'https://image.tmdb.org/t/p/w500/kv2Qk9MKFFQo4WQPaYta599HkJP.jpg', 'The Boss Baby: Family Business', '761.177', '2021-07-01', 7.7, '1582', '[\'Animation\', \'Comedy\', \'Adventure\', \'Family\']', 'The Templeton brothers — Tim and his Boss Baby little bro Ted — have become adults and drifted away from each other. But a new boss baby with a cutting-edge approach and a can-do attitude is about to bring them together again … and inspire a new family business.'),
(26, '820511', 'en', 'https://image.tmdb.org/t/p/w500/eJ0q6GIac00TvanshEDREQ79mpz.jpg', 'Ripper Untold', '678.956', '2021-06-28', 6.5, '47', '[\'Horror\']', 'A detective and a medical examiner join forces to solve a series of horrific murders in Victorian London - but one of them harbours a deadly secret.'),
(27, '772436', 'es', 'https://image.tmdb.org/t/p/w500/jxdKa1467pktAILLbfw6kZyQlbW.jpg', 'Matando Cabos 2: La Máscara del Máscara', '693.568', '2021-10-01', 7.9, '57', '[\'Action\', \'Comedy\', \'Adventure\']', 'Faced with the unexpected death of his estranged father -El Máscara- and the subsequent theft of his precious mask, Rubén -Mascarita- will find himself confronted with his past. Alongside his invincible bodyguard Tony \"The Cannibal\" and, an unexpected ally, he will have only one day to recover it and make amends with the memory of his father.'),
(28, '385128', 'en', 'https://image.tmdb.org/t/p/w500/deEmLILTPejEb6OGsXRJ5MCvyDW.jpg', 'F9', '701.647', '2021-05-19', 7.4, '4302', '[\'Action\', \'Crime\', \'Thriller\']', 'Dominic Toretto and his crew battle the most skilled assassin and high-performance driver they\'ve ever encountered: his forsaken brother.'),
(29, '451048', 'en', 'https://image.tmdb.org/t/p/w500/yKy9ELL8CON5sqDg4yIvBb5LTZL.jpg', 'Jungle Cruise', '683.909', '2021-07-28', 7.8, '3111', '[\'Adventure\', \'Fantasy\', \'Comedy\', \'Action\']', 'Dr. Lily Houghton enlists the aid of wisecracking skipper Frank Wolff to take her down the Amazon in his dilapidated boat. Together, they search for an ancient tree that holds the power to heal – a discovery that will change the future of medicine.'),
(30, '508943', 'en', 'https://image.tmdb.org/t/p/w500/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg', 'Luca', '639.636', '2021-06-17', 8, '5020', '[\'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.'),
(31, '613098', 'es', 'https://image.tmdb.org/t/p/w500/kZBA6UFI9KTS5kZdEtGmw9PqdWZ.jpg', 'Operación Camarón', '585.313', '2021-06-24', 5.5, '17', '[\'Comedy\']', 'Geeky-looking Sebas is a surprisingly good classical musician. He’s also a complete unknown in the criminal underworld, and as a new newbie on the police force, that makes him the perfect man for a dangerous mission: to go undercover as a keyboard player for “Los Lolos”, a cheesy flamenco-trap band, who have been hired to play at the wedding of a local mafia boss’ daughter that a major drug trafficker will be attending.  Sebas is keen to take on the mission, blissfully unaware that he will turn out to be even cheesier than Lolo, the band’s lead singer, and fall in love with his sister, Luci. Now Sebas will face a tough choice: remain loyal to his new friends or complete his police mission.'),
(32, '497698', 'en', 'https://image.tmdb.org/t/p/w500/7JPpIjhD2V0sKyFvhB9khUMa30d.jpg', 'Black Widow', '624.488', '2021-07-07', 7.7, '5823', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Natasha Romanoff, also known as Black Widow, confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.'),
(33, '760195', 'en', 'https://image.tmdb.org/t/p/w500/Ah056BdaMIaMBOi2lZlfgtPJ84s.jpg', 'Separation', '557.939', '2021-04-30', 6, '77', '[\'Horror\']', 'A young girl finds solace in her artist father and the ghost of her dead mother.'),
(34, '675445', 'en', 'https://image.tmdb.org/t/p/w500/jXavWyam2VPR6bOhLwwuP3K2Hw4.jpg', 'PAW Patrol: The Movie', '596.854', '2021-08-09', 7.7, '660', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'Ryder and the pups are called to Adventure City to stop Mayor Humdinger from turning the bustling metropolis into a state of chaos.'),
(35, '744275', 'en', 'https://image.tmdb.org/t/p/w500/dU4HfnTEJDf9KvxGS9hgO7BVeju.jpg', 'After We Fell', '625.512', '2021-09-01', 7.4, '766', '[\'Romance\', \'Drama\']', 'Just as Tessa\'s life begins to become unglued, nothing is what she thought it would be. Not her friends nor her family. The only person that she should be able to rely on is Hardin, who is furious when he discovers the massive secret that she\'s been keeping. Before Tessa makes the biggest decision of her life, everything changes because of revelations about her family.'),
(36, '839436', 'en', 'https://image.tmdb.org/t/p/w500/6WcJ4cV2Y3gnTYp5zHu968TYmTJ.jpg', 'Dragon Fury', '580.002', '2021-06-15', 6, '21', '[\'Horror\', \'Fantasy\', \'Mystery\']', 'A group of soldiers are taken to the mountains of Wales to investigate a strange beast.'),
(37, '874948', 'tr', 'https://image.tmdb.org/t/p/w500/oPE5GXHaTlu5eRcd4USuOX3A1mf.jpg', 'Kin', '579.316', '2021-10-08', 6.6, '32', '[\'Crime\', \'Drama\', \'Thriller\']', 'Ahead of a promotion, a police chief becomes entangled in a deadly incident and uncovers an intrigue fueled by grudge that threatens his colleagues.'),
(38, '864873', 'en', 'https://image.tmdb.org/t/p/w500/m0mYmlN9AewOGSOl7Q1ZgZvEeUU.jpg', 'Hypnotic', '514.169', '2021-10-27', 6.2, '214', '[\'Thriller\', \'Drama\', \'Horror\']', 'A young woman seeking self-improvement enlists the help of a renowned hypnotist but, after a handful of intense sessions, discovers unexpected and deadly consequences.'),
(39, '354912', 'en', 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', 'Coco', '573.567', '2017-10-27', 8.2, '14756', '[\'Family\', \'Animation\', \'Fantasy\', \'Music\', \'Comedy\', \'Adventure\']', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel\'s family history.'),
(40, '812204', 'en', 'https://image.tmdb.org/t/p/w500/kETYRGA15L0wkVPugSl8lKmSgFn.jpg', 'Rock Dog 2: Rock Around the Park', '611.612', '2021-06-24', 7.6, '25', '[\'Animation\', \'Comedy\', \'Music\', \'Family\']', 'When Bodi and his band \'True Blue\' leave Snow Mountain, to tour with pop sensation, Lil\' Foxy, they learn that fame comes at a price.'),
(41, '379686', 'en', 'https://image.tmdb.org/t/p/w500/mDACFTANR34u6lvucazoYiFJOp7.jpg', 'Space Jam: A New Legacy', '525.266', '2021-07-08', 7.3, '2550', '[\'Animation\', \'Comedy\', \'Family\', \'Science Fiction\']', 'When LeBron and his young son Dom are trapped in a digital space by a rogue A.I., LeBron must get them home safe by leading Bugs, Lola Bunny and the whole gang of notoriously undisciplined Looney Tunes to victory over the A.I.\'s digitized champions on the court. It\'s Tunes versus Goons in the highest-stakes challenge of his life.'),
(42, '637649', 'en', 'https://image.tmdb.org/t/p/w500/M7SUK85sKjaStg4TKhlAVyGlz3.jpg', 'Wrath of Man', '541.957', '2021-04-22', 7.8, '2598', '[\'Action\', \'Crime\', \'Thriller\']', 'A cold and mysterious new security guard for a Los Angeles cash truck company surprises his co-workers when he unleashes precision skills during a heist. The crew is left wondering who he is and where he came from. Soon, the marksman\'s ultimate motive becomes clear as he takes dramatic and irrevocable steps to settle a score.'),
(43, '524369', 'en', 'https://image.tmdb.org/t/p/w500/1UkbPQspPbq1FPbFP4VV1ELCfSN.jpg', 'The Many Saints of Newark', '593.17', '2021-09-22', 6.8, '201', '[\'Crime\', \'Drama\']', 'Young Anthony Soprano is growing up in one of the most tumultuous eras in Newark, N.J., history, becoming a man just as rival gangsters start to rise up and challenge the all-powerful DiMeo crime family. Caught up in the changing times is the uncle he idolizes, Dickie Moltisanti, whose influence over his nephew will help shape the impressionable teenager into the all-powerful mob boss, Tony Soprano.'),
(44, '777620', 'en', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSnU7WEJGSkZlv6pjJ_4ysqZyBkyBecq_bVyw&s', 'Caged', '475.873', '2021-01-26', 6.6, '39', '[\'Thriller\', \'Horror\']', 'An African American male is imprisoned and placed in solitary confinement after being found guilty of murdering his wife, as he\'s haunted by internal demons and his dead wife, and pushed to the breaking point by an abusive female guard.'),
(45, '831405', 'en', 'https://image.tmdb.org/t/p/w500/rzrSeqqpm1BwJ3tcTznztBtLLSD.jpg', 'Injustice', '563.221', '2021-10-09', 8, '339', '[\'Animation\', \'Science Fiction\', \'Fantasy\', \'Action\']', 'When Lois Lane is killed, an unhinged Superman decides to take control of the Earth. Determined to stop him, Batman creates a team of freedom-fighting heroes. But when superheroes go to war, can the world survive?'),
(46, '681887', 'en', 'https://image.tmdb.org/t/p/w500/6Wm7P6y22UZA40QuPYHyWyJ6leI.jpg', 'Cosmic Sin', '503.598', '2021-03-12', 4.4, '363', '[\'Science Fiction\']', 'In the year 2524, four centuries after humans started colonizing the outer planets, retired General James Ford gets called back into service when a hostile alien fleet attacks soldiers on a remote planet. The threat against mankind soon escalates into an interstellar war as Ford and a team of elite soldiers try to stop the imminent attack before it\'s too late.'),
(47, '337404', 'en', 'https://image.tmdb.org/t/p/w500/hjS9mH8KvRiGHgjk6VUZH7OT0Ng.jpg', 'Cruella', '510.735', '2021-05-26', 8.3, '5879', '[\'Comedy\', \'Crime\']', 'In 1970s London amidst the punk rock revolution, a young grifter named Estella is determined to make a name for herself with her designs. She befriends a pair of young thieves who appreciate her appetite for mischief, and together they are able to build a life for themselves on the London streets. One day, Estella’s flair for fashion catches the eye of the Baroness von Hellman, a fashion legend who is devastatingly chic and terrifyingly haute. But their relationship sets in motion a course of events and revelations that will cause Estella to embrace her wicked side and become the raucous, fashionable and revenge-bent Cruella.'),
(48, '637534', 'fr', 'https://image.tmdb.org/t/p/w500/nLanxl7Xhfbd5s8FxPy8jWZw4rv.jpg', 'BAC Nord', '486.411', '2021-08-18', 7.7, '483', '[\'Crime\', \'Thriller\']', 'A police brigade working in the dangerous northern neighborhoods of Marseille, where the level of crime is higher than anywhere else in France.'),
(49, '460465', 'en', 'https://image.tmdb.org/t/p/w500/ybrX94xQm8lXYpZAPRmwD9iIbWP.jpg', 'Mortal Kombat', '495.192', '2021-04-07', 7.3, '4000', '[\'Action\', \'Fantasy\', \'Adventure\']', 'Washed-up MMA fighter Cole Young, unaware of his heritage, and hunted by Emperor Shang Tsung\'s best warrior, Sub-Zero, seeks out and trains with Earth\'s greatest champions as he prepares to stand against the enemies of Outworld in a high stakes battle for the universe.'),
(50, '774021', 'en', 'https://image.tmdb.org/t/p/w500/ne0wAvbmzk72svslxjuFySrXEKw.jpg', 'Demonic', '422.784', '2021-07-29', 4.9, '74', '[\'Horror\', \'Thriller\']', 'A young woman unleashes terrifying demons when supernatural forces at the root of a decades-old rift between mother and daughter are ruthlessly revealed.'),
(51, '859041', 'zh', 'https://image.tmdb.org/t/p/w500/jVAEVDNdUPRKJ7hJ4zt6lGcLATD.jpg', '疯狂的拳头', '504.28', '2017-05-25', 7.6, '37', '[\'Action\']', 'After an opponent dies mid-match, a prominent MMA champion swore never to fight again and retired to run his family\'s company. But when his best friend dies under suspicious circumstances, he has no choice but to step back in the ring.'),
(52, '662708', 'ja', 'https://image.tmdb.org/t/p/w500/9Ow7PJcAHMMxgSIjCW6RnRqE9OA.jpg', '劇場版ポケットモンスター ココ', '510.2', '2020-12-25', 7.3, '59', '[\'Animation\', \'Adventure\']', 'In the Forest of Okoya, Koko is a feral child who has been raised as a Pokémon by the Mythical Pokémon Zarude. Koko has grown up never doubting that he is a Pokémon even though he can\'t really use any sort of moves. Ash Ketchum and Pikachu meet Koko and help him protect the Great Tree from the crooked scientist Dr. Zed.'),
(53, '588228', 'en', 'https://image.tmdb.org/t/p/w500/34nDCQZwaEvsy4CFO5hkGRFDCVU.jpg', 'The Tomorrow War', '439.548', '2021-07-02', 8.1, '4522', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'The world is stunned when a group of time travelers arrive from the year 2051 to deliver an urgent message: Thirty years in the future, mankind is losing a global war against a deadly alien species. The only hope for survival is for soldiers and civilians from the present to be transported to the future and join the fight. Among those recruited is high school teacher and family man Dan Forester. Determined to save the world for his young daughter, Dan teams up with a brilliant scientist and his estranged father in a desperate quest to rewrite the fate of the planet.'),
(54, '581726', 'en', 'https://image.tmdb.org/t/p/w500/niw2AKHz6XmwiRMLWaoyAOAti0G.jpg', 'Infinite', '430.839', '2021-09-09', 6.9, '553', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'Evan McCauley has skills he never learned and memories of places he has never visited. Self-medicated and on the brink of a mental breakdown, a secret group that call themselves “Infinites” come to his rescue, revealing that his memories are real.'),
(55, '631843', 'en', 'https://image.tmdb.org/t/p/w500/vclShucpUmPhdAOmKgf3B3Z4POD.jpg', 'Old', '427.735', '2021-07-21', 6.7, '1593', '[\'Thriller\', \'Mystery\', \'Horror\']', 'A group of families on a tropical holiday discover that the secluded beach where they are staying is somehow causing them to age rapidly – reducing their entire lives into a single day.'),
(56, '882206', 'en', 'https://image.tmdb.org/t/p/w500/vbc8H3SR3BM6TZkJw6UBN4ekdjK.jpg', 'LOL Surprise: The Movie', '414.698', '2021-10-08', 7.5, '31', '[\'Animation\', \'Family\']', 'Dazzling doll sisters Queen Bee and Royal Bee make their first movie with help from their fashionable friends in this one-of-a-kind magical adventure.'),
(57, '588921', 'en', 'https://image.tmdb.org/t/p/w500/l8HyObVj8fPrzacAPtGWWLDhcfh.jpg', 'Ainbo: Spirit of the Amazon', '400.934', '2021-02-09', 7.2, '220', '[\'Adventure\', \'Animation\', \'Family\', \'Fantasy\']', 'An epic journey of a young hero and her Spirit Guides, \'Dillo\' a cute and humorous armadillo and \"Vaca\" a goofy oversized tapir, who embark on a quest to save their home in the spectacular Amazon Rainforest.'),
(58, '726684', 'fr', 'https://image.tmdb.org/t/p/w500/msI5a9TPnepx47JUb2vl88hb80R.jpg', 'Miraculous World: Shanghai, la légende de Ladydragon', '434.458', '2021-05-15', 8, '362', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'On school break, Marinette heads to Shanghai to meet Adrien. But after arriving, Marinette loses all her stuff, including the Miraculous that allows her to turn into Ladybug!'),
(59, '375211', 'en', 'https://image.tmdb.org/t/p/w500/wVWDDzB0sWEIEMh0TXgqRa8X65o.jpg', 'Marvel Knights: Eternals', '429.973', '2014-09-16', 5.6, '5', '[\'Animation\']', 'You are thousands of years old. You have amazing powers. You have watched civilizations rise and fall. So why does no one remember any of this? Best-selling author, Neil Gaiman (Marvel: 1602) is joined by superstar artist, John Romita. Jr. (Amazing Spider-Man), to bring you the extraordinary tale of The Eternals. Medical student Mark Curry\'s world is turned upside-down when he meets Ike Harris, a man who believes that he is part of a centuries-old race of super-powered beings put here on Earth by aliens to preserve and safeguard the planet — and even crazier, tried to convince Mark that he is one too.'),
(60, '791373', 'en', 'https://image.tmdb.org/t/p/w500/tnAuB8q5vv7Ax9UAEje5Xi4BXik.jpg', 'Zack Snyder\'s Justice League', '410.965', '2021-03-18', 8.4, '6803', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'Determined to ensure Superman\'s ultimate sacrifice was not in vain, Bruce Wayne aligns forces with Diana Prince with plans to recruit a team of metahumans to protect the world from an approaching threat of catastrophic proportions.'),
(61, '634649', 'en', 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', 'Spider-Man: No Way Home', '480.702', '2021-12-15', 0, '0', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a Super Hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.'),
(62, '370172', 'en', 'https://image.tmdb.org/t/p/w500/iUgygt3fscRoKWCV1d0C7FbM9TP.jpg', 'No Time to Die', '604.254', '2021-09-29', 7.4, '1209', '[\'Adventure\', \'Action\', \'Thriller\']', 'Bond has left active service and is enjoying a tranquil life in Jamaica. His peace is short-lived when his old friend Felix Leiter from the CIA turns up asking for help. The mission to rescue a kidnapped scientist turns out to be far more treacherous than expected, leading Bond onto the trail of a mysterious villain armed with dangerous new technology.'),
(63, '706972', 'en', 'https://image.tmdb.org/t/p/w500/7p0O4mKYLIhU2E5Zcq9Z3vOZ4e9.jpg', 'Narco Sub', '374.848', '2021-01-22', 7.1, '59', '[\'Action\', \'Drama\', \'Crime\']', 'A man will become a criminal to save his family.  Director: Shawn Welling  Writer: Derek H. Potts  Stars: Tom Vera, Tom Sizemore, Lee Majors |'),
(64, '669671', 'en', 'https://image.tmdb.org/t/p/w500/1i8SJSdjAqd6PI5lPxhPaYKhUU3.jpg', 'Night Teeth', '367.303', '2021-10-20', 6.8, '299', '[\'Horror\', \'Thriller\', \'Action\']', 'A college student moonlighting as a chauffeur picks up two mysterious women for a night of party-hopping across LA. But when he uncovers their bloodthirsty intentions - and their dangerous, shadowy underworld - he must fight to stay alive.'),
(65, '503736', 'en', 'https://image.tmdb.org/t/p/w500/gCIsRxzcxvmuLYeAvWgoOuSxszF.jpg', 'Army of the Dead', '364.974', '2021-05-14', 6.4, '2514', '[\'Action\', \'Adventure\', \'Crime\', \'Horror\']', 'Following a zombie outbreak in Las Vegas, a group of mercenaries take the ultimate gamble: venturing into the quarantine zone to pull off the greatest heist ever attempted.'),
(66, '19995', 'en', 'https://image.tmdb.org/t/p/w500/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', 'Avatar', '374.059', '2009-12-10', 7.5, '24280', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.'),
(67, '619297', 'en', 'https://image.tmdb.org/t/p/w500/cP7odDzzFBD9ycxj2laTeFWGLjD.jpg', 'Sweet Girl', '360.21', '2021-08-18', 6.9, '697', '[\'Action\']', 'A devastated husband vows to bring justice to the people responsible for his wife\'s death while protecting the only family he has left, his daughter.'),
(68, '399566', 'en', 'https://image.tmdb.org/t/p/w500/pgqgaUx1cJb5oZQQ5v0tNARCeBp.jpg', 'Godzilla vs. Kong', '393.812', '2021-03-24', 7.9, '7185', '[\'Action\', \'Adventure\', \'Fantasy\']', 'In a time when monsters walk the Earth, humanity’s fight for its future sets Godzilla and Kong on a collision course that will see the two most powerful forces of nature on the planet collide in a spectacular battle for the ages.'),
(69, '767304', 'en', 'https://image.tmdb.org/t/p/w500/y1Tk1LUwS3nRlugiXnag6Bu1ToG.jpg', 'Redemption Day', '360.237', '2021-01-08', 6.7, '150', '[\'Action\']', 'Having just returned home, decorated U.S. Marine Captain Brad Paxton\'s wife, Kate, is kidnapped by a terrorist group while working in Morocco. He is forced back into action for a daring and deadly operation to save the woman he loves.'),
(70, '525660', 'cn', 'https://image.tmdb.org/t/p/w500/7BCTdek5LFHglcgl7shsm7igJAH.jpg', '真·三国无双', '372.423', '2021-04-29', 6.7, '71', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Warlords, warriors and statesmen wage a battle for supremacy in this fantasy tale based on the hit video games and the \"Romance of the Three Kingdoms.\"'),
(71, '840756', 'es', 'https://image.tmdb.org/t/p/w500/11z4nAYm1ZYIEzTvG0dzyKDBn6R.jpg', 'Mi otra yo', '501.068', '2021-06-15', 6.3, '3', '[\'Comedy\']', 'A controversial TV host and comedian who has built his career on sexist humor is forced to assume a woman\'s identity to elude a relentless drug dealer.'),
(72, '482373', 'en', 'https://image.tmdb.org/t/p/w500/aOu6PJVO9RyGAzdUwG6fupu0gpz.jpg', 'Don\'t Breathe 2', '366.157', '2021-08-12', 7.7, '1114', '[\'Thriller\', \'Horror\']', 'The Blind Man has been hiding out for several years in an isolated cabin and has taken in and raised a young girl orphaned from a devastating house fire. Their quiet life together is shattered when a group of criminals kidnap the girl, forcing the Blind Man to leave his safe haven to save her.'),
(73, '423108', 'en', 'https://image.tmdb.org/t/p/w500/rQfX2xx8TUoNvyk892yKWNikJaM.jpg', 'The Conjuring: The Devil Made Me Do It', '311.759', '2021-05-25', 7.8, '3856', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Paranormal investigators Ed and Lorraine Warren encounter what would become one of the most sensational cases from their files. The fight for the soul of a young boy takes them beyond anything they\'d ever seen before, to mark the first time in U.S. history that a murder suspect would claim demonic possession as a defense.'),
(74, '522402', 'en', 'https://image.tmdb.org/t/p/w500/eEJtzD1F05xDipFEDY98CTH5yZn.jpg', 'Finch', '549.884', '2021-11-04', 8, '522', '[\'Science Fiction\', \'Drama\', \'Adventure\']', 'On a post-apocalyptic Earth, a robot, built to protect the life of his dying creator\'s beloved dog, learns about life, love, friendship, and what it means to be human.'),
(75, '453354', 'fr', 'https://image.tmdb.org/t/p/w500/qzA87Wf4jo1h8JMk9GilyIYvwsA.jpg', 'Ava', '367.131', '2017-06-21', 6, '121', '[\'Drama\']', 'Ava, 13, is spending the summer on the Atlantic coast when she learns that she will lose her sight sooner than expected. Her mother decides to act as if everything were normal so as to spend their best summer ever. Ava confronts the problem in her own way. She steals a big black dog that belongs to a young man on the run...'),
(76, '725273', 'en', 'https://image.tmdb.org/t/p/w500/2ntZTs8ghCISFpTYA7hxo2MwLQ3.jpg', 'Solitary', '347.349', '2020-08-31', 5.8, '59', '[\'Science Fiction\']', 'A man wakes up inside a room to discover he\'s a prisoner sent into space to form Earth\'s first colony, and worse - his cell mate Alana is hell bent on destroying everything.'),
(77, '685274', 'ja', 'https://image.tmdb.org/t/p/w500/6gw8onh4FKsruBA7Oouv01EFxzn.jpg', '機動戦士ガンダム 閃光のハサウェイ', '371.425', '2021-06-11', 8.1, '57', '[\'Animation\', \'Action\', \'Drama\', \'Science Fiction\']', 'After Char\'s rebellion, Hathaway Noa leads an insurgency against Earth Federation, but meeting an enemy officer and a mysterious woman alters his fate.'),
(78, '859860', 'en', 'https://image.tmdb.org/t/p/w500/iykb2F7SEhC7gspgv5j8qh5p4um.jpg', 'Catch the Bullet', '363.643', '2021-09-10', 5.6, '67', '[\'Western\', \'Action\']', 'U.S. marshal Britt MacMasters returns from a mission to find his father wounded and his son kidnapped by the outlaw Jed Blake. Hot on their trail, Britt forms a posse with a gunslinging deputy and a stoic Pawnee tracker. But Jed and Britt tread dangerously close to the Red Desert’s Sioux territory.'),
(79, '825997', 'en', 'https://image.tmdb.org/t/p/w500/zedUsN2fxRYhrp8k4uHVZuoEPaj.jpg', 'Rogue Hostage', '340.663', '2021-06-11', 6.4, '101', '[\'Action\', \'Thriller\']', 'A former Marine races against time to save a group of hostages -- including his young daughter and a congressman — when armed militants take over his stepfather\'s store.'),
(80, '755812', 'fr', 'https://image.tmdb.org/t/p/w500/9YbyvcrHmY2SVbdfXpb8mC4Fy0g.jpg', 'Miraculous World : New York, les héros unis', '326.392', '2020-11-21', 8.3, '812', '[\'Animation\', \'Family\', \'Comedy\', \'Adventure\', \'TV Movie\']', 'During a school field trip, Ladybug and Cat Noir meet the American superheroes, whom they have to save from an akumatised super-villain. They discover that Miraculous exist in the United States too.'),
(81, '719164', 'en', 'https://image.tmdb.org/t/p/w500/yTgSMm9LRXVGxfaKqmlPCcQx5RJ.jpg', 'Women', '219.924', '2021-04-08', 6.1, '14', '[\'Thriller\']', 'A small town detective while investigating the disappearance of a local woman comes across an unassuming Sociology professor who is hiding a secret life.'),
(82, '602223', 'en', 'https://image.tmdb.org/t/p/w500/lB068qa6bQ0QKYKyC2xnYGvYjl7.jpg', 'The Forever Purge', '321.093', '2021-06-30', 7.4, '1396', '[\'Horror\', \'Action\', \'Thriller\']', 'All the rules are broken as a sect of lawless marauders decides that the annual Purge does not stop at daybreak and instead should never end as they chase a group of immigrants who they want to punish because of their harsh historical past.'),
(83, '595743', 'en', 'https://image.tmdb.org/t/p/w500/6Y9fl8tD1xtyUrOHV2MkCYTpzgi.jpg', 'SAS: Red Notice', '328.657', '2021-08-11', 6, '259', '[\'Drama\', \'Action\', \'Thriller\']', 'An off-duty SAS soldier, Tom Buckingham, must thwart a terror attack on a train running through the Channel Tunnel. As the action escalates on the train, events transpire in the corridors of power that may make the difference as to whether Buckingham and the civilian passengers make it out of the tunnel alive.'),
(84, '741636', 'en', 'https://image.tmdb.org/t/p/w500/49a2fQEFO2R190Ng5ksJedRJun6.jpg', 'Bloodthirsty', '334.459', '2021-04-23', 6.6, '16', '[\'Horror\']', 'When indie singer Grey struggles to write her sophomore album, she teams up with a mysterious producer at his secluded cabin. Though their bond strengthens her music, it also starts to irreparably alter Grey’s body and mind.'),
(85, '1930', 'en', 'https://image.tmdb.org/t/p/w500/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg', 'The Amazing Spider-Man', '369.323', '2012-06-23', 6.6, '13495', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Peter Parker is an outcast high schooler abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben and Aunt May. Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents\' disappearance – leading him directly to Oscorp and the lab of Dr. Curt Connors, his father\'s former partner. As Spider-Man is set on a collision course with Connors\' alter ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.'),
(86, '641501', 'fr', 'https://image.tmdb.org/t/p/w500/d0wn9YtEnmbucx8ZUsT918ctoiK.jpg', 'Comment je suis devenu super-héros', '320.168', '2020-11-19', 6.1, '292', '[\'Science Fiction\', \'Adventure\', \'Mystery\', \'Action\', \'Thriller\', \'Fantasy\', \'Comedy\']', 'Paris 2020. While superheroes have assimilated into the Parisian society, they discover a new drug that gives themselves personal superpowers to mere mortals. Lieutenants Moreau and Schaltzmann are investigating the case with the support of two ex-superheroes, Monte Carlo and Callista. They\'ll do whatever it takes to dismantle the traffic. But Moreau\'s past resurfaces, and the investigation becomes more complicated.'),
(87, '848278', 'en', 'https://image.tmdb.org/t/p/w500/bZnOioDq1ldaxKfUoj3DenHU7mp.jpg', 'Jurassic Hunt', '305.718', '2021-08-26', 5, '153', '[\'Action\', \'Science Fiction\', \'Thriller\']', 'Female adventurer Parker joins a crew of male trophy hunters in a remote wilderness park. Their goal: slaughter genetically recreated dinosaurs for sport using rifles, arrows, and grenades. After their guide is killed by raptors, the team tries to escape the park – but the hunters quickly become the hunted. Even worse, the park’s manager suspects Parker of being a spy and sends a hit squad after her. This battle’s about to become primitive!'),
(88, '13811', 'en', 'https://image.tmdb.org/t/p/w500/OG0mxQt4YaNIWiz8EKJSHe9lPh.jpg', 'Knowing', '314.469', '2009-03-19', 6.1, '4067', '[\'Action\', \'Mystery\', \'Science Fiction\', \'Thriller\']', 'A teacher opens a time capsule that has been dug up at his son\'s elementary school; in it are some chilling predictions -- some that have already occurred and others that are about to -- that lead him to believe his family plays a role in the events that are about to unfold.'),
(89, '813258', 'en', 'https://image.tmdb.org/t/p/w500/dkokENeY5Ka30BFgWAqk14mbnGs.jpg', 'Monster Pets: A Hotel Transylvania Short', '307.614', '2021-04-02', 7.5, '254', '[\'Animation\', \'Comedy\', \'Fantasy\']', 'Drac tries out some new monster pets to help occupy Tinkles for playtime.'),
(90, '512195', 'en', 'https://image.tmdb.org/t/p/w500/lAXONuqg41NwUMuzMiFvicDET9Y.jpg', 'Red Notice', '282.641', '2021-11-05', 7.4, '19', '[\'Action\', \'Comedy\', \'Crime\', \'Thriller\']', 'An Interpol-issued Red Notice is a global alert to hunt and capture the world\'s most wanted. But when a daring heist brings together the FBI\'s top profiler and two rival criminals, there\'s no telling what will happen.'),
(91, '672322', 'ja', 'https://image.tmdb.org/t/p/w500/rODS466qSdrwMlGdbUwPENhDN2c.jpg', 'るろうに剣心 最終章 The Beginning', '310.225', '2021-06-04', 7.9, '202', '[\'Action\', \'Adventure\', \'Drama\']', 'Before he was a protector, Kenshin was a fearsome assassin known as Battosai. But when he meets gentle Tomoe Yukishiro, a beautiful young woman who carries a huge burden in her heart, his life will change forever.'),
(92, '592350', 'ja', 'https://image.tmdb.org/t/p/w500/kpWsIkfXrnQ1pmR79qAHHq7DPxc.jpg', '僕のヒーローアカデミア THE MOVIE ヒーローズ：ライジング', '326.465', '2019-12-20', 8.5, '816', '[\'Animation\', \'Action\', \'Fantasy\', \'Adventure\']', 'Class 1-A visits Nabu Island where they finally get to do some real hero work. The place is so peaceful that it\'s more like a vacation … until they\'re attacked by a villain with an unfathomable Quirk! His power is eerily familiar, and it looks like Shigaraki had a hand in the plan. But with All Might retired and citizens\' lives on the line, there\'s no time for questions. Deku and his friends are the next generation of heroes, and they\'re the island\'s only hope.'),
(93, '878962', 'en', 'https://image.tmdb.org/t/p/w500/llKx3r1iKqkojnAhQpED0GZwqKL.jpg', 'Sharkdog’s Fintastic Halloween', '261.208', '2021-10-15', 3.7, '3', '[\'Animation\', \'Fantasy\', \'Family\']', 'The Sharkpack gets ready for Halloween with the spooky legend of the \"Fearsome Fog\" — and Sharkdog must save trick-or-treating from a slimy sea monster!'),
(94, '763873', 'en', 'https://image.tmdb.org/t/p/w500/7RbSSHD0MqQ4SmopPQBRBO0xuix.jpg', 'Under Wraps', '273.852', '2021-10-01', 7.1, '41', '[\'Comedy\', \'Family\', \'Fantasy\']', 'Three friends try to save their mummified friend, Harold, from greedy criminals by returning him to his resting place before midnight on Halloween.'),
(95, '843906', 'en', 'https://image.tmdb.org/t/p/w500/rlQJnQfPgaSGQtyMw35VOIqoIsj.jpg', 'Straight Outta Nowhere: Scooby-Doo! Meets Courage the Cowardly Dog', '310.694', '2021-09-14', 8.3, '221', '[\'Animation\', \'Comedy\', \'Mystery\', \'Family\', \'Fantasy\']', 'With Mystery, Inc. on the tail of a strange object in Nowhere, Kansas, the strange hometown of Eustice, Muriel, and Courage, the gang soon find themselves contending with a giant cicada monster and her winged warriors.'),
(96, '527774', 'en', 'https://image.tmdb.org/t/p/w500/5nVhgCzxKbK47OLIKxCR1syulOn.jpg', 'Raya and the Last Dragon', '308.607', '2021-03-03', 8.1, '4514', '[\'Family\', \'Fantasy\', \'Animation\', \'Action\', \'Adventure\']', 'Long ago, in the fantasy world of Kumandra, humans and dragons lived together in harmony. But when an evil force threatened the land, the dragons sacrificed themselves to save humanity. Now, 500 years later, that same evil has returned and it’s up to a lone warrior, Raya, to track down the legendary last dragon to restore the fractured land and its divided people.'),
(97, '299536', 'en', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', 'Avengers: Infinity War', '307.188', '2018-04-25', 8.3, '23027', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.'),
(98, '613504', 'en', 'https://image.tmdb.org/t/p/w500/kiX7UYfOpYrMFSAGbI6j1pFkLzQ.jpg', 'After We Collided', '299.644', '2020-09-02', 7.3, '4262', '[\'Romance\', \'Drama\']', 'Tessa finds herself struggling with her complicated relationship with Hardin; she faces a dilemma that could change their lives forever.'),
(99, '539885', 'en', 'https://image.tmdb.org/t/p/w500/qzA87Wf4jo1h8JMk9GilyIYvwsA.jpg', 'Ava', '302.664', '2020-07-02', 5.7, '1785', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'A black ops assassin is forced to fight for her own survival after a job goes dangerously wrong.'),
(100, '597316', 'en', 'https://image.tmdb.org/t/p/w500/uvbj8puRj37Pc8FS4rIfVeReYFF.jpg', 'My Little Pony: A New Generation', '316.848', '2021-09-23', 8.1, '131', '[\'Animation\', \'Family\', \'Fantasy\', \'Comedy\', \'Music\', \'Adventure\']', 'Equestria\'s divided. But a bright-eyed hero believes Earth Ponies, Pegasi and Unicorns should be pals — and, hoof to heart, she’s determined to prove it.'),
(101, '522444', 'en', 'https://image.tmdb.org/t/p/w500/pmAv14TPE2vKMIRrVeCd1Ll7K94.jpg', 'Black Water: Abyss', '274.301', '2020-07-09', 5.1, '284', '[\'Horror\', \'Thriller\', \'Adventure\', \'Mystery\']', 'An adventure-loving couple convince their friends to explore a remote, uncharted cave system in the forests of Northern Australia. With a tropical storm approaching, they abseil into the mouth of the cave, but when the caves start to flood, tensions rise as oxygen levels fall and the friends find themselves trapped. Unknown to them, the storm has also brought in a pack of dangerous and hungry crocodiles.'),
(102, '680319', 'en', 'https://image.tmdb.org/t/p/w500/qPeSznx1YJkjKwd3B5yqRlxq0xD.jpg', 'We Broke Up', '272.144', '2021-04-23', 5.7, '12', '[\'Comedy\']', 'Lori and Doug break up right before Lori\'s sister\'s wedding and decide to pretend they\'re still together for the weekend as to not disrupt the fun.'),
(103, '458576', 'en', 'https://image.tmdb.org/t/p/w500/1UCOF11QCw8kcqvce8LKOO6pimh.jpg', 'Monster Hunter', '273.173', '2020-12-03', 6.9, '2236', '[\'Action\', \'Fantasy\', \'Adventure\']', 'A portal transports Cpt. Artemis and an elite unit of soldiers to a strange world where powerful monsters rule with deadly ferocity. Faced with relentless danger, the team encounters a mysterious hunter who may be their only hope to find a way home.'),
(104, '613583', 'fr', 'https://image.tmdb.org/t/p/w500/tDnkvlBXXiIkAowjtzLeU54ZVhK.jpg', 'Chacun chez soi', '257.834', '2021-06-02', 5.4, '27', '[\'Comedy\']', 'Catherine and Yann, happily married for many years, should have spent the year travelling abroad. But since he sold his business, Yann has been too busy with his bonsai trees and keeps postponing the big trip. Things go from bad to worse when their 27-year-old broke daughter and her boyfriend lose their apartment and come knocking on the door to stay. With Yann’s mid-life crisis spinning out of control, their couch surfing daughter and partner getting increasingly invasive and their stay becoming indefinite, Catherine will try everything to kick them out of the parental home and get her life back on track!'),
(105, '36419', 'en', 'https://image.tmdb.org/t/p/w500/ty43RTdSBpL3VjBJWeRoKhFg7hF.jpg', 'After.Life', '387.777', '2009-11-07', 6.1, '803', '[\'Drama\', \'Horror\', \'Mystery\', \'Thriller\']', 'Following a terrible car crash, a woman awakes to find an enigmatic mortician preparing her for burial.'),
(106, '632357', 'en', 'https://image.tmdb.org/t/p/w500/bShgiEQoPnWdw4LBrYT5u18JF34.jpg', 'The Unholy', '263.412', '2021-03-31', 6.9, '1410', '[\'Horror\']', 'Alice, a young hearing-impaired girl who, after a supposed visitation from the Virgin Mary, is inexplicably able to hear, speak and heal the sick. As word spreads and people from near and far flock to witness her miracles, a disgraced journalist hoping to revive his career visits the small New England town to investigate. When terrifying events begin to happen all around, he starts to question if these phenomena are the works of the Virgin Mary or something much more sinister.'),
(107, '861057', 'en', 'https://image.tmdb.org/t/p/w500/sDGozQOG01O1R2733ky3EjUaAVL.jpg', 'Swim', '273.818', '2021-08-13', 7.4, '16', '[\'Horror\', \'Action\']', 'A family gets trapped in their storm flooded vacation rental, tries to escape from a hungry shark that made it\'s way into the house.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(108, '597891', 'en', 'https://image.tmdb.org/t/p/w500/uJgdT1boTSP0dDIjdTgGleg71l4.jpg', 'Kate', '270.225', '2021-09-10', 6.8, '740', '[\'Action\', \'Thriller\']', 'After she\'s irreversibly poisoned, a ruthless criminal operative has less than 24 hours to exact revenge on her enemies and in the process forms an unexpected bond with the daughter of one of her past victims.'),
(109, '846214', 'en', 'https://image.tmdb.org/t/p/w500/rtMdtzywcAGOrF6t8fbxJBqpdcq.jpg', 'The Simpsons: The Good, the Bart, and the Loki', '276.105', '2021-07-07', 7.6, '431', '[\'Animation\', \'Comedy\', \'Family\']', 'Loki is banished from Asgard once again and must face his toughest opponents yet: the Simpsons and Springfield’s mightiest heroes. The God of Mischief teams up with Bart Simpson in the ultimate crossover event paying tribute to the Marvel Cinematic Universe of superheroes and villains.'),
(110, '482321', 'en', 'https://image.tmdb.org/t/p/w500/plzgQAXIEHm4Y92ktxU6fedUc0x.jpg', 'Ron\'s Gone Wrong', '287.164', '2021-10-15', 7.3, '41', '[\'Animation\', \'Science Fiction\', \'Family\', \'Comedy\']', 'In a world where walking, talking, digitally connected bots have become children\'s best friends, an 11-year-old finds that his robot buddy doesn\'t quite work the same as the others do.'),
(111, '529203', 'en', 'https://image.tmdb.org/t/p/w500/tbVZ3Sq88dZaCANlUcewQuHQOaE.jpg', 'The Croods: A New Age', '277.639', '2020-11-25', 7.6, '2621', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\', \'Comedy\']', 'Searching for a safer habitat, the prehistoric Crood family discovers an idyllic, walled-in paradise that meets all of its needs. Unfortunately, they must also learn to live with the Bettermans -- a family that\'s a couple of steps above the Croods on the evolutionary ladder. As tensions between the new neighbors start to rise, a new threat soon propels both clans on an epic adventure that forces them to embrace their differences, draw strength from one another, and survive together.'),
(112, '678580', 'es', 'https://image.tmdb.org/t/p/w500/zvGC5jX5wQmU1GgPc0VGZz7Mtcs.jpg', 'El mesero', '249.461', '2021-07-15', 8.3, '286', '[\'Comedy\']', 'A waiter pretends to be an important businessman in order to reach the upper class through his entrepreneurial dreams.'),
(113, '734265', 'en', 'https://image.tmdb.org/t/p/w500/oTkAFDZRLnqrXOrOwuy3Tvul0v5.jpg', 'Love Hard', '279.451', '2021-11-05', 6.6, '170', '[\'Comedy\', \'Romance\']', 'An LA girl, unlucky in love, falls for an East Coast guy on a dating app and decides to surprise him for Christmas, only to discover that she’s been catfished. But the object of her affection actually lives in the same town, and the guy who duped her offers to set them up if she pretends to be his own girlfriend for the holidays.'),
(114, '568124', 'en', 'https://image.tmdb.org/t/p/w500/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', 'Encanto', '265.395', '2021-11-24', 0, '0', '[\'Family\', \'Music\', \'Adventure\', \'Animation\', \'Fantasy\']', 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family with a unique gift from super strength to the power to heal—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family\'s last hope.'),
(115, '324786', 'en', 'https://image.tmdb.org/t/p/w500/fnOMP6mjmOmZwmlC1n0K7ivrzt1.jpg', 'Hacksaw Ridge', '233.039', '2016-10-07', 8.2, '10136', '[\'Drama\', \'History\', \'War\']', 'WWII American Army Medic Desmond T. Doss, who served during the Battle of Okinawa, refuses to kill people and becomes the first Conscientious Objector in American history to receive the Congressional Medal of Honor.'),
(116, '839100', 'ja', 'https://image.tmdb.org/t/p/w500/6FuOW69wl9Bf2kzaVut596sMhZ6.jpg', 'ブライト: サムライソウル', '240.726', '2021-10-12', 6.2, '22', '[\'Animation\', \'Action\', \'Fantasy\']', 'Izo, a Ronin, and Raiden, an orc, work to bring a young elf girl and the wand she carries to the land of the elves in the north.'),
(117, '20982', 'ja', 'https://image.tmdb.org/t/p/w500/vDkct38sSFSWJIATlfJw0l3QOIR.jpg', '劇場版 NARUTO -ナルト- 疾風伝', '262.861', '2007-08-04', 7.3, '382', '[\'Animation\', \'Action\', \'Fantasy\']', 'Demons that once almost destroyed the world, are revived by someone. To prevent the world from being destroyed, the demon has to be sealed and the only one who can do it is the shrine maiden Shion from the country of demons, who has two powers; one is sealing demons and the other is predicting the deaths of humans. This time Naruto\'s mission is to guard Shion, but she predicts Naruto\'s death. The only way to escape it, is to get away from Shion, which would leave her unguarded, then the demon, whose only goal is to kill Shion will do so, thus meaning the end of the world. Naruto decides to challenge this \"prediction of death.\"'),
(118, '634528', 'en', 'https://image.tmdb.org/t/p/w500/6vcDalR50RWa309vBH1NLmG2rjQ.jpg', 'The Marksman', '287.586', '2021-01-15', 7.1, '950', '[\'Action\', \'Thriller\', \'Crime\']', 'Jim Hanson’s quiet life is suddenly disturbed by two people crossing the US/Mexico border – a woman and her young son – desperate to flee a Mexican cartel. After a shootout leaves the mother dead, Jim becomes the boy’s reluctant defender. He embraces his role as Miguel’s protector and will stop at nothing to get him to safety, as they go on the run from the relentless assassins.'),
(119, '763164', 'en', 'https://image.tmdb.org/t/p/w500/5UaXLGCJKbBQHaCHV6EsI21igUe.jpg', 'Apex', '401.393', '2021-11-12', 5.3, '50', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'Ex-cop James Malone is serving a life sentence for a crime he didn’t commit. He is offered a chance at freedom if he can survive a deadly game of Apex, in which six hunters pay for the pleasure of hunting another human on a remote island. He accepts, and once he arrives, all hell breaks loose.'),
(120, '464052', 'en', 'https://image.tmdb.org/t/p/w500/8UlWHLMpgZm9bx6QYh0NFoq67TZ.jpg', 'Wonder Woman 1984', '267.785', '2020-12-16', 6.6, '6105', '[\'Action\', \'Adventure\', \'Fantasy\']', 'A botched store robbery places Wonder Woman in a global battle against a powerful and mysterious ancient force that puts her powers in jeopardy.'),
(121, '573164', 'es', 'https://image.tmdb.org/t/p/w500/7he8glf7j41d3amgf4Nbpt3HVq1.jpg', 'Un rescate de huevitos', '268.087', '2021-08-12', 8.1, '256', '[\'Animation\', \'Comedy\']', 'A rooster and his fowl partner embark on a dangerous trip to the Congo to recover their stolen eggs from a group of Russian goons.'),
(122, '520763', 'en', 'https://image.tmdb.org/t/p/w500/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', 'A Quiet Place Part II', '252.028', '2021-05-21', 7.7, '3294', '[\'Science Fiction\', \'Thriller\', \'Horror\']', 'Following the events at home, the Abbott family now face the terrors of the outside world. Forced to venture into the unknown, they realize that the creatures that hunt by sound are not the only threats that lurk beyond the sand path.'),
(123, '619778', 'en', 'https://image.tmdb.org/t/p/w500/dGv2BWjzwAz6LB8a8JeRIZL8hSz.jpg', 'Malignant', '233.546', '2021-09-01', 7.1, '979', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Madison is paralyzed by shocking visions of grisly murders, and her torment worsens as she discovers that these waking dreams are in fact terrifying realities with a mysterious tie to her past.'),
(124, '529106', 'ru', 'https://image.tmdb.org/t/p/w500/4PsiX8or0QHg3LKLbh4VyF0bLj1.jpg', 'Майор Гром: Чумной Доктор', '248.521', '2021-04-01', 6.8, '342', '[\'Action\', \'Adventure\']', 'Igor Grom is a skilled policeman from St. Petersburg, known for his daring nature and uncompromising attitude towards the criminals of all kinds. Incredible strength, analytical mind and integrity – these qualities make Major Grom the perfect policeman. Working tirelessly, he always pushes through, and meets the challenges standing in the way.'),
(125, '729720', 'fr', 'https://image.tmdb.org/t/p/w500/ttpKJ7XQxDZV252KNEHXtykYT41.jpg', 'Le Dernier Mercenaire', '265.12', '2021-07-30', 6.8, '431', '[\'Action\', \'Comedy\']', 'A mysterious former secret service agent must urgently return to France when his estranged son  is falsely accused of arms and drug trafficking by the government, following a blunder by an overzealous bureaucrat and a mafia operation.'),
(126, '883648', 'en', 'https://image.tmdb.org/t/p/w500/GCzsXnTvybNulfDJ1GxqkyAOM9.jpg', 'Little Big Mouth', '239.444', '2021-10-22', 4.9, '13', '[\'Comedy\']', 'Kicked out of his band and home, a playful guitarist takes refuge with a bookkeeper, her son and dad. Is it possible to make sweet music together?'),
(127, '739990', 'en', 'https://image.tmdb.org/t/p/w500/ysJte1iqN8pFQ470tumnViB1wHP.jpg', 'Nightbooks', '227.322', '2021-09-15', 6.6, '183', '[\'Fantasy\', \'Family\', \'Horror\']', 'Alex, a boy obsessed with scary stories, is trapped by a witch in her modern, magical New York City apartment. His original hair-raising tales are the only thing keeping him safe as he desperately tries to find a way out of this twisted place.'),
(128, '857702', 'en', 'https://image.tmdb.org/t/p/w500/fYiaBZDjyXjvlY6EDZMAxIhBO1I.jpg', 'LEGO Star Wars Terrifying Tales', '242.303', '2021-10-01', 6.6, '85', '[\'Family\', \'Animation\', \'Science Fiction\', \'Comedy\']', 'Poe Dameron and BB-8 must face the greedy crime boss Graballa the Hutt, who has purchased Darth Vader’s castle and is renovating it into the galaxy’s first all-inclusive Sith-inspired luxury hotel.'),
(129, '671', 'en', 'https://image.tmdb.org/t/p/w500/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', 'Harry Potter and the Philosopher\'s Stone', '234.446', '2001-11-16', 7.9, '21302', '[\'Adventure\', \'Fantasy\']', 'Harry Potter has lived under the stairs at his aunt and uncle\'s house his whole life. But on his 11th birthday, he learns he\'s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school\'s kindly headmaster, Harry uncovers the truth about his parents\' deaths—and about the villain who\'s to blame.'),
(130, '315635', 'en', 'https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', 'Spider-Man: Homecoming', '266.445', '2017-07-05', 7.4, '17065', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Drama\']', 'Following the events of Captain America: Civil War, Peter Parker, with the help of his mentor Tony Stark, tries to balance his life as an ordinary high school student in Queens, New York City, with fighting crime as his superhero alter ego Spider-Man as a new threat, the Vulture, emerges.'),
(131, '385687', 'en', 'https://image.tmdb.org/t/p/w500/fiVW06jE7z9YnO4trhaMEdclSiC.jpg', 'Fast & Furious 10', '211.849', '2023-04-06', 0, '0', '[\'Action\', \'Crime\']', 'The tenth installment in the Fast Saga.'),
(132, '880009', 'es', 'https://image.tmdb.org/t/p/w500/siGmPNbxKdooHm7unHpiBSdfYpR.jpg', 'Catalina la Catrina: especial Día de Muertos', '260.402', '2021-10-01', 3.3, '5', '[\'Family\', \'Animation\']', ''),
(133, '826914', 'en', 'https://image.tmdb.org/t/p/w500/AeVMV8cMvNhn6aKozAH3pysvftm.jpg', 'Muppets Haunted Mansion', '206.82', '2021-10-08', 6.9, '86', '[\'Comedy\', \'Family\', \'TV Movie\']', 'Gonzo is challenged to spend one night in The Haunted Mansion on Halloween night.'),
(134, '617502', 'en', 'https://image.tmdb.org/t/p/w500/b0fBzqCmHr0a0XkeAdhc02XhKXG.jpg', 'Jolt', '243.844', '2021-07-15', 6.8, '753', '[\'Action\', \'Comedy\']', 'Lindy is an acid-tongued woman with rage issues who controls her temper by shocking herself with an electrode vest. One day she makes a connection with Justin, who gives her a glimmer of hope for a shock-free future, but when he’s murdered she launches herself on a revenge-fueled rampage in pursuit of his killer.'),
(135, '429617', 'en', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', 'Spider-Man: Far From Home', '273.535', '2019-06-28', 7.5, '10893', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Peter Parker and his friends go on a summer trip to Europe. However, they will hardly be able to rest - Peter will have to agree to help Nick Fury uncover the mystery of creatures that cause natural disasters and destruction throughout the continent.'),
(136, '800497', 'en', 'https://image.tmdb.org/t/p/w500/5CGgbgyvmE39Yoqa80GKsgClbQm.jpg', 'Werewolves Within', '225.012', '2021-06-25', 6.1, '179', '[\'Comedy\', \'Horror\']', 'When a proposed pipeline creates hostilities between residents of a small town, a newly-arrived forest ranger must keep the peace after a snowstorm confines the townspeople to an old lodge. But when a mysterious creature begins terrorizing the group, their worst tendencies and prejudices rise to the surface, and it is up to the ranger to keep the residents alive, both from each other and the monster which plagues them.'),
(137, '537915', 'en', 'https://image.tmdb.org/t/p/w500/u3B2YKUjWABcxXZ6Nm9h10hLUbh.jpg', 'After', '239.301', '2019-04-11', 7.2, '6704', '[\'Romance\', \'Drama\']', 'Tessa Young is a dedicated student, dutiful daughter and loyal girlfriend to her high school sweetheart. Entering her first semester of college, Tessa\'s guarded world opens up when she meets Hardin Scott, a mysterious and brooding rebel who makes her question all she thought she knew about herself -- and what she wants out of life.'),
(138, '347201', 'ja', 'https://image.tmdb.org/t/p/w500/1k6iwC4KaPvTBt1JuaqXy3noZRY.jpg', 'BORUTO -NARUTO THE MOVIE-', '229.477', '2015-08-07', 7.7, '917', '[\'Animation\', \'Action\', \'Comedy\']', 'The spirited Boruto Uzumaki, son of Seventh Hokage Naruto, is a skilled ninja who possesses the same brashness and passion his father once had. However, the constant absence of his father, who is busy with his Hokage duties, puts a damper on Boruto\'s fire. He ends up meeting his father\'s friend Sasuke, and requests to become... his apprentice!? The curtain on the story of the new generation rises!'),
(139, '587807', 'en', 'https://image.tmdb.org/t/p/w500/5qttWFjsO62k88civZaDMHiBTvy.jpg', 'Tom & Jerry', '232.966', '2021-02-11', 7.1, '1831', '[\'Comedy\', \'Family\', \'Animation\']', 'Tom the cat and Jerry the mouse get kicked out of their home and relocate to a fancy New York hotel, where a scrappy employee named Kayla will lose her job if she can’t evict Jerry before a high-class wedding at the hotel. Her solution? Hiring Tom to get rid of the pesky mouse.'),
(140, '559', 'en', 'https://image.tmdb.org/t/p/w500/qFmwhVUoUSXjkKRmca5yGDEXBIj.jpg', 'Spider-Man 3', '236.031', '2007-05-01', 6.3, '10473', '[\'Fantasy\', \'Action\', \'Adventure\']', 'The seemingly invincible Spider-Man goes up against an all-new crop of villains—including the shape-shifting Sandman. While Spider-Man’s superpowers are altered by an alien organism, his alter ego, Peter Parker, deals with nemesis Eddie Brock and also gets caught up in a love triangle.'),
(141, '585083', 'en', 'https://image.tmdb.org/t/p/w500/teCy1egGQa0y8ULJvlrDHQKnxBL.jpg', 'Hotel Transylvania: Transformania', '190.917', '2022-01-14', 0, '0', '[\'Family\', \'Animation\', \'Fantasy\', \'Comedy\', \'Adventure\']', 'When Van Helsing\'s mysterious invention, the \\\"Monsterfication Ray,\\\" goes haywire, Drac and his monster pals are all transformed into humans, and Johnny becomes a monster. In their new mismatched bodies, Drac and Johnny must team up and race across the globe to find a cure before it\'s too late, and before they drive each other crazy.'),
(142, '508442', 'en', 'https://image.tmdb.org/t/p/w500/6jmppcaubzLF8wkXM36ganVISCo.jpg', 'Soul', '229.134', '2020-12-25', 8.2, '7165', '[\'Animation\', \'Comedy\', \'Fantasy\', \'Family\']', 'Joe Gardner is a middle school teacher with a love for jazz music. After a successful audition at the Half Note Club, he suddenly gets into an accident that separates his soul from his body and is transported to the You Seminar, a center in which souls develop and gain passions before being transported to a newborn child. Joe must enlist help from the other souls-in-training, like 22, a soul who has spent eons in the You Seminar, in order to get back to Earth.'),
(143, '317442', 'ja', 'https://image.tmdb.org/t/p/w500/bAQ8O5Uw6FedtlCbJTutenzPVKd.jpg', 'The Last: Naruto the Movie', '244.198', '2014-12-06', 7.9, '1069', '[\'Action\', \'Romance\', \'Animation\']', 'Two years after the events of the Fourth Great Ninja War, the moon that Hagoromo Otsutsuki created long ago to seal away the Gedo Statue begins to descend towards the world, threatening to become a meteor that would destroy everything on impact. Amidst this crisis, a direct descendant of Kaguya Otsutsuki named Toneri Otsutsuki attempts to kidnap Hinata Hyuga but ends up abducting her younger sister Hanabi. Naruto and his allies now mount a rescue mission before finding themselves embroiled in a final battle to decide the fate of everything.'),
(144, '567189', 'en', 'https://image.tmdb.org/t/p/w500/6GCOpT8QcNzup09TAMmvvk22LTR.jpg', 'Tom Clancy\'s Without Remorse', '223.53', '2021-04-29', 7.2, '1641', '[\'Action\', \'Thriller\']', 'An elite Navy SEAL uncovers an international conspiracy while seeking justice for the murder of his pregnant wife.'),
(145, '449406', 'en', 'https://image.tmdb.org/t/p/w500/eRLlrhbdYE7XN6VtcZKy6o2BsOw.jpg', 'Vivo', '208.114', '2021-07-30', 7.7, '415', '[\'Animation\', \'Family\', \'Comedy\']', 'A music-loving kinkajou named Vivo embarks on the journey of a lifetime to fulfill his destiny and deliver a love song for an old friend.'),
(146, '719088', 'ja', 'https://image.tmdb.org/t/p/w500/oPiCFGiDqcAPUYoX96hwitcUScI.jpg', 'イエスかノーか半分か', '234.805', '2020-12-11', 6.4, '11', '[\'Animation\', \'Drama\', \'Romance\']', 'Kunieda Kei is a popular, young TV announcer whose public and private personas are so different, they might be called extreme. On the outside, he is the picture of perfection, affectionately nicknamed \"The Prince,\" while on the inside he is constantly cursing at all of the incompetence around him. Of course, no one knows this secret of his.  One day, Kei meets animation artist Tsuzuki Ushio for a work assignment. While Kei is in \"inside mode,\" he later runs into Tsuzuki, who doesn\'t recognize him in his worn-out sweats and a facemask, but as compensation for injuring Tsuzuki\'s arm, Kei gets roped into helping out with his work.'),
(147, '522241', 'en', 'https://image.tmdb.org/t/p/w500/jE6QFRd48IzAxAubOE9HKB8sTjP.jpg', 'The Courier', '224.855', '2021-03-18', 7.2, '456', '[\'Thriller\', \'History\', \'Drama\']', 'Cold War spy Greville Wynne and his Russian source try to put an end to the Cuban Missile Crisis.'),
(148, '637693', 'en', 'https://image.tmdb.org/t/p/w500/fLE2mvuvhvzmSICOsqR9uE50Ave.jpg', 'Spirit Untamed', '215.011', '2021-05-20', 7.8, '288', '[\'Animation\', \'Adventure\', \'Family\', \'Western\']', 'Lucky Prescott\'s life is changed forever when she moves from her home in the city to a small frontier town and befriends a wild mustang named Spirit.'),
(149, '850818', 'en', 'https://image.tmdb.org/t/p/w500/jeggetf6lrd0dhtcbqJH75Sik4K.jpg', 'Barbie: Big City, Big Dreams', '216.59', '2021-08-20', 7.2, '73', '[\'Animation\', \'Music\', \'Family\']', 'Barbie swaps the sunny shores of Malibu for the bright lights of Broadway to attend an excusive summer performing arts program and meets…Barbie!  Fast friends, the two discover they share more than a name as they explore New York City and all the amazing things they have in common.  As they compete for the coveted once-in-a-lifetime Spotlight Solo from Times Square, the friends discover competition isn’t all about winning, it’s about striving to be your best, overcoming doubts, and sharing the spotlight.'),
(150, '882812', 'es', 'https://image.tmdb.org/t/p/w500/micqKpKDKeC1Nu1Ku1MNIMLV276.jpg', 'No me echen ese muerto', '173.395', '2021-10-09', 7.4, '17', '[\'Comedy\']', ''),
(151, '581644', 'en', 'https://image.tmdb.org/t/p/w500/rkIkyPhT5oetT463HxpdIuct30l.jpg', 'The Misfits', '239.557', '2021-06-10', 5.6, '163', '[\'Action\']', 'After being recruited by a group of unconventional thieves, renowned criminal Richard Pace finds himself caught up in an elaborate gold heist that promises to have far-reaching implications on his life and the lives of countless others.'),
(152, '841755', 'en', 'https://image.tmdb.org/t/p/w500/ablrE8IbWcIrAxMmm4gnPn75AMS.jpg', 'Mortal Kombat Legends: Battle of the Realms', '200.515', '2021-08-30', 8.1, '177', '[\'Animation\', \'Action\', \'Fantasy\']', 'The Earthrealm heroes must journey to the Outworld and fight for the survival of their homeland, invaded by the forces of evil warlord Shao Kahn, in the tournament to end all tournaments: the final Mortal Kombat.'),
(153, '15092', 'en', 'https://image.tmdb.org/t/p/w500/tzTC4EEvF0OPL63frEiogxL2T8M.jpg', 'Crank: High Voltage', '219.241', '2009-04-16', 6, '2115', '[\'Action\', \'Thriller\', \'Crime\']', 'Chelios faces a Chinese mobster who has stolen his nearly indestructible heart and replaced it with a battery-powered ticker that requires regular jolts of electricity to keep working.'),
(154, '522478', 'en', 'https://image.tmdb.org/t/p/w500/cycDz68DtTjJrDJ1fV8EBq2Xdpb.jpg', 'Peter Rabbit 2: The Runaway', '211.56', '2021-03-25', 7.4, '426', '[\'Family\', \'Comedy\', \'Adventure\', \'Animation\', \'Fantasy\']', 'Bea, Thomas, and the rabbits have created a makeshift family, but despite his best efforts, Peter can’t seem to shake his mischievous reputation. Adventuring out of the garden, Peter finds himself in a world where his mischief is appreciated, but when his family risks everything to come looking for him, Peter must figure out what kind of bunny he wants to be.'),
(155, '586047', 'ko', 'https://image.tmdb.org/t/p/w500/nxxuWC32Y6TULj4VnVwMPUFLIpK.jpg', '서복', '212.792', '2021-04-12', 7.5, '90', '[\'Science Fiction\', \'Action\']', 'A former intelligence agent gets involved with the first human clone, Seo Bok, who others seek, causing trouble.'),
(156, '400160', 'en', 'https://image.tmdb.org/t/p/w500/jlJ8nDhMhCYJuzOw3f52CP1W8MW.jpg', 'The SpongeBob Movie: Sponge on the Run', '200.485', '2020-08-14', 7.7, '2343', '[\'Family\', \'Animation\', \'Fantasy\', \'Adventure\', \'Comedy\']', 'When his best friend Gary is suddenly snatched away, SpongeBob takes Patrick on a madcap mission far beyond Bikini Bottom to save their pink-shelled pal.'),
(157, '559907', 'en', 'https://image.tmdb.org/t/p/w500/if4hw3Ou5Sav9Em7WWHj66mnywp.jpg', 'The Green Knight', '197.458', '2021-07-29', 6.7, '498', '[\'Adventure\', \'Drama\', \'Fantasy\']', 'An epic fantasy adventure based on the timeless Arthurian legend, The Green Knight tells the story of Sir Gawain, King Arthur\'s reckless and headstrong nephew, who embarks on a daring quest to confront the eponymous Green Knight, a gigantic emerald-skinned stranger and tester of men.'),
(158, '597433', 'en', 'https://image.tmdb.org/t/p/w500/hGIxOfxsgcNS8aco8xgFlv3rYnt.jpg', 'Beckett', '203.703', '2021-08-04', 6.4, '383', '[\'Action\', \'Crime\', \'Drama\', \'Mystery\']', 'While vacationing in Greece, Beckett, becomes the target of a manhunt after a devastating car accident forces him to run for his life across the country to clear his name but tensions escalate as the authorities close in and political unrest mounts which makes Beckett fall even deeper into a dangerous web of conspiracy.'),
(159, '871875', 'en', 'https://image.tmdb.org/t/p/w500/dSF7INctoCQ4iPFRiRkZjIQIIVa.jpg', 'Escape The Undertaker', '204.213', '2021-10-05', 5.3, '26', '[\'Horror\', \'Mystery\', \'Family\']', 'The Undertaker has set a trap for the decorated tag team The New Day at his mansion. What they don\'t know: The Undertaker\'s mansion is an extreme Haunted House, packed to the brim with supernatural challenges. It\'s up to viewers to decide the fate of these poor souls trying to survive the wrath of The Undertaker.'),
(160, '674', 'en', 'https://image.tmdb.org/t/p/w500/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg', 'Harry Potter and the Goblet of Fire', '212.082', '2005-11-16', 7.8, '16256', '[\'Adventure\', \'Fantasy\', \'Family\']', 'When Harry Potter\'s name emerges from the Goblet of Fire, he becomes a competitor in a grueling battle for glory among three wizarding schools—the Triwizard Tournament. But since Harry never submitted his name for the Tournament, who did? Now Harry must confront a deadly dragon, fierce water demons and an enchanted maze only to find himself in the cruel grasp of He Who Must Not Be Named.'),
(161, '656940', 'en', 'https://image.tmdb.org/t/p/w500/fNQUUrtlN79pDIMAPigX8NUvNW2.jpg', 'Body Brokers', '193.708', '2021-02-19', 6.6, '47', '[\'Thriller\', \'Crime\']', 'Utah and his girlfriend Opal, are drug addicts living on the streets in rural Ohio. After getting recruited by body broker Wood, and offered treatment in Los Angeles, Wood takes Utah under his wing and introduces him to treatment center mogul Vin. Wood and Vin bring Utah in on their lucrative and illegal dealings, where saving lives comes second to the bottom line.'),
(162, '672', 'en', 'https://image.tmdb.org/t/p/w500/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', 'Harry Potter and the Chamber of Secrets', '216.882', '2002-11-13', 7.7, '17203', '[\'Adventure\', \'Fantasy\']', 'Cars fly, trees fight back, and a mysterious house-elf comes to warn Harry Potter at the start of his second year at Hogwarts. Adventure and danger await when bloody writing on a wall announces: The Chamber Of Secrets Has Been Opened. To save Hogwarts will require all of Harry, Ron and Hermione’s magical abilities and courage.'),
(163, '8960', 'en', 'https://image.tmdb.org/t/p/w500/7DyuV2G0hLEqHeueDfOqhZ2DVut.jpg', 'Hancock', '226.726', '2008-07-01', 6.3, '7665', '[\'Fantasy\', \'Action\']', 'Hancock is a down-and-out superhero who\'s forced to employ a PR expert to help repair his image when the public grows weary of all the damage he\'s inflicted during his lifesaving heroics. The agent\'s idea of imprisoning the antihero to make the world miss him proves successful, but will Hancock stick to his new sense of purpose or slip back into old habits?'),
(164, '585216', 'en', 'https://image.tmdb.org/t/p/w500/jGYJyPzVgrVV2bgClI9uvEZgVLE.jpg', 'Escape Room: Tournament of Champions', '174.019', '2021-07-01', 6.9, '709', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Six people unwittingly find themselves locked in another series of escape rooms, slowly uncovering what they have in common to survive as they discover all the games that they\'ve played before.'),
(165, '638045', 'en', 'https://image.tmdb.org/t/p/w500/q6vV6sSWz9cytmc8L9IEBjjyFmV.jpg', 'The Toll', '200.391', '2021-03-26', 6.2, '59', '[\'Thriller\', \'Horror\']', 'A socially awkward driver and a weary passenger try to make it to their destination while being haunted by a supernatural threat.'),
(166, '25769', 'en', 'https://image.tmdb.org/t/p/w500/puJzc96EFU4oh6NZ195RKaHpdMz.jpg', 'Carriers', '203.334', '2009-09-04', 5.8, '815', '[\'Action\', \'Drama\', \'Horror\', \'Science Fiction\', \'Thriller\']', 'A deadly virus has spread across the globe. Contagion is everywhere, no one is safe, and no one can be trusted. Four friends race through the back roads of the American West on their way to a secluded utopian beach in the Gulf of Mexico where they could peacefully wait out the pandemic. Their plans take a grim turn when their car breaks down on an isolated road starting a chain of events that will seal their fates.'),
(167, '299534', 'en', 'https://image.tmdb.org/t/p/w500/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', 'Avengers: Endgame', '193.86', '2019-04-24', 8.3, '19434', '[\'Adventure\', \'Science Fiction\', \'Action\']', 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos\' actions and restore order to the universe once and for all, no matter what consequences may be in store.'),
(168, '531219', 'en', 'https://image.tmdb.org/t/p/w500/ht6EfsM5hrsUPSR4ReJQFDVU71F.jpg', 'Roald Dahl\'s The Witches', '197.823', '2020-10-25', 6.5, '1941', '[\'Family\', \'Fantasy\', \'Adventure\', \'Comedy\', \'Horror\']', 'In late 1967, a young orphaned boy goes to live with his loving grandma in the rural Alabama town of Demopolis. As the boy and his grandmother encounter some deceptively glamorous but thoroughly diabolical witches, she wisely whisks him away to a seaside resort. Regrettably, they arrive at precisely the same time that the world\'s Grand High Witch has gathered.'),
(169, '673', 'en', 'https://image.tmdb.org/t/p/w500/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg', 'Harry Potter and the Prisoner of Azkaban', '208.631', '2004-05-31', 8, '16913', '[\'Adventure\', \'Fantasy\']', 'Year three at Hogwarts means new fun and challenges as Harry learns the delicate art of approaching a Hippogriff, transforming shape-shifting Boggarts into hilarity and even turning back time. But the term also brings danger: soul-sucking Dementors hover over the school, an ally of the accursed He-Who-Cannot-Be-Named lurks within the castle walls, and fearsome wizard Sirius Black escapes Azkaban. And Harry will confront them all.'),
(170, '505262', 'ja', 'https://image.tmdb.org/t/p/w500/hC4nTxdhXqFWzgqynGvvXVMiMNp.jpg', '僕のヒーローアカデミア THE MOVIE ～2人の英雄～', '220.805', '2018-08-03', 8, '677', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\']', 'All Might and Deku accept an invitation to go abroad to a floating and mobile manmade city, called \'I-Island\', where they research quirks as well as hero supplemental items at the special \'I-Expo\' convention that is currently being held on the island. During that time, suddenly, despite an iron wall of security surrounding the island, the system is breached by a villain, and the only ones able to stop him are the students of Class 1-A.'),
(171, '740925', 'en', 'https://image.tmdb.org/t/p/w500/bZUostLcCZYgcuBuAjmuSkBggiQ.jpg', 'No One Gets Out Alive', '172.059', '2021-09-29', 6, '223', '[\'Horror\', \'Thriller\', \'Mystery\']', 'An immigrant in search of the American dream is forced to take a room in a boarding house and soon finds herself in a nightmare from which she can\'t escape.'),
(172, '866408', 'zh', 'https://image.tmdb.org/t/p/w500/h4HcBZC8XMuSFBNxWu7qd34tFDI.jpg', '火星异变', '213.619', '2021-08-27', 6.3, '19', '[\'Drama\', \'Science Fiction\']', 'In the near future, the Earth’s resources are gradually getting scarce. In order to continue the hope of survival for generations of children and grandchildren, top scientists from various countries have brought several species of animals and plants to Mars for research, hoping to improve the Martian environment through advanced science and technology to make it suitable for human habitation.'),
(173, '24428', 'en', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', 'The Avengers', '209.584', '2012-04-25', 7.7, '25642', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!'),
(174, '814780', 'en', 'https://image.tmdb.org/t/p/w500/cfbAuU9EUz4slitPRqVgoI5P8bk.jpg', 'Farm to Fork to Love', '194.391', '2021-04-29', 5.2, '5', '[\'Romance\', \'TV Movie\']', 'Alice, a young and talented sous chef at NY\'s top restaurant, receives an invitation to judge a food competition for a prestigious annual fundraiser.'),
(175, '102382', 'en', 'https://image.tmdb.org/t/p/w500/bU7nTmvmy0h3VUP01v1T2imgH6N.jpg', 'The Amazing Spider-Man 2', '221.297', '2014-04-16', 6.4, '9866', '[\'Action\', \'Adventure\', \'Fantasy\']', 'For Peter Parker, life is busy. Between taking out the bad guys as Spider-Man and spending time with the person he loves, Gwen Stacy, high school graduation cannot come quickly enough. Peter has not forgotten about the promise he made to Gwen’s father to protect her by staying away, but that is a promise he cannot keep. Things will change for Peter when a new villain, Electro, emerges, an old friend, Harry Osborn, returns, and Peter uncovers new clues about his past.'),
(176, '800823', 'es', 'https://image.tmdb.org/t/p/w500/xxK9GyYqEN8224PxSdkOKYbLPZX.jpg', 'A todo tren: destino Asturias', '186.728', '2021-07-08', 4.7, '33', '[\'Comedy\', \'Family\']', 'When Ricardo, a responsible father, decides to personally take his son to a camp in Asturias, other parents propose that he should also take care of their children. When the train is about to leave, Felipe, a flamboyant individual and grandfather of two of the children, shows up at the station.'),
(177, '198663', 'en', 'https://image.tmdb.org/t/p/w500/ode14q7WtDugFDp78fo9lCsmay9.jpg', 'The Maze Runner', '204.576', '2014-09-10', 7.2, '13987', '[\'Action\', \'Mystery\', \'Science Fiction\', \'Thriller\']', 'Set in a post-apocalyptic world, young Thomas is deposited in a community of boys after his memory is erased, soon learning they\'re all trapped in a maze that will require him to join forces with fellow “runners” for a shot at escape.'),
(178, '11932', 'en', 'https://image.tmdb.org/t/p/w500/yaIPNOcC7ZRuwH3maNwP9qzIo5G.jpg', 'Bride of Chucky', '175.452', '1998-10-16', 5.9, '1302', '[\'Horror\', \'Comedy\', \'Romance\']', 'Chucky hooks up with another murderous doll, the bridal gown-clad Tiffany, for a Route 66 murder spree with their unwitting hosts.'),
(179, '604822', 'zh', 'https://image.tmdb.org/t/p/w500/mKvw1Ic9enfFlCPBNJGiejRPMUO.jpg', '急先锋', '188.834', '2020-09-30', 6.3, '374', '[\'Action\', \'Adventure\', \'Crime\']', 'Covert security company Vanguard is the last hope of survival for an accountant after he is targeted by the world\'s deadliest mercenary organization.'),
(180, '11322', 'en', 'https://image.tmdb.org/t/p/w500/3KgtekisQBrHRsm2cD5UOB6Ce3k.jpg', 'Public Enemies', '165.954', '2009-07-01', 6.7, '3432', '[\'Crime\', \'History\']', 'Depression-era bank robber John Dillinger\'s charm and audacity endear him to much of America\'s downtrodden public, but he\'s also a thorn in the side of J. Edgar Hoover and the fledgling FBI. Desperate to capture the elusive outlaw, Hoover makes Dillinger his first Public Enemy Number One and assigns his top agent, Melvin Purvis, the task of bringing him in dead or alive.'),
(181, '431075', 'en', 'https://image.tmdb.org/t/p/w500/6a1iqhfM0Y31kNPOSNPIuPrsYQ6.jpg', 'Polaroid', '218.474', '2019-01-10', 5.8, '684', '[\'Horror\', \'Thriller\', \'Mystery\']', 'High school loner Bird Fitcher has no idea what dark secrets are tied to the mysterious Polaroid vintage camera she stumbles upon, but it doesn\'t take long to discover that those who have their picture taken meet a tragic end. Bird and her friends must survive one more night as they race to solve the mystery of the haunted Polaroid before it kills them all.'),
(182, '159211', 'en', 'https://image.tmdb.org/t/p/w500/iB8rf8FYHGlrbmLybCo6Mpg8hNt.jpg', 'The Haunting of Helena', '173.551', '2013-01-14', 5.6, '115', '[\'Horror\', \'Thriller\']', 'After a divorce, Sophia moves to the south of Italy with her daughter, Helena. Their new home, an apartment within an austere building of the fascist age, is a chance for them to start a new life. But inside an old storage room hides a mysterious closet and a buried secret. After the loss of Helena’s first baby tooth, a chilling obsession begins and an apparition haunts her sleep...'),
(183, '12445', 'en', 'https://image.tmdb.org/t/p/w500/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', 'Harry Potter and the Deathly Hallows: Part 2', '191.193', '2011-07-07', 8.1, '16362', '[\'Fantasy\', \'Adventure\']', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort\'s formidable skills.'),
(184, '22894', 'en', 'https://image.tmdb.org/t/p/w500/ykocDqwg5PRUopnBVb1x1DWnEJF.jpg', 'Legion', '189.34', '2010-01-21', 5.7, '1933', '[\'Horror\', \'Action\', \'Fantasy\']', 'When God loses faith in humankind, he sends his legion of angels to bring on the Apocalypse. Humanity\'s only hope for survival lies in a group of strangers trapped in an out-of-the-way, desert diner with the Archangel Michael.'),
(185, '834404', 'en', 'https://image.tmdb.org/t/p/w500/xBOipwFIZS2uLk0FwmKpysCx4HD.jpg', 'Teen Titans Go! See Space Jam', '199.353', '2021-06-20', 7, '143', '[\'Animation\', \'Action\', \'Adventure\', \'Comedy\', \'Family\', \'Fantasy\', \'Science Fiction\']', 'The Teen Titans are visited by the Nerdlucks, the Space Jam villains who tried to capture Michael Jordan and the Looney Tunes. Astonished to discover his fellow Titans have never seen Space Jam, Cyborg organizes an exclusive watch party. Of course, if the Titans are watching a movie, don\'t expect silence to be golden. Raven and Starfire provide the commentary, Cyborg presents the fun facts, Beast Boy points out the butt shots, and Robin, but Robin doesn\'t trust their new alien friends. Are the Nerdlucks here to attend an innocent watch party, or do they have more sinister motives up their sleeves?'),
(186, '557', 'en', 'https://image.tmdb.org/t/p/w500/kjdJntyBeEvqm9w97QGBdxPptzj.jpg', 'Spider-Man', '221.416', '2002-05-01', 7.2, '14296', '[\'Fantasy\', \'Action\']', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.'),
(187, '623135', 'ko', 'https://image.tmdb.org/t/p/w500/alBxLvZ5LkDRJPw4TX1PgkWLE8a.jpg', '싱크홀', '189.962', '2021-08-11', 7.3, '21', '[\'Comedy\', \'Drama\']', 'The average citizen Dong-won and his family move into a house bought after years of hard work. Filled with happiness, he invites his colleagues for a housewarming party, but the heavy rain during the night before creates a gigantic sinkhole, and in a mere minute, it swallows up the whole house and the people inside. Hundreds of meters down the hole, Dong-won, his neighbor Man-su, and the unfortunate guests must find their way out. Rain starts to pour down, filling the sinkhole with water, and they’re running out of time.'),
(188, '763532', 'en', 'https://image.tmdb.org/t/p/w500/9vDOARw8Avodokk2WZzVI4M1piE.jpg', 'Long Story Short', '179.125', '2021-02-11', 7.4, '51', '[\'Romance\', \'Comedy\', \'Fantasy\']', 'Teddy wakes up the morning after his wedding to discover that he\'s jumped forward a year in his life to his first anniversary. Trapped in an endless cycle of time jumps, transported another year ahead every few minutes, he is faced with a race against time as his life crumbles around him.'),
(189, '615658', 'en', 'https://image.tmdb.org/t/p/w500/jIPIxaBcppLLkygko7tV5yuTIs1.jpg', 'Awake', '194.284', '2021-06-09', 6, '708', '[\'Drama\', \'Science Fiction\', \'Thriller\']', 'After a sudden global event wipes out all electronics and takes away humankind’s ability to sleep, chaos quickly begins to consume the world. Only Jill, an ex-soldier with a troubled past, may hold the key to a cure in the form of her own daughter. The question is, can Jill safely deliver her daughter and save the world before she herself loses her mind.'),
(190, '12444', 'en', 'https://image.tmdb.org/t/p/w500/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg', 'Harry Potter and the Deathly Hallows: Part 1', '186.846', '2010-10-17', 7.8, '15180', '[\'Adventure\', \'Fantasy\']', 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort\'s bid for immortality. But with Harry\'s beloved Dumbledore dead and Voldemort\'s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.'),
(191, '512025', 'en', 'https://image.tmdb.org/t/p/w500/GaPJQscaH4MtYQTbJyWjCUIho8.jpg', 'There\'s Someone Inside Your House', '181.842', '2021-09-24', 5.7, '259', '[\'Horror\', \'Thriller\', \'Mystery\']', 'As the countdown to graduation begins, students at Osborne High are being stalked by a maniac intent on exposing their darkest secrets to the entire town, terrorizing victims while wearing a life-like mask of their own face. With a mysterious past of her own, Makani and her friends must discover the killer\'s identity before they become victims themselves.'),
(192, '767', 'en', 'https://image.tmdb.org/t/p/w500/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg', 'Harry Potter and the Half-Blood Prince', '188.106', '2009-07-07', 7.7, '15241', '[\'Adventure\', \'Fantasy\']', 'As Lord Voldemort tightens his grip on both the Muggle and wizarding worlds, Hogwarts is no longer a safe haven. Harry suspects perils may even lie within the castle, but Dumbledore is more intent upon preparing him for the final battle fast approaching. Together they work to find the key to unlock Voldemorts defenses and to this end, Dumbledore recruits his old friend and colleague Horace Slughorn, whom he believes holds crucial information. Even as the decisive showdown looms, romance blossoms for Harry, Ron, Hermione and their classmates. Love is in the air, but danger lies ahead and Hogwarts may never be the same again.'),
(193, '768744', 'ja', 'https://image.tmdb.org/t/p/w500/jzP5rPwwNqUGERlrUzKKljfyulf.jpg', '僕のヒーローアカデミア THE MOVIE ワールド ヒーローズ ミッション', '184.977', '2021-08-06', 7.2, '21', '[\'Animation\', \'Action\', \'Comedy\', \'Fantasy\', \'Adventure\']', 'A mysterious group called Humarize strongly believes in the Quirk Singularity Doomsday theory which states that when quirks get mixed further in with future generations, that power will bring forth the end of humanity. In order to save everyone, the Pro-Heroes around the world ask UA Academy heroes-in-training to assist them and form a world-classic selected hero team. It is up to the heroes to save the world and the future of heroes in what is the most dangerous crisis to take place yet in My Hero Academia.'),
(194, '653349', 'en', 'https://image.tmdb.org/t/p/w500/cCyJeTAct07ORPJPHyzxCrVtZzh.jpg', 'Vacation Friends', '144.236', '2021-08-27', 7.3, '326', '[\'Comedy\']', 'When a straight-laced couple that has fun with a rowdy couple on vacation in Mexico return to the States, they discover that the crazy couple they met in Mexico followed them back home and decide to play tricks on them.'),
(195, '615457', 'en', 'https://image.tmdb.org/t/p/w500/oBgWY00bEFeZ9N25wWVyuQddbAo.jpg', 'Nobody', '191.625', '2021-03-18', 8.3, '3624', '[\'Action\', \'Crime\', \'Thriller\', \'Drama\']', 'Hutch Mansell, a suburban dad, overlooked husband, nothing neighbor — a \"nobody.\" When two thieves break into his home one night, Hutch\'s unknown long-simmering rage is ignited and propels him on a brutal path that will uncover dark secrets he fought to leave behind.'),
(196, '38234', 'en', 'https://image.tmdb.org/t/p/w500/g8KB77SPA7SyU8eid6TAEpt9skU.jpg', 'Undisputed III: Redemption', '200.045', '2010-05-22', 7.5, '569', '[\'Action\', \'Thriller\']', 'Russian inmate Boyka, now severely hobbled by the knee injury suffered at the end of Undisputed 2. No longer the feared prison fighter he was, he has declined so far that he is now good only for cleaning toilets. But when a new prison fight tournament begins - an international affair, matching the best fighters from prisons around the globe, enticing them with the promise of freedom for the winner - Boyka must reclaim his dignity and fight for his position in the tournament.'),
(197, '565028', 'en', 'https://image.tmdb.org/t/p/w500/jQtgkgDZE7egMq532sOt83DnT83.jpg', 'Candyman', '167.154', '2021-08-25', 6.4, '564', '[\'Horror\', \'Thriller\']', 'Anthony and his partner move into a loft in the now gentrified Cabrini-Green, and after a chance encounter with an old-timer exposes Anthony to the true story behind Candyman, he unknowingly opens a door to a complex past that unravels his own sanity and unleashes a terrifying wave of violence.'),
(198, '303857', 'ja', 'https://image.tmdb.org/t/p/w500/soq3AxjALdBfdPAm8H7yuMmNL5Y.jpg', 'ドラゴンボールZ 復活の「F」', '187.296', '2015-04-18', 6.8, '1240', '[\'Action\', \'Animation\', \'Science Fiction\']', 'One peaceful day on Earth, two remnants of Frieza\'s army named Sorbet and Tagoma arrive searching for the Dragon Balls with the aim of reviving Frieza. They succeed, and Frieza subsequently seeks revenge on the Saiyans.'),
(199, '784500', 'ja', 'https://image.tmdb.org/t/p/w500/f91rtk8dODezNLT3grQrELyzFwA.jpg', '劇場版 美少女戦士セーラームーンEternal 後編', '185.857', '2021-02-11', 8.2, '90', '[\'Animation\', \'Action\', \'Adventure\', \'Comedy\', \'Drama\', \'Fantasy\', \'Romance\']', 'While under the care of the Outer Sailor Guardians, Hotaru begins to age rapidly. Then, the time comes for all the Sailor Guardians to reunite!'),
(200, '550205', 'en', 'https://image.tmdb.org/t/p/w500/lnPf6hzANL6pVQTxUlsNYSuhT5l.jpg', 'Wish Dragon', '182.12', '2021-01-15', 8.2, '663', '[\'Animation\', \'Family\', \'Comedy\', \'Fantasy\']', 'Determined teen Din is longing to reconnect with his childhood best friend when he meets a wish-granting dragon who shows him the magic of possibilities.'),
(201, '773660', 'es', 'https://image.tmdb.org/t/p/w500/1bdjpX9l2tueek5gUOm7LntLXMX.jpg', 'Este amor es de otro planeta', '247.872', '2021-03-31', 4.5, '2', '[\'Comedy\', \'Romance\']', ''),
(202, '876576', 'en', 'https://image.tmdb.org/t/p/w500/eZvpTcUk0L8paEqegXzUcJa9nG.jpg', 'Go! Go! Cory Carson: Chrissy Takes the Wheel', '155.155', '2021-09-21', 5.5, '8', '[\'Animation\', \'Family\']', 'From arcade games to sled days and hiccup cures, Cory Carson’s curious little sister Chrissy speeds off on her own for fun and adventure all over town!'),
(203, '24021', 'en', 'https://image.tmdb.org/t/p/w500/dK4Gi1UdMiHzHc7r7CZQG4IQ9Sr.jpg', 'The Twilight Saga: Eclipse', '183.118', '2010-06-23', 6.2, '7154', '[\'Adventure\', \'Fantasy\', \'Drama\', \'Romance\']', 'Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob, knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.'),
(204, '337401', 'en', 'https://image.tmdb.org/t/p/w500/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg', 'Mulan', '165.655', '2020-09-04', 7, '5239', '[\'Adventure\', \'Fantasy\']', 'When the Emperor of China issues a decree that one man per family must serve in the Imperial Chinese Army to defend the country from Huns, Hua Mulan, the eldest daughter of an honored warrior, steps in to take the place of her ailing father. She is spirited, determined and quick on her feet. Disguised as a man by the name of Hua Jun, she is tested every step of the way and must harness her innermost strength and embrace her true potential.'),
(205, '774456', 'es', 'https://image.tmdb.org/t/p/w500/5kFquXISihCWIe1ANGCK08r0dEz.jpg', 'García y García', '172.079', '2021-08-27', 3.2, '3', '[\'Comedy\']', ''),
(206, '809314', 'en', 'https://image.tmdb.org/t/p/w500/qlXenN6jjgbsIyEJxBjkfkEU0q8.jpg', 'Trigger Point', '181.905', '2021-04-23', 6.6, '86', '[\'Action\', \'Thriller\']', 'Nicolas Shaw is a retired U.S. special operative who becomes part of an elite \'invisible\' team that quietly takes out the worst villains around the world.'),
(207, '22832', 'en', 'https://image.tmdb.org/t/p/w500/ipJ4mgqse6uoTRsDyU3TXmva1rt.jpg', 'Ninja Assassin', '158.219', '2009-09-29', 6.5, '1053', '[\'Action\']', 'Ninja Assassin follows Raizo, one of the deadliest assassins in the world. Taken from the streets as a child, he was transformed into a trained killer by the Ozunu Clan, a secret society whose very existence is considered a myth. But haunted by the merciless execution of his friend by the Clan, Raizo breaks free from them and vanishes. Now he waits, preparing to exact his revenge.'),
(208, '618162', 'en', 'https://image.tmdb.org/t/p/w500/su9WzL7lwUZPhjH6eZByAYFx2US.jpg', 'The Harder They Fall', '264.246', '2021-10-22', 6.6, '197', '[\'Western\']', 'Gunning for revenge, outlaw Nat Love saddles up with his gang to take down enemy Rufus Buck, a ruthless crime boss who just got sprung from prison.'),
(209, '13475', 'en', 'https://image.tmdb.org/t/p/w500/hN2ZtF3Uw6mhIHZiqL0SKzELtKn.jpg', 'Star Trek', '170.815', '2009-05-06', 7.4, '8170', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'The fate of the galaxy rests in the hands of bitter rivals. One, James Kirk, is a delinquent, thrill-seeking Iowa farm boy. The other, Spock, a Vulcan, was raised in a logic-based society that rejects all emotion. As fiery instinct clashes with calm reason, their unlikely but powerful partnership is the only thing capable of leading their crew through unimaginable danger, boldly going where no one has gone before. The human adventure has begun again.'),
(210, '32657', 'en', 'https://image.tmdb.org/t/p/w500/brzpTyZ5bnM7s53C1KSk1TmrMO6.jpg', 'Percy Jackson & the Olympians: The Lightning Thief', '172.953', '2010-02-01', 6.2, '6008', '[\'Adventure\', \'Fantasy\', \'Family\']', 'Accident prone teenager, Percy discovers he\'s actually a demi-God, the son of Poseidon, and he is needed when Zeus\' lightning is stolen. Percy must master his new found skills in order to prevent a war between the Gods that could devastate the entire world.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(211, '474350', 'en', 'https://image.tmdb.org/t/p/w500/zfE0R94v1E8cuKAerbskfD3VfUt.jpg', 'It Chapter Two', '165.741', '2019-09-04', 6.9, '6418', '[\'Horror\', \'Fantasy\']', '27 years after overcoming the malevolent supernatural entity Pennywise, the former members of the Losers\' Club, who have grown up and moved away from Derry, are brought back together by a devastating phone call.'),
(212, '393345', 'en', 'https://image.tmdb.org/t/p/w500/r5JUiMYfatwYeDkxkLWYUx5GIjY.jpg', 'Cult of Chucky', '149.692', '2017-10-23', 5.8, '800', '[\'Horror\', \'Thriller\']', 'Confined to an asylum for the criminally insane, Nica Pierce is convinced that she, not Chucky, murdered her entire family. But when the psychiatrist introduces a new therapeutic \"Good Guy\" doll with a familiar face, a string of new, grisly deaths leads Nica to wonder if she isn\'t crazy after all.'),
(213, '410113', 'fr', 'https://image.tmdb.org/t/p/w500/7dM5DILTl9ddpjvnJhs2nA1U9Ru.jpg', 'The Loud House Movie', '177.043', '2021-08-20', 8.4, '84', '[\'Animation\', \'Family\', \'Comedy\', \'Music\', \'Fantasy\']', 'The Loud family travel to Scotland and discover they are descendants of Scottish royalty as they move into their giant ancestral castle.'),
(214, '633515', 'nl', 'https://image.tmdb.org/t/p/w500/wU8ijITXE2ZgoXJexTQByJiHCbp.jpg', 'De Slag om de Schelde', '172.669', '2021-06-05', 7.2, '183', '[\'War\', \'History\', \'Drama\']', 'November 1944. On the flooded isle of Walcheren, Zeeland, thousands of Allied soldiers are battling the German army. Three young lives become inextricably connected. A Dutch boy fighting for the Germans, an English glider pilot and a girl from Zeeland connected to the resistance against her will, are forced to make crucial choices that impact both their own freedom and the freedom of others.'),
(215, '590706', 'en', 'https://image.tmdb.org/t/p/w500/eLT8Cu357VOwBVTitkmlDEg32Fs.jpg', 'Jiu Jitsu', '165.469', '2020-11-20', 5.1, '445', '[\'Fantasy\', \'Action\', \'Science Fiction\']', 'Every six years, an ancient order of jiu-jitsu fighters joins forces to battle a vicious race of alien invaders. But when a celebrated war hero goes down in defeat, the fate of the planet and mankind hangs in the balance.'),
(216, '532067', 'ja', 'https://image.tmdb.org/t/p/w500/fv5BgcfkpWh3V6Pb1qVlXESBOdl.jpg', '映画 この素晴らしい世界に祝福を！紅伝説', '172.811', '2019-08-30', 8.5, '303', '[\'Adventure\', \'Comedy\', \'Animation\', \'Fantasy\']', 'It is not strange that the Demon Lord\'s forces fear the Crimson Demons, the clan from which Megumin and Yunyun originate. Even if the Demon Lord\'s generals attack their village, the Crimson Demons can just easily brush them off with their supreme mastery of advanced and overpowered magic.  When Yunyun receives a seemingly serious letter regarding a potential disaster coming to her hometown, she immediately informs Kazuma Satou and the rest of his party. After a series of wacky misunderstandings, it turns out to be a mere prank by her fellow demon who wants to be an author. Even so, Megumin becomes worried about her family and sets out toward the Crimson Demons\' village with the gang.  There, Kazuma and the others decide to sightsee the wonders of Megumin\'s birthplace. However, they soon come to realize that the nonsense threat they received might have been more than just a joke.'),
(217, '659940', 'da', 'https://image.tmdb.org/t/p/w500/iedopRnMHIDyQlZzTTfroJfHhSN.jpg', 'Marco effekten', '165.433', '2021-05-27', 6.5, '11', '[\'Thriller\', \'Crime\']', 'When 14-year-old Marco, a homeless Romani boy, is arrested at the Danish border for possession of a missing public servant\'s passport, police inspector Carl Mørck and his Department Q team are tasked with finding the connection. The old case contains several suspicious elements: The public servant was accused of pedophilia shortly before he disappeared, and his case was closed unusually quickly. But the silent, traumatized Marco refuses to talk to them and it\'s not long before he\'s on the run from those who intend to kill him because of what he knows.'),
(218, '675', 'en', 'https://image.tmdb.org/t/p/w500/5aOyriWkPec0zUDxmHFP9qMmBaj.jpg', 'Harry Potter and the Order of the Phoenix', '175.883', '2007-06-28', 7.7, '15479', '[\'Adventure\', \'Fantasy\', \'Mystery\']', 'The rebellion begins! Lord Voldemort has returned, but the Ministry of Magic is doing everything it can to keep the wizarding world from knowing the truth – including appointing Ministry official Dolores Umbridge as the new Defence Against the Dark Arts professor at Hogwarts. When Umbridge refuses to teach practical defensive magic, Ron and Hermione convince Harry to secretly train a select group of students for the wizarding war that lies ahead. A terrifying showdown between good and evil awaits in this enthralling film version of the fifth novel in J.K. Rowling’s Harry Potter series. Prepare for battle!'),
(219, '283566', 'ja', 'https://image.tmdb.org/t/p/w500/md5wZRRj8biHrGtyitgBZo7674t.jpg', 'シン・エヴァンゲリオン劇場版:||', '182.942', '2021-03-08', 8.6, '359', '[\'Animation\', \'Action\', \'Drama\', \'Science Fiction\']', 'In the aftermath of the Fourth Impact, stranded without their Evangelions, Shinji, Asuka, and Rei find refuge in one of the rare pockets of humanity that still exist on the ruined planet Earth. There, each of them live a life far different from their days as an Evangelion pilot. However, the danger to the world is far from over. A new impact is looming on the horizon—one that will prove to be the true end of Evangelion.'),
(220, '786705', 'pt', 'https://image.tmdb.org/t/p/w500/fRxz9cKaCOF5noUBvoA6cebOdUE.jpg', 'Confissões de Uma Garota Excluída', '163.901', '2021-09-22', 6.9, '108', '[\'Comedy\', \'Drama\']', 'When the clever but socially-awkward Tetê joins a new school, she\'ll do anything to fit in. But the queen bee among her classmates has other ideas.'),
(221, '572154', 'ja', 'https://image.tmdb.org/t/p/w500/AtFnN4OztDJy8IFwYd5JfU0jlEM.jpg', '青春ブタ野郎はゆめみる少女の夢を見ない', '168.435', '2019-06-15', 8.5, '317', '[\'Animation\', \'Comedy\', \'Romance\', \'Drama\', \'Fantasy\']', 'In Fujisawa, Sakuta Azusagawa is in his second year of high school. Blissful days with his girlfriend and upperclassman, Mai Sakurajima, are interrupted by the appearance of his first crush, Shoko Makinohara.'),
(222, '91314', 'en', 'https://image.tmdb.org/t/p/w500/jyzrfx2WaeY60kYZpPYepSjGz4S.jpg', 'Transformers: Age of Extinction', '166.524', '2014-06-25', 5.9, '6392', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'As humanity picks up the pieces, following the conclusion of \"Transformers: Dark of the Moon,\" Autobots and Decepticons have all but vanished from the face of the planet. However, a group of powerful, ingenious businessman and scientists attempt to learn from past Transformer incursions and push the boundaries of technology beyond what they can control - all while an ancient, powerful Transformer menace sets Earth in his cross-hairs.'),
(223, '848932', 'en', 'https://image.tmdb.org/t/p/w500/xHJhH0pGTFLsECDry3G170M8fsG.jpg', '粉色樱与大眠王', '169.603', '2021-07-06', 4.5, '2', '[\'Romance\']', 'The male lead is the king of a small island nation. He was previously badly hurt by the female lead. The female lead has a canine tooth that makes her look extremely captivating when she smiles. When the female lead vanished, the male lead became extremely fond of sleeping because he did not want to miss her. As fate would have it, the male lead married the female lead in the end. He decided to properly torment that adorable yet horrible woman for a while'),
(224, '4564', 'en', 'https://image.tmdb.org/t/p/w500/AhNfnsGW95RKHQNLdgFH48UN0Zy.jpg', 'Sex and the City', '147.048', '2008-05-12', 6.6, '1703', '[\'Comedy\', \'Drama\', \'Romance\']', 'A New York writer on sex and love is finally getting married to her Mr. Big. But her three best girlfriends must console her after one of them inadvertently leads Mr. Big to jilt her.'),
(225, '809968', 'pl', 'https://image.tmdb.org/t/p/w500/9jUF9fuNRaJv0uYEJ1J3srNAnX7.jpg', 'Bartkowiak', '151.004', '2021-07-28', 6.3, '113', '[\'Action\', \'Thriller\']', 'After his brother dies in a car crash, a disgraced MMA fighter takes over the family nightclub — and soon learns his sibling\'s death wasn’t an accident.'),
(226, '347626', 'en', 'https://image.tmdb.org/t/p/w500/kW3AG5NHoyq52dcSbMiFB6LyHvk.jpg', 'He\'s All That', '176.343', '2021-08-27', 6.9, '679', '[\'Comedy\', \'Romance\']', 'To get revenge on her ex-boyfriend, an influencer attempts to transform an unpopular classmate into prom king.'),
(227, '862', 'en', 'https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', 'Toy Story', '153.86', '1995-10-30', 8, '14635', '[\'Animation\', \'Adventure\', \'Family\', \'Comedy\']', 'Led by Woody, Andy\'s toys live happily in his room until Andy\'s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy\'s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.'),
(228, '785516', 'fr', 'https://image.tmdb.org/t/p/w500/bvK9AMUvh0TzjSmWwv74CgBEfg2.jpg', '8 Rue de l\'Humanité', '134.572', '2021-10-20', 6.1, '150', '[\'Comedy\']', 'Seven families live in the Parisian apartment building at 8, Rue de l’Humanite - and they didn’t escape to the countryside at the arrival of the coronavirus. Three months of life under lockdown will reveal the best and worst of these neighbours.'),
(229, '10358', 'en', 'https://image.tmdb.org/t/p/w500/ipePhKf87FixwfAVJ8MMWK53caI.jpg', 'Zack and Miri Make a Porno', '127.583', '2008-09-18', 6.3, '1757', '[\'Comedy\']', 'Lifelong platonic friends Zack and Miri look to solve their respective cash-flow problems by making an adult film together. As the cameras roll, however, the duo begin to sense that they may have more feelings for each other than they previously thought.'),
(230, '330457', 'en', 'https://image.tmdb.org/t/p/w500/mINJaa34MtknCYl5AjtNJzWj8cD.jpg', 'Frozen II', '166.097', '2019-11-20', 7.3, '7740', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'Elsa, Anna, Kristoff and Olaf head far into the forest to learn the truth about an ancient mystery of their kingdom.'),
(231, '4247', 'en', 'https://image.tmdb.org/t/p/w500/fVQFPRuw3yWXojYDJvA5EoFjUOY.jpg', 'Scary Movie', '143.834', '2000-07-07', 6.3, '5152', '[\'Comedy\']', 'A familiar-looking group of teenagers find themselves being stalked by a more-than-vaguely recognizable masked killer! As the victims begin to pile up and the laughs pile on, none of your favorite scary movies escape the razor-sharp satire of this outrageously funny parody!'),
(232, '10138', 'en', 'https://image.tmdb.org/t/p/w500/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', 'Iron Man 2', '177.523', '2010-04-28', 6.8, '16914', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James \'Rhodey\' Rhodes at his side, must forge new alliances – and confront powerful enemies.'),
(233, '122917', 'en', 'https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg', 'The Hobbit: The Battle of the Five Armies', '149.368', '2014-12-10', 7.3, '11435', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Immediately after the events of The Desolation of Smaug, Bilbo and the dwarves try to defend Erebor\'s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo\'s hands.'),
(234, '372058', 'ja', 'https://image.tmdb.org/t/p/w500/q719jXXEzOoYaps6babgKnONONX.jpg', '君の名は。', '154.252', '2016-08-26', 8.6, '8013', '[\'Romance\', \'Animation\', \'Drama\']', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.'),
(235, '293660', 'en', 'https://image.tmdb.org/t/p/w500/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', 'Deadpool', '139.535', '2016-02-09', 7.6, '25733', '[\'Action\', \'Adventure\', \'Comedy\']', 'Deadpool tells the origin story of former Special Forces operative turned mercenary Wade Wilson, who after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.'),
(236, '581387', 'ko', 'https://image.tmdb.org/t/p/w500/gCZ0RHifBxZGedde7WPWSgjpyZt.jpg', '백두산', '160.747', '2019-12-19', 6.5, '328', '[\'Action\', \'Adventure\', \'Thriller\']', 'A group of unlikely heroes from across the Korean peninsula try to save the day after a volcano erupts on the mythical and majestic Baekdu Mountain.'),
(237, '808023', 'en', 'https://image.tmdb.org/t/p/w500/ufFbnDMa1XNJxWYxlYv2jEPxUcD.jpg', 'The Virtuoso', '143.514', '2021-04-30', 6.3, '196', '[\'Thriller\', \'Action\', \'Crime\']', 'A lonesome stranger with nerves of steel must track down and kill a rogue hitman to satisfy an outstanding debt. But the only information he\'s been given is a time and location where to find his quarry. No name. No description. Nothing.'),
(238, '335797', 'en', 'https://image.tmdb.org/t/p/w500/b8UiFXwMrSXVTHM0fb2twl8uE8a.jpg', 'Sing', '154.993', '2016-11-23', 7.1, '6280', '[\'Family\', \'Animation\', \'Music\', \'Comedy\', \'Drama\']', 'A koala named Buster recruits his best friend to help him drum up business for his theater by hosting a singing competition.'),
(239, '646207', 'en', 'https://image.tmdb.org/t/p/w500/gl1dlX9sKYpiKujq80Yxve7l4yg.jpg', 'The Ice Road', '151.124', '2021-06-24', 7.2, '730', '[\'Action\', \'Adventure\', \'Drama\', \'Thriller\']', 'After a remote diamond mine collapses in far northern Canada, an ice road driver must lead an impossible rescue mission over a frozen ocean to save the trapped miners.'),
(240, '723072', 'en', 'https://image.tmdb.org/t/p/w500/h7dZpJDORYs5c56dydbrLFkEXpE.jpg', 'Host', '143.281', '2020-12-04', 6.6, '424', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Six friends hire a medium to hold a séance via Zoom during lockdown — but they get far more than they bargained for as things quickly go wrong. When an evil spirit starts invading their homes, they begin to realize they might not survive the night.'),
(241, '99861', 'en', 'https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', 'Avengers: Age of Ultron', '139.577', '2015-04-22', 7.3, '18757', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.'),
(242, '553604', 'en', 'https://image.tmdb.org/t/p/w500/zeD4PabP6099gpE0STWJrJrCBCs.jpg', 'Honest Thief', '141.884', '2020-09-03', 6.5, '1124', '[\'Thriller\', \'Action\', \'Crime\', \'Drama\']', 'A bank robber tries to turn himself in because he\'s falling in love and wants to live an honest life...but when he realizes the Feds are more corrupt than him, he must fight back to clear his name.'),
(243, '591273', 'en', 'https://image.tmdb.org/t/p/w500/9J9Wy39ZjrVmfk7yMkulpcI5sy0.jpg', 'Fear Street: 1994', '137.655', '2021-06-28', 6.8, '1226', '[\'Horror\', \'Mystery\']', 'In 1994, a group of teenagers discovers that the terrifying events which have haunted their town for generations ​are all connected — and that they may be the next targets.'),
(244, '743439', 'en', 'https://image.tmdb.org/t/p/w500/qHcn3PbjVHxBweDZxWpYH3JfugS.jpg', 'PAW Patrol: Jet to the Rescue', '157.469', '2021-12-02', 0, '0', '[\'Family\', \'Animation\']', 'Get ready to zoom back to Barkingburg with the pups in this all-new TV movie! When the scheming DUKE of Flappington steals a powerful levitation gem from the royal castle, it’s up to the PAW Patrol to jet to the rescue before the town is lost forever! Then join the PAW Patrol in even more high-flying adventures where they will save a stunt pilot, one of Mayor Humdinger’s kittens, and even Skye when she breaks her wing flying to Jake’s Mountain!'),
(245, '607259', 'en', 'https://image.tmdb.org/t/p/w500/wvqO1gTAMZIFGi3Ioq1BN6KV95R.jpg', 'Fatherhood', '140.428', '2021-06-18', 7.7, '859', '[\'Drama\', \'Family\', \'Comedy\']', 'A widowed new dad copes with doubts, fears, heartache and dirty diapers as he sets out to raise his daughter on his own. Inspired by a true story.'),
(246, '675024', 'es', 'https://image.tmdb.org/t/p/w500/uoTPjx07dxTrC1g3dYeaS2WNVGL.jpg', 'El Exorcismo de Carmen Farías', '134.901', '2021-05-05', 6.4, '74', '[\'Horror\']', 'Carmen, a brave journalist, discovers soon after her mother\'s death that she has inherited her grandma\'s house. She decides to move there without knowing it hides dark secrets.'),
(247, '384018', 'en', 'https://image.tmdb.org/t/p/w500/qRyy2UmjC5ur9bDi3kpNNRCc5nc.jpg', 'Fast & Furious Presents: Hobbs & Shaw', '145.33', '2019-08-01', 6.9, '5417', '[\'Action\', \'Adventure\', \'Comedy\']', 'Ever since US Diplomatic Security Service Agent Hobbs and lawless outcast Shaw first faced off, they just have traded smack talk and body blows. But when cyber-genetically enhanced anarchist Brixton\'s ruthless actions threaten the future of humanity, they join forces to defeat him.'),
(248, '14869', 'en', 'https://image.tmdb.org/t/p/w500/mc9b25IAprHfsaOz0wTshOwGHcY.jpg', 'G.I. Joe: The Rise of Cobra', '146.299', '2009-08-03', 5.7, '3738', '[\'Adventure\', \'Action\', \'Thriller\', \'Science Fiction\']', 'From the Egyptian desert to deep below the polar ice caps, the elite G.I. JOE team uses the latest in next-generation spy and military equipment to fight the corrupt arms dealer Destro and the growing threat of the mysterious Cobra organization to prevent them from plunging the world into chaos.'),
(249, '811367', 'en', 'https://image.tmdb.org/t/p/w500/32vLDKSzcCMh55zqqaSqqUA8naz.jpg', '22 vs. Earth', '157.116', '2021-04-30', 7.1, '218', '[\'Family\', \'Comedy\', \'Fantasy\', \'Animation\']', 'Set before the events of ‘Soul’, 22 refuses to go to Earth, enlisting a gang of 5 new souls in attempt of rebellion. However, 22’s subversive plot leads to a surprising revelation about the meaning of life.'),
(250, '659954', 'fr', 'https://image.tmdb.org/t/p/w500/qciSIhwpjS3NtzW4VcgSzxK04sG.jpg', 'Azor', '143.506', '2021-09-10', 5.6, '7', '[\'Drama\']', 'Yvan De Wiel, a private banker from Geneva, is going to an Argentina in the midst of a dictatorship to replace his partner, the object of the most worrying rumours, who disappeared overnight. Between hushed lounges, swimming pools and gardens under surveillance, a remote duel between two bankers who, despite different methods, are the accomplices of a discreet and merciless form of colonization.'),
(251, '571891', 'ja', 'https://image.tmdb.org/t/p/w500/rtlyO2oIMcCx2DbOM52XO2rAcgn.jpg', '劇場版 ポケットモンスター ミュウツーの逆襲 EVOLUTION', '171.112', '2019-07-12', 6.7, '345', '[\'Animation\', \'Adventure\', \'Fantasy\', \'Action\', \'Family\']', 'After accepting an invitation from a mysterious trainer, Ash, Misty and Brock meet Mewtwo, an artificially created Pokémon who wants to do battle.'),
(252, '324857', 'en', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', 'Spider-Man: Into the Spider-Verse', '162.399', '2018-12-06', 8.4, '10126', '[\'Action\', \'Adventure\', \'Animation\', \'Science Fiction\', \'Comedy\']', 'Miles Morales is juggling his life between being a high school student and being a spider-man. When Wilson \"Kingpin\" Fisk uses a super collider, others from across the Spider-Verse are transported to this dimension.'),
(253, '72331', 'en', 'https://image.tmdb.org/t/p/w500/qv8deK0ZmutAuEpejruQKApIy6r.jpg', 'Abraham Lincoln: Vampire Hunter', '153.492', '2012-06-20', 5.7, '2625', '[\'Action\', \'Fantasy\', \'Horror\']', 'President Lincoln\'s mother is killed by a supernatural creature, which fuels his passion to crush vampires and their slave-owning helpers.'),
(254, '583081', 'en', 'https://image.tmdb.org/t/p/w500/d0iPHGvzEIvoiTkBVVMWOuMGarH.jpg', 'Warning', '145.949', '2021-10-22', 5.9, '36', '[\'Science Fiction\', \'Thriller\', \'Drama\']', 'Loneliness, death and the meaning of life, explored through vastly separate lives colliding in interweaving short stories set in future Earth.'),
(255, '741074', 'en', 'https://image.tmdb.org/t/p/w500/hddzYJtfYYeMDOQVcH58n8m1W3A.jpg', 'Once Upon a Snowman', '164.474', '2020-10-23', 6.9, '388', '[\'Animation\', \'Family\', \'Comedy\', \'Fantasy\']', 'The previously untold origins of Olaf, the innocent and insightful, summer-loving snowman are revealed as we follow Olaf’s first steps as he comes to life and searches for his identity in the snowy mountains outside Arendelle.'),
(256, '39254', 'en', 'https://image.tmdb.org/t/p/w500/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg', 'Real Steel', '151.173', '2011-09-28', 6.9, '6312', '[\'Action\', \'Science Fiction\', \'Drama\']', 'Charlie Kenton is a washed-up fighter who retired from the ring when robots took over the sport. After his robot is trashed, he reluctantly teams up with his estranged son to rebuild and train an unlikely contender.'),
(257, '136797', 'en', 'https://image.tmdb.org/t/p/w500/45D153Bk0bNwonV1w5IBBvqssPV.jpg', 'Need for Speed', '112.352', '2014-03-12', 6.3, '3404', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'The film revolves around a local street-racer who partners with a rich and arrogant business associate, only to find himself framed by his colleague and sent to prison. After he gets out, he joins a New York-to-Los Angeles race to get revenge. But when the ex-partner learns of the scheme, he puts a massive bounty on the racer\'s head, forcing him to run a cross-country gauntlet of illegal racers in all manner of supercharged vehicles.'),
(258, '138843', 'en', 'https://image.tmdb.org/t/p/w500/wVYREutTvI2tmxr6ujrHT704wGF.jpg', 'The Conjuring', '129.537', '2013-03-20', 7.5, '8829', '[\'Horror\', \'Thriller\']', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.'),
(259, '10196', 'en', 'https://image.tmdb.org/t/p/w500/kl9JJ8288bNsY8oqT1SpQh1w2mb.jpg', 'The Last Airbender', '133.331', '2010-06-30', 4.7, '3093', '[\'Action\', \'Adventure\', \'Fantasy\']', 'The story follows the adventures of Aang, a young successor to a long line of Avatars, who must put his childhood ways aside and stop the Fire Nation from enslaving the Water, Earth and Air nations.'),
(260, '602734', 'en', 'https://image.tmdb.org/t/p/w500/cTvSDfBuXTZTdRCNduGMANd7VEP.jpg', 'Spiral: From the Book of Saw', '143.703', '2021-05-12', 6.3, '930', '[\'Horror\', \'Crime\', \'Mystery\']', 'Working in the shadow of an esteemed police veteran, brash Detective Ezekiel “Zeke” Banks and his rookie partner take charge of a grisly investigation into murders that are eerily reminiscent of the city’s gruesome past.  Unwittingly entrapped in a deepening mystery, Zeke finds himself at the center of the killer’s morbid game.'),
(261, '43347', 'en', 'https://image.tmdb.org/t/p/w500/wZLM2uKJRYNchLmiCIjosX0rXy8.jpg', 'Love & Other Drugs', '130.559', '2010-11-22', 7, '3969', '[\'Drama\', \'Comedy\', \'Romance\']', 'Maggie is an alluring free spirit who won\'t let anyone – or anything – tie her down. But she meets her match in Jamie, whose relentless and nearly infallible charm serves him well with the ladies and in the cutthroat world of pharmaceutical sales. Maggie and Jamie\'s evolving relationship takes them both by surprise, as they find themselves under the influence of the ultimate drug: love.'),
(262, '214756', 'en', 'https://image.tmdb.org/t/p/w500/38C91I7Xft0gyY7BITm8i4yvuRb.jpg', 'Ted 2', '143.756', '2015-06-25', 6.3, '5903', '[\'Comedy\']', 'Newlywed couple Ted and Tami-Lynn want to have a baby, but in order to qualify to be a parent, Ted will have to prove he\'s a person in a court of law.'),
(263, '18785', 'en', 'https://image.tmdb.org/t/p/w500/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', 'The Hangover', '139.259', '2009-06-02', 7.3, '13819', '[\'Comedy\']', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can\'t seem to locate their best friend, Doug – who\'s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.'),
(264, '27578', 'en', 'https://image.tmdb.org/t/p/w500/j09ZkH6R4JWVylBcDai1laCmGw7.jpg', 'The Expendables', '131.546', '2010-08-03', 6.2, '6202', '[\'Thriller\', \'Adventure\', \'Action\']', 'Barney Ross leads a band of highly skilled mercenaries including knife enthusiast Lee Christmas, a martial arts expert, heavy weapons specialist, demolitionist, and a loose-cannon sniper. When the group is commissioned by the mysterious Mr. Church to assassinate the dictator of a small South American island, Barney and Lee visit the remote locale to scout out their opposition and discover the true nature of the conflict engulfing the city.'),
(265, '68726', 'en', 'https://image.tmdb.org/t/p/w500/8wo4eN8dWKaKlxhSvBz19uvj8gA.jpg', 'Pacific Rim', '135.647', '2013-07-11', 6.8, '10092', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'A ragtag band of humans band together in the year 2025 to fight legions of monstrous creatures rising from the sea. Using massive piloted robots to combat the alien threat, earth\'s survivors take the fight to the invading alien force lurking in the depths of the Pacific Ocean. Nearly defenseless in the face of the relentless enemy, the forces of mankind have no choice but to turn to two unlikely heroes -- a washed up former pilot and an untested trainee -- who now stand as earth\'s final hope against the mounting apocalypse.'),
(266, '27205', 'en', 'https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', 'Inception', '144.741', '2010-07-15', 8.3, '30184', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: \"inception\", the implantation of another person\'s idea into a target\'s subconscious.'),
(267, '9479', 'en', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'The Nightmare Before Christmas', '136.45', '1993-10-09', 7.8, '7112', '[\'Fantasy\', \'Animation\', \'Family\']', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack\'s rag-doll girlfriend, Sally, tries to foil his misguided plans.'),
(268, '24418', 'en', 'https://image.tmdb.org/t/p/w500/8DSRpomxdPAsyecjDH2sgMqYBkL.jpg', 'Cirque du Freak: The Vampire\'s Assistant', '145.311', '2009-10-23', 5.7, '838', '[\'Adventure\', \'Fantasy\', \'Action\', \'Thriller\']', 'Darren Shan is a regular teenage kid. He and his friend Steve find out about a Freak Show coming to town and work hard at trying to find tickets. They do, and together they go to \"Cirque du Freak\" where they see many strange acts including a wolf-man and a bearded lady'),
(269, '875460', 'es', 'https://image.tmdb.org/t/p/w500/lTCsGvAjqBbqp7T5ziK28SeDfVT.jpg', 'Cato', '155.765', '2021-10-14', 2, '1', '[\'Drama\']', ''),
(270, '11249', 'en', 'https://image.tmdb.org/t/p/w500/vd9K93gQ9whMKjXzADZanxWpIXM.jpg', 'Seed of Chucky', '124.59', '2004-11-11', 5.4, '1085', '[\'Horror\', \'Comedy\', \'Thriller\']', 'Chucky and Tiffany are resurrected by their innocent son, Glen, and hit Hollywood, where a movie depicting the killer dolls\' murder spree is underway.'),
(271, '590995', 'en', 'https://image.tmdb.org/t/p/w500/lhMIra0pqWNuD6CIXoTmGwZ0EBS.jpg', 'The Craft: Legacy', '214.36', '2020-10-28', 6.4, '475', '[\'Horror\', \'Drama\', \'Fantasy\']', 'An eclectic foursome of aspiring teenage witches get more than they bargained for as they lean into their newfound powers.'),
(272, '776909', 'es', 'https://image.tmdb.org/t/p/w500/tYUdh9HsTHLd2GJUtAyKg3InlXs.jpg', 'Fuimos canciones', '130.055', '2021-09-29', 6.6, '62', '[\'Comedy\', \'Romance\']', 'Fashion assistant Maca has just about got her life together after a devastating breakup, when Leo, the man who broke her heart returns. Seeking support from best friends, Adriana and Jime, all three will learn love can be complicated.'),
(273, '10585', 'en', 'https://image.tmdb.org/t/p/w500/wvpgvcWNkF2HLuTEMIM7K83MvZ.jpg', 'Child\'s Play', '139.534', '1988-11-08', 6.6, '2030', '[\'Horror\']', 'A single mother gives her son a beloved doll for his birthday, only to discover that it is possessed by the soul of a serial killer.'),
(274, '585', 'en', 'https://image.tmdb.org/t/p/w500/wFSpyMsp7H0ttERbxY7Trlv8xry.jpg', 'Monsters, Inc.', '155.086', '2001-11-01', 7.8, '14785', '[\'Animation\', \'Comedy\', \'Family\']', 'James Sullivan and Mike Wazowski are monsters, they earn their living scaring children and are the best in the business... even though they\'re more afraid of the children than they are of them. When a child accidentally enters their world, James and Mike suddenly find that kids are not to be afraid of and they uncover a conspiracy that could threaten all children across the world.'),
(275, '57214', 'en', 'https://image.tmdb.org/t/p/w500/lUPDGT3lyRrq8SvWuNWG2DP64bR.jpg', 'Project X', '132.264', '2012-03-01', 6.8, '4826', '[\'Comedy\']', 'Three high school seniors throw a party to make a name for themselves. As the night progresses, things spiral out of control as word of the party spreads.'),
(276, '769749', 'en', 'https://image.tmdb.org/t/p/w500/mRSsYtYcbhNAfHBp3ha1Nr65agi.jpg', 'Finding You', '141.589', '2021-05-13', 6.4, '23', '[\'Romance\', \'Drama\']', 'Finley, a talented aspiring violinist, meets Beckett, a famous young movie star, on the way to her college semester abroad program in a small coastal village in Ireland. An unexpected romance emerges as the heartthrob Beckett leads the uptight Finley on an adventurous reawakening, and she emboldens him to take charge of his future, until the pressures of his stardom get in the way.'),
(277, '412656', 'en', 'https://image.tmdb.org/t/p/w500/xAYGdGBGptNkisXRpmhZSry6SPF.jpg', 'Chaos Walking', '130.785', '2021-02-24', 6.8, '1346', '[\'Science Fiction\']', 'Two unlikely companions embark on a perilous adventure through the badlands of an unexplored planet as they try to escape a dangerous and disorienting reality, where all inner thoughts are seen and heard by everyone.'),
(278, '1865', 'en', 'https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg', 'Pirates of the Caribbean: On Stranger Tides', '164.123', '2011-05-14', 6.5, '11352', '[\'Adventure\', \'Action\', \'Fantasy\']', 'Captain Jack Sparrow crosses paths with a woman from his past, and he\'s not sure if it\'s love -- or if she\'s a ruthless con artist who\'s using him to find the fabled Fountain of Youth. When she forces him aboard the Queen Anne\'s Revenge, the ship of the formidable pirate Blackbeard, Jack finds himself on an unexpected adventure in which he doesn\'t know who to fear more: Blackbeard or the woman from his past.'),
(279, '8587', 'en', 'https://image.tmdb.org/t/p/w500/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', 'The Lion King', '135.559', '1994-06-23', 8.3, '14586', '[\'Family\', \'Animation\', \'Drama\']', 'A young lion prince is cast out of his pride by his cruel uncle, who claims he killed his father. While the uncle rules with an iron paw, the prince grows up beyond the Savannah, living by a philosophy: No worries for the rest of your days. But when his past comes to haunt him, the young prince must decide his fate: Will he remain an outcast or face his demons and become what he needs to be?'),
(280, '72190', 'en', 'https://image.tmdb.org/t/p/w500/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg', 'World War Z', '118.892', '2013-06-20', 6.8, '12458', '[\'Action\', \'Drama\', \'Horror\', \'Science Fiction\', \'Thriller\']', 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.'),
(281, '333339', 'en', 'https://image.tmdb.org/t/p/w500/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', 'Ready Player One', '130.46', '2018-03-28', 7.6, '12141', '[\'Science Fiction\', \'Adventure\', \'Action\']', 'When the creator of a popular video game system dies, a virtual contest is created to compete for his fortune.'),
(282, '301528', 'en', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', 'Toy Story 4', '123.399', '2019-06-19', 7.6, '7466', '[\'Family\', \'Adventure\', \'Animation\', \'Comedy\', \'Fantasy\', \'Drama\']', 'Woody has always been confident about his place in the world and that his priority is taking care of his kid, whether that\'s Andy or Bonnie. But when Bonnie adds a reluctant new toy called \"Forky\" to her room, a road trip adventure alongside old and new friends will show Woody how big the world can be for a toy.'),
(283, '400155', 'en', 'https://image.tmdb.org/t/p/w500/lzE5BwGQea1nek7TPXUuC5AZ6rq.jpg', 'Hotel Transylvania 3: Summer Vacation', '133.111', '2018-06-28', 6.9, '3332', '[\'Family\', \'Fantasy\', \'Comedy\', \'Animation\']', 'Dracula, Mavis, Johnny and the rest of the Drac Pack take a vacation on a luxury Monster Cruise Ship, where Dracula falls in love with the ship’s captain, Ericka, who’s secretly a descendant of Abraham Van Helsing, the notorious monster slayer.'),
(284, '216015', 'en', 'https://image.tmdb.org/t/p/w500/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg', 'Fifty Shades of Grey', '141.527', '2015-02-11', 5.9, '9860', '[\'Drama\', \'Romance\', \'Thriller\']', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian\'s true sexual proclivities push the boundaries of pain and pleasure.'),
(285, '34851', 'en', 'https://image.tmdb.org/t/p/w500/wdniP8NDaJIydi1hMxhpbJMUfr6.jpg', 'Predators', '131.253', '2010-07-03', 6.2, '2963', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'A group of cold-blooded killers find themselves trapped on an alien planet to be hunted by extraterrestrial Predators.'),
(286, '38575', 'en', 'https://image.tmdb.org/t/p/w500/1mp4ViklKvA0WXXsNvNx0RBuiit.jpg', 'The Karate Kid', '133.142', '2010-06-10', 6.5, '4653', '[\'Action\', \'Adventure\', \'Drama\', \'Family\']', 'Twelve-year-old Dre Parker could have been the most popular kid in Detroit, but his mother\'s latest career move has landed him in China. Dre immediately falls for his classmate Mei Ying but the cultural differences make such a friendship impossible. Even worse, Dre\'s feelings make him an enemy of the class bully, Cheng. With no friends in a strange land, Dre has nowhere to turn but maintenance man Mr. Han, who is a kung fu master. As Han teaches Dre that kung fu is not about punches and parries, but maturity and calm, Dre realizes that facing down the bullies will be the fight of his life.'),
(287, '630586', 'en', 'https://image.tmdb.org/t/p/w500/4U1SBHmwHkNA0eHZ2n1CuiC1K1g.jpg', 'Wrong Turn', '120.944', '2021-01-26', 6.1, '583', '[\'Horror\', \'Thriller\']', 'Jen and a group of friends set out to hike the Appalachian Trail. Despite warnings to stick to the trail, the hikers stray off course—and cross into land inhabited by The Foundation, a hidden community of mountain dwellers who use deadly means to protect their way of life.'),
(288, '630520', 'es', 'https://image.tmdb.org/t/p/w500/i0SecYO6UMV3Dr0D9FU6g5goTdy.jpg', 'La noche mágica', '135.977', '2021-03-11', 8.2, '20', '[\'Comedy\', \'Drama\']', 'A peaceful Christmas Eve is interrupted when a thief breaks into a villa. When the family’s little daughter mistakes him for Santa Claus and asks him to fulfill her Christmas wish, he will be forced to perform a miracle that will redeem secrets from the past.'),
(289, '228150', 'en', 'https://image.tmdb.org/t/p/w500/pfte7wdMobMF4CVHuOxyu6oqeeA.jpg', 'Fury', '142.06', '2014-10-15', 7.5, '9440', '[\'War\', \'Drama\', \'Action\']', 'In the last months of World War II, as the Allies make their final push in the European theatre, a battle-hardened U.S. Army sergeant named \'Wardaddy\' commands a Sherman tank called \'Fury\' and its five-man crew on a deadly mission behind enemy lines. Outnumbered and outgunned, Wardaddy and his men face overwhelming odds in their heroic attempts to strike at the heart of Nazi Germany.'),
(290, '118406', 'ja', 'https://image.tmdb.org/t/p/w500/xLal6fXNtiJN6Zw6qk21xAtdOeN.jpg', 'Road to Ninja: Naruto the Movie', '133.295', '2012-07-28', 7.6, '616', '[\'Animation\', \'Fantasy\', \'Action\']', 'Sixteen years ago, a mysterious masked ninja unleashes a powerful creature known as the Nine-Tailed Demon Fox on the Hidden Leaf Village Konoha, killing many people. In response, the Fourth Hokage Minato Namikaze and his wife Kushina Uzumaki, the Demon Fox\'s living prison or Jinchūriki, manage to seal the creature inside their newborn son Naruto Uzumaki. With the Tailed Beast sealed, things continued as normal. However, in the present day, peace ended when a group of ninja called the Akatsuki attack Konoha under the guidance of Tobi, the mysterious masked man behind Fox\'s rampage years ago who intends on executing his plan to rule the world by shrouding it in illusions.'),
(291, '75624', 'ja', 'https://image.tmdb.org/t/p/w500/4WT7zYFpe0fsbg6TitppiHddWAh.jpg', '劇場版 NARUTO -ナルト- ブラッド・プリズン', '127.505', '2011-07-30', 7.2, '316', '[\'Thriller\', \'Animation\', \'Action\', \'Comedy\', \'Horror\', \'Mystery\']', 'After his capture for attempted assassination of the Raikage, leader of Kumogakure, as well as killing Jōnin from Kirigakure and Iwagakure, Naruto is imprisoned in Hōzukijou: A criminal containment facility known as the Blood Prison. Mui, the castle master, uses the ultimate imprisonment technique to steal power from the prisoners, which is when Naruto notices his life has been targeted. Thus begins the battle to uncover the truth behind the mysterious murders and prove Naruto\'s innocence.'),
(292, '730840', 'en', 'https://image.tmdb.org/t/p/w500/zvUNFeTz0Sssb210wSiIiHRjA4W.jpg', 'Trollhunters: Rise of the Titans', '130.153', '2021-07-21', 8, '196', '[\'Animation\', \'Fantasy\', \'Family\', \'Action\', \'Adventure\', \'Science Fiction\']', 'Arcadia may look like an ordinary town, but it lies at the center of magical and mystical lines that makes it a nexus for many battles among otherworldly creatures, including trolls, aliens, and wizards. Now, various heroes will team-up in an epic adventure where they must fight the Arcane Order for control over the magic that binds them all together.'),
(293, '340102', 'en', 'https://image.tmdb.org/t/p/w500/xiDGcXJTvu1lazFRYip6g1eLt9c.jpg', 'The New Mutants', '127.816', '2020-08-26', 6.3, '2383', '[\'Horror\', \'Science Fiction\']', 'Five young mutants, just discovering their abilities while held in a secret facility against their will, fight to escape their past sins and save themselves.'),
(294, '808', 'en', 'https://image.tmdb.org/t/p/w500/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', 'Shrek', '144.217', '2001-05-18', 7.7, '13065', '[\'Animation\', \'Comedy\', \'Fantasy\', \'Adventure\', \'Family\']', 'It ain\'t easy bein\' green -- especially if you\'re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.'),
(295, '860425', 'es', 'https://image.tmdb.org/t/p/w500/oxNoVgbu2v9ETL93Kri1pw8osYf.jpg', 'Sinaliento', '123.674', '2021-08-11', 5.9, '32', '[\'Crime\', \'Drama\', \'Thriller\']', 'In the DR, hardened cop Manolo tries to take down an infamous drug cartel; meanwhile, his daughter has fallen in love with Lorenzo, a construction worker who\'s unwittingly gotten embroiled in the drug cartel\'s dealings.'),
(296, '716594', 'en', 'https://image.tmdb.org/t/p/w500/cr8wtSX1IGV7vLocSMzPnqGvsjq.jpg', 'No Man of God', '131.981', '2021-08-19', 6.9, '77', '[\'Crime\', \'Drama\', \'History\']', 'The complicated relationship that formed between the FBI analyst Bill Hagmaier and serial killer Bundy during Bundy\'s final years on death row.'),
(297, '98566', 'en', 'https://image.tmdb.org/t/p/w500/azL2ThbJMIkts3ZMt3j1YgBUeDB.jpg', 'Teenage Mutant Ninja Turtles', '121.653', '2014-08-07', 5.9, '5622', '[\'Science Fiction\', \'Action\', \'Adventure\', \'Comedy\']', 'When a kingpin threatens New York City, a group of mutated turtle warriors must emerge from the shadows to protect their home.'),
(298, '578701', 'en', 'https://image.tmdb.org/t/p/w500/xCEg6KowNISWvMh8GvPSxtdf9TO.jpg', 'Those Who Wish Me Dead', '130.33', '2021-05-05', 7, '925', '[\'Thriller\']', 'A young boy finds himself pursued by two assassins in the Montana wilderness, with a survival expert determined to protect him, and a forest fire threatening to consume them all.'),
(299, '854535', 'en', 'https://image.tmdb.org/t/p/w500/xDUsJtuTuwmBeQPAiYqLD490sSF.jpg', 'The Legacy of Chucky', '114.749', '2021-07-25', 5.4, '5', '[\'Horror\', \'Documentary\']', 'A celebration of the 30+ year legacy of the Child’s Play franchise and iconic character, Chucky, with never-before-seen interviews with franchise creator and actors.'),
(300, '631132', 'ja', 'https://image.tmdb.org/t/p/w500/A7SH888eBwbJDU3m48Vk2FK6ahW.jpg', 'ゴブリンスレイヤー -GOBLIN\'S CROWN-', '138.039', '2020-02-01', 7.7, '139', '[\'Animation\', \'Adventure\', \'Action\', \'Fantasy\']', 'Goblin Slayer and his party head up to the snowy mountains in the north after receiving that request from the Sword Maiden to find any information on the Noble Fencer that disappeared after leaving to slay some goblins. A small village gets attacked, they encounter a mysterious chapel, and something about how these goblins are acting bothers the Goblin slayer.  In order to save the captured Noble Fencer, the Goblin Slayer and his party head to an ancient fortress covered in snow to face off with a powerful foe and a horde of goblins!'),
(301, '14161', 'en', 'https://image.tmdb.org/t/p/w500/c2PkTPT5D9zB8SIm5wNlDAANEqM.jpg', '2012', '135.783', '2009-10-10', 5.8, '9992', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth\'s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world\'s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world\'s leaders race to build \"arks\" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.'),
(302, '3933', 'en', 'https://image.tmdb.org/t/p/w500/isb2Qow76GpqYmsSyfdMfsYAjts.jpg', 'Corpse Bride', '120.776', '2005-09-12', 7.5, '6743', '[\'Romance\', \'Fantasy\', \'Animation\']', 'Set in a 19th-century european village, this stop-motion animation feature follows the story of Victor, a young man whisked away to the underworld and wed to a mysterious corpse bride, while his real bride Victoria waits bereft in the land of the living.'),
(303, '44571', 'en', 'https://image.tmdb.org/t/p/w500/qDI6PbIjeEdLUoPHGaZqDMV9Fdx.jpg', 'The King of Fighters', '119.792', '2010-08-26', 4.7, '89', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'The King of Fighters movie will introduce a new science fiction spin into the setting established in the games universe by following the surviving members of three legendary fighting clans who are continually whisked away to other dimensions by an evil power. As the fighters enter each new world they battle that universes native defenders, while the force that brought them seeks to find a way to invade and infect our world.'),
(304, '676845', 'es', 'https://image.tmdb.org/t/p/w500/iM5kNvZzcMSmWv7CFTxnTu5zfoa.jpg', 'Juega Conmigo', '115.134', '2021-02-25', 7.2, '136', '[\'Horror\']', 'Sofia, an insecure young woman, begins babysitting two troublesome siblings that turn her job into a complete living hell. That is until a devilish presence starts messing with the trio and they must band together to fight the demon away.'),
(305, '775996', 'en', 'https://image.tmdb.org/t/p/w500/rBWy3MicOIGbxA0AsBK8VenWKVR.jpg', 'Outside the Wire', '132.287', '2021-01-15', 6.4, '1323', '[\'Thriller\', \'Action\', \'Science Fiction\']', 'In the near future, a drone pilot is sent into a deadly militarized zone and must work with an android officer to locate a doomsday device.'),
(306, '438695', 'en', 'https://image.tmdb.org/t/p/w500/aWeKITRFbbwY8txG5uCj4rMCfSP.jpg', 'Sing 2', '117.07', '2021-12-02', 0, '0', '[\'Family\', \'Comedy\', \'Animation\', \'Drama\', \'Music\']', 'Buster and his new cast now have their sights set on debuting a new show at the Crystal Tower Theater in glamorous Redshore City. But with no connections, he and his singers must sneak into the Crystal Entertainment offices, run by the ruthless wolf mogul Jimmy Crystal, where the gang pitches the ridiculous idea of casting the lion rock legend Clay Calloway in their show. Buster must embark on a quest to find the now-isolated Clay and persuade him to return to the stage.'),
(307, '425909', 'en', 'https://image.tmdb.org/t/p/w500/sg4xJaufDiQl7caFEskBtQXfD4x.jpg', 'Ghostbusters: Afterlife', '147.716', '2021-11-11', 7.9, '5', '[\'Comedy\', \'Fantasy\']', 'When a single mom and her two kids arrive in a small town, they begin to discover their connection to the original Ghostbusters and the secret legacy their grandfather left behind.'),
(308, '878231', 'en', 'https://image.tmdb.org/t/p/w500/6B2xwjjNSILqkMF9rNhnWbDGmKx.jpg', 'The Secret Lives of College Freshmen', '127.76', '2021-09-24', 2, '1', '[\'TV Movie\', \'Thriller\']', 'A college freshman moves into the perfect dorm on campus, but soon discovers the previous resident died under mysterious circumstances. Believing the girl was murdered, she tries to uncover the identity of the killer before it\'s too late.'),
(309, '10195', 'en', 'https://image.tmdb.org/t/p/w500/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', 'Thor', '136.338', '2011-04-21', 6.8, '17242', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Against his father Odin\'s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.'),
(310, '788905', 'es', 'https://image.tmdb.org/t/p/w500/12qaWw3KntFPoOCEJFSCLAuL7rN.jpg', 'A un paso de mí', '131.952', '2021-02-25', 7, '39', '[\'Adventure\', \'Comedy\', \'Drama\']', 'Tatiana is a journalist with a routine life in all its aspects and a recently failed love relationship. Motivated by her best friend, she decides to make a stop and travel around Costa Rica to find herself and inner peace.'),
(311, '50546', 'en', 'https://image.tmdb.org/t/p/w500/3rz7bfGsPGcI6cfY002n9VrUgao.jpg', 'Just Go with It', '129.168', '2011-02-10', 6.6, '4418', '[\'Comedy\', \'Romance\']', 'A plastic surgeon, romancing a much younger schoolteacher, enlists his loyal assistant to pretend to be his soon to be ex-wife, in order to cover up a careless lie. When more lies backfire, the assistant\'s kids become involved, and everyone heads off for a weekend in Hawaii that will change all their lives.'),
(312, '533642', 'en', 'https://image.tmdb.org/t/p/w500/wvpgvcWNkF2HLuTEMIM7K83MvZ.jpg', 'Child\'s Play', '119.218', '2019-06-19', 6, '1420', '[\'Horror\']', 'Karen, a single mother, gifts her son Andy a Buddi doll for his birthday, unaware of its more sinister nature. A contemporary re-imagining of the 1988 horror classic.'),
(313, '284053', 'en', 'https://image.tmdb.org/t/p/w500/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', 'Thor: Ragnarok', '131.502', '2017-10-25', 7.6, '16679', '[\'Action\', \'Adventure\', \'Comedy\', \'Fantasy\', \'Science Fiction\']', 'Thor is imprisoned on the other side of the universe and finds himself in a race against time to get back to Asgard to stop Ragnarok, the destruction of his home-world and the end of Asgardian civilization, at the hands of a powerful new threat, the ruthless Hela.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(314, '72545', 'en', 'https://image.tmdb.org/t/p/w500/uFm2vnp9LhHx5MNo1Ego6O3vUhl.jpg', 'Journey 2: The Mysterious Island', '128.153', '2012-01-19', 6.1, '3290', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'Sean Anderson partners with his mom\'s boyfriend on a mission to find his grandfather, who is thought to be missing on a mythical island.'),
(315, '662237', 'ko', 'https://image.tmdb.org/t/p/w500/3yGwAPl6LWpi8QwHjwCMaqsPgNB.jpg', '새콤달콤', '136.04', '2021-06-04', 7.9, '64', '[\'Comedy\', \'Romance\']', 'Faced with real-world opportunities and challenges, a couple endures the highs and lows of trying to make a long-distance relationship survive.'),
(316, '157336', 'en', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', 'Interstellar', '116.046', '2014-11-05', 8.4, '26999', '[\'Adventure\', \'Drama\', \'Science Fiction\']', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.'),
(317, '23168', 'en', 'https://image.tmdb.org/t/p/w500/3NIzyXkfylsjflRKSz8Fts3lXzm.jpg', 'The Town', '119.717', '2010-09-15', 7.2, '3756', '[\'Crime\', \'Drama\', \'Thriller\']', 'Doug MacRay is a longtime thief, who, smarter than the rest of his crew, is looking for his chance to exit the game. When a bank job leads to the group kidnapping an attractive branch manager, he takes on the role of monitoring her – but their burgeoning relationship threatens to unveil the identities of Doug and his crew to the FBI Agent who is on their case.'),
(318, '534', 'en', 'https://image.tmdb.org/t/p/w500/gw6JhlekZgtKUFlDTezq3j5JEPK.jpg', 'Terminator Salvation', '140.259', '2009-05-20', 6, '5115', '[\'Action\', \'Science Fiction\', \'Thriller\']', 'All grown up in post-apocalyptic 2018, John Connor must lead the resistance of humans against the increasingly dominating militaristic robots. But when Marcus Wright appears, his existence confuses the mission as Connor tries to determine whether Wright has come from the future or the past -- and whether he\'s friend or foe.'),
(319, '33273', 'es', 'https://image.tmdb.org/t/p/w500/koap5B3bQHQi3yaZ39vpWR66TGP.jpg', 'Celda 211', '125.665', '2009-11-06', 7.5, '910', '[\'Action\', \'Thriller\', \'Drama\']', 'The story of two men on different sides of a prison riot -- the inmate leading the rebellion and the young guard trapped in the revolt, who poses as a prisoner in a desperate attempt to survive the ordeal.'),
(320, '30767', 'en', 'https://image.tmdb.org/t/p/w500/1jhHwF0sMoi8fcmiZh1TAFfG7vF.jpg', 'Eternal', '120.275', '2004-09-24', 4, '16', '[\'Drama\', \'Horror\', \'Mystery\', \'Thriller\']', 'Detective Raymond Pope is a detective of questionable morals, searching for his missing wife. His investigation leads him to the wealthy estate of the enigmatic Elizabeth Kane and her young maid Irina. Under Elizabeth\'s fascinating looks and aristocratic manners hides a terrifying secret,shared by her companion Irina. As Detective Pope finds himself perversely drawn to the powerful Elizabeth, bodies begin to surface, his inquiries only deepening the mystery surrounding Elizabeth\'s past. Pope\'s obsession grows so intense that he completely fails to anticipate Elizabeth\'s reaction to his intrusion into her dark world, a fatal mistake that might cost him his life and the lives of those close to him.'),
(321, '602063', 'ja', 'https://image.tmdb.org/t/p/w500/7bbEASVf9XWtfxWiuWUMY3uyhTb.jpg', 'るろうに剣心 最終章 The Final', '120.346', '2021-04-23', 7.9, '265', '[\'Action\', \'Adventure\', \'Drama\']', 'In 1879, Kenshin and his allies face their strongest enemy yet: his former brother-in-law Enishi Yukishiro and his minions, who\'ve vowed their revenge.'),
(322, '119450', 'en', 'https://image.tmdb.org/t/p/w500/mSmAc9G25fhOHH45SLEeagR0qi7.jpg', 'Dawn of the Planet of the Apes', '114.003', '2014-06-26', 7.3, '9097', '[\'Science Fiction\', \'Action\', \'Drama\', \'Thriller\']', 'A group of scientists in San Francisco struggle to stay alive in the aftermath of a plague that is wiping out humanity, while Caesar tries to maintain dominance over his community of intelligent apes.'),
(323, '727745', 'en', 'https://image.tmdb.org/t/p/w500/c7xcqnMDVQ5v1hJBm3AZ5YikNe6.jpg', 'The Kissing Booth 3', '131.877', '2021-08-11', 7.3, '1221', '[\'Romance\', \'Comedy\']', 'It’s the summer before Elle heads to college, and she has a secret decision to make. Elle has been accepted into Harvard, where boyfriend Noah is matriculating, and also Berkeley, where her BFF Lee is headed and has to decide if she should stay or not.'),
(324, '560144', 'en', 'https://image.tmdb.org/t/p/w500/2W4ZvACURDyhiNnSIaFPHfNbny3.jpg', 'Skylines', '124.425', '2020-10-25', 5.7, '376', '[\'Science Fiction\', \'Action\']', 'When a virus threatens to turn the now earth-dwelling friendly alien hybrids against humans, Captain Rose Corley must lead a team of elite mercenaries on a mission to the alien world in order to save what\'s left of humanity.'),
(325, '885110', 'en', 'https://image.tmdb.org/t/p/w500/n8798tEvkj6INi1we2o0wC1Jthy.jpg', 'Amina', '186.998', '2021-11-04', 6, '5', '[\'War\', \'History\', \'Drama\', \'Adventure\']', 'In 16th-century Zazzau, now Zaria, Nigeria, Amina must utilize her military skills and tactics to defend her family\'s kingdom. Based on a true story.'),
(326, '18823', 'en', 'https://image.tmdb.org/t/p/w500/6iHYLipwEyZUPNO8MM3l1yHDaFE.jpg', 'Clash of the Titans', '134.318', '2010-03-31', 5.9, '5046', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Born of a god but raised as a man, Perseus is helpless to save his family from Hades, vengeful god of the underworld. With nothing to lose, Perseus volunteers to lead a dangerous mission to defeat Hades before he can seize power from Zeus and unleash hell on earth. Battling unholy demons and fearsome beasts, Perseus and his warriors will only survive if Perseus accepts his power as a god, defies fate and creates his own destiny.'),
(327, '481084', 'en', 'https://image.tmdb.org/t/p/w500/qFf8anju5f2epI0my8RdwwIXFIP.jpg', 'The Addams Family', '116.563', '2019-10-10', 6.7, '1619', '[\'Family\', \'Animation\', \'Comedy\']', 'The Addams family\'s lives begin to unravel when they face-off against a treacherous, greedy crafty reality-TV host while also preparing for their extended family to arrive for a major celebration.'),
(328, '22803', 'en', 'https://image.tmdb.org/t/p/w500/fcEXcip7v0O1ndV4VUdFqJSqbOg.jpg', 'Law Abiding Citizen', '138.868', '2009-10-15', 7.3, '3759', '[\'Drama\', \'Crime\', \'Thriller\']', 'A frustrated man decides to take justice into his own hands after a plea bargain sets one of his family\'s killers free. He targets not only the killer but also the district attorney and others involved in the deal.'),
(329, '475557', 'en', 'https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', 'Joker', '116.462', '2019-10-02', 8.2, '18970', '[\'Crime\', \'Thriller\', \'Drama\']', 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.'),
(330, '792657', 'en', 'https://image.tmdb.org/t/p/w500/2mfnSVdDartB6TJ3k7Qyn0zMzKu.jpg', 'Safer at Home', '109.528', '2021-02-26', 5.7, '86', '[\'Thriller\', \'Horror\']', 'Two years into the pandemic, a group of friends throw an online party with a night of games, drinking and drugs. After taking an ecstasy pill, things go terribly wrong and the safety of their home becomes more terrifying than the raging chaos outside.'),
(331, '259693', 'en', 'https://image.tmdb.org/t/p/w500/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', 'The Conjuring 2', '101.648', '2016-05-13', 7.3, '6402', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.'),
(332, '796428', 'en', 'https://image.tmdb.org/t/p/w500/19pHi0qrUKvnUtwx6EoVbFNxg1E.jpg', 'Madres', '121.017', '2021-10-08', 5.9, '31', '[\'Horror\']', 'A Mexican-American couple expecting their first child relocate to a migrant farming community in 1970\'s California. When the wife begins to experience strange symptoms and terrifying visions, she tries to determine if it\'s related to a legendary curse or something more nefarious'),
(333, '228326', 'en', 'https://image.tmdb.org/t/p/w500/aotTZos5KswgCryEzx2rlOjFsm1.jpg', 'The Book of Life', '122.104', '2014-10-01', 7.5, '2037', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\', \'Fantasy\']', 'The journey of Manolo, a young man who is torn between fulfilling the expectations of his family and following his heart. Before choosing which path to follow, he embarks on an incredible adventure that spans three fantastical worlds where he must face his greatest fears.'),
(334, '578908', 'en', 'https://image.tmdb.org/t/p/w500/fq0JfDZeL9lZWyXcIZdOlHvjAQs.jpg', 'Bad Trip', '123.69', '2020-03-26', 6.1, '328', '[\'Comedy\']', 'Two pals embark on a road trip full of funny pranks that pull real people into mayhem.'),
(335, '400535', 'en', 'https://image.tmdb.org/t/p/w500/qcLYofEhNh51Sk1jUWjmKHLzkqw.jpg', 'Sicario: Day of the Soldado', '112.159', '2018-06-27', 6.9, '2528', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'Agent Matt Graver teams up with operative Alejandro Gillick to prevent Mexican drug cartels from smuggling terrorists across the United States border.'),
(336, '440249', 'en', 'https://image.tmdb.org/t/p/w500/rfItXrtDGILwsCdmgVxX79phFuI.jpg', 'After Porn Ends 2', '129.369', '2017-03-28', 5.5, '183', '[\'Documentary\']', 'After Porn Ends 2 picks up where its predecessor left off and not only turns back the clock to meet the oldest living stars in adult film\'s history, but goes in depth with some of Its most current retirees and juxtaposes their experiences in a life after porn. Delving deeper into society\'s ongoing stigmas of race, misogyny, and the reality of decreasing opportunities for these former VHS box cover stars. For some, their careers in adult entertainment is accepted proudly and without regret. In fact, it seems to have proven to be the pathway to their current happiness and inner peace. For others, however, a career in porn has proven to be a conduit to certain despair as they struggle to find a way to bury their past and emerge with a new career or calling.'),
(337, '592656', 'en', 'https://image.tmdb.org/t/p/w500/kKSs1Ce4wOJSwqlqFdi4BuQ9Q9T.jpg', 'Brothers by Blood', '114.855', '2020-09-08', 6, '83', '[\'Crime\', \'Action\', \'Drama\']', 'Peter and Michael, raised on the streets of Philadelphia, are the children of Irish mob members, forever linked by the crimes of their fathers. 30 years later, Michael now runs the criminal organization and lusts for more power, his dangerous antics frequently held in check by his cautious cousin Peter. Haunted by the death of his sister, whose passing destroyed both his parents, Peter is caught between the dreams of childhood and the realities of his life as an enforcer. His only reprieve is a local boxing gym, a sanctuary that is quickly threatened as Michael’s desire for control escalates.'),
(338, '106646', 'en', 'https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', 'The Wolf of Wall Street', '127.565', '2013-12-25', 8, '18565', '[\'Crime\', \'Drama\', \'Comedy\']', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort\'s autobiography.'),
(339, '70981', 'en', 'https://image.tmdb.org/t/p/w500/qsYQflQhOuhDpQ0W2aOcwqgDAeI.jpg', 'Prometheus', '109.482', '2012-05-30', 6.5, '9786', '[\'Science Fiction\', \'Adventure\', \'Mystery\']', 'A team of explorers discover a clue to the origins of mankind on Earth, leading them on a journey to the darkest corners of the universe. There, they must fight a terrifying battle to save the future of the human race.'),
(340, '271110', 'en', 'https://image.tmdb.org/t/p/w500/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', 'Captain America: Civil War', '120.428', '2016-04-27', 7.4, '18797', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.'),
(341, '577922', 'en', 'https://image.tmdb.org/t/p/w500/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', 'Tenet', '132.599', '2020-08-22', 7.3, '6282', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.'),
(342, '337167', 'en', 'https://image.tmdb.org/t/p/w500/jjPJ4s3DWZZvI4vw8Xfi4Vqa1Q8.jpg', 'Fifty Shades Freed', '124.672', '2018-01-17', 6.7, '6563', '[\'Drama\', \'Romance\']', 'Believing they have left behind shadowy figures from their past, newlyweds Christian and Ana fully embrace an inextricable connection and shared life of luxury. But just as she steps into her role as Mrs. Grey and he relaxes into an unfamiliar stability, new threats could jeopardize their happy ending before it even begins.'),
(343, '793723', 'fr', 'https://image.tmdb.org/t/p/w500/dfkQkc55gvBHXmWptfax6l5JdK3.jpg', 'Sentinelle', '114.789', '2021-03-05', 5.9, '454', '[\'Thriller\', \'Action\', \'Drama\']', 'Transferred home after a traumatizing combat mission, a highly trained French soldier uses her lethal skills to hunt down the man who hurt her sister.'),
(344, '568160', 'ja', 'https://image.tmdb.org/t/p/w500/qgrk7r1fV4IjuoeiGS5HOhXNdLJ.jpg', '天気の子', '126.581', '2019-06-19', 8.1, '1228', '[\'Fantasy\', \'Animation\', \'Romance\', \'Drama\']', 'The summer of his high school freshman year, Hodaka runs away from his remote island home to Tokyo, and quickly finds himself pushed to his financial and personal limits. The weather is unusually gloomy and rainy every day, as if taking its cue from his life. After many days of solitude, he finally finds work as a freelance writer for a mysterious occult magazine. Then, one day, Hodaka meets Hina on a busy street corner. This bright and strong-willed girl possesses a strange and wonderful ability: the power to stop the rain and clear the sky.'),
(345, '593910', 'en', 'https://image.tmdb.org/t/p/w500/j91LJmcWo16CArFOoapsz84bwxb.jpg', 'Cinderella', '109.329', '2021-09-03', 6.7, '877', '[\'Fantasy\', \'Romance\', \'Comedy\']', 'Cinderella, an orphaned girl with an evil stepmother, has big dreams and with the help of her Fabulous Godmother, she perseveres to make them come true.'),
(346, '809', 'en', 'https://image.tmdb.org/t/p/w500/2yYP0PQjG8zVqturh1BAqu2Tixl.jpg', 'Shrek 2', '124.478', '2004-05-19', 7.1, '9344', '[\'Animation\', \'Family\', \'Comedy\', \'Fantasy\', \'Adventure\']', 'Shrek, Fiona and Donkey set off to Far, Far Away to meet Fiona\'s mother and father. But not everyone is happy. Shrek and the King find it hard to get along, and there\'s tension in the marriage. The fairy godmother discovers that Shrek has married Fiona instead of her Son Prince Charming and sets about destroying their marriage.'),
(347, '669659', 'en', 'https://image.tmdb.org/t/p/w500/7UQ01PyC4OCo9uFKn6EidomQybd.jpg', 'Best Sellers', '97.152', '2021-09-09', 6.4, '23', '[\'Drama\', \'Comedy\']', 'A cranky, retired author reluctantly embarks on a final book tour to help out a young publisher.'),
(348, '595280', 'es', 'https://image.tmdb.org/t/p/w500/i8aR3usDzjSCeJ78ttHxNDCaEhc.jpg', 'Distancia de rescate', '112.679', '2021-10-06', 6.1, '68', '[\'Horror\', \'Thriller\', \'Drama\']', 'A woman named Amanda lies stricken, far from home. A young boy named David questions her, trying to make her remember. She\'s not his mother, he\'s not her son. As her time is running out, he helps her unravel a powerful, haunting story of obsessive jealousy, an invisible danger, and the power of a mother\'s love for her child.'),
(349, '804435', 'en', 'https://image.tmdb.org/t/p/w500/AoWY1gkcNzabh229Icboa1Ff0BM.jpg', 'Vanquish', '128.132', '2021-04-16', 6, '165', '[\'Action\', \'Crime\', \'Thriller\']', 'Victoria is a young mother trying to put her dark past as a Russian drug courier behind her, but retired cop Damon forces Victoria to do his bidding by holding her daughter hostage. Now, Victoria must use guns, guts and a motorcycle to take out a series of violent gangsters—or she may never see her child again.'),
(350, '681019', 'pl', 'https://image.tmdb.org/t/p/w500/5vFCHFVLPcU4M8uNXM1ba9y83Iu.jpg', 'W lesie dziś nie zaśnie nikt', '115.017', '2020-03-13', 5, '379', '[\'Horror\', \'Thriller\']', 'Addicted to technology, a group of teens attends a rehabilitation camp in the forest, but a sinister force there intends to take them offline forever.'),
(351, '864388', 'tr', 'https://image.tmdb.org/t/p/w500/8j9iIwxFal1Nq8NY4MSLC6Y6bLE.jpg', 'Mickey\'s Tale of Two Witches', '177.282', '2021-10-07', 7, '12', '[\'Animation\']', 'On Halloween, Mickey tells a tale of two witches-in-training, Minnie and Daisy, who must pass four tests to graduate from the With Academy in Happy Haunt Hills.'),
(352, '580532', 'en', 'https://image.tmdb.org/t/p/w500/15e2VcMTtk3pqgGlHWxisvygFAw.jpg', 'Crisis', '101.411', '2021-02-26', 6.4, '153', '[\'Thriller\', \'Crime\', \'Drama\']', 'Three stories about the world of opioids collide: a drug trafficker arranges a multi-cartel Fentanyl smuggling operation between Canada and the U.S., an architect recovering from an OxyContin addiction tracks down the truth behind her son\'s involvement with narcotics, and a university professor battles unexpected revelations about his research employer, a drug company with deep government influence bringing a new \"non-addictive\" painkiller to market.'),
(353, '7182', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'Venom', '106.563', '2005-09-16', 5.5, '217', '[\'Horror\', \'Thriller\']', 'A group of teenagers fear for their lives in the swamps of Louisiana, chased by Mr. Jangles, a man possessed by 13 evil souls, and now relentless in his pursuit of new victims.'),
(354, '17654', 'en', 'https://image.tmdb.org/t/p/w500/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', 'District 9', '111.488', '2009-08-05', 7.4, '7461', '[\'Science Fiction\']', 'Thirty years ago, aliens arrive on Earth. Not to conquer or give aid, but to find refuge from their dying planet. Separated from humans in a South African area called District 9, the aliens are managed by Multi-National United, which is unconcerned with the aliens\' welfare but will do anything to master their advanced technology. When a company field agent contracts a mysterious virus that begins to alter his DNA, there is only one place he can hide: District 9.'),
(355, '18240', 'en', 'https://image.tmdb.org/t/p/w500/6stnAm1wSek8ZrislwK4xGTyCnt.jpg', 'The Proposal', '115.539', '2009-06-01', 7.1, '5084', '[\'Comedy\', \'Romance\', \'Drama\']', 'When she learns she\'s in danger of losing her visa status and being deported, overbearing book editor Margaret Tate forces her put-upon assistant, Andrew Paxton, to marry her.'),
(356, '260346', 'en', 'https://image.tmdb.org/t/p/w500/vzvMXMypMq7ieDofKThsxjHj9hn.jpg', 'Taken 3', '128.222', '2014-12-16', 6.2, '4645', '[\'Thriller\', \'Action\']', 'Ex-government operative Bryan Mills finds his life is shattered when he\'s falsely accused of a murder that hits close to home. As he\'s pursued by a savvy police inspector, Mills employs his particular set of skills to track the real killer and exact his unique brand of justice.'),
(357, '649409', 'en', 'https://image.tmdb.org/t/p/w500/kARdPEc4b32GQlHmJXMhGOCplEA.jpg', 'No Sudden Move', '91.432', '2021-06-24', 6.5, '278', '[\'Crime\', \'Drama\', \'Mystery\']', 'A group of criminals are brought together under mysterious circumstances and have to work together to uncover what\'s really going on when their simple job goes completely sideways.'),
(358, '28510', 'en', 'https://image.tmdb.org/t/p/w500/hYLzRwCcCyTVKGBRAiHEW7NOEni.jpg', 'Universal Soldier: Regeneration', '113.026', '2009-10-01', 5.6, '319', '[\'Adventure\', \'Action\', \'Science Fiction\', \'Thriller\']', 'When terrorists threaten nuclear catastrophe at Chernobyl, the world\'s only hope is to reactivate decommissioned Universal Soldier Luc Deveraux. Rearmed and reprogrammed, Deveraux must take on his nemesis from the original Universal Soldier and a next-generation \"UniSol\" that seems almost unstoppable.'),
(359, '335988', 'en', 'https://image.tmdb.org/t/p/w500/s5HQf2Gb3lIO2cRcFwNL9sn1o1o.jpg', 'Transformers: The Last Knight', '114.472', '2017-06-16', 6.1, '4704', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\']', 'Autobots and Decepticons are at war, with humans on the sidelines. Optimus Prime is gone. The key to saving our future lies buried in the secrets of the past, in the hidden history of Transformers on Earth.'),
(360, '9637', 'en', 'https://image.tmdb.org/t/p/w500/mTAiBJGg8mqEfnYHHbi37ZoRSZm.jpg', 'Scooby-Doo', '120.75', '2002-06-14', 6, '3337', '[\'Mystery\', \'Adventure\', \'Comedy\']', 'The Mystery Inc. gang have gone their separate ways and have been apart for two years, until they each receive an invitation to Spooky Island. Not knowing that the others have also been invited, they show up and discover an amusement park that affects young visitors in very strange ways.'),
(361, '645710', 'en', 'https://image.tmdb.org/t/p/w500/8Y4XOIWhpOvSOEn8XrxbkH9yAXO.jpg', 'The Voyeurs', '95.844', '2021-08-25', 6.9, '268', '[\'Thriller\']', 'A young couple, find themselves becoming interested in the sex life of their neighbors across the street. What starts as an innocent curiosity turns into an unhealthy obsession.'),
(362, '337339', 'en', 'https://image.tmdb.org/t/p/w500/dImWM7GJqryWJO9LHa3XQ8DD5NH.jpg', 'The Fate of the Furious', '100.659', '2017-04-12', 6.9, '8595', '[\'Action\', \'Crime\', \'Thriller\']', 'When a mysterious woman seduces Dom into the world of crime and a betrayal of those closest to him, the crew face trials that will test them as never before.'),
(363, '7445', 'en', 'https://image.tmdb.org/t/p/w500/skHqceAFYee0JZuYd9MVk2IQggi.jpg', 'Brothers', '86.645', '2009-01-22', 7, '1897', '[\'Drama\', \'Thriller\', \'War\']', 'When his helicopter goes down during his fourth tour of duty in Afghanistan, Marine Sam Cahill is presumed dead. Back home, brother Tommy  steps in to look over Sam’s wife, Grace, and two children. Sam’s surprise homecoming triggers domestic mayhem.'),
(364, '45682', 'zh', 'https://m.media-amazon.com/images/M/MV5BZmRkZTgzY2UtZTg4Zi00ODE2LTkyNzMtOGNhMjI5ZjU1MjhiXkEyXkFqcGc@._V1_QL75_UY281_CR5,0,190,281_.jpg', 'Xun zhao Cheng Long', '118.653', '2009-07-03', 4.4, '46', '[\'Action\', \'Comedy\', \'Family\']', 'Jackie Chan is the undefeated Kung Fu Master who dishes out the action in traditional Jackie Chan style. When a young boy sets out to learn how to fight from the Master himself, he not only witnesses some spectacular fights, but learns some important life lessons along the way.'),
(365, '863', 'en', 'https://image.tmdb.org/t/p/w500/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', 'Toy Story 2', '125.459', '1999-10-30', 7.6, '11000', '[\'Animation\', \'Comedy\', \'Family\']', 'Andy heads off to Cowboy Camp, leaving his toys to their own devices. Things shift into high gear when an obsessive toy collector named Al McWhiggen, owner of Al\'s Toy Barn kidnaps Woody. Andy\'s toys mount a daring rescue mission, Buzz Lightyear meets his match and Woody has to decide where he and his heart truly belong.'),
(366, '425', 'en', 'https://image.tmdb.org/t/p/w500/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg', 'Ice Age', '126.211', '2002-03-10', 7.3, '10489', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'With the impending ice age almost upon them, a mismatched trio of prehistoric critters – Manny the woolly mammoth, Diego the saber-toothed tiger and Sid the giant sloth – find an orphaned infant and decide to return it to its human parents. Along the way, the unlikely allies become friends but, when enemies attack, their quest takes on far nobler aims.'),
(367, '378064', 'ja', 'https://image.tmdb.org/t/p/w500/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg', '映画 聲の形', '132.05', '2016-09-17', 8.4, '2614', '[\'Animation\', \'Drama\']', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?'),
(368, '284052', 'en', 'https://image.tmdb.org/t/p/w500/xf8PbyQcR5ucXErmZNzdKR0s8ya.jpg', 'Doctor Strange', '115.596', '2016-10-25', 7.4, '17709', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'After his career is destroyed, a brilliant but arrogant surgeon gets a new lease on life when a sorcerer takes him under her wing and trains him to defend the world against evil.'),
(369, '381749', 'it', 'https://image.tmdb.org/t/p/w500/rfH4si9f40mgCnAGvEbN8fVeN1s.jpg', 'Porno & Libertà', '122.833', '2016-06-24', 5.4, '63', '[\'Documentary\']', 'Italy, 1970. An increasing legion of harmless warriors begins a peaceful struggle for sexual freedom through pornography, shaking and shocking religious authorities and conservative political institutions. They are ironic, happy, crazy. They are dreamers, defenders of definitive communion between body and soul. But they were censored and humiliated. They were mistreated and arrested for demanding loud a new cultural renaissance.'),
(370, '307081', 'en', 'https://image.tmdb.org/t/p/w500/kSQ49Fi3NVTqGGXILmxV2T2pdkG.jpg', 'Southpaw', '105.745', '2015-03-24', 7.4, '4516', '[\'Action\', \'Drama\']', 'Billy \"The Great\" Hope, the reigning junior middleweight boxing champion, has an impressive career, a loving wife and daughter, and a lavish lifestyle. However, when tragedy strikes, Billy hits rock bottom, losing his family, his house and his manager. He soon finds an unlikely savior in Tick Willis, a former fighter who trains the city\'s toughest amateur boxers. With his future on the line, Hope fights to reclaim the trust of those he loves the most.'),
(371, '778657', 'es', 'https://image.tmdb.org/t/p/w500/tgWFiNqRMntJKi2PDbq7dig3qs1.jpg', 'Destello Bravío', '120.253', '2021-06-18', 6.1, '7', '[\'Drama\']', 'The women of a small rural town, suspended in time and whipped by depopulation, live between the apathy of their daily day where nothing extraordinary happens and a deep desire for liberating experiences that makes them rediscover the place where they believe they were happy or dreamed of being happy.'),
(372, '316727', 'en', 'https://image.tmdb.org/t/p/w500/gg7tlp45xqGWMra0sqQVPvybje2.jpg', 'The Purge: Election Year', '106.161', '2016-06-29', 6.4, '4261', '[\'Action\', \'Horror\', \'Thriller\']', 'Two years after choosing not to kill the man who killed his son, former police sergeant Leo Barnes has become head of security for Senator Charlene Roan, the front runner in the next Presidential election due to her vow to eliminate the Purge. On the night of what should be the final Purge, a betrayal from within the government forces Barnes and Roan out onto the street where they must fight to survive the night.'),
(373, '49529', 'en', 'https://image.tmdb.org/t/p/w500/lCxz1Yus07QCQQCb6I0Dr3Lmqpx.jpg', 'John Carter', '115.257', '2012-03-07', 6.2, '4474', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'John Carter is a war-weary, former military captain who\'s inexplicably transported to the mysterious and exotic planet of Barsoom (Mars) and reluctantly becomes embroiled in an epic conflict. It\'s a world on the brink of collapse, and Carter rediscovers his humanity when he realizes the survival of Barsoom and its people rests in his hands.'),
(374, '57165', 'en', 'https://image.tmdb.org/t/p/w500/b9n2R3xZWQ8MVZgndQoV34stS0h.jpg', 'Wrath of the Titans', '105.074', '2012-03-28', 5.7, '3377', '[\'Fantasy\', \'Adventure\']', 'Perseus tries to live a quieter life as a village fisherman while - dangerously weakened by humanity\'s lack of devotion - the gods are losing control of the long-imprisoned Titans and their ferocious leader, Kronos.'),
(375, '643586', 'en', 'https://image.tmdb.org/t/p/w500/keEnkeAvifw8NSEC4f6WsqeLJgF.jpg', 'Willy\'s Wonderland', '108.006', '2021-02-12', 6.5, '385', '[\'Action\', \'Horror\', \'Comedy\']', 'When his car breaks down, a quiet loner agrees to clean an abandoned family fun center in exchange for repairs. He soon finds himself waging war against possessed animatronic mascots while trapped inside Willy\'s Wonderland.'),
(376, '857910', 'es', 'https://image.tmdb.org/t/p/w500/Aq0a9qdBVgWKVCy2OlFdZOCj3Iw.jpg', 'Lokillo: nada es igual', '97.682', '2021-08-12', 7.8, '15', '[\'Comedy\']', 'Through songs and puns, comedian Lokillo Florez hilariously reviews how Latin Americans have adjusted to a new world where no-hugging policies prevail.'),
(377, '812456', 'en', 'https://image.tmdb.org/t/p/w500/dAmBnfCRBwy5S6n3Qb6aQKJYYRO.jpg', 'Barbie & Chelsea: The Lost Birthday', '106.542', '2021-05-14', 7.2, '58', '[\'Animation\']', 'Enjoy high-sea thrills as Barbie, Chelsea and the rest of the Roberts family set sail on an adventure cruise.  \"Barbie & Chelsea The Lost Birthday\" tells the story of Chelsea, Barbie’s precocious youngest sister, and the rest of the Roberts family as they set sail on an adventure cruise for her seventh birthday. When they cross the International Date Line, Chelsea discovers her actual birthday has been lost and she embarks on a fantastical journey through an enchanted jungle island in order to save it.'),
(378, '454626', 'en', 'https://image.tmdb.org/t/p/w500/aQvJ5WPzZgYVDrxLX4R6cLJCEaQ.jpg', 'Sonic the Hedgehog', '124.308', '2020-02-12', 7.4, '7240', '[\'Action\', \'Science Fiction\', \'Comedy\', \'Family\']', 'Based on the global blockbuster videogame franchise from Sega, Sonic the Hedgehog tells the story of the world’s speediest hedgehog as he embraces his new home on Earth. In this live-action adventure comedy, Sonic and his new best friend team up to defend the planet from the evil genius Dr. Robotnik and his plans for world domination.'),
(379, '177572', 'en', 'https://image.tmdb.org/t/p/w500/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', 'Big Hero 6', '109.657', '2014-10-24', 7.8, '13112', '[\'Adventure\', \'Family\', \'Animation\', \'Action\', \'Comedy\']', 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.'),
(380, '167032', 'en', 'https://image.tmdb.org/t/p/w500/x9DzkDWp8O82Wzxk6otuD9bce9a.jpg', 'Curse of Chucky', '96.24', '2013-10-04', 5.8, '1127', '[\'Horror\', \'Thriller\']', 'After the passing of her mother, a young woman in a wheelchair since birth, is forced to deal with her sister, brother-in-law, niece and their nanny as they say their goodbyes to mother. When people start turning up dead, Nica discovers the culprit might be a strange doll she received a few days earlier.'),
(381, '801335', 'en', 'https://image.tmdb.org/t/p/w500/tPP9n6r5QrIKPnshnJqE7klptj2.jpg', 'Girl in the Basement', '113.334', '2021-02-27', 8.1, '268', '[\'Crime\', \'Thriller\']', 'Sara is a teen girl who is looking forward to her 18th birthday to move away from her controlling father Don. But before she could even blow out the candles, Don imprisons her in the basement of their home.'),
(382, '383498', 'en', 'https://image.tmdb.org/t/p/w500/to0spRl1CMDvyUbOnbb4fTk3VAd.jpg', 'Deadpool 2', '111.516', '2018-05-10', 7.5, '13893', '[\'Action\', \'Comedy\', \'Adventure\']', 'Wisecracking mercenary Deadpool battles the evil and powerful Cable and other bad guys to save a boy\'s life.'),
(383, '348893', 'en', 'https://image.tmdb.org/t/p/w500/7QGdIJWWTkPhVjpQ0zA6z69khod.jpg', 'Boyka: Undisputed IV', '116.227', '2016-08-01', 7, '930', '[\'Action\', \'Drama\']', 'In the fourth installment of the fighting franchise, Boyka is shooting for the big leagues when an accidental death in the ring makes him question everything he stands for. When he finds out the wife of the man he accidentally killed is in trouble, Boyka offers to fight in a series of impossible battles to free her from a life of servitude'),
(384, '617708', 'es', 'https://image.tmdb.org/t/p/w500/vBiqoYfDIWKKzZTiQScqgCO09UD.jpg', 'La Llorona', '90.234', '2020-01-22', 6.6, '223', '[\'Thriller\', \'Horror\', \'Drama\']', 'Accused of the genocide of Mayan people, retired general Enrique is trapped in his mansion by massive protests. Abandoned by his staff, the indignant old man and his family must face the devastating truth of his actions and the growing sense that a wrathful supernatural force is targeting them for his crimes.'),
(385, '44943', 'en', 'https://image.tmdb.org/t/p/w500/jloyGeVYZSxM9zsLFvVOWuj2ey4.jpg', 'Battle: Los Angeles', '115.452', '2011-03-08', 5.7, '2745', '[\'Science Fiction\', \'Action\']', 'When once distant UFOs become a terrifying threat attacking Earth, a Marine staff sergeant and his team take it upon themselves to face the enemy and protect what remains of the planet.'),
(386, '8871', 'en', 'https://image.tmdb.org/t/p/w500/1WZbbPApEivA421gCOluuzMMKCk.jpg', 'How the Grinch Stole Christmas', '122.213', '2000-11-17', 6.7, '5531', '[\'Family\', \'Comedy\', \'Fantasy\']', 'Inside a snowflake exists the magical land of Whoville. In Whoville, live the Whos, an almost mutated sort of Munchkin-like people. All the Whos love Christmas, yet just outside of their beloved Whoville lives the Grinch. The Grinch is a nasty creature that hates Christmas, and plots to steal it away from the Whos, whom he equally abhors. Yet a small child, Cindy Lou Who, decides to try befriending the Grinch.'),
(387, '42194', 'en', 'https://image.tmdb.org/t/p/w500/1xO2LirDZstkqZic1FwfK6GJIHH.jpg', 'TEKKEN', '101.66', '2010-03-20', 5.4, '512', '[\'Crime\', \'Drama\', \'Action\', \'Thriller\', \'Science Fiction\']', 'In the year of 2039, after World Wars destroy much of the civilization as we know it, territories are no longer run by governments, but by corporations; the mightiest of which is the Mishima Zaibatsu. In order to placate the seething masses of this dystopia, Mishima sponsors Tekken, a tournament in which fighters battle until only one is left standing.'),
(388, '131631', 'en', 'https://image.tmdb.org/t/p/w500/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg', 'The Hunger Games: Mockingjay - Part 1', '105.522', '2014-11-19', 6.8, '13034', '[\'Science Fiction\', \'Adventure\', \'Thriller\']', 'Katniss Everdeen reluctantly becomes the symbol of a mass rebellion against the autocratic Capitol.'),
(389, '778552', 'en', 'https://image.tmdb.org/t/p/w500/bkUxZ9sFE7tn0NPRILqZVEPZRF9.jpg', 'The Penitent Thief', '115.977', '2021-02-25', 4.8, '4', '[\'Drama\']', 'The story of the two unnamed men who were crucified alongside Jesus and how they came to be beside him on the cross that fateful day. Dismas and his brother Jotham, along with Gestas, another young man who will share their fate, suffer tragedy and injustice at the hands of a band of thieves and a ruthless Roman centurion. Theirs is a story of survival against the odds, but they cannot outrun their destiny.'),
(390, '49530', 'en', 'https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', 'In Time', '99.952', '2011-10-27', 6.9, '9049', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'In the not-too-distant future the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest try to negotiate for their immortality. A poor young man who comes into a fortune of time, though too late to help his mother from dying. He ends up on the run from a corrupt police force known as \'time keepers\'.'),
(391, '581392', 'ko', 'https://image.tmdb.org/t/p/w500/eeqvAzCccAZOhU3RfbvHB3s44S6.jpg', '반도', '112.928', '2020-07-15', 6.9, '1714', '[\'Action\', \'Horror\', \'Thriller\']', 'A soldier and his team battle hordes of post-apocalyptic zombies in the wastelands of the Korean Peninsula.'),
(392, '786300', 'en', 'https://image.tmdb.org/t/p/w500/rRfcH0jg9X8czKJhXCnny45NSWt.jpg', 'Tentacles', '93.795', '2021-02-12', 6.2, '83', '[\'Horror\', \'Romance\']', 'A young Los Angeles couple Tara and Sam fall head over heels into a new romance, entwining their lives—until their intimacy transforms into something terrifying.'),
(393, '442249', 'en', 'https://image.tmdb.org/t/p/w500/litjsBoiydO6JlO70uOX4N3WnNL.jpg', 'The First Purge', '106.14', '2018-07-04', 6, '3159', '[\'Action\', \'Thriller\', \'Horror\']', 'To push the crime rate below one percent for the rest of the year, the New Founding Fathers of America test a sociological theory that vents aggression for one night in one isolated community. But when the violence of oppressors meets the rage of the others, the contagion will explode from the trial-city borders and spread across the nation.'),
(394, '254128', 'en', 'https://image.tmdb.org/t/p/w500/2Gfjn962aaFSD6eST6QU3oLDZTo.jpg', 'San Andreas', '109.152', '2015-05-27', 6.2, '6870', '[\'Action\', \'Drama\', \'Thriller\']', 'In the aftermath of a massive earthquake in California, a rescue-chopper pilot makes a dangerous journey across the state in order to rescue his estranged daughter.'),
(395, '45243', 'en', 'https://image.tmdb.org/t/p/w500/cKZu0Fdkj7dmwbfMpgDqVVCkLJQ.jpg', 'The Hangover Part II', '100.411', '2011-05-25', 6.4, '8490', '[\'Comedy\']', 'The Hangover crew heads to Thailand for Stu\'s wedding. After the disaster of a bachelor party in Las Vegas last year, Stu is playing it safe with a mellow pre-wedding brunch. However, nothing goes as planned and Bangkok is the perfect setting for another adventure with the rowdy group.'),
(396, '439079', 'en', 'https://image.tmdb.org/t/p/w500/sFC1ElvoKGdHJIWRpNB3xWJ9lJA.jpg', 'The Nun', '96.872', '2018-09-05', 5.8, '4901', '[\'Horror\', \'Mystery\', \'Thriller\']', 'When a young nun at a cloistered abbey in Romania takes her own life, a priest with a haunted past and a novitiate on the threshold of her final vows are sent by the Vatican to investigate. Together they uncover the order’s unholy secret. Risking not only their lives but their faith and their very souls, they confront a malevolent force in the form of the same demonic nun that first terrorized audiences in “The Conjuring 2” as the abbey becomes a horrific battleground between the living and the damned.'),
(397, '1726', 'en', 'https://image.tmdb.org/t/p/w500/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', 'Iron Man', '98.686', '2008-04-30', 7.6, '21554', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.'),
(398, '76492', 'en', 'https://image.tmdb.org/t/p/w500/eJGvzGrsfe2sqTUPv5IwLWXjVuR.jpg', 'Hotel Transylvania', '101.384', '2012-09-20', 6.9, '6959', '[\'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'Welcome to Hotel Transylvania, Dracula\'s lavish five-stake resort, where monsters and their families can live it up and no humans are allowed. One special weekend, Dracula has invited all his best friends to celebrate his beloved daughter Mavis\'s 118th birthday. For Dracula catering to all of these legendary monsters is no problem but the party really starts when one ordinary guy stumbles into the hotel and changes everything!'),
(399, '26123', 'en', 'https://image.tmdb.org/t/p/w500/hwP0GEP0zy8ar965Xaht19SmMd3.jpg', 'American Pie Presents: The Book of Love', '117.752', '2009-06-18', 5.3, '1389', '[\'Comedy\']', 'Ten years after the first American Pie movie, three new hapless virgins discover the Bible hidden in the school library at East Great Falls High. Unfortunately for them, the book is ruined, and with incomplete advice, the Bible leads them on a hilarious journey to lose their virginity.'),
(400, '888917', 'fr', 'https://image.tmdb.org/t/p/w500/tPcrO8DJAP0lPeoTiQHRsNBD2EC.jpg', 'Les Rois de l\'arnaque', '115.384', '2021-11-03', 6, '4', '[\'Documentary\']', 'This documentary traces the rise and crash of scammers who conned the EU carbon quota system and pocketed millions before turning on one another.'),
(401, '495764', 'en', 'https://image.tmdb.org/t/p/w500/h4VB6m0RwcicVEZvzftYZyKXs6K.jpg', 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', '109.157', '2020-02-05', 7, '8238', '[\'Action\', \'Crime\']', 'Harley Quinn joins forces with a singer, an assassin and a police detective to help a young girl who had a hit placed on her after she stole a rare diamond from a crime lord.'),
(402, '44251', 'ja', 'https://image.tmdb.org/t/p/w500/Apnw8FWoPOIsu14d5dvaNZzFSJE.jpg', 'ドラゴンボールＺ 危険なふたり！超戦士はねむれない', '111.569', '1994-03-12', 6.7, '475', '[\'Animation\', \'Action\', \'Science Fiction\']', 'A Saiyan Space pod crash-lands on Earth out of which a wounded Saiyan crawls: Broly, the Legendary Super Saiyan. The wounded Broly shouts out in frustration and turns into normal form. The place soon freezes, trapping him in it and he falls into a coma.'),
(403, '398818', 'en', 'https://image.tmdb.org/t/p/w500/mZ4gBdfkhP9tvLH1DO4m4HYtiyi.jpg', 'Call Me by Your Name', '117.179', '2017-09-01', 8.3, '9589', '[\'Romance\', \'Drama\']', 'In 1980s Italy, a relationship begins between seventeen-year-old teenage Elio and the older adult man hired as his father\'s research assistant.'),
(404, '520946', 'en', 'https://image.tmdb.org/t/p/w500/2VrvxK4yxNCU6KVgo5TADJeBEQu.jpg', '100% Wolf', '109.35', '2020-06-26', 5.9, '198', '[\'Animation\', \'Family\', \'Fantasy\']', 'Freddy Lupin, heir to a proud family line of werewolves, is in for a shock when on his 14th birthday his first \'warfing\' goes awry, turning him into a ferocious poodle. The pack elders give Freddy until the next moonrise to prove he has the heart of a wolf, or risk being cast out forever. With the help of an unlikely ally in a streetwise stray named Batty, Freddy must prove he\'s 100% Wolf.'),
(405, '2062', 'en', 'https://image.tmdb.org/t/p/w500/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', 'Ratatouille', '107.165', '2007-06-28', 7.8, '13176', '[\'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'Remy, a resident of Paris, appreciates good food and has quite a sophisticated palate. He would love to become a chef so he can create and enjoy culinary masterpieces to his heart\'s delight. The only problem is, Remy is a rat. When he winds up in the sewer beneath one of Paris\' finest restaurants, the rodent gourmet finds himself ideally placed to realize his dream.'),
(406, '366170', 'ja', 'https://image.tmdb.org/t/p/w500/ti0CRprP9iSg9IDadTZ3TFnuczS.jpg', '遊☆戯☆王 THE DARK SIDE OF DIMENSIONS', '106.812', '2016-04-23', 7.5, '245', '[\'Adventure\', \'Animation\']', 'Yugi and Kaiba have a special duel that transcends dimensions.'),
(407, '632632', 'ja', 'https://image.tmdb.org/t/p/w500/pegCub2zdYD5As43AOmGsIctuKc.jpg', '映画 ギヴン', '115.335', '2020-08-22', 8.5, '263', '[\'Animation\', \'Drama\', \'Music\', \'Romance\']', 'The film centers on the love relationship among the band\'s bassist Haruki Nakayama, drummer Akihiko Kaji, and Akihiko\'s roommate and ex-boyfriend Ugetsu Murata.'),
(408, '109445', 'en', 'https://image.tmdb.org/t/p/w500/kgwjIb2JDHRhNk13lmSxiClFjVk.jpg', 'Frozen', '112.116', '2013-11-20', 7.3, '13633', '[\'Animation\', \'Adventure\', \'Family\']', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She\'s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.'),
(409, '14849', 'en', 'https://image.tmdb.org/t/p/w500/ekzGiwleJbx0ei1R3s0ylowFKT9.jpg', 'Dead Like Me: Life After Death', '96.973', '2009-02-17', 6.2, '150', '[\'Drama\', \'Fantasy\', \'Comedy\']', 'When George and her colleagues get a new boss whose focus is on moving souls quickly and enjoying life without consequences, the team begins to break the strict reaper rules. While her friends fall victim to their desires for money, success, and fame, George breaks another rule by revealing her true identity to her living family.'),
(410, '604360', 'ko', 'https://image.tmdb.org/t/p/w500/kscflbI5A6KVlMg2foAWnt8CJ5Y.jpg', '제8일의 밤', '101.97', '2021-07-02', 6.1, '54', '[\'Mystery\', \'Thriller\', \'Horror\']', 'With prayer beads in one hand and an ax in the other, a monk hunts down a millennia-old spirit that\'s possessing humans and unleashing hell on Earth.'),
(411, '714968', 'en', 'https://image.tmdb.org/t/p/w500/iHCcn6100h2HMWx83OdQtZXuhSR.jpg', 'Plan A', '158.725', '2021-09-03', 4.3, '6', '[\'Thriller\']', 'Germany 1945, Max, a Jewish Holocaust survivor, meets a radical group of Jewish resistance fighters, who, like him, lost all hope for their future after they were robbed of their existence and their entire families were killed by the Nazis. They dream of retaliation on an epic scale for the Jewish people. An eye for an eye, a tooth for a tooth. Max starts identifying with the group\'s monstrous plans...'),
(412, '847981', 'de', 'https://image.tmdb.org/t/p/w500/53jsv5TASLwOqsJNsUNp4RPPq2l.jpg', 'Schwarze Insel', '93.971', '2021-08-17', 6.2, '109', '[\'Thriller\']', 'The dark secrets of a seemingly peaceful island threaten to swallow up an orphaned student when he grows close to a mysterious new teacher.'),
(413, '617653', 'en', 'https://image.tmdb.org/t/p/w500/zjrJE0fpzPvX8saJXj8VNfcjBoU.jpg', 'The Last Duel', '111.097', '2021-10-13', 7.7, '394', '[\'Action\', \'Drama\', \'History\', \'Thriller\']', 'King Charles VI declares that Knight Jean de Carrouges settle his dispute with his squire by challenging him to a duel.'),
(414, '38055', 'en', 'https://image.tmdb.org/t/p/w500/uZ9ytt3sPTx62XTfN56ILSuYWRe.jpg', 'Megamind', '105.316', '2010-10-28', 6.9, '5294', '[\'Animation\', \'Action\', \'Comedy\', \'Family\', \'Science Fiction\']', 'Bumbling supervillain Megamind finally defeats his nemesis, the superhero Metro Man. But without a hero, he loses all purpose and must find new meaning to his life.'),
(415, '49051', 'en', 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', 'The Hobbit: An Unexpected Journey', '107.123', '2012-11-26', 7.3, '15327', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.'),
(416, '736069', 'en', 'https://image.tmdb.org/t/p/w500/tOUJvmdjppmPYZOoykWmerSspMT.jpg', 'Justice Society: World War II', '98.108', '2021-04-27', 7.8, '338', '[\'Animation\', \'War\', \'Science Fiction\']', 'When the Flash finds himself dropped into the middle of World War II, he joins forces with Wonder Woman and her top-secret team known as the Justice Society of America.'),
(417, '14836', 'en', 'https://image.tmdb.org/t/p/w500/4jeFXQYytChdZYE9JYO7Un87IlW.jpg', 'Coraline', '111.854', '2009-02-05', 7.8, '5356', '[\'Animation\', \'Family\', \'Fantasy\']', 'When Coraline moves to an old house, she feels bored and neglected by her parents. She finds a hidden door with a bricked up passage. During the night, she crosses the passage and finds a parallel world where everybody has buttons instead of eyes, with caring parents and all her dreams coming true. When the Other Mother invites Coraline to stay in her world forever, the girl refuses and finds that the alternate reality where she is trapped is only a trick to lure her.'),
(418, '785539', 'en', 'https://image.tmdb.org/t/p/w500/7w4gX4zRlONqThjhmjdxw93FAXt.jpg', 'Resort to Love', '100.284', '2021-07-29', 7.4, '263', '[\'Romance\', \'Comedy\']', 'Aspiring pop star Erica ends up as the entertainment at her ex-fiancé’s wedding after reluctantly taking a gig at a luxurious island resort while in the wake of a music career meltdown.'),
(419, '4258', 'en', 'https://image.tmdb.org/t/p/w500/vBqLLxE6GaAPhO6v9EFvFbLZ7Ap.jpg', 'Scary Movie 5', '100.035', '2013-04-11', 4.8, '2193', '[\'Comedy\']', 'Home with their newly-formed family, happy parents Dan and Jody are haunted by sinister, paranormal activities. Determined to expel the insidious force, they install security cameras and discover their family is being stalked by an evil dead demon.'),
(420, '283995', 'en', 'https://image.tmdb.org/t/p/w500/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', 'Guardians of the Galaxy Vol. 2', '92.961', '2017-04-19', 7.6, '17344', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'The Guardians must fight to keep their newfound family together as they unravel the mysteries of Peter Quill\'s true parentage.'),
(421, '805051', 'en', 'https://image.tmdb.org/t/p/w500/w7PJ7fBEYOuaAMKfYa4zmw45v3N.jpg', 'Smelliville', '107.299', '2021-01-01', 7.6, '32', '[\'Animation\', \'Drama\', \'Adventure\', \'Family\']', 'The Oggly family arrive at the municipal rubbish dump of Smelliville and must look for a new home, but they never feel really welcome anywhere. They stink and are for most humans just a tad too oggly. When Firebottom, the family dragon, crash-lands on the run-down rubbish tip of the small town of Smelliville, the Ogglies at once feel at home. And it\'s here they want to stay.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(422, '324552', 'en', 'https://image.tmdb.org/t/p/w500/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', 'John Wick: Chapter 2', '109.503', '2017-02-08', 7.3, '9618', '[\'Thriller\', \'Action\', \'Crime\']', 'John Wick is forced out of retirement by a former associate looking to seize control of a shadowy international assassins’ guild. Bound by a blood oath to aid him, Wick travels to Rome and does battle against some of the world’s most dangerous killers.'),
(423, '689249', 'es', 'https://image.tmdb.org/t/p/w500/AboUXTrDWEi0PuZUqaft0iwBTm7.jpg', 'La Casa de Papel: el fenómeno', '107.516', '2020-04-03', 7.6, '843', '[\'Documentary\']', 'A documentary on why \'Money Heist\' sparked a wave of enthusiasm around the world for a lovable group of thieves and their professor.'),
(424, '595172', 'en', 'https://image.tmdb.org/t/p/w500/vtfsNxAsDHElFvYHUc9Khwqg17Y.jpg', 'The Pilgrim\'s Progress', '90.879', '2019-04-18', 7.9, '55', '[\'Animation\', \'Adventure\']', 'An epic journey, faithfully adapted to modern-day. Christian faces distractions, challenges, and perils at every turn of the way. But ends victorious, with helpful guides, as he stays on the narrow path to the distant Celestial City.'),
(425, '68721', 'en', 'https://image.tmdb.org/t/p/w500/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', 'Iron Man 3', '109.815', '2013-04-18', 6.9, '18524', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'When Tony Stark\'s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.'),
(426, '11186', 'en', 'https://image.tmdb.org/t/p/w500/2tPQbPQeHEYAGoXFSW61IWNmoce.jpg', 'Child\'s Play 2', '109.348', '1990-11-09', 6.2, '1244', '[\'Horror\', \'Thriller\']', 'When Andy\'s mother is admitted to a psychiatric hospital, the young boy is placed in foster care, and Chucky, determined to claim Andy\'s soul, is not far behind.'),
(427, '27576', 'en', 'https://image.tmdb.org/t/p/w500/kqeIJG7VjwkcTR26QHg8D01x8yI.jpg', 'Salt', '111.486', '2010-07-21', 6.4, '4388', '[\'Action\', \'Mystery\', \'Thriller\']', 'As a CIA officer, Evelyn Salt swore an oath to duty, honor and country. Her loyalty will be tested when a defector accuses her of being a Russian spy. Salt goes on the run, using all her skills and years of experience as a covert operative to elude capture. Salt\'s efforts to prove her innocence only serve to cast doubt on her motives, as the hunt to uncover the truth behind her identity continues and the question remains: \"Who is Salt?\"'),
(428, '34433', 'ja', 'https://image.tmdb.org/t/p/w500/6iO8TJCyLI4BiPYOvdwzPV2bhoV.jpg', 'ドラゴンボールＺ 燃え尽きろ!!熱戦・烈戦・超激戦', '112.958', '1993-03-06', 7.2, '609', '[\'Animation\', \'Science Fiction\', \'Action\']', 'While the Saiyan Paragus persuades Vegeta to rule a new planet, King Kai alerts Goku of the South Galaxy\'s destruction by an unknown Super Saiyan.'),
(429, '9820', 'en', 'https://image.tmdb.org/t/p/w500/dNqgjqxHIdfsQRQL5XTujNfX9pj.jpg', 'The Parent Trap', '108.251', '1998-07-28', 7.1, '3061', '[\'Comedy\', \'Family\']', 'Hallie Parker and Annie James are identical twins separated at a young age because of their parents\' divorce. Unknowingly to their parents, the girls are sent to the same summer camp where they meet, discover the truth about themselves, and then plot with each other to switch places.'),
(430, '55846', 'en', 'https://image.tmdb.org/t/p/w500/qjqmhhc7uLub22mhu4V6DjOBwXM.jpg', 'Blitz', '103.325', '2011-05-20', 6.1, '1211', '[\'Crime\', \'Action\', \'Thriller\']', 'A tough cop is dispatched to take down a serial killer who has been targeting police officers.'),
(431, '420809', 'en', 'https://image.tmdb.org/t/p/w500/vloNTScJ3w7jwNwtNGoG8DbTThv.jpg', 'Maleficent: Mistress of Evil', '86.477', '2019-10-16', 7.4, '4730', '[\'Family\', \'Fantasy\', \'Adventure\']', 'Maleficent and her goddaughter Aurora begin to question the complex family ties that bind them as they are pulled in different directions by impending nuptials, unexpected allies, and dark new forces at play.'),
(432, '615678', 'en', 'https://image.tmdb.org/t/p/w500/3mKMWP5OokB7QpcOMA1yl8BXFAF.jpg', 'Thunder Force', '98.333', '2021-04-09', 5.7, '826', '[\'Action\', \'Adventure\', \'Comedy\']', 'In a world where supervillains are commonplace, two estranged childhood best friends reunite after one devises a treatment that gives them powers to protect their city.'),
(433, '576393', 'zh', 'https://image.tmdb.org/t/p/w500/yM00obaRRlZxr7VLt3ebDjOFyJC.jpg', '一吻定情', '88.894', '2019-02-14', 6.7, '71', '[\'Romance\', \'Comedy\']', 'After an earthquake destroys Xiang Qin\'s house, she and her father move in with the family of her father\'s college buddy. To her surprise, her new kind and amicable aunt and uncle are the parents of her cold and distant schoolmate, Jiang Zhi Shu, a genius with an IQ of 200 whom not too long ago rejected her when she confessed her feelings for him. Will the close proximity give her a second chance to win Zhi Shu\'s heart? Or will her love for him end under his cold words?'),
(434, '120', 'en', 'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', 'The Lord of the Rings: The Fellowship of the Ring', '100.529', '2001-12-18', 8.4, '19964', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.'),
(435, '158011', 'en', 'https://image.tmdb.org/t/p/w500/mG334OlDVJpD8gMfTCM2Mpp0gQH.jpg', 'The Call', '83.301', '2013-03-14', 6.8, '2380', '[\'Crime\', \'Thriller\']', 'Jordan Turner is an experienced 911 operator but when she makes an error in judgment and a call ends badly, Jordan is rattled and unsure if she can continue. But when teenager Casey Welson is abducted in the back of a man\'s car and calls 911, Jordan is the one called upon to use all of her experience, insights and quick thinking to help Casey escape, and not just to save her, but to make sure the man is brought to justice.'),
(436, '512200', 'en', 'https://image.tmdb.org/t/p/w500/4kh9dxAiClS2GMUpkRyzGwpNWWX.jpg', 'Jumanji: The Next Level', '96.802', '2019-12-04', 7, '6337', '[\'Adventure\', \'Comedy\', \'Fantasy\']', 'As the gang return to Jumanji to rescue one of their own, they discover that nothing is as they expect. The players will have to brave parts unknown and unexplored in order to escape the world’s most dangerous game.'),
(437, '581389', 'ko', 'https://image.tmdb.org/t/p/w500/bmemsraCG1kIthY74NjDnnLRT2Q.jpg', '승리호', '106.984', '2021-02-05', 7.2, '674', '[\'Drama\', \'Fantasy\', \'Science Fiction\']', 'When the crew of a space junk collector ship called The Victory discovers a humanoid robot named Dorothy that\'s known to be a weapon of mass destruction, they get involved in a risky business deal which puts their lives at stake.'),
(438, '606523', 'ko', 'https://image.tmdb.org/t/p/w500/dYCWUAidqgakGETwZkfGxU7CWhL.jpg', '낙원의 밤', '98.945', '2020-09-03', 6.9, '148', '[\'Crime\', \'Drama\', \'Thriller\', \'Action\']', 'An assassin named Tae-goo is offered a chance to switch sides with his rival Bukseong gang, headed by Chairman Doh. Tae-goo rejects the offer that results in the murder of his sister and niece. In revenge, Tae-goo brutally kills Chairman Doh and his men and flees to Jeju Island where he meets Jae-yeon, a terminally ill woman. Though, the henchman of the Bukseong gang, Executive Ma is mercilessly hunting Tae-goo to take revenge.'),
(439, '677638', 'en', 'https://image.tmdb.org/t/p/w500/khtIr0Gxtz52T10RRQZ42o1a5Ry.jpg', 'We Bare Bears: The Movie', '111.927', '2020-06-30', 7.9, '686', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\', \'TV Movie\']', 'When Grizz, Panda, and Ice Bear\'s love of food trucks and viral videos get out of hand, the brothers are now chased away from their home and embark on a trip to Canada, where they can live in peace.'),
(440, '483898', 'en', 'https://image.tmdb.org/t/p/w500/g1xiBoLD6v3ZaXPa4QtuXiQeYKW.jpg', '50 Greatest Harry Potter Moments', '92.859', '2011-07-27', 7.9, '38', '[\'Documentary\']', 'To mark the release two weeks ago of the eighth and final movie in the series, Robbie Coltrane narrates a countdown of the movie franchise\'s best moments. From Harry\'s first meeting with Ron and Hermione aboard the Hogwarts Express through to magical mysteries.'),
(441, '118', 'en', 'https://image.tmdb.org/t/p/w500/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg', 'Charlie and the Chocolate Factory', '116.162', '2005-07-13', 7, '11875', '[\'Adventure\', \'Comedy\', \'Family\', \'Fantasy\']', 'A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world\'s most unusual candy maker.'),
(442, '736074', 'en', 'https://image.tmdb.org/t/p/w500/5X1n5q08mZ7NpNpxehMFODxfNYq.jpg', 'Batman: The Long Halloween, Part Two', '121.797', '2021-07-26', 7.7, '215', '[\'Animation\', \'Mystery\', \'Action\', \'Crime\']', 'As Gotham City\'s young vigilante, the Batman, struggles to pursue a brutal serial killer, district attorney Harvey Dent gets caught in a feud involving the criminal family of the Falcones.'),
(443, '87101', 'en', 'https://image.tmdb.org/t/p/w500/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', 'Terminator Genisys', '110.469', '2015-06-23', 5.9, '6907', '[\'Science Fiction\', \'Action\', \'Thriller\', \'Adventure\']', 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John\'s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.'),
(444, '793002', 'en', 'https://image.tmdb.org/t/p/w500/lLhvwLNU4pLgvaNREVFaQ4n3lCf.jpg', 'Dreamcatcher', '87.409', '2021-03-05', 6.6, '70', '[\'Horror\', \'Mystery\', \'Thriller\']', 'The film centers on two estranged sisters who, along with their friends, become entrenched in a 48 hour whirlwind of violence after a traumatic experience at an underground music festival.'),
(445, '225886', 'en', 'https://image.tmdb.org/t/p/w500/pFdS7SIdjcrYXtf141dabWVly9B.jpg', 'Sex Tape', '99.58', '2014-07-17', 5.4, '3517', '[\'Comedy\']', 'When Jay and Annie first got together, their romantic connection was intense – but ten years and two kids later, the flame of their love needs a spark.  To kick things up a notch, they decide – why not? – to make a video of themselves trying out every position in The Joy of Sex in one marathon three-hour session.  It seems like a great idea – until they discover that their most private video is no longer private.  With their reputations on the line, they know they’re just one click away from being laid bare to the world... but as their race to reclaim their video leads to a night they\'ll never forget, they\'ll find that their video will expose even more than they bargained for.'),
(446, '655431', 'ja', 'https://image.tmdb.org/t/p/w500/5Ln3Hr6UYvnnQXLIEMotdeo2BCK.jpg', 'PSYCHO-PASS サイコパス 3 FIRST INSPECTOR', '107.407', '2020-03-27', 7.7, '47', '[\'Science Fiction\', \'Action\', \'Crime\', \'Animation\']', 'Inspector Kei Mikhail Ignatov finds himself involved with an organization named Bifrost with the possibility of freeing his wife if he betrays Unit One. Koichi Azusawa coordinates an assault on the Public Safety Bureau tower using his hacker Obata, locking down the building and kidnapping Inspector Arata Shindo. Azusawa demands that governor Karina Komiya resign from her position.'),
(447, '460458', 'en', 'https://image.tmdb.org/t/p/w500/bArhvjRHl535XMaSh9VjInF2mSZ.jpg', 'Resident Evil: Welcome to Raccoon City', '88.822', '2021-11-24', 0, '0', '[\'Horror\', \'Action\', \'Mystery\']', 'Once the booming home of pharmaceutical giant Umbrella Corporation, Raccoon City is now a dying Midwestern town. The company’s exodus left the city a wasteland…with great evil brewing below the surface. When that evil is unleashed, the townspeople are forever…changed…and a small group of survivors must work together to uncover the truth behind Umbrella and make it through the night.'),
(448, '44912', 'en', 'https://image.tmdb.org/t/p/w500/fj21HwUprqjjwTdkKC1XZurRSpV.jpg', 'Green Lantern', '101.214', '2011-06-16', 5.2, '5909', '[\'Adventure\', \'Action\', \'Thriller\', \'Science Fiction\']', 'For centuries, a small but powerful force of warriors called the Green Lantern Corps has sworn to keep intergalactic order. Each Green Lantern wears a ring that grants him superpowers. But when a new enemy called Parallax threatens to destroy the balance of power in the Universe, their fate and the fate of Earth lie in the hands of the first human ever recruited.'),
(449, '296096', 'en', 'https://image.tmdb.org/t/p/w500/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg', 'Me Before You', '97.535', '2016-06-01', 7.9, '9490', '[\'Drama\', \'Romance\']', 'A small town girl is caught between dead-end jobs. A high-profile, successful man becomes wheelchair bound following an accident. The man decides his life is not worth living until the girl is hired for six months to be his new caretaker. Worlds apart and trapped together by circumstance, the two get off to a rocky start. But the girl becomes determined to prove to the man that life is worth living and as they embark on a series of adventures together, each finds their world changing in ways neither of them could begin to imagine.'),
(450, '20533', 'en', 'https://image.tmdb.org/t/p/w500/b1BLIXEe9zzaFvuWdYGoeuhuh75.jpg', 'Jonah Hex', '108.923', '2010-06-18', 4.9, '1096', '[\'Action\', \'Western\', \'Drama\', \'Fantasy\', \'Thriller\']', 'Gunslinger Jonah Hex is appointed by President Ulysses Grant to track down terrorist Quentin Turnbull, a former Confederate officer determined on unleashing hell on earth. Jonah not only secures freedom by accepting this task, he also gets revenge on the man who slayed his wife and child.'),
(451, '536841', 'es', 'https://image.tmdb.org/t/p/w500/3eBZxi0xcXBnEYq4m4YTVf0eHWX.jpg', 'Diego Maradona', '88.424', '2019-06-14', 7.5, '296', '[\'Documentary\']', 'Constructed from over 500 hours of never-before-seen footage, this documentary centers on the personal life and career of the controversial football player Diego Maradona who played for SSC Napoli and Argentina in the 1980s.'),
(452, '651571', 'en', 'https://image.tmdb.org/t/p/w500/m2iVkJPxDrrink7NiE412nFBMQj.jpg', 'Breach', '97.208', '2020-12-17', 4.4, '470', '[\'Science Fiction\', \'Action\']', 'A hardened mechanic must stay awake and maintain an interstellar ark fleeing the dying planet Earth with a few thousand lucky souls on board... the last of humanity. Unfortunately, humans are not the only passengers. A shapeshifting alien creature has taken residence, its only goal is to kill as many people as possible. The crew must think quickly to stop this menace before it destroys mankind.'),
(453, '4248', 'en', 'https://image.tmdb.org/t/p/w500/7Eb1JWK0Cb0rbfsYjwfc9g0PbQH.jpg', 'Scary Movie 2', '92.5', '2001-07-04', 5.8, '3506', '[\'Comedy\']', 'While the original parodied slasher flicks like Scream, Keenen Ivory Wayans\'s sequel to Scary Movie takes comedic aim at haunted house movies. A group of students visit a mansion called \"Hell House,\" and murderous high jinks ensue.'),
(454, '658558', 'ja', 'https://image.tmdb.org/t/p/w500/uJFki1BLHvEi4gaPCJvy9SZQZpx.jpg', '劇場版 巨蟲列島', '118.732', '2020-01-10', 4.5, '11', '[\'Mystery\', \'Drama\', \'Horror\', \'Adventure\', \'Animation\']', 'After an airplane crash during a school trip, Oribe Mutsumi and her classmates were stranded on a seemingly deserted island. Mutsumi found the other survivors, and used her wilderness knowledge to help them. She expects that they will be rescued in about three days, which doesn\'t seem so long to endure. However, she didn\'t account for the fact that the island is populated with gigantic killer insects. Her knowledge of butterflies, wasps, and more may be the only thing that will help any of her classmates survive to be rescued!'),
(455, '424139', 'en', 'https://image.tmdb.org/t/p/w500/cD8JrfSEI4j7WVnKM1GdiYzMoUh.jpg', 'Halloween', '94.627', '2018-10-18', 6.5, '3581', '[\'Horror\', \'Thriller\']', 'Jamie Lee Curtis returns to her iconic role as Laurie Strode, who comes to her final confrontation with Michael Myers, the masked figure who has haunted her since she narrowly escaped his killing spree on Halloween night four decades ago.'),
(456, '59440', 'en', 'https://image.tmdb.org/t/p/w500/iM8n4nZJPR2abpnyZ36FUgHiRjr.jpg', 'Warrior', '140.066', '2011-09-09', 7.8, '3416', '[\'Drama\', \'Action\']', 'The youngest son of an alcoholic former boxer returns home, where he\'s trained by his father for competition in a mixed martial arts tournament – a path that puts the fighter on a collision course with his estranged, older brother.'),
(457, '13448', 'en', 'https://image.tmdb.org/t/p/w500/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg', 'Angels & Demons', '106.651', '2009-05-13', 6.7, '5509', '[\'Thriller\', \'Mystery\']', 'Harvard symbologist Robert Langdon is recruited by the Vatican to investigate the apparent return of the Illuminati - a secret, underground organization - after four cardinals are kidnapped on the night of the papal conclave.'),
(458, '281338', 'en', 'https://image.tmdb.org/t/p/w500/3vYhLLxrTtZLysXtIWktmd57Snv.jpg', 'War for the Planet of the Apes', '83.448', '2017-07-11', 7.1, '7013', '[\'Drama\', \'Science Fiction\', \'War\']', 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind. As the journey finally brings them face to face, Caesar and the Colonel are pitted against each other in an epic battle that will determine the fate of both their species and the future of the planet.'),
(459, '622386', 'en', 'https://image.tmdb.org/t/p/w500/k9EUKPVgT4Pk7rbNoKTvdOiW9GK.jpg', 'Tiffany + Chucky', '95.705', '2019-07-19', 8.5, '4', '[\'Horror\']', 'Long before being fatally wounded and transferring his soul into the body of a Good Guy doll, Charles Lee Ray aka Chucky, was better known as the Lakeshore Strangler; a serial killer who wrought havoc all over the Chicago area. But Chucky\'s killing spree wasn\'t a solo venture. He had a little help from the only woman crazy enough to stand by his side- Tiffany Valentine. This is how they met.'),
(460, '587996', 'es', 'https://image.tmdb.org/t/p/w500/dWSnsAGTfc8U27bWsy2RfwZs0Bs.jpg', 'Bajocero', '96.349', '2021-01-29', 6.4, '656', '[\'Action\', \'Crime\', \'Thriller\']', 'When a prisoner transfer van is attacked, the cop in charge must fight those inside and outside while dealing with a silent foe: the icy temperatures.'),
(461, '663558', 'zh', 'https://image.tmdb.org/t/p/w500/np4ScPY04HESKBbpexwstKsipKe.jpg', '新神榜：哪吒重生', '101.09', '2021-02-06', 8.3, '233', '[\'Animation\', \'Action\', \'Fantasy\']', '3000 years after the boy-god Nezha conquers the Dragon King then disappears in mythological times, he returns as an ordinary man to find his own path to becoming a true hero.'),
(462, '22', 'en', 'https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', 'Pirates of the Caribbean: The Curse of the Black Pearl', '110.921', '2003-07-09', 7.8, '16599', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Jack Sparrow, a freewheeling 18th-century pirate, quarrels with a rival pirate bent on pillaging Port Royal. When the governor\'s daughter is kidnapped, Sparrow decides to help the girl\'s love save her.'),
(463, '684281', 'en', 'https://image.tmdb.org/t/p/w500/j2QwbzBQNEw0Wx8ijiCqDZv3TVP.jpg', 'Adventures of a Mathematician', '94.406', '2021-06-11', 6.4, '9', '[\'Drama\', \'History\']', 'The warmhearted story of Polish immigrant and mathematician Stan Ulam, who moved to the U.S. in the 1930s. Stan deals with the difficult losses of family and friends all while helping to create the hydrogen bomb and the first computer.'),
(464, '45610', 'en', 'https://image.tmdb.org/t/p/w500/534yDalJ8rybnSn8VZ9XPWU3egc.jpg', 'Machine Gun Preacher', '104.67', '2011-09-23', 6.7, '749', '[\'Action\', \'Thriller\', \'Crime\']', 'The true story of Sam Childers, a former drug-dealing biker who finds God and became a crusader for hundreds of Sudanese children who\'ve been kidnapped and pressed into duty as soldiers.'),
(465, '198184', 'en', 'https://image.tmdb.org/t/p/w500/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg', 'Chappie', '95.834', '2015-03-04', 6.8, '6558', '[\'Crime\', \'Action\', \'Science Fiction\']', 'Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there\'s one thing that makes Chappie different from any one else: he is a robot.'),
(466, '458156', 'en', 'https://image.tmdb.org/t/p/w500/ziEuG1essDuWuC5lpWUaw1uXY2O.jpg', 'John Wick: Chapter 3 - Parabellum', '115.765', '2019-05-15', 7.4, '7365', '[\'Action\', \'Thriller\', \'Crime\']', 'Super-assassin John Wick returns with a $14 million price tag on his head and an army of bounty-hunting killers on his trail. After killing a member of the shadowy international assassin’s guild, the High Table, John Wick is excommunicado, but the world’s most ruthless hit men and women await his every turn.'),
(467, '48138', 'en', 'https://image.tmdb.org/t/p/w500/aXBQD515okXQZmYA89ntXMvSJSd.jpg', 'Unknown', '94.122', '2011-02-16', 6.6, '3044', '[\'Action\', \'Mystery\', \'Thriller\']', 'A man awakens from a coma, only to discover that someone has taken on his identity and that no one, (not even his wife), believes him. With the help of a young woman, he sets out to prove who he is.'),
(468, '23988', 'en', 'https://image.tmdb.org/t/p/w500/qDlmKahejt0NoQzw65tnLayEhHZ.jpg', 'Stan Helsing', '87.419', '2009-10-27', 4.2, '339', '[\'Comedy\', \'Horror\']', 'It\'s Halloween night and video store clerk Stan Helsing just got stuck with a last minute request to deliver some videos. With his best friend, his best friend\'s date, and a smoking hot ex-girlfriend waiting to go to a party, Stan convinces them to take a side trip to Stormy Night Estates for the drop. But the group gets locked inside and Stan discovers he\'s actually Stan Van Helsing, descendan'),
(469, '749274', 'en', 'https://image.tmdb.org/t/p/w500/esrzqq7Ud8yoslFTu3J5HqTJVOQ.jpg', 'Cry Macho', '94.288', '2021-09-16', 6.5, '247', '[\'Western\', \'Drama\']', 'Mike Milo, a one-time rodeo star and washed-up horse breeder, takes a job from an ex-boss to bring the man\'s young son home from Mexico.'),
(470, '50620', 'en', 'https://image.tmdb.org/t/p/w500/7IGdPaKujv0BjI0Zd0m0a4CzEjJ.jpg', 'The Twilight Saga: Breaking Dawn - Part 2', '101.074', '2012-11-13', 6.5, '7347', '[\'Adventure\', \'Fantasy\', \'Drama\', \'Romance\']', 'After the birth of Renesmee, the Cullens gather other vampire clans in order to protect the child from a false allegation that puts the family in front of the Volturi.'),
(471, '567748', 'en', 'https://image.tmdb.org/t/p/w500/m8aR1k35oZMOzZ1kYWUyt401mwq.jpg', 'The Guilty', '93.318', '2021-09-24', 6.5, '1041', '[\'Crime\', \'Drama\', \'Thriller\']', 'A demoted police officer assigned to a call dispatch desk is conflicted when he receives an emergency phone call from a kidnapped woman.'),
(472, '37686', 'en', 'https://image.tmdb.org/t/p/w500/pUWIjaMMYJjeBm5bJyE3mIXdQ62.jpg', 'Super 8', '92.013', '2011-06-08', 6.7, '5413', '[\'Thriller\', \'Science Fiction\', \'Mystery\']', 'In 1979 Ohio, several youngsters are making a zombie movie with a Super-8 camera. In the midst of filming, the friends witness a horrifying train derailment and are lucky to escape with their lives. They soon discover that the catastrophe was no accident, as a series of unexplained events and disappearances soon follows. Deputy Jackson Lamb, the father of one of the kids, searches for the terrifying truth behind the crash.'),
(473, '126963', 'ja', 'https://image.tmdb.org/t/p/w500/nxZEdYcHMuD8SSuwusDnK9CD2H1.jpg', 'ドラゴンボールZ 神と神', '99.96', '2013-03-30', 6.8, '1122', '[\'Animation\', \'Action\', \'Science Fiction\']', 'The events of Battle of Gods take place some years after the battle with Majin Buu, which determined the fate of the entire universe. After awakening from a long slumber, Beerus, the God of Destruction is visited by Whis, his attendant and learns that the galactic overlord Frieza has been defeated by a Super Saiyan from the North Quadrant of the universe named Goku, who is also a former student of the North Kai. Ecstatic over the new challenge, Goku ignores King Kai\'s advice and battles Beerus, but he is easily overwhelmed and defeated. Beerus leaves, but his eerie remark of \"Is there nobody on Earth more worthy to destroy?\" lingers on. Now it is up to the heroes to stop the God of Destruction before all is lost.'),
(474, '486589', 'en', 'https://image.tmdb.org/t/p/w500/MBiKqTsouYqAACLYNDadsjhhC0.jpg', 'Red Shoes and the Seven Dwarfs', '99.323', '2019-07-25', 7.8, '803', '[\'Animation\', \'Romance\', \'Family\']', 'Princes who have been turned into Dwarfs seek the red shoes of a lady in order to break the spell, although it will not be easy.'),
(475, '50723', 'ja', 'https://image.tmdb.org/t/p/w500/6e2YvN1tQK4xQHlmy7GJTuXOt2u.jpg', '劇場版 NARUTO -ナルト- 疾風伝 ザ・ロストタワー', '97.24', '2010-07-31', 7, '262', '[\'Adventure\', \'Action\', \'Animation\']', 'Assigned on a mission to capture Mukade, a missing-nin, Naruto Uzumaki sets out for the once glorious historic ruins of \"Ouran\", where he pursues and corners the rouge ninja. Mukade\'s goal is revealed to be a dormant leyline within the ruins; he unleashes the power of the leyline, causing a light to envelop Naruto, sending him into the past, 20 years before the series began. When Naruto awakens, he comes into contact with the Fourth Hokage, Minato Namikaze.'),
(476, '667757', 'es', 'https://image.tmdb.org/t/p/w500/zGD9CiO6vCk1nmvk0SzlhgYB5fz.jpg', 'El prófugo', '99.208', '2021-07-30', 5.1, '9', '[\'Thriller\']', 'Inés works as a dubbing actress and sings in a choir in Buenos Aires. While on an idyllic trip she suffers a traumatic episode that she can’t recover from. She has trouble sleeping and experiences very vivid nightmares as strange sounds begin to emerge from inside her. Awake, Inés feels suddenly surrounded by people that seem to come from her dreams.'),
(477, '618353', 'en', 'https://image.tmdb.org/t/p/w500/k8Q9ulyRE8fkvZMkAM9LPYMKctb.jpg', 'Batman: Death in the Family', '107.95', '2020-10-13', 7.3, '281', '[\'Animation\', \'Action\']', 'Tragedy strikes the Batman\'s life again when Robin Jason Todd tracks down his birth mother only to run afoul of the Joker. An adaptation of the 1988 comic book storyline of the same name.'),
(478, '674164', 'en', 'https://image.tmdb.org/t/p/w500/s0XnZJwwsamRVaCphz3zJofGMFj.jpg', 'Return of Chucky', '84.368', '2021-12-31', 0, '0', '[]', 'The fan movie follows the story of Andrew, a kid who finds a terrifying deteriorated Good Guy doll at the forest. Soon, a chain of blood is unleashed after several murders, which leaves the trail that the doll, named Chucky, is possessed, and will kill anyone who crosses in his way to complete his terrifying and dirty plan.'),
(479, '76338', 'en', 'https://image.tmdb.org/t/p/w500/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg', 'Thor: The Dark World', '96.827', '2013-10-30', 6.6, '14048', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.'),
(480, '739542', 'en', 'https://image.tmdb.org/t/p/w500/j0HnLa6FtGcslbqClKOIyvCXfpe.jpg', 'America: The Motion Picture', '98.542', '2021-06-30', 5.8, '130', '[\'Action\', \'Comedy\', \'History\', \'Animation\', \'Fantasy\']', 'A chainsaw-wielding George Washington teams with beer-loving bro Sam Adams to take down the Brits in a tongue-in-cheek riff on the American Revolution.'),
(481, '75174', 'en', 'https://image.tmdb.org/t/p/w500/a0Vt3wx8ciKmPt4iXPx9sH4HBVU.jpg', 'The Grey', '83.368', '2011-09-14', 6.6, '3051', '[\'Drama\', \'Thriller\', \'Action\', \'Adventure\']', 'Following a grueling five-week shift at an Alaskan oil refinery, workers led by sharpshooter John Ottway, are flying home for a much-needed vacation. But a brutal storm causes their plane to crash in the frozen wilderness, and only eight men, including Ottway, survive. As they trek southward toward civilization and safety, Ottway and his companions must battle mortal injuries, the icy elements, and a pack of hungry wolves.'),
(482, '284054', 'en', 'https://image.tmdb.org/t/p/w500/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', 'Black Panther', '95.125', '2018-02-13', 7.4, '18107', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'King T\'Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country\'s new leader. However, T\'Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T\'Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan \'special forces\') and an American secret agent, to prevent Wakanda from being dragged into a world war.'),
(483, '839440', 'en', 'https://image.tmdb.org/t/p/w500/qISzj26R3LnsChQcXQKnuyxQQhK.jpg', 'Dinosaur Hotel', '94.71', '2021-06-11', 5.3, '48', '[\'Horror\', \'Science Fiction\', \'Mystery\']', 'Sienna is desperate to win a large cash prize in a secret underground game show. However, Dinosaur\'s begin to hunt her down for the entertainment of the rich and wealthy. Can she be the last to survive the horrific night to win the prize?'),
(484, '23629', 'en', 'https://image.tmdb.org/t/p/w500/jtaUDnvIiHUd2ranDcjB5AbPx6o.jpg', 'Sucker Punch', '91.55', '2011-03-24', 6.1, '3777', '[\'Action\', \'Fantasy\', \'Thriller\']', 'A young girl is institutionalized by her abusive stepfather. Retreating to an alternative reality as a coping strategy, she envisions a plan which will help her escape from the mental facility.'),
(485, '649087', 'sv', 'https://image.tmdb.org/t/p/w500/cMhoSGFMOOZUyvZYB6Q9AR4t6fV.jpg', 'Red Dot', '90.161', '2021-02-11', 5.9, '542', '[\'Thriller\', \'Drama\', \'Horror\']', 'On a hiking trip to rekindle their marriage, a couple find themselves fleeing for their lives in the unforgiving wilderness from an unknown shooter.'),
(486, '35', 'en', 'https://image.tmdb.org/t/p/w500/s3b8TZWwmkYc2KoJ5zk77qB6PzY.jpg', 'The Simpsons Movie', '102.162', '2007-07-25', 7, '6443', '[\'Animation\', \'Comedy\', \'Family\']', 'After Homer accidentally pollutes the town\'s water supply, Springfield is encased in a gigantic dome by the EPA and the Simpsons are declared fugitives.'),
(487, '285', 'en', 'https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', 'Pirates of the Caribbean: At World\'s End', '103.797', '2007-05-19', 7.2, '11414', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Captain Barbossa, long believed to be dead, has come back to life and is headed to the edge of the Earth with Will Turner and Elizabeth Swann. But nothing is quite as it seems.'),
(488, '9543', 'en', 'https://image.tmdb.org/t/p/w500/siNGMLdOUNYLEGtlsnmQcpO2XZX.jpg', 'Prince of Persia: The Sands of Time', '101.593', '2010-05-19', 6.2, '5537', '[\'Adventure\', \'Fantasy\', \'Action\']', 'A rogue prince reluctantly joins forces with a mysterious princess and together, they race against dark forces to safeguard an ancient dagger capable of releasing the Sands of Time – gift from the gods that can reverse time and allow its possessor to rule the world.'),
(489, '597', 'en', 'https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', 'Titanic', '94.235', '1997-11-18', 7.9, '19999', '[\'Drama\', \'Romance\']', '101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic\'s departure through to its death—on its first and last voyage—on April 15, 1912.'),
(490, '38365', 'en', 'https://image.tmdb.org/t/p/w500/cQGM5k1NtU85n4TUlrOrwijSCcm.jpg', 'Grown Ups', '98.326', '2010-06-24', 6.3, '4649', '[\'Comedy\']', 'After their high school basketball coach passes away, five good friends and former teammates reunite for a Fourth of July holiday weekend.'),
(491, '615677', 'en', 'https://image.tmdb.org/t/p/w500/1S21HpcKY6uQ9UAw68aICmrJaq6.jpg', 'We Can Be Heroes', '97.081', '2020-12-25', 6.3, '544', '[\'Action\', \'Fantasy\', \'Family\', \'Comedy\']', 'When alien invaders capture Earth\'s superheroes, their kids must learn to work together to save their parents - and the planet.'),
(492, '10201', 'en', 'https://image.tmdb.org/t/p/w500/8Vk2nQF1kY34x53YnWd5zDaTht.jpg', 'Yes Man', '94.058', '2008-12-09', 6.6, '5283', '[\'Comedy\', \'Romance\']', 'Carl Allen has stumbled across a way to shake free of post-divorce blues and a dead-end job: embrace life and say yes to everything.'),
(493, '8966', 'en', 'https://image.tmdb.org/t/p/w500/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', 'Twilight', '99.856', '2008-11-20', 6.3, '11034', '[\'Fantasy\', \'Drama\', \'Romance\']', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward\'s repeated cautions, Bella can\'t stay away from him, a fatal move that endangers her own life.'),
(494, '24752', 'ja', 'https://image.tmdb.org/t/p/w500/uqTSXqjaSgSAT2lCv3GyZeodQPG.jpg', 'Doragon bôru Z 5: Tobikkiri no saikyô tai saikyô', '92.233', '1991-07-20', 6.8, '433', '[\'Action\', \'Animation\', \'Science Fiction\']', 'After defeating Frieza, Goku returns to Earth and goes on a camping trip with Gohan and Krillin. Everything is normal until Cooler - Frieza\'s brother - sends three henchmen after Goku. A long fight ensues between our heroes and Cooler, in which he transforms into the fourth stage of his evolution and has the edge in the fight... until Goku transforms into a Super Saiyan.'),
(495, '874965', 'de', 'https://image.tmdb.org/t/p/w500/yAlmGXeAtc7ejp2G1V3qT4mATlb.jpg', 'Du Sie Er & Wir', '93.729', '2021-10-15', 5.2, '35', '[\'Comedy\', \'Romance\', \'Drama\']', 'After their partner swap experiment takes a turn, four friends arrive at a remote beach hut to face the fallout and purge themselves of deeper truths.'),
(496, '336843', 'en', 'https://image.tmdb.org/t/p/w500/drbERzlA4cuRWhsTXfFOY4mRR4f.jpg', 'Maze Runner: The Death Cure', '84.838', '2018-01-10', 7.1, '6056', '[\'Science Fiction\', \'Action\', \'Adventure\', \'Thriller\']', 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.'),
(497, '72105', 'en', 'https://image.tmdb.org/t/p/w500/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg', 'Ted', '101.173', '2012-06-29', 6.4, '10151', '[\'Comedy\', \'Fantasy\']', 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.'),
(498, '11224', 'en', 'https://image.tmdb.org/t/p/w500/j91LJmcWo16CArFOoapsz84bwxb.jpg', 'Cinderella', '92.807', '1950-02-22', 7, '5389', '[\'Family\', \'Fantasy\', \'Animation\', \'Romance\']', 'Cinderella has faith her dreams of a better life will come true. With help from her loyal mice friends and a wave of her Fairy Godmother\'s wand, Cinderella\'s rags are magically turned into a glorious gown and off she goes to the Royal Ball. But when the clock strikes midnight, the spell is broken, leaving a single glass slipper... the only key to the ultimate fairy-tale ending!'),
(499, '785752', 'en', 'https://image.tmdb.org/t/p/w500/o6ozTBflWXlBje0uxJv4m6s4HTq.jpg', 'Intrusion', '93.456', '2021-09-22', 6.2, '289', '[\'Thriller\']', 'When a husband and wife move to a small town, a home invasion leaves the wife traumatized and suspicious that those around her might not be who they seem.'),
(500, '779202', 'pt', 'https://image.tmdb.org/t/p/w500/azwL00eK99iEMmGjpRQ9rGpGJ28.jpg', 'Terapia do Medo', '79.967', '2021-08-04', 6.8, '56', '[\'Mystery\', \'Horror\', \'Thriller\']', 'A woman tries to help her twin sister, with whom she has a strong connection, recover from a trauma. But weird things surround their lives.'),
(501, '12429', 'ja', 'https://image.tmdb.org/t/p/w500/yp8vEZflGynlEylxEesbYasc06i.jpg', '崖の上のポニョ', '90.365', '2008-07-19', 7.7, '2989', '[\'Animation\', \'Fantasy\', \'Family\']', 'The son of a sailor, 5-year old Sosuke, lives a quiet life on an oceanside cliff with his mother Lisa. One fateful day, he finds a beautiful goldfish trapped in a bottle on the beach and upon rescuing her, names her Ponyo. But she is no ordinary goldfish.'),
(502, '576845', 'en', 'https://image.tmdb.org/t/p/w500/n1ZRmjlk1BJTY7aASqACfPAaLn2.jpg', 'Last Night in Soho', '88.37', '2021-10-21', 7.5, '198', '[\'Drama\', \'Horror\', \'Mystery\', \'Thriller\']', 'A young girl, passionate about fashion design, is mysteriously able to enter the 1960s where she encounters her idol, a dazzling wannabe singer. But 1960s London is not what it seems, and time seems to be falling apart with shady consequences.'),
(503, '654028', 'en', 'https://image.tmdb.org/t/p/w500/6sG0kbEvAi3RRLcGGU5h8l3qAPa.jpg', 'The Christmas Chronicles: Part Two', '101.772', '2020-11-18', 6.6, '653', '[\'Family\', \'Fantasy\', \'Adventure\', \'Comedy\']', 'Kate Pierce is reluctantly spending Christmas with her mom’s new boyfriend and his son Jack. But when the North Pole and Christmas are threatened to be destroyed, Kate and Jack are unexpectedly pulled into a new adventure with Santa Claus.'),
(504, '396535', 'ko', 'https://image.tmdb.org/t/p/w500/vNVFt6dtcqnI7hqa6LFBUibuFiw.jpg', '부산행', '98.877', '2016-07-20', 7.8, '5196', '[\'Action\', \'Horror\', \'Thriller\']', 'Martial law is declared when a mysterious viral outbreak pushes Korea into a state of emergency. Those on an express train to Busan, a city that has successfully fended off the viral outbreak, must fight for their own survival…'),
(505, '57158', 'en', 'https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', 'The Hobbit: The Desolation of Smaug', '94.336', '2013-12-11', 7.6, '10474', '[\'Fantasy\', \'Adventure\', \'Action\']', 'The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.'),
(506, '102651', 'en', 'https://image.tmdb.org/t/p/w500/bDG3yei6AJlEAK3A5wN7RwFXQ7V.jpg', 'Maleficent', '86.02', '2014-05-28', 7.1, '11236', '[\'Fantasy\', \'Adventure\', \'Action\', \'Family\', \'Romance\']', 'A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land.  Maleficent rises to be the land\'s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King\'s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom – and to Maleficent\'s true happiness as well.'),
(507, '544401', 'en', 'https://image.tmdb.org/t/p/w500/pwDvkDyaHEU9V7cApQhbcSJMG1w.jpg', 'Cherry', '92.247', '2021-02-26', 7.5, '790', '[\'Crime\', \'Drama\']', 'Cherry drifts from college dropout to army medic in Iraq - anchored only by his true love, Emily. But after returning from the war with PTSD, his life spirals into drugs and crime as he struggles to find his place in the world.'),
(508, '36728', 'ja', 'https://image.tmdb.org/t/p/w500/pZzdFmztwmg0FUOVCMa7vReHhQN.jpg', '劇場版 NARUTO -ナルト- 疾風伝 火の意志を継ぐ者', '93.894', '2009-08-01', 7.2, '274', '[\'Action\', \'Adventure\', \'Comedy\', \'Drama\', \'Fantasy\', \'Animation\']', 'Ninjas with bloodline limits begin disappearing in all the countries and blame points toward the fire nation. By Tsunade\'s order, Kakashi is sacrificed to prevent an all out war. After inheriting charms left by Kakashi, Naruto fights through friends and foes to prevent his death while changing the minds of those who\'ve inherited the will of fire.'),
(509, '16996', 'en', 'https://image.tmdb.org/t/p/w500/yEcfFXEWpuXcfsR9nKESVCFneqV.jpg', '17 Again', '86.823', '2009-03-11', 6.3, '4135', '[\'Comedy\']', 'On the brink of a midlife crisis, 30-something Mike O\'Donnell wishes he could have a \"do-over.\" And that\'s exactly what he gets when he wakes up one morning to find he\'s 17 years old again. With his adult mind stuck inside the body of a teenager, Mike actually has the chance to reverse some decisions he wishes he\'d never made. But maybe they weren\'t so bad after all.'),
(510, '375846', 'en', 'https://image.tmdb.org/t/p/w500/jKrIlgfJPIWNeowaOZPBZuOPmq0.jpg', 'Bad Sister', '78.021', '2016-01-03', 6.7, '151', '[\'Thriller\', \'TV Movie\']', 'As a top student at St. Adeline\'s Catholic Boarding School, Zoe senses that something is not quite right about the school\'s new nun-- a sense proven to be true when it is revealed the \"good\' nun is an imposter with a fatal attraction to Zoe\'s brother.'),
(511, '60304', 'en', 'https://image.tmdb.org/t/p/w500/j343Rpj3WeNvP0SV80zveve70io.jpg', 'Hansel & Gretel: Witch Hunters', '83.4', '2013-01-17', 6, '5662', '[\'Fantasy\', \'Horror\', \'Action\']', 'After getting a taste for blood as children, Hansel and Gretel have become the ultimate vigilantes, hell-bent on retribution. Now, unbeknownst to them, Hansel and Gretel have become the hunted, and must face an evil far greater than witches... their past.'),
(512, '787009', 'en', 'https://image.tmdb.org/t/p/w500/kEKQjLYZiIy78eEiMrtBfqSm3LU.jpg', 'Stay Out of the Attic', '80.706', '2021-03-11', 5.8, '43', '[\'Horror\']', 'A diverse group of ex-cons-turned-movers are convinced by their creepy client, Vern Muller, to pull an all-nighter for a generous pay bump.  As the night progresses and rooms are cleared, they slowly uncover the horrors that exist inside his old Victorian mansion, which include boobytraps, human experimentation, Nazi monsters and more. Will they survive the night?'),
(513, '698320', 'en', 'https://image.tmdb.org/t/p/w500/lTUfalNirpq7SBASa6lnzs27iam.jpg', 'The Mad Hatter', '78.535', '2021-01-29', 5.8, '46', '[\'Horror\', \'Thriller\']', 'An eccentric professor takes four of his students to the mansion of the “Mad Hatter”, an urban legend driven insane by mercury poisoning and grief. He says that there’s nothing to worry about now: the strange, shambling “caretakers” that haunt the home are merely servants that have fallen to inbreeding, and the Hatter himself has been dead for years. But as the students start disappearing one by one, those that remain start to question if the professor’s experiment is truly scientific...and if the Hatter didn’t just succumb to his madness, but decided to spread it...'),
(514, '644083', 'en', 'https://image.tmdb.org/t/p/w500/tw7lgyrQpEVXuwjsx94brDSRIFZ.jpg', 'Twist', '100.902', '2021-01-22', 6.1, '122', '[\'Crime\', \'Drama\', \'Action\']', 'A Dickens classic brought thrillingly up to date in the teeming heartland of modern London, where a group of street smart young hustlers plan the heist of the century for the ultimate payday.'),
(515, '82675', 'en', 'https://image.tmdb.org/t/p/w500/yzAlcuJhpnxRPjaj7AHBRbNPQCJ.jpg', 'Taken 2', '98.855', '2012-09-27', 6.3, '5412', '[\'Action\', \'Crime\', \'Thriller\']', 'In Istanbul, retired CIA operative Bryan Mills and his wife are taken hostage by the father of a kidnapper Mills killed while rescuing his daughter.'),
(516, '591275', 'en', 'https://image.tmdb.org/t/p/w500/rmEPtz3Ufzol2VWUAZYzOFaBio3.jpg', 'Fear Street: 1666', '100.608', '2021-07-14', 7.4, '893', '[\'Mystery\', \'Horror\']', 'In 1666, a colonial town is gripped by a hysterical witch-hunt that has deadly consequences for centuries to come, and it\'s up to teenagers in 1994 to finally put an end to their town\'s curse, before it\'s too late.'),
(517, '447404', 'en', 'https://image.tmdb.org/t/p/w500/uhWvnFgg3BNlcUz0Re1HfQqIcCD.jpg', 'Pokémon Detective Pikachu', '93.0', '2019-05-03', 7, '5230', '[\'Action\', \'Adventure\', \'Fantasy\']', 'In a world where people collect pocket-size monsters (Pokémon) to do battle, a boy comes across an intelligent monster who seeks to be a detective.'),
(518, '607383', 'en', 'https://image.tmdb.org/t/p/w500/wB8qqLIaYDkYEnjbS5hAJiTuYU6.jpg', 'Aquaslash', '92.067', '2019-07-29', 4.1, '84', '[\'Horror\', \'Comedy\']', 'To celebrate their graduation, the teenagers from Valley Hills High School have organized an ’80s-themed party at the old Wet Valley water park. Things turn gruesome when it\'s revealed that a mysterious maniac has inserted giant razor blades into one of the water slides. The water park thus becomes the backdrop for a bloodbath (literally), and everyone is a suspect...'),
(519, '82690', 'en', 'https://image.tmdb.org/t/p/w500/zWoIgZ7mgmPkaZjG0102BSKFIqQ.jpg', 'Wreck-It Ralph', '88.172', '2012-01-01', 7.3, '10189', '[\'Family\', \'Animation\', \'Comedy\', \'Adventure\']', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game\'s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero\'s Duty, a first-person shooter where he helps the game\'s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.'),
(520, '1771', 'en', 'https://image.tmdb.org/t/p/w500/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', 'Captain America: The First Avenger', '92.892', '2011-07-22', 7, '17604', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'During World War II, Steve Rogers is a sickly man from Brooklyn who\'s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler\'s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.'),
(521, '602269', 'en', 'https://image.tmdb.org/t/p/w500/tLO1aD1ghdtVMT32z2sRmzgYKYd.jpg', 'The Little Things', '93.78', '2021-01-28', 6.4, '1291', '[\'Thriller\', \'Crime\', \'Drama\']', 'Deputy Sheriff Joe \"Deke\" Deacon joins forces with Sgt. Jim Baxter to search for a serial killer who\'s terrorizing Los Angeles. As they track the culprit, Baxter is unaware that the investigation is dredging up echoes of Deke\'s past, uncovering disturbing secrets that could threaten more than his case.'),
(522, '645856', 'en', 'https://image.tmdb.org/t/p/w500/dtt2dfMdmlCcgaJZkPPQsIY5oR6.jpg', 'The Seventh Day', '85.071', '2021-03-26', 5.7, '140', '[\'Horror\']', 'A renowned exorcist teams up with a rookie priest for his first day of training. As they plunge deeper into hell on earth, the lines between good and evil blur, and their own demons emerge.'),
(523, '11187', 'en', 'https://image.tmdb.org/t/p/w500/6toMk9OCuDYEEf733Bzlq3yiw3z.jpg', 'Child\'s Play 3', '85.613', '1991-08-30', 5.9, '1069', '[\'Horror\', \'Thriller\']', 'Eight years have passed since the events of the second film. Chucky has been resurrected once again and seeks revenge on Andy, his former owner, who is now a teenager enrolled in military school.'),
(524, '360920', 'en', 'https://image.tmdb.org/t/p/w500/smxA8yvZ0LzDPer9BIRd4pyOpx1.jpg', 'The Grinch', '108.579', '2018-11-08', 6.8, '2683', '[\'Animation\', \'Family\', \'Comedy\', \'Fantasy\']', 'The Grinch hatches a scheme to ruin Christmas when the residents of Whoville plan their annual holiday celebration.'),
(525, '10144', 'en', 'https://image.tmdb.org/t/p/w500/ym1dxyOk4jFcSl4Q2zmRrA5BEEN.jpg', 'The Little Mermaid', '102.5', '1989-11-17', 7.4, '6158', '[\'Animation\', \'Family\', \'Fantasy\']', 'This colorful adventure tells the story of an impetuous mermaid princess named Ariel who falls in love with the very human Prince Eric and puts everything on the line for the chance to be with him. Memorable songs and characters -- including the villainous sea witch Ursula.'),
(526, '16869', 'en', 'https://image.tmdb.org/t/p/w500/7sfbEnaARXDDhKm0CZ7D7uc2sbo.jpg', 'Inglourious Basterds', '115.552', '2009-08-19', 8.2, '17709', '[\'Drama\', \'Action\', \'Thriller\', \'War\']', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as \"The Basterds\" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(527, '37724', 'en', 'https://image.tmdb.org/t/p/w500/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg', 'Skyfall', '119.752', '2012-10-25', 7.2, '12945', '[\'Action\', \'Adventure\', \'Thriller\']', 'When Bond\'s latest assignment goes gravely wrong and agents around the world are exposed, MI6 is attacked forcing M to relocate the agency. These events cause her authority and position to be challenged by Gareth Mallory, the new Chairman of the Intelligence and Security Committee. With MI6 now compromised from both inside and out, M is left with one ally she can trust: Bond. 007 takes to the shadows - aided only by field agent, Eve - following a trail to the mysterious Silva, whose lethal and hidden motives have yet to reveal themselves.'),
(528, '441168', 'en', 'https://image.tmdb.org/t/p/w500/kvcdaGcres9pGDwZfPN9jOKfZh.jpg', 'From Straight A\'s to XXX', '94.153', '2017-02-11', 5.6, '75', '[\'Drama\', \'TV Movie\']', 'When a change of circumstances leaves Miriam unable to pay her college tuition, she makes a surprising decision: to start performing in adult films, using the pseudonym Belle Knox. Miriam lies to her family and her friends at school, keeping her double life a secret. But soon rumours spread and Miriam becomes the subject of vicious online attacks and unwanted attention. Miriam fights back: she talks to the media, saying her new line of work empowers her as a feminist. But her confident stand has unintended consequences. Miriam is shunned by her conservative family and her colleagues in the adult film world. One impulsive decision has quickly spiralled out of control - and Miriam\'s problems are just beginning.'),
(529, '536728', 'en', 'https://image.tmdb.org/t/p/w500/luVAyI2imMIuSL9oA65W44iuDMr.jpg', 'The Space Between', '92.4', '2021-04-23', 5.5, '6', '[\'Drama\', \'Comedy\']', 'Micky Adams, an eccentric has-been rock musician, loses his grip on reality as his record label looks to drop him and his new \"unique\" albums. In hopes of breaking out of the mailroom, young Charlie Porter is tasked with traveling to the musician\'s bizarre home and forcing Micky out of his contract. Micky realizes Charlie could be the key to an artistic breakthrough and the pair\'s unlikely friendship grows. The odd but powerful bond helps both gain perspective on the music industry, life, love... and the space between.'),
(530, '345940', 'en', 'https://image.tmdb.org/t/p/w500/eyWICPcxOuTcDDDbTMOZawoOn8d.jpg', 'The Meg', '91.212', '2018-08-09', 6.2, '5534', '[\'Action\', \'Science Fiction\', \'Horror\']', 'A deep sea submersible pilot revisits his past fears in the Mariana Trench, and accidentally unleashes the seventy foot ancestor of the Great White Shark believed to be extinct.'),
(531, '126889', 'en', 'https://image.tmdb.org/t/p/w500/zecMELPbU5YMQpC81Z8ImaaXuf9.jpg', 'Alien: Covenant', '84.204', '2017-05-09', 6, '6752', '[\'Horror\', \'Science Fiction\', \'Mystery\']', 'Bound for a remote planet on the far side of the galaxy, the crew of the colony ship \'Covenant\' discovers what is thought to be an uncharted paradise, but is actually a dark, dangerous world—which has a sole inhabitant: the \'synthetic\', David, survivor of the doomed Prometheus expedition.'),
(532, '819413', 'zh', 'https://image.tmdb.org/t/p/w500/n25rzoh84RFgGSpzoDw86M0EbFW.jpg', '八月未央', '104.663', '2021-04-16', 2, '1', '[\'Romance\']', 'A story revolving around two friends with very different personalities - the no-nonsense and rebellious Weiyang and the idealist \'Princess\' Qiao. When Xiao Qiao met Weiyang, the two easily became close friends. However, Xiao Qiao\'s fiancee Chao Yan can\'t help himself as he falls deeply in love with Weiyang, which crushes Xiao Qiao\'s fairytale love story. Just as the three are entangled in a world of complications, Weiyang makes a surprising decision.'),
(533, '122', 'en', 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', 'The Lord of the Rings: The Return of the King', '93.118', '2003-12-01', 8.5, '18523', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Aragorn is revealed as the heir to the ancient kings as he, Gandalf and the other members of the broken fellowship struggle to save Gondor from Sauron\'s forces. Meanwhile, Frodo and Sam take the ring closer to the heart of Mordor, the dark lord\'s realm.'),
(534, '400928', 'en', 'https://image.tmdb.org/t/p/w500/9Ts7Vc4wLlpI9oox9mkVUE1tBHy.jpg', 'Gifted', '76.165', '2017-04-12', 8.1, '4108', '[\'Family\', \'Drama\', \'Comedy\']', 'Frank, a single man raising his child prodigy niece Mary, is drawn into a custody battle with his mother.'),
(535, '12', 'en', 'https://image.tmdb.org/t/p/w500/eHuGQ10FUzK1mdOY69wF5pGgEf5.jpg', 'Finding Nemo', '82.071', '2003-05-30', 7.8, '15612', '[\'Animation\', \'Family\']', 'Nemo, an adventurous young clownfish, is unexpectedly taken from his Great Barrier Reef home to a dentist\'s office aquarium. It\'s up to his worrisome father Marlin and a friendly but forgetful fish Dory to bring Nemo home -- meeting vegetarian sharks, surfer dude turtles, hypnotic jellyfish, hungry seagulls, and more along the way.'),
(536, '50253', 'ja', 'https://image.tmdb.org/t/p/w500/w1id1iEKogRjmMffAM01ZcWwBLR.jpg', '聖闘士星矢 天界編 序奏 ~overture~', '91.69', '2004-02-14', 7.6, '179', '[\'Animation\', \'Fantasy\']', 'After the bloody battle against Hades, the goddess Athena and her saints are still recovering when they find themselves face to face with their newest and most formidable foe: the dreadful moon goddess Artemis. Artemis replaces Athena as the earth guardian deity and takes over the Sanctuary, turning Athena\'s Saints into her servants.  Upon invading the Sanctuary, the Bronze Saints learn that Athena was banished by Artemis and decide to fight the moon goddess in order to rescue their true goddess and free the Earth from Artemis\'s ominous control.'),
(537, '47971', 'en', 'https://image.tmdb.org/t/p/w500/hba8zREJpP1AYhaXgb2oJLQeO0K.jpg', 'xXx: Return of Xander Cage', '95.781', '2017-01-13', 5.8, '4933', '[\'Action\', \'Adventure\', \'Crime\']', 'Extreme athlete turned government operative Xander Cage comes out of self-imposed exile, thought to be long dead, and is set on a collision course with deadly alpha warrior Xiang and his team in a race to recover a sinister and seemingly unstoppable weapon known as Pandora\'s Box. Recruiting an all-new group of thrill-seeking cohorts, Xander finds himself enmeshed in a deadly conspiracy that points to collusion at the highest levels of world governments.'),
(538, '953', 'en', 'https://image.tmdb.org/t/p/w500/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', 'Madagascar', '82.367', '2005-05-25', 6.9, '8654', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\']', 'Alex the lion is the king of the urban jungle, the main attraction at New York\'s Central Park Zoo. He and his best friends—Marty the zebra, Melman the giraffe and Gloria the hippo—have spent their whole lives in blissful captivity before an admiring public and with regular meals provided for them. Not content to leave well enough alone, Marty lets his curiosity get the better of him and makes his escape—with the help of some prodigious penguins—to explore the world.'),
(539, '49026', 'en', 'https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', 'The Dark Knight Rises', '82.767', '2012-07-16', 7.8, '18529', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent\'s crimes to protect the late attorney\'s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham\'s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.'),
(540, '159824', 'en', 'https://image.tmdb.org/t/p/w500/3nFnrivNgipSKZ8LZJJbRSlAcTR.jpg', 'Hotel Transylvania 2', '84.767', '2015-09-21', 6.8, '4533', '[\'Family\', \'Animation\', \'Comedy\', \'Fantasy\']', 'When the old-old-old-fashioned vampire Vlad arrives at the hotel for an impromptu family get-together, Hotel Transylvania is in for a collision of supernatural old-school and modern day cool.'),
(541, '523931', 'en', 'https://image.tmdb.org/t/p/w500/hES2eVAbVt08JJTqgu3jmI34Yxx.jpg', 'Megalodon', '81.889', '2018-08-10', 5.6, '189', '[\'Action\', \'Science Fiction\', \'Horror\', \'TV Movie\']', 'A military vessel on the search for an unidentified submersible finds themselves face to face with a giant shark, forced to use only what they have on board to defend themselves from the monstrous beast.'),
(542, '43074', 'en', 'https://image.tmdb.org/t/p/w500/7E8nLijS9AwwUEPu2oFYOVKhdFA.jpg', 'Ghostbusters', '91.185', '2016-07-14', 5.4, '5195', '[\'Action\', \'Fantasy\', \'Comedy\']', 'Following a ghost invasion of Manhattan, paranormal enthusiasts Erin Gilbert and Abby Yates, nuclear engineer Jillian Holtzmann, and subway worker Patty Tolan band together to stop the otherworldly threat.'),
(543, '158015', 'en', 'https://image.tmdb.org/t/p/w500/46X1ei9uf13nkkr0OhWldGyr5Uh.jpg', 'The Purge', '82.329', '2013-05-31', 6.3, '6900', '[\'Science Fiction\', \'Horror\', \'Thriller\']', 'Given the country\'s overcrowded prisons, the U.S. government begins to allow 12-hour periods of time in which all illegal activity is legal. During one of these free-for-alls, a family must protect themselves from a home invasion.'),
(544, '341174', 'en', 'https://image.tmdb.org/t/p/w500/w3qa274gvca9t8pkUoG8nfQgTU3.jpg', 'Fifty Shades Darker', '102.283', '2017-02-08', 6.5, '6473', '[\'Drama\', \'Romance\']', 'When a wounded Christian Grey tries to entice a cautious Ana Steele back into his life, she demands a new arrangement before she will give him another chance. As the two begin to build trust and find stability, shadowy figures from Christian’s past start to circle the couple, determined to destroy their hopes for a future together.'),
(545, '420818', 'en', 'https://image.tmdb.org/t/p/w500/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', 'The Lion King', '103.805', '2019-07-12', 7.2, '8021', '[\'Adventure\', \'Family\', \'Animation\']', 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub\'s arrival. Scar, Mufasa\'s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba\'s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.'),
(546, '715658', 'en', 'https://image.tmdb.org/t/p/w500/a8Pi3MHOKw6lTPBPs6NF82qqWFx.jpg', 'The Scientist', '80.275', '2020-09-21', 6.5, '90', '[\'Horror\']', 'An unconventional scientist, struggling to care for his terminally-ill wife, embarks on a journey to develop a cure for her. However, his methods of treatment and tampering with human DNA, could lead to the extinction of humanity.'),
(547, '109439', 'en', 'https://image.tmdb.org/t/p/w500/vtxuPWkdllLNLVyGjKYa267ntuH.jpg', 'The Hangover Part III', '85.173', '2013-05-23', 6.2, '7037', '[\'Comedy\']', 'This time, there\'s no wedding. No bachelor party. What could go wrong, right? But when the Wolfpack hits the road, all bets are off.'),
(548, '37834', 'en', 'https://image.tmdb.org/t/p/w500/a7JmOBMNj5erYTgt4u1mQgvHItu.jpg', 'Knight and Day', '76.641', '2010-06-15', 6.2, '3491', '[\'Action\', \'Comedy\']', 'A fugitive couple goes on a glamorous and sometimes deadly adventure where nothing and no one – even themselves – are what they seem. Amid shifting alliances and unexpected betrayals, they race across the globe, with their survival ultimately hinging on the battle of truth vs. trust.'),
(549, '554596', 'es', 'https://image.tmdb.org/t/p/w500/rG7rDoTe1ZEa936eonDCkV76nkx.jpg', 'No Manches Frida 2', '81.456', '2019-03-15', 8.1, '644', '[\'Comedy\']', 'Ex-con Zequi and company come back for a new adventure.'),
(550, '209112', 'en', 'https://image.tmdb.org/t/p/w500/5UsK3grJvtQrtzEgqNlDljJW96w.jpg', 'Batman v Superman: Dawn of Justice', '84.219', '2016-03-23', 5.9, '15226', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.'),
(551, '41630', 'en', 'https://image.tmdb.org/t/p/w500/9C09L1U9S13J4Ut029Qhu0oLcTQ.jpg', 'No Strings Attached', '93.973', '2011-01-21', 6.3, '3851', '[\'Comedy\', \'Romance\']', 'Emma is a busy doctor who sets up a seemingly perfect arrangement when she offers her best friend Adam a relationship with one rule: No strings attached. But when a fling becomes a thing, can sex friends stay best friends?'),
(552, '793147', 'zh', 'https://image.tmdb.org/t/p/w500/8Rp6h4AHHa5dg1jMTRRMuFS7WaI.jpg', '余生，请多指教', '98.214', '2021-02-03', 2, '1', '[\'Romance\']', 'A  story between Lin Zhi Xiao, a graduating student from the Conservatory of Music, and her father\'s attending physician Gu Wei. Fourth-year student Lin Zhi Xiao hits rock bottom right before her graduation. Her father is hospitalized due to cancer leaving her no choice but to give up the chance to work at a reputable company. She also bears the pain from a relationship that has ended. All her beautiful imaginations towards love and her future are shattered in an instant. Just then, her father\'s doctor Gu Wei walks into Lin Zhi Xiao\'s life. When love begins, people often don\'t know that it\'s love. Two people who have been hurt before and no longer believe in love start to get to know each other. There are uncertainties and setbacks, misunderstandings and downturns, but in the process of falling in love, they become more assured that they have found the person to whom they can entrust the rest of their lives.'),
(553, '671583', 'en', 'https://image.tmdb.org/t/p/w500/r2MfnMmFzGvRvjGVLIuyx3R16a6.jpg', 'Upside-Down Magic', '87.357', '2020-07-31', 7.4, '178', '[\'Fantasy\', \'Family\', \'TV Movie\']', 'Nory and her best friend Reina enter the Sage Academy for Magical Studies, where Nory’s unconventional powers land her in a class for those with wonky, or “upside-down,” magic. Undaunted, Nory sets out to prove that that upside-down magic can be just as powerful as right-side-up.'),
(554, '121', 'en', 'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', 'The Lord of the Rings: The Two Towers', '89.91', '2002-12-18', 8.4, '17256', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.'),
(555, '8355', 'en', 'https://image.tmdb.org/t/p/w500/cXOLaxcNjNAYmEx1trZxOTKhK3Q.jpg', 'Ice Age: Dawn of the Dinosaurs', '89.998', '2009-06-26', 6.7, '6553', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'Times are changing for Manny the moody mammoth, Sid the motor mouthed sloth and Diego the crafty saber-toothed tiger. Life heats up for our heroes when they meet some new and none-too-friendly neighbors – the mighty dinosaurs.'),
(556, '841', 'en', 'https://image.tmdb.org/t/p/w500/d5NXSklXo0qyIYkgV94XAgMIckC.jpg', 'Dune', '87.574', '1984-12-14', 6.3, '1964', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'In the year 10,191, the world is at war for control of the desert planet Arrakis—the only place where the space-travel substance Melange \'Spice\' can be found. But when one leader gives up control, it\'s only so he can stage a coup with some unsavory characters.'),
(557, '10674', 'en', 'https://image.tmdb.org/t/p/w500/jAbexAtB0aSfP5Ay4TpWHARyVnG.jpg', 'Mulan', '94.011', '1998-06-18', 7.9, '7628', '[\'Animation\', \'Family\', \'Adventure\']', 'A tomboyish girl disguises herself as a young man so she can fight with the Imperial Chinese Army against the invading Huns. With help from wise-cracking dragon Mushu, Mulan just might save her country -- and win the heart of handsome Captain Li Shang.'),
(558, '10193', 'en', 'https://image.tmdb.org/t/p/w500/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', 'Toy Story 3', '82.89', '2010-06-16', 7.8, '11889', '[\'Animation\', \'Family\', \'Comedy\']', 'Woody, Buzz, and the rest of Andy\'s toys haven\'t been played with in years. With Andy about to go to college, the gang find themselves accidentally left at a nefarious day care center. The toys must band together to escape and return home to Andy.'),
(559, '785544', 'cs', 'https://image.tmdb.org/t/p/w500/z3ul9VzWk8Vk5ic7EKujLn8eDeP.jpg', 'ボクたちはみんな大人になれなかった', '133.274', '2021-11-05', 4, '3', '[\'Romance\', \'Drama\']', 'A friend request with a lost love sends a man back into his memories of the \'90s, when life seemed to burn a little brighter'),
(560, '58', 'en', 'https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', 'Pirates of the Caribbean: Dead Man\'s Chest', '107.364', '2006-07-06', 7.3, '12734', '[\'Adventure\', \'Fantasy\', \'Action\']', 'Captain Jack Sparrow works his way out of a blood debt with the ghostly Davy Jones to avoid eternal damnation.'),
(561, '647302', 'en', 'https://image.tmdb.org/t/p/w500/3RE9DNBCvuso5OPZPg71ryntNjx.jpg', 'Benny Loves You', '90.52', '2019-11-21', 6.3, '101', '[\'Horror\', \'Comedy\']', 'Jack, a man desperate to improve his life, throws away his beloved childhood plush, Benny. It’s a move that has disastrous consequences when Benny springs to life with deadly intentions!'),
(562, '190859', 'en', 'https://image.tmdb.org/t/p/w500/vJgtfUmZE5i4L12sOryAPuBa04K.jpg', 'American Sniper', '88.398', '2014-12-25', 7.4, '10604', '[\'War\', \'Action\']', 'U.S. Navy SEAL Chris Kyle takes his sole mission—protect his comrades—to heart and becomes one of the most lethal snipers in American history. His pinpoint accuracy not only saves countless lives but also makes him a prime target of insurgents. Despite grave danger and his struggle to be a good husband and father to his family back in the States, Kyle serves four tours of duty in Iraq. However, when he finally returns home, he finds that he cannot leave the war behind.'),
(563, '496243', 'ko', 'https://image.tmdb.org/t/p/w500/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', '기생충', '96.306', '2019-05-30', 8.5, '12445', '[\'Comedy\', \'Thriller\', \'Drama\']', 'All unemployed, Ki-taek\'s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.'),
(564, '875828', 'en', 'https://m.media-amazon.com/images/I/71C0B8nmU7L._UF1000,1000_QL80_.jpg', 'Untitled Peaky Blinders Film', '100.232', '', 0, '0', '[]', 'An untitled film connected to the hit BBC TV Show - \'Peaky Blinders\'. It will release after Season 6 and will finish the story of the Shelby family.'),
(565, '591274', 'en', 'https://image.tmdb.org/t/p/w500/5dNTxhoGDTHHGqUTdxcr4H1dqlU.jpg', 'Fear Street: 1978', '86.548', '2021-07-08', 7.3, '1001', '[\'Horror\', \'Mystery\']', 'In 1978, two rival groups at Camp Nightwing must band together to solve a terrifying mystery when horrors from their towns\' history come alive.'),
(566, '531499', 'en', 'https://image.tmdb.org/t/p/w500/3eg0kGC2Xh0vhydJHO37Sp4cmMt.jpg', 'The Tax Collector', '93.986', '2020-08-07', 5.7, '329', '[\'Action\', \'Crime\', \'Drama\']', 'David Cuevas is a family man who works as a gangland tax collector for high ranking Los Angeles gang members. He makes collections across the city with his partner Creeper making sure people pay up or will see retaliation. An old threat returns to Los Angeles that puts everything David loves in harm’s way.'),
(567, '610150', 'ja', 'https://image.tmdb.org/t/p/w500/pi0iZOEHeA3ih4p1IwAG4x2DZNH.jpg', 'ドラゴンボール超：スーパーヒーロー', '88.668', '', 0, '0', '[\'Animation\', \'Science Fiction\', \'Action\']', ''),
(568, '9023', 'en', 'https://image.tmdb.org/t/p/w500/cUgYrz4twiJ3QgVGpRfey984NIB.jpg', 'Spirit: Stallion of the Cimarron', '91.239', '2002-05-24', 7.7, '3603', '[\'Western\', \'Animation\', \'Adventure\', \'Comedy\', \'Family\', \'Drama\']', 'As a wild stallion travels across the frontiers of the Old West, he befriends a young human and finds true love with a mare.'),
(569, '720026', 'en', 'https://image.tmdb.org/t/p/w500/k4jWlViz5VhDZdyWG786pMBQuY3.jpg', 'Butchers', '83.072', '2021-01-12', 4.9, '124', '[\'Horror\']', 'A family of sadistic butchers lives deep inside the backcountry. From the dead of winter to the dog days of summer, anyone who crosses their path is dead meat.'),
(570, '294254', 'en', 'https://image.tmdb.org/t/p/w500/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg', 'Maze Runner: The Scorch Trials', '84.993', '2015-09-09', 6.7, '8483', '[\'Science Fiction\', \'Action\', \'Thriller\', \'Adventure\']', 'Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.'),
(571, '11688', 'en', 'https://image.tmdb.org/t/p/w500/isA0acj3ONKBLp1pKadUNzxEPFv.jpg', 'The Emperor\'s New Groove', '87.316', '2000-12-15', 7.6, '5172', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'Kuzco is a self-centered emperor who summons Pacha from a village and to tell him that his home will be destroyed to make room for Kuzco\'s new summer home. Kuzco\'s advisor, Yzma, tries to poison Kuzco and accidentally turns him into a llama, who accidentally ends up in Pacha\'s village. Pacha offers to help Kuzco if he doesn\'t destroy his house, and so they form an unlikely partnership.'),
(572, '736073', 'en', 'https://image.tmdb.org/t/p/w500/sR7gppb0YGjwLvE6Vnj6wYv5MnW.jpg', 'Batman: The Long Halloween, Part One', '107.078', '2021-06-21', 7.9, '264', '[\'Animation\', \'Mystery\', \'Action\', \'Crime\']', 'Following a brutal series of murders taking place on Halloween, Thanksgiving, and Christmas, Gotham City\'s young vigilante known as the Batman sets out to pursue the mysterious serial killer alongside police officer James Gordon and district attorney Harvey Dent.'),
(573, '262500', 'en', 'https://image.tmdb.org/t/p/w500/dP5Fb6YRfzmCQtRbHOr2kO7tJW9.jpg', 'Insurgent', '81.546', '2015-03-18', 6.4, '8601', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Thriller\']', 'Beatrice Prior must confront her inner demons and continue her fight against a powerful alliance which threatens to tear her society apart.'),
(574, '17134', 'en', 'https://image.tmdb.org/t/p/w500/7k7qhrO57sVoBLrNo5HYoTp24sT.jpg', '12 Rounds', '89.693', '2009-03-19', 5.9, '567', '[\'Action\', \'Thriller\', \'Crime\']', 'When New Orleans Police Detective Danny Fisher stops a brilliant thief from getting away with a multimillion-dollar heist, the thief\'s girlfriend is accidentally killed. After escaping from prison, the criminal mastermind enacts his revenge, taunting Danny with 12 rounds of near-impossible puzzles and tasks that he must somehow complete to save the life of the woman he loves.'),
(575, '19908', 'en', 'https://image.tmdb.org/t/p/w500/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg', 'Zombieland', '89.286', '2009-10-07', 7.3, '9871', '[\'Comedy\', \'Horror\']', 'Columbus has made a habit of running from what scares him. Tallahassee doesn\'t have fears. If he did, he\'d kick their ever-living ass. In a world overrun by zombies, these two are perfectly evolved survivors. But now, they\'re about to stare down the most terrifying prospect of all: each other.'),
(576, '37645', 'fr', 'https://image.tmdb.org/t/p/w500/4spRV4Qw0YGaWBHYJ6enu84sR81.jpg', 'L\'Immortel', '82.973', '2010-03-23', 6.6, '903', '[\'Drama\', \'Crime\', \'Thriller\']', 'Charly Matteï has turned his back on his life as an outlaw. For the last three years, he\'s led a peaceful life devoting himself to his wife and two children. Then, one winter morning, he\'s left for dead in the parking garage in Marseille\'s Old Port, with 22 bullets in his body. Against all the odds, he doesn\'t die...'),
(577, '820232', 'ja', 'https://image.tmdb.org/t/p/w500/xnXeOfHXsgCRi4u75OPU2U3kZsO.jpg', '鬼滅の刃 兄妹の絆', '92.484', '2019-03-29', 9.4, '17', '[\'Action\', \'Animation\', \'Fantasy\']', 'Tanjiro finds his family slaughtered and the lone survivor, his sister Nezuko Kamado, turned into a Demon. To his surprise, however, Nezuko still shows signs of human emotion and thought. Thus begins Tanjiro\'s journey to seek out the Demon who killed their family and turn his sister human again. A recap film of Kimetsu no Yaiba, covering episodes 1-5 with extra footage.'),
(578, '50619', 'en', 'https://image.tmdb.org/t/p/w500/qs8LsHKYlVRmJbFUiSUhhRAygwj.jpg', 'The Twilight Saga: Breaking Dawn - Part 1', '90.295', '2011-11-16', 6.2, '7238', '[\'Adventure\', \'Fantasy\', \'Romance\']', 'The new found married bliss of Bella Swan and vampire Edward Cullen is cut short when a series of betrayals and misfortunes threatens to destroy their world.'),
(579, '630240', 'fr', 'https://image.tmdb.org/t/p/w500/mBlpouG3gqB8WLdP65LCOXb3jFb.jpg', 'Titane', '92.889', '2021-07-14', 6.8, '322', '[\'Drama\', \'Thriller\', \'Horror\']', 'A woman with a metal plate in her head from a childhood car accident embarks on a bizarre journey, bringing her into contact with a firefighter who\'s reunited with his missing son after 10 years.'),
(580, '61979', 'es', 'https://image.tmdb.org/t/p/w500/xeWyY2s13dRlKOLk4E3TkXgM4sS.jpg', 'Tres metros sobre el cielo', '96.784', '2010-12-03', 7.8, '2280', '[\'Romance\', \'Drama\']', 'Story of two young people who belong to different worlds. It is the chronicle of a love improbable, almost impossible but inevitable dragging in a frantic journey they discover the first great love. Babi is a girl from upper-middle class that is educated in goodness and innocence . Hache is a rebellious boy, impulsive, unconscious, has a appetite for risk and danger embodied in endless fights and illegal motorbike races, the limit of common sense'),
(581, '676842', 'es', 'https://image.tmdb.org/t/p/w500/vX1XLbrHxpryX9EOWI3akbasz6c.jpg', 'Después de ti', '86.235', '2021-04-08', 7.9, '74', '[\'Comedy\', \'Drama\']', 'Su, a woman whose friends are only men, finds herself forced to follow a series of absurd instructions to overcome the unexpected death of her fiancé.'),
(582, '11699', 'en', 'https://image.tmdb.org/t/p/w500/73jnKMm8bCcV1w2ltkaeJfLZJzX.jpg', 'Bad Lieutenant: Port of Call - New Orleans', '95.658', '2009-05-21', 6.1, '814', '[\'Drama\', \'Crime\']', 'Terrence McDonagh is a New Orleans Police sergeant, who recieves a medal and a promotion to lieutenant for heroism during Hurricane Katrina. Due to his heroic act, McDonagh injures his back and becomes addicted to prescription pain medication. He then finds himself involved with a drug dealer who is suspected of murdering a family of African immigrants.'),
(583, '718867', 'en', 'https://image.tmdb.org/t/p/w500/uHdxICUIRGoJjK67aOp3ykvL8ZW.jpg', 'The Larva Island Movie', '86.144', '2020-07-23', 7.4, '135', '[\'Animation\', \'Family\']', 'Back at home, Chuck relates the island shenanigans of his larva pals Red and Yellow to a skeptical reporter in this movie sequel to the hit cartoon.'),
(584, '49521', 'en', 'https://image.tmdb.org/t/p/w500/8GFtkImmK0K1VaUChR0n9O61CFU.jpg', 'Man of Steel', '82.456', '2013-06-12', 6.6, '12574', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.'),
(585, '521029', 'en', 'https://image.tmdb.org/t/p/w500/qWsHMrbg9DsBY3bCMk9jyYCRVRs.jpg', 'Annabelle Comes Home', '81.547', '2019-06-26', 6.4, '2537', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Determined to keep Annabelle from wreaking more havoc, demonologists Ed and Lorraine Warren bring the possessed doll to the locked artifacts room in their home, placing her “safely” behind sacred glass and enlisting a priest’s holy blessing. But an unholy night of horror awaits as Annabelle awakens the evil spirits in the room, who all set their sights on a new target—the Warrens\' ten-year-old daughter, Judy, and her friends.'),
(586, '579047', 'en', 'https://image.tmdb.org/t/p/w500/17siH6wJRQ2jZiqz9BWUhy1UtZ.jpg', 'Reminiscence', '92.703', '2021-08-19', 7.1, '846', '[\'Science Fiction\', \'Thriller\', \'Mystery\', \'Romance\']', 'Nicolas Bannister, a rugged and solitary veteran living in a near-future Miami flooded by rising seas, is an expert in a dangerous occupation: he offers clients the chance to relive any memory they desire. His life changes when he meets a mysterious young woman named Mae. What begins as a simple matter of lost and found becomes a passionate love affair. But when a different client\'s memories implicate Mae in a series of violent crimes, Bannister must delve through the dark world of the past to uncover the truth about the woman he fell for.'),
(587, '8920', 'en', 'https://image.tmdb.org/t/p/w500/vqwTSWNLyH55g8kBT61s2DgNYEp.jpg', 'Garfield', '90.276', '2004-06-10', 5.6, '3003', '[\'Animation\', \'Comedy\', \'Family\']', 'Garfield, the fat, lazy, lasagna lover, has everything a cat could want. But when Jon, in an effort to impress the Liz - the vet and an old high-school crush - adopts a dog named Odie and brings him home, Garfield gets the one thing he doesn\'t want. Competition.'),
(588, '743904', 'en', 'https://image.tmdb.org/t/p/w500/azDVclNJPVWJamcffDFkZp0alY.jpg', 'Curious George: Go West, Go Wild', '89.346', '2020-09-08', 6.2, '83', '[\'Animation\', \'Family\', \'TV Movie\']', 'While farm-sitting, George accidentally lets the farm animals escape. Ted, George and wannabe cowboy Emmett must round \'em up, accounting for every animal -- and emerging with some new skills, to boot.'),
(589, '585245', 'en', 'https://image.tmdb.org/t/p/w500/30ULVKdjBcQTsj2aOSThXXZNSxF.jpg', 'Clifford the Big Red Dog', '128.713', '2021-11-10', 0, '0', '[\'Family\', \'Animation\', \'Comedy\']', 'As Emily struggles to fit in at home and at school, she discovers a small red puppy who is destined to become her best friend. When Clifford magically undergoes one heck of a growth spurt, becomes a gigantic dog and attracts the attention of a genetics company, Emily and her Uncle Casey have to fight the forces of greed as they go on the run across New York City. Along the way, Clifford affects the lives of everyone around him and teaches Emily and her uncle the true meaning of acceptance and unconditional love.'),
(590, '168259', 'en', 'https://image.tmdb.org/t/p/w500/ktofZ9Htrjiy0P6LEowsDaxd3Ri.jpg', 'Furious 7', '93.407', '2015-04-01', 7.3, '8750', '[\'Action\', \'Thriller\', \'Crime\', \'Adventure\']', 'Deckard Shaw seeks revenge against Dominic Toretto and his family for his comatose brother.'),
(591, '714277', 'es', 'https://image.tmdb.org/t/p/w500/1rlgIzw129hEl46bFaJZ7wpEEZZ.jpg', 'La funeraria', '76.623', '2021-04-15', 4.1, '17', '[\'Horror\']', 'Bernardo is an undertaker. He runs his mortuary business in the same house where he resides. In the front, he has his clients. And in the back, his dysfunctional family lives amongst coffins, wreaths, and the mischievous but nonviolent ghosts that visit on a daily basis. But when a malevolent entity enters the scene, it wreaks havoc on the already fractured household.'),
(592, '522931', 'en', 'https://image.tmdb.org/t/p/w500/6zwGWDpY8Zu0L6W4SYWERBR8Msw.jpg', 'Hitman\'s Wife\'s Bodyguard', '111.297', '2021-06-14', 7, '859', '[\'Action\', \'Comedy\', \'Thriller\']', 'The world’s most lethal odd couple – bodyguard Michael Bryce and hitman Darius Kincaid – are back on another life-threatening mission. Still unlicensed and under scrutiny, Bryce is forced into action by Darius\'s even more volatile wife, the infamous international con artist Sonia Kincaid. As Bryce is driven over the edge by his two most dangerous protectees, the trio get in over their heads in a global plot and soon find that they are all that stand between Europe and a vengeful and powerful madman.'),
(593, '138103', 'en', 'https://image.tmdb.org/t/p/w500/utS5euWHlEdKBNnEFwjpZ2oGuhF.jpg', 'The Expendables 3', '75.656', '2014-08-04', 6.2, '3945', '[\'Action\', \'Adventure\', \'Thriller\']', 'Barney, Christmas and the rest of the team comes face-to-face with Conrad Stonebanks, who years ago co-founded The Expendables with Barney. Stonebanks subsequently became a ruthless arms trader and someone who Barney was forced to kill… or so he thought. Stonebanks, who eluded death once before, now is making it his mission to end The Expendables -- but Barney has other plans. Barney decides that he has to fight old blood with new blood, and brings in a new era of Expendables team members, recruiting individuals who are younger, faster and more tech-savvy. The latest mission becomes a clash of classic old-school style versus high-tech expertise in the Expendables’ most personal battle yet.'),
(594, '43549', 'en', 'https://image.tmdb.org/t/p/w500/zy6hJYii2PJfMRoUBlULhfuLsgL.jpg', 'The Experiment', '82.002', '2010-07-15', 6.4, '920', '[\'Thriller\', \'Drama\']', '20 men are chosen to participate in the roles of guards and prisoners in a psychological study that ultimately spirals out of control.'),
(595, '44263', 'cn', 'https://image.tmdb.org/t/p/w500/8FDwOGJT7OSE3Rho4qDoifMpOTW.jpg', '全城戒備', '84.376', '2010-08-11', 4.9, '38', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'Sunny is a naïve circus performer who dreams of inheriting his father\'s knife-throwing skills. However, his hostile colleagues continue to bully him, relegating him to a lowly clown. On a tour to Malaysia, Cheung and other performers discover a cave occupied by the Japanese army during World War II. Instead of finding treasure, the performers - including Sunny - are sprayed with a mysterious chemical that turns them into superhuman mutants...'),
(596, '193893', 'en', 'https://image.tmdb.org/t/p/w500/pf4FoUr2phn5WyZjU7rLXSiW1Ve.jpg', 'Let\'s Be Cops', '94.691', '2014-08-13', 6.4, '2200', '[\'Comedy\']', 'It\'s the ultimate buddy cop movie except for one thing: they\'re not cops.  When two struggling pals dress as police officers for a costume party, they become neighborhood sensations.  But when these newly-minted “heroes” get tangled in a real life web of mobsters and dirty detectives, they must put their fake badges on the line.'),
(597, '232672', 'en', 'https://image.tmdb.org/t/p/w500/o2YrH9jS7CAfWjETHFeL0tth79E.jpg', 'Blended', '85.083', '2014-05-21', 6.9, '2638', '[\'Comedy\']', 'After a bad blind date, a man and woman find themselves stuck together at a resort for families, where their attractions grows as their respective kids benefit from the burgeoning relationship.'),
(598, '10729', 'en', 'https://image.tmdb.org/t/p/w500/8q0VQYwOhhuRFMsyzdZ5JoB676g.jpg', 'Quick Change', '71.162', '1990-07-13', 6.7, '244', '[\'Comedy\', \'Crime\']', 'With the aid of his girlfriend, Phyllis Potter, and best friend, Loomis, Grimm enters a Manhattan bank dressed as a clown, creates a hostage situation and executes a flawless robbery. The only thing left for the trio to do is make their getaway out of the city and to the airport. It sounds simple enough, but it seems that fate deserts them immediately after the bank heist. One mishap after another conspires to keep these robbers from reaching freedom.'),
(599, '539892', 'en', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRiyjE4ANrs4INOKGiwQp5u5uwta9LRo-UUSg&s', 'Freaks', '79.211', '2019-09-13', 6.9, '766', '[\'Science Fiction\', \'Thriller\', \'Drama\', \'Mystery\']', 'Kept locked inside the house by her father, 7-year-old Chloe lives in fear and fascination of the outside world, where Abnormals create a constant threat—or so she believes. When a mysterious stranger offers her a glimpse of what\'s really happening outside, Chloe soon finds that while the truth isn\'t so simple, the danger is very real.'),
(600, '39513', 'en', 'https://image.tmdb.org/t/p/w500/dKhexH8nS08lVlSmwSs00cHFxbY.jpg', 'Paul', '77.586', '2011-02-14', 6.7, '4492', '[\'Adventure\', \'Comedy\', \'Science Fiction\']', 'For the past 60 years, a space-traveling smart-ass named Paul has been locked up in a top-secret military base, advising world leaders about his kind. But when he worries he’s outlived his usefulness and the dissection table is drawing uncomfortably close, Paul escapes on the first RV that passes by his compound in Area 51. Fortunately, it contains the two earthlings who are most likely to rescue and harbor an alien on the run.'),
(601, '772', 'en', 'https://image.tmdb.org/t/p/w500/6YqkD9h0woc4OdNzlp4fDyvtxPT.jpg', 'Home Alone 2: Lost in New York', '88.518', '1992-11-19', 6.7, '7277', '[\'Comedy\', \'Family\', \'Adventure\']', 'Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad\'s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he\'s determined to foil their plans to rob a toy store on Christmas eve.'),
(602, '691179', 'en', 'https://image.tmdb.org/t/p/w500/bT3c4TSOP8vBmMoXZRDPTII6eDa.jpg', 'Friends: The Reunion', '73.955', '2021-05-27', 8.2, '699', '[\'Documentary\']', 'The cast of Friends reunites for a once-in-a-lifetime celebration of the hit series, an unforgettable evening filled with iconic memories, uncontrollable laughter, happy tears, and special guests.'),
(603, '273481', 'en', 'https://image.tmdb.org/t/p/w500/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg', 'Sicario', '77.598', '2015-09-17', 7.4, '6483', '[\'Action\', \'Crime\', \'Thriller\']', 'An idealistic FBI agent is enlisted by a government task force to aid in the escalating war against drugs at the border area between the U.S. and Mexico.'),
(604, '39106', 'ja', 'https://image.tmdb.org/t/p/w500/A0VKJ6eRIubW6wH4eAwcpQfjoRD.jpg', 'ドラゴンボールＺ 超戦士撃破!!勝のはオレだ', '94.571', '1994-07-09', 5.8, '371', '[\'Animation\', \'Action\', \'Science Fiction\']', 'Jaga Bada, Mr. Satan\'s old sparring partner, has invited Satan to his personal island to hold a grudge match. Trunks and Goten decide to come for the adventure and Android #18 is following Satan for the money he owes her. Little do they know that Jaga Bada\'s scientist have found a way to resurrect Broly, the legendary Super Saiyan.'),
(605, '763788', 'en', 'https://image.tmdb.org/t/p/w500/8RqdjlPjyN59FnMkw5nnpaRXJde.jpg', 'Dangerous', '81.639', '2021-11-05', 5.5, '21', '[\'Action\', \'Thriller\']', 'A reformed sociopath heads to a remote island after the death of his brother. Soon after his arrival, the island falls under siege from a deadly gang of mercenaries, and when he discovers their role in his brother’s demise, he sets out on a relentless quest for vengeance.'),
(606, '447332', 'en', 'https://image.tmdb.org/t/p/w500/nAU74GmpUk7t5iklEp3bufwDq4n.jpg', 'A Quiet Place', '71.674', '2018-04-03', 7.4, '10900', '[\'Horror\', \'Drama\', \'Science Fiction\']', 'A family is forced to live in silence while hiding from creatures that hunt by sound.'),
(607, '9732', 'en', 'https://image.tmdb.org/t/p/w500/sWR1x6UCMCGN9xEf8RGhPS934X0.jpg', 'The Lion King II: Simba\'s Pride', '87.907', '1998-10-24', 7, '3569', '[\'Family\', \'Adventure\', \'Animation\']', 'The circle of life continues for Simba, now fully grown and in his rightful place as the king of Pride Rock. Simba and Nala have given birth to a daughter, Kiara who\'s as rebellious as her father was. But Kiara drives her parents to distraction when she catches the eye of Kovu, the son of the evil lioness, Zira. Will Kovu steal Kiara\'s heart?'),
(608, '411', 'en', 'https://image.tmdb.org/t/p/w500/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg', 'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', '86.457', '2005-12-07', 7.1, '8208', '[\'Adventure\', \'Family\', \'Fantasy\']', 'Siblings Lucy, Edmund, Susan and Peter step through a magical wardrobe and find the land of Narnia. There, they discover a charming, once peaceful kingdom that has been plunged into eternal winter by the evil White Witch, Jadis. Aided by the wise and magnificent lion, Aslan, the children lead Narnia into a spectacular, climactic battle to be free of the Witch\'s glacial powers forever.'),
(609, '817451', 'en', 'https://image.tmdb.org/t/p/w500/ccsSqbpEqr2KK9eMvoeF8ERFCd5.jpg', 'Endangered Species', '86.198', '2021-05-27', 6.3, '94', '[\'Thriller\', \'Action\']', 'Jack Halsey takes his wife, their adult kids, and a friend for a dream vacation in Kenya. But as they venture off alone into a wilderness park, their safari van is flipped over by an angry rhino, leaving them injured and desperate. Then, as two of them go in search of rescue, a bloody, vicious encounter with a leopard and a clan of hyenas incites a desperate fight for survival.'),
(610, '34813', 'en', 'https://image.tmdb.org/t/p/w500/b9dVH0n7YnBqLmW2c5AzftxhhpH.jpg', 'The Losers', '91.914', '2010-04-23', 6.3, '1334', '[\'Action\', \'Adventure\', \'Crime\', \'Mystery\', \'Thriller\']', 'A tale of double cross and revenge, centered upon the members of an elite U.S. Special Forces unit sent into the Bolivian jungle on a search and destroy mission. The team-Clay, Jensen, Roque, Pooch and Cougar -find themselves the target of a lethal betrayal instigated from inside by a powerful enemy known only as Max. Presumed dead, the group makes plans to even the score when they\'re joined by the mysterious Aisha, a beautiful operative with her own agenda. Working together, they must remain deep undercover while tracking the heavily-guarded Max, a ruthless man bent on embroiling the world in a new high-tech global war.'),
(611, '381289', 'en', 'https://image.tmdb.org/t/p/w500/3jcNvhtVQe5Neoffdic39fRactM.jpg', 'A Dog\'s Purpose', '76.215', '2017-01-19', 7.6, '2571', '[\'Adventure\', \'Comedy\', \'Fantasy\', \'Family\', \'Drama\']', 'A dog goes on quest to discover his purpose in life over the course of several lifetimes with multiple owners.'),
(612, '802504', 'nl', 'https://image.tmdb.org/t/p/w500/3btDwus5VN5jOWfA9strpDJWwfj.jpg', 'Just Say Yes', '82.043', '2021-04-02', 6.7, '163', '[\'Comedy\', \'Romance\']', 'Incurable romantic Lotte finds her life upended when her plans for a picture-perfect wedding unravel -- just as her self-absorbed sister gets engaged.'),
(613, '351694', 'zh', 'https://image.tmdb.org/t/p/w500/xHme10Y5jVdH8KeSGgStndjatF5.jpg', '西游记之大圣归来', '77.956', '2015-07-10', 7.1, '155', '[\'Fantasy\', \'Animation\', \'Comedy\']', 'The all-powerful Monkey King once roamed freely between Heaven and Earth, but after angering the Gods, he was imprisoned within an ice cage deep within the mountains. 500 years later, monsters attack a small village and a child flees to the mountains. Unknowingly, the child releases the Monkey King from his curse. With the help and encouragement from this special child, Monkey King saves the village from the evil monsters.'),
(614, '608804', 'pt', 'https://image.tmdb.org/t/p/w500/7gqZyGlLjNKXIk8RBswqAGJygVz.jpg', 'A Menina Que Matou os Pais', '86.329', '2021-09-24', 6.5, '134', '[\'Crime\', \'Drama\', \'Thriller\']', 'Based on one of the most shocking and gruesome murder cases in Brazil, the film presents Daniel Cravinhos\'s point of view of the events that led to the death of Marísia and Manfred von Richthofen, his girlfriend’s parents.'),
(615, '683127', 'ja', 'https://image.tmdb.org/t/p/w500/9oK820JieICOcfUhI6mkpFrcA9m.jpg', 'アーヤと魔女', '76.883', '2021-01-27', 6.4, '72', '[\'Animation\', \'Fantasy\', \'Family\']', 'A headstrong orphan discovers a world of spells and potions while living with a selfish witch.'),
(616, '484718', 'en', 'https://image.tmdb.org/t/p/w500/nWBPLkqNApY5pgrJFMiI9joSI30.jpg', 'Coming 2 America', '83.631', '2021-03-05', 6.7, '1612', '[\'Comedy\']', 'Prince Akeem Joffer is set to become King of Zamunda when he discovers he has a son he never knew about in America – a street savvy Queens native named Lavelle. Honoring his royal father\'s dying wish to groom this son as the crown prince, Akeem and Semmi set off to America once again.'),
(617, '721656', 'en', 'https://image.tmdb.org/t/p/w500/ojSrGq5qIBObrodYilJQPXSYv6r.jpg', 'Happy Halloween, Scooby-Doo!', '91.185', '2020-10-06', 7.9, '164', '[\'Family\', \'Animation\', \'Mystery\', \'Comedy\']', 'Scooby-Doo and the gang team up with their pals, Bill Nye The Science Guy and Elvira Mistress of the Dark, to solve this mystery of gigantic proportions and save Crystal Cove!'),
(618, '345938', 'en', 'https://image.tmdb.org/t/p/w500/doAzav9kfdtsoSdw1MDFvjKq3J4.jpg', 'The Shack', '73.591', '2017-03-03', 7.4, '1567', '[\'Drama\', \'Fantasy\']', 'After suffering a family tragedy, Mack Phillips spirals into a deep depression causing him to question his innermost beliefs. Facing a crisis of faith, he receives a mysterious letter urging him to an abandoned shack deep in the Oregon wilderness. Despite his doubts, Mack journeys to the shack and encounters an enigmatic trio of strangers led by a woman named Papa. Through this meeting, Mack finds important truths that will transform his understanding of his tragedy and change his life forever.'),
(619, '616851', 'en', 'https://m.media-amazon.com/images/M/MV5BYWI0ZjgxYWYtODZmNi00ZWI0LWI4MmEtZDBmOTNmMTRlMjY0XkEyXkFqcGc@._V1_QL75_UX140_CR0,0,140,207_.jpg', 'Untitled \'The Walking Dead\' Film', '82.87', '', 0, '0', '[\'Adventure\', \'Drama\', \'Horror\', \'Science Fiction\']', 'Follows Rick Grimes from the departure of his final season in the TV series.'),
(620, '287947', 'en', 'https://image.tmdb.org/t/p/w500/xnopI5Xtky18MPhK40cZAGAOVeV.jpg', 'Shazam!', '85.783', '2019-03-29', 7.1, '7022', '[\'Action\', \'Comedy\', \'Fantasy\']', 'A boy is given the ability to become an adult superhero in times of need with a single magic word.'),
(621, '853588', 'de', 'https://image.tmdb.org/t/p/w500/2FKjLRt7oK1bRRIrxgWmthbBdFh.jpg', 'Prey', '78.895', '2021-09-10', 4.5, '173', '[\'Thriller\']', 'A hiking trip into the wild turns into a desperate bid for survival for five friends on the run from a mysterious shooter.'),
(622, '76757', 'en', 'https://image.tmdb.org/t/p/w500/2NCcAZ3M3F0FxENYmammBknwpVn.jpg', 'Jupiter Ascending', '83.972', '2015-02-04', 5.4, '5661', '[\'Science Fiction\', \'Fantasy\', \'Action\', \'Adventure\']', 'In a universe where human genetic material is the most precious commodity, an impoverished young Earth woman becomes the key to strategic maneuvers and internal strife within a powerful dynasty…'),
(623, '680531', 'fr', 'https://image.tmdb.org/t/p/w500/A8KeSPmFDxqHKwNzyiuwUvPIrw0.jpg', 'Le bal des folles', '78.325', '2021-09-12', 7.1, '125', '[\'Drama\', \'Thriller\']', 'Eugenie has a unique gift: she hears and sees the dead. When her family discovers her secret, at the end of the 19th century, she is taken by her father and brother to the neurological clinic at La Pitié Salpêtrière with no possibility of escaping her fate. Her destiny becomes entwined with that of Geneviève, a nurse at the hospital.'),
(624, '760883', 'de', 'https://image.tmdb.org/t/p/w500/v7aOJKI5vxCHotHvN8O7SR6SpP6.jpg', 'Blood Red Sky', '78.326', '2021-07-23', 7.2, '943', '[\'Horror\', \'Thriller\', \'Action\']', 'A woman with a mysterious illness is forced into action when a group of terrorists attempt to hijack a transatlantic overnight flight. In order to protect her son she will have to reveal a dark secret, and unleash the inner monster she has fought to hide.'),
(625, '6466', 'en', 'https://image.tmdb.org/t/p/w500/f9ZASRUfl8Jlco7rgRx3ujPR0P7.jpg', 'Freddy vs. Jason', '72.234', '2003-08-15', 6, '1843', '[\'Horror\']', 'In an attempt to free himself from a state of forgotten limbo, evil dream-demon Freddy Krueger devises a plan to manipulate un-dead mass murderer Jason Voorhees  into slicing-and-dicing his way through the teenage population of Springwood.  But when the master of dreams loses control of his monster, a brutal fight to the death is the only way out.'),
(626, '11674', 'en', 'https://image.tmdb.org/t/p/w500/8o2ADoAyG796UwTjwBFjPyBz0yG.jpg', '101 Dalmatians', '86.019', '1996-11-27', 5.9, '2662', '[\'Family\', \'Comedy\']', 'An evil high-fashion designer plots to steal Dalmatian puppies in order to make an extravagant fur coat, but instead creates an extravagant mess.'),
(627, '763149', 'en', 'https://image.tmdb.org/t/p/w500/gEHIVyJB9VWLF3cuJOpYjJjegd1.jpg', 'Aftermath', '70.788', '2021-08-04', 6.6, '342', '[\'Horror\', \'Crime\', \'Drama\', \'Thriller\']', 'Desperate to save their marriage, a young couple takes a deal to move into their dream home, but disturbing events reveal the house\'s troubled history.'),
(628, '246655', 'en', 'https://image.tmdb.org/t/p/w500/ikA8UhYdTGpqbatFa93nIf6noSr.jpg', 'X-Men: Apocalypse', '78.541', '2016-05-18', 6.5, '10822', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\']', 'After the re-emergence of the world\'s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.'),
(629, '77338', 'fr', 'https://image.tmdb.org/t/p/w500/1QU7HKgsQbGpzsJbJK4pAVQV9F5.jpg', 'Intouchables', '83.726', '2011-11-02', 8.3, '13952', '[\'Drama\', \'Comedy\']', 'A true story of two men who should never have met – a quadriplegic aristocrat who was injured in a paragliding accident and a young man from the projects.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(630, '299537', 'en', 'https://image.tmdb.org/t/p/w500/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', 'Captain Marvel', '89.442', '2019-03-06', 6.9, '12134', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.'),
(631, '187017', 'en', 'https://image.tmdb.org/t/p/w500/850chzYHYbT3IISl6Q7dbBuFP2B.jpg', '22 Jump Street', '73.496', '2014-06-05', 6.8, '6632', '[\'Crime\', \'Comedy\', \'Action\']', 'After making their way through high school (twice), big changes are in store for officers Schmidt and Jenko when they go deep undercover at a local college. But when Jenko meets a kindred spirit on the football team, and Schmidt infiltrates the bohemian art major scene, they begin to question their partnership. Now they don\'t have to just crack the case - they have to figure out if they can have a mature relationship. If these two overgrown adolescents can grow from freshmen into real men, college might be the best thing that ever happened to them.'),
(632, '286217', 'en', 'https://image.tmdb.org/t/p/w500/3ndAx3weG6KDkJIRMCi5vXX6Dyb.jpg', 'The Martian', '75.018', '2015-09-30', 7.7, '16246', '[\'Drama\', \'Adventure\', \'Science Fiction\']', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.'),
(633, '9806', 'en', 'https://image.tmdb.org/t/p/w500/2LqaLgk4Z226KkgPJuiOQ58wvrm.jpg', 'The Incredibles', '82.059', '2004-10-27', 7.7, '14488', '[\'Action\', \'Adventure\', \'Animation\', \'Family\']', 'Bob Parr has given up his superhero days to log in time as an insurance adjuster and raise his three children with his formerly heroic wife in suburbia. But when he receives a mysterious assignment, it\'s time to get back into costume.'),
(634, '49519', 'en', 'https://image.tmdb.org/t/p/w500/27zvjVOtOi5ped1HSlJKNsKXkFH.jpg', 'The Croods', '79.704', '2013-03-15', 6.9, '5665', '[\'Animation\', \'Adventure\', \'Family\', \'Fantasy\', \'Comedy\', \'Action\']', 'The prehistoric Croods family live in a particularly dangerous moment in time. Patriarch Grug, his mate Ugga, teenage daughter Eep, son Thunk, and feisty Gran gather food by day and huddle together in a cave at night. When a more evolved caveman named Guy arrives on the scene, Grug is distrustful, but it soon becomes apparent that Guy is correct about the impending destruction of their world.'),
(635, '767504', 'en', 'https://image.tmdb.org/t/p/w500/mx6cgtUiEOVGSI3sb3SNQxAXqRa.jpg', 'Black as Night', '90.634', '2021-10-01', 5.4, '44', '[\'Horror\', \'Thriller\']', 'A teenage girl with self-esteem issues finds confidence in the most unlikely way, by spending her summer battling vampires that prey on New Orleans\' disenfranchised with the help of her best friend, the boy she\'s always pined for, and a peculiar rich girl.'),
(636, '19994', 'en', 'https://image.tmdb.org/t/p/w500/wrkjsGcFJxcQqR56kJUYAEKKg2T.jpg', 'Jennifer\'s Body', '75.333', '2009-09-18', 5.8, '2764', '[\'Horror\', \'Comedy\']', 'Jennifer, a gorgeous, seductive cheerleader takes evil to a whole new level after she\'s possessed by a sinister demon. Now it\'s up to her best friend to stop Jennifer\'s reign of terror before it\'s too late.'),
(637, '71676', 'en', 'https://image.tmdb.org/t/p/w500/fDtIZXLNreDHk3mOskJYABrQNOQ.jpg', 'Ghost Rider: Spirit of Vengeance', '81.726', '2011-12-11', 5, '2926', '[\'Action\', \'Fantasy\', \'Thriller\']', 'When the devil resurfaces with aims to take over the world in human form, Johnny Blaze reluctantly comes out of hiding to transform into the flame-spewing supernatural hero Ghost Rider -- and rescue a 10-year-old boy from an unsavory end.'),
(638, '553301', 'en', 'https://image.tmdb.org/t/p/w500/q719jXXEzOoYaps6babgKnONONX.jpg', 'Your Name', '98.507', '', 0, '0', '[\'Drama\', \'Fantasy\', \'Romance\']', 'J.J. Abrams and Paramount Pictures have announced they’ll be turning the critically acclaimed Japanese anime Your Name into a live-action film.'),
(639, '23047', 'en', 'https://image.tmdb.org/t/p/w500/dNVqi8EsBtnnwfR6TgiWM51JOuS.jpg', 'Season of the Witch', '85.61', '2011-01-07', 5.4, '1909', '[\'Adventure\', \'Fantasy\', \'Action\']', 'A 14th century Crusader returns with his comrade to a homeland devastated by the Black Plague. The Church commands the two knights to transport a witch to a remote abbey, where monks will perform a ritual in hopes of ending the pestilence.'),
(640, '351286', 'en', 'https://image.tmdb.org/t/p/w500/x2Us3jR6ToMJjbcPbLimYoxf6xr.jpg', 'Jurassic World: Fallen Kingdom', '77.339', '2018-06-06', 6.6, '9311', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Three years after the demise of Jurassic World, a volcanic eruption threatens the remaining dinosaurs on Isla Nublar. So, Claire Dearing recruits Owen Grady to help prevent the extinction of the dinosaurs once again.'),
(641, '260513', 'en', 'https://image.tmdb.org/t/p/w500/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', 'Incredibles 2', '79.377', '2018-06-14', 7.5, '10387', '[\'Action\', \'Adventure\', \'Animation\', \'Family\']', 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.'),
(642, '662546', 'en', 'https://image.tmdb.org/t/p/w500/80tDCErk6ymHS7YfvqJcbnnTtqa.jpg', 'Godmothered', '83.007', '2020-12-04', 7, '423', '[\'Family\', \'Fantasy\', \'Comedy\']', 'A young and unskilled fairy godmother that ventures out on her own to prove her worth by tracking down a young girl whose request for help was ignored. What she discovers is that the girl has now become a grown woman in need of something very different than a \"prince charming.\"'),
(643, '504253', 'ja', 'https://image.tmdb.org/t/p/w500/noDaFc11nTBAajjH3AqGEkcZVWg.jpg', '君の膵臓をたべたい', '68.613', '2018-09-01', 8.3, '860', '[\'Animation\', \'Drama\', \'Romance\', \'Family\']', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: \"Living with Dying.\" He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret. Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change.'),
(644, '636879', 'en', 'https://image.tmdb.org/t/p/w500/eutNRwSguV0NCx7BNAXOibWzjP6.jpg', 'A Nun\'s Curse', '66.21', '2020-05-12', 6.2, '66', '[\'Horror\']', 'A group of travelers are forced to seek shelter inside an abandoned jail where a notorious nun named Sister Monday had once been assigned and was suspected of murdering prisoners.'),
(645, '260514', 'en', 'https://image.tmdb.org/t/p/w500/zg5RDxvIIAKsucjuU2EZJIHEIvz.jpg', 'Cars 3', '83.148', '2017-06-15', 6.9, '4214', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\']', 'Blindsided by a new generation of blazing-fast racers, the legendary Lightning McQueen is suddenly pushed out of the sport he loves. To get back in the game, he will need the help of an eager young race technician with her own plan to win, inspiration from the late Fabulous Hudson Hornet, and a few unexpected turns. Proving that #95 isn\'t through yet will test the heart of a champion on Piston Cup Racing’s biggest stage!'),
(646, '817566', 'es', 'https://image.tmdb.org/t/p/w500/hphNszzQI0eFAopKCJtuBLQP0Fa.jpg', 'Solo una vez', '81.647', '2021-06-11', 4.7, '3', '[\'Drama\']', ''),
(647, '20222', 'es', 'https://image.tmdb.org/t/p/w500/9Unz4SnlkXg0OAxgiLKZAfu096c.jpg', 'Sexo con amor', '75.435', '2003-03-27', 6.5, '158', '[\'Comedy\', \'Romance\']', 'In Santiago, Chile, the schoolteacher Luisa proposes a debate about sex with the parents of her students with the intention of giving classes about sex education to the youngsters.'),
(648, '14160', 'en', 'https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', 'Up', '82.286', '2009-05-28', 7.9, '16406', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.'),
(649, '749618', 'es', 'https://image.tmdb.org/t/p/w500/g8ZyfUC0THygJkVoO2J7NxsdPI5.jpg', 'El camino de Xico', '74.511', '2020-11-12', 6.9, '76', '[\'Animation\', \'Family\']', 'The peace of a small town is endangered when a corporation wants to destroy the mountain that protects them. A girl named Copi and her best friend Xico, a Xoloitzcuintle dog, will go into the mountains to try to save the town.'),
(650, '3170', 'en', 'https://image.tmdb.org/t/p/w500/wV9e2y4myJ4KMFsyFfWYcUOawyK.jpg', 'Bambi', '79.123', '1942-08-14', 7, '4458', '[\'Animation\', \'Drama\', \'Family\']', 'Bambi\'s tale unfolds from season to season as the young prince of the forest learns about life, love, and friends.'),
(651, '37786', 'en', 'https://image.tmdb.org/t/p/w500/iHSRxhZsPaVuLCivvV6WEkMVGWU.jpg', 'Sex and the City 2', '77.925', '2010-05-26', 6.1, '1334', '[\'Comedy\', \'Drama\', \'Romance\']', 'Carrie, Charlotte, and Miranda are all married now, but they\'re still up for a little fun in the sun. When Samantha gets the chance to visit one of the most extravagant vacation destinations on the planet and offers to bring them all along, they surmise that a women-only retreat may be the perfect excuse to eschew their responsibilities and remember what life was like before they decided to settle down.'),
(652, '9502', 'en', 'https://image.tmdb.org/t/p/w500/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', 'Kung Fu Panda', '83.023', '2008-06-04', 7.2, '8839', '[\'Action\', \'Adventure\', \'Animation\', \'Family\', \'Comedy\']', 'When the Valley of Peace is threatened, lazy Po the panda discovers his destiny as the \"chosen one\" and trains to become a kung fu hero, but transforming the unsleek slacker into a brave warrior won\'t be easy. It\'s up to Master Shifu and the Furious Five -- Tigress, Crane, Mantis, Viper and Monkey -- to give it a try.'),
(653, '135397', 'en', 'https://image.tmdb.org/t/p/w500/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg', 'Jurassic World', '79.276', '2015-06-06', 6.7, '17336', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Thriller\']', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.'),
(654, '23823', 'en', 'https://image.tmdb.org/t/p/w500/84s4LMWuGbm4xPWW5PSbHyQhh33.jpg', 'Wrong Turn 3: Left for Dead', '76.17', '2009-10-20', 5.6, '776', '[\'Horror\', \'Thriller\']', 'A group of people find themselves trapped in the backwoods of West Virginia, fighting for their lives against a group of vicious and horribly disfigured inbred cannibals.'),
(655, '157350', 'en', 'https://image.tmdb.org/t/p/w500/aNh4Q3iuPKDMPi2SL7GgOpiLukX.jpg', 'Divergent', '77.075', '2014-03-14', 6.9, '10838', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'In a world divided into factions based on personality types, Tris learns that she\'s been classified as Divergent and won\'t fit in. When she discovers a plot to destroy Divergents, Tris and the mysterious Four must find out what makes Divergents dangerous before it\'s too late.'),
(656, '249070', 'en', 'https://image.tmdb.org/t/p/w500/cx9AOBOv9Qf5ufZYQMbfTV7w7VY.jpg', 'Hitman: Agent 47', '83.864', '2015-08-20', 5.8, '2415', '[\'Action\', \'Crime\', \'Thriller\']', 'An assassin teams up with a woman to help her find her father and uncover the mysteries of her ancestry.'),
(657, '667520', 'ja', 'https://image.tmdb.org/t/p/w500/6inkRM1XGBG5vRhclCPWfMenp7N.jpg', '泣きたい私は猫をかぶる', '76.534', '2020-06-18', 8.1, '867', '[\'Animation\', \'Drama\', \'Romance\', \'Fantasy\', \'Science Fiction\']', 'Miyo \"Muge\" Sasaki is a peculiar second-year junior high student who has fallen in love with her classmate Kento Hinode. Muge resolutely pursues Kento every day, but he takes no notice of her. Nevertheless, while carrying a secret she can tell no one, Muge continues to pursue Kento. Muge discovers a magic mask that allows her to transform into a cat named Tarō. The magic lets Muge get close to Kento, but eventually it may also make her unable to transform back to a human.'),
(658, '335984', 'en', 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', 'Blade Runner 2049', '66.808', '2017-10-04', 7.5, '10096', '[\'Science Fiction\', \'Drama\']', 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what\'s left of society into chaos. K\'s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.'),
(659, '530079', 'ja', 'https://image.tmdb.org/t/p/w500/byoY2stdullEcVjlaWs1ENXyrDm.jpg', 'きみと、波にのれたら', '80.365', '2019-06-21', 7.6, '154', '[\'Animation\', \'Romance\', \'Comedy\', \'Drama\', \'Fantasy\']', 'Hinako is a surf-loving college student who has just moved to a small seaside town. When a sudden fire breaks out at her apartment building, she is rescued by Minato, a handsome firefighter, and the two soon fall in love. Just as they become inseparable, Minato loses his life in an accident at sea. Hinako is so distraught that she can no longer even look at the ocean, but one day she sings a song that reminds her of their time together, and Minato appears in the water. From then on, she can summon him in any watery surface as soon as she sings their song, but can the two really remain together forever? And what is the real reason for Minato\'s sudden reappearance?'),
(660, '602288', 'ko', 'https://image.tmdb.org/t/p/w500/xHxO4K0Fxqh9VgmSUxMKT3ztvox.jpg', '여고괴담 여섯번째 이야기: 모교', '79.88', '2021-06-17', 7.7, '14', '[\'Horror\']', 'Eun-hee is hired as a vice principal at her old high school, where strange things take place in the closed down washroom. High school student Ha-young and So-yeon, who used the washroom as their hideout hear humming in the empty washroom, and believe that a ghost exists inside. Ha-young discovers a flowerpot on the stairs and suspect that Eun-hee is somehow linked to the mystery. Suffering from hallucination upon her inauguration, Eun-hee finds a ghastly figured girl in the washroom mirror and begins to believe that the girl was the one who brought her back to this school…'),
(661, '49849', 'en', 'https://image.tmdb.org/t/p/w500/9uZsGCP4rvOHVGCpMpYq5gNCuNI.jpg', 'Cowboys & Aliens', '71.58', '2011-07-29', 5.5, '4124', '[\'Action\', \'Science Fiction\', \'Thriller\', \'Western\']', 'A stranger stumbles into the desert town of Absolution with no memory of his past and a futuristic shackle around his wrist. With the help of mysterious beauty Ella and the iron-fisted Colonel Dolarhyde, he finds himself leading an unlikely posse of cowboys, outlaws, and Apache warriors against a common enemy from beyond this world in an epic showdown for survival.'),
(662, '75656', 'en', 'https://image.tmdb.org/t/p/w500/oD3Eey4e4Z259XLm3eD3WGcoJAh.jpg', 'Now You See Me', '85.28', '2013-05-29', 7.4, '13133', '[\'Thriller\', \'Crime\']', 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.'),
(663, '117251', 'en', 'https://image.tmdb.org/t/p/w500/6TeIVKPw7nXXWy2zKmDmlnSwzb7.jpg', 'White House Down', '77.476', '2013-06-27', 6.4, '3838', '[\'Action\', \'Drama\', \'Thriller\']', 'Capitol Policeman John Cale has just been denied his dream job with the Secret Service of protecting President James Sawyer. Not wanting to let down his little girl with the news, he takes her on a tour of the White House, when the complex is overtaken by a heavily armed paramilitary group. Now, with the nation\'s government falling into chaos and time running out, it\'s up to Cale to save the president, his daughter, and the country.'),
(664, '197158', 'pt', 'https://image.tmdb.org/t/p/w500/bhbPSpYjsRJAK7rXqL8APK9EwBl.jpg', 'Pornô!', '88.33', '1981-01-01', 4.5, '42', '[\'Drama\']', 'Three tales of the erotic: Two young ladies experiment with lesbianism, a handsome and wealthy socialite makes a beautiful woman patiently wait to make love to him, and a gorgeous, but controlling and dominating blind woman makes a hunky stud her sexual hostage in her swanky mansion home.'),
(665, '775943', 'es', 'https://image.tmdb.org/t/p/w500/yDCIUtqZDc9JCKuxRGiqwMuDjUE.jpg', 'Llanto Maldito', '119.624', '2021-07-29', 3.7, '6', '[\'Horror\']', 'Sara and Óscar, a couple going through a marital crisis, decide to spend a week in a remote country cabin with their two children, Alicia and Tomás. The family tries to have a quiet time, but something strange happens there. There is a woman who prowls through the forest and cries uncontrollably looking for a baby she has just lost. This deeply affects the family who will have to stay together to survive this nightmare.'),
(666, '616651', 'en', 'https://image.tmdb.org/t/p/w500/1lrPR7ah1KElPKnCsxmIRE1OlIh.jpg', 'Stillwater', '73.947', '2021-07-29', 7, '349', '[\'Drama\', \'Crime\', \'Thriller\']', 'Bill Baker, an American oil-rig roughneck from Oklahoma, travels to Marseille to visit his estranged daughter, Allison, who is in prison for a murder she claims she did not commit. Confronted with language barriers, cultural differences, and a complicated legal system, Bill builds a new life for himself in France as he makes it his personal mission to exonerate his daughter.'),
(667, '265208', 'en', 'https://image.tmdb.org/t/p/w500/zN80Tlly8oMpKbVJv2TfRIj8dHG.jpg', 'Wild Card', '64.141', '2015-01-14', 5.6, '1389', '[\'Thriller\', \'Crime\', \'Action\']', 'When a Las Vegas bodyguard with lethal skills and a gambling problem gets in trouble with the mob, he has one last play… and it\'s all or nothing.'),
(668, '206647', 'en', 'https://image.tmdb.org/t/p/w500/zj8ongFhtWNsVlfjOGo8pSr7PQg.jpg', 'Spectre', '110.665', '2015-10-26', 6.5, '8662', '[\'Action\', \'Adventure\', \'Thriller\']', 'A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.'),
(669, '404368', 'en', 'https://image.tmdb.org/t/p/w500/iVCrhBcpDaHGvv7CLYbK6PuXZo1.jpg', 'Ralph Breaks the Internet', '80.184', '2018-11-20', 7.2, '5867', '[\'Family\', \'Animation\', \'Comedy\', \'Adventure\']', 'Video game bad guy Ralph and fellow misfit Vanellope von Schweetz must risk it all by traveling to the World Wide Web in search of a replacement part to save Vanellope\'s video game, Sugar Rush. In way over their heads, Ralph and Vanellope rely on the citizens of the internet — the netizens — to help navigate their way, including an entrepreneur named Yesss, who is the head algorithm and the heart and soul of trend-making site BuzzzTube.'),
(670, '14306', 'en', 'https://image.tmdb.org/t/p/w500/pnB6hjTKylb0Ve2nUWt16gzkErr.jpg', 'Marley & Me', '75.306', '2008-12-25', 7.2, '3780', '[\'Comedy\', \'Family\']', 'A newly married couple who, in the process of starting a family, learn many of life\'s important lessons from their trouble-loving retriever, Marley. Packed with plenty of laughs to lighten the load, the film explores the highs and lows of marriage, maturity and confronting one\'s own mortality, as seen through the lens of family life with a dog.'),
(671, '665251', 'ja', 'https://image.tmdb.org/t/p/w500/vlIYzx7cc4Wvaoh7ShjF2HZG45.jpg', 'オルタード・カーボン：リスリーブド', '93.033', '2020-03-19', 6.5, '186', '[\'Animation\', \'Science Fiction\']', 'On the planet Latimer, Takeshi Kovacs must protect a tattooist while investigating the death of a yakuza boss alongside a no-nonsense CTAC.'),
(672, '433422', 'ja', 'https://image.tmdb.org/t/p/w500/4CtvjdvuRj3iPlvtpvFomhTxjXR.jpg', '劇場版 FAIRY TAIL 『DRAGON CRY』', '90.944', '2017-05-06', 6.5, '341', '[\'Action\', \'Adventure\', \'Comedy\', \'Fantasy\', \'Animation\']', 'Natsu Dragneel and his friends travel to the island Kingdom of Stella, where they will reveal dark secrets, fight the new enemies and once again save the world from destruction.'),
(673, '436931', 'ja', 'https://image.tmdb.org/t/p/w500/b4U689nUPUtER5Qh1MNlLRPeh8q.jpg', '劇場版 ポケットモンスター キミにきめた！', '79.994', '2017-07-15', 7, '474', '[\'Family\', \'Animation\', \'Adventure\', \'Fantasy\']', 'Ash Ketchum wakes up late one morning after having broken his alarm clock in his sleep. He eventually makes it to Professor Oak\'s lab, but is told that the three starter List of Pokémon (Bulbasaur, Squirtle, and Charmander) have already been taken by Trainers who were on time. However, Oak reveals that he has one more Pokémon, an Electric-type named Pikachu. Despite its volatile and feisty personality, as well as its refusal to get inside a Poké Ball, Ash happily takes Pikachu for his journey.'),
(674, '681260', 'en', 'https://image.tmdb.org/t/p/w500/tMS2qcbhbkFpcwLnbUE9o9IK4HH.jpg', 'Maya the Bee: The Golden Orb', '77.902', '2021-01-07', 6.6, '62', '[\'Adventure\', \'Animation\', \'Family\']', 'When Maya, a headstrong little bee, and her best friend Willi, rescue an ant princess they find themselves in the middle of an epic bug battle that will take them to strange new worlds and test their friendship to its limits.'),
(675, '64635', 'en', 'https://image.tmdb.org/t/p/w500/wVbeL6fkbTKSmNfalj4VoAUUqJv.jpg', 'Total Recall', '75.182', '2012-08-02', 6, '4481', '[\'Action\', \'Science Fiction\', \'Adventure\', \'Thriller\']', 'Welcome to Rekall, the company that can turn your dreams into real memories. For a factory worker named Douglas Quaid, even though he\'s got a beautiful wife who he loves, the mind-trip sounds like the perfect vacation from his frustrating life - real memories of life as a super-spy might be just what he needs. But when the procedure goes horribly wrong, Quaid becomes a hunted man. Finding himself on the run from the police - controlled by Chancellor Cohaagen, the leader of the free world - Quaid teams up with a rebel fighter to find the head of the underground resistance and stop Cohaagen. The line between fantasy and reality gets blurred and the fate of his world hangs in the balance as Quaid discovers his true identity, his true love, and his true fate.'),
(676, '74513', 'fr', 'https://image.tmdb.org/t/p/w500/xpe9F3214mNrk8tnIqZvHSmIV1I.jpg', 'Forces spéciales', '89.43', '2011-11-02', 6.7, '397', '[\'Action\', \'Drama\', \'War\']', 'Afghanistan. War correspondent Elsa Casanova is taken hostage by the Taliban. Faced with her imminent execution, a Special Forces unit is dispatched to free her. In some of the world’s most breathtaking yet hostile landscapes, a relentless pursuit begins between her kidnappers who have no intention of letting their prey escape them and a group of soldiers who risk their lives in pursuit of their single aim – to bring her home alive. This strong, independent woman and these men of duty are thrown together and forced to confront situations of great danger that inextricably bind them – emotionally, violently and intimately.'),
(677, '10202', 'en', 'https://image.tmdb.org/t/p/w500/2PljsqbhxrFUzfTnaVhsseHhXN0.jpg', 'Bedtime Stories', '72.573', '2008-12-24', 6.1, '2285', '[\'Fantasy\', \'Comedy\', \'Family\', \'Romance\']', 'Skeeter Bronson is a down-on-his-luck guy who\'s always telling bedtime stories to his niece and nephew. But his life is turned upside down when the fantastical stories he makes up for entertainment inexplicably turn into reality. Can a bewildered Skeeter manage his own unruly fantasies now that the outrageous characters and situations from his mind have morphed into actual people and events?'),
(678, '38700', 'en', 'https://image.tmdb.org/t/p/w500/y95lQLnuNKdPAzw9F9Ab8kJ80c3.jpg', 'Bad Boys for Life', '77.044', '2020-01-15', 7.2, '6624', '[\'Thriller\', \'Action\', \'Crime\']', 'Marcus and Mike are forced to confront new threats, career changes, and midlife crises as they join the newly created elite team AMMO of the Miami police department to take down the ruthless Armando Armas, the vicious leader of a Miami drug cartel.'),
(679, '30789', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'Venom', '64.197', '1981-11-28', 6.2, '50', '[\'Horror\', \'Thriller\']', 'International terrorists attempt to kidnap a wealthy couple\'s child. Their plan comes unstuck when a deadly Black Mamba, sent by mistake instead of a harmless snake, escapes and the terrorists and several hostages are trapped in the boy\'s London home.'),
(680, '412117', 'en', 'https://image.tmdb.org/t/p/w500/s9xg4V5EDKiphgIksVJ9gewBM11.jpg', 'The Secret Life of Pets 2', '77.592', '2019-05-24', 7, '2301', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Max the terrier must cope with some major life changes when his owner gets married and has a baby. When the family takes a trip to the countryside, nervous Max has numerous run-ins with canine-intolerant cows, hostile foxes and a scary turkey. Luckily for Max, he soon catches a break when he meets Rooster, a gruff farm dog who tries to cure the lovable pooch of his neuroses.'),
(681, '265712', 'ja', 'https://image.tmdb.org/t/p/w500/wc7XQbfx6EIQqCuvmBMt3aisb2Y.jpg', 'STAND BY ME ドラえもん', '80.677', '2014-08-08', 7.3, '312', '[\'Animation\', \'Family\', \'Science Fiction\', \'Fantasy\']', 'In the suburbs of Tokyo some time ago, there lived a clumsy boy about 10 years old. There appeared in front of him named Sewashi, Nobita\'s descendant of four generations later from the 22nd century, and Doraemon, a 22nd century cat-type caretaker robot who helps people with its secret gadgets. Sewashi claims that his family is suffering from the debts Nobita made even to his generation, so in order to change this disastrous future, he brought along Doraemon as Nobita\'s caretaker to bring happiness to his future, although Doraemon is not happy about this. And so Sewashi installed an accomplishment program into Doraemon forcing him to take care of Nobita. Unless he makes Nobita happy, Doraemon can no longer go back to the 22nd century. This is how the life of Doraemon and Nobita begins. Will Doraemon succeed this mission and return to the 22nd century?'),
(682, '408', 'en', 'https://image.tmdb.org/t/p/w500/3VAHfuNb6Z7UiW12iYKANSPBl8m.jpg', 'Snow White and the Seven Dwarfs', '79.049', '1938-02-04', 7.1, '5903', '[\'Fantasy\', \'Animation\', \'Family\']', 'A beautiful girl, Snow White, takes refuge in the forest in the house of seven dwarfs to hide from her stepmother, the wicked Queen. The Queen is jealous because she wants to be known as \"the fairest in the land,\" and Snow White\'s beauty surpasses her own.'),
(683, '18095', 'ja', 'https://image.tmdb.org/t/p/w500/reNPMjkPg9f6wgf6kHSSkKjBarL.jpg', 'ドラゴンボールGT 悟空外伝! 勇気の証しは四星球(スーシンチュウ)', '85.137', '1997-03-26', 6.7, '208', '[\'Animation\', \'Family\', \'Fantasy\']', 'Son Goku Jr. is the great-great-great-great-grandson of the legendary martial artist Son Goku. However, unlike his predecessor he\'s not a brave fighter. He\'s constantly picked on by school bullies, his grandmother Pan sees this and she\'s worried, but even though Goku Jr. is not a strong and powerful Saiyan, he has a kind heart, and Pan loves him. When Pan gets sick Goku Jr. realizes he must do something if he doesn\'t want to lose Pan. Then he will remember about the legends of the Dragon Balls. It was told they granted a wish to the bearer, Goku Jr. needs a magical wish more than ever.'),
(684, '800305', 'pt', 'https://image.tmdb.org/t/p/w500/h9onDM7U8KCv2nXQNCCayuGzt4z.jpg', 'O Menino Que Matou Meus Pais', '78.527', '2021-09-24', 6.4, '118', '[\'Crime\', \'Drama\', \'Thriller\']', 'Based on one of the most shocking and gruesome murder cases in Brazil, the film presents de Suzane von Richthofen\'s point of view of the events that led to the death of her parents.'),
(685, '509635', 'en', 'https://image.tmdb.org/t/p/w500/tExdDYmxqv30rtf2dMkTAVpzORf.jpg', 'Alone', '73.648', '2020-09-10', 6.2, '357', '[\'Thriller\', \'Horror\', \'Drama\']', 'A recently widowed traveler is kidnapped by a cold blooded killer, only to escape into the wilderness where she is forced to battle against the elements as her pursuer closes in on her.'),
(686, '788929', 'is', 'https://image.tmdb.org/t/p/w500/gP9yviboTGWGolqUZKIB1UkF1C2.jpg', 'Dýrið', '70.048', '2021-08-12', 6.7, '102', '[\'Drama\', \'Horror\', \'Mystery\']', 'An Icelandic couple live with their herd of sheep on a beautiful but remote farm. When they discover a mysterious newborn on their land, they decide to keep it and raise it as their own. This unexpected development and the prospects of a new family brings them much joy before ultimately destroying them.'),
(687, '13971', 'en', 'https://image.tmdb.org/t/p/w500/xwbFEPubG4wroLDZdmTWRGNnnWf.jpg', 'Wild Child', '75.028', '2008-08-15', 6.7, '1525', '[\'Comedy\', \'Drama\', \'Romance\']', 'Sixteen-year-old Poppy has everything her unlimited credit cards can buy, and a spoiled attitude to match. After a final thoughtless prank, her exasperated father ships her off to boarding school in England. There, Poppy meets her match in a stern headmistress and a class full of girls who will not tolerate her selfishness.'),
(688, '621870', 'en', 'https://image.tmdb.org/t/p/w500/qnO3aXSqkKCDw5cEVyNUDexI4NJ.jpg', 'Secret Society of Second Born Royals', '82.866', '2020-09-25', 6.9, '395', '[\'Action\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'Sam is a teenage royal rebel, second in line to the throne of the kingdom of Illyria. Just as her disinterest in the royal way of life is at an all-time high, she discovers she has super-human abilities and is invited to join a secret society of similar extraordinary second-born royals charged with keeping the world safe.'),
(689, '166426', 'en', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', 'Pirates of the Caribbean: Dead Men Tell No Tales', '95.012', '2017-05-23', 6.6, '9638', '[\'Adventure\', \'Action\', \'Fantasy\']', 'Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil\'s Triangle. Jack\'s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.'),
(690, '42684', 'en', 'https://image.tmdb.org/t/p/w500/C5g4AyBeDxrihWjSCrOdSD2cOd.jpg', 'Skyline', '71.804', '2010-11-11', 4.9, '1230', '[\'Science Fiction\', \'Action\']', 'When strange lights descend on the city of Los Angeles, people are drawn outside like moths to a flame where an extraterrestrial force threatens to swallow the entire human population off the face of the Earth. Now the band of survivors must fight for their lives as the world unravels around them.'),
(691, '454983', 'en', 'https://image.tmdb.org/t/p/w500/vcQNnnXgKLacoYF4LNWgkNiDXPd.jpg', 'The Kissing Booth', '82.912', '2018-05-11', 7.3, '6288', '[\'Romance\', \'Comedy\']', 'When teenager Elle\'s first kiss leads to a forbidden romance with the hottest boy in high school, she risks her relationship with her best friend.'),
(692, '119698', 'en', 'https://image.tmdb.org/t/p/w500/qmMoPP8hSFbxzLn3Tt9UonPsma9.jpg', 'The Dinosaur Project', '63.75', '2012-08-09', 5.2, '171', '[\'Adventure\', \'Action\']', 'Found footage of an expedition into the Congo jungle where a team of explorers stumbles upon a colony of Dinosaurs.'),
(693, '726739', 'en', 'https://image.tmdb.org/t/p/w500/4BgSWFMW2MJ0dT5metLzsRWO7IJ.jpg', 'Cats & Dogs 3: Paws Unite', '76.081', '2020-10-02', 6.6, '149', '[\'Comedy\', \'Action\']', 'It\'s been ten years since the creation of the Great Truce, an elaborate joint-species surveillance system designed and monitored by cats and dogs to keep the peace when conflicts arise. But when a tech-savvy villain hacks into wireless networks to use frequencies only heard by cats and dogs, he manipulates them into conflict and the worldwide battle between cats and dogs is BACK ON. Now, a team of inexperienced and untested agents will have to use their old-school animal instincts to restore order and peace between cats and dogs everywhere.'),
(694, '20526', 'en', 'https://image.tmdb.org/t/p/w500/vuifSABRpSnxCAOxEnWpNbZSXpp.jpg', 'TRON: Legacy', '83.204', '2010-12-14', 6.4, '5742', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'Sam Flynn, the tech-savvy and daring son of Kevin Flynn, investigates his father\'s disappearance and is pulled into The Grid. With the help of a mysterious program named Quorra, Sam quests to stop evil dictator Clu from crossing into the real world.'),
(695, '268896', 'en', 'https://image.tmdb.org/t/p/w500/nFWhttU8PM50t25NPdy7PE7rv3G.jpg', 'Pacific Rim: Uprising', '78.562', '2018-03-21', 6.1, '3786', '[\'Action\', \'Fantasy\', \'Science Fiction\', \'Adventure\']', 'It has been ten years since The Battle of the Breach and the oceans are still, but restless. Vindicated by the victory at the Breach, the Jaeger program has evolved into the most powerful global defense force in human history. The PPDC now calls upon the best and brightest to rise up and become the next generation of heroes when the Kaiju threat returns.'),
(696, '522938', 'en', 'https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', 'Rambo: Last Blood', '73.971', '2019-09-19', 6.5, '2840', '[\'Action\', \'Thriller\', \'Drama\']', 'After fighting his demons for decades, John Rambo now lives in peace on his family ranch in Arizona, but his rest is interrupted when Gabriela, the granddaughter of his housekeeper María, disappears after crossing the border into Mexico to meet her biological father. Rambo, who has become a true father figure for Gabriela over the years, undertakes a desperate and dangerous journey to find her.'),
(697, '613200', 'zh', 'https://image.tmdb.org/t/p/w500/ibaBs2k3I57TIHd6rBOxhWdHmcv.jpg', '全职高手之巅峰荣耀', '83.69', '2019-08-16', 7.2, '14', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\']', 'Prequel movie to the animated series The King\'s Avatar, dealing with Ye Xiu\'s original entry into the pro gaming world of Glory, and the first Pro League series tournament.'),
(698, '19840', 'en', 'https://image.tmdb.org/t/p/w500/mUi6nEbo04DR1YwflbZX1RR7UwS.jpg', 'I Love You, Beth Cooper', '69.49', '2009-07-10', 5.9, '643', '[\'Comedy\', \'Romance\']', 'A valedictorian\'s declaration of love for a high-school cheerleader launches a night of revelry, reflection and romance for a group of graduating seniors.'),
(699, '270946', 'en', 'https://image.tmdb.org/t/p/w500/dXbpNrPDZDMEbujFoOxmMNQVMHa.jpg', 'Penguins of Madagascar', '84.255', '2014-11-22', 6.5, '3265', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\']', 'Skipper, Kowalski, Rico and Private join forces with undercover organization The North Wind to stop the villainous Dr. Octavius Brine from destroying the world as we know it.'),
(700, '16995', 'en', 'https://image.tmdb.org/t/p/w500/mWsfeSFUM3NxWa62UrA9IIn240B.jpg', 'State of Play', '80.719', '2009-04-17', 6.8, '1419', '[\'Thriller\', \'Drama\']', 'Handsome, unflappable U.S. Congressman Stephen Collins is the future of his political party: an honorable appointee who serves as the chairman of a committee overseeing defense spending. All eyes are upon the rising star to be his party\'s contender for the upcoming presidential race. Until his research assistant/mistress is brutally murdered and buried secrets come tumbling out.'),
(701, '37430', 'en', 'https://image.tmdb.org/t/p/w500/qw2A587Ee61IwcSOLNFRhuOACZZ.jpg', 'Conan the Barbarian', '82.166', '2011-08-17', 5.3, '1452', '[\'Adventure\', \'Fantasy\', \'Action\']', 'A quest that begins as a personal vendetta for the fierce Cimmerian warrior soon turns into an epic battle against hulking rivals, horrific monsters, and impossible odds, as Conan (Jason Momoa) realizes he is the only hope of saving the great nations of Hyboria from an encroaching reign of supernatural evil.'),
(702, '396422', 'en', 'https://image.tmdb.org/t/p/w500/tb86j8jVCVsdZnzf8I6cIi65IeM.jpg', 'Annabelle: Creation', '75.165', '2017-08-03', 6.6, '4522', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Several years after the tragic death of their little girl, a doll maker and his wife welcome a nun and several girls from a shuttered orphanage into their home, soon becoming the target of the doll maker\'s possessed creation—Annabelle.'),
(703, '62211', 'en', 'https://image.tmdb.org/t/p/w500/y7thwJ7z5Bplv6vwl6RI0yteaDD.jpg', 'Monsters University', '77.608', '2013-06-19', 7, '8643', '[\'Animation\', \'Family\']', 'A look at the relationship between Mike and Sulley during their days at Monsters University — when they weren\'t necessarily the best of friends.'),
(704, '11970', 'en', 'https://image.tmdb.org/t/p/w500/sKNIwY6UENCJ36FvYvnBW3Vdzt7.jpg', 'Hercules', '71.102', '1997-06-20', 7.5, '5876', '[\'Animation\', \'Family\', \'Fantasy\', \'Adventure\', \'Comedy\', \'Romance\']', 'Bestowed with superhuman strength, a young mortal named Hercules sets out to prove himself a hero in the eyes of his father, the great god Zeus. Along with his friends Pegasus, a flying horse, and Phil, a personal trainer, Hercules is tricked by the hilarious, hotheaded villain Hades, who\'s plotting to take over Mount Olympus!'),
(705, '17581', 'ja', 'https://image.tmdb.org/t/p/w500/bBqEiQbbfyt4MWR3NhDZMbS4Wp8.jpg', '劇場版 NARUTO -ナルト- 疾風伝 絆', '78.683', '2008-08-02', 7.2, '266', '[\'Fantasy\', \'Animation\', \'Action\']', 'A mysterious group of ninjas makes a surprise attack on the Konohagakure, which takes great damage. The nightmare of another Shinobi World War could become a reality. Sasuke, who was still a missing nin from Konoha trying to kill his brother, Itachi, appears for the second time in front of Naruto at an unknown location to prevent it from happening.'),
(706, '39101', 'ja', 'https://image.tmdb.org/t/p/w500/fDX4Dp8IKvjBAaEb5MOJrGkxWX0.jpg', 'ドラゴンボールZ 地球まるごと超決戦', '80.178', '1990-06-07', 6.5, '383', '[\'Action\', \'Animation\', \'Science Fiction\']', 'Goku and friends must stop a band of space pirates from consuming fruit from the Tree of Might before it\'s destructive powers drain Earth\'s energy.'),
(707, '446893', 'en', 'https://image.tmdb.org/t/p/w500/7W0G3YECgDAfnuiHG91r8WqgIOe.jpg', 'Trolls World Tour', '80.845', '2020-03-11', 7.5, '1643', '[\'Family\', \'Animation\', \'Comedy\', \'Fantasy\', \'Adventure\', \'Music\']', 'Queen Poppy and Branch make a surprising discovery — there are other Troll worlds beyond their own, and their distinct differences create big clashes between these various tribes. When a mysterious threat puts all of the Trolls across the land in danger, Poppy, Branch, and their band of friends must embark on an epic quest to create harmony among the feuding Trolls to unite them against certain doom.'),
(708, '51876', 'en', 'https://image.tmdb.org/t/p/w500/kCokPP4WCQRrrAuZ7FcpIyHr8b2.jpg', 'Limitless', '74.01', '2011-03-08', 7.2, '8591', '[\'Thriller\', \'Mystery\', \'Science Fiction\']', 'A paranoia-fueled action thriller about an unsuccessful writer whose life is transformed by a top-secret \"smart drug\" that allows him to use 100% of his brain and become a perfect version of himself. His enhanced abilities soon attract shadowy forces that threaten his new life in this darkly comic and provocative film.'),
(709, '709629', 'es', 'https://image.tmdb.org/t/p/w500/jpdWHOu6EJbYnLXLCA52h82nLEz.jpg', 'Guerra de Likes', '70.438', '2021-03-12', 7.8, '219', '[\'Comedy\']', 'In order to advance her career in the dynamic world of publicity in Mexico City, Raquel tries to reunite with her high school friend Cecy who has become the queen of social media. But unlike followers, friendships do not come instantly.'),
(710, '240832', 'en', 'https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg', 'Lucy', '66.751', '2014-07-25', 6.4, '13512', '[\'Action\', \'Science Fiction\']', 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.'),
(711, '768334', 'it', 'https://image.tmdb.org/t/p/w500/bifYmCujLshZo4qVdmUpP7Q2iLn.jpg', 'A Classic Horror Story', '75.424', '2021-07-14', 6, '515', '[\'Drama\', \'Horror\', \'Mystery\', \'Comedy\']', 'Five carpoolers travel in a motorhome to reach a common destination. Night falls, and to avoid a dead animal carcass, they crash into a tree. When they come to their senses, they find themselves in the middle of nowhere. The road they were traveling on has disappeared and there is only a dense, impenetrable forest and a wooden house in the middle of a clearing, which they discover is the home of a spine-chilling cult.'),
(712, '853088', 'en', 'https://image.tmdb.org/t/p/w500/m0f9sDiwYlEtfhUWxc5F2ZW7wfq.jpg', 'Happier Than Ever: A Love Letter to Los Angeles', '77.252', '2021-09-03', 7.9, '57', '[\'Documentary\', \'Music\', \'Animation\']', 'Fresh off the heels of her brand-new album, \"Happier Than Ever,\" this cinematic concert experience features an intimate performance of every song in the album\'s sequential order – for the first and only time – from the stage of the legendary Hollywood Bowl.'),
(713, '9552', 'en', 'https://image.tmdb.org/t/p/w500/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg', 'The Exorcist', '68.992', '1973-05-31', 7.7, '5954', '[\'Horror\']', '12-year-old Regan MacNeil begins to adapt an explicit new personality as strange events befall the local area of Georgetown. Her mother becomes torn between science and superstition in a desperate bid to save her daughter, and ultimately turns to her last hope: Father Damien Karras, a troubled priest who is struggling with his own faith.'),
(714, '150540', 'en', 'https://image.tmdb.org/t/p/w500/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', 'Inside Out', '74.044', '2015-06-09', 7.9, '17090', '[\'Animation\', \'Family\', \'Adventure\', \'Drama\', \'Comedy\']', 'Growing up can be a bumpy road, and it\'s no exception for Riley, who is uprooted from her Midwest life when her father starts a new job in San Francisco. Riley\'s guiding emotions— Joy, Fear, Anger, Disgust and Sadness—live in Headquarters, the control centre inside Riley\'s mind, where they help advise her through everyday life and tries to keep things positive, but the emotions conflict on how best to navigate a new city, house and school.'),
(715, '150689', 'en', 'https://image.tmdb.org/t/p/w500/j91LJmcWo16CArFOoapsz84bwxb.jpg', 'Cinderella', '78.934', '2015-03-12', 6.8, '6036', '[\'Romance\', \'Fantasy\', \'Family\', \'Drama\']', 'When her father unexpectedly passes away, young Ella finds herself at the mercy of her cruel stepmother and her daughters. Never one to give up hope, Ella\'s fortunes begin to change after meeting a dashing stranger in the woods.'),
(716, '297761', 'en', 'https://image.tmdb.org/t/p/w500/sk3FZgh3sRrmr8vyhaitNobMcfh.jpg', 'Suicide Squad', '76.03', '2016-08-03', 5.9, '18110', '[\'Action\', \'Adventure\', \'Fantasy\']', 'From DC Comics comes the Suicide Squad, an antihero team of incarcerated supervillains who act as deniable assets for the United States government, undertaking high-risk black ops missions in exchange for commuted prison sentences.'),
(717, '10567', 'en', 'https://image.tmdb.org/t/p/w500/rSje3FS7ycJSglowlngjsvDt7vO.jpg', 'Dinosaur', '72.501', '2000-05-19', 6.5, '1885', '[\'Family\', \'Animation\']', 'An orphaned dinosaur raised by lemurs joins an arduous trek to a sancturary after a meteorite shower destroys his family home.'),
(718, '76163', 'en', 'https://image.tmdb.org/t/p/w500/74rTIGyGoIu5KSxDVMdr8H3MtMo.jpg', 'The Expendables 2', '67.1', '2012-08-08', 6.3, '5468', '[\'Action\', \'Adventure\', \'Thriller\']', 'Mr. Church reunites the Expendables for what should be an easy paycheck, but when one of their men is murdered on the job, their quest for revenge puts them deep in enemy territory and up against an unexpected threat.'),
(719, '136418', 'en', 'https://image.tmdb.org/t/p/w500/bN2aGUOxHRwGms68WTDr2MHzkKa.jpg', 'Hummingbird', '77.843', '2013-05-07', 6.2, '1282', '[\'Action\', \'Thriller\']', 'Homeless and on the run from a military court martial, a damaged ex-special forces soldier navigating London\'s criminal underworld seizes an opportunity to assume another man\'s identity, transforming into an avenging angel in the process.'),
(720, '52520', 'en', 'https://image.tmdb.org/t/p/w500/jN0uuc8U6M3sTg9zEaliJV60Stf.jpg', 'Underworld: Awakening', '69.313', '2012-01-19', 6.3, '3333', '[\'Fantasy\', \'Action\', \'Horror\']', 'Having escaped years of imprisonment, vampire warrioress Selene finds herself in a changed world where humans have discovered the existence of both Vampire and Lycan clans and are conducting an all-out war to eradicate both immortal species. Now Selene must battle the humans and a frightening new breed of super Lycans to ensure the death dealers\' survival.'),
(721, '719923', 'ko', 'https://i.ytimg.com/vi/mxlloUcfUy0/maxresdefault.jpg', 'TXT (투모로우바이투게더) \'Eternally\'', '69.673', '', 8, '3', '[\'Drama\']', 'Eternally is the sixth and final track of the album The Dream Chapter: ETERNITY by South Korean boy group TXT. The corresponding short film for the song was released on June 28th, 2020.'),
(722, '391757', 'en', 'https://image.tmdb.org/t/p/w500/pHVswTDHAvq9Npi0XCZ0qVMSiM2.jpg', 'Never Back Down: No Surrender', '66.838', '2016-06-05', 7, '345', '[\'Drama\', \'Action\']', 'Picking up after the events of Never Back Down 2, former MMA champion Case Walker is on the comeback trail to become champion once again.'),
(723, '364689', 'en', 'https://image.tmdb.org/t/p/w500/rMm94JsRfcOPiPVsTRcBiiVBOhz.jpg', 'Ferdinand', '74.041', '2017-12-09', 7.2, '2255', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'Ferdinand, a little bull, prefers sitting quietly under a cork tree just smelling the flowers versus jumping around, snorting, and butting heads with other bulls. As Ferdinand grows big and strong, his temperament remains mellow, but one day five men come to choose the \"biggest, fastest, roughest bull\" for the bullfights in Madrid and Ferdinand is mistakenly chosen.  Based on the classic 1936 children\'s book by Munro Leaf.'),
(724, '597398', 'en', 'https://resizing.flixster.com/r_y8oG7ZDNAEHDWo83KCHBEC37o=/ems.cHJkLWVtcy1hc3NldHMvbW92aWVzL2I2OWFmZmQ4LWIwMzItNDJiNy04NTQ3LTc5MjljNmU4ZTJlMy53ZWJw', 'Away', '72.848', '2019-11-15', 6.4, '50', '[\'Animation\', \'Drama\', \'Adventure\', \'Fantasy\']', 'After suffering a plane crash on a mysterious island, a young man embarks on an epic journey through forests, deserts and mountains trying to escape the shadow of a huge dark spirit.'),
(725, '21208', 'en', 'https://image.tmdb.org/t/p/w500/lCGpOgoTOGLtZnBiGY9HRg5Xnjd.jpg', 'Orphan', '67.704', '2009-07-24', 6.9, '3830', '[\'Horror\', \'Thriller\', \'Mystery\']', 'After losing their baby, a married couple adopt 9-year old Esther, who may not be as innocent as she seems.'),
(726, '46528', 'en', 'https://image.tmdb.org/t/p/w500/otjBqNDpZ3C9mzfDOI4kaiib3Qd.jpg', 'The Warrior\'s Way', '73.801', '2010-12-01', 6.5, '408', '[\'Adventure\', \'Fantasy\', \'Action\', \'Western\', \'Thriller\']', 'A warrior-assassin is forced to hide in a small town in the American Badlands after refusing a mission.'),
(727, '184345', 'en', 'https://image.tmdb.org/t/p/w500/oV7M00fPXy5P0nbdeMbSUjYv0vx.jpg', 'A Haunted House 2', '64.251', '2014-04-17', 6.1, '1012', '[\'Comedy\', \'Horror\']', 'After exorcising the demons of his ex-, Malcolm starts afresh with his new girlfriend and her two children. After moving into their dream home, Malcolm is once again plagued by bizarre paranormal events.'),
(728, '526896', 'en', 'https://image.tmdb.org/t/p/w500/Av8Z2jZhEm1FLkFzMThzz9hndJF.jpg', 'Morbius', '65.783', '2022-01-20', 0, '0', '[\'Horror\', \'Action\', \'Science Fiction\']', 'Dangerously ill with a rare blood disorder, and determined to save others suffering his same fate, Dr. Michael Morbius attempts a desperate gamble. What at first appears to be a radical success soon reveals itself to be a remedy potentially worse than the disease.'),
(729, '139038', 'en', 'https://image.tmdb.org/t/p/w500/tpw6kvuAJBo1CGRw1Bwdz1KU0hc.jpg', 'A Haunted House', '62.753', '2013-01-11', 5.7, '1342', '[\'Comedy\', \'Horror\']', 'Malcolm and Kisha move into their dream home, but soon learn a demon also resides there. When Kisha becomes possessed, Malcolm - determined to keep his sex life on track - turns to a priest, a psychic, and a team of ghost-busters for help in this spoof of all the \"found-footage/documentary style\" films released in recent years.'),
(730, '10521', 'en', 'https://image.tmdb.org/t/p/w500/eyXT8tmUoyHrg7YX1UVjmecHCWP.jpg', 'Bride Wars', '70.737', '2009-01-09', 6.2, '2487', '[\'Comedy\', \'Romance\']', 'Two best friends become rivals when their respective weddings are accidentally booked for the same day.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(731, '48340', 'en', 'https://image.tmdb.org/t/p/w500/zRUNv1CbeVtmTCNr6RLHnxV2QYm.jpg', 'Sanctum', '69.482', '2011-02-03', 5.9, '771', '[\'Action\', \'Thriller\']', 'Master diver Frank McGuire (Richard Roxburgh) has explored the South Pacific\'s Esa-ala Caves for months.  But when his exit is cut off in a flash flood, Frank\'s team—including 17-year-old son Josh (Rhys Wakefield) and financier Carl Hurley (Ioan Gruffudd)—are forced to radically alter plans.  With dwindling supplies, the crew must navigate an underwater labyrinth to make it out.  Soon, they are confronted with the unavoidable question: Can they survive, or will they be trapped forever?'),
(732, '37135', 'en', 'https://image.tmdb.org/t/p/w500/bTvHlcqiOjGa3lFtbrTLTM3zasY.jpg', 'Tarzan', '73.426', '1999-06-18', 7.4, '5329', '[\'Family\', \'Adventure\', \'Animation\', \'Drama\']', 'Tarzan was a small orphan who was raised by an ape named Kala since he was a child. He believed that this was his family, but on an expedition Jane Porter is rescued by Tarzan. He then finds out that he\'s human. Now Tarzan must make the decision as to which family he should belong to...'),
(733, '594328', 'en', 'https://image.tmdb.org/t/p/w500/m5ZGqyTN8BMRO3OApuSWHBfyySg.jpg', 'Phineas and Ferb: The Movie: Candace Against the Universe', '70.451', '2020-08-28', 7.5, '276', '[\'Family\', \'Animation\', \'Science Fiction\', \'Comedy\', \'TV Movie\']', 'Phineas and Ferb travel across the galaxy to rescue their older sister Candace, who has been abducted by aliens and taken to a utopia in a far-off planet, free of her pesky little brothers.'),
(734, '179826', 'en', 'https://image.tmdb.org/t/p/w500/skBMhQjHLTU1rp4gutxHp0JuY1C.jpg', 'Odd Thomas', '68.412', '2013-01-29', 6.9, '921', '[\'Mystery\', \'Thriller\']', 'In a California desert town, a short-order cook with clairvoyant abilities encounters a mysterious man with a link to dark, threatening forces.'),
(735, '34544', 'en', 'https://image.tmdb.org/t/p/w500/bkAWEx5g5tvRPjtDQyvIZ7LRxQm.jpg', 'The A-Team', '80.338', '2010-06-09', 6.4, '3704', '[\'Thriller\', \'Action\', \'Adventure\', \'Comedy\', \'Crime\']', 'A group of Iraq War veterans goes on the run from U.S. military forces while they try to clear their names after being framed for a crime they didn\'t commit. Along the way, Col. Hannibal Smith, Capt. H.M. ‘Howling Mad’ Murdock , Sgt. Bosco ‘B.A.’ Baracus, and Lt. Templeton ‘Faceman’ Peck help out various people they encounter.'),
(736, '871858', 'en', 'https://image.tmdb.org/t/p/w500/iCzzCUgsFSlaEbgKKmJttSAUXGr.jpg', 'Justin Bieber: Our World', '74.099', '2021-10-08', 7.5, '12', '[\'Music\', \'Documentary\']', 'After a three-year hiatus from a full performance, and with concert venues shut down due to the pandemic, Bieber delivers an electrifying show to close out 2020 on the rooftop of the Beverly Hilton Hotel for 240 invited guests—and millions of fans across the globe watching via livestream. The film follows Bieber and his close-knit team in the month leading up to the show, as they rehearse and construct a monumental stage while adhering to strict health and safety protocols. The film also captures personal, self-shot moments between Bieber and his wife Hailey.'),
(737, '4256', 'en', 'https://image.tmdb.org/t/p/w500/lpNG1nx67rvYze1b1R9q0YoSzrC.jpg', 'Scary Movie 3', '68.507', '2003-10-24', 6, '3092', '[\'Comedy\']', 'In the third installment of the Scary Movie franchise, news anchorwoman Cindy Campbell has to investigate mysterious crop circles and killing video tapes, and help the President stop an alien invasion in the process.'),
(738, '346910', 'en', 'https://image.tmdb.org/t/p/w500/a3eWGF6YPF7No5Rbtjc8QpDvz7l.jpg', 'The Predator', '62.569', '2018-09-05', 5.6, '3537', '[\'Science Fiction\', \'Action\', \'Adventure\', \'Comedy\']', 'When a young child accidentally triggers extraterrestrial hunters to return to Earth, a ragtag crew of ex-soldiers and scientists join forces to prevent the end of the human race.'),
(739, '778814', 'en', 'https://image.tmdb.org/t/p/w500/2hx1ByfkqYTR8I5MBWzBkVXizsg.jpg', 'Daisy Quokka: World\'s Scariest Animal', '92.063', '2021-02-04', 6.7, '45', '[\'Animation\', \'Comedy\', \'Family\']', 'When an unbearably adorable, eternally optimistic Quokka named Daisy wants to achieve the impossible – to win the annual ‘World’s Scariest Animal’ championship, she enlists the guidance of a washed-up, former champion, a grouchy Saltwater Crocodile, to help her achieve her dreams and prove that champions can come in all sizes.'),
(740, '427641', 'en', 'https://image.tmdb.org/t/p/w500/MGADip4thVSErP34FAAfzFBTZ5.jpg', 'Rampage', '67.007', '2018-04-12', 6.5, '5579', '[\'Action\']', 'Primatologist Davis Okoye shares an unshakable bond with George, the extraordinarily intelligent, silverback gorilla who has been in his care since birth.  But a rogue genetic experiment gone awry mutates this gentle ape into a raging creature of enormous size.  To make matters worse, it’s soon discovered there are other similarly altered animals.  As these newly created alpha predators tear across North America, destroying everything in their path, Okoye teams with a discredited genetic engineer to secure an antidote, fighting his way through an ever-changing battlefield, not only to halt a global catastrophe but to save the fearsome creature that was once his friend.'),
(741, '10895', 'en', 'https://image.tmdb.org/t/p/w500/bnZJrLRnoQHpzEJdka1KYfsAF3N.jpg', 'Pinocchio', '78.323', '1940-02-23', 7.1, '4615', '[\'Animation\', \'Family\']', 'Lonely toymaker Geppetto has his wishes answered when the Blue Fairy arrives to bring his wooden puppet Pinocchio to life. Before becoming a real boy, however, Pinocchio must prove he\'s worthy as he sets off on an adventure with his whistling sidekick and conscience, Jiminy Cricket.'),
(742, '38757', 'en', 'https://image.tmdb.org/t/p/w500/ym7Kst6a4uodryxqbGOxmewF235.jpg', 'Tangled', '77.523', '2010-11-24', 7.6, '8920', '[\'Animation\', \'Family\']', 'When the kingdom\'s most wanted-and most charming-bandit Flynn Rider hides out in a mysterious tower, he\'s taken hostage by Rapunzel, a beautiful and feisty tower-bound teen with 70 feet of magical, golden hair. Flynn\'s curious captor, who\'s looking for her ticket out of the tower where she\'s been locked away for years, strikes a deal with the handsome thief and the unlikely duo sets off on an action-packed escapade, complete with a super-cop horse, an over-protective chameleon and a gruff gang of pub thugs.'),
(743, '259316', 'en', 'https://image.tmdb.org/t/p/w500/fLsaFKExQt05yqjoAvKsmOMYvJR.jpg', 'Fantastic Beasts and Where to Find Them', '81.471', '2016-11-16', 7.4, '15766', '[\'Adventure\', \'Fantasy\']', 'In 1926, Newt Scamander arrives at the Magical Congress of the United States of America with a magically expanded briefcase, which houses a number of dangerous creatures and their habitats. When the creatures escape from the briefcase, it sends the American wizarding authorities after Newt, and threatens to strain even further the state of magical and non-magical relations.'),
(744, '1579', 'en', 'https://image.tmdb.org/t/p/w500/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg', 'Apocalypto', '68.455', '2006-12-07', 7.5, '4116', '[\'Action\', \'Drama\', \'Thriller\', \'History\']', 'Set in the Mayan civilization, when a man\'s idyllic presence is brutally disrupted by a violent invading force, he is taken on a perilous journey to a world ruled by fear and oppression where a harrowing end awaits him. Through a twist of fate and spurred by the power of his love for his woman and his family he will make a desperate break to return home and to ultimately save his way of life.'),
(745, '453071', 'ja', 'https://image.tmdb.org/t/p/w500/7Zp4LaCbFNd1hxfxRDTdFqMzqxi.jpg', 'ナルトが火影になった日', '76.611', '2016-07-06', 7.6, '156', '[\'Comedy\', \'Animation\', \'Action\', \'Adventure\']', 'Depicts the day that Naruto Uzumaki became the 7th Hokage. Packaged with Boruto the Movie.'),
(746, '797394', 'ru', 'https://image.tmdb.org/t/p/w500/4ZSzEDVdxWVMVO4oZDvoodQOEfr.jpg', 'Ганзель, Гретель и Агентство Магии', '77.918', '2021-03-18', 7.2, '194', '[\'Animation\', \'Comedy\', \'Fantasy\']', 'The Secret Magic Control Agency sends its two best agents, Hansel and Gretel, to fight against the witch of the Gingerbread House.'),
(747, '575088', 'ru', 'https://image.tmdb.org/t/p/w500/sQF8UV3LrYtELqcJluckTOl9q4D.jpg', 'Яга. Кошмар тёмного леса', '70.117', '2020-02-27', 6.1, '160', '[\'Horror\']', 'The young family who moved to a new apartment on the outskirts of the city. The nanny hired by them for the newborn daughter quickly gained confidence. However, the older boy, Egor, talks about the frightening behavior of a woman, but his parents do not believe him. The surveillance cameras installed by the father for comfort only confirm everything is in order. Then one day, Egor, returning home, finds no trace of either the nanny or the little sister, and the parents are in a strange trance and do not even remember that they had a daughter. Then Egor, together with his friends, goes in search, during which it turns out that the nanny is an ancient Slavic demon, popularly known as Baba Yaga.'),
(748, '553835', 'ja', 'https://image.tmdb.org/t/p/w500/78x3RRydNXvdB8BhJAwZz42g1Q1.jpg', '劇場版 ダンジョンに出会いを求めるのは間違っているだろうか -オリオンの矢-', '83.852', '2019-02-15', 7.9, '140', '[\'Action\', \'Adventure\', \'Comedy\', \'Fantasy\', \'Romance\', \'Animation\']', 'In the city of Orario, beneath an impossibly tall tower, lies the dungeon. Only adventurers who form partnerships with the gods themselves have any hope of defeating the monsters that lie within. But the dungeon is not the only place where monsters exist. Far from Orario, in the ruins of an ancient city, a new threat arises. To counter this threat, the goddess Artemis has come to Orario in search of a champion—but it’s not Ais Wallenstein (the legendary Sword Princess) nor Ottar (the strongest warrior to ever enter the dungeon) that she chooses. Rather it is Bell Cranel, a newbie adventurer partnered with a low-tier goddess.'),
(749, '514439', 'en', 'https://image.tmdb.org/t/p/w500/lUd2FNC8cMCcHyRMNZtVC48p3xH.jpg', 'Breakthrough', '72.587', '2019-04-10', 7.7, '794', '[\'Drama\']', 'Tragedy strikes when a woman named Joyce\'s son falls through the ice on a frozen lake and is trapped underwater for over 15 minutes. After being rushed to the hospital, the 14-year-old boy continues to fight for his life as Joyce, her husband and their pastor stay by his bedside and pray for a miracle.'),
(750, '105965', 'en', 'https://image.tmdb.org/t/p/w500/fK3U8xulldz6lhMDuz3LFB7ngWH.jpg', 'Beverly Hills Chihuahua 3: Viva la Fiesta!', '80.521', '2012-09-03', 6.3, '189', '[\'Comedy\', \'Family\']', 'When Papi, Chloe, the pups, Uncle Pedro, and their owners move to a hotel, the smallest pup Rosa feels like she doesn\'t fit in, and Papi wants to make her feel better by showing her how special she is.'),
(751, '11544', 'en', 'https://image.tmdb.org/t/p/w500/ckQzKpQJO4ZQDCN5evdpKcfm7Ys.jpg', 'Lilo & Stitch', '74.064', '2002-06-21', 7.5, '4726', '[\'Animation\', \'Family\']', 'As Stitch, a runaway genetic experiment from a faraway planet, wreaks havoc on the Hawaiian Islands, he becomes the mischievous adopted alien \"puppy\" of an independent little girl named Lilo and learns about loyalty, friendship, and \'ohana, the Hawaiian tradition of family.'),
(752, '61927', 'en', 'https://image.tmdb.org/t/p/w500/uoQmK7FRXNIQa7sikGg1xM0QaN9.jpg', 'Porno Unplugged', '80.537', '2009-03-17', 6.2, '33', '[\'Documentary\']', 'Journalist Fabian Burstein looks behind the curtains of the porn industry. Starting in Budapest he heads westwards to explore a new world on its victory march rooted deeply in Austria. On this journey he meets the heroes and leading actors of this story: Austrians Mick Blue, Renee Pornero and Thomas Janisch. Porno Unplugged follows its native porn stars to where their lives happen. From east to west...'),
(753, '39104', 'ja', 'https://image.tmdb.org/t/p/w500/pIwjWaEuCcT3QVBd9Ng9wG3kbpU.jpg', 'ドラゴンボールＺ 極限バトル！三大超サイヤ人', '75.544', '1992-07-11', 6.7, '347', '[\'Action\', \'Animation\', \'Science Fiction\']', 'Dr. Gero\'s Androids #13, #14, and #15 are awakened by the laboratory computers and immediately head to the mall where Goku is shopping. After Goku, Trunks, and Vegeta defeat #14 and #15, #13 absorbs their inner computers and becomes a super being greater than the original three separately were. Now it is up to Goku to stop him.'),
(754, '18239', 'en', 'https://image.tmdb.org/t/p/w500/k2qTooPlHffgNABNWxeJdGMglPK.jpg', 'The Twilight Saga: New Moon', '78.69', '2009-11-18', 6, '7538', '[\'Adventure\', \'Fantasy\', \'Drama\', \'Romance\']', 'Forks, Washington resident Bella Swan is reeling from the departure of her vampire love, Edward Cullen, and finds comfort in her friendship with Jacob Black, a werewolf. But before she knows it, she\'s thrust into a centuries-old conflict, and her desire to be with Edward at any cost leads her to take greater and greater risks.'),
(755, '20048', 'en', 'https://image.tmdb.org/t/p/w500/r17R9OIC0pKDqqsNore6atYLCVZ.jpg', 'Confessions of a Shopaholic', '75.433', '2009-02-05', 6.4, '2223', '[\'Comedy\', \'Romance\']', 'In the glamorous world of New York City, Rebecca Bloomwood is a fun-loving girl who is really good at shopping-a little too good, perhaps. She dreams of working for her favorite fashion magazine, but can\'t quite get her foot in the door-until ironically, she snags a job as an advice columnist for a financial magazine published by the same company.'),
(756, '10009', 'en', 'https://image.tmdb.org/t/p/w500/otptPbEY0vBostmo95xwiiumMJm.jpg', 'Brother Bear', '71.226', '2003-10-23', 7.2, '4295', '[\'Adventure\', \'Animation\', \'Family\']', 'When an impulsive boy named Kenai is magically transformed into a bear, he must literally walk in another\'s footsteps until he learns some valuable life lessons. His courageous and often zany journey introduces him to a forest full of wildlife, including the lovable bear cub Koda, hilarious moose Rutt and Tuke, woolly mammoths and rambunctious rams.'),
(757, '682254', 'en', 'https://image.tmdb.org/t/p/w500/sCoG0ibohbPrnyomtzegSuBL40L.jpg', 'Scooby-Doo! The Sword and the Scoob', '76.096', '2021-02-22', 7.9, '124', '[\'Animation\', \'Comedy\', \'Family\', \'Mystery\', \'Adventure\', \'Fantasy\']', 'An evil sorceress transports the gang back to the age of chivalrous knights, spell-casting wizards, and fire-breathing dragons.'),
(758, '522518', 'en', 'https://image.tmdb.org/t/p/w500/wquJChp0NpoqthYdE3YjXNNxvVC.jpg', 'A Dog\'s Journey', '63.029', '2019-05-03', 8.1, '1014', '[\'Family\', \'Adventure\', \'Drama\']', 'A dog finds the meaning of his own existence through the lives of the humans he meets.'),
(759, '573699', 'zh', 'https://image.tmdb.org/t/p/w500/30SLnoKmYNyRPkKCYowsrGLRnJA.jpg', '白蛇：缘起', '67.775', '2019-01-11', 7.8, '243', '[\'Romance\', \'Animation\', \'Fantasy\']', 'One day a young woman named Blanca is saved by Xuan, a snake catcher from a nearby village. She has lost her memory, and together they go on a journey to discover her real identity, developing deeper feelings for one another along the way. But as they learn more about her past, they uncover a darker plot of supernatural forces vying for power, with the fate of the world hanging in the balance.'),
(760, '246464', 'ja', 'https://image.tmdb.org/t/p/w500/yZt3jMOzTG1MyF9bPfKEE67VB7q.jpg', 'そらのおとしものFinal 永遠の私の鳥籠', '72.172', '2014-04-27', 7.6, '22', '[\'Animation\', \'Romance\', \'Science Fiction\', \'Comedy\']', 'Ikaros is an Angeloid and falls out of the sky. Tomoki Sakurai is a boy who believes the most important thing is to live a peaceful life. The two live tougher. Tomoki Sakurai has never seen Ikaros smile. Tomoki Sakurai sees Nymph and Astraea laugh after they got free from the master’s rule. He hopes Ikaros can laugh like an ordinary girl.  This movie wraps up the story of Tomoki Sakurai and his relationship with the Angeloid from the sky, Ikaros.'),
(761, '433945', 'ja', 'https://image.tmdb.org/t/p/w500/1JjfOrZQAmdsR9bPKlwmL6u0eaG.jpg', '東京喰種 トーキョーグール', '76.959', '2017-07-16', 7, '280', '[\'Action\', \'Drama\', \'Horror\', \'Thriller\']', 'A Tokyo college student is attacked by a ghoul, a super-powered human who feeds on human flesh. He survives, but has become part ghoul and becomes a fugitive on the run.'),
(762, '9487', 'en', 'https://image.tmdb.org/t/p/w500/Ah3J9OJVc2CNCuH2zMydXy9fmIC.jpg', 'A Bug\'s Life', '77.149', '1998-11-25', 7, '7278', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'On behalf of \"oppressed bugs everywhere,\" an inventive ant named Flik hires a troupe of warrior bugs to defend his bustling colony from a horde of freeloading grasshoppers led by the evil-minded Hopper.'),
(763, '37710', 'en', 'https://image.tmdb.org/t/p/w500/oXe1nw4HcS32YVpvxwsWEVdvEXA.jpg', 'The Tourist', '71.986', '2010-12-08', 6.2, '4470', '[\'Action\', \'Thriller\', \'Romance\']', 'American tourist Frank meets mysterious British woman Elsie on the train to Venice. Romance seems to bud, but there\'s more to her than meets the eye. Remake of the 2005 French film \"Anthony Zimmer\", written and directed by Jérôme Salle.'),
(764, '93456', 'en', 'https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg', 'Despicable Me 2', '77.273', '2013-06-26', 6.9, '9382', '[\'Animation\', \'Comedy\', \'Family\']', 'Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal.'),
(765, '272818', 'en', 'https://image.tmdb.org/t/p/w500/rRL7GcA3dPNdD0GHRbq20DCeoeg.jpg', 'Monstruosamente Solo', '73.741', '2021-09-16', 5.2, '6', '[\'Comedy\', \'Drama\', \'Animation\']', 'Santiago is contained in the micro-universe of his home due to a deep depression after his girlfriend left him for no apparent reason. That is when he realizes that even though he wants to live his duel alone, his friends accompany him through video chats, telephone calls or visits right at  his door.'),
(766, '184315', 'en', 'https://image.tmdb.org/t/p/w500/sKNIwY6UENCJ36FvYvnBW3Vdzt7.jpg', 'Hercules', '72.559', '2014-07-23', 5.7, '3379', '[\'Action\', \'Adventure\']', 'Fourteen hundred years ago, a tormented soul walked the earth that was neither man nor god. Hercules was the powerful son of the god king Zeus, for this he received nothing but suffering his entire life. After twelve arduous labors and the loss of his family, this dark, world-weary soul turned his back on the gods finding his only solace in bloody battle. Over the years he warmed to the company of six similar souls, their only bond being their love of fighting and presence of death. These men and woman never question where they go to fight or why or whom, just how much they will be paid. Now the King of Thrace has hired these mercenaries to train his men to become the greatest army of all time. It is time for this bunch of lost souls to finally have their eyes opened to how far they have fallen when they must train an army to become as ruthless and blood thirsty as their reputation has become.'),
(767, '761388', 'en', 'https://image.tmdb.org/t/p/w500/n3G5XLqmJSs4RvozoIsqaTWTHRq.jpg', 'Lady of the Manor', '53.959', '2021-09-17', 6.8, '22', '[\'Comedy\', \'Fantasy\']', 'An aimless ne\'er-do-well becomes a tour guide in a historic estate and winds up befriending the manor\'s resident ghost.'),
(768, '49444', 'en', 'https://image.tmdb.org/t/p/w500/mtqqD00vB4PGRt20gWtGqFhrkd0.jpg', 'Kung Fu Panda 2', '69.645', '2011-05-25', 6.9, '5257', '[\'Animation\', \'Family\']', 'Po is now living his dream as The Dragon Warrior, protecting the Valley of Peace alongside his friends and fellow kung fu masters, The Furious Five - Tigress, Crane, Mantis, Viper and Monkey. But Po’s new life of awesomeness is threatened by the emergence of a formidable villain, who plans to use a secret, unstoppable weapon to conquer China and destroy kung fu. It is up to Po and The Furious Five to journey across China to face this threat and vanquish it. But how can Po stop a weapon that can stop kung fu? He must look to his past and uncover the secrets of his mysterious origins; only then will he be able to unlock the strength he needs to succeed.'),
(769, '27581', 'en', 'https://image.tmdb.org/t/p/w500/wNEHNqo3MgHmj3BUiPSqqq5czcm.jpg', 'The Other Guys', '72.393', '2010-08-06', 6.3, '3209', '[\'Comedy\', \'Action\', \'Crime\']', 'Unlike their heroic counterparts on the force, desk-bound NYPD detectives Gamble and Hoitz garner no headlines as they work day to day. When a seemingly minor case turns out to be a big deal, the two cops get the opportunity to finally prove to their comrades that they have the right stuff.'),
(770, '146233', 'en', 'https://image.tmdb.org/t/p/w500/jsS3a3ep2KyBVmmiwaz3LvK49b1.jpg', 'Prisoners', '76.372', '2013-09-18', 8, '8596', '[\'Drama\', \'Thriller\', \'Crime\']', 'Keller Dover faces a parent\'s worst nightmare when his 6-year-old daughter, Anna, and her friend go missing. The only lead is an old motorhome that had been parked on their street. The head of the investigation, Detective Loki, arrests the driver, but a lack of evidence forces Loki to release his only suspect. Dover, knowing that his daughter\'s life is at stake, decides that he has no choice but to take matters into his own hands.'),
(771, '109418', 'en', 'https://image.tmdb.org/t/p/w500/hT6ijOtjtYrnyDhN7VA2QWyGFAm.jpg', 'Grown Ups 2', '77.563', '2013-07-11', 6.1, '3214', '[\'Comedy\']', 'Lenny has relocated his family back to the small town where he and his friends grew up. This time around, the grown ups are the ones learning lessons from their kids on a day notoriously full of surprises—the last day of school.'),
(772, '587496', 'en', 'https://image.tmdb.org/t/p/w500/3ynPnBXQVT2Y0s19fDIPlWKUlxH.jpg', 'The Rental', '66.619', '2020-07-23', 5.6, '553', '[\'Horror\']', 'Two couples on an oceanside getaway grow suspicious that the host of their seemingly perfect rental house may be spying on them. Before long, what should have been a celebratory weekend trip turns into something far more sinister.'),
(773, '39105', 'ja', 'https://image.tmdb.org/t/p/w500/iihTK9Af8G1ZzBjkIIAV4qQMkzF.jpg', 'ドラゴンボールZ 銀河ギリギリ!! ぶっちぎりの凄い奴', '77.856', '1993-07-10', 7, '376', '[\'Action\', \'Animation\', \'Science Fiction\']', 'Mr. Money is holding another World Martial Arts Tournament and Mr. Satan invites everyone in the world to join in. Little does he know that Bojack, an ancient villain who has escaped his prison, is competing. Since Goku is currently dead, it is up to Gohan, Vegeta, and Trunks to defeat Bojack and his henchman.'),
(774, '81796', 'en', 'https://image.tmdb.org/t/p/w500/i5QfNIcg6hc327IWUerea0EczP4.jpg', 'Lockout', '64.097', '2012-04-12', 5.9, '1444', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'Set in the near future, Lockout follows a falsely convicted ex-government agent , whose one chance at obtaining freedom lies in the dangerous mission of rescuing the President\'s daughter from rioting convicts at an outer space maximum security prison.'),
(775, '39100', 'ja', 'https://image.tmdb.org/t/p/w500/5elbm3iLgGQ6nA5vqUmi9vIojbF.jpg', 'ドラゴンボールZ この世で一番強いヤツ', '79.839', '1990-03-10', 6.4, '334', '[\'Action\', \'Animation\', \'Science Fiction\']', 'The evil Dr. Kochin uses the dragon balls to resurrect his mentor, Dr. Wheelo, in an effort to take over the world. Dr. Wheelo, his body having been destroyed by the avalanche that killed him fifty years before, desires the body of the strongest fighter in the world as his new vessel. Believing Roshi to be the world\'s strongest warrior, Dr. Kochin abducts Bulma and forces Roshi to surrender himself to save her. When Goku hears of their abduction, he goes to their rescue.'),
(776, '156022', 'en', 'https://image.tmdb.org/t/p/w500/9u4yW7yPA0BQ2pv9XwiNzItwvp8.jpg', 'The Equalizer', '75.165', '2014-09-24', 7.2, '6874', '[\'Thriller\', \'Action\', \'Crime\']', 'McCall believes he has put his mysterious past behind him and dedicated himself to beginning a new, quiet life. But when he meets Teri, a young girl under the control of ultra-violent Russian gangsters, he can’t stand idly by – he has to help her. Armed with hidden skills that allow him to serve vengeance against anyone who would brutalize the helpless, McCall comes out of his self-imposed retirement and finds his desire for justice reawakened. If someone has a problem, if the odds are stacked against them, if they have nowhere else to turn, McCall will help. He is The Equalizer.'),
(777, '102899', 'en', 'https://image.tmdb.org/t/p/w500/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', 'Ant-Man', '74.888', '2015-07-14', 7.1, '16237', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.'),
(778, '420817', 'en', 'https://image.tmdb.org/t/p/w500/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', 'Aladdin', '78.481', '2019-05-22', 7.1, '8150', '[\'Adventure\', \'Fantasy\', \'Romance\', \'Family\']', 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.'),
(779, '560050', 'en', 'https://image.tmdb.org/t/p/w500/lG0TF0wj1n9p9CPy5xlIUIkF56a.jpg', 'Over the Moon', '77.023', '2020-10-16', 7.4, '976', '[\'Animation\', \'Adventure\', \'Family\', \'Fantasy\']', 'In this animated musical, a girl builds a rocket ship and blasts off, hoping to meet a mythical moon goddess.'),
(780, '480530', 'en', 'https://image.tmdb.org/t/p/w500/v3QyboWRoA4O9RbcsqH8tJMe8EB.jpg', 'Creed II', '71.228', '2018-11-21', 6.9, '3934', '[\'Drama\']', 'Between personal obligations and training for his next big fight against an opponent with ties to his family\'s past, Adonis Creed is up against the challenge of his life.'),
(781, '375794', 'es', 'https://image.tmdb.org/t/p/w500/6HfyXfIEywLa2HvcswKi44dDKxL.jpg', 'No Manches Frida', '70.515', '2016-09-02', 7.8, '579', '[\'Comedy\']', 'After his release from prison, bank robber Zequi sets off to recover the stolen money that was buried by his dizzy accomplice. He\'s horrified to learn that a high school gymnasium is now standing over the site where the loot is stashed. Needing to infiltrate the building, Zequi lands a job as a substitute teacher for a group of wild and unruly students. As the ex-con tries to lay down the law, he starts to realize that life in jail may have been easier than trying to deal with rebellious teens.'),
(782, '39103', 'ja', 'https://image.tmdb.org/t/p/w500/k23L4i0JjwU8D5flnR5damgXFcS.jpg', 'ドラゴンボールZ 激突!!100億パワーの戦士たち', '78.001', '1992-03-07', 6.7, '384', '[\'Action\', \'Animation\', \'Science Fiction\']', 'Cooler has resurrected himself as a robot and is enslaving the people of New Namek. Goku and the gang must help.'),
(783, '533535', 'en', 'https://image.tmdb.org/t/p/w500/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', 'Deadpool 3', '70.498', '', 0, '0', '[\'Action\', \'Science Fiction\', \'Comedy\']', ''),
(784, '6499', 'en', 'https://image.tmdb.org/t/p/w500/4mau5EXQoKUTiS5wx3Wocwrh5hG.jpg', 'Turbo: A Power Rangers Movie', '79.74', '1997-03-27', 5.7, '201', '[\'Action\', \'Adventure\', \'Family\', \'Fantasy\', \'Science Fiction\', \'Thriller\']', 'The legendary Power Rangers must stop the evil space pirate Divatox from releasing the powerful Maligore from his volcanic imprisonment on the island of Muranthias, where only the kindly wizard Lerigot has the key to release him. The hope of victory lies in the Ranger\'s incredible new Turbo powers and powerful Turbo Zords.'),
(785, '567006', 'ja', 'https://image.tmdb.org/t/p/w500/1O5jE1w2wYkFInDHnWYa91TemOO.jpg', '甲鉄城のカバネリ～海門決戦～', '82.218', '2019-05-10', 7.4, '32', '[\'Animation\', \'Action\', \'Fantasy\', \'Adventure\']', 'Half a year after the events of the series \"Kabaneri of the Iron Fortress\", the team attempt to take back Unato castle.'),
(786, '13186', 'en', 'https://image.tmdb.org/t/p/w500/ow3IMhTVLryZuCEoQznVTTmFYuu.jpg', 'Wrong Turn 2: Dead End', '64.739', '2007-08-25', 6, '942', '[\'Horror\', \'Thriller\']', 'Retired military commander Colonel Dale Murphy hosts the simulated post-apocalyptic reality show where participants are challenged to survive a remote West Virginia wasteland. But the show turns into a nightmarish showdown when each realizes they are being hunted by an inbred family of cannibals determined to make them all dinner!'),
(787, '706545', 'en', 'https://image.tmdb.org/t/p/w500/mRTnim0xPxYiH0LWi2O59Lqk2Gd.jpg', 'Introducing Chucky: The Making of Child\'s Play', '61.352', '1988-11-09', 5.8, '4', '[\'Documentary\']', 'A vintage featurette about the making of Child\'s Play (1988).'),
(788, '129', 'ja', 'https://image.tmdb.org/t/p/w500/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', '千と千尋の神隠し', '72.923', '2001-07-20', 8.5, '11996', '[\'Animation\', \'Family\', \'Fantasy\']', 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.'),
(789, '169917', 'en', 'https://image.tmdb.org/t/p/w500/euPgyPsiNFp6gOBB7nUFxvN5ZaY.jpg', 'A Walk Among the Tombstones', '68.008', '2014-09-18', 6.3, '2267', '[\'Crime\', \'Drama\', \'Mystery\', \'Thriller\']', 'Private investigator Matthew Scudder is hired by a drug kingpin to find out who kidnapped and murdered his wife.'),
(790, '12230', 'en', 'https://image.tmdb.org/t/p/w500/kSlYq6FrBUviGSEh8v4L9nrSnBT.jpg', 'One Hundred and One Dalmatians', '70.879', '1961-01-25', 7.2, '5000', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'When a litter of dalmatian puppies are abducted by the minions of Cruella De Vil, the parents must find them before she uses them for a diabolical fashion statement.\r In a Disney animation classic, Dalmatian Pongo is tired of his bachelor-dog life. He spies lovely Perdita and maneuvers his master, Roger, into meeting Perdita\'s owner, Anita. The owners fall in love and marry, keeping Pongo and Perdita together too. After Perdita gives birth to a litter of 15 puppies, Anita\'s old school friend Cruella De Vil wants to buy them all. Roger declines her offer, so Cruella hires the criminal Badun brothers to steal them -- so she can have a fur coat.'),
(791, '49013', 'en', 'https://image.tmdb.org/t/p/w500/okIz1HyxeVOMzYwwHUjH2pHi74I.jpg', 'Cars 2', '77.63', '2011-06-11', 6, '5877', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'Star race car Lightning McQueen and his pal Mater head overseas to compete in the World Grand Prix race. But the road to the championship becomes rocky as Mater gets caught up in an intriguing adventure of his own: international espionage.'),
(792, '76726', 'en', 'https://image.tmdb.org/t/p/w500/kdyrdFIt29FUmLIKvedAc2j4rpo.jpg', 'Chronicle', '68.619', '2012-02-01', 6.8, '4127', '[\'Science Fiction\', \'Drama\', \'Thriller\']', 'Three high school students make an incredible discovery, leading to their developing uncanny powers beyond their understanding. As they learn to control their abilities and use them to their advantage, their lives start to spin out of control, and their darker sides begin to take over.'),
(793, '338967', 'en', 'https://image.tmdb.org/t/p/w500/dtRbVsUb5O12WWO54SRpiMtHKC0.jpg', 'Zombieland: Double Tap', '75.829', '2019-10-09', 7, '4105', '[\'Horror\', \'Action\', \'Comedy\']', 'Columbus, Tallahassee, Wichita, and Little Rock move to the American heartland as they face off against evolved zombies, fellow survivors, and the growing pains of the snarky makeshift family.'),
(794, '76341', 'en', 'https://image.tmdb.org/t/p/w500/hA2ple9q4qnwxp3hKVNhroipsir.jpg', 'Mad Max: Fury Road', '74.41', '2015-05-13', 7.5, '18593', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.'),
(795, '176', 'en', 'https://image.tmdb.org/t/p/w500/rLNSOudrayDBo1uqXjrhxcjODIC.jpg', 'Saw', '65.499', '2004-10-01', 7.4, '6984', '[\'Horror\', \'Mystery\', \'Crime\']', 'Obsessed with teaching his victims the value of life, a deranged, sadistic serial killer abducts the morally wayward. Once captured, they must face impossible choices in a horrific game of survival. The victims must fight to win their lives back, or die trying...'),
(796, '950', 'en', 'https://image.tmdb.org/t/p/w500/zDduhCHasKQ9YOTvlOreHem7Wbi.jpg', 'Ice Age: The Meltdown', '75.846', '2006-03-29', 6.7, '7898', '[\'Animation\', \'Family\', \'Comedy\', \'Adventure\']', 'Diego, Manny and Sid return in this sequel to the hit animated movie Ice Age. This time around, the deep freeze is over, and the ice-covered earth is starting to melt, which will destroy the trio\'s cherished valley. The impending disaster prompts them to reunite and warn all the other beasts about the desperate situation.'),
(797, '23631', 'en', 'https://image.tmdb.org/t/p/w500/dcPSm1rGEFdiEc7DaKz0t5kb66b.jpg', 'Machete', '71.639', '2010-09-01', 6.3, '2575', '[\'Action\', \'Comedy\', \'Thriller\']', 'After being set-up and betrayed by the man who hired him to assassinate a Texas Senator, an ex-Federale launches a brutal rampage of revenge against his former boss.'),
(798, '84354', 'es', 'https://image.tmdb.org/t/p/w500/ixTyxtsK6W63jrWjixczyeJSex2.jpg', 'Joven y alocada', '66.015', '2012-03-29', 6.4, '96', '[\'Comedy\', \'Drama\']', 'Daniela, raised in the bosom of a strict Evangelical family and recently unmasked as a fornicator by her shocked parents, struggles to find her own path to spiritual harmony.'),
(799, '269149', 'en', 'https://image.tmdb.org/t/p/w500/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg', 'Zootopia', '72.082', '2016-02-11', 7.7, '13369', '[\'Animation\', \'Adventure\', \'Family\', \'Comedy\']', 'Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia\'s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.'),
(800, '583833', 'ru', 'https://image.tmdb.org/t/p/w500/rxc6ducVrgUWLat8WwUVLvr2GRR.jpg', 'Пальма', '64.682', '2021-03-18', 8.5, '91', '[\'Family\', \'Romance\']', 'The film is inspired by an incredible story of a shepherd dog named Palm who was inadvertently left in the airport by her owner. She befriends nine-year old Nicholas whose mother dies leaving him with a father he barely knows - a pilot who finds the dog at the airport. It\'s a story of amazing adventures, true friendship and unconditional love.'),
(801, '10192', 'en', 'https://image.tmdb.org/t/p/w500/6HrfPZtKcGmX2tUWW3cnciZTaSD.jpg', 'Shrek Forever After', '71.574', '2010-05-16', 6.3, '5633', '[\'Comedy\', \'Adventure\', \'Fantasy\', \'Animation\', \'Family\']', 'A bored and domesticated Shrek pacts with deal-maker Rumpelstiltskin to get back to feeling like a real ogre again, but when he\'s duped and sent to a twisted version of Far Far Away—where Rumpelstiltskin is king, ogres are hunted, and he and Fiona have never met—he sets out to restore his world and reclaim his true love.'),
(802, '263115', 'en', 'https://image.tmdb.org/t/p/w500/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', 'Logan', '80.578', '2017-02-28', 7.8, '16187', '[\'Action\', \'Drama\', \'Science Fiction\']', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan\'s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.'),
(803, '238636', 'en', 'https://image.tmdb.org/t/p/w500/qwqHHZLZSUvMkAMQ47ymtfjEifY.jpg', 'The Purge: Anarchy', '69.554', '2014-07-17', 6.7, '5340', '[\'Horror\', \'Thriller\']', 'One night per year, the government sanctions a 12-hour period in which citizens can commit any crime they wish -- including murder -- without fear of punishment or imprisonment. Leo, a sergeant who lost his son, plans a vigilante mission of revenge during the mayhem. However, instead of a death-dealing avenger, he becomes the unexpected protector of four innocent strangers who desperately need his help if they are to survive the night.'),
(804, '865140', 'es', 'https://image.tmdb.org/t/p/w500/gNObb3Q1P2yO2Z14bs6AXx0cWVy.jpg', 'Chilangolandia', '71.487', '2021-09-16', 3, '3', '[\'Comedy\']', ''),
(805, '11430', 'en', 'https://image.tmdb.org/t/p/w500/u2hN0WT7Dz46HfhQbr6uzSYfVW4.jpg', 'The Lion King 1½', '66.753', '2004-02-06', 6.6, '2401', '[\'Family\', \'Animation\', \'Comedy\']', 'Timon the meerkat and Pumbaa the warthog are best pals and the unsung heroes of the African savanna. This prequel to the smash Disney animated adventure takes you back -- way back -- before Simba\'s adventure began. You\'ll find out all about Timon and Pumbaa and tag along as they search for the perfect home and attempt to raise a rambunctious lion cub.'),
(806, '297762', 'en', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', 'Wonder Woman', '69.344', '2017-05-30', 7.3, '17040', '[\'Action\', \'Adventure\', \'Fantasy\']', 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.'),
(807, '313297', 'en', 'https://image.tmdb.org/t/p/w500/ewcOCkuuKAKULGUnbBVaO1htt0D.jpg', 'Kubo and the Two Strings', '74.374', '2016-08-18', 7.7, '2913', '[\'Animation\', \'Adventure\', \'Family\']', 'Kubo mesmerizes the people in his village with his magical gift for spinning wild tales with origami. When he accidentally summons an evil spirit seeking vengeance, Kubo is forced to go on a quest to solve the mystery of his fallen samurai father and his mystical weaponry, as well as discover his own magical powers.'),
(808, '668780', 'pt', 'https://image.tmdb.org/t/p/w500/a8grhLGhULwTpWbsCdXD8GQQUDN.jpg', 'Quem Vai Ficar com Mário?', '61.676', '2021-06-10', 5.7, '18', '[\'Comedy\']', 'Mario decides to tell his family the truth about himself. But when he is finally ready to come out in front of the entire family, his older brother Vicente ruins his plans.'),
(809, '8363', 'en', 'https://image.tmdb.org/t/p/w500/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg', 'Superbad', '65.915', '2007-03-20', 7.2, '5386', '[\'Comedy\']', 'Two co-dependent high school seniors are forced to deal with separation anxiety after their plan to stage a booze-soaked party goes awry.'),
(810, '51620', 'en', 'https://image.tmdb.org/t/p/w500/80mBFNVvak2bA9TJN1MD0yM7Lfi.jpg', 'Death Race 2', '79.603', '2010-11-12', 5.8, '829', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'In the world\'s most dangerous prison, a new game is born: Death Race. The rules of this adrenaline-fueled blood sport are simple, drive or die. When repentant convict Carl Lucas discovers there\'s a price on his head, his only hope is to survive a twisted race against an army of hardened criminals and tricked-out cars.'),
(811, '346364', 'en', 'https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg', 'It', '67.795', '2017-09-06', 7.2, '15789', '[\'Horror\', \'Fantasy\']', 'In a small town in Maine, seven children known as The Losers Club come face to face with life problems, bullies and a monster that takes the shape of a clown called Pennywise.'),
(812, '823855', 'en', 'https://image.tmdb.org/t/p/w500/m6bUeV4mczG3z2YXXr5XDKPsQzv.jpg', 'I Am All Girls', '70.315', '2021-05-14', 6.7, '163', '[\'Crime\', \'Drama\', \'Mystery\', \'Thriller\']', 'A special crimes investigator forms an unlikely bond with a serial killer to bring down a global child sex trafficking syndicate.'),
(813, '381288', 'en', 'https://image.tmdb.org/t/p/w500/lli31lYTFpvxVBeFHWoe5PMfW5s.jpg', 'Split', '71.342', '2016-11-15', 7.3, '14385', '[\'Horror\', \'Thriller\']', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.'),
(814, '5255', 'en', 'https://image.tmdb.org/t/p/w500/eOoCzH0MqeGr2taUZO4SwG416PF.jpg', 'The Polar Express', '83.576', '2004-11-10', 6.7, '4748', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\', \'Comedy\']', 'When a doubting young boy takes an extraordinary train ride to the North Pole, he embarks on a journey of self-discovery that shows him that the wonder of life never fades for those who believe.'),
(815, '49018', 'en', 'https://image.tmdb.org/t/p/w500/1egpmVXuXed58TH2UOnX1nATTrf.jpg', 'Insidious', '64.575', '2010-09-13', 6.9, '5188', '[\'Horror\', \'Thriller\']', 'A family discovers that dark spirits have invaded their home after their son inexplicably falls into an endless sleep. When they reach out to a professional for help, they learn things are a lot more personal than they thought.'),
(816, '105864', 'en', 'https://image.tmdb.org/t/p/w500/8RSkxOO80btfKjyiC5ZiTaCHIT8.jpg', 'The Good Dinosaur', '65.366', '2015-11-14', 6.7, '4383', '[\'Adventure\', \'Animation\', \'Family\']', 'An epic journey into the world of dinosaurs where an Apatosaurus named Arlo makes an unlikely human friend.'),
(817, '200085', 'ko', 'https://image.tmdb.org/t/p/w500/mvTXhTddHIZbOU9pmrcPODI1kRx.jpg', '감기', '58.644', '2013-08-14', 7.5, '907', '[\'Action\', \'Drama\', \'Science Fiction\']', 'A case of the flu quickly morphs into a pandemic. As the death toll mounts and the living panic, the government plans extreme measures to contain it.'),
(818, '58857', 'ja', 'https://image.tmdb.org/t/p/w500/yUsVsiVXUwClk4vSCx80vrdO6MV.jpg', '十三人の刺客', '68.629', '2010-09-09', 7.3, '785', '[\'Adventure\', \'Drama\', \'Action\']', 'A bravado period action film set at the end of Japan\'s feudal era in which a group of unemployed samurai are enlisted to bring down a sadistic lord and prevent him from ascending to the throne and plunging the country into a war-torn future.'),
(819, '51608', 'ko', 'https://image.tmdb.org/t/p/w500/ld19CFIo27t41JXSGZdaPMUGTxh.jpg', '아저씨', '69.125', '2010-08-04', 7.7, '911', '[\'Action\', \'Thriller\', \'Crime\']', 'His only friend called him \'the man from nowhere\'... Taesik, a former special agent becomes a loner after losing his wife in a miserable accident and lives a bitter life running a pawnshop. He only has a few customers and a friend named Somi, a little girl next door. As Taesik spends more and more time with Somi, he gets attached to her. Then Somi is kidnapped by a gang, and as Taesik tries to save Somi by becoming deeply associated with the gang his mysterious past is revealed...'),
(820, '374205', 'ja', 'https://image.tmdb.org/t/p/w500/wPBFqO9zeSjX3bK9NMvhm9xL1Le.jpg', 'ワンピース　フィルム GOLD', '69.876', '2016-07-23', 7.2, '296', '[\'Action\', \'Animation\', \'Adventure\', \'Comedy\']', 'The Straw Hat Pirates are taking on Gild Tesoro, one of the richest men in the world.'),
(821, '480157', 'en', 'https://image.tmdb.org/t/p/w500/fSvhp22gCoHgFMDSnyhrmlo3M0k.jpg', 'House of the Witch', '59.086', '2017-10-07', 4.5, '99', '[\'Horror\']', 'A group of high-school kids set out to play a Halloween prank at an abandoned house, but once they enter they become victims of a demonic witch who has set her wrath upon them.'),
(822, '390043', 'en', 'https://image.tmdb.org/t/p/w500/5CGjlz2vyBhW5xHW4eNOZIdgzYq.jpg', 'The Hitman\'s Bodyguard', '65.691', '2017-08-16', 6.9, '4759', '[\'Thriller\', \'Comedy\', \'Crime\', \'Action\']', 'The world\'s top bodyguard gets a new client, a hit man who must testify at the International Court of Justice. They must put their differences aside and work together to make it to the trial on time.'),
(823, '11360', 'en', 'https://image.tmdb.org/t/p/w500/4x9FmvdJ464Fg7A9XcbYSmxfVw3.jpg', 'Dumbo', '75.479', '1941-10-22', 7, '3938', '[\'Animation\', \'Family\']', 'Dumbo is a baby elephant born with over-sized ears and a supreme lack of confidence. But thanks to his even more diminutive buddy Timothy the Mouse,  the pint-sized pachyderm learns to surmount all obstacles.'),
(824, '712121', 'pl', 'https://image.tmdb.org/t/p/w500/Ab6NF6oP2BxQdk9rxaA9qWPARAm.jpg', 'Sweat', '71.775', '2021-03-12', 7, '21', '[\'Drama\', \'Thriller\']', 'Three days in the life of fitness motivator Sylwia Zając, whose presence on social media has made her a celebrity. Although she has hundreds of thousands of followers, is surrounded by loyal employees and admired by acquaintances, she is looking for true intimacy.'),
(825, '20662', 'en', 'https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg', 'Robin Hood', '81.615', '2010-05-12', 6.4, '3623', '[\'Adventure\']', 'When soldier Robin happens upon the dying Robert of Loxley, he promises to return the man\'s sword to his family in Nottingham. There, he assumes Robert\'s identity; romances his widow, Marion; and draws the ire of the town\'s sheriff and King John\'s henchman, Godfrey.'),
(826, '738215', 'en', 'https://image.tmdb.org/t/p/w500/AwkmMTKJBAatbeAVhTwhcU3Pyp4.jpg', 'Barbie: Princess Adventure', '66.341', '2020-09-01', 7.4, '175', '[\'Animation\', \'Music\']', 'With new friends in a new kingdom, Barbie learns what it means to be herself when she trades places with a royal lookalike in this musical adventure.'),
(827, '726429', 'es', 'https://image.tmdb.org/t/p/w500/cwUhVcDeMYYeu8fq5q1OPOoSbZ7.jpg', 'Xtremo', '71.165', '2021-06-04', 6.8, '165', '[\'Action\', \'Adventure\', \'Crime\']', 'Two years after the murder of his son and father, a retired hitman sets in motion a carefully crafted revenge plan against the killer: his own brother.'),
(828, '127585', 'en', 'https://image.tmdb.org/t/p/w500/tYfijzolzgoMOtegh1Y7j2Enorg.jpg', 'X-Men: Days of Future Past', '71.64', '2014-05-15', 7.5, '12862', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.'),
(829, '835739', 'en', 'https://image.tmdb.org/t/p/w500/unIkHTdCEIdHdtmWjEwfv7Ifllk.jpg', 'Super Monsters: Once Upon a Rhyme', '81.791', '2021-06-01', 6.3, '55', '[\'Animation\']', 'From Goldilocks to Hansel and Gretel, the Super Monsters reimagine classic fairy tales and favorite nursery rhymes with a musical, magical spin!'),
(830, '7446', 'en', 'https://image.tmdb.org/t/p/w500/zAurB9mNxfYRoVrVjAJJwGV3sPg.jpg', 'Tropic Thunder', '54.225', '2008-08-09', 6.6, '4604', '[\'Action\', \'Comedy\', \'Adventure\', \'War\']', 'Ben Stiller, Jack Black and Robert Downey Jr. lead an ensemble cast in \'Tropic Thunder,\' an action comedy about a group of self-absorbed actors who set out to make the most expensive war film. After ballooning costs force the studio to cancel the movie, the frustrated director refuses to stop shooting, leading his cast into the jungles of Southeast Asia, where they encounter real bad guys.'),
(831, '10020', 'en', 'https://image.tmdb.org/t/p/w500/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', 'Beauty and the Beast', '73.397', '1991-10-22', 7.7, '8020', '[\'Romance\', \'Family\', \'Animation\', \'Fantasy\']', 'Follow the adventures of Belle, a bright young woman who finds herself in the castle of a prince who\'s been turned into a mysterious beast. With the help of the castle\'s enchanted staff, Belle soon learns the most important lesson of all -- that true beauty comes from within.'),
(832, '38322', 'en', 'https://image.tmdb.org/t/p/w500/n1GSxFcDaZ6lMVf21M0KloPfuhu.jpg', 'Big Mommas: Like Father, Like Son', '62.697', '2011-02-16', 5.6, '948', '[\'Crime\', \'Comedy\', \'Action\']', 'FBI agent Malcolm Turner and his 17-year-old son, Trent, go undercover at an all-girls performing arts school after Trent witnesses a murder. Posing as Big Momma and Charmaine, they must find the murderer before he finds them.'),
(833, '14164', 'en', 'https://image.tmdb.org/t/p/w500/sunS9xhPnFNP5wlOWrvbpBteAB.jpg', 'Dragonball Evolution', '75.676', '2009-03-12', 2.9, '1557', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\', \'Thriller\']', 'The young warrior Son Goku sets out on a quest, racing against time and the vengeful King Piccolo, to collect a set of seven magical orbs that will grant their wielder unlimited power.'),
(834, '9948', 'en', 'https://image.tmdb.org/t/p/w500/o3b8nenAzu5OJk7sbPJURwmeHSV.jpg', 'The Fox and the Hound 2', '77.971', '2006-11-09', 6.1, '508', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Best friends Tod, a fox kit, and Copper, a hound puppy, visit a country fair when they see a band of dogs called \"The Singin\' Strays\". The band has five members: Dixie, Cash, Granny Rose, and twin brothers Waylon and Floyd. It is important that they perform well because a talent scout is visiting.'),
(835, '763240', 'en', 'https://image.tmdb.org/t/p/w500/qfLtwNZ2f3kXNAPJzzSRRJqrGpb.jpg', 'Sugar Daddy', '65.843', '2021-04-09', 6.3, '18', '[\'Drama\']', 'When a struggling musician can\'t afford her rent, she signs up for a website where rich older men pay to date younger women. Her new money-making venture sends her down a dark rabbit hole that forces her to grow up fast, shaping her music, and how she sees the world.'),
(836, '300669', 'en', 'https://image.tmdb.org/t/p/w500/dSxHyPZ2nipSfvdft4IhQKjk5eZ.jpg', 'Don\'t Breathe', '72.706', '2016-06-08', 7, '5745', '[\'Horror\', \'Thriller\']', 'A group of teens break into a blind man\'s home thinking they\'ll get away with the perfect crime. They\'re wrong.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(837, '450465', 'en', 'https://image.tmdb.org/t/p/w500/svIDTNUoajS8dLEo7EosxvyAsgJ.jpg', 'Glass', '59.904', '2019-01-16', 6.7, '6600', '[\'Thriller\', \'Drama\', \'Science Fiction\']', 'In a series of escalating encounters, former security guard David Dunn uses his supernatural abilities to track Kevin Wendell Crumb, a disturbed man who has twenty-four personalities. Meanwhile, the shadowy presence of Elijah Price emerges as an orchestrator who holds secrets critical to both men.'),
(838, '12153', 'en', 'https://image.tmdb.org/t/p/w500/aHTUpo45qy9QYIOnVITGGqLoVcA.jpg', 'White Chicks', '64.214', '2004-06-23', 6.9, '2732', '[\'Comedy\', \'Crime\']', 'Two FBI agent brothers, Marcus and Kevin Copeland, accidentally foil a drug bust. To avoid being fired they accept a mission escorting a pair of socialites to the Hamptons--but when the girls are disfigured in a car accident, they refuse to go. Left without options, Marcus and Kevin decide to pose as the sisters, transforming themselves from black men into rich white women.'),
(839, '480414', 'en', 'https://image.tmdb.org/t/p/w500/hETrPpoKs6BwoilK64YJ7Z5GcRT.jpg', 'The Curse of La Llorona', '63.881', '2019-04-17', 5.7, '1772', '[\'Horror\', \'Thriller\']', 'A social worker dealing with the disappearance of two children fears for her own family after beginning the investigation.'),
(840, '756', 'en', 'https://image.tmdb.org/t/p/w500/5m9njnidjR0syG2gpVPVgcEMB2X.jpg', 'Fantasia', '74.161', '1940-11-13', 7.4, '2305', '[\'Animation\', \'Family\']', 'Walt Disney\'s timeless masterpiece is an extravaganza of sight and sound! See the music come to life, hear the pictures burst into song and experience the excitement that is Fantasia over and over again.'),
(841, '810', 'en', 'https://image.tmdb.org/t/p/w500/n4SexGGQzI26E269tfpa80MZaGV.jpg', 'Shrek the Third', '71.352', '2007-05-17', 6.2, '6958', '[\'Fantasy\', \'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'The King of Far Far Away has died and Shrek and Fiona are to become King & Queen. However, Shrek wants to return to his cozy swamp and live in peace and quiet, so when he finds out there is another heir to the throne, they set off to bring him back to rule the kingdom.'),
(842, '766680', 'en', 'https://image.tmdb.org/t/p/w500/thzaTeq3H68VrDUgEO9SKpDEQX2.jpg', 'Sexo', '60.665', '2001-08-21', 4.2, '9', '[\'Comedy\']', 'This film skewers the audience\'s prejudices when the subtitles abandon their usual chore of translating what is said and start talking directly to the audience.'),
(843, '583083', 'en', 'https://image.tmdb.org/t/p/w500/mb7wQv0adK3kjOUr9n93mANHhPJ.jpg', 'The Kissing Booth 2', '72.461', '2020-07-24', 7.9, '4353', '[\'Comedy\', \'Romance\']', 'With college decisions looming, Elle juggles her long-distance romance with Noah, changing relationship with bestie Lee and feelings for a new classmate.'),
(844, '747984', 'ko', 'https://image.tmdb.org/t/p/w500/lUgr4a9tgLbpq4C3Xy9Ecty2q9S.jpg', '불어라 검풍아', '74.886', '2021-04-08', 5.5, '6', '[\'Action\', \'Comedy\']', 'Since she was a child, Yeon-hee dreamt of becoming an action star. Even though she has an amazing swordsmanship, the reality of reaching her goal is just too hard for her to handle.  One day, she is hired as a stand-in for an action film and goes onto the set, only to be transported to a lawless parallel world where people carry swords and kill each other without any retribution. Almost immediately, she is welcomed to the village as their protector and is respected by the villagers. And to save the villagers as a heroine, she begins to fight the villains back.'),
(845, '58595', 'en', 'https://image.tmdb.org/t/p/w500/8HUa5kRubYbnAD5UVpnhTGGgMTW.jpg', 'Snow White and the Huntsman', '66.82', '2012-05-30', 6, '6752', '[\'Adventure\', \'Fantasy\', \'Drama\']', 'After the Evil Queen marries the King, she performs a violent coup in which the King is murdered and his daughter, Snow White, is taken captive. Almost a decade later, a grown Snow White is still in the clutches of the Queen. In order to obtain immortality, The Evil Queen needs the heart of Snow White. After Snow escapes the castle, the Queen sends the Huntsman to find her in the Dark Forest.'),
(846, '522406', 'en', 'https://image.tmdb.org/t/p/w500/wQ2jQbygvJW5HsEyaCNv2WxtAnl.jpg', 'Flashback', '73.703', '2021-06-03', 6.5, '144', '[\'Thriller\']', 'Frederick Fitzell is living his best life—until he starts having horrific visions of Cindy, a girl who vanished in high school. After reaching out to old friends with whom he used to take a mystery drug called Mercury, Fredrick realizes the only way to stop the visions lies deep within his own memories, so he embarks on a terrifying mental odyssey to learn the truth.'),
(847, '570269', 'ja', 'https://image.tmdb.org/t/p/w500/nlgrBVlXCXf72rYPxKOnzH0eZ59.jpg', '劇場版トリニティセブン -天空図書館と真紅の魔王-', '74.752', '2019-03-29', 7.9, '30', '[\'Animation\', \'Action\', \'Fantasy\', \'Comedy\']', 'The series focuses on the adventures of Arata Kasuga, a high school student, who is targeted by Lilith, a teacher at a mystical school. Given three choices in an effort to help save the breakdown phenomenon of the world by evil forces and while attempting to solve the mystery of his beloved cousin and childhood friend, Hijiri, who disappeared to a difference space.'),
(848, '134374', 'en', 'https://image.tmdb.org/t/p/w500/9WqA0Ry9wmTzFvom8mNbcyKZQgP.jpg', 'Pain & Gain', '71.538', '2013-04-18', 6.2, '3526', '[\'Crime\', \'Action\']', 'Daniel Lugo, manager of the Sun Gym in 1990s Miami, decides that there is only one way to achieve his version of the American dream: extortion. To achieve his goal, he recruits musclemen Paul and Adrian as accomplices. After several failed attempts, they abduct rich businessman Victor Kershaw and convince him to sign over all his assets to them. But when Kershaw makes it out alive, authorities are reluctant to believe his story.'),
(849, '13640', 'en', 'https://image.tmdb.org/t/p/w500/itvuWm7DFWWzWgW0xgiaKzzWszP.jpg', 'Superman: Doomsday', '60.823', '2007-09-18', 6.7, '439', '[\'Action\', \'Animation\', \'Science Fiction\', \'Family\']', 'When LexCorp accidentally unleashes a murderous creature, Superman meets his greatest challenge as a champion. Based on the \"The Death of Superman\" storyline that appeared in DC Comics\' publications in the 1990s.'),
(850, '64690', 'en', 'https://image.tmdb.org/t/p/w500/602vevIURmpDfzbnv5Ubi6wIkQm.jpg', 'Drive', '64.81', '2011-08-06', 7.6, '9766', '[\'Drama\', \'Thriller\', \'Crime\']', 'Driver is a skilled Hollywood stuntman who moonlights as a getaway driver for criminals. Though he projects an icy exterior, lately he\'s been warming up to a pretty neighbor named Irene and her young son, Benicio. When Irene\'s husband gets out of jail, he enlists Driver\'s help in a million-dollar heist. The job goes horribly wrong, and Driver must risk his life to protect Irene and Benicio from the vengeful masterminds behind the robbery.'),
(851, '573680', 'en', 'https://image.tmdb.org/t/p/w500/xD9mc8JCVXA8T8u4Od7qOUBuGH4.jpg', 'The Banishing', '62.811', '2021-04-29', 5.5, '47', '[\'Horror\']', 'In the 1930s, a young reverend and his family are forced to confront their worst fears when they discover their new home holds a horrifying secret.'),
(852, '503314', 'ja', 'https://media.eiga.com/images/movie/88348/photo/3fbc598a6485207b.jpg', 'ドラゴンボール超スーパー ブロリー', '69.543', '2018-12-14', 7.8, '2089', '[\'Action\', \'Science Fiction\', \'Animation\']', 'Earth is peaceful following the Tournament of Power. Realizing that the universes still hold many more strong people yet to see, Goku spends all his days training to reach even greater heights. Then one day, Goku and Vegeta are faced by a Saiyan called \'Broly\' who they\'ve never seen before. The Saiyans were supposed to have been almost completely wiped out in the destruction of Planet Vegeta, so what\'s this one doing on Earth? This encounter between the three Saiyans who have followed completely different destinies turns into a stupendous battle, with even Frieza (back from Hell) getting caught up in the mix.'),
(853, '504175', 'en', 'https://image.tmdb.org/t/p/w500/nYU93A4MCy9mAAnrmP8p96Wc26u.jpg', 'Chucky\'s Vacation Slides', '69.262', '2005-06-07', 6.3, '7', '[\'Comedy\', \'Horror\']', 'Slasher-film star Chucky, his wife Tiffany, and their gender-ambiguous child Glen/Glenda gather in the living room for a slideshow of their vacation. Despite promising that he would \"cut back\" on his murderous behavior, the remains of Chucky\'s victims keep appearing throughout the slides.'),
(854, '644092', 'en', 'https://image.tmdb.org/t/p/w500/tTWl37oAYRXS3D5mEHmjveXXyrN.jpg', 'Finding \'Ohana', '62.587', '2021-01-29', 6.5, '275', '[\'Action\', \'Adventure\', \'Comedy\', \'Family\']', 'Two Brooklyn siblings\' summer in a rural Oahu town takes an exciting turn when a journal pointing to long-lost treasure sets them on an adventure, leading them to reconnect with their Hawaiian heritage.'),
(855, '19899', 'en', 'https://image.tmdb.org/t/p/w500/igXVSRZsNX3TZsKrQqSyEJvzHRF.jpg', 'Couples Retreat', '66.014', '2009-09-19', 5.5, '1531', '[\'Comedy\', \'Romance\']', 'Four couples, all friends, descend on a tropical island resort. Though one husband and wife are there to work on their marriage, the others just want to enjoy some fun in the sun. They soon find, however, that paradise comes at a price: Participation in couples therapy sessions is mandatory. What started out as a cut-rate vacation turns into an examination of the common problems many face.'),
(856, '223702', 'en', 'https://image.tmdb.org/t/p/w500/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', 'Sausage Party', '67.664', '2016-07-11', 5.7, '5937', '[\'Animation\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'Frank leads a group of supermarket products on a quest to discover the truth about their existence and what really happens when they become chosen to leave the grocery store.'),
(857, '652004', 'en', 'https://image.tmdb.org/t/p/w500/nXeTSXR5ryFwxrlpmD9hhXJTAuc.jpg', 'The Wolf of Snow Hollow', '61.224', '2020-10-23', 6.1, '186', '[\'Horror\', \'Thriller\']', 'A stressed-out police officer struggles not to give in to the paranoia that grips his small mountain town as bodies turn up after each full moon.'),
(858, '8922', 'en', 'https://image.tmdb.org/t/p/w500/g410Y1U1ELbmJG14Zru3UAimm1G.jpg', 'Jeepers Creepers', '61.379', '2001-07-01', 6.4, '2118', '[\'Horror\', \'Thriller\']', 'A brother and sister driving home through an isolated countryside from college encounter a flesh-eating creature in the midst of its ritualistic eating spree.'),
(859, '24593', 'en', 'https://image.tmdb.org/t/p/w500/kqB0fF7VlODmw1exH4iDZHGUiVI.jpg', 'Thinking XXX', '73.315', '2004-10-27', 5, '63', '[\'Documentary\']', 'For a book project, photographer Timothy Greenfield-Sanders took photographs of 30 stars of adult movies, each pair of photographs in the same pose, clothed and nude. This film records the photo shoots and includes interviews with the performers and commentary from eight writers (and John Waters). The actors and writers discuss economics, nudity and exhibitionism, careers, and private lives.'),
(860, '470044', 'en', 'https://image.tmdb.org/t/p/w500/2icwBom0t5nmOuZI9FVXF3gkMK0.jpg', 'The Hate U Give', '99.513', '2018-10-19', 8.3, '1642', '[\'Crime\', \'Drama\']', 'Raised in a poverty-stricken slum, a 16-year-old girl named Starr now attends a suburban prep school. After she witnesses a police officer shoot her unarmed best friend, she\'s torn between her two very different worlds as she tries to speak her truth.'),
(861, '569094', 'en', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'Spider-Man: Across the Spider-Verse', '75.702', '2022-10-06', 0, '0', '[\'Animation\', \'Action\', \'Science Fiction\', \'Comedy\', \'Adventure\']', 'The continuing story of Miles Morales and the many other Spider-People from different realities.'),
(862, '10198', 'en', 'https://image.tmdb.org/t/p/w500/v6nAUs62OJ4DXmnnmPFeVmMz8H9.jpg', 'The Princess and the Frog', '67.269', '2009-12-08', 7.1, '4186', '[\'Romance\', \'Family\', \'Animation\']', 'A waitress, desperate to fulfill her dreams as a restaurant owner, is set on a journey to turn a frog prince back into a human being, but she has to face the same problem after she kisses him.'),
(863, '75948', 'zh', 'https://image.tmdb.org/t/p/w500/5Jfv3CtMULd41C5jpLR8PGAMgE3.jpg', '白蛇传说', '62.614', '2011-09-27', 6.2, '169', '[\'Action\', \'Fantasy\']', 'The Sorcerer and the White Snake is an ancient Chinese fable about a woman demon who falls in love with a mortal is brought to life through the latest advances in CGI and action techniques.'),
(864, '242582', 'en', 'https://image.tmdb.org/t/p/w500/j9HrX8f7GbZQm1BrBiR40uFQZSb.jpg', 'Nightcrawler', '59.561', '2014-10-23', 7.7, '8451', '[\'Crime\', \'Drama\', \'Thriller\']', 'When Lou Bloom, desperate for work, muscles into the world of L.A. crime journalism, he blurs the line between observer and participant to become the star of his own story. Aiding him in his effort is Nina, a TV-news veteran.'),
(865, '124905', 'en', 'https://image.tmdb.org/t/p/w500/tphkjmQq8WebuVwNXelmjLUXuPJ.jpg', 'Godzilla', '69.375', '2014-05-14', 6.2, '7255', '[\'Action\', \'Drama\', \'Science Fiction\']', 'Ford Brody, a Navy bomb expert, has just reunited with his family in San Francisco when he is forced to go to Japan to help his estranged father, Joe. Soon, both men are swept up in an escalating crisis when an ancient alpha predator arises from the sea to combat malevolent adversaries that threaten the survival of humanity. The creatures leave colossal destruction in their wake, as they make their way toward their final battleground: San Francisco.'),
(866, '181812', 'en', 'https://image.tmdb.org/t/p/w500/db32LaOibwEliAmSL2jjDF6oDdj.jpg', 'Star Wars: The Rise of Skywalker', '71.676', '2019-12-18', 6.5, '7194', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'The surviving Resistance faces the First Order once again as the journey of Rey, Finn and Poe Dameron continues. With the power and knowledge of generations behind them, the final battle begins.'),
(867, '72431', 'en', 'https://image.tmdb.org/t/p/w500/dXmhYTdeMiuQFW4VpiWbfjtxtl9.jpg', 'Red Tails', '55.302', '2012-01-19', 6.5, '464', '[\'Drama\', \'Action\', \'Adventure\', \'History\', \'War\']', 'The story of the Tuskegee Airmen, the first African-American pilots to fly in a combat squadron during World War II.'),
(868, '280002', 'en', 'https://image.tmdb.org/t/p/w500/fFeTfXI67Oj80s65jtbq4uQ4InP.jpg', 'The Remaining', '64.053', '2014-08-25', 5.5, '244', '[\'Thriller\', \'Horror\']', 'When a group of close-knit friends assemble for the marriage of Skylar and Dan, they have no idea they will witness The Rapture and face a series of catastrophic events turning the celebration into a life-or-death struggle.'),
(869, '633954', 'fr', 'https://image.tmdb.org/t/p/w500/cBhkSwZpb3QpUwFuFdWAXTqWAtS.jpg', 'Le guide de la famille parfaite', '57.537', '2021-07-14', 6.6, '70', '[\'Comedy\', \'Drama\']', 'A couple in Québec deals with the pitfalls, pressure and high expectations of raising kids in a society obsessed with success and social media image.'),
(870, '14405', 'en', 'https://image.tmdb.org/t/p/w500/2aRvqtLoE06hTjG93lASvO7r1as.jpg', 'Beverly Hills Chihuahua', '62.931', '2008-10-03', 5.3, '816', '[\'Comedy\', \'Family\', \'Adventure\', \'Romance\']', 'A pampered Beverly Hills chihuahua named Chloe who, while on vacation in Mexico with her owner Viv\'s niece, Rachel, gets lost and must rely on her friends to help her get back home before she is caught by a dognapper who wants to ransom her.'),
(871, '363088', 'en', 'https://image.tmdb.org/t/p/w500/cFQEO687n1K6umXbInzocxcnAQz.jpg', 'Ant-Man and the Wasp', '67.025', '2018-07-04', 7, '10399', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.'),
(872, '737568', 'en', 'https://image.tmdb.org/t/p/w500/pklyUbh4k1DbHdnsOMASyw7C6NH.jpg', 'The Doorman', '67.488', '2020-10-01', 5.9, '256', '[\'Action\', \'Thriller\']', 'A former Marine turned doorman at a luxury New York City high-rise must outsmart and battle a group of art thieves and their ruthless leader — while struggling to protect her sister\'s family. As the thieves become increasingly desperate and violent, the doorman calls upon her deadly fighting skills to end the showdown.'),
(873, '603692', 'en', 'https://pbs.twimg.com/media/FDtbzIyVcAA3fMu.jpg', 'John Wick: Chapter 4 - Hagakure', '65.84', '2022-05-25', 0, '0', '[\'Action\', \'Crime\', \'Thriller\']', ''),
(874, '11351', 'en', 'https://image.tmdb.org/t/p/w500/u2ghDfjcs3y5c8ata3COc4pWiAN.jpg', 'Jeepers Creepers 2', '60.188', '2003-08-08', 6, '1121', '[\'Horror\']', 'When their bus is crippled on the side of a deserted road, a team of high school athletes discover an opponent they cannot defeat – and may not survive. Staring hungrily at them through the school bus windows, the \"Creeper\" returns again and again. But when the teammates discover that it’s selective about whom it attacks, it will test their ability to stick together – as the insatiable menace tries to tear them apart!'),
(875, '695568', 'en', 'https://image.tmdb.org/t/p/w500/cE1pT8biarqm2Sjk094Sdygsu69.jpg', 'Finding Grace', '67.187', '2020-04-21', 6.5, '14', '[\'Drama\']', 'A struggling family, already on the verge of disintegration, faces new challenges that will test their faith in God and each other.'),
(876, '522681', 'en', 'https://image.tmdb.org/t/p/w500/8Ls1tZ6qjGzfGHjBB7ihOnf7f0b.jpg', 'Escape Room', '62.348', '2019-01-03', 6.5, '3425', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Six strangers find themselves in circumstances beyond their control, and must use their wits to survive.'),
(877, '14248', 'en', 'https://image.tmdb.org/t/p/w500/mI4SPs0bZQm7bGVZKToC8KUsTd.jpg', 'Igor', '60.447', '2008-09-19', 5.9, '436', '[\'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'A cliché hunchbacked evil scientist\'s assistant aspires to become a scientist himself, much to the displeasure of the rest of the evil science community.'),
(878, '2907', 'en', 'https://image.tmdb.org/t/p/w500/qFf8anju5f2epI0my8RdwwIXFIP.jpg', 'The Addams Family', '56.89', '1991-11-22', 7, '3408', '[\'Family\', \'Comedy\', \'Fantasy\', \'Horror\']', 'When a man claiming to be long-lost Uncle Fester reappears after 25 years lost, the family plans a celebration to wake the dead. But the kids barely have time to warm up the electric chair before Morticia begins to suspect Fester is fraud when he can\'t recall any of the details of Fester\'s life.'),
(879, '140300', 'en', 'https://image.tmdb.org/t/p/w500/oajNi4Su39WAByHI6EONu8G8HYn.jpg', 'Kung Fu Panda 3', '60.892', '2016-01-23', 6.8, '4397', '[\'Action\', \'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Continuing his \"legendary adventures of awesomeness\", Po must face two hugely epic, but different threats: one supernatural and the other a little closer to his home.'),
(880, '20453', 'hi', 'https://image.tmdb.org/t/p/w500/66A9MqXOyVFCssoloscw79z8Tew.jpg', '3 Idiots', '53.676', '2009-12-23', 8, '1709', '[\'Drama\', \'Comedy\']', 'In the tradition of “Ferris Bueller’s Day Off” comes this refreshing comedy about a rebellious prankster with a crafty mind and a heart of gold. Rascal. Joker. Dreamer. Genius... You\'ve never met a college student quite like \"Rancho.\" From the moment he arrives at India\'s most prestigious university, Rancho\'s outlandish schemes turn the campus upside down—along with the lives of his two newfound best friends. Together, they make life miserable for \"Virus,\" the school’s uptight and heartless dean. But when Rancho catches the eye of the dean\'s sexy daughter, Virus sets his sights on flunking out the \"3 idiots\" once and for all.'),
(881, '9325', 'en', 'https://image.tmdb.org/t/p/w500/yN1kuupnPTLUprgfvC5WapgrxG4.jpg', 'The Jungle Book', '64.123', '1967-10-18', 7.3, '5040', '[\'Family\', \'Animation\', \'Adventure\']', 'The boy Mowgli makes his way to the man-village with Bagheera, the wise panther. Along the way he meets jazzy King Louie, the hypnotic snake Kaa and the lovable, happy-go-lucky bear Baloo, who teaches Mowgli \"The Bare Necessities\" of life and the true meaning of friendship.'),
(882, '762469', 'en', 'https://image.tmdb.org/t/p/w500/mI6mFCO3lrJ4ovzwfmoLs58uhlK.jpg', 'Father Christmas Is Back', '97.261', '2021-11-07', 5.8, '14', '[\'Comedy\', \'Family\']', 'Caroline Christmas, a control freak desires nothing more than a perfect Christmas with her sisters at her lavish country manor to atone for the fact that their father abandoned them many years ago. When on Christmas Eve their long-lost father arrives at their doorstep with his new girlfriend, chaos ensues. Through a series of mishaps and misunderstandings, Caroline uncovers a long-buried family secret. Can the family still celebrate Christmas together after all?'),
(883, '76600', 'en', 'https://image.tmdb.org/t/p/w500/5ANRjyS85pkUYs2b2KoqEDvoYHx.jpg', 'Avatar 2', '58.466', '2022-12-14', 0, '0', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\']', 'Twelve years after exploring Pandora and joining the Na’vi, Jake Sully has since raised a family with Neytiri and established himself within the clans of the new world. Of course, peace can only last so long. Especially when the military organization from the original film returns to “finish what they started”.'),
(884, '291167', 'en', 'https://image.tmdb.org/t/p/w500/8LibYV8Jf8BbVZvCh26LJo69oxe.jpg', 'Crystal Skulls', '54.119', '2014-08-12', 4.4, '15', '[\'Adventure\', \'Science Fiction\']', 'A millionaire philanthropist collects the famous Chrystal Skulls trying to tap into their ancient powers. It is up to a team lead by a college professor whose father disappeared searching for the 13th skull to save the world when the first 12 skulls are united and reek havoc on the earth without the control of the 13th skull.'),
(885, '39102', 'ja', 'https://image.tmdb.org/t/p/w500/1lmwZTsqwTtvd3m60pyQfhGM2Ut.jpg', 'ドラゴンボールゼット 超スーパーサイヤ人じんだ孫そん悟ご空くう', '62.659', '1991-03-19', 6.3, '360', '[\'Action\', \'Animation\', \'Science Fiction\']', 'A Super Namekian named Slug comes to invade Earth. But the Z Warriors do their best to stop Slug and his gang.'),
(886, '373571', 'en', 'https://image.tmdb.org/t/p/w500/mzOHg7Q5q9yUmY0b9Esu8Qe6Nnm.jpg', 'Godzilla: King of the Monsters', '75.929', '2019-05-29', 6.7, '4480', '[\'Science Fiction\', \'Action\']', 'Follows the heroic efforts of the crypto-zoological agency Monarch as its members face off against a battery of god-sized monsters, including the mighty Godzilla, who collides with Mothra, Rodan, and his ultimate nemesis, the three-headed King Ghidorah. When these ancient super-species, thought to be mere myths, rise again, they all vie for supremacy, leaving humanity\'s very existence hanging in the balance.'),
(887, '575249', 'ja', 'https://image.tmdb.org/t/p/w500/bsML7r1iijCiGjowbcUfsgtrUWH.jpg', 'Dragon Ball Z: The Real 4-D at 超天下一武道会', '65.959', '2017-06-30', 7.7, '10', '[\'Action\', \'Animation\', \'Adventure\']', 'Dragon Ball Z: The Real 4-D at Super Tenkaichi Budoka is a cinematic attraction at Universal Studios Japan and the successor to Dragon Ball Z: The Real 4-D. Like its predecessor, it is a new installment in the Dragon Ball series, this time primarily featuring the face off between Super Saiyan Blue Goku and Broly God.'),
(888, '41154', 'en', 'https://image.tmdb.org/t/p/w500/90DdoEStzeObs96fsYf4GG544iN.jpg', 'Men in Black 3', '73.75', '2012-05-23', 6.5, '8515', '[\'Action\', \'Comedy\', \'Science Fiction\']', 'Agents J and K are back...in time. J has seen some inexplicable things in his 15 years with the Men in Black, but nothing, not even aliens, perplexes him as much as his wry, reticent partner. But when K\'s life and the fate of the planet are put at stake, Agent J will have to travel back in time to put things right. J discovers that there are secrets to the universe that K never told him - secrets that will reveal themselves as he teams up with the young Agent K to save his partner, the agency, and the future of humankind.'),
(889, '615', 'en', 'https://image.tmdb.org/t/p/w500/v9f9MMrq2nGQrN7cHnQRmEq9lSE.jpg', 'The Passion of the Christ', '67.995', '2004-02-25', 7.4, '3157', '[\'Drama\']', 'A graphic portrayal of the last twelve hours of Jesus of Nazareth\'s life.'),
(890, '131634', 'en', 'https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg', 'The Hunger Games: Mockingjay - Part 2', '66.351', '2015-11-18', 6.9, '10113', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'With the nation of Panem in a full scale war, Katniss confronts President Snow in the final showdown. Teamed with a group of her closest friends – including Gale, Finnick, and Peeta – Katniss goes off on a mission with the unit from District 13 as they risk their lives to stage an assassination attempt on President Snow who has become increasingly obsessed with destroying her. The mortal traps, enemies, and moral choices that await Katniss will challenge her more than any arena she faced in The Hunger Games.'),
(891, '136795', 'en', 'https://image.tmdb.org/t/p/w500/yERBa1y5zNUOTRKQPiDCPIc2fuv.jpg', 'The Heat', '58.533', '2013-06-27', 6.6, '3251', '[\'Action\', \'Comedy\', \'Crime\']', 'Uptight and straight-laced, FBI Special Agent Sarah Ashburn is a methodical investigator with a reputation for excellence--and hyper-arrogance. Shannon Mullins, one of Boston P.D.\'s \"finest,\" is foul-mouthed and has a very short fuse, and uses her gut instinct and street smarts to catch the most elusive criminals. Neither has ever had a partner, or a friend for that matter. When these two wildly incompatible law officers join forces to bring down a ruthless drug lord, they become the last thing anyone expected: Buddies.'),
(892, '347548', 'en', 'https://image.tmdb.org/t/p/w500/lz6G41YdOK1CO2qOkoBe6cudofb.jpg', 'Containment', '54.38', '2015-07-09', 5.9, '133', '[\'Thriller\', \'Horror\', \'Science Fiction\']', 'Neighbors in a block wake one morning to find they have been sealed inside their apartments. Can they work together to find out why? Or will they destroy each other in their fight to escape?'),
(893, '603', 'en', 'https://image.tmdb.org/t/p/w500/p96dm7sCMn4VYAStA6siNz30G1r.jpg', 'The Matrix', '65.273', '1999-03-30', 8.2, '20163', '[\'Action\', \'Science Fiction\']', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.'),
(894, '176983', 'ja', 'https://image.tmdb.org/t/p/w500/dd0HwfxstffjRgbBcQvtw3uqS6O.jpg', 'ワンピース フィルム ゼット', '63.37', '2012-12-15', 7.5, '348', '[\'Action\', \'Adventure\', \'Animation\']', 'Zephyr, now known as Z, rides the seas with only one goal: Destroy all pirates and their dreams at becoming King of Pirates. When Luffy and his crew encounter him at sea, not only are they utterly defeated by the man with an arm made of Seastone, Nami, Robin, and Chopper are turned 10 years younger due to Z\'s minion Ain. Luffy is so determined to win against him that he does not even notice Z\'s master plan that could sacrifice thousands of lives.'),
(895, '125509', 'en', 'https://image.tmdb.org/t/p/w500/8fABep8FSRpeo8Ea4j3rfnoVgkg.jpg', 'Wrong Turn 5: Bloodlines', '64.868', '2012-10-23', 5.3, '652', '[\'Horror\', \'Thriller\']', 'A small West Virginia town is hosting the legendary Mountain Man Festival on Halloween, where throngs of costumed party goers gather for a wild night of music and mischief. But an inbred family of hillbilly cannibals kill the fun when they trick and treat themselves to a group of visiting college students.'),
(896, '62835', 'en', 'https://image.tmdb.org/t/p/w500/rEdGDgRB3gducezNSIyx2lbKQy4.jpg', 'Colombiana', '68.314', '2011-07-27', 6.6, '2001', '[\'Action\', \'Thriller\', \'Crime\', \'Drama\']', 'After witnessing her parents’ murder as a child in Bogota, Cataleya Restrepo grows up to be a stone-cold assassin. She works for her uncle as a hitman by day, but her personal time is spent engaging in vigilante murders that she hopes will lead her to her ultimate target: the mobster responsible for her parents\' death.'),
(897, '10184', 'en', 'https://image.tmdb.org/t/p/w500/jip2ap24Y6JxEgzVRyNqyYssnyR.jpg', 'He\'s Just Not That Into You', '64.353', '2009-02-06', 6.5, '2935', '[\'Comedy\', \'Romance\', \'Drama\']', 'Remember that really cute girl/guy who said they\'d call – and didn\'t? Maybe they lost your number. Maybe they\'re in the hospital. Maybe they\'re awed by your looks, brains or success. Or maybe... They\'re just not that into you.'),
(898, '527776', 'en', 'https://image.tmdb.org/t/p/w500/rVR3uN1yPRqYBBtNFSrEKCpRhaK.jpg', 'Overcomer', '64.118', '2019-08-22', 7.8, '151', '[\'Drama\']', 'After reluctantly agreeing to coach cross-country, high school basketball Coach John Harrison helps the least likely runner attempt the impossible in the biggest race of the year.'),
(899, '557950', 'en', 'https://image.tmdb.org/t/p/w500/9vTf02WXyldeKN4kfwZRwwI4XbG.jpg', 'Mainstream', '58.936', '2021-05-07', 5.2, '25', '[\'Comedy\', \'Drama\']', 'A young woman finds a path to internet stardom when she starts making videos with a charismatic stranger.'),
(900, '10386', 'en', 'https://image.tmdb.org/t/p/w500/ct04FCFLPImNG5thcPLRnVsZlmS.jpg', 'The Iron Giant', '58.471', '1999-08-06', 7.9, '4254', '[\'Family\', \'Animation\', \'Adventure\', \'Science Fiction\', \'Comedy\']', 'In the small town of Rockwell, Maine in October 1957, a giant metal machine befriends a nine-year-old boy and ultimately finds its humanity by unselfishly saving people from their own fears and prejudices.'),
(901, '71672', 'en', 'https://image.tmdb.org/t/p/w500/l1vD4GY7tlT420KJ3xWTzyQ2Aa9.jpg', 'Wrong Turn 4: Bloody Beginnings', '60.544', '2011-10-17', 5.7, '736', '[\'Horror\', \'Thriller\']', 'Follows a group of friends that decide to go snowmobiling during their winter break. They make a \"wrong turn\", getting lost in a storm.'),
(902, '298618', 'en', 'https://image.tmdb.org/t/p/w500/rktDFPbfHfUbArZ6OOOKsXcv0Bm.jpg', 'The Flash', '70.092', '2022-11-02', 0, '0', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\', \'Drama\']', 'The Flash travels back in time to prevent the murder of his mother, an act which disrupts time significantly.'),
(903, '351819', 'en', 'https://image.tmdb.org/t/p/w500/nkGhv7WMbyX7tL8CJkvMY3S2lW.jpg', 'Fifty Shades of Black', '69.693', '2016-01-28', 4.9, '1104', '[\'Romance\', \'Comedy\']', 'An inexperienced college student meets a wealthy businessman whose sexual practices put a strain on their relationship.'),
(904, '245891', 'en', 'https://image.tmdb.org/t/p/w500/wXqWR7dHncNRbxoEGybEy7QTe9h.jpg', 'John Wick', '71.346', '2014-10-22', 7.4, '14953', '[\'Action\', \'Thriller\']', 'Ex-hitman John Wick comes out of retirement to track down the gangsters that took everything from him.'),
(905, '333484', 'en', 'https://image.tmdb.org/t/p/w500/ezcS78TIjgr85pVdaPDd2rSPVNs.jpg', 'The Magnificent Seven', '61.909', '2016-09-14', 6.3, '4806', '[\'Adventure\', \'Action\', \'Western\']', 'Looking to mine for gold, greedy industrialist Bartholomew Bogue seizes control of the Old West town of Rose Creek. With their lives in jeopardy, Emma Cullen and other desperate residents turn to bounty hunter Sam Chisolm for help. Chisolm recruits an eclectic group of gunslingers to take on Bogue and his ruthless henchmen. With a deadly showdown on the horizon, the seven mercenaries soon find themselves fighting for more than just money once the bullets start to fly.'),
(906, '621876', 'en', 'https://image.tmdb.org/t/p/w500/syobJCxZcIJl0OpjNroZSQKa1kW.jpg', 'Flora & Ulysses', '65.568', '2021-02-19', 6.7, '156', '[\'Family\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'When Flora rescues a squirrel she names Ulysses, she is amazed to discover he possesses unique superhero powers, which take them on an adventure of humorous complications that ultimately change Flora\'s life--and her outlook--forever.'),
(907, '409502', 'en', 'https://image.tmdb.org/t/p/w500/P4bxuNq5XT0Wc3MYpoLP52e0P6.jpg', 'I\'m Not Ashamed', '58.501', '2016-10-21', 7.4, '189', '[\'Drama\']', 'Based on the inspiring and powerful true story and journal entries of Rachel Joy Scott- the first student killed in the Columbine High School shooting in 1999.'),
(908, '274855', 'en', 'https://image.tmdb.org/t/p/w500/nrsx0jEaBgXq4PWo7SooSnYJTv.jpg', 'Geostorm', '60.697', '2017-10-13', 6.1, '3723', '[\'Action\', \'Science Fiction\', \'Thriller\']', 'After an unprecedented series of natural disasters threatened the planet, the world\'s leaders came together to create an intricate network of satellites to control the global climate and keep everyone safe. But now, something has gone wrong: the system built to protect Earth is attacking it, and it becomes a race against the clock to uncover the real threat before a worldwide geostorm wipes out everything and everyone along with it.'),
(909, '287590', 'ja', 'https://image.tmdb.org/t/p/w500/gxKfP9278RK4t3J8vLXoFfB8ihl.jpg', '聖闘士星矢 LEGEND of SANCTUARY', '74.224', '2014-06-21', 6.4, '500', '[\'Action\', \'Animation\', \'Fantasy\']', 'Warriors called \"Saints\" are the champions of hope who have always appeared since the Age of Myth whenever evil threatens the world. In this present day story, many years since the long fought \"Holy War\" we find Saori Kido, a girl troubled by her mysterious powers. She is saved by a boy, Seiya \"Bronze Saint\" from a sudden attack by an assassin, through the accident Saori realizes her destiny and mission and decides to go to \"Sanctuary\" with Seiya and his company of Bronze Saints. In Sanctuary they confront \"Pope\" and wage a desperate battle against the greatest Saints, the \"Gold Saints\".'),
(910, '339403', 'en', 'https://image.tmdb.org/t/p/w500/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', 'Baby Driver', '63.226', '2017-06-28', 7.5, '12495', '[\'Action\', \'Crime\']', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.'),
(911, '68718', 'en', 'https://image.tmdb.org/t/p/w500/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg', 'Django Unchained', '69.198', '2012-12-25', 8.1, '21484', '[\'Drama\', \'Western\']', 'With the help of a German bounty hunter, a freed slave sets out to rescue his wife from a brutal Mississippi plantation owner.'),
(912, '516329', 'en', 'https://image.tmdb.org/t/p/w500/cMch3tiexw3FdOEeZxMWVel61Xg.jpg', 'Antlers', '61.795', '2021-10-28', 5.9, '37', '[\'Drama\', \'Horror\', \'Mystery\']', 'A young teacher discovers that her troubled student\'s father and younger brother harbor a deadly supernatural secret. Taking the boy into her care, the teacher must fight for their survival against horrors beyond imagination.'),
(913, '71552', 'en', 'https://image.tmdb.org/t/p/w500/de5QBIdVR4dnkBZ4a0zjkS4lTg.jpg', 'American Reunion', '66.679', '2012-04-04', 6.3, '3636', '[\'Comedy\']', 'The characters we met a little more than a decade ago return to East Great Falls for their high-school reunion. In one long-overdue weekend, they will discover what has changed, who hasn’t, and that time and distance can’t break the bonds of friendship.'),
(914, '527641', 'en', 'https://image.tmdb.org/t/p/w500/kreTuJBkUjVWePRfhHZuYfhNE1T.jpg', 'Five Feet Apart', '66.267', '2019-03-14', 8.4, '4452', '[\'Romance\', \'Drama\']', 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There\'s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.'),
(915, '9730', 'en', 'https://image.tmdb.org/t/p/w500/1J7zudfR3VLPwAf9lK5YPfSu0n6.jpg', 'Friday the 13th: The Final Chapter', '53.59', '1984-04-13', 6.1, '889', '[\'Horror\']', 'After being mortally wounded and taken to the morgue, murderer Jason Voorhees spontaneously revives and embarks on a killing spree as he makes his way back to his home at Crystal Lake.'),
(916, '282069', 'ja', 'https://image.tmdb.org/t/p/w500/lNzCFguC8wEyJWP89ewQYK8d2nJ.jpg', '寄生獣', '54.381', '2014-11-29', 7.1, '162', '[\'Science Fiction\', \'Horror\']', 'Alien pods come to Earth and, naturally, start taking over Human Hosts. One such pod only manages to take over one human\'s, Shin Izumi, right arm. Together they grow and co-exist, all the while the other aliens are making meals of other humans; Shin feels he must put a stop to it all, but his alien, Migi, doesn\'t see why.'),
(917, '609972', 'en', 'https://image.tmdb.org/t/p/w500/wRy3SwJFE55iL2bfKqECzP2qyrd.jpg', 'Paranormal Activity: Next of Kin', '58.577', '2021-10-29', 6.9, '88', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Margot, a documentary filmmaker, heads to a secluded Amish community in the hopes of learning about her long-lost mother and extended family. Following a string of strange occurrences and discoveries, she comes to realize this community may not be what it seems.'),
(918, '46195', 'en', 'https://image.tmdb.org/t/p/w500/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg', 'Rio', '61.019', '2011-04-03', 6.7, '5270', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\']', 'Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.'),
(919, '791910', 'en', 'https://image.tmdb.org/t/p/w500/qahz9340FEDIo4FsNK3aFwzcw9C.jpg', 'Rise of the Mummy', '60.788', '2021-04-03', 5.1, '28', '[\'Horror\', \'Science Fiction\']', 'A group of archaeology students awaken an ancient mummy. After being trapped in a time loop, the only way they can escape, is to defeat the mummy. As the body count rises, it seems the Mummy has to collect the souls of those who woke him to be able to walk the earth - for good.'),
(920, '413594', 'ja', 'https://image.tmdb.org/t/p/w500/2szdEK0Mr0RG0nWGFVTseNQHbnP.jpg', '劇場版 ソードアート・オンライン -オーディナル・スケール-', '64.121', '2017-02-18', 7.7, '469', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\', \'Romance\', \'Science Fiction\']', 'In 2026, four years after the infamous Sword Art Online incident, a revolutionary new form of technology has emerged: the Augma, a device that utilizes an Augmented Reality system. Unlike the Virtual Reality of the NerveGear and the Amusphere, it is perfectly safe and allows players to use it while they are conscious, creating an instant hit on the market. The most popular application for the Augma is the game Ordinal Scale, which immerses players in a fantasy role-playing game with player rankings and rewards.  Following the new craze, Kirito\'s friends dive into the game, and despite his reservations about the system, Kirito eventually joins them. While at first it appears to be just fun and games, they soon find out that the game is not all that it seems...'),
(921, '675327', 'en', 'https://image.tmdb.org/t/p/w500/t7EUMSlfUN3jUSZUJOLURAzJzZs.jpg', 'Shadow in the Cloud', '58.119', '2021-01-01', 5.9, '482', '[\'Horror\', \'Action\', \'War\']', 'A WWII pilot traveling with top secret documents on a B-17 Flying Fortress encounters an evil presence on board the flight.'),
(922, '7555', 'en', 'https://image.tmdb.org/t/p/w500/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg', 'Rambo', '61.612', '2008-01-24', 6.6, '2839', '[\'Action\', \'Thriller\']', 'When governments fail to act on behalf of captive missionaries, ex-Green Beret John James Rambo sets aside his peaceful existence along the Salween River in a war-torn region of Thailand to take action.  Although he\'s still haunted by violent memories of his time as a U.S. soldier during the Vietnam War, Rambo can hardly turn his back on the aid workers who so desperately need his help.'),
(923, '57800', 'en', 'https://image.tmdb.org/t/p/w500/dfp1BZF7FxbBUyzHvMOI9t8NWDD.jpg', 'Ice Age: Continental Drift', '72.859', '2012-06-27', 6.3, '6128', '[\'Animation\', \'Comedy\', \'Adventure\', \'Family\']', 'Manny, Diego, and Sid embark upon another adventure after their continent is set adrift. Using an iceberg as a ship, they encounter sea creatures and battle pirates as they explore a new world.'),
(924, '417384', 'en', 'https://image.tmdb.org/t/p/w500/uy0dNFbhRhHBLwpOGpcTw9UEwdX.jpg', 'Scary Stories to Tell in the Dark', '67.473', '2019-08-08', 6.5, '1985', '[\'Horror\', \'Thriller\']', 'Mill Valley, Pennsylvania, Halloween night, 1968. After playing a joke on a school bully, Sarah and her friends decide to sneak into a supposedly haunted house that once belonged to the powerful Bellows family, unleashing dark forces that they will be unable to control.'),
(925, '76489', 'en', 'https://image.tmdb.org/t/p/w500/b0nNQCL90RGTwjxLEFsFFLQZKNe.jpg', 'The Three Stooges', '57.778', '2012-04-13', 5.7, '412', '[\'Comedy\']', 'While trying to save their childhood orphanage, Moe, Larry and Curly inadvertently stumble into a murder plot and wind up starring in a reality TV show.'),
(926, '189349', 'ja', 'https://image.tmdb.org/t/p/w500/imvclUHRdAte5RUZQl3FLXK0zIM.jpg', '炎の中忍試験! ナルトvs木ノ葉丸!!', '64.887', '2011-07-30', 7.5, '19', '[\'Animation\', \'Action\']', 'Naruto faces off against his old pupil Konohamaru in a tournament during the chuunin entrance exams.'),
(927, '664168', 'en', 'https://image.tmdb.org/t/p/w500/d2UCD7xwWFKucozkKcKBiCayJC6.jpg', 'Fat Ass Zombies', '62.376', '2020-02-18', 4.8, '43', '[\'Horror\', \'Comedy\']', 'In a sleepy town, one man, a wannabe horror film director is about to have his life and the world he knows change forever. Finally, he gets the big break he has been waiting a lifetime for, but its not Hollywood knocking on his door.'),
(928, '12092', 'en', 'https://image.tmdb.org/t/p/w500/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg', 'Alice in Wonderland', '64.736', '1951-07-28', 7.2, '4703', '[\'Animation\', \'Family\', \'Fantasy\', \'Adventure\']', 'On a golden afternoon, young Alice follows a White Rabbit, who disappears down a nearby rabbit hole. Quickly following him, she tumbles into the burrow - and enters the merry, topsy-turvy world of Wonderland! Memorable songs and whimsical escapades highlight Alice\'s journey, which culminates in a madcap encounter with the Queen of Hearts - and her army of playing cards!'),
(929, '785457', 'en', 'https://image.tmdb.org/t/p/w500/1bkcOEt4zvc5tBl6xFxTbkSqhEQ.jpg', 'Afterlife of the Party', '59.296', '2021-09-02', 6.9, '259', '[\'Fantasy\', \'Comedy\', \'Drama\']', 'A social butterfly who dies during her birthday week is given a second chance to right her wrongs on Earth.'),
(930, '343668', 'en', 'https://image.tmdb.org/t/p/w500/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', 'Kingsman: The Golden Circle', '93.516', '2017-09-20', 7, '8079', '[\'Action\', \'Adventure\', \'Comedy\', \'Crime\', \'Thriller\']', 'When an attack on the Kingsman headquarters takes place and a new villain rises, Eggsy and Merlin are forced to work together with the American agency known as the Statesman to save the world.'),
(931, '62177', 'en', 'https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', 'Brave', '64.823', '2012-06-21', 7, '11012', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\', \'Action\', \'Fantasy\']', 'Brave is set in the mystical Scottish Highlands, where Mérida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Mérida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Mérida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Mérida’s quest — and serving as comic relief — are the kingdom’s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.'),
(932, '137113', 'en', 'https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', 'Edge of Tomorrow', '53.707', '2014-05-27', 7.6, '11079', '[\'Action\', \'Science Fiction\']', 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.'),
(933, '609202', 'ja', 'https://image.tmdb.org/t/p/w500/mrW03HqQnw1kw1tF3xuTWqWVJcM.jpg', 'Blackfox', '67.259', '2019-10-05', 7.1, '17', '[\'Animation\', \'Action\', \'Drama\', \'Science Fiction\']', 'Rikka is a ninja descendant. Her grandfather Hyoe is the last chief of their ninja clan and her father is a cyborg researcher. Both are killed when a weapons\' company raids his lab to use his research. Rikka sets out to avenge their deaths.'),
(934, '10625', 'en', 'https://image.tmdb.org/t/p/w500/2ZkuQXvVhh45uSvkBej4S7Ix1NJ.jpg', 'Mean Girls', '57.816', '2004-04-30', 7.2, '6871', '[\'Comedy\']', 'Cady Heron is a hit with The Plastics, the A-list girl clique at her new school, until she makes the mistake of falling for Aaron Samuels, the ex-boyfriend of alpha Plastic Regina George.'),
(935, '725649', 'es', 'https://image.tmdb.org/t/p/w500/uEilmHRJ2YElyZ9kSjrTUjEnTkt.jpg', 'Lavaperros', '57.511', '2020-10-09', 6.4, '25', '[\'Comedy\', \'Drama\', \'Crime\']', 'When a narco past his prime refuses to pay a debt to an upstart, only a secret stash of money can save his men. But guess what the gardener just found?'),
(936, '61791', 'en', 'https://image.tmdb.org/t/p/w500/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg', 'Rise of the Planet of the Apes', '52.365', '2011-08-03', 7.3, '9523', '[\'Thriller\', \'Action\', \'Drama\', \'Science Fiction\']', 'A highly intelligent chimpanzee named Caeser has been living a peaceful suburban life ever since he was born. But when he gets taken to a cruel primate facility, Caeser decides to revolt against those who have harmed him.'),
(937, '39108', 'ja', 'https://image.tmdb.org/t/p/w500/7uRu9EA3nie0n2mlVDDLlTI3IzC.jpg', 'ドラゴンボールZ 龍拳爆発!!悟空がやらねば誰がやる', '64.946', '1995-07-15', 7.2, '465', '[\'Animation\', \'Action\', \'Science Fiction\']', 'The Z Warriors discover an unopenable music box and are told to open it with the Dragon Balls. The contents turn out to be a warrior named Tapion who had sealed himself inside along with a monster called Hildegarn. Goku must now perfect a new technique to defeat the evil monster.'),
(938, '23023', 'en', 'https://image.tmdb.org/t/p/w500/cRZvw3bPomtucIUtMHZ3qPIYtYs.jpg', 'Tooth Fairy', '59.992', '2010-01-14', 5.5, '1596', '[\'Comedy\', \'Family\', \'Fantasy\']', 'When minor-league hockey player Derek Thompson -- who has a penchant for knocking out his opponents\' teeth every time he plays -- disillusions a fan, he is sentenced to a stint for one week as a bona fide, tutu-clad, real-life tooth fairy. Soon, Derek is inspired to rekindle his youthful dreams.'),
(939, '58574', 'en', 'https://image.tmdb.org/t/p/w500/y1MYZkwhZK6L0Jy4YMuPktzDOfn.jpg', 'Sherlock Holmes: A Game of Shadows', '64.176', '2011-11-22', 7.1, '8579', '[\'Adventure\', \'Action\', \'Crime\', \'Mystery\']', 'There is a new criminal mastermind at large (Professor Moriarty) and not only is he Holmes’ intellectual equal, but his capacity for evil and lack of conscience may give him an advantage over the  detective.'),
(940, '461083', 'ja', 'https://image.tmdb.org/t/p/w500/suy8nFraq8vASRKz6GcL6p9FEvN.jpg', '劇場版 Fate/kaleid liner プリズマ☆イリヤ 雪下の誓い', '60.126', '2017-08-26', 6.6, '15', '[\'Animation\', \'Action\', \'Fantasy\']', 'After succumbing to an unenviable fate, Kiritsugu Emiya has left Shirou Emiya the duty to save mankind in his place. The world is dying and time is ticking, but when the salvation Shirou seeks is at the cost of his only family left—his younger sister—will he still have the heart to pursue this duty?  Shirou is now pressed with the choice to continue being a hero of justice—or become the very evil his ideal has vowed to vanquish. The orphan is alone once again, yet his body is still made of swords. The Fifth Holy Grail War now begins with his oath under snow.'),
(941, '534338', 'en', 'https://image.tmdb.org/t/p/w500/d9TeB8VLCgwSph2OSYK3lcHGf1f.jpg', 'An Interview with God', '66.624', '2018-08-20', 7.1, '182', '[\'Drama\', \'Mystery\']', 'An up-and-coming journalist finds his world and faith increasingly challenged when he\'s granted the interview of a lifetime – with someone who claims to be God.'),
(942, '339846', 'en', 'https://image.tmdb.org/t/p/w500/6HE4xd8zloDqmjMZuhUCCw2UcY1.jpg', 'Baywatch', '54.513', '2017-05-12', 6.1, '6656', '[\'Comedy\', \'Action\', \'Crime\']', 'Devoted lifeguard Mitch Buchannon butts heads with a brash new recruit. Together, they uncover a local criminal plot that threatens the future of the Bay.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(943, '123553', 'en', 'https://image.tmdb.org/t/p/w500/zaK1aVn5vXfNwLIDop9U8XA3Q0x.jpg', 'The Mortal Instruments: City of Bones', '54.656', '2013-08-21', 6.4, '3886', '[\'Fantasy\', \'Action\', \'Mystery\']', 'In New York City, Clary Fray, a seemingly ordinary teenager, learns that she is descended from a line of Shadowhunters — half-angel warriors who protect humanity from evil forces. After her mother disappears, Clary joins forces with a group of Shadowhunters and enters Downworld, an alternate realm filled with demons, vampires, and a host of other creatures. Clary and her companions must find and protect an ancient cup that holds the key to her mother\'s future.'),
(944, '2758', 'en', 'https://image.tmdb.org/t/p/w500/sdxT2VjVSx9DRicwnuECUdBHeE7.jpg', 'Addams Family Values', '56.147', '1993-11-19', 6.9, '2145', '[\'Comedy\', \'Family\', \'Fantasy\']', 'Siblings Wednesday and Pugsley Addams will stop at nothing to get rid of Pubert, the new baby boy adored by parents Gomez and Morticia. Things go from bad to worse when the new \"black widow\" nanny, Debbie Jellinsky, launches her plan to add Fester to her collection of dead husbands.'),
(945, '811592', 'en', 'https://image.tmdb.org/t/p/w500/3OXiTjU30gWtqxmx4BU9RVp2OTv.jpg', 'One Shot', '49.562', '2021-11-05', 4.8, '6', '[\'Action\']', 'An elite squad of Navy SEAL\'s, on a covert mission to transport a prisoner off a CIA black site island prison, are trapped when insurgents attack while trying to rescue the same prisoner.'),
(946, '16985', 'en', 'https://image.tmdb.org/t/p/w500/wZnEw0avASZwBWcJo5F1pdJnmO2.jpg', 'Legally Blondes', '70.345', '2009-04-28', 5.6, '203', '[\'Comedy\']', 'Moving from England to California, the youngest cousins of Elle Woods must defend themselves when their schools reigning forces turn on the girls and try to frame them for a crime.'),
(947, '638566', 'ja', 'https://image.tmdb.org/t/p/w500/8OkxtHotJnegiBbWQSz8fD60NEc.jpg', 'NARUTO to BORUTO The Live 2019', '68.98', '2019-05-05', 6.8, '19', '[\'Documentary\']', '“NARUTO to BORUTO THE LIVE 2019”, a special event for the 20th anniversary of the first publication of “NARUTO” series in Weekly Shonen Jump!! Featuring live performances by artists performing the theme songs of both “NARUTO” and “BORUTO: NARUTO NEXT GENERATIONS”, anime cast members reading original story episodes, and more.'),
(948, '825597', 'en', 'https://image.tmdb.org/t/p/w500/ou1cuRaV22FbDq8oEZeyR6C6P6l.jpg', 'Maggie Simpson in The Force Awakens from Its Nap', '59.952', '2021-05-04', 6.9, '99', '[\'Family\', \'Animation\', \'Comedy\', \'Science Fiction\']', 'In a daycare far, far away… but still in Springfield, Maggie is on an epic quest for her stolen pacifier. Her adventure brings her face-to-face with young Padawans, Sith Lords, familiar droids, Rebel scum, and an ultimate battle against the dark side, in this original short celebrating the Star Wars galaxy.'),
(949, '476292', 'ja', 'https://image.tmdb.org/t/p/w500/hL3NqRE2ccR4Y2sYSJTrmalRjrz.jpg', 'さよならの朝に約束の花をかざろう', '71.389', '2018-02-24', 8.4, '392', '[\'Animation\', \'Fantasy\', \'Romance\', \'Drama\']', 'Maquia is a member of a special race called the Iorph who can live for hundreds of years. However, Maquia has always felt lonely despite being surrounded by her people, as she was orphaned from a young age. She daydreams about the outside world, but dares not travel from her home due to the warnings of the clan\'s chief.  One day the kingdom of Mezarte invades her homeland. They already have what is left of the giant dragons, the Renato, under their control, and now their king wishes to add the immortality to his bloodline.  They ravage the Iorph homeland and kill most of its inhabitants. Caught in the midst of the attack, Maquia is carried off by one of the Renato. It soon dies, and she is left deserted in a forest, now truly alone save for the cries of a single baby off in the distance. Maquia finds the baby in a destroyed village and decides to raise him as her own, naming him Ariel. Although she knows nothing of the human world, how to raise a child that ages much faster than her.'),
(950, '25565', 'en', 'https://image.tmdb.org/t/p/w500/q61s5H2DRHSJYx75adOtTL3aFuY.jpg', 'Transformers: Beginnings', '61.116', '2006-10-16', 6.8, '187', '[\'Action\', \'Animation\', \'Science Fiction\', \'Thriller\']', 'On their home planet of Cybertron, the Autobots and Decepticons are involved in an explosive battle over the coveted AllSpark. With the fate of the universe at stake, the Autobots send it far from the reaches of the ruthless Megatron, leader of the Decepticons. But there are even more surprises in store when it crash-lands on Earth.'),
(951, '703745', 'en', 'https://image.tmdb.org/t/p/w500/bKthjUmxjHjvJK8FktFfQdmwP12.jpg', 'Deep Blue Sea 3', '69.539', '2020-08-25', 5.9, '178', '[\'Action\', \'Horror\', \'Science Fiction\']', 'Dr. Emma Collins and her team are spending their third summer on the island of Little Happy studying the effect of climate change on the great white sharks who come to the nearby nursery every year to give birth. Along with the last two inhabitants of this former fishing village, their peaceful life is disrupted when a \"scientific\" team led by her ex-boyfriend and marine biologist Richard show up looking for three bull sharks who we soon learn aren\'t just any bull sharks.'),
(952, '290859', 'en', 'https://image.tmdb.org/t/p/w500/vqzNJRH4YyquRiWxCCOH0aXggHI.jpg', 'Terminator: Dark Fate', '59.969', '2019-10-23', 6.5, '3773', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Decades after Sarah Connor prevented Judgment Day, a lethal new Terminator is sent to eliminate the future leader of the resistance. In a fight to save mankind, battle-hardened Sarah Connor teams up with an unexpected ally and an enhanced super soldier to stop the deadliest Terminator yet.'),
(953, '62206', 'en', 'https://image.tmdb.org/t/p/w500/12VgS5G6OG7ANKrSbhtUD2POHb8.jpg', '30 Minutes or Less', '56.347', '2011-08-11', 5.7, '1294', '[\'Action\', \'Adventure\', \'Comedy\']', 'Two fledgling criminals kidnap a pizza delivery guy, strap a bomb to his chest, and advise him that he has mere hours to rob a bank or else...'),
(954, '257344', 'en', 'https://image.tmdb.org/t/p/w500/d26S5EfVXLNxRXqyFy1yyl3qRq3.jpg', 'Pixels', '55.579', '2015-07-16', 5.7, '6187', '[\'Action\', \'Comedy\', \'Science Fiction\']', 'Video game experts are recruited by the military to fight 1980s-era video game characters who\'ve attacked New York.'),
(955, '447200', 'en', 'https://image.tmdb.org/t/p/w500/52ml62vClzrlqvXZq2FEW6UF6c1.jpg', 'Skyscraper', '68.699', '2018-07-11', 6.3, '3912', '[\'Action\', \'Thriller\']', 'Framed and on the run, a former FBI agent must save his family from a blazing fire in the world\'s tallest building.'),
(956, '278154', 'en', 'https://image.tmdb.org/t/p/w500/okF78W1AcXAenlYFE3vna9Uuqjp.jpg', 'Ice Age: Collision Course', '70.038', '2016-06-23', 6, '3543', '[\'Adventure\', \'Animation\', \'Family\', \'Comedy\', \'Science Fiction\']', 'Set after the events of Continental Drift, Scrat\'s epic pursuit of his elusive acorn catapults him outside of Earth, where he accidentally sets off a series of cosmic events that transform and threaten the planet. To save themselves from peril, Manny, Sid, Diego, and the rest of the herd leave their home and embark on a quest full of thrills and spills, highs and lows, laughter and adventure while traveling to exotic new lands and locations.'),
(957, '47964', 'en', 'https://image.tmdb.org/t/p/w500/qJ0csDXAVFMsNn0cRcjy6W6PxAK.jpg', 'A Good Day to Die Hard', '59.282', '2013-02-06', 5.3, '5355', '[\'Action\', \'Thriller\']', 'Iconoclastic, take-no-prisoners cop John McClane, finds himself for the first time on foreign soil after traveling to Moscow to help his wayward son Jack - unaware that Jack is really a highly-trained CIA operative out to stop a nuclear weapons heist. With the Russian underworld in pursuit, and battling a countdown to war, the two McClanes discover that their opposing methods make them unstoppable heroes.'),
(958, '852663', 'en', 'https://image.tmdb.org/t/p/w500/4Su0Agl6BKynqI6dKYTA8CycTk7.jpg', 'LEGO Monkie Kid: A Hero Is Born', '91.678', '2020-06-13', 2, '1', '[\'Animation\', \'TV Movie\', \'Action\', \'Comedy\', \'Fantasy\']', 'Monkey King comes to life as a young boy named MK, obsessed with the legends of old, discovers Monkey King\'s magical staff. After witnessing Red Son and Princess Iron Fan release the Demon Bull King from his prison under the mountain, MK accidentally grabs Monkey King’s magical staff and escapes, sending him on a journey to return the staff to Monkey King in order for him to save the day.'),
(959, '82507', 'en', 'https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg', 'Sinister', '56.169', '2012-03-29', 6.8, '4153', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Found footage helps a true-crime novelist realize how and why a family was murdered in his new home, though his discoveries put his entire family in the path of a supernatural entity.'),
(960, '297802', 'en', 'https://image.tmdb.org/t/p/w500/ufl63EFcc5XpByEV2Ecdw6WJZAI.jpg', 'Aquaman', '64.799', '2018-07-06', 6.9, '11036', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Once home to the most advanced civilization on Earth, Atlantis is now an underwater kingdom ruled by the power-hungry King Orm. With a vast army at his disposal, Orm plans to conquer the remaining oceanic people and then the surface world. Standing in his way is Arthur Curry, Orm\'s half-human, half-Atlantean brother and true heir to the throne.'),
(961, '359983', 'en', 'https://image.tmdb.org/t/p/w500/pzcQ7cQBHIdsKLN4exd7bCyy1pk.jpg', 'The Lion Guard: Return of the Roar', '57.009', '2015-11-22', 6.5, '758', '[\'Family\', \'TV Movie\', \'Animation\']', 'Set in the African savannah, the film follows Kion as he assembles the members of the \'Lion Guard\'. Throughout the film, the diverse team of young animals will learn how to utilize each of their unique abilities to solve problems and accomplish tasks to maintain balance within the Circle of Life, while also introducing viewers to the vast array of animals that populate the prodigious African landscape.'),
(962, '174772', 'en', 'https://image.tmdb.org/t/p/w500/tbsfaBjiAW5vfrV06R8KCOzVOYy.jpg', 'Europa Report', '60.555', '2013-06-27', 6.3, '1027', '[\'Science Fiction\', \'Thriller\']', 'A crew of international astronauts are sent on a private mission to Jupiter\'s fourth moon.'),
(963, '87428', 'en', 'https://image.tmdb.org/t/p/w500/oaLhdRsZ5Mq8VfZtA4Wlvjzzn0X.jpg', 'That\'s My Boy', '54.801', '2012-06-14', 5.7, '1357', '[\'Comedy\', \'Drama\']', 'While in his teens, Donny fathered a son, Todd, and raised him as a single parent up until Todd\'s 18th birthday. Now, after not seeing each other for years, Todd\'s world comes crashing down when Donny resurfaces just before Todd\'s wedding.'),
(964, '511987', 'en', 'https://image.tmdb.org/t/p/w500/4WH6AZd473lRZ3hUp8TYiv2LfZW.jpg', 'Crawl', '53.501', '2019-07-11', 6.3, '2317', '[\'Thriller\', \'Horror\']', 'When a huge hurricane hits her hometown in Florida, Haley ignores evacuation orders to look for her father. After finding him badly wounded, both are trapped by the flood. With virtually no time to escape the storm, they discover that rising water levels are the least of their problems.'),
(965, '2082', 'en', 'https://image.tmdb.org/t/p/w500/cD8JrfSEI4j7WVnKM1GdiYzMoUh.jpg', 'Halloween', '55.328', '2007-08-31', 6.2, '1664', '[\'Horror\']', 'After being committed for 17 years, Michael Myers, now a grown man and still very dangerous, escapes from the mental institution (where he was committed as a 10 year old) and he immediately returns to Haddonfield, where he wants to find his baby sister, Laurie. Anyone who crosses his path is in mortal danger'),
(966, '403310', 'ja', 'https://image.tmdb.org/t/p/w500/mvLYHpJCFK0gur7mlrLMA8z2a9F.jpg', 'HK 変態仮面　アブノーマル・クライシス', '60.071', '2016-05-14', 6.3, '43', '[\'Action\', \'Comedy\']', 'News about the disappearance of panties is still being covered every day.  Kyosuke (Ryohei Suzuki) still wears Aiko Completo\'s (Fumika Shimizu) panties to battle evil. Meanwhile, Aiko has mixed emotions and decides to get her panties back. Kyosuke suffers from the loss of Aiko\'s panties and disappears, but his biggest enemy yet is about to materialise...'),
(967, '263472', 'en', 'https://image.tmdb.org/t/p/w500/cUC4rUb1Cs2KMaZ6RD4uYUEEwls.jpg', 'Knock Knock', '57.277', '2015-06-26', 5.2, '2322', '[\'Drama\', \'Thriller\', \'Horror\']', 'When a devoted husband and father is left home alone for the weekend, two stranded young women unexpectedly knock on his door for help. What starts out as a kind gesture results in a dangerous seduction and a deadly game of cat and mouse.'),
(968, '399579', 'en', 'https://image.tmdb.org/t/p/w500/xRWht48C2V8XNfzvPehyClOvDni.jpg', 'Alita: Battle Angel', '64.435', '2019-01-31', 7.2, '7024', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'When Alita awakens with no memory of who she is in a future world she does not recognize, she is taken in by Ido, a compassionate doctor who realizes that somewhere in this abandoned cyborg shell is the heart and soul of a young woman with an extraordinary past.'),
(969, '726916', 'sv', 'https://image.tmdb.org/t/p/w500/g1OngP0vWRGrafk99vBgz6i4Xln.jpg', 'Vinterviken', '60.946', '2021-09-08', 5.6, '46', '[\'Romance\', \'Drama\']', 'Elisabeth and John-John live in the same city, but they inhabit different worlds.'),
(970, '87818', 'en', 'https://image.tmdb.org/t/p/w500/uYa06GxHsCsELx9vOQ11vsT0Aa6.jpg', 'Movie 43', '61.015', '2013-01-01', 4.5, '1813', '[\'Comedy\']', 'Fifteen directors and an all-star cast created this twisted comedy that follows three teens on the hunt for the world\'s most banned film.'),
(971, '835666', 'pt', 'https://image.tmdb.org/t/p/w500/k0SuLsAqIJaLVQkQZpZ2qeaUPnR.jpg', 'Como Hackear Seu Chefe', '51.145', '2021-06-04', 6.7, '34', '[\'Comedy\']', 'Victor accidentally sends a compromising email to his nagging boss. With the help of his office crush and a clueless friend, he\'ll try to save his job while having to deal with a rook hacker the porn industry, a children\'s online game and Smiley, the company mascot.'),
(972, '454640', 'en', 'https://image.tmdb.org/t/p/w500/fKk4bfnouKEY5iPzYDMcVmtgDEy.jpg', 'The Angry Birds Movie 2', '61.724', '2019-08-02', 7.2, '1163', '[\'Animation\', \'Comedy\', \'Adventure\', \'Family\']', 'Red, Chuck, Bomb and the rest of their feathered friends are surprised when a green pig suggests that they put aside their differences and unite to fight a common threat. Aggressive birds from an island covered in ice are planning to use an elaborate weapon to destroy the fowl and swine.'),
(973, '385103', 'en', 'https://image.tmdb.org/t/p/w500/jHo2M1OiH9Re33jYtUQdfzPeUkx.jpg', 'Scoob!', '63.989', '2020-07-11', 7.3, '1236', '[\'Animation\', \'Family\', \'Comedy\', \'Adventure\']', 'In Scooby-Doo’s greatest adventure yet, see the never-before told story of how lifelong friends Scooby and Shaggy first met and how they joined forces with young detectives Fred, Velma, and Daphne to form the famous Mystery Inc. Now, with hundreds of cases solved, Scooby and the gang face their biggest, toughest mystery ever: an evil plot to unleash the ghost dog Cerberus upon the world. As they race to stop this global “dogpocalypse,” the gang discovers that Scooby has a secret legacy and an epic destiny greater than anyone ever imagined.'),
(974, '776797', 'zh', 'https://image.tmdb.org/t/p/w500/mi5lh2brPMzuWYddyUKuCtcnjt1.jpg', '哭悲', '57.304', '2021-01-22', 6.2, '8', '[\'Thriller\', \'Horror\']', 'A young couple is pushed to the limits of sanity as they attempt to be reunited amid the chaos of a pandemic outbreak. The streets erupt into violence and depravity, as those infected are driven to enact in the most cruel and ghastly things imaginable.'),
(975, '518244', 'en', 'https://image.tmdb.org/t/p/w500/eH2ben4ZuvDKxkgAgrPAVOsuJGy.jpg', 'Scandalous Sex', '64.748', '2004-01-01', 7.1, '67', '[\'Drama\']', 'A daughter seeks to restore the reputation of her disgraced father, a wronged college professor. With help of a professional student, she must overcome an ambitious sorority bitch and corrupt college dean.'),
(976, '155', 'en', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', 'The Dark Knight', '60.734', '2008-07-14', 8.5, '26148', '[\'Drama\', \'Action\', \'Crime\', \'Thriller\']', 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.'),
(977, '776503', 'en', 'https://image.tmdb.org/t/p/w500/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', 'CODA', '50.911', '2021-07-30', 8.3, '265', '[\'Drama\', \'Music\', \'Romance\']', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family\'s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.'),
(978, '539140', 'ja', 'https://image.tmdb.org/t/p/w500/2ayrhipQ6wETRZyixZW8UPKztEG.jpg', 'センコロール コネクト', '58.525', '2019-06-29', 7.1, '10', '[\'Animation\', \'Science Fiction\']', 'Student Yuki has never seen one of the giant monsters she always hears about on the news and that threaten her city. But when she meets the lethargic Tetsu one day, things change suddenly. Because Tetsu moves around the houses with a creature called Cencoroll, which he can control with mind control and which can transform into a wide variety of objects. But not only Yuki is fascinated by Cencoroll: the boy Shu tries to take Cencoroll from Tetsu with the help of his own telepathy monster, whereupon the four engage in a bitter fight, in which Yuki also intervenes and the entire city is converted into a battle arena.'),
(979, '17610', 'en', 'https://image.tmdb.org/t/p/w500/qF573jdJYwtCbXVXPDn4xu8nW2a.jpg', 'Year One', '54.154', '2009-06-18', 4.9, '1426', '[\'Comedy\', \'Adventure\']', 'When a couple of lazy hunter-gatherers are banished from their primitive village, they set off on an epic journey through the ancient world.'),
(980, '312221', 'en', 'https://image.tmdb.org/t/p/w500/1BfTsk5VWuw8FCocAhCyqnRbEzq.jpg', 'Creed', '64.0', '2015-11-25', 7.4, '5658', '[\'Drama\']', 'The former World Heavyweight Champion Rocky Balboa serves as a trainer and mentor to Adonis Johnson, the son of his late friend and former rival Apollo Creed.'),
(981, '214', 'en', 'https://image.tmdb.org/t/p/w500/4iO9n24Rb10peXV0JH2EldIOrAp.jpg', 'Saw III', '53.894', '2006-10-27', 6.4, '3305', '[\'Horror\', \'Thriller\', \'Crime\']', 'Jigsaw has disappeared. Along with his new apprentice Amanda, the puppet-master behind the cruel, intricate games that have terrified a community and baffled police has once again eluded capture and vanished. While city detective scramble to locate him, Doctor Lynn Denlon and Jeff Reinhart are unaware that they are about to become the latest pawns on his vicious chessboard.'),
(982, '17979', 'en', 'https://image.tmdb.org/t/p/w500/xNwlAIdx1Ln28GRiQttUP9Gojy2.jpg', 'A Christmas Carol', '72.643', '2009-11-04', 6.8, '3557', '[\'Animation\', \'Family\', \'Drama\', \'Fantasy\']', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.'),
(983, '100042', 'en', 'https://image.tmdb.org/t/p/w500/cvEi0xV7TUkabJGuzulhvbMjrHi.jpg', 'Dumb and Dumber To', '49.192', '2014-11-12', 5.5, '2545', '[\'Comedy\']', '20 years since their first adventure, Lloyd and Harry go on a road trip to find Harry\'s newly discovered daughter, who was given up for adoption.'),
(984, '611489', 'en', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSHvzp9Awb6k39s6spj4ejLoBYnh_kWGMqn4g&s', 'Initiation', '57.878', '2021-05-07', 5.9, '54', '[\'Horror\', \'Mystery\']', 'During a Whiton University\'s pledge week, the carefree partying turns deadly when brutal murders start befalling the students, sending Ellery Scott into a race against time to uncover the truth behind the school\'s dark secrets and the horrifying meaning of a recurring symbol: a single exclamation mark.'),
(985, '948', 'en', 'https://image.tmdb.org/t/p/w500/cD8JrfSEI4j7WVnKM1GdiYzMoUh.jpg', 'Halloween', '57.704', '1978-10-24', 7.6, '3917', '[\'Horror\', \'Thriller\']', 'Michael Myers escaped from the Illinois State Mental Hospital after 15 years of treatment for the brutal murder of his sister and has returned to Haddonfield to relieve his crime. What follows is a reign of terror. He came home for Halloween and may return.'),
(986, '451156', 'en', 'https://image.tmdb.org/t/p/w500/gKyvJ8u2US61pHR56C2DoVbwnu.jpg', 'Infidelity in Suburbia', '53.789', '2017-02-25', 6.2, '88', '[\'Thriller\', \'TV Movie\']', 'With her husband away at work, and her son at school, Laura dreams of a home-renovation project to supplant her restless days. Elliott, her irresistibly hot private contractor, soon fulfills her more forbidden dreams.'),
(987, '166424', 'en', 'https://image.tmdb.org/t/p/w500/8HLQLILZLhDQWO6JDpvY6XJLH75.jpg', 'Fantastic Four', '59.044', '2015-08-05', 4.4, '4940', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Four young outsiders teleport to a dangerous universe, which alters their physical form in shocking ways. Their lives irrevocably upended, the team must learn to harness their daunting new abilities and work together to save Earth from a former friend turned enemy.'),
(988, '262504', 'en', 'https://image.tmdb.org/t/p/w500/faq9JlF8znUGQ5p3En1W61Fi5p0.jpg', 'Allegiant', '51.143', '2016-03-09', 6.1, '5556', '[\'Adventure\', \'Science Fiction\', \'Action\', \'Mystery\']', 'Beatrice Prior and Tobias Eaton venture into the world outside of the fence and are taken into protective custody by a mysterious agency known as the Bureau of Genetic Welfare.'),
(989, '250546', 'en', 'https://image.tmdb.org/t/p/w500/yLsuU2P2SpDYFwtZQ7dtfVAf6TE.jpg', 'Annabelle', '62.803', '2014-10-02', 5.7, '4951', '[\'Horror\']', 'A couple begins to experience terrifying supernatural occurrences involving a vintage doll shortly after their home is invaded by satanic cultists.'),
(990, '342470', 'en', 'https://image.tmdb.org/t/p/w500/4SafxuMKQiw4reBiWKVZJpJn80I.jpg', 'All the Bright Places', '69.591', '2020-02-28', 7.7, '2212', '[\'Romance\', \'Drama\']', 'Two teens facing personal struggles form a powerful bond as they embark on a cathartic journey chronicling the wonders of Indiana.'),
(991, '80035', 'en', 'https://image.tmdb.org/t/p/w500/gwfgYA9wGpV4QLB0LrcexwfwC19.jpg', 'The Watch', '61.206', '2012-07-26', 5.5, '1851', '[\'Comedy\', \'Action\', \'Science Fiction\']', 'Four everyday suburban guys come together as an excuse to escape their humdrum lives one night a week. But when they accidentally discover that their town has become overrun with aliens posing as ordinary suburbanites, they have no choice but to save their neighborhood - and the world - from total extermination.'),
(992, '324852', 'en', 'https://image.tmdb.org/t/p/w500/6t3YWl7hrr88lCEFlGVqW5yV99R.jpg', 'Despicable Me 3', '52.823', '2017-06-15', 6.4, '5724', '[\'Action\', \'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'Gru and his wife Lucy must stop former \'80s child star Balthazar Bratt from achieving world domination.'),
(993, '100402', 'en', 'https://image.tmdb.org/t/p/w500/tVFRpFw3xTedgPGqxW0AOI8Qhh0.jpg', 'Captain America: The Winter Soldier', '59.403', '2014-03-20', 7.7, '15228', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'After the cataclysmic events in New York with The Avengers, Steve Rogers, aka Captain America is living quietly in Washington, D.C. and trying to adjust to the modern world. But when a S.H.I.E.L.D. colleague comes under attack, Steve becomes embroiled in a web of intrigue that threatens to put the world at risk. Joining forces with the Black Widow, Captain America struggles to expose the ever-widening conspiracy while fighting off professional assassins sent to silence him at every turn. When the full scope of the villainous plot is revealed, Captain America and the Black Widow enlist the help of a new ally, the Falcon. However, they soon find themselves up against an unexpected and formidable enemy—the Winter Soldier.'),
(994, '11631', 'en', 'https://image.tmdb.org/t/p/w500/zdUA4FNHbXPadzVOJiU0Rgn6cHR.jpg', 'Mamma Mia!', '53.588', '2008-07-02', 7, '5233', '[\'Comedy\', \'Romance\']', 'An independent, single mother who owns a small hotel on a Greek island is about to marry off the spirited young daughter she\'s raised alone. But, the daughter has secretly invited three of her mother\'s ex-lovers in the hopes of finding her biological father.'),
(995, '9902', 'en', 'https://image.tmdb.org/t/p/w500/4U1SBHmwHkNA0eHZ2n1CuiC1K1g.jpg', 'Wrong Turn', '59.786', '2003-05-30', 6.3, '1901', '[\'Horror\', \'Thriller\']', 'Chris crashes into a carload of other young people, and the group of stranded motorists is soon lost in the woods of West Virginia, where they\'re hunted by three cannibalistic mountain men who are grossly disfigured by generations of inbreeding.'),
(996, '460555', 'zh', 'https://image.tmdb.org/t/p/w500/6ctXBO0o5fKQvGdSJsPc8TAYCvp.jpg', '红海行动', '38.336', '2018-02-16', 6.8, '143', '[\'Action\', \'Thriller\', \'War\', \'Drama\']', 'A squad of the Jiaolong Commando Unit - Sea Dragon, a spec ops team of the Chinese Navy, carries out a hostage rescue operation in the nation of Yewaire, on the Arabian Peninsula, and fiercely fights against local rebel groups and Zaka, a terrorist organization.'),
(997, '320288', 'en', 'https://image.tmdb.org/t/p/w500/cCTJPelKGLhALq3r51A9uMonxKj.jpg', 'Dark Phoenix', '54.704', '2019-06-05', 6, '4870', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'The X-Men face their most formidable and powerful foe when one of their own, Jean Grey, starts to spiral out of control. During a rescue mission in outer space, Jean is nearly killed when she\'s hit by a mysterious cosmic force. Once she returns home, this force not only makes her infinitely more powerful, but far more unstable. The X-Men must now band together to save her soul and battle aliens that want to use Grey\'s new abilities to rule the galaxy.'),
(998, '291805', 'en', 'https://image.tmdb.org/t/p/w500/A81kDB6a1K86YLlcOtZB27jriJh.jpg', 'Now You See Me 2', '53.776', '2016-06-02', 6.8, '9060', '[\'Thriller\', \'Action\', \'Comedy\']', 'One year after outwitting the FBI and winning the public’s adulation with their mind-bending spectacles, the Four Horsemen resurface only to find themselves face to face with a new enemy who enlists them to pull off their most dangerous heist yet.'),
(999, '23827', 'en', 'https://image.tmdb.org/t/p/w500/tmclkEpjeo4Zu564gf3KrwIOuKw.jpg', 'Paranormal Activity', '57.51', '2007-09-14', 6, '3939', '[\'Horror\', \'Mystery\']', 'After a young, middle-class couple moves into what seems like a typical suburban house, they become increasingly disturbed by a presence that may or may not be demonic but is certainly the most active in the middle of the night.  Followed by five terrifying installments in the franchise, this is the original found-footage shocker that started it all.'),
(1000, '2123', 'en', 'https://image.tmdb.org/t/p/w500/rvRrcbLbpn7UJGRH1JupgHOeJFq.jpg', 'Me, Myself & Irene', '44.257', '2000-06-22', 6.6, '2951', '[\'Comedy\']', 'Rhode Island State Trooper Charlie Baileygates has a multiple personality disorder. One personality is crazy and aggressive, while the other is more friendly and laid back. Both of these personalities fall in love with the same woman named Irene after Charlie loses his medication.'),
(1001, '11357', 'en', 'https://image.tmdb.org/t/p/w500/eFSOkXF9n9hsfGv45MDsPixiOyx.jpg', 'Halloween 4: The Return of Michael Myers', '57.132', '1988-10-21', 6.1, '1027', '[\'Horror\', \'Thriller\']', 'The apparently comatose Michael Myers is being transferred from one hospital to another, but he wakes up when the ambulance crew talk about his surviving niece, Jamie. After slaughtering his attendants, Myers sets out to find his one living relative who is, fortunately, being cared for by a kind and resourceful foster sister named Rachel. Meanwhile, the ever-cautious Dr. Loomis remains on the killer\'s path.'),
(1002, '339984', 'en', 'https://image.tmdb.org/t/p/w500/hz9VF1TfaM0D04pYneSXUkNeOZv.jpg', 'Miracles from Heaven', '64.487', '2016-03-17', 7.4, '915', '[\'Drama\']', 'When Christy discovers her 10-year-old daughter Anna has a rare, incurable disease, she becomes a ferocious advocate for her daughter’s healing as she searches for a solution. After Anna has a freak accident and falls three stories, a miracle unfolds in the wake of her dramatic rescue that leaves medical specialists mystified, her family restored and their community inspired.'),
(1003, '118340', 'en', 'https://image.tmdb.org/t/p/w500/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg', 'Guardians of the Galaxy', '52.038', '2014-07-30', 7.9, '23329', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.'),
(1004, '8681', 'en', 'https://image.tmdb.org/t/p/w500/ognkaUSNgJe1a2pjB4UNdzEo5jT.jpg', 'Taken', '69.324', '2008-02-18', 7.4, '9080', '[\'Action\', \'Thriller\']', 'While vacationing with a friend in Paris, an American girl is kidnapped by a gang of human traffickers intent on selling her into forced prostitution. Working against the clock, her ex-spy father must pull out all the stops to save her. But with his best years possibly behind him, the job may be more than he can handle.'),
(1005, '638134', 'en', 'https://image.tmdb.org/t/p/w500/gtwqIYSOCRwEndZTg9s6iWjEZc1.jpg', 'Pets United', '60.035', '2019-11-08', 6.1, '140', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'When Roger (a Robin Hood-esque, stray dog) and Belle (an elegant yet spoilt pet cat) are thrown together amidst the chaos of a robot take-over of their home city, they must push all their preconceptions aside in order to survive, as they embark on a high-stakes, action-packed adventure.'),
(1006, '22881', 'en', 'https://image.tmdb.org/t/p/w500/bMgq7VBriuBFknXEe9E9pVBYGZq.jpg', 'The Blind Side', '58.454', '2009-11-20', 7.6, '4739', '[\'Drama\']', 'The story of Michael Oher, a homeless and traumatized boy who became an All American football player and first round NFL draft pick with the help of a caring woman and her family.'),
(1007, '431819', 'ja', 'https://image.tmdb.org/t/p/w500/ifm8CdFjYMfEq0bLT7XwJxjZmjO.jpg', '打ち上げ花火、下から見るか？横から見るか？', '65.703', '2017-08-18', 6.5, '236', '[\'Animation\', \'Drama\', \'Fantasy\']', 'Moshimo, Japan. The annual fireworks festival is about to take place and a group of schoolboys, arguing over whether they are round or flat when viewed from different angles, set out to find it out.'),
(1008, '802226', 'en', 'https://image.tmdb.org/t/p/w500/86VKuiaox9eVJTETel0ld7XZtiO.jpg', 'Bingo Hell', '48.179', '2021-10-01', 5.3, '49', '[\'Thriller\']', 'In the Barrio of Oak Springs live a strong and stubborn group of elderly friends who refuse to be gentrified. Their leader, Lupita, keeps them together as a community, a family. But little did they know, their beloved Bingo hall is about to be sold to a much more powerful force than money itself.'),
(1009, '2454', 'en', 'https://image.tmdb.org/t/p/w500/qxz3WIyjZiSKUhaTIEJ3c1GcC9z.jpg', 'The Chronicles of Narnia: Prince Caspian', '63.838', '2008-05-15', 6.6, '5065', '[\'Adventure\', \'Family\', \'Fantasy\']', 'One year after their incredible adventures in the Lion, the Witch and the Wardrobe, Peter, Edmund, Lucy and Susan Pevensie return to Narnia to aid a young prince whose life has been threatened by the evil King Miraz. Now, with the help of a colorful cast of new characters, including Trufflehunter the badger and Nikabrik the dwarf, the Pevensie clan embarks on an incredible quest to ensure that Narnia is returned to its rightful heir.'),
(1010, '110415', 'ko', 'https://image.tmdb.org/t/p/w500/kw6YQudA0TMcNmGUGy5XIw7zbnV.jpg', 'Snowpiercer', '52.637', '2013-08-01', 6.9, '7630', '[\'Action\', \'Science Fiction\', \'Drama\']', 'In a future where a failed global-warming experiment kills off most life on the planet, a class system evolves aboard the Snowpiercer, a train that travels around the globe via a perpetual-motion engine.'),
(1011, '824853', 'en', 'https://image.tmdb.org/t/p/w500/yfOguNYHRFgrezUjRPwwahio1ef.jpg', 'Daddy\'s Perfect Little Girl', '52.134', '2021-04-30', 6, '2', '[\'Drama\', \'TV Movie\']', 'A 12-year-old girl becomes jealous when her adoptive father develops a budding relationship with a woman and her teenage son.'),
(1012, '9297', 'en', 'https://image.tmdb.org/t/p/w500/zCRPr4bkO3ae0U1134vJ39xZnAG.jpg', 'Monster House', '55.425', '2006-06-30', 6.6, '3012', '[\'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'Monsters under the bed are scary enough, but what happens when an entire house is out to get you? Three teens aim to find out when they go up against a decrepit neighboring home and unlock its frightening secrets.'),
(1013, '140607', 'en', 'https://image.tmdb.org/t/p/w500/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg', 'Star Wars: The Force Awakens', '59.007', '2015-12-15', 7.3, '16314', '[\'Action\', \'Adventure\', \'Science Fiction\', \'Fantasy\']', 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.'),
(1014, '20352', 'en', 'https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', 'Despicable Me', '60.546', '2010-07-08', 7.2, '12626', '[\'Family\', \'Animation\', \'Comedy\']', 'Villainous Gru lives up to his reputation as a despicable, deplorable and downright unlikable guy when he hatches a plan to steal the moon from the sky. But he has a tough time staying on task after three orphans land in his care.'),
(1015, '60747', 'en', 'https://image.tmdb.org/t/p/w500/aHdxKDX36NOEYE2NyAyP7ThuAcm.jpg', 'Red Dawn', '47.883', '2012-03-15', 5.6, '1247', '[\'Action\', \'Thriller\']', 'A city in Washington state awakens to the surreal sight of foreign paratroopers dropping from the sky—shockingly, the U.S. has been invaded and their hometown is the initial target. Quickly and without warning, the citizens find themselves prisoners and their town under enemy occupation. Determined to fight back, a group of young patriots seek refuge in the surrounding woods, training and reorganizing themselves into a guerrilla group of fighters.'),
(1016, '117263', 'en', 'https://image.tmdb.org/t/p/w500/u3GTFGwesNBNd0t1hiLaEk1iqZU.jpg', 'Olympus Has Fallen', '63.525', '2013-03-20', 6.3, '5464', '[\'Action\', \'Thriller\']', 'When the White House (Secret Service Code: \"Olympus\") is captured by a terrorist mastermind and the President is kidnapped, disgraced former Presidential guard Mike Banning finds himself trapped within the building. As the national security team scrambles to respond, they are forced to rely on Banning\'s inside knowledge to help retake the White House, save the President and avert an even bigger disaster.'),
(1017, '295830', 'ja', 'https://image.tmdb.org/t/p/w500/ihK3jUDlcQBMEObbLwSswqpiy3Z.jpg', '進撃の巨人 ATTACK ON TITAN', '63.671', '2015-08-01', 5.8, '512', '[\'Horror\', \'Fantasy\', \'Action\', \'Science Fiction\']', '100 years ago, titans suddenly appeared on Earth. Soon, human civilization veered on collapse due to the titans. Humans then built a giant wall to defend themselves. Within the giant walls, humans lived in peace, but, 100 years later, the giant wall is broken.'),
(1018, '4232', 'en', 'https://image.tmdb.org/t/p/w500/lr9ZIrmuwVmZhpZuTCW8D9g0ZJe.jpg', 'Scream', '54.615', '1996-12-20', 7.3, '4559', '[\'Crime\', \'Horror\', \'Mystery\']', 'A killer known as Ghostface begins killing off teenagers, and as the body count begins rising, one girl and her friends find themselves contemplating the \'rules\' of horror films as they find themselves living in a real-life one.'),
(1019, '812', 'en', 'https://image.tmdb.org/t/p/w500/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', 'Aladdin', '60.612', '1992-11-25', 7.6, '9239', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\', \'Romance\']', 'Princess Jasmine grows tired of being forced to remain in the palace, so she sneaks out into the marketplace, in disguise, where she meets street-urchin Aladdin.  The couple falls in love, although Jasmine may only marry a prince.  After being thrown in jail, Aladdin becomes embroiled in a plot to find a mysterious lamp, with which the evil Jafar hopes to rule the land.'),
(1020, '87421', 'en', 'https://image.tmdb.org/t/p/w500/pUul9pGWOKT7X0smkTvsIEIQxcP.jpg', 'Riddick', '59.563', '2013-09-02', 6.3, '3289', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'Betrayed by his own kind and left for dead on a desolate planet, Riddick fights for survival against alien predators and becomes more powerful and dangerous than ever before. Soon bounty hunters from throughout the galaxy descend on Riddick only to find themselves pawns in his greater scheme for revenge. With his enemies right where he wants them, Riddick unleashes a vicious attack of vengeance before returning to his home planet of Furya to save it from destruction.'),
(1021, '9373', 'en', 'https://image.tmdb.org/t/p/w500/781px1eOtfVt1RdIsL4Dt1s3x7R.jpg', 'The Texas Chainsaw Massacre', '53.648', '2003-05-21', 6.2, '1903', '[\'Horror\']', 'After picking up a traumatized young hitchhiker, five friends find themselves stalked and hunted by a chainsaw-wielding killer and his family of equally psychopathic killers.'),
(1022, '74998', 'en', 'https://image.tmdb.org/t/p/w500/lN3O0j1DKVnwhO1h5J3utrmrBF2.jpg', 'Seeking Justice', '60.647', '2011-09-02', 5.9, '767', '[\'Action\', \'Drama\', \'Thriller\']', 'After his wife is assaulted, a husband enlists the services of a vigilante group to help him settle the score.'),
(1023, '278', 'en', 'https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', 'The Shawshank Redemption', '65.49', '1994-09-23', 8.7, '20048', '[\'Drama\', \'Crime\']', 'Framed in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.'),
(1024, '516052', 'ja', 'https://image.tmdb.org/t/p/w500/yVwD812mrFrpxp77GTJ8zZwBsba.jpg', '銀河英雄伝説 Die Neue These 星乱 第一章', '60.99', '2019-09-27', 8.5, '11', '[]', 'In humanity\'s distant future, two interstellar states-the monarchic Galactic Empire and the democratic Free Planets Alliance-are embroiled in a never-ending war. The story focuses on the exploits of rivals Reinhard von Müsel and Yang Wen Li as they rise to power and fame in the Galactic Empire and the Free Planets Alliance.'),
(1025, '2770', 'en', 'https://image.tmdb.org/t/p/w500/854ZZxXdeabAs90mrV72NqShJqR.jpg', 'American Pie 2', '61.186', '2001-08-10', 6.2, '3909', '[\'Comedy\', \'Romance\']', 'After a year apart - attending different schools, meeting different people - the guys rent a beach house and vow to make this the best summer ever. As it turns out, whether that will happen or not has a lot to do with the girls. Between the wild parties, outrageous revelations and yes, a trip to band camp, they discover that times change and people change, but in the end, it\'s all about sticking together.'),
(1026, '671266', 'es', 'https://image.tmdb.org/t/p/w500/4jMEgn23HxojTZHT4vArcfsIpDD.jpg', 'Ni tuyo, Ni mía', '58.363', '2021-08-19', 2, '1', '[\'Drama\']', 'Amanda realizes that her perfect husband is having an affair. Instead of confronting him, she teams up with his husband\'s lover to understand what went wrong and win him back.'),
(1027, '874209', 'en', 'https://m.media-amazon.com/images/M/MV5BMjE5Mjg0MWItNTRlZi00ODVjLWI0YzQtZjBkNmJlMWQ4ZmEwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', 'Spider-Man: Responsibility', '77.727', '2016-09-23', 4.9, '4', '[]', 'Seven months after he was bitten by the spider, Peter Parker begins to learn what it’s like to be a hero. With the help of his friend, Eric Reilly, they attempt to apprehend The Shocker, who wreaks havoc in NYC, all while trying to figure out who’s behind all the chaos.'),
(1028, '64688', 'en', 'https://image.tmdb.org/t/p/w500/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg', '21 Jump Street', '54.388', '2012-03-14', 6.9, '8516', '[\'Action\', \'Comedy\', \'Crime\']', 'In high school, Schmidt was a dork and Jenko was the popular jock. After graduation, both of them joined the police force and ended up as partners riding bicycles in the city park. Since they are young and look like high school students, they are assigned to an undercover unit to infiltrate a drug ring that is supplying high school students synthetic drugs.'),
(1029, '207703', 'en', 'https://image.tmdb.org/t/p/w500/r6q9wZK5a2K51KFj4LWVID6Ja1r.jpg', 'Kingsman: The Secret Service', '68.069', '2014-12-13', 7.6, '13608', '[\'Crime\', \'Comedy\', \'Action\', \'Adventure\']', 'The story of a super-secret spy organization that recruits an unrefined but promising street kid into the agency\'s ultra-competitive training program just as a global threat emerges from a twisted tech genius.'),
(1030, '491480', 'en', 'https://image.tmdb.org/t/p/w500/yOr7RxHw15MMXNxGMXSmngDqHyI.jpg', 'The Boy Who Harnessed the Wind', '49.477', '2019-03-01', 7.9, '1150', '[\'Drama\', \'History\', \'Family\']', 'Against all the odds, a thirteen year old boy in Malawi invents an unconventional way to save his family and village from famine.'),
(1031, '75780', 'en', 'https://image.tmdb.org/t/p/w500/uQBbjrLVsUibWxNDGA4Czzo8lwz.jpg', 'Jack Reacher', '86.885', '2012-12-20', 6.5, '5448', '[\'Crime\', \'Drama\', \'Thriller\', \'Action\']', 'When a gunman takes five lives with six shots, all evidence points to the suspect in custody. On interrogation, the suspect offers up a single note: \"Get Jack Reacher!\" So begins an extraordinary chase for the truth, pitting Jack Reacher against an unexpected enemy, with a skill for violence and a secret to keep.'),
(1032, '13688', 'cn', 'https://image.tmdb.org/t/p/w500/sRzSfpSb3wYYshbaiMRIuFCJJGU.jpg', '長江七號', '56.046', '2008-01-30', 7.2, '442', '[\'Comedy\', \'Drama\', \'Family\', \'Fantasy\', \'Science Fiction\']', 'Ti, a really poor construction worker that struggles to keep his son, Dicky, in private school, mistakes an orb he finds in a junkjard for a toy which proves to be much, much more once the young boy starts to play with it.'),
(1033, '11836', 'en', 'https://image.tmdb.org/t/p/w500/xJnOMMsFASxNiFnG7v3TNIQ3ife.jpg', 'The SpongeBob SquarePants Movie', '67.745', '2004-11-14', 6.9, '2149', '[\'Family\', \'Animation\', \'Comedy\', \'Fantasy\']', 'There\'s trouble brewing in Bikini Bottom. Someone has stolen King Neptune\'s crown, and it looks like Mr. Krab, SpongeBob\'s boss, is the culprit. Though he\'s just been passed over for the promotion of his dreams, SpongeBob stands by his boss, and along with his best pal Patrick, sets out on a treacherous mission to Shell City to reclaim the crown and save Mr. Krab\'s life.'),
(1034, '23483', 'en', 'https://image.tmdb.org/t/p/w500/iHMbrTHJwocsNvo5murCBw0CwTo.jpg', 'Kick-Ass', '62.892', '2010-03-22', 7.1, '9700', '[\'Action\', \'Crime\']', 'Dave Lizewski is an unnoticed high school student and comic book fan who one day decides to become a super-hero, even though he has no powers, training or meaningful reason to do so.'),
(1035, '508439', 'en', 'https://image.tmdb.org/t/p/w500/f4aul3FyD3jv3v4bul1IrkWZvzq.jpg', 'Onward', '66.363', '2020-02-29', 7.8, '4625', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'In a suburban fantasy world, two teenage elf brothers embark on an extraordinary quest to discover if there is still a little magic left out there.'),
(1036, '38408', 'en', 'https://image.tmdb.org/t/p/w500/zLzS2aOqKsS0QvEaY6SfBw4VBqh.jpg', 'Life As We Know It', '54.286', '2010-10-02', 6.9, '2615', '[\'Comedy\', \'Romance\', \'Drama\']', 'After a distastrous first date for caterer Holly and network sports director Messer, all they have is common is a dislike for each other and their love for their goddaughter Sophie. But when they suddenly become all Sophie has in this world, Holly and Messer must set their differences aside. Juggling careers and social calendars, they\'ll have to find common ground while living under the same roof.'),
(1037, '620', 'en', 'https://image.tmdb.org/t/p/w500/7E8nLijS9AwwUEPu2oFYOVKhdFA.jpg', 'Ghostbusters', '61.844', '1984-06-08', 7.4, '6815', '[\'Comedy\', \'Fantasy\']', 'After losing their academic posts at a prestigious university, a team of parapsychologists goes into business as proton-pack-toting \"ghostbusters\" who exterminate ghouls, hobgoblins and supernatural pests of all stripes. An ad campaign pays off when a knockout cellist hires the squad to purge her swanky digs of demons that appear to be living in her refrigerator.'),
(1038, '321612', 'en', 'https://image.tmdb.org/t/p/w500/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', 'Beauty and the Beast', '57.884', '2017-03-16', 7, '13735', '[\'Family\', \'Fantasy\', \'Romance\']', 'A live-action adaptation of Disney\'s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.'),
(1039, '310131', 'en', 'https://image.tmdb.org/t/p/w500/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg', 'The Witch', '56.579', '2015-01-27', 6.8, '5066', '[\'Horror\', \'Drama\', \'Mystery\']', 'In 1630s New England, William and Katherine lead a devout Christian life with five children, homesteading on the edge of an impassable wilderness, exiled from their settlement when William defies the local church. When their newborn son vanishes and crops mysteriously fail, the family turns on one another.'),
(1040, '81188', 'en', 'https://image.tmdb.org/t/p/w500/sW4qOa9yF0Ikg7lppncQ0n5UhKX.jpg', 'Rise of the Guardians', '66.226', '2012-11-21', 7.3, '5318', '[\'Family\', \'Animation\', \'Fantasy\', \'Action\', \'Adventure\']', 'When an evil spirit known as Pitch lays down the gauntlet to take over the world, the immortal Guardians must join forces for the first time to protect the hopes, beliefs and imagination of children all over the world.'),
(1041, '14128', 'en', 'https://image.tmdb.org/t/p/w500/kEDbtKhZsqPo7ypCzoz3fkq73Pc.jpg', 'Cinderella II: Dreams Come True', '60.965', '2002-02-23', 6.1, '1132', '[\'Family\', \'Animation\', \'Romance\', \'Fantasy\']', 'As a newly crowned princess, Cinderella quickly learns that life at the Palace - and her royal responsibilities - are more challenging than she had imagined. In three heartwarming tales, Cinderella calls on her animal friends and her Fairy Godmother to help as she brings her own grace and charm to her regal role and discovers that being true to yourself is the best way to make your dreams come true.'),
(1042, '589761', 'ru', 'https://image.tmdb.org/t/p/w500/AmJLuHjxPdIJO6vmymeWADG6jK5.jpg', 'Чернобыль', '86.404', '2021-04-15', 6.4, '184', '[\'Drama\', \'History\', \'Adventure\']', 'The aftermath of a shocking explosion at the Chernobyl nuclear power station made hundreds of people sacrifice their lives to clean up the site of the catastrophe and to successfully prevent an even bigger disaster that could have turned a large part of the European continent into an uninhabitable exclusion zone. This is their story.'),
(1043, '10054', 'en', 'https://image.tmdb.org/t/p/w500/j3rUkHIAAoKr6jU30q3Db4fcIF9.jpg', 'Spy Kids', '60.954', '2001-03-18', 5.8, '2674', '[\'Action\', \'Comedy\', \'Family\', \'Adventure\']', 'Carmen and Juni think their parents are boring. Little do they know that in their day, Gregorio and Ingrid Cortez were the top secret agents from their respective countries. They gave up that life to raise their children. Now, the disappearances of several of their old colleagues forces the Cortez\' return from retirement. What they didn\'t count on was Carmen and Juni joining the \"family business.\"'),
(1044, '624963', 'en', 'https://image.tmdb.org/t/p/w500/bkld8Me0WiLWipLORRNfF1yIPHu.jpg', 'A Babysitter\'s Guide to Monster Hunting', '57.039', '2020-10-14', 6.3, '222', '[\'Family\', \'Fantasy\', \'Adventure\', \'Comedy\']', 'Recruited by a secret society of babysitters, a high schooler battles the Boogeyman and his monsters when they nab the boy she\'s watching on Halloween.'),
(1045, '10681', 'en', 'https://image.tmdb.org/t/p/w500/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', 'WALL·E', '56.942', '2008-06-22', 8, '14967', '[\'Animation\', \'Family\', \'Science Fiction\']', 'WALL·E is the last robot left on an Earth that has been overrun with garbage and all humans have fled to outer space. For 700 years he has continued to try and clean up the mess, but has developed some rather interesting human-like qualities. When a ship arrives with a sleek new type of robot, WALL·E thinks he\'s finally found a friend and stows away on the ship when it leaves.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1046, '282070', 'ja', 'https://image.tmdb.org/t/p/w500/qO8zQ9dSADWiwRnR7oCOsPDuOom.jpg', '寄生獣 完結編', '51.987', '2015-04-25', 7, '109', '[\'Science Fiction\', \'Horror\']', 'Alien pods come to Earth and, naturally, start taking over Human Hosts. One such pod only manages to take over one human\'s, Shin Izumi, right arm. Together they grow and co-exist, all the while the other aliens are making meals of other humans; Shin feels he must put a stop to it all, but his alien, Migi, doesn\'t see why.'),
(1047, '49021', 'en', 'https://image.tmdb.org/t/p/w500/7O2U0WPFPSvNSUYZlhbnV081lBF.jpg', 'Killer Elite', '50.732', '2011-09-22', 6.3, '1652', '[\'Action\', \'Adventure\', \'Thriller\']', 'Based on a shocking true story, Killer Elite pits two of the world’s most elite operatives—Danny, an ex-special ops agent and Hunter, his longtime mentor—against the cunning leader of a secret military society. Covering the globe from Australia to Paris, London and the Middle East, Danny and Hunter are plunged into a highly dangerous game of cat and mouse—where the predators become the prey.'),
(1048, '204973', 'en', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'Venom', '55.122', '2011-07-15', 6.3, '13', '[\'Thriller\']', 'After a car breaks down in an isolated desert, a mother and young daughter are relentlessly pursued by a deadly snake'),
(1049, '2105', 'en', 'https://image.tmdb.org/t/p/w500/5P68by2Thn8wHAziyWGEw2O7hco.jpg', 'American Pie', '61.017', '1999-07-09', 6.5, '6156', '[\'Comedy\', \'Romance\']', 'At a high-school party, four friends find that losing their collective virginity isn\'t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all \"score\" by their senior prom.'),
(1050, '524047', 'en', 'https://image.tmdb.org/t/p/w500/bNo2mcvSwIvnx8K6y1euAc1TLVq.jpg', 'Greenland', '56.653', '2020-07-29', 7.2, '3051', '[\'Action\', \'Thriller\', \'Drama\']', 'John Garrity, his estranged wife and their young son embark on a perilous journey to find sanctuary as a planet-killing comet hurtles toward Earth. Amid terrifying accounts of cities getting levelled, the Garritys experience the best and worst in humanity. As the countdown to the global apocalypse approaches zero, their incredible trek culminates in a desperate and last-minute flight to a possible safe haven.'),
(1051, '653024', 'en', 'https://image.tmdb.org/t/p/w500/p1dXPdz5C1tPpPIy3kth3rTCOQe.jpg', 'The God Committee', '52.816', '2021-07-02', 7.6, '19', '[\'Thriller\', \'Drama\']', 'Medicine, money and morality clash when a hospital\'s Heart Transplant Selection Committee has only minutes to decide which of three patients on the transplant list will receive a heart that has suddenly become available.'),
(1052, '300671', 'en', 'https://image.tmdb.org/t/p/w500/fZlAxZMo6BId1SiqyjLmkd7oUB7.jpg', '13 Hours: The Secret Soldiers of Benghazi', '57.357', '2016-01-14', 7.2, '2559', '[\'War\', \'Action\', \'History\', \'Thriller\', \'Drama\']', 'An American Ambassador is killed during an attack at a U.S. compound in Libya as a security team struggles to make sense out of the chaos.'),
(1053, '116322', 'es', 'https://image.tmdb.org/t/p/w500/vBiqoYfDIWKKzZTiQScqgCO09UD.jpg', 'La Leyenda de la Llorona', '55.175', '2011-10-21', 7.7, '160', '[\'Family\', \'Animation\']', 'Leo San Juan, el joven héroe de \"La Leyenda de la Nahuala\", está de regreso en una tenebrosa misión: atrapar a La Llorona, el maléfico espectro que desde hace siglos mantiene aterrorizado al pueblo de Xochimilco. Utilizando su experiencia como cazafantasmas, Leo y sus compañeros de aventura, logran dar con La Llorona y hacen hasta lo imposible por vencerla. Sin embargo, todos sus esfuerzos no sólo resultan inútiles, sino que ellos mismos terminan sufriendo la maldición de La Llorona...'),
(1054, '10948', 'en', 'https://image.tmdb.org/t/p/w500/aC3k6XBaYnulGSkK8263ABjU3Md.jpg', 'The Fox and the Hound', '52.866', '1981-07-10', 7.1, '2546', '[\'Adventure\', \'Animation\', \'Drama\', \'Family\']', 'When a feisty little fox named Tod is adopted into a farm family, he quickly becomes friends with a fun and adorable hound puppy named Copper. Life is full of hilarious adventures until Copper is expected to take on his role as a hunting dog -- and the object of his search is his best friend!'),
(1055, '62213', 'en', 'https://image.tmdb.org/t/p/w500/fd9Ck4cxVlmtXsbeGtQW7WFuUFI.jpg', 'Dark Shadows', '51.216', '2012-05-09', 6, '5914', '[\'Comedy\', \'Fantasy\']', 'Vampire Barnabas Collins is inadvertently freed from his tomb and emerges into the very changed world of 1972. He returns to Collinwood Manor to find that his once-grand estate and family have fallen into ruin.'),
(1056, '24122', 'en', 'https://image.tmdb.org/t/p/w500/j82RTG8dNyOYhIKspjk5Z0bEmdi.jpg', 'The Rebound', '64.141', '2009-09-16', 6.5, '693', '[\'Romance\', \'Comedy\']', 'Upon discovering her husband\'s infidelity, Sandy leaves the suburbs and moves into the city. There, she befriends Aram, a guy whose wife only married him so she could get a green card. Sandy hires Aram to be her nanny, and  it isn\'t long until Aram and Sandy find out they get along wonderfully and start to date. But is their relationship real or is it, in fact, just a rebound for both of them?'),
(1057, '833971', 'es', 'https://image.tmdb.org/t/p/w500/nzbwTwSo8aKuvAytaPG6s0xGVE8.jpg', 'La Casa de las Flores: la película', '52.462', '2021-06-23', 8.3, '82', '[\'Drama\']', 'The De La Mora siblings concoct a mischievous plan to break into their old family home to retrieve a hidden treasure of significant importance.'),
(1058, '43959', 'en', 'https://image.tmdb.org/t/p/w500/cvgRxrEupUFeJ0xzUExJo4dMXbL.jpg', 'Soul Surfer', '55.77', '2011-04-08', 7.1, '983', '[\'Family\', \'Drama\']', 'The true story of teen surfer Bethany Hamilton, who lost her arm in a shark attack and courageously overcame all odds to become a champion again, through her sheer determination and unwavering faith.'),
(1059, '561', 'en', 'https://image.tmdb.org/t/p/w500/vPYgvd2MwHlxTamAOjwVQp4qs1W.jpg', 'Constantine', '53.567', '2005-02-08', 7, '5219', '[\'Fantasy\', \'Action\', \'Horror\']', 'John Constantine has literally been to Hell and back. When he teams up with a policewoman to solve the mysterious suicide of her twin sister, their investigation takes them through the world of demons and angels that exists beneath the landscape of contemporary Los Angeles.'),
(1060, '10693', 'en', 'https://image.tmdb.org/t/p/w500/6QdU3TZZrIvXFzoHOwafZAynFjB.jpg', 'Peter Pan', '65.012', '1953-02-05', 7.2, '4286', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\']', 'Leaving the safety of their nursery behind, Wendy, Michael and John follow Peter Pan to a magical world where childhood lasts forever. But while in Neverland, the kids must face Captain Hook and foil his attempts to get rid of Peter for good.'),
(1061, '535845', 'en', 'https://image.tmdb.org/t/p/w500/4MnCFcFHYAEMG4NBTUKvjhf5AhU.jpg', 'Brian Banks', '55.081', '2019-08-09', 7.3, '118', '[\'Drama\']', 'An All-American football player\'s dreams to play in the NFL are halted when he is falsely accused of rape and sent to prison.'),
(1062, '172385', 'en', 'https://image.tmdb.org/t/p/w500/gVNTBrjxh2YRmQFjlaqrNbHVvrd.jpg', 'Rio 2', '48.747', '2014-03-19', 6.5, '2687', '[\'Family\', \'Adventure\', \'Comedy\', \'Animation\']', 'It\'s a jungle out there for Blu, Jewel and their three kids after they\'re hurtled from Rio de Janeiro to the wilds of the Amazon. As Blu tries to fit in, he goes beak-to-beak with the vengeful Nigel, and meets the most fearsome adversary of all: his father-in-law.'),
(1063, '462883', 'en', 'https://image.tmdb.org/t/p/w500/cSo4vsBdzTNJG24VYgAkGgeYkAs.jpg', 'Woody Woodpecker', '49.251', '2017-10-05', 6.7, '565', '[\'Animation\', \'Comedy\', \'Family\']', 'Woody Woodpecker enters a turf war with a big city lawyer wanting to tear down his home in an effort to build a house to flip.'),
(1064, '447362', 'en', 'https://image.tmdb.org/t/p/w500/bP7u19opmHXYeTCUwGjlLldmUMc.jpg', 'Life in a Year', '63.083', '2020-11-27', 8.4, '879', '[\'Drama\', \'Romance\']', 'A 17 year old finds out that his girlfriend is dying, so he sets out to give her an entire life, in the last year she has left.'),
(1065, '785527', 'nl', 'https://image.tmdb.org/t/p/w500/vRbX9sTiZheczEtNfjAi0bhHPAn.jpg', 'Forever Rich', '51.748', '2021-10-01', 6, '52', '[\'Crime\', \'Comedy\', \'Drama\']', 'This is the story of Richie and his journey to become the greatest rap-artist in the Netherlands. One evening he is violently mugged by a group of teenagers and loses his most prized possession: an expensive watch. When images of the humiliating robbery go viral, Richie\'s hard-earned reputation is damaged.'),
(1066, '277217', 'en', 'https://image.tmdb.org/t/p/w500/65DkgHPSLVjgr6IYkpY9Aqqqid5.jpg', 'Descendants', '75.808', '2015-07-31', 7.1, '1871', '[\'Family\', \'Music\', \'Adventure\', \'Comedy\', \'Fantasy\', \'TV Movie\']', 'A present-day idyllic kingdom where the benevolent teenage son of King Adam and Queen Belle offers a chance of redemption for the troublemaking offspring of Disney\'s classic villains: Cruella De Vil (Carlos), Maleficent (Mal), the Evil Queen (Evie) and Jafar (Jay).'),
(1067, '19913', 'en', 'https://image.tmdb.org/t/p/w500/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg', '(500) Days of Summer', '54.692', '2009-07-17', 7.3, '7945', '[\'Comedy\', \'Drama\', \'Romance\']', 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.'),
(1068, '305470', 'en', 'https://image.tmdb.org/t/p/w500/bKYKyyIv5YnisxjZtDreWtYA386.jpg', 'Power Rangers', '63.548', '2017-03-23', 6.3, '3706', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'Saban\'s Power Rangers follows five ordinary teens who must become something extraordinary when they learn that their small town of Angel Grove — and the world — is on the verge of being obliterated by an alien threat. Chosen by destiny, our heroes quickly discover they are the only ones who can save the planet. But to do so, they will have to overcome their real-life issues and before it’s too late, band together as the Power Rangers.'),
(1069, '156717', 'en', 'https://image.tmdb.org/t/p/w500/aRV4oC61nmBqypSaXtMXOk99dOM.jpg', 'Death Race: Inferno', '49.734', '2013-01-04', 5.8, '561', '[\'Action\', \'Science Fiction\', \'Thriller\']', 'Carl Lucas / Frankenstein has won four of his races and needs to win one more to win his freedom. Before his final race, Lucas and his team, car and all, are transferred to another prison where they will compete in a Death Race in the desert. Also, at the same time, Ceaser runs into a marketer who wants to franchise the Death Race program.'),
(1070, '311324', 'en', 'https://image.tmdb.org/t/p/w500/p70dq1YxabemdZDm5K6Q8G10wSn.jpg', 'The Great Wall', '64.087', '2016-12-16', 5.9, '4043', '[\'Action\', \'Adventure\', \'Fantasy\']', 'European mercenaries searching for black powder become embroiled in the defense of the Great Wall of China against a horde of monstrous creatures.'),
(1071, '270771', 'en', 'https://image.tmdb.org/t/p/w500/8QV86y9ympSjtZfuAeufAeBb9OG.jpg', 'The Well', '54.033', '2014-06-12', 6.2, '155', '[\'Horror\', \'Thriller\', \'Action\']', 'In the near future, society collapses and water becomes scarce. When a greedy water baron starts violently clearing out survivors, Kendal, a 17-year-old teenager, fights the baron\'s henchman to keep a well open.'),
(1072, '166428', 'en', 'https://image.tmdb.org/t/p/w500/xvx4Yhf0DVH8G4LzNISpMfFBDy2.jpg', 'How to Train Your Dragon: The Hidden World', '54.877', '2019-01-03', 7.8, '4801', '[\'Animation\', \'Family\', \'Adventure\']', 'As Hiccup fulfills his dream of creating a peaceful dragon utopia, Toothless’ discovery of an untamed, elusive mate draws the Night Fury away. When danger mounts at home and Hiccup’s reign as village chief is tested, both dragon and rider must make impossible decisions to save their kind.'),
(1073, '371370', 'ja', 'https://image.tmdb.org/t/p/w500/sOtvIOc65gmDdrAk3Eg01oH4gZY.jpg', 'Dragon Ball Z: Zenbu Misemasu Toshi Wasure Dragon Ball Z!', '56.106', '1993-12-31', 6.8, '20', '[\'Action\', \'Animation\', \'Comedy\']', 'This movie is very different from the previous TV specials (Dragon Ball Z: Bardock - The Father of Goku and Dragon Ball Z: The History of Trunks), as it is a look back at what had happened in Dragon Ball Z in 1993.  In this film, which is believed to take place some time around the 25th World Martial Arts Tournament, Gohan and Goten are having a hot bath outside in the middle of winter. Goku (who is still dead) suddenly appears in front of his sons with the help of his Instant Transmission, and joins them in the tub. While there, the three Saiyans reflect back on the events that occurred during the Cell Games. Inside the house after Chi-Chi appeared, Goku tells his sons about Pikkon and the Other World Tournament.  Later, the four members of the Son family appear dressed nicely. Gohan says that the adult division of the Tournament will begin this next year (in 1994), and the special comes to an end.'),
(1074, '553839', 'ja', 'https://image.tmdb.org/t/p/w500/pZnt7GJDEsnL7V6hS9OPhMuh6aQ.jpg', '劇場版 幼女戦記', '64.712', '2019-02-08', 8.1, '98', '[\'Animation\', \'Action\', \'War\', \'Fantasy\']', 'With its armies sweeping across the continent, the Empire seems unstoppable. After securing victory over the remnants of the Republic\'s army, the Empire\'s ultimate victory is finally within reach. However, dark clouds are gathering in the East. The communist-led Russy Federation is mustering troops on its western border, preparing to enter the war. Supported by a detachment of Allied volunteer magicians—among whom is Mary Sioux, the daughter of a soldier killed by Tanya—the Federation is determined to spread the communist creed and bring the Empire to its knees.\r Meanwhile, Tanya and her battalion return to the imperial capital from the southern front. Upon their arrival, they are tasked with investigating troop movements on the border with the Federation. Any escalation of violence at this point may lead to new conflicts, plunging the world into a global war.\r Will the Empire eventually emerge victorious from its struggle, or will it crumble in the face radically different ideologies?'),
(1075, '4257', 'en', 'https://image.tmdb.org/t/p/w500/sEqFdw1wLtY94RKCSPolsHWzn6r.jpg', 'Scary Movie 4', '65.654', '2006-04-12', 5.5, '2470', '[\'Comedy\']', 'Cindy finds out the house she lives in is haunted by a little boy and goes on a quest to find out who killed him and why. Also, Alien \"Tr-iPods\" are invading the world and she has to uncover the secret in order to stop them.'),
(1076, '210577', 'en', 'https://image.tmdb.org/t/p/w500/ts996lKsxvjkO2yiYG0ht4qAicO.jpg', 'Gone Girl', '46.07', '2014-10-01', 7.9, '14928', '[\'Mystery\', \'Thriller\', \'Drama\']', 'With his wife\'s disappearance having become the focus of an intense media circus, a man sees the spotlight turned on him when it\'s suspected that he may not be innocent.'),
(1077, '42246', 'en', 'https://image.tmdb.org/t/p/w500/4pQhh5bU1KcUeXqPOteWsCkNZPK.jpg', 'Tom and Jerry: The Fast and the Furry', '52.503', '2005-10-11', 7, '181', '[\'Family\', \'Animation\', \'Comedy\', \'Action\', \'Adventure\']', 'After being evicted from their old house by Tom\'s owner for causing major damage, cat and mouse Tom and Jerry enter a race entitled the \"Fabulous Super Race\" to win a mansion.'),
(1078, '82700', 'en', 'https://image.tmdb.org/t/p/w500/iXMvYIlzzJBs352CfeiQcBvovZt.jpg', 'After Earth', '63.502', '2013-05-30', 5.2, '5589', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'One thousand years after cataclysmic events forced humanity\'s escape from Earth, Nova Prime has become mankind\'s new home. Legendary General Cypher Raige returns from an extended tour of duty to his estranged family, ready to be a father to his 13-year-old son, Kitai. When an asteroid storm damages Cypher and Kitai\'s craft, they crash-land on a now unfamiliar and dangerous Earth. As his father lies dying in the cockpit, Kitai must trek across the hostile terrain to recover their rescue beacon. His whole life, Kitai has wanted nothing more than to be a soldier like his father. Today, he gets his chance.'),
(1079, '147441', 'en', 'https://image.tmdb.org/t/p/w500/uaDj37JtvLan9tihxZ18e6qL33b.jpg', 'Exodus: Gods and Kings', '61.248', '2014-12-03', 5.8, '3782', '[\'Adventure\', \'Drama\', \'Action\']', 'The defiant leader Moses rises up against the Egyptian Pharaoh Ramses, setting 400,000 slaves on a monumental journey of escape from Egypt and its terrifying cycle of deadly plagues.'),
(1080, '353486', 'en', 'https://image.tmdb.org/t/p/w500/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', 'Jumanji: Welcome to the Jungle', '55.231', '2017-12-09', 6.8, '11155', '[\'Adventure\', \'Action\', \'Comedy\', \'Fantasy\']', 'The tables are turned as four teenagers are sucked into Jumanji\'s world - pitted against rhinos, black mambas and an endless variety of jungle traps and puzzles. To survive, they\'ll play as characters from the game.'),
(1081, '106', 'en', 'https://image.tmdb.org/t/p/w500/k3mW4qfJo6SKqe6laRyNGnbB9n5.jpg', 'Predator', '57.186', '1987-06-12', 7.5, '5781', '[\'Science Fiction\', \'Action\', \'Adventure\', \'Thriller\']', 'A team of commandos on a mission in a Central American jungle find themselves hunted by an extraterrestrial warrior.'),
(1082, '9702', 'en', 'https://image.tmdb.org/t/p/w500/gvP6R6juhe2IpCG7QGDgjyUvm0g.jpg', 'Bound by Honor', '54.126', '1993-02-05', 8.1, '821', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the \"Vatos Locos\", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a \"home\" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his \"carnal\", Miklo.'),
(1083, '338952', 'en', 'https://image.tmdb.org/t/p/w500/fMMrl8fD9gRCFJvsx0SuFwkEOop.jpg', 'Fantastic Beasts: The Crimes of Grindelwald', '61.139', '2018-11-14', 6.9, '8481', '[\'Adventure\', \'Fantasy\', \'Drama\']', 'Gellert Grindelwald has escaped imprisonment and has begun gathering followers to his cause—elevating wizards above all non-magical beings. The only one capable of putting a stop to him is the wizard he once called his closest friend, Albus Dumbledore. However, Dumbledore will need to seek help from the wizard who had thwarted Grindelwald once before, his former student Newt Scamander, who agrees to help, unaware of the dangers that lie ahead. Lines are drawn as love and loyalty are tested, even among the truest friends and family, in an increasingly divided wizarding world.'),
(1084, '575813', 'zh', 'https://image.tmdb.org/t/p/w500/csVZ2ZQCj98XdZoCuW1aixMYJ0W.jpg', '少年的你', '54.74', '2019-10-25', 8.4, '184', '[\'Drama\']', 'A bullied teenage girl forms an unlikely friendship with a mysterious young man who protects her from her assailants, while she copes with the pressures of her final examinations.'),
(1085, '70160', 'en', 'https://image.tmdb.org/t/p/w500/yXCbOiVDCxO71zI7cuwBRXdftq8.jpg', 'The Hunger Games', '57.826', '2012-03-12', 7.2, '18477', '[\'Science Fiction\', \'Adventure\', \'Fantasy\']', 'Every year in the ruins of what was once North America, the nation of Panem forces each of its twelve districts to send a teenage boy and girl to compete in the Hunger Games.  Part twisted entertainment, part government intimidation tactic, the Hunger Games are a nationally televised event in which “Tributes” must fight with one another until one survivor remains.  Pitted against highly-trained Tributes who have prepared for these Games their entire lives, Katniss is forced to rely upon her sharp instincts as well as the mentorship of drunken former victor Haymitch Abernathy.  If she’s ever to return home to District 12, Katniss must make impossible choices in the arena that weigh survival against humanity and life against love. The world will be watching.'),
(1086, '648964', 'ja', 'https://image.tmdb.org/t/p/w500//dORZD6Z2RKNEs9VdHHwAQGB5W5a.jpg', 'Ninja Escapades: Creation of Akatsuki, The Two Uchiha, The Far Reaches of Hope', '58.62', '2014-09-11', 6.5, '14', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\', \'Comedy\']', ''),
(1087, '471498', 'fr', 'https://image.tmdb.org/t/p/w500/u74DFoZGTcZ8cuHO8nvQkCqXEVP.jpg', 'Oxygène', '46.738', '2021-05-12', 6.7, '835', '[\'Science Fiction\', \'Thriller\', \'Horror\']', 'A woman wakes in a cryogenic chamber with no recollection of how she got there, and must find a way out before running out of air.'),
(1088, '39107', 'ja', 'https://image.tmdb.org/t/p/w500/7AHvaEAeQfkfJ4OqcBePxa2ao09.jpg', 'ドラゴンボールZ 復活のフュージョン!! 悟空とベジータ', '58.93', '1995-03-04', 7.5, '583', '[\'Animation\', \'Action\', \'Fantasy\', \'Science Fiction\']', 'Not paying attention to his job, a young demon allows the evil cleansing machine to overflow and explode, turning the young demon into the infamous monster Janemba. Goku and Vegeta make solo attempts to defeat the monster, but realize their only option is fusion.'),
(1089, '621013', 'en', 'https://image.tmdb.org/t/p/w500/q1MNlZYqhoD4U7sd7pjxD6SUf4z.jpg', 'Chemical Hearts', '58.217', '2020-08-21', 7.5, '882', '[\'Drama\', \'Romance\']', 'When a hopelessly romantic high school senior falls for a mysterious new classmate, it sets them both on an unexpected journey that teaches them about love, loss, and most importantly themselves.'),
(1090, '617762', 'en', 'https://image.tmdb.org/t/p/w500/jmlul0Y8KBXPqJ0LUcTfsCoRcoI.jpg', 'The Electrical Life of Louis Wain', '83.296', '2021-10-21', 7, '23', '[\'Drama\', \'History\']', 'The extraordinary true story of eccentric British artist Louis Wain, whose playful, sometimes even psychedelic pictures helped to transform the public\'s perception of cats forever.'),
(1091, '136799', 'en', 'https://image.tmdb.org/t/p/w500/9VlK2j0THZWzhQPq0W3Oc0IIdBB.jpg', 'Trolls', '60.828', '2016-10-13', 6.7, '2890', '[\'Family\', \'Animation\', \'Fantasy\', \'Adventure\', \'Comedy\', \'Music\']', 'Lovable and friendly, the trolls love to play around. But one day, a mysterious giant shows up to end the party. Poppy, the optimistic leader of the Trolls, and her polar opposite, Branch, must embark on an adventure that takes them far beyond the only world they’ve ever known.'),
(1092, '119283', 'en', 'https://image.tmdb.org/t/p/w500/ocTaizFzASVPClHsx6VRBi5yP9Z.jpg', 'Parker', '53.17', '2013-01-23', 6, '2479', '[\'Action\', \'Crime\']', 'A thief with a unique code of professional ethics is double-crossed by his crew and left for dead. Assuming a new disguise and forming an unlikely alliance with a woman on the inside, he looks to hijack the score of the crew\'s latest heist.'),
(1093, '41446', 'en', 'https://image.tmdb.org/t/p/w500/tcrI37K98TVopLbcZBa55mWhLT1.jpg', 'Scream 4', '51.859', '2011-04-11', 6.3, '2355', '[\'Horror\', \'Mystery\']', 'Sidney Prescott, now the author of a self-help book, returns home to Woodsboro on the last stop of her book tour. There she reconnects with Sheriff Dewey and Gale, who are now married, as well as her cousin Jill and her Aunt Kate. Unfortunately, Sidney\'s appearance also brings about the return of Ghostface, putting Sidney, Gale, and Dewey, along with Jill, her friends, and the whole town of Woodsboro in danger.'),
(1094, '8065', 'en', 'https://image.tmdb.org/t/p/w500/efG8Po57alqSlhqHU1lXJ3duG6t.jpg', '21', '41.804', '2008-03-27', 6.7, '3642', '[\'Drama\', \'Crime\']', 'Ben Campbell is a young, highly intelligent, student at M.I.T. in Boston who strives to succeed. Wanting a scholarship to transfer to Harvard School of Medicine with the desire to become a doctor, Ben learns that he cannot afford the $300,000 for the four to five years of schooling as he comes from a poor, working-class background. But one evening, Ben is introduced by his unorthodox math professor Micky Rosa into a small but secretive club of five. Students Jill, Choi, Kianna, and Fisher, who are being trained by Professor Rosa of the skill of card counting at blackjack.'),
(1095, '57201', 'en', 'https://image.tmdb.org/t/p/w500/yDuJGq8biNMW7zM3w95UaDJv0KG.jpg', 'The Lone Ranger', '52.607', '2013-07-03', 6.1, '4910', '[\'Action\', \'Adventure\', \'Western\']', 'The Texas Rangers chase down a gang of outlaws led by Butch Cavendish, but the gang ambushes the Rangers, seemingly killing them all. One survivor is found, however, by an American Indian named Tonto, who nurses him back to health. The Ranger, donning a mask and riding a white stallion named Silver, teams up with Tonto to bring the unscrupulous gang and others of that ilk to justice.'),
(1096, '293167', 'en', 'https://image.tmdb.org/t/p/w500/r2517Vz9EhDhj88qwbDVj8DCRZN.jpg', 'Kong: Skull Island', '53.011', '2017-03-08', 6.5, '8551', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Explore the mysterious and dangerous home of the king of the apes as a team of explorers ventures deep inside the treacherous, primordial island.'),
(1097, '82702', 'en', 'https://image.tmdb.org/t/p/w500/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg', 'How to Train Your Dragon 2', '61.659', '2014-06-05', 7.7, '7727', '[\'Fantasy\', \'Action\', \'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Five years have passed since Hiccup and Toothless united the dragons and Vikings of Berk. Now, they spend their time charting unmapped territories. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons -- and a mysterious dragon rider who turns out to be Hiccup\'s mother, Valka. Hiccup and Toothless then find themselves at the center of a battle to protect Berk from a power-hungry warrior named Drago.'),
(1098, '542178', 'en', 'https://image.tmdb.org/t/p/w500/6JXR3KJH5roiBCjWFt09xfgxHZc.jpg', 'The French Dispatch', '61.436', '2021-10-21', 7.3, '213', '[\'Comedy\', \'Drama\', \'Romance\']', 'The staff of a European publication decides to publish a memorial edition highlighting the three best stories from the last decade: an artist sentenced to life imprisonment, student riots, and a kidnapping resolved by a chef.'),
(1099, '4922', 'en', 'https://image.tmdb.org/t/p/w500/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', 'The Curious Case of Benjamin Button', '50.237', '2008-12-25', 7.6, '10140', '[\'Drama\', \'Fantasy\', \'Romance\']', 'I was born under unusual circumstances. And so begins. The Curious Case of Benjamin Button, adapted from the 1920s story by F. Scott Fitzgerald about a man who is born in his eighties and ages backwards: a man, like any of us, who is unable to stop time. We follow his story, set in New Orleans, from the end of World War I in 1918 into the 21st century, following his journey that is as unusual as any man\'s life can be. Directed by David Fincher and starring Brad Pitt and Cate Blanchett with Taraji P. Henson, Tilda Swinton, Jason Flemyng, Elias Koteas and Julia Ormond, Benjamin Button, is a grand tale of a not-so-ordinary man and the people and places he discovers along the way, the loves he finds, the joys of life and the sadness of death, and what lasts beyond time.'),
(1100, '222935', 'en', 'https://image.tmdb.org/t/p/w500/kcVuktIlrn9SAN1uBmPDnocTQmF.jpg', 'The Fault in Our Stars', '52.838', '2014-05-16', 7.6, '9638', '[\'Romance\', \'Drama\']', 'Despite the tumor-shrinking medical miracle that has bought her a few years, Hazel has never been anything but terminal, her final chapter inscribed upon diagnosis. But when a patient named Augustus Waters suddenly appears at Cancer Kid Support Group, Hazel\'s story is about to be completely rewritten.'),
(1101, '200727', 'en', 'https://image.tmdb.org/t/p/w500/8Mf9GgyNv5jjLAAPGsom9skH2Du.jpg', 'Love, Rosie', '53.335', '2014-10-16', 7.8, '5218', '[\'Comedy\', \'Romance\']', 'Since the moment they met at age 5, Rosie and Alex have been best friends, facing the highs and lows of growing up side by side. A fleeting shared moment, one missed opportunity, and the decisions that follow send their lives in completely different directions. As each navigates the complexities of life, love, and everything in between, they always find their way back to each other - but is it just friendship, or something more?'),
(1102, '141052', 'en', 'https://image.tmdb.org/t/p/w500/eifGNCSDuxJeS1loAXil5bIGgvC.jpg', 'Justice League', '61.587', '2017-11-15', 6.2, '10894', '[\'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'Fuelled by his restored faith in humanity and inspired by Superman\'s selfless act, Bruce Wayne and Diana Prince assemble a team of metahumans consisting of Barry Allen, Arthur Curry and Victor Stone to face the catastrophic threat of Steppenwolf and the Parademons who are on the hunt for three Mother Boxes on Earth.'),
(1103, '238', 'en', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', 'The Godfather', '54.022', '1972-03-14', 8.7, '15020', '[\'Drama\', \'Crime\']', 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.'),
(1104, '545609', 'en', 'https://image.tmdb.org/t/p/w500/nygOUcBKPHFTbxsYRFZVePqgPK6.jpg', 'Extraction', '53.949', '2020-04-24', 7.4, '4203', '[\'Drama\', \'Action\', \'Thriller\']', 'Tyler Rake, a fearless mercenary who offers his services on the black market, embarks on a dangerous mission when he is hired to rescue the kidnapped son of a Mumbai crime lord.'),
(1105, '80321', 'en', 'https://image.tmdb.org/t/p/w500/ekraj4ksvIKeuvQVEevEJkuybZd.jpg', 'Madagascar 3: Europe\'s Most Wanted', '55.558', '2012-06-06', 6.6, '4860', '[\'Animation\', \'Family\', \'Comedy\', \'Adventure\']', 'Animal pals Alex, Marty, Melman, and Gloria are still trying to make it back to New York\'s Central Park Zoo. They are forced to take a detour to Europe to find the penguins and chimps who broke the bank at a Monte Carlo casino. When French animal-control officer Capitaine Chantel DuBois picks up their scent, Alex and company are forced to hide out in a traveling circus.'),
(1106, '68737', 'en', 'https://image.tmdb.org/t/p/w500/7Q8DfXSjcFSSQDOxz1Sk865wNqI.jpg', 'Seventh Son', '54.326', '2014-12-12', 5.5, '2076', '[\'Adventure\', \'Fantasy\']', 'John Gregory, who is a seventh son of a seventh son and also the local spook, has protected the country from witches, boggarts, ghouls and all manner of things that go bump in the night. However John is not young anymore, and has been seeking an apprentice to carry on his trade. Most have failed to survive. The last hope is a young farmer\'s son named Thomas Ward. Will he survive the training to become the spook that so many others couldn\'t?'),
(1107, '471335', 'ko', 'https://image.tmdb.org/t/p/w500/jG1nfIvkSpwlEt2EeAG6oGFKyqY.jpg', '치즈인더트랩', '65.079', '2018-03-14', 6.6, '49', '[\'Romance\', \'Drama\', \'Thriller\']', 'Movie is based on the popular webcomic “Cheese in the Trap” by Soonkki which was previously adapted in the 2016 television drama series “Cheese in the Trap.”'),
(1108, '506574', 'en', 'https://image.tmdb.org/t/p/w500/7IRy0iHdaS0JI3ng4ZYlk5gLSFn.jpg', 'Descendants 3', '78.113', '2019-08-02', 7.9, '1156', '[\'Family\', \'TV Movie\', \'Music\', \'Adventure\', \'Fantasy\']', 'The teenagers of Disney\'s most infamous villains return to the Isle of the Lost to recruit a new batch of villainous offspring to join them at Auradon Prep.'),
(1109, '667969', 'en', 'https://image.tmdb.org/t/p/w500/3b1ZSkBrxtDEtk61NVKn7EtbZaL.jpg', 'Birds of Paradise', '49.564', '2021-09-23', 7, '71', '[\'Drama\']', 'Two dancers at an elite ballet academy in Paris must compete for a contract to join the highly coveted Opéra National de Paris as they confront their competitive nature, sexual awakenings and how far they would go to win.'),
(1110, '732472', 'en', 'https://image.tmdb.org/t/p/w500/lGYf7TKZPSvbI11IwoQBvbTCuq0.jpg', 'The Amityville Harvest', '42.836', '2020-10-20', 7.4, '15', '[\'Horror\']', 'While staying at an aging manor to research its liquor-smuggling history, Christina and her documentary video team interview their spooky host Vincent—but no one can capture his image or voice on video. After shocking dreams and bloody encounters, the crew members fall under Victor’s hypnotic spell.'),
(1111, '11324', 'en', 'https://image.tmdb.org/t/p/w500/nrmXQ0zcZUL8jFLrakWc90IR8z9.jpg', 'Shutter Island', '56.076', '2010-02-14', 8.2, '18779', '[\'Drama\', \'Thriller\', \'Mystery\']', 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by his troubling visions and also by a mysterious doctor.'),
(1112, '302666', 'en', 'https://image.tmdb.org/t/p/w500/xk2XMdPM29ETA491JVEBj1BhJ7F.jpg', '10.0 Earthquake', '57.477', '2014-10-15', 4.9, '80', '[\'Drama\', \'Adventure\', \'Action\']', 'Los Angeles is about to be hit by a devastating earthquake, and time is running out to save the city from imminent danger.'),
(1113, '326359', 'en', 'https://image.tmdb.org/t/p/w500/mPrDJ7puYzPLG5kPM96iNszF2sM.jpg', 'Frozen Fever', '54.562', '2015-03-09', 6.8, '1566', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'On Anna\'s birthday, Elsa and Kristoff are determined to give her the best celebration ever, but Elsa\'s icy powers may put more than just the party at risk.'),
(1114, '9769', 'en', 'https://image.tmdb.org/t/p/w500/9INcC14WZjCMKGE360VXmklCLdZ.jpg', 'Lolita', '50.557', '1997-09-27', 7.1, '1147', '[\'Drama\']', 'Urbane professor Humbert Humbert marries a New England widow to be near her nymphet daughter.'),
(1115, '359724', 'en', 'https://image.tmdb.org/t/p/w500/dR1Ju50iudrOh3YgfwkAU1g2HZe.jpg', 'Ford v Ferrari', '60.53', '2019-11-13', 8, '5183', '[\'Drama\', \'Action\', \'History\']', 'American car designer Carroll Shelby and the British-born driver Ken Miles work together to battle corporate interference, the laws of physics, and their own personal demons to build a revolutionary race car for Ford Motor Company and take on the dominating race cars of Enzo Ferrari at the 24 Hours of Le Mans in France in 1966.'),
(1116, '9291', 'en', 'https://image.tmdb.org/t/p/w500/nbKcVBcxF96ARW2oKHqDYAcLdu.jpg', 'The Longest Yard', '41.643', '2005-05-27', 6.6, '2501', '[\'Comedy\']', 'Pro quarter-back, Paul Crewe and former college champion and coach, Nate Scarboro are doing time in the same prison. Asked to put together a team of inmates to take on the guards, Crewe enlists the help of Scarboro to coach the inmates to victory in a football game \'fixed\' to turn out quite another way.'),
(1117, '468225', 'en', 'https://image.tmdb.org/t/p/w500/gPkaPGNbjZCeRurSYGi0JD63DBa.jpg', 'The Starling', '53.632', '2021-09-17', 7.2, '113', '[\'Comedy\', \'Drama\']', 'A woman adjusting to life after a loss contends with a feisty bird that\'s taken over her garden — and a husband who\'s struggling to find a way forward.'),
(1118, '10867', 'it', 'https://image.tmdb.org/t/p/w500/3OyQTl0IGkbnjDxd3MhztfPE34g.jpg', 'Malèna', '58.775', '2000-03-16', 7.3, '1445', '[\'Drama\']', 'On the day in 1940 that Italy enters the war, two things happen to the 12-year-old Renato: he gets his first bike, and he gets his first look at Malèna. She is a beautiful, silent outsider who\'s moved to this Sicilian town to be with her husband, Nico. He promptly goes off to war, leaving her to the lustful eyes of the men and the sharp tongues of the women. During the next few years, as Renato grows toward manhood, he watches Malèna suffer and prove her mettle. He sees her loneliness, then grief when Nico is reported dead, the effects of slander on her relationship with her father, her poverty and search for work, and final humiliations. Will Renato learn courage from Malèna and stand up for her?'),
(1119, '55066', 'en', 'https://image.tmdb.org/t/p/w500/r6wLlv6gS39T2jVniHJ7ORsBegt.jpg', 'The Eternal', '52.114', '1998-09-18', 4.2, '20', '[\'Horror\']', 'An alcoholic American couple travel to the UK with their son so he can meet his grandmother but they walk in on their crazed uncle who is in the midst of reviving a centuries-old Druid witch.'),
(1120, '7342', 'en', 'https://image.tmdb.org/t/p/w500/8tT1rqlsTguyfUBMrbHR9cv1rxM.jpg', 'Carrie', '62.71', '2002-11-04', 6.2, '336', '[\'Drama\', \'Horror\', \'TV Movie\']', 'Carrie White is a lonely and painfully shy teenage girl with telekinetic powers who is slowly pushed to the edge of insanity by frequent bullying from both classmates at her school, and her own religious, but abusive, mother.'),
(1121, '675353', 'en', 'https://image.tmdb.org/t/p/w500/6DrHO1jr3qVrViUO6s6kFiAGM7.jpg', 'Sonic the Hedgehog 2', '58.089', '2022-03-31', 0, '0', '[\'Family\', \'Science Fiction\', \'Comedy\', \'Action\']', 'When the evil Dr. Robotnik and his sidekick Knuckles make an unexpected visit to Earth on the search for an all-powerful emerald, Sonic joins forces with a new ally named Tails and embarks on a journey to find the emerald before it falls into the wrong hands.'),
(1122, '243688', 'en', 'https://image.tmdb.org/t/p/w500/jBXupXZ7WEPUpkYFpkQsdipwBQn.jpg', 'Poltergeist', '40.614', '2015-05-20', 5.2, '1915', '[\'Horror\', \'Thriller\']', 'Legendary filmmaker Sam Raimi and director Gil Kenan reimagine and contemporize the classic tale about a family whose suburban home is invaded by angry spirits. When the terrifying apparitions escalate their attacks and take the youngest daughter, the family must come together to rescue her.'),
(1123, '350', 'en', 'https://image.tmdb.org/t/p/w500/8912AsVuS7Sj915apArUFbv6F9L.jpg', 'The Devil Wears Prada', '48.353', '2006-06-30', 7.4, '9624', '[\'Comedy\', \'Drama\', \'Romance\']', 'Andy moves to New York to work in the fashion industry. Her boss is extremely demanding, cruel and won\'t let her succeed if she doesn\'t fit into the high class elegant look of their magazine.'),
(1124, '618344', 'en', 'https://image.tmdb.org/t/p/w500/c01Y4suApJ1Wic2xLmaq1QYcfoZ.jpg', 'Justice League Dark: Apokolips War', '52.432', '2020-05-05', 8.4, '1070', '[\'Animation\', \'Action\', \'Adventure\', \'Fantasy\', \'Science Fiction\']', 'Earth is decimated after intergalactic tyrant Darkseid has devastated the Justice League in a poorly executed war by the DC Super Heroes. Now the remaining bastions of good – the Justice League, Teen Titans, Suicide Squad and assorted others – must regroup, strategize and take the war to Darkseid in order to save the planet and its surviving inhabitants.'),
(1125, '346672', 'en', 'https://image.tmdb.org/t/p/w500/v1ciDCWMG47gdT4kMyjyQbnLQQn.jpg', 'Underworld: Blood Wars', '48.742', '2016-11-24', 5.8, '3027', '[\'Fantasy\', \'Action\', \'Thriller\']', 'Vampire death dealer Selene fends off brutal attacks from both the Lycan clan and the Vampire faction that betrayed her. With her only allies, David and his father Thomas, she must stop the eternal war between Lycans and Vampires, even if it means she has to make the ultimate sacrifice.'),
(1126, '56292', 'en', 'https://image.tmdb.org/t/p/w500/eRZTGx7GsiKqPch96k27LK005ZL.jpg', 'Mission: Impossible - Ghost Protocol', '58.429', '2011-12-07', 7, '7952', '[\'Action\', \'Thriller\', \'Adventure\']', 'Ethan Hunt and his team are racing against time to track down a dangerous terrorist named Hendricks, who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt to stop him ends in an explosion causing severe destruction to the Kremlin and the IMF to be implicated in the bombing, forcing the President to disavow them. No longer being aided by the government, Ethan and his team chase Hendricks around the globe, although they might still be too late to stop a disaster.'),
(1127, '354556', 'ru', 'https://image.tmdb.org/t/p/w500/sGHAoGdxD9CeJxr1mvKHjgt8eqj.jpg', 'Защитники', '50.223', '2017-02-14', 4.8, '575', '[\'Action\', \'Fantasy\', \'Science Fiction\']', 'During the Cold War, an organization called \"Patriot\" created a super-hero squad, which includes members of multiple soviet republics. For years, the heroes had to hide their identities, but in hard times they must show themselves again.'),
(1128, '18861', 'ja', 'https://image.tmdb.org/t/p/w500/mmKiJ93x6uhTwJlrxCoY38R4qo6.jpg', '劇場版 NARUTO -ナルト- 大興奮!みかづき島のアニマル騒動だってばよ', '55.714', '2006-08-05', 7, '217', '[\'Adventure\', \'Animation\', \'Action\']', 'Naruto Uzumaki, Kakashi Hatake, Sakura Haruno, and Rock Lee are assigned to protect the prince of the Land of the Moon, Michiru, during his world trip; other escorts had been hired, but quit due to being treated poorly. The Land of the Moon is a very wealthy nation, so Michiru tends to buy whatever he wants, and has a very materialistic worldview. His Hikaru, also acts in much the same manner.'),
(1129, '4523', 'en', 'https://image.tmdb.org/t/p/w500/8KCNzCArLlvLdQoHx6npua2VSVc.jpg', 'Enchanted', '59.458', '2007-11-20', 6.7, '4377', '[\'Comedy\', \'Family\', \'Fantasy\', \'Romance\']', 'The beautiful princess Giselle is banished by an evil queen from her magical, musical animated land and finds herself in the gritty reality of the streets of modern-day Manhattan. Shocked by this strange new environment that doesn\'t operate on a \"happily ever after\" basis, Giselle is now adrift in a chaotic world badly in need of enchantment. But when Giselle begins to fall in love with a charmingly flawed divorce lawyer who has come to her aid - even though she is already promised to a perfect fairy tale prince back home - she has to wonder: Can a storybook view of romance survive in the real world?'),
(1130, '16577', 'en', 'https://image.tmdb.org/t/p/w500/6AK3uOHaIbl6EDaytHYe4FinZMu.jpg', 'Astro Boy', '52.859', '2009-10-15', 6.3, '1160', '[\'Animation\', \'Action\', \'Family\', \'Science Fiction\']', 'Set in the futuristic Metro City, Astro Boy (Atom) is a young robot with incredible powers created by a brilliant scientist in the image of the son he had lost. Unable to fulfill his creator\'s expectations, Astro embarks on a journey in search of acceptance, experiencing betrayal and a netherworld of robot gladiators, before returning to save Metro City and reconcile with the father who rejected him.'),
(1131, '428707', 'ja', 'https://image.tmdb.org/t/p/w500/mXJQbwxA0joNv9rGy25rFrm5N1r.jpg', '劇場版 黒子のバスケ LAST GAME', '52.598', '2017-03-18', 7.9, '63', '[\'Animation\']', 'Shortly after the Inter-High of Kagami and Kuroko\'s second-year, a street basketball team from the USA called Team Jabberwock came to Japan to play a friendly match against a Japanese college-level street basketball team, Team Strky. Despite their best efforts, Strky is brutally crushed by Jabberwock. After the match, the Jabberwock players insult the players from Strky and all of Japanese basketball, claiming Strky\'s basketball was at the same level as monkeys and telling the players and crowds to quit playing basketball and kill themselves.  As a revenge match, Kagetora assembles a dream team of all members of Generation of Miracles plus Kuroko Tetsuya and Kagami Taiga, along with bench players Hyūga Junpei, Takao Kazunari, and Wakamatsu Kōsuke, forming Team Vorpal Swords, with the hopes of reclaiming the pride of Japanese basketball.'),
(1132, '273477', 'en', 'https://image.tmdb.org/t/p/w500/lUKvvSnjFlazrdh6wyHxHrdMknD.jpg', 'Scouts Guide to the Zombie Apocalypse', '56.686', '2015-10-23', 6.5, '1419', '[\'Comedy\', \'Horror\']', 'Three scouts and lifelong friends join forces with one badass cocktail waitress to become the world’s most unlikely team of heroes.  When their peaceful town is ravaged by a zombie invasion, they’ll fight for the badge of a lifetime and put their scouting skills to the test to save mankind from the undead.'),
(1133, '109689', 'es', 'https://image.tmdb.org/t/p/w500/m7JUNQu5zRsmFeUWZrGoV0fTp0B.jpg', 'Tengo ganas de ti', '58.626', '2012-06-22', 7.3, '1408', '[\'Drama\', \'Romance\']', 'The sexy Gin is the new love of Hache, but this can not forget his former girlfriend, so the love triangle is inevitable.'),
(1134, '302699', 'en', 'https://image.tmdb.org/t/p/w500/hXQVMbRNpf7c93e8clMY4W5DRm6.jpg', 'Central Intelligence', '50.965', '2016-06-15', 6.4, '4567', '[\'Action\', \'Comedy\', \'Mystery\', \'Crime\']', 'After he reunites with an old pal through Facebook, a mild-mannered accountant is lured into the world of international espionage.'),
(1135, '648990', 'es', 'https://image.tmdb.org/t/p/w500/fvTGWaQejnHQBZbEOrdbb38NBTC.jpg', 'La casa', '55.255', '2020-01-30', 6.5, '69', '[\'Horror\']', 'Responding to an urgent call for help, a police officer becomes trapped by the evil spirits of a cursed house.'),
(1136, '215', 'en', 'https://image.tmdb.org/t/p/w500/gTnaTysN8HsvVQqTRUh8m35mmUA.jpg', 'Saw II', '48.8', '2005-10-28', 6.6, '3944', '[\'Horror\']', 'When a new murder victim is discovered with all the signs of Jigsaw\'s hand, Detective Eric Matthews begins a full investigation and apprehends Jigsaw with little effort. But for Jigsaw, getting caught is just another part of his plan. Eight more of his victims are already fighting for their lives and now it\'s time for Matthews to join the game.'),
(1137, '475215', 'ja', 'https://image.tmdb.org/t/p/w500/b9XvI4Nehzi0nXyNVD6DtT39P6l.jpg', '未来のミライ', '55.562', '2018-06-16', 7.2, '523', '[\'Animation\', \'Family\', \'Fantasy\', \'Adventure\', \'Drama\']', 'The movie follows a 4-year old boy who is struggling to cope with the arrival of a little sister in the family until things turn magical. A mysterious garden in the backyard of the boy\'s home becomes a gateway allowing the child to travel back in time and encounter his mother as a little girl and his great-grandfather as a young man. These fantasy-filled adventures allow the child to change his perspective and help him become the big brother he was meant to be.'),
(1138, '511679', 'es', 'https://image.tmdb.org/t/p/w500/tkP0FzEivLxsUYt8BlaL8Sh7ceY.jpg', 'Héctor El Father: Conocerás la verdad', '52.918', '2018-03-22', 7.7, '84', '[\'Drama\', \'Documentary\']', 'This autobiography of Hector Delgado runs from his childhood to become one of the greatest exponents of the urban genre, but the results of that life did not please him and led him to try to take his life  .After being victim of a firefight at a service station in Aguada, a city hall in Puerto Rico, he stopped earning at least two hundred American dollars for presentation and being \"devout of Jesus\"'),
(1139, '874562', 'en', 'https://image.tmdb.org/t/p/w500/40Zrwud1EVxNvcjQkotZo7jmr4L.jpg', 'Swallow', '55.939', '2021-10-01', 4.7, '3', '[\'Drama\', \'History\', \'Thriller\', \'Crime\']', 'Set in the 1980s, Tolani Ajao is a bank secretary in Lagos, who finds herself persuaded by her friend Rose Adamson to enter the world of drug trafficking.'),
(1140, '37735', 'en', 'https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', 'Easy A', '57.331', '2010-09-16', 6.8, '5690', '[\'Comedy\']', 'Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school\'s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.'),
(1141, '4935', 'ja', 'https://image.tmdb.org/t/p/w500/13kOl2v0nD2OLbVSHnHk8GUFEhO.jpg', 'ハウルの動く城', '52.706', '2004-11-19', 8.4, '6789', '[\'Fantasy\', \'Animation\', \'Adventure\']', 'When Sophie, a shy young woman, is cursed with an old body by a spiteful witch, her only chance of breaking the spell lies with a self-indulgent yet insecure young wizard and his companions in his legged, walking castle.'),
(1142, '68724', 'en', 'https://image.tmdb.org/t/p/w500/uiiXHBd9oUrtUa4YqZiAoy05cRz.jpg', 'Elysium', '52.059', '2013-08-07', 6.5, '7150', '[\'Science Fiction\', \'Action\', \'Drama\', \'Thriller\']', 'In the year 2159, two classes of people exist: the very wealthy who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Rhodes, a hard line government ofﬁcial, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn’t stop the people of Earth from trying to get in, by any means they can. When unlucky Max is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life, but could bring equality to these polarized worlds.'),
(1143, '290764', 'en', 'https://image.tmdb.org/t/p/w500/2XoazCkD4gRlqkJK7q6TOTUx1ta.jpg', 'Tracers', '58.534', '2015-01-15', 6.1, '938', '[\'Action\', \'Crime\', \'Drama\']', 'Wanted by the mafia, a New York City bike messenger escapes into the world of parkour after meeting a beautiful stranger.'),
(1144, '479455', 'en', 'https://image.tmdb.org/t/p/w500/dPrUPFcgLfNbmDL8V69vcrTyEfb.jpg', 'Men in Black: International', '74.065', '2019-06-12', 6, '3650', '[\'Comedy\', \'Science Fiction\']', 'The Men in Black have always protected the Earth from the scum of the universe. In this new adventure, they tackle their biggest, most global threat to date: a mole in the Men in Black organization.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1145, '920', 'en', 'https://image.tmdb.org/t/p/w500/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', 'Cars', '59.195', '2006-06-08', 6.9, '11021', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\']', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town\'s offbeat characters.'),
(1146, '10112', 'en', 'https://image.tmdb.org/t/p/w500/1BVOSmQUhphMgnTxnXyfQ9tL1Sc.jpg', 'The Aristocats', '56.411', '1970-12-24', 7.3, '4016', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\']', 'When Madame Adelaide Bonfamille leaves her fortune to Duchess and her children—Bonfamille’s beloved family of cats—the butler plots to steal the money and kidnaps the legatees, leaving them out on a country road. All seems lost until the wily Thomas O’Malley Cat and his jazz-playing alley cats come to the aristocats’ rescue.'),
(1147, '146368', 'cn', 'https://image.tmdb.org/t/p/w500/f9uqMIJz4m6muckNpx36xCXqRCA.jpg', '虐之戀', '52.4', '1993-11-18', 5, '3', '[\'Drama\', \'Horror\']', 'A woman looks to a cop for help against her abusive husband, who constantly rapes, beats, and belittles her and her son, but the husband catches wind of the cop\'s plan.'),
(1148, '7485', 'en', 'https://image.tmdb.org/t/p/w500/2aWGxo1E5polpBjPvtBRkWp7qaS.jpg', 'Shooter', '79.804', '2007-03-22', 7.1, '3624', '[\'Action\', \'Drama\', \'Mystery\', \'Thriller\', \'Crime\']', 'A marksman living in exile is coaxed back into action after learning of a plot to kill the president. Ultimately double-crossed and framed for the attempt, he goes on the run to track the real killer and find out who exactly set him up, and why??'),
(1149, '86331', 'fr', 'https://image.tmdb.org/t/p/w500/wxvvNXY3n0637cOcdeC61eyVAnC.jpg', 'Q', '46.05', '2011-09-14', 5.3, '394', '[\'Drama\', \'Romance\']', 'In a social context deteriorated by a countrywide economic crisis, the life of several people will be turned upside down after they meet Cécile, a character who symbolizes desire.'),
(1150, '753453', 'en', 'https://image.tmdb.org/t/p/w500/9fSogEkqDfJQTuGHsTFloQz3Tw8.jpg', 'V/H/S/94', '49.612', '2021-09-26', 6.7, '129', '[\'Horror\', \'Thriller\']', 'A mysterious VHS tape leads a police S.W.A.T. team to the discovery of a sinister cult whose collection of pre-recorded material reveals a nightmarish conspiracy.'),
(1151, '1369', 'en', 'https://image.tmdb.org/t/p/w500/pzPdwOitmTleVE3YPMfIQgLh84p.jpg', 'Rambo: First Blood Part II', '50.739', '1985-05-21', 6.6, '2798', '[\'Action\', \'Adventure\', \'Thriller\', \'War\']', 'John Rambo is released from prison by the government for a top-secret covert mission to the last place on Earth he\'d want to return - the jungles of Vietnam.'),
(1152, '2978', 'en', 'https://image.tmdb.org/t/p/w500/yObYPMA58DnTMvJooFW7GG6jWAt.jpg', 'Ghostbusters II', '79.57', '1989-06-16', 6.5, '3159', '[\'Comedy\', \'Fantasy\']', 'Five years after they defeated Gozer, the Ghostbusters are out of business. When Dana begins to have ghost problems again, the boys come out of retirement to aid her and hopefully save New York City from a new paranormal threat.'),
(1153, '106758', 'ja', 'https://image.tmdb.org/t/p/w500/rr14VvTvCI7cFY1STaLegkyiXuC.jpg', '天使のはらわた 赤い淫画', '58.233', '1981-12-25', 5.5, '24', '[\'Drama\']', 'Nami is a department store worker who agrees to stand in for a friend in a magazine photo-shoot, which turns out to be for an S&M magazine. When the photos are published, she is sacked and her lover abandons her.'),
(1154, '26389', 'en', 'https://image.tmdb.org/t/p/w500/2nD0RAWVOccomLp1iToVJn6KC2a.jpg', 'From Paris with Love', '54.462', '2010-02-04', 6.2, '1535', '[\'Action\', \'Crime\', \'Thriller\']', 'James Reese has a good job as an ambassador\'s aid in France, but his real passion is a side gig—working in a minor role in the CIA. He would love to be a full-fledged agent and can\'t believe his luck when he lands an assignment with Charlie Wax. Trigger-happy Charlie soon has James crying for his desk job, but when he learns that the same guys they\'re trying to catch are after him, James realises that Charlie may be his only hope of survival.'),
(1155, '891060', 'en', 'https://m.media-amazon.com/images/M/MV5BZDUwMmZmYWQtZGI3NC00NDJlLThmZTAtNTJkODk3NTJjNGU5XkEyXkFqcGc@._V1_.jpg', 'Spider-Man: Lotus', '79.384', '', 0, '0', '[\'Action\', \'Drama\']', 'Following the tragic death of his former girlfriend – seemingly caused by his own attempt to save her – Peter Parker lingers in his guilt of the past, questioning whether the curse of his alter ego should be buried for good. When he\'s met by the news that a terminally ill child has requested to meet Spider-Man, Peter contemplates the decision to comfort him in his final days.'),
(1156, '854442', 'en', 'https://image.tmdb.org/t/p/w500/lkCi5Cm71QqHEwuIppWoI7paiZn.jpg', 'Next-Door Nightmare', '79.384', '2021-07-08', 6, '2', '[\'Thriller\', \'TV Movie\']', 'When young couple Sarah and Kyle move next door to Helen, a charismatic older woman, they have no idea she\'s a deeply disturbed psychopath who will stop at nothing to become Sarah\'s surrogate mother, and grandmother to the child she is expecting. Julia Borsellino, Mark Taylor, Deborah Grover, Marium Carvell star. (2021)'),
(1157, '10191', 'en', 'https://image.tmdb.org/t/p/w500/53dsJ3oEnBhTBVMigWJ9tkA5bzJ.jpg', 'How to Train Your Dragon', '54.758', '2010-03-10', 7.8, '10423', '[\'Fantasy\', \'Adventure\', \'Animation\', \'Family\']', 'As the son of a Viking leader on the cusp of manhood, shy Hiccup Horrendous Haddock III faces a rite of passage: he must kill a dragon to prove his warrior mettle. But after downing a feared dragon, he realizes that he no longer wants to destroy it, and instead befriends the beast – which he names Toothless – much to the chagrin of his warrior father'),
(1158, '289720', 'en', 'https://image.tmdb.org/t/p/w500/efsgCTlofzIuysfokEp7hwQnUho.jpg', 'Outcast', '47.261', '2014-09-26', 5, '354', '[\'Action\']', 'A mysterious warrior teams up with the daughter and son of a deposed Chinese Emperor to defeat their cruel Uncle, who seeks their deaths.'),
(1159, '796849', 'ja', 'https://image.tmdb.org/t/p/w500/c7JzcVK4OZY1u7HYiFBOASkKPP5.jpg', '彼女', '46.443', '2021-04-15', 6.4, '87', '[\'Drama\', \'Romance\', \'Thriller\']', 'Rei helps the woman she\'s been in love with for years escape her abusive husband. While on the run, their feelings for each other catch fire.'),
(1160, '481848', 'en', 'https://image.tmdb.org/t/p/w500/33VdppGbeNxICrFUtW2WpGHvfYc.jpg', 'The Call of the Wild', '50.723', '2020-02-19', 7.6, '2676', '[\'Adventure\', \'Family\', \'Drama\']', 'Buck is a big-hearted dog whose blissful domestic life is turned upside down when he is suddenly uprooted from his California home and transplanted to the exotic wilds of the Yukon during the Gold Rush of the 1890s. As the newest rookie on a mail delivery dog sled team—and later its leader—Buck experiences the adventure of a lifetime, ultimately finding his true place in the world and becoming his own master.'),
(1161, '8373', 'en', 'https://image.tmdb.org/t/p/w500/pLBb0whOzVDtJvyD4DPeQyQNOqp.jpg', 'Transformers: Revenge of the Fallen', '55.454', '2009-06-19', 6.1, '6727', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'Sam Witwicky leaves the Autobots behind for a normal life. But when his mind is filled with cryptic symbols, the Decepticons target him and he is dragged back into the Transformers\' war.'),
(1162, '506680', 'en', 'https://image.tmdb.org/t/p/w500/oD5RxDJGdJgpX8X61QMX0qNyYYu.jpg', 'Unbroken: Path to Redemption', '55.116', '2018-09-14', 7, '87', '[\'Drama\']', 'Zamperini returns to California where he wound up marrying Cynthia Applewhite while wrestling with untreated PTSD, suffering constant nightmares, angry, bitter and deeply depressed, his wife convinces Zamperini to attend the 1949 Billy Graham Crusade.'),
(1163, '558', 'en', 'https://image.tmdb.org/t/p/w500/eg8XHjA7jkM3ulBLnfGTczR9ytI.jpg', 'Spider-Man 2', '65.27', '2004-06-25', 7.1, '11527', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Peter Parker is going through a major identity crisis. Burned out from being Spider-Man, he decides to shelve his superhero alter ego, which leaves the city suffering in the wake of carnage left by the evil Doc Ock. In the meantime, Parker still can\'t act on his feelings for Mary Jane Watson, a girl he\'s loved since childhood. A certain anger begins to brew in his best friend Harry Osborn as well...'),
(1164, '14574', 'en', 'https://image.tmdb.org/t/p/w500/sLwYSEVVV3r047cjrpRAbGgNsfL.jpg', 'The Boy in the Striped Pyjamas', '47.175', '2008-05-07', 7.9, '5494', '[\'War\', \'Drama\']', 'When his family moves from their home in Berlin to a strange new house in Poland, young Bruno befriends Shmuel, a boy who lives on the other side of the fence where everyone seems to be wearing striped pajamas. Unaware of Shmuel\'s fate as a Jewish prisoner or the role his own Nazi father plays in his imprisonment, Bruno embarks on a dangerous journey inside the camp\'s walls.'),
(1165, '869617', 'fr', 'https://image.tmdb.org/t/p/w500/xgQ55Koxnq6rwLoPDIfaIjm16bA.jpg', 'Friendzone', '49.92', '2021-09-29', 6.3, '109', '[\'Romance\', \'Comedy\']', 'Hopeful romantic Thibault believes his luck could change when sparks fly between him and Rose. But can he go from bestie to boyfriend?'),
(1166, '11', 'en', 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', 'Star Wars', '62.168', '1977-05-25', 8.2, '16223', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.'),
(1167, '14560', 'en', 'https://image.tmdb.org/t/p/w500/A4zZv0Q1VKURFZFEl2vwjaE2q0g.jpg', 'Paul Blart: Mall Cop', '50.62', '2009-01-15', 5.4, '1957', '[\'Action\', \'Adventure\', \'Comedy\', \'Family\']', 'Mild-mannered Paul Blart has always had huge dreams of becoming a State Trooper. Until then, he patrols the local mall as a security guard. With his closely cropped moustache, personal transporter and gung-ho attitude, only Blart seems to take his job seriously. All that changes when a team of thugs raids the mall and takes hostages. Untrained, unarmed and a super-size target, Blart has to become a real cop to save the day.'),
(1168, '15167', 'en', 'https://image.tmdb.org/t/p/w500/eIkXJggVmzN4MyPgJ2kDjOy9lmQ.jpg', 'Barbie in the Nutcracker', '56.917', '2001-09-30', 6.8, '815', '[\'Animation\', \'Family\']', '\"Barbie\" stars as Clara in this animated retelling of the classic Christmas ballet, complete with Tchaikovsky soundtrack and ballet choreography.'),
(1169, '41439', 'en', 'https://image.tmdb.org/t/p/w500/qHCZ6LjtmqWDfXXN28TlIC9OppK.jpg', 'Saw 3D', '49.408', '2010-10-21', 6, '2225', '[\'Horror\', \'Crime\']', 'As a deadly battle rages over Jigsaw\'s brutal legacy, a group of Jigsaw survivors gathers to seek the support of self-help guru and fellow survivor Bobby Dagen, a man whose own dark secrets unleash a new wave of terror.'),
(1170, '55779', 'en', 'https://image.tmdb.org/t/p/w500/Akx1Po4ZLetOWfYJhQf75tbhTtK.jpg', 'Final Destination 5', '43.899', '2011-08-12', 6, '2534', '[\'Horror\', \'Mystery\']', 'In this fifth installment, Death is just as omnipresent as ever, and is unleashed after one man’s premonition saves a group of coworkers from a terrifying suspension bridge collapse. But this group of unsuspecting souls was never supposed to survive, and, in a terrifying race against time, the ill-fated group frantically tries to discover a way to escape Death’s sinister agenda.'),
(1171, '842171', 'th', 'https://image.tmdb.org/t/p/w500/jhbJCqSUmhFJJYo27DP44kdN6Fb.jpg', 'โปรเจกต์ลับ หลับ เป็น ตาย', '52.038', '2021-07-16', 6.4, '48', '[\'Science Fiction\', \'Thriller\']', 'Four insomniac med school students are lured into a neuroscience experiment that spirals out of control and must find a way out before it’s too late.'),
(1172, '513310', 'en', 'https://image.tmdb.org/t/p/w500/nt8on8Ge0Lsw0oF6EbmGiDV69Hf.jpg', 'Boss Level', '49.655', '2021-02-19', 6.9, '754', '[\'Action\', \'Science Fiction\', \'Thriller\']', 'A retired special forces officer is trapped in a never-ending time loop on the day of his death.'),
(1173, '44896', 'en', 'https://image.tmdb.org/t/p/w500/A5MP1guV8pbruieG0tnpPIbaJtt.jpg', 'Rango', '53.581', '2011-03-02', 6.7, '4997', '[\'Animation\', \'Comedy\', \'Family\', \'Western\', \'Adventure\']', 'When Rango, a lost family pet, accidentally winds up in the gritty, gun-slinging town of Dirt, the less-than-courageous lizard suddenly finds he stands out. Welcomed as the last hope the town has been waiting for, new Sheriff Rango is forced to play his new role to the hilt.'),
(1174, '345887', 'en', 'https://image.tmdb.org/t/p/w500/cQvc9N6JiMVKqol3wcYrGshsIdZ.jpg', 'The Equalizer 2', '43.79', '2018-07-19', 6.6, '3704', '[\'Action\', \'Thriller\', \'Crime\']', 'Robert McCall, who serves an unflinching justice for the exploited and oppressed, embarks on a relentless, globe-trotting quest for vengeance when a long-time girl friend is murdered.'),
(1175, '13654', 'en', 'https://image.tmdb.org/t/p/w500/uB0DQU4Cog8tYrkiOEVTmDw6Qnn.jpg', '101 Dalmatians II: Patch\'s London Adventure', '57.117', '2003-03-02', 6, '902', '[\'Family\', \'Adventure\', \'Comedy\', \'Animation\']', 'Being one of 101 takes its toll on Patch, who doesn\'t feel unique. When he\'s accidentally left behind on moving day, he meets his idol, Thunderbolt, who enlists him on a publicity campaign.'),
(1176, '6479', 'en', 'https://image.tmdb.org/t/p/w500/iPDkaSdKk2jRLTM65UOEoKtsIZ8.jpg', 'I Am Legend', '56.016', '2007-12-12', 7.2, '12652', '[\'Drama\', \'Science Fiction\', \'Thriller\']', 'Robert Neville is a scientist who was unable to stop the spread of the terrible virus that was incurable and man-made. Immune, Neville is now the last human survivor in what is left of New York City and perhaps the world. For three years, Neville has faithfully sent out daily radio messages, desperate to find any other survivors who might be out there. But he is not alone.'),
(1177, '546554', 'en', 'https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', 'Knives Out', '55.039', '2019-11-27', 7.9, '7991', '[\'Comedy\', \'Drama\', \'Crime\', \'Mystery\']', 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan\'s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan\'s untimely death.'),
(1178, '812630', 'es', 'https://image.tmdb.org/t/p/w500/zuUMgDpxdnZSI4hQVgCIr9NWMOm.jpg', 'El cuartito', '52.353', '2021-03-25', 4.6, '12', '[\'Comedy\']', 'The dreams of five strangers traveling to Puerto Rico are put on hold when immigration authorities confine them in \'El cuartito\'.'),
(1179, '12242', 'en', 'https://image.tmdb.org/t/p/w500/mIHE3BKyAKG8ocRAoZuCQN1NTv9.jpg', 'Mulan II', '52.861', '2004-11-03', 6.5, '1878', '[\'Animation\', \'Comedy\', \'Family\', \'Action\']', 'Fa Mulan gets the surprise of her young life when her love, Captain Li Shang asks for her hand in marriage. Before the two can have their happily ever after, the Emperor assigns them a secret mission, to escort three princesses to Chang\'an, China. Mushu is determined to drive a wedge between the couple after he learns that he will lose his guardian job if Mulan marries into the Li family.'),
(1180, '841793', 'pt', 'https://image.tmdb.org/t/p/w500/jZonuUeC9bH2D5A609w7nkplhyj.jpg', 'Ilhados', '44.518', '2021-01-02', 5, '35', '[\'Drama\']', 'Tensions run high while food runs low as six influencers find themselves stranded on a secluded island after plans for a weekend escape go awry.'),
(1181, '181808', 'en', 'https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', 'Star Wars: The Last Jedi', '54.966', '2017-12-13', 6.9, '12376', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.'),
(1182, '660982', 'en', 'https://image.tmdb.org/t/p/w500/xqvX5A24dbIWaeYsMTxxKX5qOfz.jpg', 'American Pie Presents: Girls\' Rules', '56.199', '2020-10-06', 6.5, '380', '[\'Comedy\']', 'It\'s Senior year at East Great Falls. Annie, Kayla, Michelle, and Stephanie decide to harness their girl power and band together to get what they want their last year of high school.'),
(1183, '680', 'en', 'https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', 'Pulp Fiction', '59.3', '1994-09-10', 8.5, '22032', '[\'Thriller\', \'Crime\']', 'A burger-loving hit man, his philosophical partner, a drug-addled gangster\'s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.'),
(1184, '73456', 'en', 'https://image.tmdb.org/t/p/w500/lI2jPbssax6XX5vDqB9mTJHGzfH.jpg', 'Barbie: Princess Charm School', '55.652', '2011-08-11', 7.4, '548', '[\'Family\', \'Animation\', \'Fantasy\']', 'Barbie stars as Blair Willows, a kind-hearted girl who is chosen to attend Princess Charm School: a magical, modern place that teaches dancing, how to have tea parties, and proper princess manners. Blair loves her classes -- as well as the helpful magical sprites and her new friends, Princesses Hadley and Isla. But when royal teacher Dame Devin discovers that Blair looks a lot like the kingdom’s missing princess, she turns Blair’s world upside down to stop her from claiming the throne. Now Blair, Hadley and Delancy must find an enchanted crown to prove Blair’s true identity in this charming and magical princess story!'),
(1185, '12244', 'en', 'https://image.tmdb.org/t/p/w500/gWKZ1iLhukvLoh8XY2N4tMvRQ2M.jpg', '9', '46.699', '2009-08-19', 6.8, '2772', '[\'Action\', \'Adventure\', \'Animation\', \'Science Fiction\', \'Thriller\']', 'When 9 first comes to life, he finds himself in a post-apocalyptic world. All humans are gone, and it is only by chance that he discovers a small community of others like him taking refuge from fearsome machines that roam the earth intent on their extinction. Despite being the neophyte of the group, 9 convinces the others that hiding will do them no good.'),
(1186, '11442', 'en', 'https://image.tmdb.org/t/p/w500/1mlKwbNzJCGzqe4i0ZEJtUUL290.jpg', 'Halloween: Resurrection', '52.085', '2002-07-01', 4.6, '873', '[\'Horror\', \'Thriller\']', 'Serial Killer Michael Myers is not finished with Laurie Strode, and their rivalry finally comes to an end. But is this the last we see of Myers? Freddie Harris and Nora Winston are reality programmers at DangerTainment, and are planning to send a group of 6 thrill-seeking teenagers into the childhood home of Myers. Cameras are placed all over the house and no one can get out of the house... and then Michael arrives home!'),
(1187, '10528', 'en', 'https://image.tmdb.org/t/p/w500/momkKuWburNTqKBF6ez7rvhYVhE.jpg', 'Sherlock Holmes', '37.233', '2009-01-01', 7.2, '11733', '[\'Action\', \'Adventure\', \'Crime\', \'Mystery\']', 'Eccentric consulting detective, Sherlock Holmes and Doctor John Watson battle to bring down a new nemesis and unravel a deadly plot that could destroy England.'),
(1188, '466282', 'en', 'https://image.tmdb.org/t/p/w500/hKHZhUbIyUAjcSrqJThFGYIR6kI.jpg', 'To All the Boys I\'ve Loved Before', '51.792', '2018-08-16', 7.7, '7332', '[\'Comedy\', \'Romance\']', 'Lara Jean\'s love life goes from imaginary to out of control when her secret letters to every boy she\'s ever fallen for are mysteriously mailed out.'),
(1189, '493922', 'en', 'https://image.tmdb.org/t/p/w500/hjlZSXM86wJrfCv5VKfR5DI2VeU.jpg', 'Hereditary', '48.14', '2018-06-07', 7.2, '5361', '[\'Horror\', \'Mystery\', \'Thriller\']', 'When Ellen, the matriarch of the Graham family, passes away, her daughter\'s family begins to unravel cryptic and increasingly terrifying secrets about their ancestry.'),
(1190, '9532', 'en', 'https://image.tmdb.org/t/p/w500/1mXhlQMnlfvJ2frxTjZSQNnA9Vp.jpg', 'Final Destination', '52.521', '2000-03-17', 6.5, '4108', '[\'Horror\']', 'After a teenager has a terrifying vision of him and his friends dying in a plane crash, he prevents the accident only to have Death hunt them down, one by one.'),
(1191, '717192', 'nl', 'https://image.tmdb.org/t/p/w500/uT0CbPtySSNLNh6MvFkq3xwbRBR.jpg', 'Ferry', '54.72', '2021-05-14', 6.8, '132', '[\'Action\', \'Crime\', \'Drama\']', 'Before he built a drug empire, Ferry Bouman returns to his hometown on a revenge mission that finds his loyalty tested — and a love that alters his life.'),
(1192, '10340', 'en', 'https://image.tmdb.org/t/p/w500/340NcWz9SQXWQyf4oicMxjbrLOb.jpg', 'Lady and the Tramp', '57.016', '1955-06-22', 7.1, '4209', '[\'Family\', \'Animation\', \'Romance\']', 'Lady, a golden cocker spaniel, meets up with a mongrel dog who calls himself the Tramp. He is obviously from the wrong side of town, but happenings at Lady\'s home make her decide to travel with him for a while.'),
(1193, '65291', 'en', 'https://image.tmdb.org/t/p/w500/v8ZGOwcE0aFEpfWdZrVdmdGoFWC.jpg', 'Green Lantern: Emerald Knights', '50.866', '2011-04-09', 6.7, '383', '[\'Action\', \'Adventure\', \'Animation\', \'Science Fiction\', \'Drama\']', 'As the home planet of the Green Lantern Corps faces a battle with an ancient enemy, Hal Jordan prepares new recruit Arisia for the coming conflict by relating stories of the first Green Lantern and several of Hal\'s comrades.'),
(1194, '101299', 'en', 'https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg', 'The Hunger Games: Catching Fire', '46.959', '2013-11-15', 7.4, '14375', '[\'Adventure\', \'Action\', \'Science Fiction\']', 'Katniss Everdeen has returned home safe after winning the 74th Annual Hunger Games along with fellow tribute Peeta Mellark. Winning means that they must turn around and leave their family and close friends, embarking on a \"Victor\'s Tour\" of the districts. Along the way Katniss senses that a rebellion is simmering, but the Capitol is still very much in control as President Snow prepares the 75th Annual Hunger Games (The Quarter Quell) - a competition that could change Panem forever.'),
(1195, '20943', 'en', 'https://image.tmdb.org/t/p/w500/2rq96Ihbqb1eU3TEBVtgFlqbeX7.jpg', 'The Ugly Truth', '48.647', '2009-07-24', 6.5, '2859', '[\'Comedy\', \'Romance\']', 'A romantically challenged morning show producer is reluctantly embroiled in a series of outrageous tests by her chauvinistic correspondent to prove his theories on relationships and help her find love. His clever ploys, however, lead to an unexpected result.'),
(1196, '13053', 'en', 'https://image.tmdb.org/t/p/w500/v5aC4nrzXFGJDWY4JO1eengXzqk.jpg', 'Bolt', '56.544', '2008-11-21', 6.5, '4769', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\']', 'Bolt is the star of the biggest show in Hollywood. The only problem is, he thinks it\'s real. After he\'s accidentally shipped to New York City and separated from Penny, his beloved co-star and owner, Bolt must harness all his \"super powers\" to find a way home.'),
(1197, '19458', 'en', 'https://image.tmdb.org/t/p/w500/tPKD9hmuYxclAQnfup47qLx8a5T.jpg', 'Princess Protection Program', '56.242', '2009-05-20', 6.6, '1444', '[\'Family\', \'TV Movie\', \'Comedy\', \'Drama\']', 'When an evil dictator threatens to take over the kingdom, Princess Rosalinda gets put into the Princess Protection Program. She is taken under the wing of General Joe Mason, an agent from the agency, and his daughter, Carter, who works after school at a nearby bait shop. Rosalinda goes undercover as a regular teen named, Rosie with the help of Carter. In turn, Rosalinda helps Carter overcome insecurities with herself and her crush on Donny who also likes her but can\'t tell or get shy.'),
(1198, '454286', 'en', 'https://image.tmdb.org/t/p/w500/1MwoZ4U8SGm7yIzfPFcTTbiiOYY.jpg', 'God\'s Not Dead: A Light in Darkness', '56.6', '2018-03-30', 6.8, '134', '[\'Drama\']', 'Pastor Dave  responds to the unimaginable tragedy of having his church, located on the grounds of the local university, burned down.'),
(1199, '406563', 'en', 'https://image.tmdb.org/t/p/w500/nb9fc9INMg8kQ8L7sE7XTNsZnUX.jpg', 'Insidious: The Last Key', '42.548', '2018-01-03', 6.2, '2122', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Parapsychologist Elise Rainier and her team travel to Five Keys, NM, to investigate a man’s claim of a haunting. Terror soon strikes when Rainier realizes that the house he lives in was her family’s old home.'),
(1200, '76589', 'en', 'https://image.tmdb.org/t/p/w500/6IUhwX2fHPBzsKHpygW50a3tkEw.jpg', 'Justice League: Doom', '50.837', '2012-02-28', 7.5, '621', '[\'Action\', \'Animation\', \'Science Fiction\']', 'An adaptation of Mark Waid\'s \"Tower of Babel\" story from the JLA comic. Vandal Savage steals confidential files Batman has compiled on the members of the Justice League, and learns all their weaknesses.'),
(1201, '7980', 'en', 'https://image.tmdb.org/t/p/w500/sn0iDphRxQ7I6aLd9igIgACITak.jpg', 'The Lovely Bones', '46.735', '2009-02-19', 7, '3593', '[\'Fantasy\', \'Drama\']', 'After being brutally murdered, 14-year-old Susie Salmon watches from heaven over her grief-stricken family -- and her killer. As she observes their daily lives, she must balance her thirst for revenge with her desire for her family to heal.'),
(1202, '547565', 'en', 'https://image.tmdb.org/t/p/w500/rqs2CXpc4d5FzeP1EZCYItAVo81.jpg', 'The Night House', '42.387', '2021-07-15', 6.8, '285', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Reeling from the unexpected death of her husband, Beth is left alone in the lakeside home he built for her. Soon she begins to uncover her recently deceased husband\'s disturbing secrets.'),
(1203, '622230', 'en', 'https://image.tmdb.org/t/p/w500/7M3fUjKWukFuPAJsFjZsTVQIRsJ.jpg', 'LEGO Marvel Spider-Man: Vexed by Venom', '54.556', '2019-08-03', 7.1, '7', '[\'Animation\', \'Action\']', 'Thanks to Green Goblin and Venom, tech theft is now at an all-time high. Can our Friendly Neighborhood Spider-Man put an end to their mysterious villainous scheme before all of New York City is destroyed?'),
(1204, '8839', 'en', 'https://image.tmdb.org/t/p/w500/2ah8fNJFZVU3vcXhU5xfAYi2eym.jpg', 'Casper', '43.761', '1995-05-26', 6.3, '3677', '[\'Fantasy\', \'Comedy\', \'Family\']', 'Casper is a kind young ghost who peacefully haunts a mansion in Maine. When specialist James Harvey arrives to communicate with Casper and his fellow spirits, he brings along his teenage daughter, Kat. Casper quickly falls in love with Kat, but their budding relationship is complicated not only by his transparent state, but also by his troublemaking apparition uncles and their mischievous antics.'),
(1205, '227348', 'en', 'https://image.tmdb.org/t/p/w500/2o4vBAnORr9UnLMvWHhULGDHfzH.jpg', 'Paranormal Activity: The Marked Ones', '45.811', '2014-01-01', 5.4, '1112', '[\'Horror\', \'Thriller\']', 'Seventeen-year-old Jesse has been hearing terrifying sounds coming from his neighbor’s apartment, but when he turns on his camera and sets out to uncover their source, he encounters an ancient evil that won’t rest until it’s claimed his very soul.'),
(1206, '869', 'en', 'https://image.tmdb.org/t/p/w500/2r9iKnlSYEk4daQadsXfcjHfIjQ.jpg', 'Planet of the Apes', '39.037', '2001-07-25', 5.7, '3115', '[\'Thriller\', \'Science Fiction\', \'Action\', \'Adventure\']', 'After a spectacular crash-landing on an uncharted planet, brash astronaut Leo Davidson finds himself trapped in a savage world where talking apes dominate the human race. Desperate to find a way home, Leo must evade the invincible gorilla army led by Ruthless General Thade.'),
(1207, '360789', 'pt', 'https://image.tmdb.org/t/p/w500/whuQjGVlqeHyggFAyDg3x9fd5Ay.jpg', 'Sexo, Sexo e Sexo', '55.823', '1984-09-21', 5.5, '43', '[\'Crime\']', ''),
(1208, '34584', 'en', 'https://image.tmdb.org/t/p/w500/lWJC8om086h01f0CMGR9ombdpnI.jpg', 'Die unendliche Geschichte', '55.733', '1984-04-05', 7.2, '3083', '[\'Drama\', \'Family\', \'Fantasy\', \'Adventure\']', 'While hiding from bullies in his school\'s attic, a young boy discovers the extraordinary land of Fantasia, through a magical book called The Neverending Story. The book tells the tale of Atreyu, a young warrior who, with the help of a luck dragon named Falkor, must save Fantasia from the destruction of The Nothing.'),
(1209, '638597', 'en', 'https://image.tmdb.org/t/p/w500/rejrD9ovTHJbfmpLM0mbEliEPV6.jpg', 'Yes Day', '48.057', '2021-03-12', 7, '720', '[\'Comedy\', \'Family\']', 'A mom and dad who usually say no decide to say yes to their kids\' wildest requests — with a few ground rules — on a whirlwind day of fun and adventure.'),
(1210, '667538', 'en', 'https://image.tmdb.org/t/p/w500/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', 'Transformers: Rise of the Beasts', '55.116', '2022-06-22', 0, '0', '[\'Action\', \'Science Fiction\', \'Adventure\']', 'The origin story for Optimus Prime and how he became the leader of the Autobots, and introduces the Maximals, the Predacons, and the Terrorcons.'),
(1211, '424783', 'en', 'https://image.tmdb.org/t/p/w500/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', 'Bumblebee', '59.595', '2018-12-15', 6.7, '4662', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'On the run in the year 1987, Bumblebee finds refuge in a junkyard in a small Californian beach town. Charlie, on the cusp of turning 18 and trying to find her place in the world, discovers Bumblebee, battle-scarred and broken.  When Charlie revives him, she quickly learns this is no ordinary yellow VW bug.'),
(1212, '524251', 'en', 'https://image.tmdb.org/t/p/w500/2LwamrHAmxqEHsT9JViFJxT08Ek.jpg', 'I See You', '48.151', '2019-09-11', 7, '828', '[\'Thriller\', \'Mystery\', \'Horror\', \'Crime\']', 'When a 12-year-old boy goes missing, lead investigator Greg Harper struggles to balance the pressure of the investigation and troubles with his wife, Jackie. Facing a recent affair, great strain is put on the family that slowly gnaws away at Jackie\'s grip on reality. But after a malicious presence manifests itself in their home and puts their son, Connor, in mortal danger, the cold, hard truth about evil in the Harper household is finally uncovered.'),
(1213, '77866', 'en', 'https://image.tmdb.org/t/p/w500/dNNjyZQ0zVtmPa74nJE63Kn0xEx.jpg', 'Contraband', '51.727', '2012-01-12', 6.3, '1647', '[\'Thriller\', \'Action\', \'Drama\', \'Crime\']', 'When his brother-in-law runs afoul of a drug lord, family man Chris Farraday turns to a skill he abandoned long ago—smuggling—to repay the debt. But the job goes wrong, and Farraday finds himself wanted by cops, crooks and killers alike.'),
(1214, '15373', 'en', 'https://image.tmdb.org/t/p/w500/ki79dSjh6Rr51xrsz4dT04UGxSU.jpg', 'Role Models', '46.275', '2008-11-07', 6.5, '1392', '[\'Comedy\']', 'Two salesmen trash a company truck on an energy drink-fueled bender. Upon their arrest, the court gives them a choice: do hard time or spend 150 service hours with a mentorship program. After one day with the kids, however, jail doesn\'t look half bad.'),
(1215, '627661', 'en', 'https://image.tmdb.org/t/p/w500/maBFNvaxae6IgLL4qwz7hvz19EZ.jpg', 'Cranston Academy: Monster Zone', '47.241', '2020-04-29', 6.5, '73', '[\'Adventure\', \'Science Fiction\', \'Animation\', \'Fantasy\', \'Horror\']', 'An intelligent 15-year-old high school student is unexpectedly transferred to a boarding school where he opens a portal of monsters from another dimension.'),
(1216, '9444', 'en', 'https://image.tmdb.org/t/p/w500/bppGWGA8zq1sRvTdDJnUzVW9GcH.jpg', 'Anastasia', '55.266', '1997-11-20', 7.6, '4397', '[\'Animation\', \'Family\']', 'This animated adventure spins a more optimistic twist on the long-mythicized story of the \"lost daughter\" of Russia\'s last czar. A wicked sorcerer places a curse on the Romanov family, and Anastasia is separated from them during their attempts to escape from a rowdy revolt seizing their palace. Years later, after growing up with amnesia in an orphanage, \"Anya\" encounters two Russian men seeking a reward offered by the Dowager Empress Marie, for the return of her missing granddaughter. They decide to travel together to visit the Empress in Paris. Will Anya finally be reunited with her remaining family and find a loving home at last?'),
(1217, '824920', 'es', 'https://image.tmdb.org/t/p/w500/MvLpAU308ij2dI4KKuuPWROolo.jpg', 'Stop', '42.919', '2021-05-01', 4, '2', '[]', 'Misfortune leads the musical group Doble Pletina to be sentenced to perform community services in a mysterious park in Barcelona. Director Stanley Sunday unfolds his singular, fantastic and freely absurd universe in this witty musical comedy starring the band Doble Pletina. Stop includes four original songs by the group, produced by Hidrogenesse.'),
(1218, '43947', 'en', 'https://image.tmdb.org/t/p/w500/4VZ9eqel8Fsp54KMnesr3xIc67N.jpg', 'I Spit on Your Grave', '47.264', '2010-06-17', 6.5, '1643', '[\'Thriller\', \'Crime\', \'Horror\']', 'Jennifer is a writer working on a new novel and, needing to get out of the city to finish it, hires a riverside apartment in upstate New York to finish her book—attracting the attention of a number of rowdy male locals.'),
(1219, '258489', 'en', 'https://image.tmdb.org/t/p/w500/eJrfz178xBGlxjDGxnBXTzWWa4w.jpg', 'The Legend of Tarzan', '49.142', '2016-06-29', 5.9, '5331', '[\'Fantasy\', \'Action\', \'Adventure\', \'Drama\', \'Romance\']', 'Tarzan, having acclimated to life in London, is called back to his former home in the jungle to investigate the activities at a mining encampment.'),
(1220, '29826', 'es', 'https://image.tmdb.org/t/p/w500/nQ94eTRXQogJTDwlbq0R8VXSNMZ.jpg', 'La Leyenda de la Nahuala', '46.729', '2007-10-31', 7.6, '123', '[\'Animation\', \'Family\', \'Fantasy\']', 'Leo San Juan, an insecure child of nine years old, lives eternally frightened by horror stories that Nando tells his older brother. Within these stories it is \'The Legend of Nahuala\', according to which, an old abandoned Casona is possessed by the spirit of an evil witch known as the Nahuala.'),
(1221, '471707', 'pl', 'https://image.tmdb.org/t/p/w500/aUM9CZLwvbgTMiYducW3rBoqDyd.jpg', 'Boże Ciało', '60.493', '2019-09-10', 7.8, '335', '[\'Drama\']', 'A pious 20-year-old juvenile delinquent is sent to work at a sawmill in a small town; on arrival, he dresses up as a priest and accidentally takes over the local parish. The arrival of this young, charismatic preacher is an opportunity for the local community to begin the healing process after a tragedy that happened a year prior.'),
(1222, '630', 'en', 'https://image.tmdb.org/t/p/w500/hpjssLLLrYuefDqR2iAl8wYUxy9.jpg', 'The Wizard of Oz', '55.653', '1939-08-15', 7.6, '4319', '[\'Adventure\', \'Fantasy\', \'Family\']', 'Young Dorothy finds herself in a magical world where she makes friends with a lion, a scarecrow and a tin man as they make their way along the yellow brick road to talk with the Wizard and ask for the things they miss most in their lives. The Wicked Witch of the West is the only thing that could stop them.'),
(1223, '419430', 'en', 'https://image.tmdb.org/t/p/w500/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', 'Get Out', '45.058', '2017-02-24', 7.6, '13420', '[\'Mystery\', \'Thriller\', \'Horror\']', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family\'s overly accommodating behavior as nervous attempts to deal with their daughter\'s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.'),
(1224, '16290', 'en', 'https://image.tmdb.org/t/p/w500/rqK0MkfpWT2DpFjNzkvjHf0vxZ4.jpg', 'Jackass 3D', '48.642', '2010-10-15', 6.5, '1010', '[\'Comedy\', \'Documentary\', \'Action\']', 'Johnny Knoxville, Bam Margera, Steve-O, Wee Man and the rest of their fearless and foolhardy friends take part in another round of outrageous pranks and stunts. In addition to standing in the path of a charging bull, launching themselves into the air and crashing through various objects, the guys perform in segments such as \"Sweatsuit Cocktail,\" \"Beehive Tetherball\" and \"Lamborghini Tooth Pull.\"'),
(1225, '9286', 'en', 'https://image.tmdb.org/t/p/w500/p7ARuNKUGPGvkBiDtIDvAzYzonX.jpg', 'Final Destination 3', '59.886', '2006-02-09', 6.1, '2859', '[\'Horror\', \'Mystery\']', 'A student\'s premonition of a deadly rollercoaster ride saves her life and a lucky few, but not from death itself – which seeks out those who escaped their fate.'),
(1226, '442062', 'en', 'https://image.tmdb.org/t/p/w500/t2wy38iiMpB8WsgJi3lYeDnGh2H.jpg', 'Goosebumps 2: Haunted Halloween', '46.593', '2018-10-11', 6.1, '1093', '[\'Adventure\', \'Comedy\', \'Fantasy\', \'Family\', \'Horror\']', 'Two boys face an onslaught from witches, monsters, ghouls and a talking dummy after they discover a mysterious book by author R. L. Stine.'),
(1227, '570503', 'ko', 'https://image.tmdb.org/t/p/w500/7yaF5BOtPjQH8JDSSiVbzdrsWM4.jpg', '유열의 음악앨범', '58.694', '2019-08-28', 7.9, '163', '[\'Romance\', \'Drama\']', 'In 1994, on the first day that Yoo Yeul went on air as the new DJ of the popular radio show ‘Music Album,\' a college girl Mi-su meets Hyun-woo who happens to drop by the bakery she works at. Like the music streaming from the radio, their frequencies slowly come in sync; even when they\'re apart, the show brings them together through ebbs and flows of events arising from both pure coincidence and inevitability, until the bitter reality sets in and drives them apart...'),
(1228, '476968', 'en', 'https://image.tmdb.org/t/p/w500/2NUXG94dGMKYgJL1BkJGKynMb3l.jpg', 'Paul, Apostle of Christ', '46.665', '2018-03-23', 7.4, '233', '[\'Drama\', \'History\']', 'Risking his life, Luke ventures to Rome to visit Paul -- the apostle who\'s bound in chains and held captive in Nero\'s darkest and bleakest prison cell. Haunted by the shadows of his past misdeeds, Paul wonders if he\'s been forgotten as he awaits his grisly execution. Before Paul\'s death, Luke resolves to write another book that details the birth of what will come to be known as the church.'),
(1229, '12279', 'en', 'https://image.tmdb.org/t/p/w500/buA8dN4zLNr0dYBeKfHfMnEfdLE.jpg', 'Spy Kids 3-D: Game Over', '53.799', '2003-07-25', 5.1, '1691', '[\'Action\', \'Adventure\', \'Comedy\', \'Family\', \'Science Fiction\']', 'Carmen\'s caught in a virtual reality game designed by the Kids\' new nemesis, the Toymaker. It\'s up to Juni to save his sister, and ultimately the world.'),
(1230, '431693', 'en', 'https://image.tmdb.org/t/p/w500/e7rWcrnuNej3JeVjqmRu0jVeRa4.jpg', 'Spies in Disguise', '47.872', '2019-12-04', 7.7, '2093', '[\'Animation\', \'Action\', \'Adventure\', \'Comedy\', \'Family\']', 'Super spy Lance Sterling and scientist Walter Beckett are almost exact opposites. Lance is smooth, suave and debonair. Walter is… not. But what Walter lacks in social skills he makes up for in smarts and invention, creating the awesome gadgets Lance uses on his epic missions. But when events take an unexpected turn, Walter and Lance suddenly have to rely on each other in a whole new way.'),
(1231, '47933', 'en', 'https://image.tmdb.org/t/p/w500/9S50foUIYGwiNPWOxi1WJF6IPwI.jpg', 'Independence Day: Resurgence', '53.903', '2016-06-22', 5.2, '5050', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'We always knew they were coming back. Using recovered alien technology, the nations of Earth have collaborated on an immense defense program to protect the planet. But nothing can prepare us for the aliens’ advanced and unprecedented force. Only the ingenuity of a few brave men and women can bring our world back from the brink of extinction.'),
(1232, '41733', 'en', 'https://image.tmdb.org/t/p/w500/sBxWS09pOOyXZ0dcnqfqqCAQGan.jpg', 'Due Date', '49.846', '2010-11-04', 6.3, '4365', '[\'Comedy\', \'Drama\']', 'Peter Highman must scramble across the US in five days to be present for the birth of his first child. He gets off to a bad start when his wallet and luggage are stolen, and put on the \'no-fly\' list. Peter embarks on a terrifying journey when he accepts a ride from an actor.'),
(1233, '449443', 'en', 'https://image.tmdb.org/t/p/w500/4cahr8gscRMjxbOJ8PddKGjH5NB.jpg', 'Den of Thieves', '49.404', '2018-01-18', 6.7, '2153', '[\'Action\', \'Thriller\', \'Crime\']', 'A gritty crime saga which follows the lives of an elite unit of the LA County Sheriff\'s Dept. and the state\'s most successful bank robbery crew as the outlaws plan a seemingly impossible heist on the Federal Reserve Bank.'),
(1234, '623491', 'en', 'https://image.tmdb.org/t/p/w500/imy1OoT1xddt2kqw6hhc4v01e8i.jpg', 'The Babysitter: Killer Queen', '45.734', '2020-09-10', 6.6, '957', '[\'Comedy\', \'Horror\']', 'Two years after defeating a satanic cult led by his babysitter Bee, Cole\'s trying to forget his past and focus on surviving high school. But when old enemies unexpectedly return, Cole will once again have to outsmart the forces of evil.'),
(1235, '559957', 'zh', 'https://image.tmdb.org/t/p/w500/qPqlhcsiu7U20aQu2r6wI4RgsnE.jpg', '上海堡垒', '59.209', '2019-08-09', 5.5, '77', '[\'Science Fiction\', \'War\']', 'Set in the future, the city of Shanghai battle to defend itself against an ongoing attack by an alien force that has attacked and laid siege to numerous cities around the globe in it\'s quest to harvest a hidden energy only found on earth.'),
(1236, '439157', 'ja', 'https://dosbg3xlm0x1t.cloudfront.net/images/items/9784088806969/1200/9784088806969.jpg', 'ドラゴンボールZ 復活の「F」 “未来”トランクス特別編', '59.205', '2016-08-10', 7.6, '79', '[\'Animation\']', 'Extra scenes of the movie Resurrection F, where future Trunks remembers the battle of Goku againts Freezer.'),
(1237, '716612', 'en', 'https://image.tmdb.org/t/p/w500/7GcqdBKaMM9BWXWN07BirBMkcBF.jpg', 'Spencer', '54.036', '2021-11-05', 7.2, '16', '[\'Drama\']', 'During her Christmas holidays with the royal family at the Sandringham estate in Norfolk, England, Diana decides to leave her marriage to Prince Charles.'),
(1238, '652', 'en', 'https://image.tmdb.org/t/p/w500/51auXjXepW1zblzhaN7CAhwvf5i.jpg', 'Troy', '56.356', '2004-05-03', 7.1, '8023', '[\'Adventure\', \'History\', \'War\']', 'In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnom to help him get her back. Agamemnon sees this as an opportunity for power. So they set off with 1,000 ships holding 50,000 Greeks to Troy. With the help of Achilles, the Greeks are able to fight the never before defeated Trojans.'),
(1239, '257445', 'en', 'https://image.tmdb.org/t/p/w500/aeZT9pqEgrmXOGdESFkAuVjX6kw.jpg', 'Goosebumps', '43.012', '2015-08-05', 6.3, '3075', '[\'Adventure\', \'Horror\', \'Comedy\']', 'After moving to a small town, Zach Cooper finds a silver lining when he meets next door neighbor Hannah, the daughter of bestselling Goosebumps series author R.L. Stine. When Zach unintentionally unleashes real monsters from their manuscripts and they begin to terrorize the town, it’s suddenly up to Stine, Zach and Hannah to get all of them back in the books where they belong.'),
(1240, '331482', 'en', 'https://image.tmdb.org/t/p/w500/yn5ihODtZ7ofn8pDYfxCmxh8AXI.jpg', 'Little Women', '51.021', '2019-12-25', 7.9, '4229', '[\'Drama\', \'Romance\']', 'Four sisters come of age in America in the aftermath of the Civil War.'),
(1241, '6477', 'en', 'https://image.tmdb.org/t/p/w500/3s3WvpKPXXeKAPketDDqiQTi20S.jpg', 'Alvin and the Chipmunks', '48.737', '2007-12-13', 5.8, '3515', '[\'Comedy\', \'Family\', \'Fantasy\', \'Animation\']', 'A struggling songwriter named Dave Seville finds success when he comes across a trio of singing chipmunks: mischievous leader Alvin, brainy Simon, and chubby, impressionable Theodore.'),
(1242, '91586', 'en', 'https://image.tmdb.org/t/p/w500/w5JjiB3O1CLDXbTJe1QpU5RHmlU.jpg', 'Insidious: Chapter 2', '48.734', '2013-09-12', 6.7, '3219', '[\'Horror\', \'Thriller\']', 'The haunted Lambert family seeks to uncover the mysterious childhood secret that has left them dangerously connected to the spirit world.'),
(1243, '204082', 'en', 'https://image.tmdb.org/t/p/w500/xcFLM44jgl015wLe7lWC1C1bEEM.jpg', 'Homefront', '40.781', '2013-11-12', 7, '2695', '[\'Action\', \'Thriller\']', 'Phil Broker is a former DEA agent who has gone through a crisis after his action against a biker gang went horribly wrong and it cost the life of his boss\' son. He is recently widowed and is left with a 9-years-old daughter, Maddy. He decides to quit the turbulent and demanding life of thrill for Maddy\'s sake and retires to a small town. His daughter fights off a boy who was bullying her at school and this sets in motion a round of events that end in his direct confrontation with the local Meth drug lord. His past history with the biker gang also enters the arena, making matters more complex. But he has a mission in his mind to protect his daughter and he is ready to pay any cost that it demands.'),
(1244, '11361', 'en', 'https://image.tmdb.org/t/p/w500/rYvP6yMXCIVHnkVtwGaAXFmpzkB.jpg', 'Halloween 5: The Revenge of Michael Myers', '45.474', '1989-10-12', 5.4, '786', '[\'Horror\', \'Thriller\']', 'Presumed dead after a shoot-out with the Haddonfield police, Michael Myers is secretly nursed back to health -- and returns a year later to kill again and once more targets his young niece, Jamie. Jamie is now recovering in the local children\'s hospital after attacking her stepmother and losing her voice. Her mental link with her evil uncle may be the key to uprooting her family tree.'),
(1245, '10679', 'en', 'https://image.tmdb.org/t/p/w500/hVDJM29BSbET4FzI24xLuWSmDUR.jpg', 'Iron Sky', '46.325', '2012-03-10', 5.7, '1216', '[\'Action\', \'Comedy\', \'Science Fiction\']', 'In the last moments of World War II, a secret Nazi space program evaded destruction by fleeing to the Dark Side of the Moon. During 70 years of utter secrecy, the Nazis construct a gigantic space fortress with a massive armada of flying saucers.'),
(1246, '406997', 'en', 'https://image.tmdb.org/t/p/w500/sONh3LYGFcVDTy8pm1tbSOB13Li.jpg', 'Wonder', '42.472', '2017-11-13', 8.2, '6549', '[\'Drama\', \'Family\']', 'The story of August Pullman – a boy with facial differences – who enters fifth grade, attending a mainstream elementary school for the first time.'),
(1247, '601666', 'en', 'https://image.tmdb.org/t/p/w500/gKnhEsjNefpKnUdAkn7INzIFLSu.jpg', 'I Care a Lot', '47.191', '2020-09-12', 6.7, '1757', '[\'Comedy\', \'Crime\', \'Thriller\']', 'A court-appointed legal guardian defrauds her older clients and traps them under her care. But her latest mark comes with some unexpected baggage.'),
(1248, '667141', 'en', 'https://image.tmdb.org/t/p/w500/y40lD9qpKxnzsdKqAA1TiEKX5gb.jpg', '12 Hour Shift', '47.832', '2020-10-02', 5.4, '143', '[\'Thriller\', \'Horror\', \'Comedy\', \'Crime\']', 'It\'s 1999 and over the course of one 12-hour shift at an Arkansas hospital, a junkie nurse, her scheming cousin and a group of black market organ-trading criminals start a heist that could lead to their collective demise.'),
(1249, '499701', 'en', 'https://image.tmdb.org/t/p/w500/xvYCZ740XvngXK0FNeSNVTJJJ5v.jpg', 'Dora and the Lost City of Gold', '50.257', '2019-08-08', 6.8, '1307', '[\'Adventure\', \'Comedy\', \'Family\']', 'Dora, a girl who has spent most of her life exploring the jungle with her parents, now must navigate her most dangerous adventure yet: high school. Always the explorer, Dora quickly finds herself leading Boots (her best friend, a monkey), Diego, and a rag tag group of teens on an adventure to save her parents and solve the impossible mystery behind a lost Inca civilization.'),
(1250, '128748', 'en', 'https://image.tmdb.org/t/p/w500/e7AvQaI3k60HGGEso1t3KNjTuDW.jpg', 'Curse of the Blair Witch', '49.357', '1999-07-11', 6.2, '69', '[\'Documentary\', \'Horror\', \'Thriller\']', 'Curse of the Blair Witch is a documentary about the Blair Witch legend and the three filmmakers who disappeared in October of 1999. It first aired on the Sci-Fi Channel on July 11, 1999 as a promotional prelude to the release of The Blair Witch Project on July 30, 1999.'),
(1251, '670428', 'en', 'https://image.tmdb.org/t/p/w500/28Y3pxfkRZMhLsw4if6e3J0HD7Q.jpg', 'Psycho Goreman', '45.047', '2021-01-22', 6.2, '176', '[\'Science Fiction\', \'Comedy\', \'Horror\']', 'Siblings Mimi and Luke unwittingly resurrect an ancient alien overlord. Using a magical amulet, they force the monster to obey their childish whims, and accidentally attract a rogues’ gallery of intergalactic assassins to small-town suburbia.'),
(1252, '37211', 'en', 'https://image.tmdb.org/t/p/w500/cXUQuHnNBxFSZAmYfogMfrcvMk7.jpg', 'Scooby-Doo! and the Reluctant Werewolf', '49.981', '1988-11-13', 7.3, '225', '[\'Animation\', \'Comedy\', \'Family\', \'Mystery\', \'TV Movie\']', 'Shaggy is turned into a werewolf, and it\'s up to Scooby, Scrappy and Shaggy\'s girlfriend to help him win a race against other monsters, and become human again.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1253, '118365', 'en', 'https://image.tmdb.org/t/p/w500/zqdqwnBNPWISYr0isDRLV2bhmMH.jpg', 'Moses, Prince of Egypt', '47.095', '2000-01-01', 5.5, '4', '[]', 'At birth, Moses, a Hebrew baby is abandoned on the Nile by his mother. The wife of Pharaoh finds the small and decides to raise him as his own son. Moses grows Egyptian with his brother, Ramses, between games and pranks. When Moses became a man discovers the truth about his birth and, confused, flees into the wilderness. There he joins a group of nomadic Hebrews and is pastor. One day, God appears as a burning bush and entrusted with the mission to free the Hebrew slaves that holds the Pharaoh. Moses returns to Egypt to demand the release of his people and found that Rameses has become the new Pharaoh.'),
(1254, '36557', 'en', 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', 'Casino Royale', '74.368', '2006-11-14', 7.5, '8414', '[\'Adventure\', \'Action\', \'Thriller\']', 'Le Chiffre, a banker to the world\'s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.'),
(1255, '599281', 'en', 'https://image.tmdb.org/t/p/w500/5hmaACPJfI2M0v38DeltW3dSggT.jpg', 'Fear of Rain', '40.276', '2021-02-12', 7.2, '299', '[\'Thriller\', \'Horror\', \'Drama\']', 'A teenage girl living with schizophrenia begins to suspect her neighbor has kidnapped a child. Her parents try desperately to help her live a normal life, without exposing their own tragic secrets, and the only person who believes her is Caleb – a boy she isn’t even sure exists.'),
(1256, '68735', 'en', 'https://image.tmdb.org/t/p/w500/nZIIOs06YigBnvmlJ2hxZeA8eTO.jpg', 'Warcraft', '55.715', '2016-05-25', 6.3, '5513', '[\'Action\', \'Adventure\', \'Fantasy\']', 'The peaceful realm of Azeroth stands on the brink of war as its civilization faces a fearsome race of invaders: orc warriors fleeing their dying home to colonize another. As a portal opens to connect the two worlds, one army faces destruction and the other faces extinction. From opposing sides, two heroes are set on a collision course that will decide the fate of their family, their people, and their home.'),
(1257, '201088', 'en', 'https://image.tmdb.org/t/p/w500/7zu6HPnKPjNA7NuR4DGRdaH0PdX.jpg', 'Blackhat', '48.872', '2015-01-13', 5.4, '1598', '[\'Crime\', \'Thriller\', \'Action\']', 'A man is released from prison to help American and Chinese authorities pursue a mysterious cyber criminal. The dangerous search leads them from Chicago to Hong Kong.'),
(1258, '9792', 'en', 'https://image.tmdb.org/t/p/w500/2eJL1Ccr1FN3dm9OSDwyd8uaX1b.jpg', 'The Hills Have Eyes', '50.945', '2006-03-10', 6.4, '2186', '[\'Horror\', \'Thriller\']', 'Based on Wes Craven\'s 1977 suspenseful cult classic, The Hills Have Eyes is the story of a family road trip that goes terrifyingly awry when the travelers become stranded in a government atomic zone. Miles from nowhere, the Carter family soon realizes the seemingly uninhabited wasteland is actually the breeding ground of a blood-thirsty mutant family...and they are the prey.'),
(1259, '13596', 'en', 'https://image.tmdb.org/t/p/w500/hCHc6v0XIggcRlkvWkbXCDejKYL.jpg', 'My Best Friend\'s Girl', '52.892', '2008-09-19', 5.6, '552', '[\'Romance\', \'Comedy\']', 'When Dustin\'s girlfriend, Alexis, breaks up with him, he employs his best buddy, Tank, to take her out on the worst rebound date imaginable in the hopes that it will send her running back into his arms. But when Tank begins to really fall for Alexis, he finds himself in an impossible position.'),
(1260, '272', 'en', 'https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', 'Batman Begins', '50.492', '2005-06-10', 7.7, '16797', '[\'Action\', \'Crime\', \'Drama\']', 'Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.'),
(1261, '382190', 'ja', 'https://image.tmdb.org/t/p/w500/4hdbuM6qBrHH0hX4sD8pNsXmalm.jpg', 'ポケモン・ザ・ムービーXY&Z ボルケニオンと機巧のマギアナ', '46.857', '2016-07-16', 6.5, '97', '[\'Family\', \'Adventure\', \'Animation\', \'Fantasy\', \'Science Fiction\']', 'Ash meets the Mythical Pokémon Volcanion when it crashes down from the sky, creating a cloud of dust—and a mysterious force binds the two of them together! Volcanion despises humans and tries to get away, but it’s forced to drag Ash along as it continues its rescue mission. They arrive in a city of cogs and gears, where a corrupt official has stolen the ultimate invention: the Artificial Pokémon Magearna, created 500 years ago. He plans to use its mysterious power to take control of this mechanical kingdom! Can Ash and Volcanion work together to rescue Magearna? One of the greatest battles in Pokémon history is about to unfold!'),
(1262, '424694', 'en', 'https://image.tmdb.org/t/p/w500/lHu1wtNaczFPGFDTrjCSzeLPTKN.jpg', 'Bohemian Rhapsody', '55.553', '2018-10-24', 8, '13830', '[\'Music\', \'Drama\', \'History\']', 'Singer Freddie Mercury, guitarist Brian May, drummer Roger Taylor and bass guitarist John Deacon take the music world by storm when they form the rock \'n\' roll band Queen in 1970. Hit songs become instant classics. When Mercury\'s increasingly wild lifestyle starts to spiral out of control, Queen soon faces its greatest challenge yet – finding a way to keep the band together amid the success and excess.'),
(1263, '400136', 'ja', 'https://image.tmdb.org/t/p/w500/kdiMtgjWXEH9QZ85hgmWaSwshjf.jpg', 'バイオハザード ヴェンデッタ', '46.897', '2017-05-27', 6.9, '700', '[\'Horror\', \'Adventure\', \'Mystery\', \'Animation\', \'Action\', \'Science Fiction\']', 'BSAA Chris Redfield enlists the help of government agent Leon S. Kennedy and Professor Rebecca Chambers from Alexander Institute of Biotechnology to stop a death merchant with a vengeance from spreading a deadly virus in New York.'),
(1264, '550776', 'en', 'https://image.tmdb.org/t/p/w500/qbJEzCzEKDHPZDiRvSSBiYEKaAH.jpg', 'Believe Me: The Abduction of Lisa McVey', '40.147', '2018-09-30', 8.2, '250', '[\'Drama\', \'TV Movie\']', 'On the night she plans on taking her own life, 17-year-old \'Lisa McVey\' is kidnapped and finds herself fighting to stay alive and manages to be a victim of rape. She manages to talk her attacker into releasing her, but when she returns home, no one believes her story except for one detective, who suspects she was abducted by a serial killer. Based on horrifying true events.'),
(1265, '13207', 'en', 'https://image.tmdb.org/t/p/w500/uGGpnWHOmWTARVN9wbC1nPxNgps.jpg', 'Friday the 13th', '45.43', '2009-02-11', 5.8, '1890', '[\'Horror\']', 'A group of young adults visit a boarded up campsite named Crystal Lake where they soon encounter the mysterious Jason Voorhees and his deadly intentions.'),
(1266, '818659', 'pt', 'https://image.tmdb.org/t/p/w500/iuCYKGaC9k4FVWA60ECl3rUQut2.jpg', 'Carnaval', '50.82', '2021-06-02', 5.3, '51', '[\'Comedy\']', 'After a breakup, an influencer takes her friends on a free trip to Bahia\'s vibrant Carnival, where she learns life\'s not just about social media likes.'),
(1267, '497', 'en', 'https://image.tmdb.org/t/p/w500/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', 'The Green Mile', '54.523', '1999-12-10', 8.5, '12992', '[\'Fantasy\', \'Drama\', \'Crime\']', 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people\'s ailments. When the cell block\'s head guard, Paul Edgecomb, recognizes Coffey\'s miraculous gift, he tries desperately to help stave off the condemned man\'s execution.'),
(1268, '346651', 'en', 'https://image.tmdb.org/t/p/w500/m0OCqNmVudMtbGlv4iTcyYrbp9m.jpg', 'Pandemic', '51.18', '2016-02-26', 5, '248', '[\'Action\', \'Science Fiction\', \'Horror\']', 'After a virus of epic proportions overwhelms the planet—with more infected than uninfected—humanity is losing its grip on survival and its only hope is finding a cure and keeping the infected contained. Lauren, a doctor, arrives in Los Angeles with her crack team to lead the hunt for uncontaminated civilian survivors, but nothing can prepare them for the blood-soaked mayhem they witness as they head into the Californian streets where everything is considered a trap.'),
(1269, '675490', 'en', 'https://image.tmdb.org/t/p/w500/Xt37loPwHjipC1qaCbfLfDcFu4.jpg', 'The Unfamiliar', '46.85', '2020-08-21', 6.1, '63', '[\'Thriller\', \'Horror\']', 'A British Army doctor comes back from a war, thinking that she has PTSD only to discover that there is a more daunting malevolence at work making the life that she knew unfamiliar.'),
(1270, '845422', 'es', 'https://image.tmdb.org/t/p/w500/fGbVBL4D0KmJSv7J5cZxsiZM2qL.jpg', 'Fondeados', '48.72', '2021-07-23', 6.5, '21', '[\'Comedy\']', 'While blind drunk, two unemployed millennials entrepreneurs drunkenly post a video pitch about their revolutionary app to a crowdfunding site. When the app catches fire and they accidentally raise millions of dollars they actually have to create the app.'),
(1271, '50544', 'en', 'https://image.tmdb.org/t/p/w500/nKhhDFCdzxeJ3GUunQ570LDpUkz.jpg', 'Friends with Benefits', '54.871', '2011-07-21', 6.7, '6520', '[\'Romance\', \'Comedy\']', 'Dylan and Jamie think it\'s going to be easy to add the simple act of sex to their friendship, despite what Hollywood romantic comedies would have them believe. They soon discover however that getting physical really does always lead to complications.'),
(1272, '138832', 'en', 'https://image.tmdb.org/t/p/w500/qF2LJ0jwWrtXSuT4AFD5OS2IqaT.jpg', 'We\'re the Millers', '46.619', '2013-08-07', 6.8, '7193', '[\'Comedy\', \'Crime\']', 'A veteran pot dealer creates a fake family as part of his plan to move a huge shipment of weed into the U.S. from Mexico.'),
(1273, '23437', 'en', 'https://image.tmdb.org/t/p/w500/wGTpGGRMZmyFCcrY2YoxVTIBlli.jpg', 'A Nightmare on Elm Street', '51.063', '2010-04-30', 5.5, '2105', '[\'Horror\', \'Mystery\', \'Thriller\']', 'The film that brings back horror icon Freddy Krueger as a darker and more sinister character than ever before. While Freddy is on the prowl a group of teenagers being stalked soon learn they all have a common factor making them targets for this twisted killer.'),
(1274, '287075', 'en', 'https://m.media-amazon.com/images/M/MV5BNmJmMzVmOWQtMDgxZC00NTdiLWEzZWUtZDhkYmY1YzNiMGU3XkEyXkFqcGc@._V1_.jpg', 'Double Mama', '38.973', '2013-02-27', 6, '2', '[]', 'Double mama has a reputation for indiscriminately tackling anyone who dares to cross her. This allows her mischievous son to freely terrorise the villagers.'),
(1275, '9100', 'en', 'https://image.tmdb.org/t/p/w500/8bW2RdRkloYtEPhbQZN4wcdmJP4.jpg', 'The Craft', '73.766', '1996-05-03', 6.7, '1309', '[\'Fantasy\', \'Horror\', \'Drama\', \'Thriller\']', 'A Catholic school newcomer falls in with a clique of teen witches who wield their powers against all who dare to cross them -- be they teachers, rivals or meddlesome parents.'),
(1276, '524216', 'en', 'https://image.tmdb.org/t/p/w500/5WXeYnezavNI6hXH74aQYv6yFzj.jpg', 'The Mortuary Collection', '46.874', '2019-09-21', 6.8, '246', '[\'Fantasy\', \'Horror\']', 'In the phantasmagorical town of Raven\'s End, a misguided young girl takes refuge in a decrepit old mortuary. The eccentric undertaker chronicles the strange history of the town through a series of twisted tales, each more terrifying than the last, but the young girl\'s world is unhinged when she discovers that the final story... is her own.'),
(1277, '291870', 'en', 'https://image.tmdb.org/t/p/w500/k0Lz1TfSlbcQthQKYGwE7blDfwN.jpg', 'Dirty Grandpa', '51.356', '2016-01-20', 5.9, '3626', '[\'Comedy\']', 'Jason Kelly is one week away from marrying his boss\'s uber-controlling daughter, putting him on the fast track for a partnership at the law firm. However, when the straight-laced Jason is tricked into driving his foul-mouthed grandfather, Dick, to Daytona for spring break, his pending nuptials are suddenly in jeopardy. Between riotous frat parties, bar fights, and an epic night of karaoke, Dick is on a quest to live his life to the fullest and bring Jason along for the ride.'),
(1278, '9904', 'en', 'https://image.tmdb.org/t/p/w500/sxqzaOto1qyUseSg6YpIP9Su5lp.jpg', 'The Wild', '53.599', '2006-03-06', 5.5, '790', '[\'Family\', \'Animation\']', 'An adolescent lion is accidentally shipped from the New York Zoo to Africa. Now running free, his zoo pals must put aside their differences to help bring him back.'),
(1279, '9836', 'en', 'https://image.tmdb.org/t/p/w500/za41IHkj6LnkilfTzv5B2qmthKD.jpg', 'Happy Feet', '58.189', '2006-11-16', 6.1, '4007', '[\'Animation\', \'Comedy\', \'Family\']', 'Into the world of the Emperor Penguins, who find their soul mates through song, a penguin is born who cannot sing. But he can tap dance something fierce!'),
(1280, '16910', 'ja', 'https://image.tmdb.org/t/p/w500/itKMldwL6uhUZYO3X78NOFU4zzO.jpg', '劇場版 NARUTO -ナルト- 大激突!幻の地底遺跡だってばよ', '48.838', '2005-08-06', 6.6, '238', '[\'Animation\', \'Adventure\', \'Fantasy\']', 'Naruto, Shikamaru, and Sakura are executing their mission of delivering a lost pet to a certain village. However, right in the midst of things, troops led by the mysterious knight, Temujin, attack them. In the violent battle, the three become separated. Temujin challenges Naruto to a fight and at the end of the fierce battle, both fall together from a high cliff...'),
(1281, '641960', 'en', 'https://image.tmdb.org/t/p/w500/uaJmqZxwAsdFLLjPGH5DzIEnbpj.jpg', 'Four Good Days', '45.263', '2021-04-30', 7.1, '43', '[\'Drama\']', 'A mother helps her daughter work through four crucial days of recovery from substance abuse.'),
(1282, '58233', 'en', 'https://image.tmdb.org/t/p/w500/zDbrU0eSnRGh5gHc1iqTACTNNyT.jpg', 'Johnny English Reborn', '46.326', '2011-09-15', 6.2, '2559', '[\'Crime\', \'Adventure\', \'Action\', \'Comedy\', \'Thriller\']', 'The most prominent heads of state in the world begin gathering for a conference that could have a major impact on global politics. When MI-7 receives word that the Chinese premier has become the target of some high-powered killers, it falls on Johnny English to save the day. Armed with the latest high-tech weaponry and gadgets that would make even James Bond jealous, the once-disgraced agent uncovers evidence of a massive conspiracy involving some of the world\'s most powerful organisations, and vows to redeem his tarnished reputation by stopping the killers before they can strike.'),
(1283, '16523', 'en', 'https://image.tmdb.org/t/p/w500/sDFV9VEjwTUWF1s5sjOllsb70jk.jpg', 'Where the Wild Things Are', '47.07', '2009-10-16', 6.5, '1428', '[\'Family\', \'Fantasy\', \'Science Fiction\', \'Drama\']', 'Max imagines running away from his mom and sailing to a far-off land where large talking beasts—Ira, Carol, Douglas, the Bull, Judith and Alexander—crown him as their king, play rumpus, build forts and discover secret hideaways.'),
(1284, '283366', 'en', 'https://image.tmdb.org/t/p/w500/CIlbMFOfYDj0MP23hsIYhFGrL6.jpg', 'Miss Peregrine\'s Home for Peculiar Children', '51.026', '2016-09-27', 6.8, '8375', '[\'Drama\', \'Fantasy\', \'Adventure\', \'Family\']', 'A teenager finds himself transported to an island where he must help protect a group of orphans with special powers from creatures intent on destroying them.'),
(1285, '308531', 'en', 'https://image.tmdb.org/t/p/w500/euVaCiCWz3AALcQXHT6aUqdGUo6.jpg', 'Teenage Mutant Ninja Turtles: Out of the Shadows', '44.855', '2016-06-01', 6, '2726', '[\'Action\', \'Adventure\', \'Comedy\', \'Family\', \'Science Fiction\']', 'After supervillain Shredder escapes custody, he joins forces with mad scientist Baxter Stockman and two dimwitted henchmen, Bebop and Rocksteady, to unleash a diabolical plan to take over the world. As the Turtles prepare to take on Shredder and his new crew, they find themselves facing an even greater evil with similar intentions: the notorious Krang.'),
(1286, '350640', 'es', 'https://image.tmdb.org/t/p/w500/57zuiN6e8D82p15HsHV9JxwKxhJ.jpg', 'Sexo limpio', '48.463', '2015-07-19', 7.8, '12', '[\'Comedy\']', 'Mariana has an obsessive cleaning habit. After starting a troubled relationship with Enrique. She must accept that sex is dirty and  impulsive.'),
(1287, '10137', 'en', 'https://image.tmdb.org/t/p/w500/362lcwTJlNyAhitTlp2UraECISR.jpg', 'Stuart Little', '51.195', '1999-12-17', 6, '3418', '[\'Family\', \'Animation\', \'Fantasy\', \'Comedy\']', 'The adventures of a heroic and debonair stalwart mouse named Stuart Little with human qualities, who faces some comic misadventures while searching for his lost bird friend and living with a human family as their child.'),
(1288, '228165', 'en', 'https://image.tmdb.org/t/p/w500/2WDmjUlSAPlA27i2OwEC7sRTFw3.jpg', 'The SpongeBob Movie: Sponge Out of Water', '54.737', '2015-01-28', 6.1, '1865', '[\'Family\', \'Adventure\', \'Comedy\', \'Fantasy\', \'Animation\']', 'Burger Beard is a pirate who is in search of the final page of a magical book that makes any evil plan he writes in it come true, which happens to be the Krabby Patty secret formula. When the entire city of Bikini Bottom is put in danger, SpongeBob, Patrick, Mr. Krabs, Squidward, Sandy, and Plankton need to go on a quest that takes them to the surface. In order to get back the recipe and save their city, the gang must retrieve the book and transform themselves into superheroes.'),
(1289, '20829', 'en', 'https://image.tmdb.org/t/p/w500/gEYKD5cWCBGg8Za3hhwDBk3gEsP.jpg', 'Funny People', '50.834', '2009-07-30', 5.9, '967', '[\'Comedy\', \'Drama\']', 'Famous and wealthy funnyman George Simmons doesn\'t give much thought to how he treats people until a doctor delivers stunning health news, forcing George to reevaluate his priorities with a little help from aspiring stand-up comic Ira.'),
(1290, '317960', 'en', 'https://image.tmdb.org/t/p/w500/grma5z8uPKan8IR4DdtXm1g2BWz.jpg', 'Viking Quest', '48.459', '2014-10-07', 4.4, '21', '[\'Action\', \'Adventure\', \'Fantasy\', \'TV Movie\']', 'Erick, a young Viking warrior, joins forces with a rival clan in order to rescue a kidnapped princess from the great Midgard Serpent. It\'s a perilous task with a risk far greater than merely their own lives; by rescuing the princess, they might cause Ragnarök - the end of the world.'),
(1291, '127521', 'en', 'https://image.tmdb.org/t/p/w500/7yEbEUrOsAS0d5DW1OqtvSpmRQv.jpg', '6 Bullets', '45.325', '2012-09-11', 6, '239', '[\'Thriller\', \'Action\', \'Crime\']', 'An ex-mercenary known for finding missing children is hired by a mixed martial arts fighter whose daughter has been kidnapped.'),
(1292, '595149', 'en', 'https://image.tmdb.org/t/p/w500/8F9xUvb1JMWUMkFV2Yq3aiueAbq.jpg', 'Death of Me', '43.116', '2020-10-02', 4.9, '165', '[\'Horror\', \'Mystery\']', 'A couple on holiday on a remote South Pacific island awaken one morning with a hang over and no recollection of what transpired. When playing back a video of the previous night, they see they participated in a local ritual that somehow ends with him murdering her.'),
(1293, '300668', 'en', 'https://image.tmdb.org/t/p/w500/4YRplSk6BhH6PRuE9gfyw9byUJ6.jpg', 'Annihilation', '45.424', '2018-02-22', 6.4, '6786', '[\'Science Fiction\', \'Horror\']', 'A biologist signs up for a dangerous, secret expedition into a mysterious zone where the laws of nature don\'t apply.'),
(1294, '16119', 'en', 'https://image.tmdb.org/t/p/w500/9QzKXbQfPp59iZ3rwnkKEAkPaXx.jpg', 'Cinderella III: A Twist in Time', '50.31', '2007-02-06', 6.5, '976', '[\'Animation\', \'Romance\', \'Family\', \'Fantasy\']', 'When Lady Tremaine steals the Fairy Godmother\'s wand and changes history, it\'s up to Cinderella to restore the timeline and reclaim her prince.'),
(1295, '9078', 'en', 'https://image.tmdb.org/t/p/w500/7lyeeuhGAJSNXYEW34S8mJ1bwI8.jpg', 'The Sword in the Stone', '49.258', '1963-12-25', 7.3, '3043', '[\'Animation\', \'Family\']', 'Wart is a young boy who aspires to be a knight\'s squire. On a hunting trip he falls in on Merlin, a powerful but amnesiac wizard who has plans for him beyond mere squiredom. He starts by trying to give him an education, believing that once one has an education, one can go anywhere. Needless to say, it doesn\'t quite work out that way.'),
(1296, '9488', 'en', 'https://image.tmdb.org/t/p/w500/z8pfWCk6SlxxDLXXQdUHdxF5dwJ.jpg', 'Spy Kids 2: The Island of Lost Dreams', '47.007', '2002-08-07', 5.6, '1674', '[\'Action\', \'Adventure\', \'Family\', \'Comedy\']', 'Exploring the further adventures of Carmen and Juni Cortez, who have now joined the family spy business as Level 2 OSS agents. Their new mission is to save the world from a mad scientist living on a volcanic island populated by an imaginative menagerie of creatures. On this bizarre island, none of the Cortez\'s gadgets work and they must rely on their wits--and each other--to survive and save the day.'),
(1297, '646696', 'id', 'https://image.tmdb.org/t/p/w500/gXB4zSApX4cS5MaMNWkKDLw0O9U.jpg', 'Mariposa', '53.922', '2020-03-12', 7.2, '3', '[\'Drama\', \'Romance\']', 'New student Acha falls for Iqbal, a high-achieving student who\'s torn between love and family pressure.'),
(1298, '71469', 'en', 'https://image.tmdb.org/t/p/w500/5Ao4qAFbjP7fcFOOdMNvQEnl0Yr.jpg', 'The Darkest Hour', '47.505', '2011-12-22', 5.3, '1125', '[\'Horror\', \'Action\', \'Thriller\', \'Science Fiction\']', 'In Moscow, five young people lead the charge against an alien race which has attacked Earth via our power supply.'),
(1299, '552687', 'ja', 'https://image.tmdb.org/t/p/w500/8Im0EqH9PmgurlbmZ0P2xSPTclu.jpg', 'ヲタクに恋は難しい', '51.684', '2020-02-07', 7.1, '37', '[\'Comedy\', \'Romance\']', 'An effervescent musical about one of the most unlikely couples seen on screen: two Otaku intent on hiding their nerdiness from their colleagues!'),
(1300, '575803', 'nl', 'https://image.tmdb.org/t/p/w500/pjeM7XdPnTuA7DszfSEA0ANsSmn.jpg', 'Mijn bijzonder rare week met Tess', '47.714', '2019-07-03', 7.4, '25', '[\'Drama\']', 'As the youngest of the family, Sam is haunted by the notion that someday he could become the last remaining survivor, all alone. On a family vacation at the beach, he meets the unconventional Tess, who carries her own secrets around with her and shows him how the present moment can win out over memories and anxiety about what’s yet to come.'),
(1301, '329865', 'en', 'https://image.tmdb.org/t/p/w500/x2FJsf1ElAgr63Y3PNPtJrcmpoe.jpg', 'Arrival', '48.152', '2016-11-10', 7.6, '14352', '[\'Drama\', \'Science Fiction\', \'Mystery\']', 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.'),
(1302, '42889', 'en', 'https://image.tmdb.org/t/p/w500/krUYZAjEZ5n5GL7tuLoQGfxja0S.jpg', 'The Virginity Hit', '43.446', '2010-09-24', 4.5, '55', '[\'Comedy\']', 'Four guys, one camera, and their experience chronicling the exhilarating and terrifying rite of passage: losing your virginity. As these guys help their buddy get laid, they\'ll have to survive friends with benefits, Internet hookups, even porn stars during an adventure that proves why you will always remember your first time.'),
(1303, '10987', 'en', 'https://image.tmdb.org/t/p/w500/noCnM8nEI2bEDSdKHh0RKbwBwbC.jpg', 'Halloween: The Curse of Michael Myers', '41.443', '1995-09-29', 5.2, '718', '[\'Horror\', \'Thriller\']', 'Six years ago, Michael Myers terrorized the town of Haddonfield, Illinois. He and his niece, Jamie Lloyd, have disappeared. Jamie was kidnapped by a bunch of evil druids who protect Michael Myers. And now, six years later, Jamie has escaped after giving birth to Michael\'s child. She runs to Haddonfield to get Dr. Loomis to help her again.'),
(1304, '615982', 'tr', 'https://image.tmdb.org/t/p/w500/2sQWnbH1sFvA1Ug9Jtm8HBDnL16.jpg', 'Siccîn 6', '46.211', '2019-08-09', 5.9, '30', '[\'Horror\']', 'Turkish villagers (mostly) being under the spell of BLACK MAGIC which is put up on them by a hater in the close or far families that makes them being suffered and trified by the Djins (very Bad Kind of Wicked Devil Among Muslims Coming from Their Holly Book Quran) They have to now look for clues and exorcists to help them run away from it or defeat it.'),
(1305, '594718', 'ru', 'https://image.tmdb.org/t/p/w500/eAUzmhP54bE1vPXaY7FbuZREJlR.jpg', 'Спутник', '54.331', '2020-09-08', 6.5, '408', '[\'Science Fiction\', \'Drama\', \'Horror\']', 'At the height of the Cold War, a Soviet spacecraft crash lands after a mission gone awry, leaving the commander as its only survivor. After a renowned Russian psychologist is brought in to evaluate the commander’s mental state, it becomes clear that something dangerous may have come back to Earth with him…'),
(1306, '169209', 'en', 'https://image.tmdb.org/t/p/w500/uU4zhkZYVfo7MGKPVIYONseusoL.jpg', 'Empire State', '43.992', '2013-09-03', 5.4, '533', '[\'Action\', \'Drama\']', 'After failing to get into the police academy, Chris Potamitis settles for a security guard job with an armoured truck company. After he makes the mistake of mentioning the company\'s lax security to his best friend, He\'s unwittingly drawn into an elaborate scheme to rob the abundant amounts of cash being stored on their premises—resulting in the largest cash heist in U.S.history.'),
(1307, '53182', 'en', 'https://image.tmdb.org/t/p/w500/wYDdWN1McB1Sio4z1dPSkb40Z78.jpg', '300: Rise of an Empire', '47.19', '2014-03-05', 6.1, '5276', '[\'Action\', \'Drama\']', 'Greek general Themistokles attempts to unite all of Greece by leading the charge that will change the course of the war. Themistokles faces the massive invading Persian forces led by mortal-turned-god, Xerxes and Artemesia, the vengeful commander of the Persian navy.'),
(1308, '10588', 'en', 'https://image.tmdb.org/t/p/w500/uYYLz67e5xEQMsY858VSSCDsLU6.jpg', 'The Cat in the Hat', '55.179', '2003-11-21', 5.3, '1242', '[\'Family\', \'Fantasy\']', 'Conrad and Sally Walden are home alone with their pet fish. It is raining outside, and there is nothing to do. Until The Cat in the Hat walks in the front door. He introduces them to their imagination, and at first it\'s all fun and games, until things get out of hand, and The Cat must go, go, go, before their parents get back.'),
(1309, '278924', 'en', 'https://image.tmdb.org/t/p/w500/bG3Q6EFcngpPn7uPuQTzTuq9DgV.jpg', 'Mechanic: Resurrection', '56.285', '2016-08-25', 5.9, '2619', '[\'Action\', \'Crime\', \'Thriller\']', 'Arthur Bishop thought he had put his murderous past behind him when his most formidable foe kidnaps the love of his life. Now he is forced to travel the globe to complete three impossible assassinations, and do what he does best, make them look like accidents.'),
(1310, '256591', 'en', 'https://image.tmdb.org/t/p/w500/lOzGWjceYTd0kd5HyX7Ch46O9kh.jpg', 'Focus', '52.926', '2015-02-25', 6.9, '6380', '[\'Romance\', \'Comedy\', \'Crime\', \'Drama\']', 'Nicky, an accomplished con artist, gets romantically involved with his disciple Jess but later ends their relationship. Years later, she returns as a femme fatale to spoil his plans.'),
(1311, '15255', 'en', 'https://image.tmdb.org/t/p/w500/2gMCokqpIJoh6u5o06LlOZWsI3k.jpg', 'Undisputed II: Last Man Standing', '52.17', '2006-04-11', 7.2, '531', '[\'Action\', \'Crime\', \'Thriller\']', 'Sequel to the 2002 film. This time, Heavyweight Champ George \"Iceman\" Chambers (White) is sent to a Russian jail on trumped-up drug charges. In order to win his freedom he must fight against the jailhouse fighting champ Uri Boyka (Adkins) in a battle to the death. This time he is not fighting for a title, he is fighting for his life!'),
(1312, '11036', 'en', 'https://image.tmdb.org/t/p/w500/rNzQyW4f8B8cQeg7Dgj3n6eT5k9.jpg', 'The Notebook', '52.303', '2004-06-25', 7.9, '9112', '[\'Romance\', \'Drama\']', 'An epic love story centered around an older man who reads aloud to a woman with Alzheimer\'s. From a faded notebook, the old man\'s words bring to life the story about a couple who is separated by World War II, and is then passionately reunited, seven years later, after they have taken different paths.'),
(1313, '819500', 'en', 'https://image.tmdb.org/t/p/w500/bYfmSYiibPC54BnG3rV23ByLXRD.jpg', 'Found', '50.689', '2021-10-13', 7.4, '19', '[\'Documentary\']', 'Follows the story of three American teenage girls—each adopted from China—who discover they are blood-related cousins on 23andMe. Their online meeting inspires the young women to confront the burning questions they have about their lost history.'),
(1314, '45612', 'en', 'https://image.tmdb.org/t/p/w500/nTr0lvAzeQmUjgSgDEHTJpnrxTz.jpg', 'Source Code', '49.997', '2011-03-30', 7.3, '6534', '[\'Thriller\', \'Science Fiction\', \'Mystery\']', 'When decorated soldier Captain Colter Stevens wakes up in the body of an unknown man, he discovers he\'s part of a mission to find the bomber of a Chicago commuter train.'),
(1315, '381890', 'zh', 'https://image.tmdb.org/t/p/w500/8YVB8VxQqx3J1FtOVvoHybBKNPS.jpg', '美人鱼', '49.496', '2016-02-08', 6.4, '240', '[\'Comedy\', \'Fantasy\', \'Romance\']', 'A playboy business tycoon, Liu Xuan, purchases the Green Gulf, a wildlife reserve, for a sea reclamation project, and uses sonar technology to get rid of the sea life in the area. Unknown to him, the Green Gulf is the home of merpeople, and the sonar has caused many of them to succumb to illness or die. Xuan\'s business ventures in the area are threatened when he crosses paths with the mermaid, Shan, who is sent to avenge her people.'),
(1316, '274854', 'en', 'https://image.tmdb.org/t/p/w500/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg', 'The Last Witch Hunter', '58.14', '2015-10-21', 5.9, '2981', '[\'Fantasy\', \'Action\', \'Adventure\', \'Science Fiction\']', 'The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.'),
(1317, '821955', 'en', 'https://image.tmdb.org/t/p/w500/xTDaHmglHN8L0aG9FT7ZUVcsA8x.jpg', 'The Right Mom', '72.166', '2021-09-17', 2.5, '2', '[\'Drama\']', 'While writing an article about an abused boy, a woman fights for protect him after she uncovers shocking details.'),
(1318, '402900', 'en', 'https://image.tmdb.org/t/p/w500/MvYpKlpFukTivnlBhizGbkAe3v.jpg', 'Ocean\'s Eight', '46.246', '2018-06-07', 7, '6729', '[\'Crime\', \'Comedy\', \'Action\']', 'Debbie Ocean, a criminal mastermind, gathers a crew of female thieves to pull off the heist of the century at New York\'s annual Met Gala.'),
(1319, '736509', 'en', 'https://image.tmdb.org/t/p/w500/e6hgmD0P133bW5EH1kfhscwXN2a.jpg', 'Intersect', '42.426', '2020-02-12', 5.9, '39', '[\'Horror\', \'Science Fiction\', \'Thriller\']', 'A group of young Miskatonic University scientists invent a time machine, only to learn that they are being manipulated by mysterious, unseen forces from another dimension.'),
(1320, '8277', 'en', 'https://image.tmdb.org/t/p/w500/j7eGbwVb9hTaRFWMlSa7C1OYp3T.jpg', 'American Pie Presents: Beta House', '54.425', '2007-12-10', 5.6, '1484', '[\'Comedy\']', 'Erik, Ryan, and Cooze start college and pledge the Beta House fraternity, presided over by none other than legendary Dwight Stifler. But chaos ensues when a fraternity of geeks threatens to stop the debauchery and the Betas have to make a stand for their right to party.'),
(1321, '637', 'it', 'https://image.tmdb.org/t/p/w500/mfnkSeeVOBVheuyn2lo4tfmOPQb.jpg', 'La vita è bella', '49.521', '1997-12-20', 8.5, '10564', '[\'Comedy\', \'Drama\']', 'A touching story of an Italian book seller of Jewish ancestry who lives in his own little fairy tale. His creative and happy life would come to an abrupt halt when his entire family is deported to a concentration camp during World War II. While locked up he tries to convince his son that the whole thing is just a game.'),
(1322, '663', 'en', 'https://image.tmdb.org/t/p/w500/ku1QdCXOU4ckz3zxLLlis8MIJVm.jpg', 'Saw IV', '46.919', '2007-10-25', 6.2, '2769', '[\'Horror\', \'Thriller\', \'Crime\']', 'Jigsaw and his apprentice Amanda are dead. Now, upon the news of Detective Kerry\'s murder, two seasoned FBI profilers, Agent Strahm and Agent Perez, arrive in the terrified community to assist the veteran Detective Hoffman in sifting through Jigsaw\'s latest grisly remains and piecing together the puzzle. However, when SWAT Commander Rigg is abducted and thrust into a game, the last officer untouched by Jigsaw has but ninety minutes to overcome a series of demented traps and save an old friend...or face the deadly consequences.'),
(1323, '213927', 'en', 'https://image.tmdb.org/t/p/w500/sYYQ9kS6Twvt0UcjxGLmBcq5k11.jpg', 'Born to Race: Fast Track', '46.228', '2014-03-20', 6.4, '67', '[\'Action\']', 'Danny Krueger is a twenty-year old drag racer who plays by his own rules. After winning a scholarship to the prestigious Fast Lane Racing Academy, Danny finds himself competing against some of the fiercest young drivers in the world. Tension soars on and off the track, and a terrible incident leaves Danny without a racing partner. Facing dismissal from the academy, Danny is forced to team up with an old rival. The pair must learn to set aside their differences as they vie for rookie spots on a professional racing team.'),
(1324, '281957', 'en', 'https://image.tmdb.org/t/p/w500/ji3ecJphATlVgWNY0B0RVXZizdf.jpg', 'The Revenant', '46.667', '2015-12-25', 7.5, '15099', '[\'Western\', \'Drama\', \'Adventure\']', 'In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.'),
(1325, '267860', 'en', 'https://image.tmdb.org/t/p/w500/iEbLkYzyiUdOKNK4WNBFyGH7r2Y.jpg', 'London Has Fallen', '71.938', '2016-03-02', 6.1, '3774', '[\'Action\', \'Thriller\']', 'In London for the Prime Minister\'s funeral, Mike Banning discovers a plot to assassinate all the attending world leaders.'),
(1326, '22794', 'en', 'https://image.tmdb.org/t/p/w500/qhOhIKf7QEyQ5dMrRUqs5eTX1Oq.jpg', 'Cloudy with a Chance of Meatballs', '49.857', '2009-09-17', 6.6, '4599', '[\'Animation\', \'Comedy\', \'Family\']', 'Inventor Flint Lockwood creates a machine that makes clouds rain food, enabling the down-and-out citizens of Chewandswallow to feed themselves. But when the falling food reaches gargantuan proportions, Flint must scramble to avert disaster. Can he regain control of the machine and put an end to the wild weather before the town is destroyed?'),
(1327, '694', 'en', 'https://image.tmdb.org/t/p/w500/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg', 'The Shining', '54.548', '1980-05-23', 8.2, '13587', '[\'Horror\', \'Thriller\']', 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren\'t prepared for the madness that lurks within.'),
(1328, '116711', 'en', 'https://image.tmdb.org/t/p/w500/81cSsWzjTfR3cJSqnTiHwy1eyPK.jpg', 'Epic', '47.143', '2013-05-15', 6.5, '2202', '[\'Animation\', \'Adventure\', \'Family\', \'Fantasy\']', 'A teenager finds herself transported to a deep forest setting where a battle between the forces of good and the forces of evil is taking place. She bands together with a rag-tag group characters in order to save their world—and ours.'),
(1329, '55341', 'en', 'https://image.tmdb.org/t/p/w500/pK7ge28ubs45av9aGEbVWW7ZbA8.jpg', 'Jeepers Creepers 3', '41.748', '2017-09-26', 4.8, '584', '[\'Horror\', \'Mystery\', \'Thriller\']', 'Taking place on the last day of the Creeper’s twenty-three-day feeding frenzy, as the skeptical Sergeant Tubbs teams up with a task force hellbent on destroying the Creeper for good. The Creeper fights back in gory glory as its enemies grow closer than ever before to learning the secret of its dark origins.'),
(1330, '11886', 'en', 'https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg', 'Robin Hood', '46.386', '1973-11-08', 7.3, '3490', '[\'Animation\', \'Family\']', 'With King Richard off to the Crusades, Prince John and his slithering minion, Sir Hiss, set about taxing Nottingham\'s citizens with support from the corrupt sheriff - and staunch opposition by the wily Robin Hood and his band of merry men.'),
(1331, '732450', 'en', 'https://image.tmdb.org/t/p/w500/uDhnTtSxU5a8DtZdbbin3aZmkmU.jpg', 'Batman: Soul of the Dragon', '54.496', '2021-01-12', 7, '192', '[\'Animation\', \'Action\', \'Adventure\', \'Crime\', \'Fantasy\']', 'Bruce Wayne faces a deadly menace from his past, with the help of three former classmates: world-renowned martial artists Richard Dragon, Ben Turner and Lady Shiva.'),
(1332, '10439', 'en', 'https://image.tmdb.org/t/p/w500/by4D4Q9NlUjFSEUA1yrxq6ksXmk.jpg', 'Hocus Pocus', '40.429', '1993-07-16', 7, '2008', '[\'Comedy\', \'Family\', \'Fantasy\']', 'After 300 years of slumber, three sister witches are accidentally resurrected in Salem on Halloween night, and it is up to three kids and their newfound feline friend to put an end to the witches\' reign of terror once and for all.'),
(1333, '205584', 'en', 'https://image.tmdb.org/t/p/w500/hzH7fwaTyQNITLo40Hu3R7cVMqv.jpg', 'Gods of Egypt', '51.433', '2016-02-25', 5.6, '3298', '[\'Action\', \'Adventure\', \'Fantasy\']', 'A common thief joins a mythical god on a quest through Egypt.'),
(1334, '377', 'en', 'https://image.tmdb.org/t/p/w500/wGTpGGRMZmyFCcrY2YoxVTIBlli.jpg', 'A Nightmare on Elm Street', '50.175', '1984-11-09', 7.3, '3726', '[\'Horror\']', 'Teenagers in a small town are dropping like flies, apparently in the grip of mass hysteria causing their suicides. A cop\'s daughter, Nancy Thompson, traces the cause to child molester Fred Krueger, who was burned alive by angry parents many years before. Krueger has now come back in the dreams of his killers\' children, claiming their lives as his revenge. Nancy and her boyfriend, Glen, must devise a plan to lure the monster out of the realm of nightmares and into the real world...'),
(1335, '576784', 'ru', 'https://image.tmdb.org/t/p/w500/kY4tmwZaBZitnDRcWFp3Wy197Um.jpg', 'Конёк-горбунок', '36.712', '2021-02-18', 6.2, '16', '[\'Adventure\', \'Fantasy\']', 'Romantic John the Fool and his friend Foal set out on a series of unpredictable adventures in different magical worlds. The two buddies will have to outsmart an evil tyrant king, catch the firebird, and find John’s true love.'),
(1336, '49520', 'en', 'https://image.tmdb.org/t/p/w500/iV6ARQZyGpjygtzFMdWH9U1Lj9x.jpg', 'The Change-Up', '50.91', '2011-08-05', 6.1, '2140', '[\'Comedy\']', 'Dave is a married man with two kids and a loving wife, and Mitch is a single man who is at the prime of his sexual life. One fateful night while Mitch and Dave are peeing in a fountain when lightning strikes, they switch bodies.'),
(1337, '564', 'en', 'https://image.tmdb.org/t/p/w500/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', 'The Mummy', '49.856', '1999-04-16', 6.9, '7037', '[\'Adventure\', \'Action\', \'Fantasy\']', 'Dashing legionnaire Rick O\'Connell stumbles upon the hidden ruins of Hamunaptra while in the midst of a battle to claim the area in 1920s Egypt. It has been over three thousand years since former High Priest Imhotep suffered a fate worse than death as a punishment for a forbidden love—along with a curse that guarantees eternal doom upon the world if he is ever awoken.'),
(1338, '9072', 'en', 'https://image.tmdb.org/t/p/w500/9KzPw1VN0pMBnq1KIqBaLI8LAB7.jpg', 'Little Man', '34.852', '2006-08-31', 5.9, '1252', '[\'Comedy\', \'Crime\']', 'After leaving the prison, the dwarf criminal Calvin Sims joins to his moron brother Percy to steal an expensive huge diamond in a jewelry for the mobster Walken. They are chased by the police, and Calvin hides the stone in the purse of the executive Vanessa Edwards, whose husband Darryl Edwards wants to have a baby. Percy convinces Calvin to dress like a baby and be left in front of the Edwards\'s house to get inside the house and retrieve the diamond. Darryl and Vanessa keep Calvin for the weekend and decide to adopt him, while Walken threatens Darryl to get the stone back.'),
(1339, '1724', 'en', 'https://image.tmdb.org/t/p/w500/gKzYx79y0AQTL4UAk1cBQJ3nvrm.jpg', 'The Incredible Hulk', '50.048', '2008-06-12', 6.2, '9149', '[\'Science Fiction\', \'Action\', \'Adventure\']', 'Scientist Bruce Banner scours the planet for an antidote to the unbridled force of rage within him: the Hulk. But when the military masterminds who dream of exploiting his powers force him back to civilization, he finds himself coming face to face with a new, deadly foe.'),
(1340, '9431', 'en', 'https://image.tmdb.org/t/p/w500/aKkUQ0Zd9TFlqfcMMHFKQBB15wZ.jpg', 'Bordello of Blood', '53.396', '1996-08-16', 5.9, '260', '[\'Horror\', \'Comedy\']', 'Private eye Rafe Guttman is hired by repressed, born-again Katherine to find her missing bad-boy brother. The trail leads him to a whorehouse run by a thousand-year-old vampire and secretly backed by Katherine\'s boss, televangelist Jimmy Current.'),
(1341, '509967', 'en', 'https://image.tmdb.org/t/p/w500/lnWkyG3LLgbbrIEeyl5mK5VRFe4.jpg', '6 Underground', '49.307', '2019-12-10', 6.3, '3420', '[\'Action\', \'Thriller\', \'Comedy\']', 'After faking his death, a tech billionaire recruits a team of international operatives for a bold and bloody mission to take down a brutal dictator.'),
(1342, '24150', 'en', 'https://image.tmdb.org/t/p/w500/xyBX7rFmNB4nM2RBW3042RQPFG2.jpg', 'Halloween II', '41.233', '2009-08-28', 5.4, '983', '[\'Horror\']', 'Laurie Strode struggles to come to terms with her brother Michael\'s deadly return to Haddonfield, Illinois. Meanwhile, Michael prepares for another reunion with his sister.'),
(1343, '84226', 'en', 'https://image.tmdb.org/t/p/w500/zNFCkFmgI4Dnv3UpC0lLM7jWhYU.jpg', 'The Day', '53.884', '2011-09-15', 5.1, '183', '[\'Action\', \'Drama\', \'Horror\', \'Science Fiction\']', 'Open war against humanity rages. For five survivors – lost and on the run – the pursuit is relentless, the bullets are dwindling and the battle is everywhere. This is a 24-hour look into their lives.'),
(1344, '10764', 'en', 'https://image.tmdb.org/t/p/w500/e3DXXLJHGqMx9yYpXsql1XNljmM.jpg', 'Quantum of Solace', '67.782', '2008-10-31', 6.3, '6189', '[\'Adventure\', \'Action\', \'Thriller\', \'Crime\']', 'Quantum of Solace continues the adventures of James Bond after Casino Royale. Betrayed by Vesper, the woman he loved, 007 fights the urge to make his latest mission personal. Pursuing his determination to uncover the truth, Bond and M interrogate Mr. White, who reveals that the organization that blackmailed Vesper is far more complex and dangerous than anyone had imagined.'),
(1345, '338970', 'en', 'https://image.tmdb.org/t/p/w500/s4Qn5LF6OwK4rIifmthIDtbqDSs.jpg', 'Tomb Raider', '49.087', '2018-03-05', 6.4, '6382', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Lara Croft, the fiercely independent daughter of a missing adventurer, must push herself beyond her limits when she finds herself on the island where her father disappeared.'),
(1346, '619264', 'es', 'https://image.tmdb.org/t/p/w500/iXvQnzy6JCAx1PiQEKXuTY04ZHl.jpg', 'El hoyo', '45.198', '2019-11-08', 7, '5006', '[\'Drama\', \'Science Fiction\', \'Thriller\']', 'A mysterious place, an indescribable prison, a deep hole. An unknown number of levels. Two inmates living on each level. A descending platform containing food for all of them. An inhuman fight for survival, but also an opportunity for solidarity.'),
(1347, '1734', 'en', 'https://image.tmdb.org/t/p/w500/kdJsW7hcy1lrj7tdMPycTAQPAiR.jpg', 'The Mummy Returns', '47.167', '2001-05-04', 6.3, '5471', '[\'Adventure\', \'Action\', \'Fantasy\']', 'Rick and Evelyn O’Connell, along with their 8-year-old son Alex, discover the key to the legendary Scorpion King’s might: the fabled Bracelet of Anubis. Unfortunately, a newly resurrected Imhotep has designs on the bracelet as well, and isn’t above kidnapping its new bearer, Alex, to gain control of Anubis’s otherworldly army.'),
(1348, '2034', 'en', 'https://image.tmdb.org/t/p/w500/bUeiwBQdupBLQthMCHKV7zv56uv.jpg', 'Training Day', '71.039', '2001-10-05', 7.5, '4377', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'On his first day on the job as a narcotics officer, a rookie cop works with a rogue detective who isn\'t what he appears.'),
(1349, '242828', 'ja', 'https://image.tmdb.org/t/p/w500/vug1dvDI1tSa60Z8qjCuUE7ntkO.jpg', '思い出のマーニー', '41.842', '2014-07-19', 8, '1292', '[\'Animation\', \'Drama\']', 'Upon being sent to live with relatives in the countryside due to an illness, an emotionally distant adolescent girl becomes obsessed with an abandoned mansion and infatuated with a girl who lives there - a girl who may or may not be real.'),
(1350, '605', 'en', 'https://image.tmdb.org/t/p/w500/bkkS61w94ZVMNVd8KEyyJl2tnY5.jpg', 'The Matrix Revolutions', '52.186', '2003-11-05', 6.7, '7394', '[\'Adventure\', \'Action\', \'Thriller\', \'Science Fiction\']', 'The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.'),
(1351, '216282', 'en', 'https://image.tmdb.org/t/p/w500/kBgrhrES9kMKSPxawUYV61KjlnB.jpg', 'Into the Storm', '43.833', '2014-08-06', 6, '1648', '[\'Action\', \'Thriller\']', 'As a new day begins in the town of Silverton, its residents have little reason to believe it will be anything other than ordinary. Mother Nature, however has other plans. In the span of just a few hours, an unprecedented onslaught of powerful tornadoes ravages Silverton. Storm trackers predict that the worst is still to come, as terrified residents seek shelter, and professional storm-chasers run toward the danger, hoping to study the phenomenon close up and get a once-in-a-lifetime shot.'),
(1352, '175112', 'en', 'https://image.tmdb.org/t/p/w500/81oxrsugqqs8sAVNX9fdlz57cVU.jpg', 'Tinker Bell and the Pirate Fairy', '39.079', '2014-02-13', 6.8, '747', '[\'Animation\', \'Family\']', 'Zarina, a smart and ambitious dust-keeper fairy who’s captivated by Blue Pixie Dust and its endless possibilities, flees Pixie Hollow and joins forces with the scheming pirates of Skull Rock, who make her captain of their ship. Tinker Bell and her friends must embark on an epic adventure to find Zarina, and together they go sword-to-sword with the band of pirates led by a cabin boy named James, who’ll soon be known as Captain Hook himself.'),
(1353, '23172', 'en', 'https://image.tmdb.org/t/p/w500/nJJrceb2xHGIA0irADX0JvWSIHT.jpg', 'The Spy Next Door', '41.524', '2010-01-15', 5.8, '986', '[\'Action\', \'Comedy\', \'Family\']', 'Former CIA spy Bob Ho takes on his toughest assignment to date: looking after his girlfriend\'s three kids, who haven\'t exactly warmed to their mom\'s beau. And when one of the youngsters accidentally downloads a top-secret formula, Bob\'s longtime nemesis, a Russian terrorist, pays a visit to the family.'),
(1354, '101', 'en', 'https://image.tmdb.org/t/p/w500/bxB2q91nKYp8JNzqE7t7TWBVupB.jpg', 'Léon: The Professional', '58.812', '1994-09-14', 8.3, '11430', '[\'Crime\', \'Drama\', \'Action\']', 'Léon, the top hit man in New York, has earned a rep as an effective \"cleaner\". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda\'s thoughts turn to revenge, and she considers following in Léon\'s footsteps.'),
(1355, '10882', 'en', 'https://image.tmdb.org/t/p/w500/n3pxoMDDxp10c1smgbDzW4bwlzq.jpg', 'Sleeping Beauty', '46.563', '1959-02-17', 6.9, '4142', '[\'Fantasy\', \'Animation\', \'Romance\', \'Family\']', 'A beautiful princess born in a faraway kingdom is destined by a terrible curse to prick her finger on the spindle of a spinning wheel and fall into a deep sleep that can only be awakened by true love\'s first kiss. Determined to protect her, her parents ask three fairies to raise her in hiding. But the evil Maleficent is just as determined to seal the princess\'s fate.'),
(1356, '280', 'en', 'https://image.tmdb.org/t/p/w500/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', 'Terminator 2: Judgment Day', '60.312', '1991-07-03', 8.1, '9801', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'Nearly 10 years have passed since Sarah Connor was targeted for termination by a cyborg from the future. Now her son, John, the future leader of the resistance, is the target for a newer, more deadly terminator. Once again, the resistance has managed to send a protector back to attempt to save John and his mother Sarah.'),
(1357, '423204', 'en', 'https://image.tmdb.org/t/p/w500/fapXd3v9qTcNBTm39ZC4KUVQDNf.jpg', 'Angel Has Fallen', '51.484', '2019-08-21', 6.5, '2537', '[\'Action\', \'Thriller\']', 'After a treacherous attack, Secret Service agent Mike Banning is charged with attempting to assassinate President Trumbull. Chased by his own colleagues and the FBI, Banning begins a race against the clock to clear his name.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1358, '193610', 'en', 'https://image.tmdb.org/t/p/w500/yHnbb6z8REuFIyBLT2Nj3MX54dY.jpg', 'The Other Woman', '39.061', '2014-04-16', 6.4, '3000', '[\'Comedy\', \'Romance\']', 'After discovering her boyfriend is married, Carly soon meets the wife he\'s been cheating on. And when yet another affair is discovered, all three women team up to plot mutual revenge on the three-timing SOB.'),
(1359, '770742', 'it', 'https://image.tmdb.org/t/p/w500/hzeHk2Cmszec4fscgPEGVLVg8O6.jpg', 'Mio fratello, mia sorella', '42.35', '2021-10-08', 6.7, '51', '[\'Drama\']', 'When their father\'s will forces them to live together, siblings Nik and Tesla — and Tesla\'s kids — try to overcome their differences to become a family.'),
(1360, '9358', 'en', 'https://image.tmdb.org/t/p/w500/vnFgxRlLTA9fDNcGXLiHmgwmIEo.jpg', 'Final Destination 2', '46.491', '2003-01-31', 6.2, '2976', '[\'Horror\', \'Mystery\']', 'When Kimberly has a violent premonition of a highway pileup she blocks the freeway, keeping a few others meant to die, safe...Or are they? The survivors mysteriously start dying and it\'s up to Kimberly to stop it before she\'s next.'),
(1361, '37797', 'ja', 'https://image.tmdb.org/t/p/w500/5FROLD8zpWFs9ja7aYho1uOMJHg.jpg', '耳をすませば', '48.276', '1995-07-15', 7.9, '1318', '[\'Animation\', \'Drama\', \'Family\']', 'Shizuku lives a simple life, dominated by her love for stories and writing. One day she notices that all the library books she has have been previously checked out by the same person: \'Seiji Amasawa\'.'),
(1362, '72559', 'en', 'https://image.tmdb.org/t/p/w500/3rWIZMzTKcCtV0eHJ70Z4Ru659f.jpg', 'G.I. Joe: Retaliation', '44.526', '2013-03-27', 5.6, '4707', '[\'Science Fiction\', \'Adventure\', \'Action\', \'Thriller\']', 'Framed for crimes against the country, the G.I. Joe team is terminated by Presidential order. This forces the G.I. Joes into not only fighting their mortal enemy Cobra; they are forced to contend with threats from within the government that jeopardize their very existence.'),
(1363, '350499', 'ja', 'https://image.tmdb.org/t/p/w500/6kXRevMC1XSywmxqqRHuBcZlROT.jpg', 'ポケモン・ザ・ムービーXY 光輪の超魔神 フーパ', '49.023', '2015-07-18', 6.7, '182', '[\'Family\', \'Adventure\', \'Animation\', \'Action\', \'Fantasy\']', 'Ash, Pikachu, and their friends come to a desert city by the sea. Here they meet the Mythical Pokémon Hoopa, which has the ability to summon things—including people and Pokémon—through its magic rings. After a scary incident, they learn of a story about a brave hero who stopped the rampage of a terrifying Pokémon long ago. Now, the threat that has been bottled up for years is in danger of breaking loose again.'),
(1364, '8456', 'en', 'https://image.tmdb.org/t/p/w500/8oRUTyP1QAtGDMvRpKZyuyFPG0U.jpg', 'Never Back Down', '45.467', '2008-03-04', 6.7, '1828', '[\'Drama\', \'Action\']', 'Jake, full of anger after his father\'s death, is just starting to find a place for himself at his new Orlando high school - until Ryan, head of an underground MMA fight club, picks Jake out as a prime opponent. After being trounced by Ryan in front of the entire school, Jake begins training under the firm, moral guidance of a MMA master, where he learns how to fight... and how to avoid a fight. But it becomes obvious that a rematch will be inevitable if Jake wants to stop Ryan and his bullying, once and for all.'),
(1365, '12556', 'en', 'https://image.tmdb.org/t/p/w500/azzg0lv5vpQRoOrZfNVkJn04f1M.jpg', 'Ghosts of Girlfriends Past', '45.963', '2009-05-01', 5.9, '1863', '[\'Fantasy\', \'Comedy\', \'Romance\']', 'When notorious womanizer Connor Mead attends his brother Paul\'s wedding, he is forced to re-evaluate his behavior as he comes face-to-face with the ghosts of girlfriends past, present, and future, along with his deceased uncle. The experience changes his attitude and allows him to reconnect with his first and only love, Jenny.'),
(1366, '814820', 'en', 'https://image.tmdb.org/t/p/w500/dy6j0JxmnTj7KfXMLAO9XSYpXSY.jpg', 'All for Her', '43.89', '2021-09-13', 4, '2', '[\'Drama\']', 'When a woman finally becomes pregnant but is diagnosed with a deadly condition, she must lean on her family to save her unborn child.'),
(1367, '15165', 'en', 'https://image.tmdb.org/t/p/w500/xHYsUwUe4MaNc6mbNBGTkqZSnPk.jpg', 'Barbie as The Princess & the Pauper', '53.257', '2004-09-28', 7.5, '1118', '[\'Animation\', \'Family\', \'Comedy\']', 'In her first animated musical featuring seven original songs, Barbie comes to life in this modern re-telling of a classic tale of mistaken identity and the power of friendship. Based on the story by Mark Twain,'),
(1368, '530385', 'en', 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'Midsommar', '43.77', '2019-07-03', 7.1, '4241', '[\'Horror\', \'Drama\', \'Mystery\']', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.'),
(1369, '10555', 'en', 'https://image.tmdb.org/t/p/w500/r08DpyPyhXcJTfNZAICNGMzcQ8l.jpg', 'Shark Tale', '48.452', '2004-09-20', 6, '5209', '[\'Animation\', \'Action\', \'Comedy\', \'Family\']', 'Oscar is a small fish whose big aspirations often get him into trouble. Meanwhile, Lenny is a great white shark with a surprising secret that no sea creature would guess: He\'s a vegetarian. When a lie turns Oscar into an improbable hero and Lenny becomes an outcast, the two form an unlikely friendship.'),
(1370, '10140', 'en', 'https://image.tmdb.org/t/p/w500/pP27zlm9yeKrCeDZLFLP2HKELot.jpg', 'The Chronicles of Narnia: The Voyage of the Dawn Treader', '47.152', '2010-12-02', 6.4, '4510', '[\'Adventure\', \'Family\', \'Fantasy\']', 'This time around Edmund and Lucy Pevensie, along with their pesky cousin Eustace Scrubb find themselves swallowed into a painting and on to a fantastic Narnian ship headed for the very edges of the world.'),
(1371, '1374', 'en', 'https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg', 'Rocky IV', '69.976', '1985-11-21', 7, '3209', '[\'Drama\']', 'After iron man Drago, a highly intimidating 6-foot-5, 261-pound Soviet athlete, kills Apollo Creed in an exhibition match, Rocky comes to the heart of Russia for 15 pile-driving boxing rounds of revenge.'),
(1372, '275619', 'en', 'https://image.tmdb.org/t/p/w500/rij2GSSXbhNLCFdvJN8YmRRD2i3.jpg', 'Age of Tomorrow', '32.496', '2014-06-10', 3, '50', '[\'Thriller\', \'Science Fiction\', \'Action\']', 'Mankind must fight to survive as Earth is invaded by hostile UFOs bent on destroying the planet. As the epic battle wages on, astronauts sneak aboard the mothership where they discover a portal to the aliens\' home world. They manage to alert Earth before they are brutally murdered. Left with no other choice, Earth sends an elite military team of science and combat specialists through the portal where they attempt to stop the invasion from the inside out.'),
(1373, '1250', 'en', 'https://image.tmdb.org/t/p/w500/1pyU94dAY7npDQCKuxCSyX9KthN.jpg', 'Ghost Rider', '41.874', '2007-01-15', 5.5, '4603', '[\'Thriller\', \'Action\', \'Fantasy\']', 'In order to save his dying father, young stunt cyclist Johnny Blaze sells his soul to Mephistopheles and sadly parts from the pure-hearted Roxanne Simpson, the love of his life. Years later, Johnny\'s path crosses again with Roxanne, now a go-getting reporter, and also with Mephistopheles, who offers to release Johnny\'s soul if Johnny becomes the fabled, fiery \'Ghost Rider\'.'),
(1374, '16366', 'en', 'https://image.tmdb.org/t/p/w500/ou0JqPXFbQcphqkMx1grfsmeJFX.jpg', 'Joseph: King of Dreams', '39.917', '2000-11-07', 6.6, '756', '[\'Family\', \'Animation\']', 'In this animated retelling of the story from the Bible\'s Book of Genesis, Joseph\'s gift of dream interpretation and his brilliantly colored coat inspires jealousy in his brothers.'),
(1375, '19912', 'en', 'https://image.tmdb.org/t/p/w500/5vxXrr1MqGsT4NNeRITpfDnl4Rq.jpg', 'The Final Destination', '45.668', '2009-08-26', 5.6, '2410', '[\'Horror\', \'Mystery\']', 'After a young man\'s premonition of a deadly race-car crash helps saves the lives of his peers, Death sets out to collect those who evaded their end.'),
(1376, '800669', 'id', 'https://image.tmdb.org/t/p/w500/zpF0WcOarNWVhS17eeT1nl6IacP.jpg', 'A Perfect Fit', '45.089', '2021-07-15', 7.5, '49', '[\'Romance\', \'Comedy\', \'Drama\']', 'Sparks fly when a fashion blogger in Bali meets a gifted shoemaker, leading her to question her commitment to her fiancé.'),
(1377, '78215', 'en', 'https://image.tmdb.org/t/p/w500/bk9RD0kH51GoDURk7xgWDoTcRl7.jpg', 'Into the White', '47.464', '2012-03-09', 6.9, '220', '[\'War\', \'Action\', \'Drama\']', 'Based on a true story. On 27 April 1940, Luftwaffe pilot Horst Schopis\' Heinkel 111 bomber is shot down near Grotli by an RAF Blackburn Skua L2940 fighter, which then crash-lands. The surviving German and English crew members begin to at shoot each other, but later find themselves huddled up in the same cabin. In order to survive the harsh winter in the Norwegian wilderness, they have to stand together. An unlikely, lifelong friendship blossoms.'),
(1378, '59108', 'en', 'https://image.tmdb.org/t/p/w500/jQrroNwP8hbFiUlNMs20emauwPE.jpg', 'Tower Heist', '42.964', '2011-11-02', 6, '2303', '[\'Action\', \'Comedy\']', 'A luxury condo manager leads a staff of workers to seek payback on the Wall Street swindler who defrauded them. With only days until the billionaire gets away with the perfect crime, the unlikely crew of amateur thieves enlists the help of petty crook Slide to steal the $20 million they’re sure is hidden in the penthouse.'),
(1379, '93837', 'en', 'https://image.tmdb.org/t/p/w500/abR6e0FaWwwcEJEM4PY5VvjwBr1.jpg', 'So Undercover', '37.214', '2012-12-06', 6.1, '978', '[\'Action\', \'Comedy\']', 'When the FBI hires her to go undercover at a college sorority, Molly Morris (Miley Cyrus) must transform herself from a tough, streetwise private investigator to a refined, sophisticated university girl to help protect the daughter of a one-time Mobster. With several suspects on her list, Molly unexpectedly discovers that not everyone is who they appear to be, including herself.'),
(1380, '10527', 'en', 'https://image.tmdb.org/t/p/w500/agRbLOHgN46TQO4YdKR462iR7To.jpg', 'Madagascar: Escape 2 Africa', '49.66', '2008-10-30', 6.4, '5441', '[\'Family\', \'Adventure\', \'Animation\', \'Comedy\']', 'Alex, Marty, and other zoo animals find a way to escape from Madagascar when the penguins reassemble a wrecked airplane. The precariously repaired craft stays airborne just long enough to make it to the African continent. There the New Yorkers encounter members of their own species for the first time. Africa proves to be a wild place, but Alex and company wonder if it is better than their Central Park home.'),
(1381, '6844', 'en', 'https://image.tmdb.org/t/p/w500/3Ei59AR64x6dMZfWobPCkZjbqTL.jpg', 'The Ten Commandments', '48.448', '1956-10-05', 7.7, '1036', '[\'Drama\', \'History\']', 'Escaping death, a Hebrew infant is raised in a royal household to become a prince. Upon discovery of his true heritage, Moses embarks on a personal quest to reclaim his destiny as the leader and liberator of the Hebrew people.'),
(1382, '14199', 'en', 'https://image.tmdb.org/t/p/w500/xpFbHSkRgOxOoutKqXob9T8iBPA.jpg', 'The Adventures of Sharkboy and Lavagirl', '46.148', '2005-06-10', 5.1, '1130', '[\'Adventure\', \'Family\', \'Science Fiction\']', 'Everyone always knew that Max had a wild imagination, but no one believed that his wildest creations -- a boy raised by watchful great white sharks and a girl with the force of a volcano -- were real. Now, these two pint-sized action masters will show Max that even an ordinary kid has what it takes to be extraordinary.'),
(1383, '854', 'en', 'https://image.tmdb.org/t/p/w500/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', 'The Mask', '54.645', '1994-07-29', 6.9, '7948', '[\'Romance\', \'Comedy\', \'Crime\', \'Fantasy\']', 'When timid bank clerk Stanley Ipkiss discovers a magical mask containing the spirit of the Norse god Loki, his entire life changes. While wearing the mask, Ipkiss becomes a supernatural playboy exuding charm and confidence which allows him to catch the eye of local nightclub singer Tina Carlyle. Unfortunately, under the mask\'s influence, Ipkiss also robs a bank, which angers junior crime lord Dorian Tyrell, whose goons get blamed for the heist.'),
(1384, '10012', 'en', 'https://image.tmdb.org/t/p/w500/y4Uba4QQcjEHqv5sw3f59PyMz8R.jpg', 'Cursed', '48.188', '2005-02-25', 5.5, '491', '[\'Horror\', \'Comedy\']', 'A werewolf loose in Los Angeles changes the lives of three young adults, who, after being mauled by the beast, learn they must kill their attacker if they hope to change their fate to avoid becoming werewolves too.'),
(1385, '817772', 'en', 'https://image.tmdb.org/t/p/w500/pP2sMNwaMrrMSfOuRh9CkUgQmGG.jpg', 'Seven Deadly Sins: Lust', '45.831', '2021-04-10', 4.5, '2', '[\'Drama\']', 'Tiffanie (Keri Hilson) is about to have the wedding of her dreams to her soul mate, the dashing Damon King (Tobias Truvillion), founder of King Enterprises. But when Damon’s old friend Trey (Durrell ‘Tank’ Babbs) arrives, fresh from prison to step in as Damon’s best man, Tiffanie’s whole world gets rocked. Sexy and mysterious, Trey triggers a passion in Tiffanie that she never expected, and suddenly the life she’s always planned with Damon is uncertain. But Trey still carries wounds from his history with Damon, and his intentions toward both Tiffanie and Damon are not to be trusted. Ms. Juicy, LeToya Luckett, and Clifton Powell also star.'),
(1386, '253412', 'en', 'https://image.tmdb.org/t/p/w500/2jKOu2bjpLP6NXJcm7Ep14bDGtA.jpg', 'Everest', '46.035', '2015-09-10', 6.8, '3953', '[\'Drama\', \'Adventure\', \'History\']', 'Inspired by the incredible events surrounding a treacherous attempt to reach the summit of the world\'s highest mountain, \"Everest\" documents the awe-inspiring journey of two different expeditions challenged beyond their limits by one of the fiercest snowstorms ever encountered by mankind. Their mettle tested by the harshest of elements found on the planet, the climbers will face nearly impossible obstacles as a lifelong obsession becomes a breathtaking struggle for survival.'),
(1387, '49040', 'en', 'https://image.tmdb.org/t/p/w500/1aExL5DTGHj25ZfIC3dDwS84RWi.jpg', 'The Bourne Legacy', '45.782', '2012-08-08', 6.2, '4667', '[\'Action\', \'Thriller\']', 'New CIA operative Aaron Cross experiences life-or-death stakes that have been triggered by the previous actions of Jason Bourne.'),
(1388, '323027', 'en', 'https://image.tmdb.org/t/p/w500/9EoqQuEZKmQIYjexoUbkxMcMCVr.jpg', 'Justice League: Gods and Monsters', '45.432', '2015-07-14', 7.2, '422', '[\'Action\', \'Animation\', \'Fantasy\']', 'In an alternate universe, very different versions of DC\'s Trinity fight against the government after they are framed for an embassy bombing.'),
(1389, '353081', 'en', 'https://image.tmdb.org/t/p/w500/AkJQpZp9WoNdj7pLYSj1L0RcMMN.jpg', 'Mission: Impossible - Fallout', '49.585', '2018-07-13', 7.4, '6213', '[\'Action\', \'Adventure\']', 'When an IMF mission ends badly, the world is faced with dire consequences. As Ethan Hunt takes it upon himself to fulfill his original briefing, the CIA begin to question his loyalty and his motives. The IMF team find themselves in a race against time, hunted by assassins while trying to prevent a global catastrophe.'),
(1390, '1364', 'es', 'https://image.tmdb.org/t/p/w500/gvErAg9bv7xOO3B40gottv6Bqip.jpg', 'Lucía y el sexo', '43.916', '2001-08-24', 6.7, '361', '[\'Drama\', \'Romance\']', 'Various lives converge on an isolated island, all connected by an author whose novel has become inextricably entwined with his own life.'),
(1391, '64694', 'es', 'https://image.tmdb.org/t/p/w500/bE1ifeGhr7gkJP9z8lAFGkEhlv6.jpg', 'No eres tú, soy yo', '38.661', '2010-08-27', 7.2, '136', '[\'Comedy\', \'Drama\', \'Romance\']', 'Javier se ha casado con María, el amor de su vida, y ahora lo único que desea es estar feliz con ella el resto de su vida, pero el destino se la quita poco después de la boda. Ahora Javier está enredado en sus emociones: ¿cómo aceptará la muerte de su mujer para encontrar nuevamente el amor?'),
(1392, '656561', 'en', 'https://image.tmdb.org/t/p/w500/3UGrAX6D1AMVra80jmUMUOLq8Qr.jpg', 'Alien Xmas', '46.286', '2020-11-20', 6.7, '86', '[\'Animation\', \'Family\', \'Fantasy\']', 'A young elf mistakes a tiny alien for a Christmas gift, not knowing her new plaything has plans to destroy Earth\'s gravity — and steal all the presents.'),
(1393, '362585', 'ja', 'https://image.tmdb.org/t/p/w500/rfKHhHvSwyCv59Ow6wuGX67RkXR.jpg', '傷物語〈Ⅲ冷血篇〉', '51.162', '2017-01-06', 8.1, '123', '[\'Animation\', \'Fantasy\', \'Mystery\']', 'With help from Meme Oshino, the apparition specialist, Koyomi defeats the three powerful vampire hunters: Dramaturgy, Episode and Guillotinecutter. Koyomi takes back all the limbs of Kiss-shot Acerola-orion Heart-under-blade in order to become a human again.'),
(1394, '11811', 'en', 'https://image.tmdb.org/t/p/w500/8SZgqIjiCSaRq03SxW1Z6yLfBHf.jpg', 'Leprechaun', '40.603', '1993-01-08', 5.6, '517', '[\'Comedy\', \'Horror\', \'Thriller\']', 'A horrific Leprechaun goes on a rampage after his precious bag of gold coins is stolen. He uses all of his magical destructive powers to trick, terrorize and kill anyone who is unlucky enough to hinder his relentless search. In a frantic attempt to survive the wrath of the Leprechaun, Tori and her friends scramble to find the only weapon known to kill this Irish monster...a four-leaf clover.'),
(1395, '756278', 'en', 'https://image.tmdb.org/t/p/w500/67ITWm7Me4ThtT7v3W9BYCcP2m.jpg', 'Haunting of the Mary Celeste', '42.668', '2020-10-23', 6, '24', '[\'Horror\']', 'Rachel, a concerned researcher, and her team have set out to sea to prove that the disappearance of a family and crew from a merchant ship was for reasons having to do with the supernatural. Her theory that those on the Mary Celeste vanished into a \"rift\" between dimensions proves true as the boat breaks down and her crew begins to vanish one by one.'),
(1396, '399897', 'ja', 'https://image.tmdb.org/t/p/w500/6QFciT2BXoqaFZsDeLrvxMmVRMq.jpg', '妖女伝説セイレーンXXX～魔性の悦楽～', '49.923', '2010-08-13', 4.2, '9', '[\'Horror\']', 'In a rural port town, Kenji Ishikawa runs a barber shop together with his new wife, who speaks very little and has mysterious eyes to match her amorous presence. Running the shop isn’t easy as hardly any customers come…  One evening, a man comes to the shop, as if lured by the faint hum of the wife. As the man takes a seat, Kenji exits his shop. The wife then gently fingers the man’s neck…'),
(1397, '381284', 'en', 'https://image.tmdb.org/t/p/w500/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg', 'Hidden Figures', '49.802', '2016-12-10', 8.1, '7310', '[\'Drama\', \'History\']', 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.'),
(1398, '13955', 'en', 'https://image.tmdb.org/t/p/w500/n6BFaobIdGWQhYI1uiq9gmY4FBq.jpg', 'Beethoven\'s Big Break', '49.893', '2008-12-26', 5.2, '105', '[\'Comedy\', \'Family\']', 'Eddie, a struggling animal trainer and single dad suddenly finds himself the personal wrangler for a large and lovable St. Bernard whose fabulous movie \"audition\" catapults the dog to stardom. However, a trio of unscrupulous ne\'er-do-wells have plans to kidnap the famous dog and hold him for ransom.'),
(1399, '70006', 'en', 'https://image.tmdb.org/t/p/w500/7VjtTMQpfy9GxMyjUfuYTfyatZz.jpg', 'Never Back Down 2: The Beatdown', '41.092', '2011-09-13', 6.4, '494', '[\'Drama\', \'Action\']', 'Four fighters from different backgrounds come together to train under an ex MMA rising star and then ultimately have to fight each other and the traitor in their midst.'),
(1400, '10283', 'en', 'https://image.tmdb.org/t/p/w500/6ezOsZ9UzqGnbDokaatxdOWP6e9.jpg', 'Friday the 13th Part VIII: Jason Takes Manhattan', '50.387', '1989-07-28', 4.9, '691', '[\'Horror\', \'Thriller\']', 'A group of students on a graduation cruise bound for Manhattan soon realize they\'ve got a stowaway aboard the ship: serial killer Jason Voorhees.'),
(1401, '13002', 'en', 'https://image.tmdb.org/t/p/w500/yBB7PwXRFJ29U8m8SnTcWVizFvM.jpg', 'Barbie in the 12 Dancing Princesses', '49.135', '2006-09-19', 7.7, '789', '[\'Animation\', \'Family\']', 'King Randolph sends for his cousin Duchess Rowena to help turn his daughters, Princess Genevieve and her 11 sisters, into better ladies. But the Duchess takes away all the sisters fun, including the sisters favorite pastime: dancing.Thinking all hope is lost they find a secret passageway to a magical land were they can dance the night away.'),
(1402, '227719', 'en', 'https://image.tmdb.org/t/p/w500/9u5Rb0e7mx8qOO7zj39KnIRWClr.jpg', 'Project Almanac', '49.636', '2015-01-28', 6.6, '2022', '[\'Science Fiction\', \'Thriller\', \'Drama\']', 'A group of teens discover secret plans of a time machine, and construct one. However, things start to get out of control.'),
(1403, '79082', 'ja', 'https://image.tmdb.org/t/p/w500/eYm3oEPiQJ9RV5QdyudwUplb9cD.jpg', 'ONE PIECE 3D 麦わらチェイス', '43.361', '2011-03-19', 6.7, '91', '[\'Animation\']', 'One Piece 3D: Straw Hat Chase is the 11th One Piece film of the series, and is set before the time-skip. This is One Piece\'s first movie release to be in 3D CGI. The movie is also the first One Piece film since Movie 3 to be a double-feature. This time, the film was featured with \"Toriko 3D: Gourmet Adventure\", both being billed as the \"Jump Heroes Film\". The double-feature was released on March 19, 2011.granmaster'),
(1404, '14442', 'en', 'https://image.tmdb.org/t/p/w500/7AyNzwSEpJEG1gBdgwRfXi1cjs8.jpg', 'Ella Enchanted', '43.877', '2004-04-09', 6.4, '1480', '[\'Family\', \'Fantasy\', \'Comedy\']', 'Ella lives in a magical world in which each child, at the moment of their birth, is given a virtuous \"gift\" from a fairy godmother. Ella\'s so-called gift, however, is obedience. This birthright proves itself to be quite the curse once Ella finds herself in the hands of several unscrupulous characters whom she quite literally cannot disobey. Determined to gain control of her life and decisions, Ella sets off on a journey to find her fairy godmother who she hopes will lift the curse. The path, however, isn\'t easy -- Ella must outwit a slew of unpleasant obstacles including ogres, giants, wicked stepsisters, elves and Prince Charmont\'s evil uncle, who wants to take over the crown and rule the kingdom.'),
(1405, '567604', 'en', 'https://image.tmdb.org/t/p/w500/w6Jk8BHohhoKBUcxGeSyDQGWGWc.jpg', 'Once Upon a Deadpool', '42.886', '2018-12-11', 7.1, '537', '[\'Comedy\', \'Action\']', 'A kidnapped Fred Savage is forced to endure Deadpool\'s PG-13 rendition of Deadpool 2 as a Princess Bride-esque story that\'s full of magic, wonder & zero F\'s.'),
(1406, '46529', 'en', 'https://image.tmdb.org/t/p/w500/2NrP3h3GEsrPXX60bmjKuYWAvl9.jpg', 'I Am Number Four', '42.12', '2011-02-18', 6.2, '3855', '[\'Action\', \'Thriller\', \'Science Fiction\', \'Adventure\']', 'A teenage fugitive with an incredible secret races to stay one step ahead of the mysterious forces seeking destroy him in this sci-fi action thriller. With three dead and one on the run, the race to find the elusive Number Four begins. Outwardly normal teen John Smith never gets too comfortable in the same identity, and along with his guardian, Henri, he is constantly moving from town to town. With each passing day, John gains a stronger grasp on his extraordinary new powers, and his bond to the beings that share his fantastic fate grows stronger.'),
(1407, '340382', 'ja', 'https://image.tmdb.org/t/p/w500/l9cJ5PKEkVJb6YUCiURtcMbTQ5D.jpg', '進撃の巨人 ATTACK ON TITAN エンド オブ ザ ワールド', '53.366', '2015-09-01', 5.7, '201', '[\'Horror\', \'Science Fiction\', \'Action\', \'Fantasy\']', 'Eren leaves to restore a break in the wall destroyed by a Titan. He comes under attack by the Titans and is cornered. Shikishima comes to his aid. The titans never stops attacking.  Eren is now injured and tries to protect Armin, but is swallowed by a titan. A Titan with black hair appears and begins to expel the other titans.'),
(1408, '278927', 'en', 'https://image.tmdb.org/t/p/w500/yN1kuupnPTLUprgfvC5WapgrxG4.jpg', 'The Jungle Book', '40.811', '2016-04-07', 6.9, '6853', '[\'Family\', \'Adventure\', \'Drama\', \'Fantasy\']', 'A man-cub named Mowgli fostered by wolves. After a threat from the tiger Shere Khan, Mowgli is forced to flee the jungle, by which he embarks on a journey of self discovery with the help of the panther, Bagheera and the free-spirited bear, Baloo.'),
(1409, '297270', 'en', 'https://image.tmdb.org/t/p/w500/3S0mmmpYStB3GqodRghcfOt81wQ.jpg', 'Tinker Bell and the Legend of the NeverBeast', '47.353', '2014-12-12', 7.1, '734', '[\'Adventure\', \'Animation\', \'Family\']', 'An ancient myth of a massive creature sparks the curiosity of Tinker Bell and her good friend Fawn, an animal fairy who’s not afraid to break the rules to help an animal in need. But this creature is not welcome in Pixie Hollow — and the scout fairies are determined to capture the mysterious beast, who they fear will destroy their home. Fawn must convince her fairy friends to risk everything to rescue the NeverBeast.'),
(1410, '59967', 'en', 'https://image.tmdb.org/t/p/w500/sNjL6SqErDBE8OUZlrDLkexfsCj.jpg', 'Looper', '43.7', '2012-09-26', 6.9, '8539', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'In the futuristic action thriller Looper, time travel will be invented but it will be illegal and only available on the black market. When the mob wants to get rid of someone, they will send their target 30 years into the past where a looper, a hired gun, like Joe is waiting to mop up. Joe is getting rich and life is good until the day the mob decides to close the loop, sending back Joe\'s future self for assassination.'),
(1411, '268', 'en', 'https://image.tmdb.org/t/p/w500/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', 'Batman', '42.888', '1989-06-23', 7.2, '5836', '[\'Fantasy\', \'Action\']', 'Batman must face his most ruthless nemesis when a deformed madman calling himself \"The Joker\" seizes control of Gotham\'s criminal underworld.'),
(1412, '14001', 'en', 'https://image.tmdb.org/t/p/w500/rvcUVdATIHKZt7BSSttUkKbeBXN.jpg', 'Dead Silence', '41.283', '2007-03-16', 6.4, '1685', '[\'Horror\']', 'Jamie returns to his hometown in search of answers to his wife\'s murder, which occurred after receiving a weird package containing a ventriloquist dummy named Billy, which may be linked to the legend of ventriloquist Mary Shaw. Destined to find out the truth, Jamie goes to the town of Raven\'s Fair, where Shaw used to perform and is buried. But Jamie is in for more than he expected.'),
(1413, '765169', 'es', 'https://image.tmdb.org/t/p/w500/eIxLHFMAsdbZGZws0duowTa4N6k.jpg', 'BIA: Un Mundo al Revés', '43.401', '2021-02-19', 7.9, '105', '[\'Comedy\', \'Drama\', \'Family\']', 'In this alternate world, Bia and Manuel will have a tempestuous relationship. Pixie, the hateful and stunning owner of Laix, decides to buy the Fundom. The great conflict erupts when Pixie announces a concert. This will have Bia and Helena, who in this upside down universe are divas and rivals, fighting to be the headliner in the final show.'),
(1414, '458220', 'en', 'https://image.tmdb.org/t/p/w500/xSDdRAjxKAGi8fUBLOqSrBhJmF0.jpg', 'Palmer', '44.137', '2021-01-29', 8.1, '649', '[\'Drama\']', 'After 12 years in prison, former high school football star Eddie Palmer returns home to put his life back together—and forms an unlikely bond with Sam, an outcast boy from a troubled home. But Eddie\'s past threatens to ruin his new life and family.'),
(1415, '75258', 'en', 'https://image.tmdb.org/t/p/w500/aPudKEzwwmwc5lS8sdxvG3WX86t.jpg', 'Secret of the Wings', '52.325', '2012-08-17', 7.1, '887', '[\'Animation\', \'Family\', \'Fantasy\', \'Adventure\']', 'Tinkerbell wanders into the forbidden Winter woods and meets Periwinkle. Together they learn the secret of their wings and try to unite the warm fairies and the winter fairies to help Pixie Hollow.'),
(1416, '9323', 'ja', 'https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', 'GHOST IN THE SHELL', '44.819', '1995-11-18', 7.9, '2361', '[\'Action\', \'Animation\', \'Science Fiction\']', 'In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as \'The Puppetmaster\' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.'),
(1417, '504631', 'en', 'https://image.tmdb.org/t/p/w500/oB281saxibom0KC3Ndz81aJJtaa.jpg', 'Mermaid Down', '40.08', '2019-10-15', 6.7, '225', '[\'Horror\', \'Fantasy\', \'Mystery\', \'Thriller\']', 'A mermaid is ripped from the Pacific, her tail is chopped off and she\'s thrown into a mental home where no one believes she is a mermaid.'),
(1418, '241259', 'en', 'https://image.tmdb.org/t/p/w500/kbGamUkYfgKIYIrU8kW5oc0NatZ.jpg', 'Alice Through the Looking Glass', '50.409', '2016-05-25', 6.6, '5321', '[\'Adventure\', \'Family\', \'Fantasy\']', 'Alice Kingsleigh returns to Underland and faces a new adventure in saving the Mad Hatter.'),
(1419, '9378', 'en', 'https://image.tmdb.org/t/p/w500/6yrrddjIjx0ElCRZp5pTZeqrj3k.jpg', 'Thir13en Ghosts', '46.748', '2001-10-26', 6.2, '1502', '[\'Horror\', \'Thriller\']', 'Arthur and his two children, Kathy and Bobby, inherit his Uncle Cyrus\'s estate: a glass house that serves as a prison to 12 ghosts. When the family, accompanied by Bobby\'s Nanny and an attorney, enter the house they find themselves trapped inside an evil machine \"designed by the devil and powered by the dead\" to open the Eye of Hell. Aided by Dennis, a ghost hunter, and his rival Kalina, a ghost rights activist out to set the ghosts free, the group must do what they can to get out of the house alive.'),
(1420, '287948', 'en', 'https://image.tmdb.org/t/p/w500/71kaQfdrMy0LHSeLRADsvlDGCgb.jpg', 'The Transporter Refueled', '53.244', '2015-09-02', 5.5, '1191', '[\'Action\', \'Thriller\', \'Crime\']', 'The fast-paced action movie is again set in the criminal underworld in France, where Frank Martin is known as The Transporter, because he is the best driver and mercenary money can buy. In this installment, he meets Anna and they attempt to take down a group of ruthless Russian human traffickers who also have kidnapped Frank’s father.'),
(1421, '171581', 'en', 'https://image.tmdb.org/t/p/w500/9liEU1O0GZIZXYf9SekjH5kb8bb.jpg', 'The Marine 3: Homefront', '44.537', '2013-03-05', 6.2, '140', '[\'Action\']', 'A Marine must do whatever it takes to save his kidnapped sister and stop a terrorist attack masterminded by a radical militia group.'),
(1422, '13', 'en', 'https://image.tmdb.org/t/p/w500/saHP97rTPS5eLmrLQEcANmKrsFl.jpg', 'Forrest Gump', '48.079', '1994-07-06', 8.5, '21522', '[\'Comedy\', \'Drama\', \'Romance\']', 'A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.'),
(1423, '16907', 'ja', 'https://image.tmdb.org/t/p/w500/eUNRUeSNzm8LktH4HRaYiAReB6R.jpg', '劇場版 NARUTO 大活劇! 雪姫忍法帖だってばよ!!', '49.281', '2004-08-21', 7.2, '332', '[\'Comedy\', \'Action\', \'Animation\', \'Adventure\']', 'Naruto is thrilled when he is sent on a mission to protect his favorite actress, Yukie Fujikaze, on the set of her new movie, The Adventures of Princess Gale. But when the crew ventures out to film in the icy, foreboding Land of Snow, Yukie mysteriously flees! Naruto and his squad set off to find her... unaware that three Snow Ninja lie in wait, with a sinister purpose that will force Yukie to face her hidden past!'),
(1424, '238615', 'en', 'https://image.tmdb.org/t/p/w500/6ri3y5n3BXahy6lu2i0ndrqA4CA.jpg', 'Self/less', '43.724', '2015-07-10', 6.4, '2452', '[\'Science Fiction\', \'Mystery\', \'Thriller\']', 'An extremely wealthy elderly man dying from cancer undergoes a radical medical procedure that transfers his consciousness to the body of a healthy young man but everything may not be as good as it seems when he starts to uncover the mystery of the body\'s origins and the secret organization that will kill to keep its secrets.'),
(1425, '552095', 'en', 'https://image.tmdb.org/t/p/w500/6qIEgqQWao5VcBE3jsXWOSTYZw.jpg', 'PAW Patrol: Mighty Pups', '45.029', '2019-05-17', 7.5, '486', '[\'Adventure\', \'Animation\', \'Family\', \'Action\']', 'When their latest scheme goes awry, Mayor Humdinger and his nephew Harold accidentally divert a meteor towards Adventure Bay. The meteor\'s golden energy grants the PAW Patrol superpowers. The heroic Mighty Pups are on a roll to super-save the day.'),
(1426, '4348', 'en', 'https://image.tmdb.org/t/p/w500/o8UhmEbWPHmTUxP0lMuCoqNkbB3.jpg', 'Pride & Prejudice', '44.161', '2005-09-16', 8.1, '6085', '[\'Drama\', \'Romance\']', 'A story of love and life among the landed English gentry during the Georgian era. Mr. Bennet is a gentleman living in Hertfordshire with his overbearing wife and five daughters, but if he dies their house will be inherited by a distant cousin whom they have never met, so the family\'s future happiness and security is dependent on the daughters making good marriages.'),
(1427, '227859', 'en', 'https://image.tmdb.org/t/p/w500/yk8xDUbvnJIElgnkW3YZ3eAwiLO.jpg', 'The Book of Daniel', '45.134', '2013-10-01', 7.2, '54', '[\'Fantasy\', \'Drama\']', 'Taken into slavery after the fall of Jerusalem in 605 B.C., Daniel is forced to serve the most powerful king in the world, King Nebuchadnezzar. Faced with imminent death, Daniel proves himself a trusted Advisor and is placed among the king\'s wise men. Threatened by death at every turn Daniel never ceases to serve the king until he is forced to choose between serving the king or honoring God. With his life at stake, Daniel has nothing but his faith to stand between him and the lions den.'),
(1428, '532321', 'ja', 'https://image.tmdb.org/t/p/w500/y7XwmyE5ue9hjk65fEWpO2hGU2B.jpg', 'Re:ゼロから始める異世界生活 Memory Snow', '46.774', '2018-10-06', 7, '119', '[\'Animation\', \'Adventure\', \'Fantasy\']', 'Subaru and friends finally get a moment of peace, and Subaru goes on a certain secret mission that he must not let anyone find out about! However, even though Subaru is wearing a disguise, Petra and other children of the village immediately figure out who he is. Now that his mission was exposed within five seconds of it starting, what will happen with Subaru\'s \"date course\" with Emilia?'),
(1429, '1427', 'en', 'https://image.tmdb.org/t/p/w500/2wrFrUej8ri5EpjgIkjKTAnr686.jpg', 'Perfume: The Story of a Murderer', '41.258', '2006-09-13', 7.3, '3414', '[\'Crime\', \'Fantasy\', \'Drama\']', 'Jean-Baptiste Grenouille, born in the stench of 18th century Paris, develops a superior olfactory sense, which he uses to create the world\'s finest perfumes. However, his work takes a dark turn as he tries to preserve scents in the search for the ultimate perfume.'),
(1430, '173185', 'fr', 'https://image.tmdb.org/t/p/w500/7PbiUzPjM6ZvD9sGppBtdLcDdwx.jpg', '20 ans d\'écart', '45.009', '2013-03-06', 6.3, '940', '[\'Comedy\']', 'Alice Lantins is 38, ambitious and so committed to her work that she neglects her personal life.  In short, she is the ideal candidate for the next editor of the magazine Rebelle, or would be were it not for the fact that she appears to be stuck in a rut.  When Balthazar, a charming 20-year-old, crosses her path, her colleagues begin to see her in a whole new light...'),
(1431, '1691', 'en', 'https://image.tmdb.org/t/p/w500/qB20aiY8Ah3pQikkBxm3j7jQVc8.jpg', 'Hostel: Part II', '43.498', '2007-06-08', 5.8, '1481', '[\'Horror\']', 'Three American college students studying abroad are lured to a Slovakian hostel, and discover the grim reality behind it.'),
(1432, '381719', 'en', 'https://image.tmdb.org/t/p/w500/lugOvdaNpbVGQK9TyMRDiUbLtY6.jpg', 'Peter Rabbit', '40.245', '2018-02-07', 6.7, '1332', '[\'Animation\', \'Adventure\', \'Family\']', 'Peter Rabbit\'s feud with Mr. McGregor escalates to greater heights than ever before as they rival for the affections of the warm-hearted animal lover who lives next door.'),
(1433, '256835', 'en', 'https://image.tmdb.org/t/p/w500/kVOaFo8RaYQceHfTqbZGmV9R80q.jpg', 'Toy Story That Time Forgot', '42.684', '2014-12-02', 7, '748', '[\'Animation\', \'Family\', \'TV Movie\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'During a post-Christmas play date, the gang find themselves in uncharted territory when the coolest set of action figures ever turn out to be dangerously delusional. It\'s all up to Trixie, the triceratops, if the gang hopes to return to Bonnie\'s room in this Toy Story That Time Forgot.'),
(1434, '431580', 'en', 'https://image.tmdb.org/t/p/w500/20djTLqppfBx5WYA67Y300S6aPD.jpg', 'Abominable', '38.75', '2019-09-19', 7.6, '1520', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\']', 'A group of misfits encounter a young Yeti named Everest, and they set off to reunite the magical creature with his family on the mountain of his namesake.'),
(1435, '136400', 'en', 'https://image.tmdb.org/t/p/w500/ptURGAFktibhk7DEAbMazlmNqWa.jpg', '2 Guns', '46.629', '2013-08-02', 6.5, '3276', '[\'Action\', \'Comedy\', \'Crime\']', 'A DEA agent and an undercover Naval Intelligence officer who have been tasked with investigating one another find they have been set up by the mob -- the very organization the two men believe they have been stealing money from.'),
(1436, '288985', 'it', 'https://image.tmdb.org/t/p/w500/o6vDV0RjXW1XL1Huy8yY69YrI9l.jpg', 'Le Porno Killers', '50.403', '1980-04-20', 3.5, '6', '[\'Crime\', \'Action\']', 'An international drugs deal goes wrong, and two New York hit-women are dispatched to Rome, Italy, to get the missing pay money. Even before departure the girls (Carmen Russo and Cintia Lodetti) have a poolside hot party with two young men, and when they get to their hotel in Rome, they share a shower and an intimate moment together. At the beach, they make eye contact with a pair of Italian gigolos, then use judo and wrestling holds to dominate them - and impose their feminist supremacy. Finally, they will get close to the money, but their mission is made easier as the top men are fighting each other for it (Vassili Karis) and Mario Cutini).'),
(1437, '578', 'en', 'https://image.tmdb.org/t/p/w500/tjbLSFwi0I3phZwh8zoHWNfbsEp.jpg', 'Jaws', '44.071', '1975-06-18', 7.6, '7849', '[\'Horror\', \'Thriller\', \'Adventure\']', 'When an insatiable great white shark terrorizes the townspeople of Amity Island, the police chief, an oceanographer and a grizzled shark hunter seek to destroy the blood-thirsty beast.'),
(1438, '58224', 'en', 'https://image.tmdb.org/t/p/w500/jGwZ1QI5DaL7mHQ2ZsMV1p8xvPS.jpg', 'Mr. Popper\'s Penguins', '45.073', '2011-06-17', 5.9, '2306', '[\'Comedy\', \'Family\']', 'Jim Carrey stars as Tom Popper, a successful businessman who’s clueless when it comes to the really important things in life...until he inherits six “adorable” penguins, each with its own unique personality. Soon Tom’s rambunctious roommates turn his swank New York apartment into a snowy winter wonderland — and the rest of his world upside-down.'),
(1439, '18126', 'en', 'https://image.tmdb.org/t/p/w500/nZUKhfpUCFfTy24LGBHdDlK5RLx.jpg', 'Hannah Montana: The Movie', '43.117', '2009-04-10', 6.6, '1662', '[\'Comedy\', \'Drama\', \'Family\', \'Music\', \'Romance\']', 'When Miley Stewart (aka pop-star Hannah Montana) gets too caught up in the superstar celebrity lifestyle, her dad decides it\'s time for a total change of scenery. But sweet niblets! Miley must trade in all the glitz and glamour of Hollywood for some ol\' blue jeans on the family farm in Tennessee, and question if she can be both Miley Stewart and Hannah Montana.'),
(1440, '10607', 'en', 'https://image.tmdb.org/t/p/w500/HZQBF7JDd2e9p4rPSbSHuWHaCC.jpg', 'Don\'t Be a Menace to South Central While Drinking Your Juice in the Hood', '46.962', '1996-01-12', 6.9, '820', '[\'Comedy\']', 'When Ashtray (Shawn Wayans) moves to South Central L.A. to live with his father (who appears to be the same age he is) and grandmother (who likes to talk tough and smoke reefer), he falls in with his gang-banging cousin Loc Dog (Marlon Wayans), who along with the requisite pistols and Uzi carries a thermo-nuclear warhead for self-defense. Will Ashtray be able to keep living the straight life?'),
(1441, '189', 'en', 'https://image.tmdb.org/t/p/w500/50kALxDX4mmzIRljbNbPY0u4cie.jpg', 'Sin City: A Dame to Kill For', '46.493', '2014-08-20', 6.4, '3051', '[\'Crime\', \'Action\', \'Thriller\']', 'Some of Sin City\'s most hard-boiled citizens cross paths with a few of its more reviled inhabitants.'),
(1442, '59429', 'ja', 'https://image.tmdb.org/t/p/w500/mh7j7XlYWo82UnQGhsxcuyolzp.jpg', 'パラノーマル・アクティビティ 第2章 TOKYO NIGHT', '45.956', '2010-11-20', 6, '314', '[\'Horror\', \'Thriller\']', 'This Japan production spins-off the story of the first Paranormal Activity film by having the ghost from the first film follow a student back to her homeland after a visit to San Diego where she is tragically injured during a car accident. Back home in Japan, she is cared for by her brother, Koichi, who begins to suspect that something is amiss when his sister\'s wheelchair begins to move on its own. From there, the picture takes on the usual candid cam shocks of the series. Tokyo Night is notable for being an official part of the franchise (it was released in Japan two days before Paranormal Activity 2\'s release in the States), even though the U.S. has yet to see an official release.'),
(1443, '19185', 'en', 'https://image.tmdb.org/t/p/w500/7WkSCClUvcAq8JNEp4pM4A9hiDU.jpg', 'Night of the Living Dead', '48.201', '1990-10-19', 6.8, '624', '[\'Horror\']', 'In this remake of the original classic film, a group of people are trapped inside a farmhouse as legions of the walking dead try to get inside and use them for food.'),
(1444, '77174', 'en', 'https://image.tmdb.org/t/p/w500/9DZPtuYTKYxt6vzHvZ5FLThG4fl.jpg', 'ParaNorman', '41.953', '2012-08-03', 6.9, '1969', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\']', 'In the town of Blithe Hollow, Norman Babcock can speak to the dead, but no one other than his eccentric new friend believes his ability is real. One day, Norman\'s eccentric uncle tells him of a ritual he must perform to protect the town from a curse cast by a witch centuries ago.'),
(1445, '111', 'en', 'https://image.tmdb.org/t/p/w500/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', 'Scarface', '51.541', '1983-12-09', 8.2, '8701', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'After getting a green card in exchange for assassinating a Cuban government official, Tony Montana stakes a claim on the drug trade in Miami. Viciously murdering anyone who stands in his way, Tony eventually becomes the biggest drug lord in the state, controlling nearly all the cocaine that comes through Miami. But increased pressure from the police, wars with Colombian drug cartels and his own drug-fueled paranoia serve to fuel the flames of his eventual downfall.'),
(1446, '38', 'en', 'https://image.tmdb.org/t/p/w500/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg', 'Eternal Sunshine of the Spotless Mind', '39.787', '2004-03-19', 8.1, '11601', '[\'Science Fiction\', \'Drama\', \'Romance\']', 'Joel Barish, heartbroken that his girlfriend underwent a procedure to erase him from her memory, decides to do the same. However, as he watches his memories of her fade away, he realises that he still loves her, and may be too late to correct his mistake.'),
(1447, '550', 'en', 'https://image.tmdb.org/t/p/w500/pB8BM7pdSp6B6Ih7QZ4DrQ3PmJK.jpg', 'Fight Club', '47.081', '1999-10-15', 8.4, '22758', '[\'Drama\']', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground \"fight clubs\" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.'),
(1448, '390734', 'ja', 'https://image.tmdb.org/t/p/w500/xGMgspge6uYoypRiasAmlluDlXH.jpg', 'キングスグレイブ ファイナルファンタジーXV', '47.936', '2016-07-09', 6.8, '516', '[\'Animation\', \'Science Fiction\', \'Action\']', 'The magical kingdom of Lucis is home to the world’s last remaining Crystal, and the menacing empire of Niflheim is determined to steal it. King Regis of Lucis commands an elite force of soldiers called the Kingsglaive. Wielding their king’s magic, they fight to protect Lucis. As the overwhelming military might of the empire bears down, King Regis is faced with an impossible ultimatum – to marry his son, Prince Noctis to Princess Lunafreya of Tenebrae, captive of Niflheim, and surrender his lands to Niflheim rule.  Although the king concedes, it becomes clear that the empire will stop at nothing to achieve their devious goals, with only the Kingsglaive standing between them and world domination.'),
(1449, '73723', 'en', 'https://image.tmdb.org/t/p/w500/tePFnZFw5JvjwjQjaKkqDPNMLPU.jpg', 'The Lorax', '44.327', '2012-03-01', 6.5, '2643', '[\'Animation\', \'Family\']', 'A 12-year-old boy searches for the one thing that will enable him to win the affection of the girl of his dreams. To find it he must discover the story of the Lorax, the grumpy yet charming creature who fights to protect his world.'),
(1450, '454527', 'fr', 'https://image.tmdb.org/t/p/w500/yofVXmLYQbr8pdOeyDRrf9N8rF4.jpg', 'Benedetta', '66.927', '2021-07-09', 6.7, '123', '[\'Drama\', \'History\', \'Romance\']', 'In the late 17th century, with plague ravaging the land, Benedetta Carlini joins the convent in Pescia, Tuscany, as a novice. Capable from an early age of performing miracles, Benedetta’s impact on life in the community is immediate and momentous.'),
(1451, '181533', 'en', 'https://image.tmdb.org/t/p/w500/xwgy305K6qDs3D20xUO4OZu1HPY.jpg', 'Night at the Museum: Secret of the Tomb', '43.085', '2014-12-17', 6.2, '4820', '[\'Adventure\', \'Comedy\', \'Fantasy\', \'Family\']', 'When the magic powers of The Tablet of Ahkmenrah begin to die out, Larry Daley spans the globe, uniting favorite and new characters while embarking on an epic quest to save the magic before it is gone forever.'),
(1452, '146216', 'en', 'https://image.tmdb.org/t/p/w500/tbksijr6g340yFWRgI4JfwrtM9h.jpg', 'RED 2', '48.374', '2013-07-18', 6.5, '3256', '[\'Action\', \'Comedy\', \'Crime\', \'Thriller\']', 'Retired C.I.A. agent Frank Moses reunites his unlikely team of elite operatives for a global quest to track down a missing portable nuclear device.'),
(1453, '7131', 'en', 'https://image.tmdb.org/t/p/w500/gsFun8nATm52aGHeT8ueAel98nE.jpg', 'Van Helsing', '40.618', '2004-05-05', 6.3, '4569', '[\'Horror\', \'Adventure\', \'Action\']', 'Famed monster slayer Gabriel Van Helsing is dispatched to Transylvania to assist the last of the Valerious bloodline in defeating Count Dracula. Anna Valerious reveals that Dracula has formed an unholy alliance with Dr. Frankenstein\'s monster and is hell-bent on exacting a centuries-old curse on her family.'),
(1454, '471506', 'en', 'https://image.tmdb.org/t/p/w500/9hBpFyJ3pGdupXbaC2L7nGvLMBn.jpg', 'Greta', '44.682', '2019-02-28', 6.6, '918', '[\'Drama\', \'Mystery\', \'Thriller\', \'Horror\']', 'A young woman returns an elderly widow’s lost purse, leading to an unlikely relationship between the two — until the young woman discovers her elder might not be all that she seems.'),
(1455, '445030', 'ja', 'https://image.tmdb.org/t/p/w500/sfNZ6G7l3cFI57LVfxnNGse7ihA.jpg', 'ノーゲーム・ノーライフ ゼロ', '61.17', '2017-07-15', 7.9, '257', '[\'Animation\', \'Action\', \'Drama\']', 'In ancient Disboard, Riku is an angry, young warrior intent on saving humanity from the warring Exceed, the sixteen sentient species, fighting to establish the \"One True God\" amongst the Old Deus. In a lawless land, humanity\'s lack of magic and weak bodies have made them easy targets, leaving them on the brink of extinction. One day, hope returns to humanity when Riku finds a powerful female Ex-machina, whom he names Schwi. Exiled from her Cluster because of her research into human emotions, Schwi is convinced that humanity has only survived due to the power of these feelings. Forming an unlikely partnership in the midst of the overwhelming chaos, Riku and Schwi must now find the answers to their individual shortcomings in each other, and discover for themselves what it truly means to be human as they fight for their lives against all odds. Each with a powerful new ally in tow, it is now up to them to prevent the extinction of the human race and establish peace throughout Disboard!'),
(1456, '440', 'en', 'https://image.tmdb.org/t/p/w500/5iTwPDNtvK6ZZF607BHBbU3HO0B.jpg', 'Aliens vs Predator: Requiem', '45.109', '2007-12-25', 5.1, '2050', '[\'Fantasy\', \'Action\', \'Science Fiction\', \'Thriller\', \'Horror\']', 'The iconic creatures from two of the scariest film franchises in movie history wage their most brutal battle ever—in our own backyard. The small town of Gunnison, Colorado becomes a war zone between two of the deadliest extra-terrestrial life forms—the Alien and the Predator. When a Predator scout ship crash-lands in the hills outside the town, Alien Facehuggers and a hybrid Alien/Predator are released and begin to terrorize the town.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1457, '350312', 'te', 'https://image.tmdb.org/t/p/w500/21sC2assImQIYCEDA84Qh9d1RsK.jpg', 'బాహుబలి 2: ది కన్ క్లూజన్', '44.163', '2017-04-27', 7.3, '493', '[\'Action\', \'Adventure\', \'Drama\']', 'When Mahendra, the son of Bāhubali, learns about his heritage, he begins to look for answers. His story is juxtaposed with past events that unfolded in the Mahishmati Kingdom.'),
(1458, '448969', 'ja', 'https://image.tmdb.org/t/p/w500/ewSs8KMJDme2LxkFxlp2K35jBOt.jpg', '劇場版「黒子のバスケ」ウインターカップ総集編～扉の向こう～', '46.997', '2016-12-03', 7.2, '3', '[\'Animation\']', 'The third of three Kuroko no Basket compilation films.'),
(1459, '419680', 'en', 'https://image.tmdb.org/t/p/w500/rF2IoKL0IFmumEXQFUuB8LajTYP.jpg', 'Daddy\'s Home 2', '44.656', '2017-11-09', 6.2, '1949', '[\'Comedy\']', 'Brad and Dusty must deal with their intrusive fathers during the holidays.'),
(1460, '136835', 'en', 'https://image.tmdb.org/t/p/w500/wcDLqCS70LsPcovieuQrb311Qr1.jpg', 'No Good Deed', '49.209', '2014-09-10', 6, '506', '[\'Crime\', \'Thriller\']', 'Terri is a devoted wife and mother of two, living an ideal suburban life in Atlanta when Colin, a charming but dangerous escaped convict, shows up at her door claiming car trouble. Terri offers her phone to help him but soon learns that no good deed goes unpunished as she finds herself fighting for survival when he invades her home and terrorizes her family.'),
(1461, '1091', 'en', 'https://image.tmdb.org/t/p/w500/tzGY49kseSE9QAKk47uuDGwnSCu.jpg', 'The Thing', '41.831', '1982-06-25', 8, '4916', '[\'Horror\', \'Mystery\', \'Science Fiction\']', 'Members of an American scientific research outpost in Antarctica find themselves battling a parasitic alien organism capable of perfectly imitating its victims. They soon discover that this task will be harder than they thought, as they don\'t know which members of the team have already been assimilated and their paranoia threatens to tear them apart.'),
(1462, '339964', 'en', 'https://image.tmdb.org/t/p/w500/vlc95gl3PtrjxSEuM8RhTtSm2xU.jpg', 'Valerian and the City of a Thousand Planets', '41.038', '2017-07-20', 6.6, '6085', '[\'Adventure\', \'Science Fiction\', \'Action\']', 'In the 28th century, Valerian and Laureline are special operatives charged with keeping order throughout the human territories. On assignment from the Minister of Defense, the two undertake a mission to Alpha, an ever-expanding metropolis where species from across the universe have converged over centuries to share knowledge, intelligence, and cultures. At the center of Alpha is a mysterious dark force which threatens the peaceful existence of the City of a Thousand Planets, and Valerian and Laureline must race to identify the menace and safeguard not just Alpha, but the future of the universe.'),
(1463, '11359', 'en', 'https://image.tmdb.org/t/p/w500/ozQAmW85tTJu2dhRe3evzyY03Nb.jpg', 'The Indian in the Cupboard', '45.873', '1995-07-14', 6.4, '458', '[\'Adventure\', \'Family\', \'Fantasy\']', 'A nine-year-old boy gets a plastic Indian and a cupboard for his birthday and finds himself involved in adventure when the Indian comes to life and befriends him.'),
(1464, '82633', 'en', 'https://image.tmdb.org/t/p/w500/Ahtzwts22ayviD3LEVslfL4nRWB.jpg', 'Lawless', '46.626', '2012-08-29', 7, '2415', '[\'Crime\', \'Drama\', \'Western\']', 'Set in the Depression-era Franklin County, Virginia, a bootlegging gang is threatened by authorities who want a cut of their profits.'),
(1465, '12155', 'en', 'https://image.tmdb.org/t/p/w500/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg', 'Alice in Wonderland', '52.422', '2010-03-03', 6.6, '11651', '[\'Family\', \'Fantasy\', \'Adventure\']', 'Alice, now 19 years old, returns to the whimsical world she first entered as a child and embarks on a journey to discover her true destiny.'),
(1466, '454699', 'en', 'https://image.tmdb.org/t/p/w500/3kZ1RrEbm6yMTcYi6jugfC51HLb.jpg', 'Happy Family', '42.877', '2018-02-09', 5.8, '229', '[\'Animation\', \'Family\', \'Fantasy\', \'Comedy\']', 'The Wishbone family are far from happy. In an attempt to reconnect as a family, they plan a fun night out. However, the plan backfires when they are cursed and all turned into Monsters.'),
(1467, '487297', 'en', 'https://image.tmdb.org/t/p/w500/30IiwvIRqPGjUV0bxJkZfnSiCL.jpg', 'What Men Want', '40.323', '2019-02-08', 6.2, '1065', '[\'Comedy\', \'Romance\']', 'Magically able to hear what men are thinking, a sports agent uses her newfound ability to turn the tables on her overbearing male colleagues.'),
(1468, '8275', 'en', 'https://image.tmdb.org/t/p/w500/6CPJVJrqVjibP5Uub8yCg4FKtJi.jpg', 'American Pie Presents: The Naked Mile', '51.553', '2006-12-07', 5.5, '1594', '[\'Comedy\']', 'When Erik Stifler realizes that he\'s the only Stifler family member who might graduate high school a virgin, he decides to live up to his legacy. After some well-meaning advice from Jim\'s dad, Erik\'s ready to take his chances at the annual and infamous Naked Mile race, where his devoted friends and some uninhibited sorority girls will create the most outrageous weekend ever.'),
(1469, '414906', 'en', 'https://image.tmdb.org/t/p/w500/74xTEgt7R36Fpooo50r9T25onhq.jpg', 'The Batman', '41.519', '2022-03-02', 0, '0', '[\'Action\', \'Crime\', \'Drama\']', 'The Batman is an edgy, action-packed thriller that depicts Batman in his early years, struggling to balance rage with righteousness as he investigates a disturbing mystery that has terrorized Gotham. Robert Pattinson delivers a raw, intense portrayal of Batman as a disillusioned, desperate vigilante awakened by the realization that the anger consuming him makes him no better than the ruthless serial killer he’s hunting.'),
(1470, '741228', 'en', 'https://image.tmdb.org/t/p/w500/svHelD0Hb3TXPAQoPsoBwdDMTvf.jpg', 'Locked Down', '43.92', '2021-02-25', 5.5, '129', '[\'Comedy\', \'Crime\', \'Drama\']', 'During a COVID-19 lockdown, sparring couple Linda and Paxton call a truce to attempt a high-risk jewellery heist at one of the world\'s most exclusive department stores, Harrods.'),
(1471, '34134', 'en', 'https://image.tmdb.org/t/p/w500/jtOlo3AaXVBnqfMeKGFrZUMPFui.jpg', 'Barbie in A Mermaid Tale', '45.1', '2010-01-25', 7.2, '544', '[\'Animation\', \'Family\', \'Fantasy\']', 'Barbie stars as Merliah, a surfer who learns a shocking secret: she\'s a mermaid! She and her dolphin friend set out for an undersea adventure to rescue her mother, the queen of Oceana.'),
(1472, '508763', 'en', 'https://image.tmdb.org/t/p/w500/pZn87R7gtmMCGGO8KeaAfZDhXLg.jpg', 'A Dog\'s Way Home', '42.613', '2019-01-10', 7.2, '766', '[\'Drama\', \'Adventure\', \'Family\']', 'The adventure of Bella, a dog who embarks on an epic 400-mile journey home after she is separated from her beloved human.'),
(1473, '618416', 'en', 'https://image.tmdb.org/t/p/w500/5l6k0Z9tYddXW9327V2jZrfWG00.jpg', 'Penguin Bloom', '38.158', '2021-01-21', 7.1, '140', '[\'Drama\']', 'When an unlikely ally enters the Bloom family\'s world in the form of an injured baby magpie they name Penguin, the bird’s arrival makes a profound difference in the struggling family’s life.'),
(1474, '204450', 'de', 'https://image.tmdb.org/t/p/w500/4dmbrgm0E9LsO2qYYrBui0z1BCP.jpg', 'Lesbian Love', '42.359', '2012-01-08', 8.5, '17', '[]', 'Experience the hot lovemaking beautiful women among them! This film takes you into the world of lesbian love in all its beauty and lets secret fantasies come true men. Be close to the action when women indulge your passionate desire and suddenly sexual playmates of girlfriends.'),
(1475, '466272', 'en', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', 'Once Upon a Time… in Hollywood', '47.364', '2019-07-24', 7.5, '9524', '[\'Comedy\', \'Drama\', \'Thriller\']', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…'),
(1476, '419743', 'en', 'https://image.tmdb.org/t/p/w500/skPT4ffWhlmmDOMNEdxOiP6Emfz.jpg', 'Disobedience', '41.103', '2017-09-10', 7, '866', '[\'Drama\', \'Romance\']', 'A woman learns about the death of her Orthodox Jewish father, a rabbi. She returns home and has romantic feelings rekindled for her best childhood friend, who is now married to her cousin.'),
(1477, '638449', 'en', 'https://image.tmdb.org/t/p/w500/fDKK51YdOfu9pTmSRw7sHUhGFxm.jpg', 'The Last Letter From Your Lover', '44.262', '2021-07-23', 7.6, '319', '[\'Drama\', \'Romance\']', 'A young journalist in London becomes obsessed with a series of letters she discovers that recounts an intense star-crossed love affair from the 1960s.'),
(1478, '25195', 'en', 'https://image.tmdb.org/t/p/w500/i86hMi5iEF3WnYLCaGHdT5FPdYg.jpg', 'Leap Year', '50.342', '2010-01-08', 6.9, '1617', '[\'Romance\', \'Comedy\']', 'When yet another anniversary passes without a marriage proposal from her boyfriend, Anna decides to take action. Aware of a Celtic tradition that allows women to pop the question on Feb. 29, she plans to follow her lover to Dublin and ask him to marry her. Fate has other plans, however, and Anna winds up on the other side of the Emerald Isle with handsome, but surly, Declan -- an Irishman who may just lead Anna down the road to true love.'),
(1479, '826733', 'es', 'https://image.tmdb.org/t/p/w500/e3cB8J1ntlrCfrVJEJaOOOlhF5c.jpg', 'El cover', '39.186', '2021-07-23', 6.8, '31', '[\'Comedy\', \'Romance\', \'Music\']', 'In Benidorm, a mecca for impersonators of live singers, Dani doesn\'t want to be just a cover. He will meet Sandra and discover authenticity, love and what it means not to be one more.'),
(1480, '799497', 'pt', 'https://image.tmdb.org/t/p/w500/rzcdLb0BhPaUJjD2jEcfRMiwOgh.jpg', 'Cabras da Peste', '50.362', '2021-03-18', 7, '151', '[\'Action\', \'Comedy\', \'Crime\']', 'Bruceuilis, a policeman from the countryside, is assigned to rescue Celestina, a goat considered heritage of his small city, and travels to São Paulo. There, he meets police clerk Trindade, who decides to venture out into the field, even though it is not his specialty.'),
(1481, '218043', 'en', 'https://image.tmdb.org/t/p/w500/b9Q2WR62yB5Aq0hd6kyRFS9cc3Y.jpg', 'Left Behind', '44.785', '2014-10-03', 4.2, '1046', '[\'Thriller\', \'Action\', \'Science Fiction\']', 'A small group of survivors are left behind after millions of people suddenly vanish during the rapture and the world is plunged into chaos and destruction.'),
(1482, '28178', 'en', 'https://image.tmdb.org/t/p/w500/lsy3aEsEfYIHdLRk4dontZ4s85h.jpg', 'Hachi: A Dog\'s Tale', '42.535', '2009-06-13', 8, '5344', '[\'Drama\', \'Family\']', 'A drama based on the true story of a college professor\'s bond with the abandoned dog he takes into his home.'),
(1483, '604', 'en', 'https://image.tmdb.org/t/p/w500/aA5qHS0FbSXO8PxcxUIHbDrJyuh.jpg', 'The Matrix Reloaded', '49.731', '2003-05-15', 7, '8263', '[\'Adventure\', \'Action\', \'Thriller\', \'Science Fiction\']', 'Six months after the events depicted in The Matrix, Neo has proved to be a good omen for the free humans, as more and more humans are being freed from the matrix and brought to Zion, the one and only stronghold of the Resistance.  Neo himself has discovered his superpowers including super speed, ability to see the codes of the things inside the matrix and a certain degree of pre-cognition. But a nasty piece of news hits the human resistance: 250,000 machine sentinels are digging to Zion and would reach them in 72 hours. As Zion prepares for the ultimate war, Neo, Morpheus and Trinity are advised by the Oracle to find the Keymaker who would help them reach the Source.  Meanwhile Neo\'s recurrent dreams depicting Trinity\'s death have got him worried and as if it was not enough, Agent Smith has somehow escaped deletion, has become more powerful than before and has fixed Neo as his next target.'),
(1484, '726208', 'es', 'https://image.tmdb.org/t/p/w500/lXvBgevABC9n5R6Gg76R3pN1h2M.jpg', 'Voces', '36.064', '2020-07-24', 6.6, '521', '[\'Drama\', \'Horror\', \'Thriller\']', 'After the strange death of his young son at their new home, Daniel hears a ghostly plea for help, spurring him to seek out a renowned paranormal expert.'),
(1485, '761898', 'ja', 'https://image.tmdb.org/t/p/w500/yD9RhgIVydQNBK7OLEbCWYcWMUd.jpg', '劇場版 ソードアート・オンライン プログレッシブ 星なき夜のアリア', '41.814', '2021-10-30', 8, '1', '[\'Animation\', \'Action\', \'Fantasy\', \'Science Fiction\']', 'One month after Kayaba Akihiko\'s game of death began, the death toll continues to rise, two thousand players having already lost their lives to the ultra-difficult VRMMO world of Sword Art Online. On the day of the strategy meeting to plan out the first-floor boss battle, Kirito, a solo player who vows to fight alone to get stronger, runs into a rare, high-level female player. She gracefully dispatches powerful monsters with a single rapier that flashes like a shooting star in the night...'),
(1486, '11284', 'en', 'https://image.tmdb.org/t/p/w500/e4qh58n2WaG4Gyh9VhjOUeN9Mhv.jpg', 'Freddy\'s Dead: The Final Nightmare', '46.271', '1991-09-05', 5.3, '907', '[\'Horror\', \'Thriller\', \'Comedy\']', 'Just when you thought it was safe to sleep, Freddy Krueger returns in this sixth installment of the Nightmare on Elm Street films, as psychologist Maggie Burroughs, tormented by recurring nightmares, meets a patient with the same horrific dreams. Their quest for answers leads to a certain house on Elm Street -- where the nightmares become reality.'),
(1487, '152259', 'en', 'https://image.tmdb.org/t/p/w500/lA1CRLLy3mA5bbut4g3u3CKBrZX.jpg', 'Phantom', '38.822', '2013-01-03', 5.9, '234', '[\'Thriller\']', 'The haunted Captain of a Soviet submarine holds the fate of the world in his hands. Forced to leave his family behind, he is charged with leading a covert mission cloaked in mystery.'),
(1488, '401469', 'en', 'https://image.tmdb.org/t/p/w500/d31SGJSaX29ba5ZUbZcesGoDE7I.jpg', 'Widows', '30.429', '2018-11-06', 6.5, '1783', '[\'Crime\', \'Thriller\']', 'A police shootout leaves four thieves dead during an explosive armed robbery attempt in Chicago. Their widows have nothing in common except a debt left behind by their spouses\' criminal activities. Hoping to forge a future on their own terms, they join forces to pull off a heist.'),
(1489, '10545', 'en', 'https://image.tmdb.org/t/p/w500/hImMgT9B27evYSRmfztqdDtX6qi.jpg', 'The Hunchback of Notre Dame', '53.008', '1996-06-21', 7.1, '3982', '[\'Drama\', \'Animation\', \'Family\']', 'At the urging of his gargoyle pals, Quasimodo leaves the solitary safety of his Notre Dame tower against the wishes of his guardian, the evil Judge Claude Frollo. He ventures out to the Festival of Fools and finds his first true friend, a Romani woman named Esmeralda, who entrusts him with a secret. When the secret is revealed, Quasi soon finds himself fighting to save the people and city he loves.'),
(1490, '256040', 'te', 'https://image.tmdb.org/t/p/w500/9BAjt8nSSms62uOVYn1t3C3dVto.jpg', 'బాహుబలి:ద బిగినింగ్', '46.762', '2015-07-10', 7.5, '537', '[\'Action\', \'Drama\']', 'The young Shivudu is left as a foundling in a small village by his mother. By the time he’s grown up, it has become apparent that he possesses exceptional gifts. He meets the beautiful warrior princess Avanthika and learns that her queen has been held captive for the last 25 years. Shividu sets off to rescue her, discovering his own origins in the process.'),
(1491, '565', 'en', 'https://image.tmdb.org/t/p/w500/AeRpUynJKDpJveklBJipOYrVxCS.jpg', 'The Ring', '41.105', '2002-10-18', 6.6, '4776', '[\'Horror\', \'Mystery\']', 'It sounded like just another urban legend: A videotape filled with nightmarish images, leading to a phone call foretelling the viewer\'s death in exactly seven days. As a newspaper reporter, Rachel Keller was naturally skeptical of the story, until four teenagers all met with mysterious deaths exactly one week after watching just such a tape. Allowing her investigative curiosity to get the better of her, Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring.'),
(1492, '10229', 'en', 'https://image.tmdb.org/t/p/w500/8lUYMvWdHA0Q0k5F76RQCeCBUkA.jpg', 'A Walk to Remember', '43.904', '2002-01-25', 7.7, '3369', '[\'Drama\', \'Romance\']', 'When the popular, restless Landon Carter is forced to participate in the school drama production he falls in love with Jamie Sullivan, the daughter of the town\'s minister. Jamie has a \"to-do\" list for her life and also a very big secret she must keep from Landon.'),
(1493, '76285', 'en', 'https://image.tmdb.org/t/p/w500/tAu90qEpLqwqiZLsMqpaMVr55oN.jpg', 'Percy Jackson: Sea of Monsters', '47.554', '2013-08-07', 6, '4278', '[\'Adventure\', \'Family\', \'Fantasy\']', 'In their quest to confront the ultimate evil, Percy and his friends battle swarms of mythical creatures to find the mythical Golden Fleece and to stop an ancient evil from rising.'),
(1494, '769', 'en', 'https://image.tmdb.org/t/p/w500/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', 'GoodFellas', '37.4', '1990-09-12', 8.5, '9475', '[\'Drama\', \'Crime\']', 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.'),
(1495, '119892', 'zh', 'https://image.tmdb.org/t/p/w500/p9Atjcbidu4DsM7EQltiTZbrvkM.jpg', '西遊記之大鬧天宮', '37.802', '2014-01-09', 5.6, '152', '[\'Action\', \'Adventure\', \'Family\']', 'Sun Wukong is a monkey born from a heavenly stone who acquires supernatural powers. After rebelling against heaven and being imprisoned under a mountain for 500 years, he later accompanies the monk Xuanzang on a journey to India. Thus, according to legend, Buddhism is brought to ancient China.'),
(1496, '659986', 'en', 'https://image.tmdb.org/t/p/w500/zMUpzTRF4f4MkScDkUZM030H2t0.jpg', 'The Owners', '38.084', '2020-08-27', 5.8, '215', '[\'Thriller\', \'Horror\']', 'A group of friends think they found the perfect easy score - an empty house with a safe full of cash. But when the elderly couple that lives there comes home early, the tables are suddenly turned. As a deadly game of cat and mouse ensues, the would-be thieves must fight to save themselves from a nightmare they could never have imagined.'),
(1497, '80389', 'en', 'https://image.tmdb.org/t/p/w500/y4IACuEUGkygp2QsZPUEMY5Tlft.jpg', 'Get the Gringo', '43.791', '2012-03-15', 6.5, '1220', '[\'Action\', \'Thriller\', \'Crime\', \'Drama\']', 'A career criminal nabbed by Mexican authorities is placed in a tough prison where he learns to survive with the help of a 9-year-old boy.'),
(1498, '9316', 'th', 'https://image.tmdb.org/t/p/w500/oagqAwp48dMPoCT94yDJUDOCVPi.jpg', 'Ong Bak', '44.28', '2003-01-21', 7.1, '1256', '[\'Action\', \'Thriller\']', 'When the head of a statue sacred to a village is stolen, a young martial artist goes to the big city and finds himself taking on the underworld to retrieve it.'),
(1499, '54138', 'en', 'https://image.tmdb.org/t/p/w500/Aim3kVNh1MPIxPEFeJrl9e9Uf1a.jpg', 'Star Trek Into Darkness', '38.277', '2013-05-05', 7.3, '7728', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'When the crew of the Enterprise is called back home, they find an unstoppable force of terror from within their own organization has detonated the fleet and everything it stands for, leaving our world in a state of crisis.  With a personal score to settle, Captain Kirk leads a manhunt to a war-zone world to capture a one man weapon of mass destruction. As our heroes are propelled into an epic chess game of life and death, love will be challenged, friendships will be torn apart, and sacrifices must be made for the only family Kirk has left: his crew.'),
(1500, '487242', 'en', 'https://image.tmdb.org/t/p/w500/va1IgsZeWBbKLsZcFwz3CM1MkMu.jpg', 'Suicide Squad: Hell to Pay', '42.734', '2018-05-09', 7.2, '425', '[\'Science Fiction\', \'Action\', \'Animation\']', 'Task Force X targets a powerful mystical object that they will risk their lives to steal.'),
(1501, '45781', 'en', 'https://image.tmdb.org/t/p/w500/Af7Vt2GaMDIfzEnrUVJevYk0Kek.jpg', 'Hole in One', '50.048', '2009-09-12', 4.1, '76', '[\'Comedy\']', 'Eric, a highly-gifted golfer but radically-undisciplined college undergrad, finds his world drastically altered after losing a golf bet to a pair of sadistic plastic surgeons. Eric\'s bad-boy attitude lifestyle comes to a screeching halt as he loses his money, his girlfriend, his dignity and his golf swing. Eric and his best friend Tyler decide to take on the doctors, in a final golf match of \"Best-Ball\" to get his life back and become the man he should have been all along.'),
(1502, '460019', 'en', 'https://image.tmdb.org/t/p/w500/ei2waWQAG8NP244WShIFgGu9IOu.jpg', 'Truth or Dare', '41.177', '2018-04-12', 6, '3307', '[\'Thriller\', \'Horror\']', 'A harmless game of \"Truth or Dare\" among friends turns deadly when someone—or something—begins to punish those who tell a lie—or refuse the dare.'),
(1503, '71880', 'en', 'https://image.tmdb.org/t/p/w500/kFeAxmZvu0TE4iuLRHQD6Cej8Wf.jpg', 'Jack and Jill', '35.96', '2011-11-11', 4.3, '1664', '[\'Comedy\']', 'Jack Sadelstein, a successful advertising executive in Los Angeles with a beautiful wife and kids, dreads one event each year: the Thanksgiving visit of his twin sister Jill. Jill\'s neediness and passive-aggressiveness is maddening to Jack, turning his normally tranquil life upside down.'),
(1504, '133121', 'en', 'https://image.tmdb.org/t/p/w500/zkHSURVCrt7rpvDDgUXO75CV1v4.jpg', 'Biohazard: Damnation', '34.254', '2012-09-25', 6.8, '592', '[\'Animation\', \'Horror\', \'Action\']', 'U.S. federal agent Leon S. Kennedy sneaks into the \"East Slavic Republic\" to verify rumors that Bio-Organic Weapons (BOWs) are being used in the country\'s civil war, which the U.S. and Russia are making preparations to jointly intervene in. Right after his infiltration, the U.S. government orders him to leave immediately. Determined to uncover the truth, Leon ignores the order and enters the battlefield to end the chain of tragedies caused by the BOWs.'),
(1505, '621151', 'en', 'https://image.tmdb.org/t/p/w500/9clw9UBQXmi3EFgjgIPGJSluQr7.jpg', 'Spell', '44.798', '2020-10-30', 6.4, '210', '[\'Thriller\', \'Horror\']', 'A father survives a plane crash in rural Appalachia, but becomes suspicious of the elderly couple who take him in to nurse him back to health with the ancient remedies.'),
(1506, '23398', 'en', 'https://image.tmdb.org/t/p/w500/8mdPqOga5fty15nXmaNcK1fsNMa.jpg', 'Alvin and the Chipmunks: The Squeakquel', '50.451', '2009-12-21', 5.7, '2254', '[\'Comedy\', \'Family\', \'Animation\', \'Fantasy\', \'Music\']', 'Pop sensations Alvin, Simon and Theodore end up in the care of Dave Seville\'s twenty-something nephew Toby. The boys must put aside music super stardom to return to school, and are tasked with saving the school\'s music program by winning the $25,000 prize in a battle of the bands. But the Chipmunks unexpectedly meet their match in three singing chipmunks known as The Chipettes - Brittany, Eleanor and Jeanette. Romantic and musical sparks are ignited when the Chipmunks and Chipettes square off.'),
(1507, '840427', 'ro', 'https://image.tmdb.org/t/p/w500/d2aGQwebCkXqNqOVYGqOzPhguCa.jpg', 'Tata mută munții', '44.45', '2021-07-25', 5.9, '51', '[\'Drama\', \'Thriller\']', 'Mircea, former Intelligence officer, finds out that his son from has gone missing in the mountains. He travels there to find him. After days of searches, Mircea put his own rescue team together, leading to conflict with the local squad.'),
(1508, '15015', 'en', 'https://image.tmdb.org/t/p/w500/ysiGzuMSc0nFmmDPn9z7U7YSFYf.jpg', 'Barbie as Rapunzel', '49.239', '2002-10-01', 7, '920', '[\'Animation\', \'Family\']', 'Long, long ago, in a time of magic and dragons, there lived a girl named Rapunzel who had the most beautiful radiant hair the world had ever seen. But Rapunzel\'s life was far from wonderful. She lived as a servant to Gothel, a jealous, scheming witch who kept her hidden deep in a forbidding forest, guarded by the enormous dragon Hugo and surrounded by an enchanted glass wall. However, in a twist of fate, Rapunzel\'s discovery of a magic paintbrush leads her on a journey that will unravel a web of deception, bring peace to two feuding kingdoms, and ultimately lead her to love with the help of Penelope(TM), the least intimidating of dragons!'),
(1509, '15016', 'en', 'https://image.tmdb.org/t/p/w500/sLpCLVQWTU7BI4yAL6kIFM9J3eX.jpg', 'Barbie of Swan Lake', '43.484', '2003-09-27', 7, '869', '[\'Animation\', \'Family\']', 'Barbie as Odette, the young daughter of a baker, follows a unicorn into the Enchanted Forest and is transformed into a swan by an evil wizard intent on defeating the Fairy Queen.'),
(1510, '619432', 'ja', 'https://image.tmdb.org/t/p/w500/iltYXp5YaCNnmuVor4GjRN3o2f3.jpg', '木ノ葉の里の大運動会', '41.663', '2004-08-21', 7.1, '6', '[\'Action\', \'Animation\', \'Comedy\']', 'The genin of Konoha are having a sports day filled with races, obstacle courses and of course the relay and the prize is a paid vacation for the winner. Unfortunately Naruto and his stomach are getting him into trouble again.'),
(1511, '55301', 'en', 'https://image.tmdb.org/t/p/w500/npOXWVoZyl8UrF2wtByHtfmsWSX.jpg', 'Alvin and the Chipmunks: Chipwrecked', '44.731', '2011-12-14', 5.7, '1666', '[\'Comedy\', \'Fantasy\', \'Family\', \'Music\', \'Animation\']', 'Playing around while aboard a cruise ship, the Chipmunks and Chipettes accidentally go overboard and end up marooned in a tropical paradise. They discover their new turf is not as deserted as it seems.'),
(1512, '456740', 'en', 'https://image.tmdb.org/t/p/w500/lbaTEneOofwvAyg77R8HbFML2zT.jpg', 'Hellboy', '48.044', '2019-04-10', 5.5, '2573', '[\'Fantasy\', \'Action\', \'Adventure\', \'Science Fiction\']', 'Hellboy comes to England, where he must defeat Nimue, Merlin\'s consort and the Blood Queen. But their battle will bring about the end of the world, a fate he desperately tries to turn away.'),
(1513, '280092', 'en', 'https://image.tmdb.org/t/p/w500/iDdGfdNvY1EX0uDdA4Ru77fwMfc.jpg', 'Insidious: Chapter 3', '45.625', '2015-06-04', 6.3, '2624', '[\'Horror\', \'Drama\', \'Thriller\']', 'A twisted new tale of terror begins for a teenage girl and her family, and revealing more mysteries of the otherworldly realm, \'The Further\'.'),
(1514, '43539', 'en', 'https://image.tmdb.org/t/p/w500/wBaRZ3aHa7qoYTSY0ONbXrXYk4B.jpg', 'The Next Three Days', '38.721', '2010-11-18', 7.1, '2217', '[\'Romance\', \'Drama\', \'Thriller\', \'Crime\']', 'A married couple\'s life is turned upside down when the wife is accused of murdering her boss. Her husband John would spend the next few years trying to get her released, but there\'s no evidence that negates the evidence against her. When the strain of being separated from her husband and son gets to her, John decides to find a way to break her out.'),
(1515, '348', 'en', 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', 'Alien', '40.367', '1979-05-25', 8.1, '11049', '[\'Horror\', \'Science Fiction\']', 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.'),
(1516, '260372', 'en', 'https://image.tmdb.org/t/p/w500/whbDYXX89fjfP6LgXQbwSJVdPe.jpg', 'Bermuda Tentacles', '42.001', '2014-04-04', 4.1, '51', '[\'Science Fiction\']', 'After Air Force One goes down during a storm over the Bermuda Triangle, the United States Navy is dispatched to find the escape pod holding the President. A giant monster beneath the ocean awakens and attacks the fleet.'),
(1517, '8982', 'th', 'https://image.tmdb.org/t/p/w500/uKE9BxgtT5g2pE3ZKC7MnzsAbTZ.jpg', 'ต้มยำกุ้ง', '50.417', '2005-08-11', 7.1, '593', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'In Bangkok, the young Kham was raised by his father in the jungle with elephants as members of their family. When his old elephant and the baby Kern are stolen by criminals, Kham finds that the animals were sent to Sidney. He travels to Australia, where he locates the baby elephant in a restaurant owned by the evil Madame Rose, the leader of an international Thai mafia. With the support of the efficient Thai sergeant Mark, who was involved in a conspiracy, Kham fights to rescue the animal from the mobsters.'),
(1518, '622855', 'en', 'https://image.tmdb.org/t/p/w500/5RbyHIVydD3Krmec1LlUV7rRjet.jpg', 'Jingle Jangle: A Christmas Journey', '39.013', '2020-11-06', 6.7, '364', '[\'Family\', \'Fantasy\', \'Music\']', 'An imaginary world comes to life in a holiday tale of an eccentric toymaker, his adventurous granddaughter, and a magical invention that has the power to change their lives forever.'),
(1519, '166666', 'de', 'https://image.tmdb.org/t/p/w500/x2bybyGMtyFSVNjFSxeDNu2fnPD.jpg', '3096 Tage', '31.466', '2013-02-21', 7.5, '608', '[\'Drama\']', 'A young Austrian girl is kidnapped and held in captivity for eight years. Based on the real-life case of Natascha Kampusch.'),
(1520, '105', 'en', 'https://image.tmdb.org/t/p/w500/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', 'Back to the Future', '45.149', '1985-07-03', 8.3, '15757', '[\'Adventure\', \'Comedy\', \'Science Fiction\', \'Family\']', 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents\' first meeting and attracting his mother\'s romantic interest. Marty must repair the damage to history by rekindling his parents\' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.'),
(1521, '399402', 'en', 'https://image.tmdb.org/t/p/w500/ng7ukqGaSHOuJZ4GwLJP6AH9ixc.jpg', 'Hunter Killer', '48.414', '2018-10-19', 6.8, '1580', '[\'Action\', \'Thriller\']', 'Captain Glass of the USS Arkansas discovers that a coup d\'état is taking place in Russia, so he and his crew join an elite group working on the ground to prevent a war.'),
(1522, '845222', 'ko', 'https://image.tmdb.org/t/p/w500/piGZDwFW4urLYDWGiYJMrt6hdCS.jpg', '킹덤: 아신전', '45.318', '2021-07-23', 7.6, '319', '[\'Drama\', \'Fantasy\', \'Thriller\']', 'Tragedy, betrayal and a mysterious discovery fuel a woman\'s vengeance for the loss of her tribe and family in this special episode of \"Kingdom.\"'),
(1523, '10010', 'en', 'https://image.tmdb.org/t/p/w500/yaA8q2zHHUgFWdJNxXyAdU71SzM.jpg', 'Brother Bear 2', '45.696', '2006-08-17', 6.7, '1143', '[\'Adventure\', \'Animation\', \'Family\']', 'Kenai finds his childhood human friend Nita and the two embark on a journey to burn the amulet he gave to her before he was a bear, much to Koda\'s dismay.'),
(1524, '707131', 'en', 'https://image.tmdb.org/t/p/w500/6a1iqhfM0Y31kNPOSNPIuPrsYQ6.jpg', 'Polaroid', '61.829', '2019-10-26', 5.3, '4', '[\'Horror\']', 'A mysterious package arrives at a doorstep. The contents inside may determine the fate of whoever opens it.'),
(1525, '82390', 'en', 'https://image.tmdb.org/t/p/w500/AiALtw5Nl4adb6oO4VndBPo3RkQ.jpg', 'The Paperboy', '41.689', '2012-09-14', 5.6, '578', '[\'Thriller\', \'Drama\', \'Mystery\']', 'As investigative reporter Ward Jansen and his partner Yardley Acheman chase a sensational, career-making story with the help of Ward\'s younger brother Jack and sultry death-row groupie Charlotte Bless, the pair tries to prove violent swamp-dweller Hillary Van Wetter was framed for the murder of a corrupt local sheriff.'),
(1526, '809970', 'pl', 'https://image.tmdb.org/t/p/w500/rUX2fGa7OV85c6rtjOC351RVeyD.jpg', 'Hiacynt', '42.269', '2021-08-18', 6.2, '12', '[\'Thriller\']', 'Not satisfied with the result of a murder investigation in Warsaw\'s gay community, an officer in 1980s communist Poland resolves to uncover the truth.'),
(1527, '28', 'en', 'https://image.tmdb.org/t/p/w500/gQB8Y5RCMkv2zwzFHbUJX3kAhvA.jpg', 'Apocalypse Now', '40.634', '1979-08-15', 8.3, '6131', '[\'Drama\', \'War\']', 'At the height of the Vietnam war, Captain Benjamin Willard is sent on a dangerous mission that, officially, \"does not exist, nor will it ever exist.\" His goal is to locate - and eliminate - a mysterious Green Beret Colonel named Walter Kurtz, who has been leading his personal army on illegal guerrilla missions into enemy territory.'),
(1528, '9016', 'en', 'https://image.tmdb.org/t/p/w500/kNhZkR3UNbXfvESQo7mJpOi4tGd.jpg', 'Treasure Planet', '41.384', '2002-11-26', 7.5, '3130', '[\'Adventure\', \'Animation\', \'Family\', \'Fantasy\', \'Science Fiction\']', 'When space galleon cabin boy Jim Hawkins discovers a map to an intergalactic \"loot of a thousand worlds,\" a cyborg cook named John Silver teaches him to battle supernovas and space storms. But, soon, Jim realizes Silver is a pirate intent on mutiny!'),
(1529, '315837', 'en', 'https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', 'Ghost in the Shell', '47.592', '2017-03-29', 6, '6748', '[\'Science Fiction\', \'Action\']', 'In the near future, Major is the first of her kind: a human saved from a terrible crash, then cyber-enhanced to be a perfect soldier devoted to stopping the world\'s most dangerous criminals.'),
(1530, '298250', 'en', 'https://image.tmdb.org/t/p/w500/7RwHxhdUNS996JPFNB9a7CJtlwR.jpg', 'Jigsaw', '43.291', '2017-10-26', 6.2, '2826', '[\'Horror\', \'Crime\', \'Mystery\', \'Thriller\']', 'Dead bodies begin to turn up all over the city, each meeting their demise in a variety of grisly ways. All investigations begin to point the finger at deceased killer John Kramer.'),
(1531, '741998', 'it', 'https://image.tmdb.org/t/p/w500/w5zUq6OgL87MARwReUUXABx1Xeo.jpg', 'Il legame', '40.722', '2020-10-02', 5.5, '177', '[\'Horror\', \'Thriller\', \'Drama\']', 'While visiting her fiancé\'s mother in southern Italy, a woman must fight the mysterious and malevolent curse intent on claiming her daughter.'),
(1532, '614409', 'en', 'https://image.tmdb.org/t/p/w500/iepqdM52f4w75fNcvgRF5QoIAjm.jpg', 'To All the Boys: Always and Forever', '45.436', '2021-02-12', 7.8, '1427', '[\'Romance\', \'Comedy\', \'Drama\']', 'Senior year of high school takes center stage as Lara Jean returns from a family trip to Korea and considers her college plans — with and without Peter.'),
(1533, '18360', 'en', 'https://image.tmdb.org/t/p/w500/l9yAQn6TyrA3gv5xZZkiMMoZsiw.jpg', 'Night at the Museum: Battle of the Smithsonian', '47.516', '2009-05-20', 6.1, '5595', '[\'Adventure\', \'Fantasy\', \'Action\', \'Comedy\', \'Family\']', 'Hapless museum night watchman Larry Daley must help his living, breathing exhibit friends out of a pickle now that they\'ve been transferred to the archives at the Smithsonian Institution. Larry\'s (mis)adventures this time include close encounters with Amelia Earhart, Abe Lincoln and Ivan the Terrible.'),
(1534, '265147', 'de', 'https://image.tmdb.org/t/p/w500/M8dzMo69k4nnWagUndALTR2yk5.jpg', 'Die goldene Banane von Bad Porno', '51.561', '1971-08-26', 5.8, '5', '[\'Comedy\']', 'A producer of erotic / pornographic pictures would like very much to win the Golden Banana at the 13th Danish Festival of Pornographic Pictures. He tries to spy what the other studios are filming...'),
(1535, '314405', 'it', 'https://image.tmdb.org/t/p/w500/ryZsoaYmcEJsye6P5uo5thEjpqB.jpg', 'Il racconto dei racconti', '64.483', '2015-05-14', 6.3, '1313', '[\'Romance\', \'Fantasy\', \'Horror\']', 'The Queen of Selvascura risks everything to be a mother; the King of Roccaforte falls in love with the voice of a mysterious girl; the King of Altomonte becomes obsessed with a flea and neglects his daughter.'),
(1536, '12536', 'en', 'https://image.tmdb.org/t/p/w500/qRktvMOO2QaCL7gvNyvZDoxPOZj.jpg', 'Home Alone 4', '46.358', '2004-05-18', 4.5, '907', '[\'Comedy\', \'Family\']', 'Kevin McCallister\'s parents have split up. Now living with his mom, he decides to spend Christmas with his dad at the mansion of his father\'s rich girlfriend, Natalie. Meanwhile robber Marv Merchants, one of the villains from the first two movies, partners up with a new criminal named Vera to hit Natalie\'s mansion.'),
(1537, '11024', 'en', 'https://image.tmdb.org/t/p/w500/5BrXCJrs22bR5KR6mLHluYo6y4m.jpg', 'Scooby-Doo 2: Monsters Unleashed', '49.443', '2004-03-24', 6, '2091', '[\'Mystery\', \'Fantasy\', \'Adventure\', \'Comedy\']', 'When Mystery, Inc. are guests of honor at the grand opening of the Coolsville Museum of Criminology, a masked villain shows up and creates havoc before stealing the costumes of the gang\'s most notorious villains...Could it be that their nemesis, mad scientist Jonathan Jacobo has returned and is trying to recreate their deadliest foes?'),
(1538, '444308', 'en', 'https://image.tmdb.org/t/p/w500/iXJKrcjHXrL148OfmovdGPBvnSw.jpg', 'Cashback', '37.526', '2004-08-01', 7, '79', '[\'Drama\', \'Comedy\']', 'Ben is an art college student in London, whose imagination runs wild as he works the late-night shift at the local supermarket. What do he and his colleagues do to pass the long, endless hours of the night?'),
(1539, '752455', 'en', 'https://image.tmdb.org/t/p/w500/8ftutOnMM5JHl69mvkNbs8f1AUR.jpg', 'Angela\'s Christmas Wish', '44.033', '2020-12-01', 6.3, '71', '[\'Animation\', \'Family\']', 'A determined Angela makes a wish to reunite her family in time for Christmas, then launches a plan to find her way from Ireland to Australia.'),
(1540, '18131', 'en', 'https://image.tmdb.org/t/p/w500/5fsemnPiqmx0RMFFVytHN0nRTXY.jpg', 'Baby on Board', '39.871', '2009-06-09', 4.8, '74', '[\'Comedy\', \'Romance\']', 'The story of Angela, an ambitious, image-conscious businesswoman working for over-demanding boss Mary. When Angela becomes unexpectedly pregnant at the peak of her career, her life with her divorce attorney husband, Curtis, is turned upside-down.'),
(1541, '35056', 'en', 'https://image.tmdb.org/t/p/w500/ucEWhj32KEDcFKHMWVeu8r1Q4ld.jpg', 'Date Night', '32.642', '2010-04-08', 6.1, '2281', '[\'Comedy\', \'Action\', \'Adventure\']', 'Phil and Claire Foster fear that their mild-mannered relationship may be falling into a stale rut. During their weekly date night, their dinner reservation leads to their being mistaken for a couple of thieves—and now a number of unsavoury characters want Phil and Claire killed.'),
(1542, '49524', 'en', 'https://image.tmdb.org/t/p/w500/rS0kByPD4YF8pQ85KjzMdGiu7Xf.jpg', 'R.I.P.D.', '49.344', '2013-07-18', 5.7, '2996', '[\'Fantasy\', \'Action\', \'Comedy\', \'Crime\']', 'A recently slain cop joins a team of undead police officers working for the Rest in Peace Department and tries to find the man who murdered him. Based on the comic by Peter M. Lenkov.'),
(1543, '888', 'en', 'https://image.tmdb.org/t/p/w500/k7gkf5Wa8YZ9iyEOylBMfw9pnkp.jpg', 'The Flintstones', '43.585', '1994-05-26', 5.3, '1884', '[\'Fantasy\', \'Comedy\', \'Family\']', 'Modern Stone Age family the Flintstones hit the big screen in this live-action version of the classic cartoon. Fred helps Barney adopt a child. Barney sees an opportunity to repay him when Slate Mining tests its employees to find a new executive. But no good deed goes unpunished.'),
(1544, '43593', 'en', 'https://image.tmdb.org/t/p/w500/lMLS2OFBbNYMSB1ZbVp4q2S4zTU.jpg', 'Piranha 3D', '38.886', '2010-08-20', 5.4, '1663', '[\'Comedy\', \'Horror\']', 'Each year the population of sleepy Lake Victoria, Arizona explodes from 5,000 to 50,000 residents for the annual Spring Break celebration. But then, an earthquake opens an underwater chasm, releasing an enormous swarm of ancient Piranha that have been dormant for thousands of years, now with a taste for human flesh. This year, there\'s something more to worry about than the usual hangovers and complaints from locals, a new type of terror is about to be cut loose on Lake Victoria.'),
(1545, '8274', 'en', 'https://image.tmdb.org/t/p/w500/6BgKeWEGROpWwEWvpw7vwfTCr9C.jpg', 'American Pie Presents: Band Camp', '47.32', '2005-10-30', 5.5, '1664', '[\'Comedy\']', 'Everyone has \'moved on\', except for Sherman and Jim Levenstein\'s still understanding father. Little Matt Stiffler wants to join his older brother Steve\'s business and, after everything Matt has heard from Jim\'s band-geek wife, he plans to go back to band camp and make a video of his own.'),
(1546, '9319', 'en', 'https://image.tmdb.org/t/p/w500/glPswihcZYoAQ4YM2uJF4UACy8T.jpg', 'The Last Boy Scout', '64.096', '1991-12-11', 6.8, '1324', '[\'Action\', \'Thriller\']', 'When the girl that detective Joe Hallenback is protecting gets murdered, the boyfriend of the murdered girl attempts to investigate and solve the case. What they discover is that there is deep seated corruption going on between a crooked politician and the owner of a pro football team.'),
(1547, '872537', 'en', 'https://image.tmdb.org/t/p/w500/3Y1bV9Lw2xJZJK6yJlycoyM2WNV.jpg', 'Convergence: Courage in a Crisis', '47.778', '2021-10-08', 5.3, '3', '[\'Documentary\']', 'Activists and volunteers work through the darkest days of 2020, galvanizing social change amidst chaos as governments start to fail local communities. This epic, globally spanning and deeply passionate documentary serves as a clarion call that great change can be born of crisis.'),
(1548, '5559', 'en', 'https://image.tmdb.org/t/p/w500/aWe27GmvfVYAd7p0KEtJZWwLWk5.jpg', 'Bee Movie', '53.808', '2007-10-28', 6, '3829', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\']', 'Barry B. Benson, a bee who has just graduated from college, is disillusioned at his lone career choice: making honey. On a special trip outside the hive, Barry\'s life is saved by Vanessa, a florist in New York City. As their relationship blossoms, he discovers humans actually eat honey, and subsequently decides to sue us.'),
(1549, '715123', 'en', 'https://image.tmdb.org/t/p/w500/bXLVZGgLgd7OwbfP6fC5GCfrxuD.jpg', 'Books of Blood', '43.901', '2020-10-07', 6.7, '188', '[\'Horror\', \'Science Fiction\']', 'A journey into uncharted and forbidden territory through three tales tangled in space and time.'),
(1550, '494407', 'ja', 'https://image.tmdb.org/t/p/w500/5oXKbOQOsPaLscHCqHjvi7hegOJ.jpg', '劇場版ポケットモンスター みんなの物語', '43.866', '2018-07-13', 7, '131', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\']', 'A young athlete whose running days might be behind her, a compulsive liar, a shy researcher, a bitter old woman, and a little girl with a big secret—the only thing they have in common is the annual Wind Festival in Fula City.  The festival celebrates the Legendary Pokémon Lugia, who brings the wind that powers this seaside city. When a series of threats endangers not just the festival, but all the people and Pokémon of Fula City, it’ll take more than just Satoshi and Pikachu to save the day! Can everyone put aside their differences and work together—or will it all end in destruction?'),
(1551, '11778', 'en', 'https://image.tmdb.org/t/p/w500/bbGtogDZOg09bm42KIpCXUXICkh.jpg', 'The Deer Hunter', '29.543', '1978-03-09', 8, '2743', '[\'Drama\', \'War\']', 'A group of working-class friends decide to enlist in the Army during the Vietnam War and finds it to be hellish chaos -- not the noble venture they imagined. Before they left, Steven married his pregnant girlfriend -- and Michael and Nick were in love with the same woman. But all three are different men upon their return.'),
(1552, '271718', 'en', 'https://image.tmdb.org/t/p/w500/wrY629UTCUAKLJ4CxQXz6DCE7pr.jpg', 'Trainwreck', '41.785', '2015-07-17', 5.8, '2212', '[\'Comedy\', \'Romance\']', 'Having thought that monogamy was never possible, a commitment-phobic career woman may have to face her fears when she meets a good guy.'),
(1553, '10781', 'en', 'https://image.tmdb.org/t/p/w500/hTBueN0Ru3R7brwtONenDyEMNYe.jpg', 'The Texas Chainsaw Massacre: The Beginning', '39.09', '2006-10-06', 6.1, '1271', '[\'Horror\', \'Thriller\']', 'Chrissie and her friends set out on a road trip for a final fling before one is shipped off to Vietnam. Along the way, bikers harass the foursome and cause an accident that throws Chrissie from the vehicle. The lawman who arrives on the scene kills one of the bikers and brings Chrissie\'s friends to the Hewitt homestead, where young Leatherface is learning the tools of terror.'),
(1554, '576004', 'en', 'https://image.tmdb.org/t/p/w500/bhbPSpYjsRJAK7rXqL8APK9EwBl.jpg', 'Porno', '45.056', '2019-06-28', 6.3, '136', '[\'Comedy\', \'Horror\']', 'When a group of naive teens working at a movie theater in a small Christian town discover a mysterious film hidden in its basement, they unleash an alluring succubus who gives them a sex education…written in blood.'),
(1555, '290595', 'en', 'https://image.tmdb.org/t/p/w500/ekHPrneEoa1EoDclWdillOKznqM.jpg', 'The Huntsman: Winter\'s War', '37.592', '2016-04-06', 6.3, '4030', '[\'Action\', \'Adventure\', \'Drama\']', 'As two evil sisters prepare to conquer the land, two renegades—Eric the Huntsman, who aided Snow White in defeating Ravenna in Snowwhite and the Huntsman, and his forbidden lover, Sara—set out to stop them.'),
(1556, '218', 'en', 'https://image.tmdb.org/t/p/w500/qvktm0BHcnmDpul4Hz01GIazWPr.jpg', 'The Terminator', '42.481', '1984-10-26', 7.6, '9902', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'In the post-apocalyptic future, reigning tyrannical supercomputers teleport a cyborg assassin known as the \"Terminator\" back to 1984 to kill Sarah Connor, whose unborn son is destined to lead insurgents against 21st century mechanical hegemony. Meanwhile, the human-resistance movement dispatches a lone warrior to safeguard Sarah. Can he stop the virtually indestructible killing machine?'),
(1557, '761270', 'sv', 'https://image.tmdb.org/t/p/w500/xq2pkQZV5Yt1METvy5S0QjmCpsn.jpg', 'Dancing Queens', '45.139', '2021-06-03', 5.8, '65', '[\'Comedy\', \'Drama\']', 'The story of Dylan Pettersson, a 23-year-old girl from a small island in the Swedish archipelago with big dancing aspirations.'),
(1558, '6114', 'en', 'https://image.tmdb.org/t/p/w500/jSxCIZXudp5q8wQO8VERGX8hRAl.jpg', 'Bram Stoker\'s Dracula', '40.52', '1992-11-13', 7.4, '3720', '[\'Romance\', \'Horror\']', 'When Dracula leaves the captive Jonathan Harker and Transylvania for London in search of Mina Harker, the reincarnation of Dracula\'s long-dead wife Elisabeta, obsessed vampire hunter Dr. Van Helsing sets out to end the madness.'),
(1559, '753926', 'en', 'https://image.tmdb.org/t/p/w500/gd5zv9V6MOaLOOVSN5RoZmF8a5Q.jpg', 'Toys of Terror', '39.132', '2020-10-18', 5.6, '84', '[\'Horror\']', 'A big family moves into a dusty old house in the snowy woods of Washington with hopes of it being a nice holiday escape. But the kids soon discover a stash of old toys that just so happen to belong to a creepy ghost boy. As stranger and stranger things start to happen, some of the kids begin to sense that something in the house is not quite right…'),
(1560, '579051', 'en', 'https://image.tmdb.org/t/p/w500/6KxiEWyIDpz1ikmD7nv3GTX4Uoj.jpg', 'Silk Road', '44.28', '2021-02-19', 6.8, '112', '[\'Crime\', \'Thriller\', \'Drama\']', ''),
(1561, '338762', 'en', 'https://image.tmdb.org/t/p/w500/8WUVHemHFH2ZIP6NWkwlHWsyrEL.jpg', 'Bloodshot', '44.237', '2020-03-05', 6.8, '4070', '[\'Action\', \'Science Fiction\']', 'After he and his wife are murdered, marine Ray Garrison is resurrected by a team of scientists. Enhanced with nanotechnology, he becomes a superhuman, biotech killing machine—\'Bloodshot\'. As Ray first trains with fellow super-soldiers, he cannot recall anything from his former life. But when his memories flood back and he remembers the man that killed both him and his wife, he breaks out of the facility to get revenge, only to discover that there\'s more to the conspiracy than he thought.'),
(1562, '588', 'en', 'https://image.tmdb.org/t/p/w500/fqAGFN2K2kDL0EHxvJaXzaMUkkt.jpg', 'Silent Hill', '37.309', '2006-04-21', 6.5, '3208', '[\'Horror\', \'Mystery\']', 'In search for answers, a mother travels to the enigmatic town of Silent Hill when her daughter begins to suffer recurring nightmares related to the place. It doesn\'t take long for her to discover its home to beings as equally haunting as the town itself.'),
(1563, '406990', 'en', 'https://image.tmdb.org/t/p/w500/atOgZMJpMrTdpqvPiHVPfBhR61l.jpg', 'What Happened to Monday', '39.502', '2017-08-18', 7.2, '5009', '[\'Science Fiction\', \'Thriller\', \'Drama\', \'Mystery\']', 'In a world where families are limited to one child due to overpopulation, a set of identical septuplets must avoid being put to a long sleep by the government and dangerous infighting while investigating the disappearance of one of their own.'),
(1564, '11917', 'en', 'https://image.tmdb.org/t/p/w500/rKl79KqLXg60KFyKsLe4wSSjQ08.jpg', 'Saw V', '44.74', '2008-10-23', 6.2, '2565', '[\'Horror\', \'Thriller\', \'Crime\']', 'Detective Hoffman is seemingly the last person alive to carry on the Jigsaw legacy. But when his secret is threatened, he must go on the hunt to eliminate all the loose ends.'),
(1565, '2667', 'en', 'https://image.tmdb.org/t/p/w500/9050VGrYjYrEjpOvDZVAngLbg1f.jpg', 'The Blair Witch Project', '39.638', '1999-07-14', 6.3, '3488', '[\'Horror\', \'Mystery\']', 'In October of 1994 three student filmmakers disappeared in the woods near Burkittsville, Maryland, while shooting a documentary. A year later their footage was found.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1566, '36648', 'en', 'https://image.tmdb.org/t/p/w500/6f7iXvPOnf83MaLB1JmPzUor1rr.jpg', 'Blade: Trinity', '37.037', '2004-12-08', 5.9, '2973', '[\'Action\', \'Horror\', \'Fantasy\']', 'For years, Blade has fought against the vampires in the cover of the night. But now, after falling into the crosshairs of the FBI, he is forced out into the daylight, where he is driven to join forces with a clan of human vampire hunters he never knew existed—The Nightstalkers. Together with Abigail and Hannibal, two deftly trained Nightstalkers, Blade follows a trail of blood to the ancient creature that is also hunting him—the original vampire, Dracula.'),
(1567, '39451', 'en', 'https://image.tmdb.org/t/p/w500/90mwPRNMmX9RUGVgKMJMJNQnYX8.jpg', 'Little Fockers', '39.136', '2010-12-21', 5.6, '2623', '[\'Comedy\', \'Romance\']', 'It has taken 10 years, two little Fockers with wife Pam and countless hurdles for Greg to finally get in with his tightly wound father-in-law, Jack. After the cash-strapped dad takes a job moonlighting for a drug company, Jack\'s suspicions about his favorite male nurse come roaring back. When Greg and Pam\'s entire clan descends for the twins\' birthday party, Greg must prove to the skeptical Jack that he\'s fully capable as the man of the house.'),
(1568, '728791', 'en', 'https://image.tmdb.org/t/p/w500/1e6EJVJjRrhiU5BzK3LnzmbsMC0.jpg', 'Playhouse', '46.212', '2020-11-17', 5.5, '21', '[\'Horror\', \'Thriller\']', 'Reckless Jack Travis is an irreverent horror writer notorious for scaring audiences. But as he obsesses over creating a new theatre show set in a haunted Scottish castle, demonic disturbances from deep within the walls begin to prey on his troubled daughter. When the alarming supernatural forces start to close in on him too, Jack is forced to reckon with the terrifying consequences of creating such a dark and macabre play. But will he realise the danger of unearthing a historic curse and stop writing before he damns himself, his personal sanity and those he loves forever?'),
(1569, '22970', 'en', 'https://image.tmdb.org/t/p/w500/zZZe5wn0udlhMtdlDjN4NB72R6e.jpg', 'The Cabin in the Woods', '63.266', '2012-04-12', 6.6, '6168', '[\'Horror\', \'Comedy\', \'Fantasy\', \'Thriller\']', 'Five college friends spend the weekend at a remote cabin in the woods, where they get more than they bargained for. Together, they must discover the truth behind the cabin in the woods.'),
(1570, '837463', 'en', 'https://image.tmdb.org/t/p/w500/expZLrqEWyYn5vuAwoHMmG1KSsW.jpg', 'The Perfect Wedding', '40.675', '2021-06-03', 2, '1', '[\'Thriller\', \'TV Movie\']', 'Lindsay is about to marry the man of her dreams- until everything spirals out of control at her bachelorette party. With the wedding called off, she soon uncovers her friends devious scheme to steal away the man she loves.'),
(1571, '181283', 'en', 'https://image.tmdb.org/t/p/w500/p8uTx2xm72vXqI0H4W5kU3ku9ND.jpg', 'Child 44', '35.743', '2015-03-15', 6.3, '1301', '[\'Crime\', \'Thriller\']', 'Set in Stalin-era Soviet Union, a disgraced MGB agent is dispatched to investigate a series of child murders -- a case that begins to connect with the very top of party leadership.'),
(1572, '270303', 'en', 'https://image.tmdb.org/t/p/w500/iwnQ1JH1wdWrGYkgWySptJ5284A.jpg', 'It Follows', '40.848', '2015-02-04', 6.6, '4956', '[\'Horror\', \'Mystery\']', 'Haunted by a lethal curse that\'s passed from one sexual partner to the next, Jay tries to escape and put an end to the evil that stalks her.'),
(1573, '10591', 'en', 'https://image.tmdb.org/t/p/w500/5mVyFHSY2rSsNgD4NfEwV82HigU.jpg', 'The Girl Next Door', '44.017', '2004-04-09', 6.7, '2567', '[\'Comedy\', \'Romance\']', 'Exceptionally ambitious high schooler Matthew has aspirations for a career in politics when he falls in love with his gorgeous 19-year-old neighbor, Danielle. But Matthew\'s bright future is jeopardized when he finds Danielle was once a porn star. As Danielle\'s past catches up with her, Matthew\'s love for her forces him to re-evaluate his goals.'),
(1574, '37056', 'en', 'https://image.tmdb.org/t/p/w500/y9DdvY1IRNS2hWLq161hmP2gXn.jpg', 'Letters to Juliet', '36.918', '2010-05-13', 7, '2425', '[\'Comedy\', \'Drama\', \'Romance\']', 'An American girl on vacation in Italy finds an unanswered \"letter to Juliet\" -- one of thousands of missives left at the fictional lover\'s Verona courtyard, which are typically answered by the \"secretaries of Juliet\" -- and she goes on a quest to find the lovers referenced in the letter.'),
(1575, '13700', 'en', 'https://image.tmdb.org/t/p/w500/9xIIo4FMquy5SRqn8hppyr2QadR.jpg', 'Home on the Range', '43.711', '2004-04-02', 6, '1567', '[\'Animation\', \'Family\']', 'When a greedy outlaw schemes to take possession of the \"Patch Of Heaven\" dairy farm, three determined cows, a karate-kicking stallion and a colorful corral of critters join forces to save their home. The stakes are sky-high as this unlikely animal alliance risk their hides and match wits with a mysterious band of bad guys.'),
(1576, '774810', 'en', 'https://image.tmdb.org/t/p/w500/2kWVSZfK9gbbNQD93Qwi8VvYjlB.jpg', 'A Trash Truck Christmas', '37.224', '2020-12-11', 6.6, '47', '[\'Animation\', \'Adventure\', \'Family\']', 'When Santa crash-lands in the junkyard on Christmas Eve, Hank, Trash Truck and their animal friends all have a hand in rescuing the holiday for everyone.'),
(1577, '81005', 'en', 'https://image.tmdb.org/t/p/w500/9jSI7saUX9Qz0JLh19jX2ulEwL7.jpg', 'Jack the Giant Slayer', '47.213', '2013-02-27', 5.8, '4193', '[\'Fantasy\', \'Action\', \'Adventure\', \'Family\']', 'The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.'),
(1578, '137106', 'en', 'https://image.tmdb.org/t/p/w500/lbctonEnewCYZ4FYoTZhs8cidAl.jpg', 'The Lego Movie', '43.214', '2014-02-06', 7.4, '6311', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\', \'Fantasy\']', 'An ordinary Lego mini-figure, mistakenly thought to be the extraordinary MasterBuilder, is recruited to join a quest to stop an evil Lego tyrant from gluing the universe together.'),
(1579, '474395', 'en', 'https://image.tmdb.org/t/p/w500/mFHihhE9hlvJEk2f1AqdLRaYHd6.jpg', 'Teen Titans Go! To the Movies', '42.672', '2018-07-27', 7.4, '888', '[\'Animation\', \'Action\', \'Comedy\', \'Science Fiction\']', 'All the major DC superheroes are starring in their own films, all but the Teen Titans, so Robin is determined to remedy this situation by getting over his role as a sidekick and becoming a movie star. Thus, with a few madcap ideas and an inspirational song in their hearts, the Teen Titans head to Hollywood to fulfill their dreams.'),
(1580, '52629', 'es', 'https://image.tmdb.org/t/p/w500/ar8BpJ5xAzTIw9bqD9Sra6TjBvw.jpg', 'El Infierno', '40.26', '2010-09-03', 7.8, '370', '[\'Drama\', \'Crime\', \'Comedy\']', 'Benjamin Garcia, Benny is deported from the United States. Back home and against a bleak picture, Benny gets involved in the drug business, in which he has for the first time in his life, a spectacular rise surrounded by money, women, violence and fun. But very soon he will discover that criminal life does not always keep its promises.'),
(1581, '280217', 'en', 'https://image.tmdb.org/t/p/w500/QTESAsBVZwjtGJNDP7utiGV37z.jpg', 'The Lego Movie 2: The Second Part', '37.424', '2019-01-26', 6.7, '1541', '[\'Action\', \'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'It\'s been five years since everything was awesome and the citizens are facing a huge new threat: LEGO DUPLO® invaders from outer space, wrecking everything faster than they can rebuild.'),
(1582, '98567', 'cn', 'https://image.tmdb.org/t/p/w500/rT3NsV3bgOZ1DtyVAM1GgmKtIf8.jpg', '十二生肖', '42.759', '2012-12-20', 6.2, '602', '[\'Action\', \'Adventure\']', 'Asian Hawk (Jackie Chan) leads a mercenary team to recover several lost artifacts from the Old Summer Palace, the bronze heads of the 12 Chinese Zodiac animals which were sacked by the French and British armies from the imperial Summer Palace in Beijing in 1860. Assisted by a Chinese student & a Parisian lady, Hawk stops at nothing to accomplish the mission.'),
(1583, '267935', 'en', 'https://image.tmdb.org/t/p/w500/w17Mc2x2olB5CtewznUFxgpvne0.jpg', 'The BFG', '45.261', '2016-06-01', 6.2, '2690', '[\'Adventure\', \'Family\', \'Fantasy\']', 'The BFG is no ordinary bone-crunching giant. He is far too nice and jumbly. It\'s lucky for Sophie that he is. Had she been carried off in the middle of the night by the Bloodbottler, or any of the other giants—rather than the BFG—she would have soon become breakfast. When Sophie hears that the giants are flush-bunking off to England to swollomp a few nice little chiddlers, she decides she must stop them once and for all. And the BFG is going to help her!'),
(1584, '405774', 'en', 'https://image.tmdb.org/t/p/w500/rGfGfgL2pEPCfhIvqHXieXFn7gp.jpg', 'Bird Box', '57.768', '2018-12-13', 6.9, '7933', '[\'Thriller\', \'Drama\', \'Science Fiction\']', 'Five years after an ominous unseen presence drives most of society to suicide, a survivor and her two children make a desperate bid to reach safety.'),
(1585, '411088', 'es', 'https://image.tmdb.org/t/p/w500/fptnZJbLzKUHeNlYrAynbyoL5YJ.jpg', 'Contratiempo', '45.399', '2017-01-06', 8.2, '3468', '[\'Drama\', \'Mystery\', \'Thriller\']', 'Barcelona, Spain. Adrián Doria, a young and successful businessman accused of murder, meets one night with Virginia Goodman, an expert interrogation lawyer, in order to devise a defense strategy.'),
(1586, '9725', 'en', 'https://image.tmdb.org/t/p/w500/92rGctBMTv4uaSlIBVnhz01kRWL.jpg', 'Friday the 13th Part 2', '36.44', '1981-05-01', 6.1, '1131', '[\'Horror\', \'Thriller\']', 'Five years after the horrible bloodbath at Camp Crystal Lake, it seems Jason Voorhees and his demented mother are in the past. Paul opens up a new camp close to the infamous site, ignoring warnings to stay away, and a sexually-charged group of counselors follow -- including child psychologist major Ginny. But Jason has been hiding out all this time, and now he\'s ready for revenge.'),
(1587, '433', 'en', 'https://image.tmdb.org/t/p/w500/pHyWpWn2pRIfhS3Arcn4SKtKKW4.jpg', 'Mary Poppins', '43.382', '1964-08-27', 7.6, '3789', '[\'Comedy\', \'Family\', \'Fantasy\']', 'A magical nanny employs music and adventure to help two neglected children become closer to their father.'),
(1588, '49527', 'en', 'https://image.tmdb.org/t/p/w500/pziTpiYy5dtVdvXctYIZv09r5Nk.jpg', 'Man on a Ledge', '44.235', '2012-01-13', 6.4, '2055', '[\'Action\', \'Thriller\', \'Crime\']', 'An ex-cop turned con threatens to jump to his death from a Manhattan hotel rooftop. The NYPD dispatch a female police psychologist to talk him down. However, unbeknownst to the police on the scene, the suicide attempt is a cover for the biggest diamond heist ever pulled.'),
(1589, '254470', 'en', 'https://image.tmdb.org/t/p/w500/oFBQUufCV4c8WZoNhtGM17p884H.jpg', 'Pitch Perfect 2', '41.974', '2015-05-07', 6.9, '4657', '[\'Comedy\', \'Music\']', 'The Bellas are back, and they are better than ever. After being humiliated in front of none other than the President of the United States of America, the Bellas are taken out of the Aca-Circuit. In order to clear their name, and regain their status, the Bellas take on a seemingly impossible task: winning an international competition no American team has ever won. In order to accomplish this monumental task, they need to strengthen the bonds of friendship and sisterhood and blow away the competition with their amazing aca-magic! With all new friends and old rivals tagging along for the trip, the Bellas can hopefully accomplish their dreams.'),
(1590, '13285', 'en', 'https://image.tmdb.org/t/p/w500/uBCvRThFwjvwNQeS3Vy7xMPc0Rh.jpg', 'Barbie Fairytopia: Mermaidia', '40.721', '2006-03-14', 6.8, '524', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\']', 'In this animated follow-up to Fairytopia, Elina (played by Barbie) enlists the help of a mermaid, Nori, to save her friend Nalu, a merman prince who has been captured by the wicked Laverna.'),
(1591, '50646', 'en', 'https://image.tmdb.org/t/p/w500/p4RafgAPk558muOjnBMHhMArjS2.jpg', 'Crazy, Stupid, Love.', '37.922', '2011-07-29', 7.2, '6536', '[\'Comedy\', \'Drama\', \'Romance\']', 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal\'s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.'),
(1592, '627290', 'en', 'https://image.tmdb.org/t/p/w500/irkse1FMm9dWemwlxKJ7RINT9Iy.jpg', 'Antebellum', '35.459', '2020-09-02', 6.4, '614', '[\'Horror\']', 'Successful author Veronica finds herself trapped in a horrifying reality and must uncover the mind-bending mystery before it\'s too late.'),
(1593, '6537', 'es', 'https://image.tmdb.org/t/p/w500/vIpi1KtHLXUOfSVC2m6MqpjSPgL.jpg', 'El orfanato', '34.419', '2007-05-20', 7.2, '2193', '[\'Horror\', \'Drama\', \'Thriller\']', 'A woman brings her family back to her childhood home, which used to be an orphanage, intent on reopening it. Before long, her son starts to communicate with a new invisible friend.'),
(1594, '514710', 'ja', 'https://image.tmdb.org/t/p/w500/5jURYLaG6BX0klRHsiHc3pzOlOm.jpg', 'ちいさな英雄－カニとタマゴと透明人間－', '44.479', '2018-08-24', 6.7, '107', '[\'Animation\', \'Fantasy\', \'Adventure\', \'Drama\']', 'Two tiny, aquatic humanoids search for their missing father, a boy battles a lethal allergy to eggs, and an invisible salaryman tries to become a hero.'),
(1595, '518764', 'zh', 'https://image.tmdb.org/t/p/w500/kxc25B05Gq4CbCoWbyTFf9iF0wn.jpg', '动物世界', '35.978', '2018-06-29', 7.3, '146', '[\'Drama\', \'Action\', \'Adventure\', \'Thriller\', \'Mystery\', \'Fantasy\']', 'Drifting aimlessly through life, Kaisi (Li Yi Feng) has racked up debts of several million having borrowed money from his friends. Lured with the promise of writing it all off, Kaisi leaves his ailing mother and childhood sweetheart Qing (Zhou Dongyu) to board the ship Destiny and attend a gambling party controlled by the mysterious Anderson (Michael Douglas).  All players join the game with stars. For each game they lose, their opponent captures a star. Everyone is holding daggers behind their backs plotting dirty means by which to overcome their opponents. The game quickly deteriorates into a slaughter and Kaisi must battle save his own skin…'),
(1596, '8273', 'en', 'https://image.tmdb.org/t/p/w500/pCO3lJv2PzPkJty29APxCVSjyoE.jpg', 'American Wedding', '45.964', '2003-08-01', 6.2, '3251', '[\'Comedy\', \'Romance\']', 'With high school a distant memory, Jim and Michelle are getting married -- and in a hurry, since Jim\'s grandmother is sick and wants to see him walk down the aisle -- prompting Stifler to throw the ultimate bachelor party. And Jim\'s dad is reliable as ever, doling out advice no one wants to hear.'),
(1597, '395990', 'en', 'https://image.tmdb.org/t/p/w500/g0eEEZAqMf98ULQnoiORuazjOpn.jpg', 'Death Wish', '36.673', '2018-03-02', 6.1, '2030', '[\'Action\', \'Crime\', \'Drama\', \'Thriller\']', 'A mild-mannered father is transformed into a killing machine after his family is torn apart by a violent act.'),
(1598, '391713', 'en', 'https://image.tmdb.org/t/p/w500/gl66K7zRdtNYGrxyS2YDUP5ASZd.jpg', 'Lady Bird', '44.671', '2017-09-08', 7.3, '6667', '[\'Drama\', \'Comedy\']', 'Lady Bird McPherson, a strong willed, deeply opinionated, artistic 17 year old comes of age in Sacramento. Her relationship with her mother and her upbringing are questioned and tested as she plans to head off to college.'),
(1599, '252', 'en', 'https://image.tmdb.org/t/p/w500/vmpsZkrs4Uvkp9r1atL8B3frA63.jpg', 'Willy Wonka & the Chocolate Factory', '44.158', '1971-06-29', 7.5, '2529', '[\'Family\', \'Fantasy\', \'Comedy\']', 'When eccentric candy man Willy Wonka promises a lifetime supply of sweets and a tour of his chocolate factory to five lucky kids, penniless Charlie Bucket seeks the golden ticket that will make him a winner.'),
(1600, '195589', 'en', 'https://image.tmdb.org/t/p/w500/sN1RU08CMi8xkRIibremh3AOdgw.jpg', 'Neighbors', '39.611', '2014-05-08', 6.2, '5906', '[\'Comedy\']', 'A couple with a newborn baby face unexpected difficulties after they are forced to live next to a fraternity house.'),
(1601, '315465', 'ja', 'https://image.tmdb.org/t/p/w500/kRofx67xkbnJ6pAVcHdeMyBm4OM.jpg', 'バケモノの子', '44.212', '2015-07-11', 8.1, '1097', '[\'Animation\', \'Fantasy\', \'Action\', \'Adventure\', \'Drama\']', 'Kyuta, a boy living in Shibuya, and Kumatetsu, a lonesome beast from Jutengai, an imaginary world. One day, Kyuta forays into the imaginary world and, as he\'s looking for his way back, meets Kumatetsu who becomes his spirit guide. That encounter leads them to many adventures.'),
(1602, '323660', 'en', 'https://image.tmdb.org/t/p/w500/9sdAHQxt53W8gZKivX0Pdk4DuXA.jpg', 'Avengers Grimm', '36.7', '2015-03-17', 4.2, '83', '[\'Action\', \'Fantasy\']', 'When Rumpelstiltskin destroys the Magic Mirror and escapes to the modern world, the four princesses of \"Once Upon a Time\"-Cinderella, Sleeping Beauty, Snow White, and Rapunzel-are sucked through the portal too. Well-trained and endowed with magical powers, the four women must fight Rumpelstiltskin and his army of thralls before he enslaves everyone on Earth.'),
(1603, '347126', 'en', 'https://image.tmdb.org/t/p/w500/xsRYqQJv6t0f4J6DYeYraM9uKKT.jpg', 'God\'s Not Dead 2', '34.959', '2016-04-01', 6.1, '310', '[\'Drama\']', 'When a high school teacher is asked a question in class about Jesus, her reasoned response lands her in deep trouble and could expel God from the public square once and for all.'),
(1604, '597890', 'en', 'https://image.tmdb.org/t/p/w500/gn2vCmWO7jQBBto9SYuBHYZARaU.jpg', 'Voyagers', '39.183', '2021-04-08', 6.3, '360', '[\'Science Fiction\', \'Thriller\']', 'With the future of the human race at stake, a group of young men and women -- bred for intelligence and obedience -- embark on an expedition to colonize a distant planet. When they uncover disturbing secrets about the mission, they defy their training and begin to explore their most primitive natures. As life on the ship descends into chaos, they soon become consumed by fear, lust and an insatiable hunger for power.'),
(1605, '364111', 'ja', 'https://image.tmdb.org/t/p/w500/7bJHM6t6j3YLjDNTwe4hyghKqSr.jpg', '心が叫びたがってるんだ。', '44.453', '2015-09-19', 7.7, '268', '[\'Animation\', \'Drama\', \'Music\', \'Romance\']', 'A young girl had her voice magically taken away so that she would never hurt people with it, but her outlook changes when she encounters music and friendship. Will Naruse be able to convey the anthem of her heart?'),
(1606, '664767', 'en', 'https://image.tmdb.org/t/p/w500/iBvo3qOPcmhlqAaJcXcQHtx2qLk.jpg', 'Mortal Kombat Legends: Scorpion\'s Revenge', '44.126', '2020-04-12', 8.3, '1036', '[\'Animation\', \'Action\', \'Fantasy\']', 'After the vicious slaughter of his family by stone-cold mercenary Sub-Zero, Hanzo Hasashi is exiled to the torturous Netherrealm. There, in exchange for his servitude to the sinister Quan Chi, he’s given a chance to avenge his family – and is resurrected as Scorpion, a lost soul bent on revenge. Back on Earthrealm, Lord Raiden gathers a team of elite warriors – Shaolin monk Liu Kang, Special Forces officer Sonya Blade and action star Johnny Cage – an unlikely band of heroes with one chance to save humanity. To do this, they must defeat Shang Tsung’s horde of Outworld gladiators and reign over the Mortal Kombat tournament.'),
(1607, '476669', 'en', 'https://image.tmdb.org/t/p/w500/iMjSfMUuCkCE7z5fzGtjeDusPD3.jpg', 'The King\'s Man', '42.633', '2021-12-22', 0, '0', '[\'War\', \'Action\', \'Thriller\', \'Adventure\']', 'As a collection of history\'s worst tyrants and criminal masterminds gather to plot a war to wipe out millions, one man must race against time to stop them.'),
(1608, '399360', 'en', 'https://image.tmdb.org/t/p/w500/afdZAIcAQscziqVtsEoh2PwsYTW.jpg', 'Alpha', '35.638', '2018-08-17', 6.4, '2048', '[\'Adventure\', \'Drama\']', 'In the prehistoric past, Keda, a young and inexperienced hunter, struggles to return home after being separated from his tribe when bison hunting goes awry. On his way back he will find an unexpected ally.'),
(1609, '440471', 'en', 'https://image.tmdb.org/t/p/w500/A6tb8JNrie2qT8JC2tGqshayuck.jpg', 'Escape Plan 2: Hades', '37.132', '2018-06-05', 5.1, '1068', '[\'Action\']', 'Ray Breslin manages an elite team of security specialists trained in the art of breaking people out of the world\'s most impenetrable prisons. When his most trusted operative, Shu Ren, is kidnapped and disappears inside the most elaborate prison ever built, Ray must track him down with the help of some of his former friends.'),
(1610, '640', 'en', 'https://image.tmdb.org/t/p/w500/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg', 'Catch Me If You Can', '40.067', '2002-12-25', 7.9, '11689', '[\'Drama\', \'Crime\']', 'A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.'),
(1611, '62214', 'en', 'https://image.tmdb.org/t/p/w500/yGjVbLVdZRBlZTTQVBsj2KUjL1s.jpg', 'Frankenweenie', '48.616', '2012-10-04', 6.9, '2542', '[\'Animation\', \'Comedy\', \'Family\']', 'When a car hits young Victor\'s pet dog Sparky, Victor decides to bring him back to life the only way he knows how. But when the bolt-necked \"monster\" wreaks havoc and terror in the hearts of Victor\'s neighbors, he has to convince them that Sparky\'s still the good, loyal friend he was.'),
(1612, '76617', 'en', 'https://image.tmdb.org/t/p/w500/qaPvvHP1kKlQaUAXQZQAWitqBOT.jpg', 'Texas Chainsaw 3D', '35.911', '2013-01-03', 5.5, '1174', '[\'Horror\', \'Thriller\']', 'A young woman learns that she has inherited a Texas estate from her deceased grandmother. After embarking on a road trip with friends to uncover her roots, she finds she is the sole owner of a lavish, isolated Victorian mansion. But her newfound wealth comes at a price as she stumbles upon a horror that awaits her in the mansion’s dank cellars.'),
(1613, '343795', 'en', 'https://image.tmdb.org/t/p/w500/e3LKk8UdDyXDkov9k8iP2JJNChi.jpg', '90 Minutes in Heaven', '45.661', '2015-09-11', 6.1, '109', '[\'Drama\']', 'A man involved in a horrific car crash is pronounced dead, only to come back to life an hour and a half later, claiming to have seen Heaven.'),
(1614, '10996', 'en', 'https://image.tmdb.org/t/p/w500/hjfeMLWqJY44mqqJKZSa6jx4Y1j.jpg', 'Stuart Little 2', '43.804', '2002-07-19', 5.7, '1898', '[\'Family\', \'Adventure\', \'Animation\', \'Comedy\']', 'Stuart, an adorable white mouse, still lives happily with his adoptive family, the Littles, on the east side of Manhattan\'s Central Park. More crazy mouse adventures are in store as Stuart, his human brother, George, and their mischievous cat, Snowbell, set out to rescue a friend.'),
(1615, '9714', 'en', 'https://image.tmdb.org/t/p/w500/6uOadrCfle0n2LOOxHbgWEdnrm2.jpg', 'Home Alone 3', '37.8', '1997-12-12', 5.3, '2288', '[\'Comedy\', \'Family\']', '9-year-old Alex Pruitt is home alone with the chicken pox. Turns out, due to a mix-up among nefarious spies, Alex was given a toy car concealing a top-secret microchip. Now Alex must fend off the spies as they try break into his house to get it back.'),
(1616, '192141', 'en', 'https://image.tmdb.org/t/p/w500/jIXZEvL4dmgkjyhD5JUDeOaASKB.jpg', 'No Escape', '44.102', '2015-08-26', 6.9, '2002', '[\'Thriller\']', 'In their new overseas home, an American family soon finds themselves caught in the middle of a coup, and they frantically look for a safe escape in an environment where foreigners are being immediately executed.'),
(1617, '407439', 'en', 'https://image.tmdb.org/t/p/w500/oLbqnVAmD8ISel1SLTY3Ek0TWz8.jpg', 'Mary Magdalene', '44.656', '2018-03-15', 6.3, '413', '[\'Drama\', \'History\']', 'In the first century, free-spirited Mary Magdalene flees the marriage her family has arranged for her, finding refuge and a sense of purpose in a radical new movement led by the charismatic, rabble-rousing preacher named Jesus.'),
(1618, '63311', 'es', 'https://image.tmdb.org/t/p/w500/xa7uCwGYykrf8MMI8iF5dZvNlrG.jpg', 'La piel que habito', '39.092', '2011-08-17', 7.5, '3273', '[\'Drama\', \'Horror\']', 'A brilliant plastic surgeon creates a synthetic skin that withstands any kind of damage. His guinea pig: a mysterious and volatile woman who holds the key to his obsession.'),
(1619, '745881', 'th', 'https://image.tmdb.org/t/p/w500/tWoSE8SH6XhgWKHIL3p0sj7lA3V.jpg', 'ร่างทรง', '48.994', '2021-07-14', 7.1, '166', '[\'Horror\', \'Thriller\']', 'A horrifying story of a shaman’s inheritance in the Isan region of Thailand. But the goddess that appears to have taken possession of a family member turns out not be as benevolent as it first appears.'),
(1620, '530915', 'en', 'https://image.tmdb.org/t/p/w500/iZf0KyrE25z1sage4SYFLCCrMi9.jpg', '1917', '38.561', '2019-12-25', 8, '8870', '[\'War\', \'Drama\', \'Action\', \'Thriller\']', 'At the height of the First World War, two young British soldiers must cross enemy territory and deliver a message that will stop a deadly attack on hundreds of soldiers.'),
(1621, '354282', 'en', 'https://image.tmdb.org/t/p/w500/3sx69bH2n2tgvknvq2VROJ6lEXS.jpg', 'The Osiris Child', '35.393', '2016-02-17', 5.4, '362', '[\'Science Fiction\']', 'Set in the future in a time of interplanetary colonization, an unlikely pair race against an impending global crisis and are confronted by the monsters that live inside us all.'),
(1622, '11470', 'en', 'https://image.tmdb.org/t/p/w500/ggOND0hfoE0f3K857joSzEeIchb.jpg', 'Jason X', '39.135', '2001-07-24', 4.8, '929', '[\'Horror\', \'Science Fiction\']', 'In the year 2455, Old Earth is now a contaminated planet abandoned for centuries -- a brown world of violent storms, toxic landmasses and poisonous seas. Yet humans have returned to the deadly place that they once fled, not to live, but to research the ancient, rusting artifacts of the long-gone civilizations. But it\'s not the harmful environment that could prove fatal to the intrepid, young explorers who have just landed on Old Earth. For them, it\'s Friday the 13th, and Jason lives!'),
(1623, '170', 'en', 'https://image.tmdb.org/t/p/w500/sQckQRt17VaWbo39GIu0TMOiszq.jpg', '28 Days Later', '45.83', '2002-10-31', 7.2, '5016', '[\'Horror\', \'Thriller\', \'Science Fiction\']', 'Twenty-eight days after a killer virus was accidentally unleashed from a British research facility, a small group of London survivors are caught in a desperate struggle to protect themselves from the infected. Carried by animals and humans, the virus turns those it infects into homicidal maniacs -- and it\'s absolutely impossible to contain.'),
(1624, '4488', 'en', 'https://image.tmdb.org/t/p/w500/uGGpnWHOmWTARVN9wbC1nPxNgps.jpg', 'Friday the 13th', '35.027', '1980-05-09', 6.4, '2044', '[\'Horror\']', 'Camp counselors are stalked and murdered by an unknown assailant while trying to reopen a summer camp that was the site of a child\'s drowning.'),
(1625, '664413', 'pl', 'https://image.tmdb.org/t/p/w500/6KwrHucIE3CvNT7kTm2MAlZ4fYF.jpg', '365 dni', '41.851', '2020-02-07', 7, '6212', '[\'Drama\', \'Romance\']', 'A woman falls victim to a dominant mafia boss, who imprisons her and gives her one year to fall in love with him.'),
(1626, '109451', 'en', 'https://image.tmdb.org/t/p/w500/ss5NcK2NWFg2YcKKYXLrk8q1myS.jpg', 'Cloudy with a Chance of Meatballs 2', '41.981', '2013-09-26', 6.4, '2409', '[\'Animation\', \'Family\', \'Comedy\']', 'After the disastrous food storm in the first film, Flint and his friends are forced to leave the town. Flint accepts the invitation from his idol Chester V to join The Live Corp Company, which has been tasked to clean the island, and where the best inventors in the world create technologies for the betterment of mankind. When Flint discovers that his machine still operates and now creates mutant food beasts like living pickles, hungry tacodiles, shrimpanzees and apple pie-thons, he and his friends must return to save the world.'),
(1627, '59859', 'en', 'https://image.tmdb.org/t/p/w500/1go2A3gdQjaMuHWquybgoJlQRcX.jpg', 'Kick-Ass 2', '46.027', '2013-07-17', 6.4, '5039', '[\'Action\', \'Adventure\', \'Crime\']', 'After Kick-Ass’ insane bravery inspires a new wave of self-made masked crusaders, he joins a patrol led by the Colonel Stars and Stripes. When these amateur superheroes are hunted down by Red Mist — reborn as The Mother Fucker — only the blade-wielding Hit-Girl can prevent their annihilation.'),
(1628, '325133', 'en', 'https://image.tmdb.org/t/p/w500/eyjcLLwxuRXACbglIbwWwaXK9DN.jpg', 'Neighbors 2: Sorority Rising', '39.03', '2016-05-04', 5.8, '3736', '[\'Comedy\']', 'A sorority moves in next door to the home of Mac and Kelly Radner who have a young child. The Radner\'s enlist their former nemeses from the fraternity to help battle the raucous sisters.'),
(1629, '10320', 'en', 'https://image.tmdb.org/t/p/w500/bHbz7z2pecTawhkqLpuC2m0qywe.jpg', 'The Ring Two', '33.624', '2005-03-17', 5.7, '1778', '[\'Drama\', \'Horror\', \'Thriller\']', 'Rachel Keller must prevent evil Samara from taking possession of her son\'s soul.'),
(1630, '428078', 'en', 'https://image.tmdb.org/t/p/w500/gLhYg9NIvIPKVRTtvzCWnp1qJWG.jpg', 'Mortal Engines', '46.785', '2018-11-27', 6.2, '3564', '[\'Adventure\', \'Science Fiction\']', 'Many thousands of years in the future, Earth’s cities roam the globe on huge wheels, devouring each other in a struggle for ever diminishing resources. On one of these massive traction cities, the old London, Tom Natsworthy has an unexpected encounter with a mysterious young woman from the wastelands who will change the course of his life forever.'),
(1631, '31011', 'en', 'https://image.tmdb.org/t/p/w500/hsYa8xwtfprkVsCqGUX6ohNgtBH.jpg', 'Mr. Nobody', '29.722', '2009-11-06', 7.9, '4871', '[\'Science Fiction\', \'Drama\', \'Romance\', \'Fantasy\']', 'Nemo Nobody leads an ordinary existence with his wife and 3 children; one day, he wakes up as a mortal centenarian in the year 2092.'),
(1632, '13474', 'en', 'https://image.tmdb.org/t/p/w500/3mTtQSKoFNyvhbcqBUJl8tPRqMz.jpg', 'P2', '39.867', '2007-11-09', 6.1, '594', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Angela, a corporate climber, gets stuck working late on Christmas Eve and finds herself the target of an unhinged security guard. With no help in sight, the woman must overcome physical and psychological challenges to survive.'),
(1633, '132232', 'en', 'https://image.tmdb.org/t/p/w500/eo8BhR8Q5STmWE9sMLsEPagxmy6.jpg', 'Mama', '35.212', '2013-01-17', 6.2, '3414', '[\'Horror\']', 'Guillermo del Toro presents Mama, a supernatural thriller that tells the haunting tale of two little girls who disappeared into the woods the day that their parents were killed. When they are rescued years later and begin a new life, they find that someone or something still wants to come tuck them in at night.'),
(1634, '438650', 'en', 'https://image.tmdb.org/t/p/w500/5RILVnOchQyL1LbcVzmabipdJfc.jpg', 'Cold Pursuit', '42.272', '2019-02-07', 5.7, '1899', '[\'Action\', \'Crime\', \'Thriller\']', 'The quiet family life of Nels Coxman, a snowplow driver, is upended after his son\'s murder. Nels begins a vengeful hunt for Viking, the drug lord he holds responsible for the killing, eliminating Viking\'s associates one by one. As Nels draws closer to Viking, his actions bring even more unexpected and violent consequences, as he proves that revenge is all in the execution.'),
(1635, '114', 'en', 'https://image.tmdb.org/t/p/w500/dvcarc7TMrRp1C3jXPpn7PKce99.jpg', 'Pretty Woman', '40.205', '1990-03-23', 7.4, '6046', '[\'Romance\', \'Comedy\']', 'When a millionaire wheeler-dealer enters a business contract with a Hollywood hooker Vivian Ward, he loses his heart in the bargain.'),
(1636, '379291', 'en', 'https://image.tmdb.org/t/p/w500/ctHGhbe19xIX6wlECsFydHiha4W.jpg', 'Justice League vs. Teen Titans', '40.36', '2016-05-13', 7.4, '644', '[\'Science Fiction\', \'Action\', \'Animation\']', 'Robin is sent by Batman to work with the Teen Titans after his volatile behavior botches up a Justice League mission. The Titans must then step up to face Trigon after he possesses the League and threatens to conquer the world.'),
(1637, '583903', 'en', 'https://image.tmdb.org/t/p/w500/vg9C5LttsKBqoLuqeQvOXaeBGiD.jpg', 'Our Friend', '31.869', '2019-02-25', 7.2, '168', '[\'Drama\', \'Comedy\', \'Romance\']', 'After learning that his terminally ill wife has six months to live, a man welcomes the support of his best friend who moves into their home to help out.'),
(1638, '14564', 'en', 'https://image.tmdb.org/t/p/w500/mjtAYGglfOO6T1jRov35jH46J6Z.jpg', 'Rings', '32.806', '2017-02-01', 5, '2164', '[\'Horror\']', 'Julia becomes worried about her boyfriend, Holt when he explores the dark urban legend of a mysterious videotape said to kill the watcher seven days after viewing. She sacrifices herself to save her boyfriend and in doing so makes a horrifying discovery: there is a \"movie within the movie\" that no one has ever seen before.'),
(1639, '475430', 'en', 'https://image.tmdb.org/t/p/w500/tI8ocADh22GtQFV28vGHaBZVb0U.jpg', 'Artemis Fowl', '47.081', '2020-06-12', 5.7, '1266', '[\'Adventure\', \'Fantasy\', \'Science Fiction\', \'Family\', \'Action\']', 'Artemis Fowl is a 12-year-old genius and descendant of a long line of criminal masterminds. He soon finds himself in an epic battle against a race of powerful underground fairies who may be behind his father\'s disappearance.'),
(1640, '522162', 'en', 'https://image.tmdb.org/t/p/w500/hj8pyoNnynGeJTAbl7jcLZO8Uhx.jpg', 'Midway', '45.82', '2019-11-06', 7.1, '1690', '[\'War\', \'History\', \'Action\', \'Drama\']', 'The story of the Battle of Midway, and the leaders and soldiers who used their instincts, fortitude and bravery to overcome massive odds.'),
(1641, '460793', 'en', 'https://image.tmdb.org/t/p/w500/As8WTtxXs9e3cBit3ztTf7zoRmm.jpg', 'Olaf\'s Frozen Adventure', '38.856', '2017-10-27', 6.4, '1220', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'Olaf is on a mission to harness the best holiday traditions for Anna, Elsa, and Kristoff.'),
(1642, '298115', 'en', 'https://image.tmdb.org/t/p/w500/sgOXOQyPIjeMi1bnWu1r0CzLsZD.jpg', 'Dragons: Dawn Of The Dragon Racers', '28.351', '2014-11-01', 7.2, '251', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'A hunt for a lost sheep turns into a competition between Hiccup and friends as they compete to become the first Dragon Racing champion of Berk.'),
(1643, '98', 'en', 'https://image.tmdb.org/t/p/w500/ty8TGRuvJLPUmAR1H1nRIsgwvim.jpg', 'Gladiator', '41.793', '2000-05-01', 8.2, '14315', '[\'Action\', \'Drama\', \'Adventure\']', 'In the year 180, the death of emperor Marcus Aurelius throws the Roman Empire into chaos.  Maximus is one of the Roman army\'s most capable and trusted generals and a key advisor to the emperor.  As Marcus\' devious son Commodus ascends to the throne, Maximus is set to be executed.  He escapes, but is captured by slave traders.  Renamed Spaniard and forced to become a gladiator, Maximus must battle to the death with other men for the amusement of paying audiences.'),
(1644, '448119', 'en', 'https://image.tmdb.org/t/p/w500/3Nt3v1uzUgfSuVARD1AnI9g9Zl9.jpg', 'Dolittle', '40.963', '2020-01-01', 6.8, '2737', '[\'Family\', \'Fantasy\', \'Adventure\']', 'After losing his wife seven years earlier, the eccentric Dr. John Dolittle, famed doctor and veterinarian of Queen Victoria’s England, hermits himself away behind the high walls of Dolittle Manor with only his menagerie of exotic animals for company. But when the young queen falls gravely ill, a reluctant Dolittle is forced to set sail on an epic adventure to a mythical island in search of a cure, regaining his wit and courage as he crosses old adversaries and discovers wondrous creatures.'),
(1645, '133805', 'en', 'https://image.tmdb.org/t/p/w500/8tT1rqlsTguyfUBMrbHR9cv1rxM.jpg', 'Carrie', '58.731', '2013-10-16', 6, '3693', '[\'Drama\', \'Horror\']', 'A reimagining of the classic horror tale about Carrie White, a shy girl outcast by her peers and sheltered by her deeply religious mother, who unleashes telekinetic terror on her small town after being pushed too far at her senior prom.'),
(1646, '299687', 'en', 'https://image.tmdb.org/t/p/w500/ja34BV577dtjWl2S5G1tB93IjYb.jpg', 'The 5th Wave', '40.433', '2016-01-14', 5.9, '4919', '[\'Science Fiction\', \'Adventure\', \'Action\']', '16-year-old Cassie Sullivan tries to survive in a world devastated by the waves of an alien invasion that has already decimated the population and knocked mankind back to the Stone Age.'),
(1647, '10501', 'en', 'https://image.tmdb.org/t/p/w500/tQuqhUBACMcGqCvliHxpJreBfXC.jpg', 'The Road to El Dorado', '49.025', '2000-03-31', 7.2, '2978', '[\'Family\', \'Adventure\', \'Animation\', \'Comedy\', \'Action\']', 'After a failed swindle, two con-men end up with a map to El Dorado, the fabled \"city of gold,\" and an unintended trip to the New World.  Much to their surprise, the map does lead the pair to the mythical city, where the startled inhabitants promptly begin to worship them as gods.  The only question is, do they take the worshipful natives for all they\'re worth, or is there a bit more to El Dorado than riches?'),
(1648, '476926', 'en', 'https://image.tmdb.org/t/p/w500/qRmQazyIBZR4pQIk9VruiZul0Au.jpg', 'The Titan', '32.584', '2018-03-30', 5.4, '982', '[\'Science Fiction\', \'Thriller\']', 'On a bleak future Earth, a soldier endures a radical genetic transformation to save humanity. But his wife fears he\'s becoming more creature than man.'),
(1649, '417320', 'en', 'https://image.tmdb.org/t/p/w500/qoNlGfQmFZ37Gf5fRBaCTLlOZtx.jpg', 'Descendants 2', '56.328', '2017-07-21', 7.5, '1295', '[\'Family\', \'Fantasy\', \'TV Movie\', \'Music\', \'Adventure\', \'Action\', \'Romance\']', 'When the pressure to be royal becomes too much for Mal, she returns to the Isle of the Lost where her archenemy Uma, Ursula\'s daughter, has taken her spot as self-proclaimed queen.'),
(1650, '818647', 'es', 'https://image.tmdb.org/t/p/w500/jmkpZvMVIRrMFevxzOubSBfG0s0.jpg', 'A través de mi ventana', '43.037', '2022-02-04', 0, '0', '[\'Drama\', \'Romance\']', 'Raquel has had a longtime crush on her hot neighbor, Ares, whom she secretly watches but has never spoken to. Can she make Ares fall in love with her?'),
(1652, '551804', 'en', 'https://image.tmdb.org/t/p/w500/8xC6QSyxrpm0D5A6iyHNemEWBVe.jpg', 'Freaky', '39.609', '2020-11-12', 6.8, '852', '[\'Horror\', \'Thriller\', \'Comedy\', \'Fantasy\']', 'A mystical, ancient dagger causes a notorious serial killer to magically switch bodies with a 17-year-old girl.'),
(1653, '257346', 'ja', 'https://image.tmdb.org/t/p/w500/wJcyYVRPZDOZOD2w0r2R6wuZqqN.jpg', 'アベンジャーズ コンフィデンシャル：ブラック・ウィドウ ＆ パニッシャー', '47.563', '2014-03-25', 6.4, '169', '[\'Animation\', \'Science Fiction\', \'Action\']', 'When the Punisher takes out a black-market weapons dealer, he stumbles upon a far-reaching terrorist plot devised by a group known as Leviathan.'),
(1654, '48988', 'en', 'https://image.tmdb.org/t/p/w500/eol3uD6whQKOKCmmhF7z39fq2Pe.jpg', 'Hall Pass', '36.06', '2011-02-25', 5.6, '1540', '[\'Comedy\', \'Romance\']', 'When best buds Rick and Fred begin to show signs of restlessness at home, their wives take a bold approach to revitalize their marriages, they grant the guys a \'hall pass\'—one week of freedom to do whatever they want. At first, it seems like a dream come true, but they quickly discover that their expectations of the single life—and themselves—are completely and hilariously out of sync with reality.'),
(1655, '589082', 'ja', 'https://image.tmdb.org/t/p/w500/7iUoLTDTk5IgUJTboct2RHuuTMG.jpg', '薄暮', '48.276', '2019-06-21', 6.5, '15', '[\'Animation\', \'Drama\']', 'Hakubo tells the story of two young people who live in rural Fukushima: Sachi Koyama, a girl who excels at playing the violin, and Yuusuke Kijinami, a boy who loves to paint. After an awkward, chance encounter, the two meet and begin to fall in love, but Yuusuke is still living in the shadow of the 2011 Tohoku earthquake and tsunami.'),
(1656, '8645', 'en', 'https://image.tmdb.org/t/p/w500/fP4nBrtmc0teSDDHzYmDE7TLQBT.jpg', 'The Happening', '40.755', '2008-06-11', 5.3, '2627', '[\'Thriller\', \'Science Fiction\']', 'When a deadly airborne virus threatens to wipe out the northeastern United States, teacher Elliott Moore and his wife Alma flee from contaminated cities into the countryside in a fight to discover the truth. Is it terrorism, the accidental release of some toxic military bio weapon -- or something even more sinister?'),
(1657, '10530', 'en', 'https://image.tmdb.org/t/p/w500/kZ1ft0QZ4e3zDUPMBftEkwI9ftd.jpg', 'Pocahontas', '38.5', '1995-06-14', 7, '4626', '[\'Adventure\', \'Animation\', \'Family\', \'Romance\']', 'Pocahontas, daughter of a Native American tribe chief, falls in love with an English soldier as colonists invade 17th century Virginia.'),
(1658, '857', 'en', 'https://image.tmdb.org/t/p/w500/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', 'Saving Private Ryan', '40.199', '1998-07-24', 8.2, '12322', '[\'Drama\', \'History\', \'War\']', 'As U.S. troops storm the beaches of Normandy, three brothers lie dead on the battlefield, with a fourth trapped behind enemy lines. Ranger captain John Miller and seven men are tasked with penetrating German-held territory and bringing the boy home.'),
(1659, '109414', 'en', 'https://image.tmdb.org/t/p/w500/tNIW0NhX1hKvUsy6PQ80DOKUhkD.jpg', 'This Is the End', '39.302', '2013-06-12', 6.2, '5135', '[\'Action\', \'Comedy\']', 'While attending a party at James Franco\'s house, Seth Rogen, Jay Baruchel and many other celebrities are faced with the apocalypse.'),
(1660, '10014', 'en', 'https://image.tmdb.org/t/p/w500/53kxYw0G3o55yJ23K7s7KMaOyAM.jpg', 'A Nightmare on Elm Street Part 2: Freddy\'s Revenge', '44.995', '1985-11-01', 5.8, '1273', '[\'Horror\']', 'A new family moves into the house on Elm Street, and before long, the kids are again having nightmares about deceased child murderer Freddy Krueger. This time, Freddy attempts to possess a teenage boy to cause havoc in the real world, and can only be overcome if the boy\'s sweetheart can master her fear.'),
(1661, '11852', 'en', 'https://image.tmdb.org/t/p/w500/lnnGE4TKa05t20SZ2batuAhXCp4.jpg', 'The Hot Chick', '36.244', '2002-12-13', 6.3, '1482', '[\'Comedy\', \'Fantasy\']', 'Not only is Jessica Spencer the most popular girl in school -- she is also the meanest. But things change for the attractive teen when a freak accident involving a cursed pair of earrings and a chance encounter at a gas station causes her to switch bodies with Clive, a sleazy crook. Jessica, in the form of the repulsive Clive, struggles to adjust to this radical alteration and sets out to get her own body back before the upcoming prom.'),
(1662, '431821', 'ja', 'https://image.tmdb.org/t/p/w500/iUttStQFPGp8rCXn7JYfC5IIlQF.jpg', '劇場版 魔法科高校の劣等生 星を呼ぶ少女', '35.202', '2017-06-17', 6.1, '30', '[\'Science Fiction\', \'Action\', \'Animation\', \'Fantasy\']', 'In the story, the seasons have changed and it will soon be the second spring. Tatsuya and Miyuki have finished their first year at First Magic High School and are on their spring break. The two go to their villa on the Ogasawara Island archipelago. After only a small moment of peace a lone young woman named Kokoa appears before them. She has abandoned the Naval base and she tells Tatsuya her one wish.'),
(1663, '2300', 'en', 'https://image.tmdb.org/t/p/w500/4RN5El3Pj2W4gpwgiAGLVfSJv2g.jpg', 'Space Jam', '48.88', '1996-11-15', 6.9, '4761', '[\'Animation\', \'Family\', \'Comedy\', \'Science Fiction\']', 'Jokes fly as the Tune Squad takes on the Nerdlucks in a hardcourt game to decide if the Looney Tunes remain here... or become attractions at a far-off galactic off-ramp called Moron Mountain. The Nerdlucks have a monstrous secret weapon: they\'ve stolen the skills of top NBA stars like Charles Barkley and Patrick Ewing and become Monstars. But that\'s not all, folks. The Tune Squad’s secret weapon just happens to be the finest player in this or any other universe. He\'s outta this world. So\'s the fun.'),
(1664, '14411', 'en', 'https://image.tmdb.org/t/p/w500/yiW2L1fDiBT7AeWXrykhTNtPrr8.jpg', 'Sinbad: Legend of the Seven Seas', '41.423', '2003-07-02', 6.9, '1555', '[\'Family\', \'Animation\', \'Adventure\', \'Comedy\', \'Fantasy\', \'Action\']', 'The sailor of legend is framed by the goddess Eris for the theft of the Book of Peace, and must travel to her realm at the end of the world to retrieve it and save the life of his childhood friend Prince Proteus.'),
(1665, '207768', 'en', 'https://image.tmdb.org/t/p/w500/wit1VRI9sAbCstuwm3KPgxfYYqo.jpg', 'I Spit on Your Grave 2', '35.023', '2013-08-25', 6.4, '942', '[\'Thriller\', \'Horror\', \'Crime\']', 'Naturally beautiful, Katie has just settled into New York where she, like many other young women, is trying to make it as a model. But what starts out as an innocent and simple photo shoot soon turns into something disturbingly unthinkable! Raped, tortured and kidnapped to a foreign country, Jessica is buried alive and left to die. Against all odds, she manages to escape. Severely injured, she will have to tap into the darkest places of the human psyche to not only survive, but to exact her revenge…'),
(1666, '449176', 'en', 'https://image.tmdb.org/t/p/w500/snIsqVPmlu4LPjvToHpDotxa7Eh.jpg', 'Love, Simon', '31.878', '2018-02-16', 8.1, '5153', '[\'Comedy\', \'Drama\', \'Romance\']', 'Everyone deserves a great love story. But for seventeen-year old Simon Spier it\'s a little more complicated: he\'s yet to tell his family or friends he\'s gay and he doesn\'t know the identity of the anonymous classmate he\'s fallen for online.'),
(1667, '121856', 'en', 'https://image.tmdb.org/t/p/w500/kDXewoEcvbn0pUvJ8W3vfkuWgHw.jpg', 'Assassin\'s Creed', '38.084', '2016-12-21', 5.4, '6553', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'Through unlocked genetic memories that allow him to relive the adventures of his ancestor in 15th century Spain, Callum Lynch discovers he\'s a descendant of the secret \'Assassins\' society. After gaining incredible knowledge and skills, he is now poised to take on the oppressive Knights Templar in the present day.'),
(1668, '602', 'en', 'https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', 'Independence Day', '47.197', '1996-06-25', 6.8, '7662', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'On July 2, a giant alien mothership enters orbit around Earth and deploys several dozen saucer-shaped \'destroyer\' spacecraft that quickly lay waste to major cities around the planet. On July 3, the United States conducts a coordinated counterattack that fails. On July 4, a plan is devised to gain access to the interior of the alien mothership in space, in order to plant a nuclear missile.'),
(1669, '849938', 'en', 'https://image.tmdb.org/t/p/w500/w0OapZj3KMhsmvne1KrNmlYp6bO.jpg', 'Framed by My Husband', '60.572', '2021-07-10', 2, '1', '[\'TV Movie\', \'Thriller\']', 'A woman agrees to help her husband pay off an extortionist, but when the blackmailer is murdered she becomes the prime suspect, and discovers that the man she married has been leading a deadly double life.'),
(1670, '81774', 'fr', 'https://image.tmdb.org/t/p/w500/xvtRgQIRegLjsjaIkKQbh0hk3Qy.jpg', 'Les Exploits d\'un jeune Don Juan', '35.055', '1986-11-04', 5.2, '79', '[\'Comedy\', \'Drama\']', 'Roger is a 16-year-old who seeks to lose his virginity in this softcore erotic drama. His initial efforts are unsuccessful, but World War I breaks out and men are seen marching off to battle. Roger goes overboard when he is presented with several amorous opportunities.'),
(1671, '82703', 'en', 'https://image.tmdb.org/t/p/w500/hPcImYndWESKHzT2GHVCDsUxzYg.jpg', 'Mr. Peabody & Sherman', '38.183', '2014-02-07', 6.7, '1915', '[\'Animation\', \'Adventure\', \'Family\']', 'A young boy and his dog, who happens to have a genius-level IQ, spring into action when their time-machine is stolen and moments in history begin to be changed.'),
(1672, '836691', 'en', 'https://image.tmdb.org/t/p/w500/lnx1DMYg4hUU16rH9kOmMQECBeE.jpg', 'Shark Beach with Chris Hemsworth', '33.492', '2021-07-05', 6.4, '4', '[\'Documentary\']', 'Chris Hemsworth is on a mission to uncover the science of shark behavior and discover how humans and sharks can safely coexist. After an increase in local shark attacks along the east coast of Australia, Hemsworth seeks to understand different species of sharks and their behaviors while also exploring new preventative measures and the latest technology to help stave off shark-human encounters.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1673, '575293', 'fr', 'https://image.tmdb.org/t/p/w500/obziP53V5cVNTQpi9JffGiIfggn.jpg', 'Sous les étoiles de Paris', '30.841', '2021-04-08', 5.9, '26', '[\'Drama\', \'Comedy\']', 'Christine’s life has not been easy lately. Her lonely routine is divided between free food banks distributions and wandering the streets. On a cold winter night she founds Suli, an 8-year-old Eritrean boy, sobbing in front of her shelter. Christine understands that he is lost and has been separated from his mother. Bounded by their marginal condition, they embark together on an emotional journey to find Suli’s mother in the underground world of Paris...'),
(1674, '27579', 'en', 'https://image.tmdb.org/t/p/w500/7dNpUdJHjCue7H22jQR1NIX1kou.jpg', 'The American', '37.477', '2010-08-31', 5.9, '1018', '[\'Crime\', \'Drama\', \'Thriller\']', 'Dispatched to a small Italian town to await further orders, assassin Jack embarks on a double life that may be more relaxing than is good for him.'),
(1675, '453405', 'en', 'https://image.tmdb.org/t/p/w500/cT5m5m9X6hNbUrx7kUTsedAMivW.jpg', 'Gemini Man', '36.942', '2019-10-02', 6.4, '4012', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'Henry Brogan is an elite 51-year-old assassin who\'s ready to call it quits after completing his 72nd job. His plans get turned upside down when he becomes the target of a mysterious operative who can seemingly predict his every move. To his horror, Brogan soon learns that the man who\'s trying to kill him is a younger, faster, cloned version of himself.'),
(1676, '296099', 'en', 'https://image.tmdb.org/t/p/w500/fYDALvoCt3DBlSWN6pSAnGQ9ld7.jpg', 'Vacation', '40.172', '2015-07-28', 6.3, '2955', '[\'Comedy\']', 'Hoping to bring his family closer together and to recreate his childhood vacation for his own kids, a grown up Rusty Griswold takes his wife and their two sons on a cross-country road trip to the coolest theme park in America, Walley World. Needless to say, things don\'t go quite as planned.'),
(1677, '183011', 'en', 'https://image.tmdb.org/t/p/w500/hg6RYpSb3vU4i3yQDtE1YhSZNh5.jpg', 'Justice League: The Flashpoint Paradox', '38.215', '2013-07-30', 7.9, '1340', '[\'Science Fiction\', \'Animation\', \'Action\', \'Adventure\']', 'The Flash finds himself in a war-torn alternate timeline and teams up with alternate versions of his fellow heroes to restore the timeline.'),
(1678, '37821', 'en', 'https://image.tmdb.org/t/p/w500/zsbnZItIs4LZEFy1LOJQCqVG7Zj.jpg', 'Killers', '35.159', '2010-06-04', 5.9, '1818', '[\'Action\', \'Comedy\', \'Thriller\', \'Romance\']', 'When an elite assassin marries a beautiful computer whiz after a whirlwind romance, he gives up the gun and settles down with his new bride. That is, until he learns that someone from his past has put a contract out on his life.'),
(1679, '93856', 'en', 'https://image.tmdb.org/t/p/w500/9AKhThGA8IATBy3gR7I4dw9SEc4.jpg', 'Chernobyl Diaries', '50.709', '2012-05-24', 5.2, '1236', '[\'Horror\', \'Thriller\']', 'A group of six tourists looking to go off the beaten path, hire an \'extreme tour guide\' who, ignoring warnings, takes them into the city of Pripyat, the former home to the workers of the Chernobyl nuclear reactor, but now a deserted town since the disaster more than 25 years earlier. After a brief exploration of the abandoned city, the group members find themselves stranded, only to discover that they are not alone.'),
(1680, '228161', 'en', 'https://image.tmdb.org/t/p/w500/usFenYnk6mr8C62dB1MoAfSWMGR.jpg', 'Home', '43.411', '2015-03-18', 6.8, '3234', '[\'Fantasy\', \'Comedy\', \'Animation\', \'Science Fiction\', \'Family\']', 'When Earth is taken over by the overly-confident Boov, an alien race in search of a new place to call home, all humans are promptly relocated, while all Boov get busy reorganizing the planet. But when one resourceful girl, Tip, manages to avoid capture, she finds herself the accidental accomplice of a banished Boov named Oh. The two fugitives realize there’s a lot more at stake than intergalactic relations as they embark on the road trip of a lifetime.'),
(1681, '624860', 'en', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', 'The Matrix Resurrections', '43.245', '2021-12-15', 0, '0', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'A continuation of the story established in the first MATRIX film, reuniting cinematic icons Neo & Trinity as they venture back into the Matrix and even deeper down the rabbit hole. A mind-bending new adventure with action and epic scale, it’s set in a familiar yet even more provocative world where reality is more subjective than ever and all that’s required to see the truth is to free your mind.'),
(1682, '1970', 'en', 'https://image.tmdb.org/t/p/w500/7vPAVPKYexQVmvC578wPLn2CGCL.jpg', 'The Grudge', '37.203', '2004-10-22', 5.9, '2278', '[\'Horror\', \'Mystery\', \'Thriller\']', 'An American nurse living and working in Tokyo is exposed to a mysterious supernatural curse, one that locks a person in a powerful rage before claiming their life and spreading to another victim.'),
(1683, '72571', 'en', 'https://image.tmdb.org/t/p/w500/9nYranPiWdNmbD5PRPPSL7VUFTS.jpg', 'Paranormal Activity 3', '39.405', '2011-10-19', 5.9, '1696', '[\'Horror\', \'Mystery\']', 'In 1988, young sisters Katie and Kristi befriend an invisible entity who resides in their home.'),
(1684, '7443', 'en', 'https://image.tmdb.org/t/p/w500/8XgmIsbpVamdhwcNVsYzohFZTtT.jpg', 'Chicken Run', '43.152', '2000-06-21', 6.7, '3815', '[\'Animation\', \'Comedy\', \'Family\']', 'Having been hopelessly repressed and facing eventual certain death at the British chicken farm where they are held, Ginger the chicken along with the help of Rocky the American rooster decide to rebel and lead their fellow chickens in a great escape from the murderous farmers Mr. and Mrs. Tweedy and their farm of doom.'),
(1685, '259072', 'en', 'https://image.tmdb.org/t/p/w500/cV1biK7jlHVXlQ7ErYe5MUSBGcx.jpg', 'Wrong Turn 6: Last Resort', '41.374', '2014-08-22', 5.3, '569', '[\'Horror\']', 'A sudden and mysterious inheritance brings Danny and his friends to Hobb Springs, a forgotten resort deep in the West Virginia hills. Hobb Springs is being looked after under the watchful care of Jackson and Sally, a socially awkward couple who introduce Danny to the long lost family he\'s never known. A clan by the name of Hillicker. But soon Danny learns his relatives have a different way of living, that for generations, the Hillickers have observed ancient traditions rooted in cannibalism and other taboo rituals.'),
(1686, '39323', 'ja', 'https://image.tmdb.org/t/p/w500/docwOsWZuwJKQdwcYJtQPBcg6bm.jpg', 'ドラゴンボールZ たったひとりの最終決戦〜フリーザに挑んだZ戦士 孫悟空の父〜', '43.046', '1990-10-17', 7.4, '452', '[\'Animation\', \'Action\', \'Science Fiction\', \'Drama\', \'Fantasy\']', 'Bardock, Son Goku\'s father, is a low-ranking Saiyan soldier who was given the power to see into the future by the last remaining alien on a planet he just destroyed. He witnesses the destruction of his race and must now do his best to stop Frieza\'s impending massacre.'),
(1687, '2383', 'en', 'https://image.tmdb.org/t/p/w500/ry4A1Y2udvqyDlVHLtSeP1u9qwJ.jpg', 'L\'Ours', '36.196', '1988-10-21', 7, '325', '[\'Adventure\', \'Drama\', \'Family\']', 'An orphan bear cub hooks up with an adult male as they try to dodge human hunters.'),
(1688, '258509', 'en', 'https://image.tmdb.org/t/p/w500/16OcuuW5z509WILR6BmscNdXgw0.jpg', 'Alvin and the Chipmunks: The Road Chip', '39.652', '2015-12-17', 6.1, '1298', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Through a series of misunderstandings, Alvin, Simon and Theodore come to believe that Dave is going to propose to his new girlfriend in New York City - and dump them. They have three days to get to him and stop the proposal.'),
(1689, '70436', 'en', 'https://image.tmdb.org/t/p/w500/boE0JFhZRpWLLrKOQE6bCBZGerP.jpg', 'The Raven', '42.899', '2012-03-09', 6.3, '1007', '[\'Crime\', \'Thriller\', \'Mystery\']', 'A fictionalized account of the last days of Edgar Allan Poe\'s life, in which the poet is in pursuit of a serial killer whose murders mirror those in the writer\'s stories.'),
(1690, '19556', 'en', 'https://image.tmdb.org/t/p/w500/rJovsKIjVsSMuwURASoTZJB6jvI.jpg', 'Miss March', '34.944', '2009-03-13', 5.5, '258', '[\'Comedy\', \'Romance\']', 'A young man awakens from a four-year coma to hear that his once virginal high-school sweetheart has since become a centerfold in one of the world\'s most famous men\'s magazines. He and his sex-crazed best friend decide to take a cross-country road trip in order to crash a party at the magazine\'s legendary mansion headquarters and win back the girl.'),
(1691, '780382', 'en', 'https://image.tmdb.org/t/p/w500/x3JsrunysUwsIV9XS7hQtZG4knm.jpg', 'Le loup et le lion', '25.726', '2021-10-13', 6.4, '20', '[\'Adventure\', \'Family\']', 'After her grandfather\'s death, 20-year-old Alma decides to go back to her childhood home - a little island in the heart of the majestic Canadian forest. Whilst there, she rescues two helpless cubs: a wolf and a lion. They forge an inseparable bond, but their world soon collapses as the forest ranger discovers the animals and takes them away. The two cub brothers must now embark on a treacherous journey across Canada to be reunited with one another and Alma once more.'),
(1692, '564251', 'ja', 'https://image.tmdb.org/t/p/w500/gA7DbJXZZDUNslMtx70QIK3wMYT.jpg', '映画 賭ケグルイ', '46.506', '2019-05-03', 7.6, '52', '[\'Drama\', \'Mystery\', \'Thriller\']', 'Hyakkaou Private Academy. An institution for the privileged with a very peculiar curriculum. You see, when you\'re the sons and daughters of the wealthiest of the wealthy, it\'s not athletic prowess or book smarts that keep you ahead. It\'s reading your opponent, the art of the deal. What better way to hone those skills than with a rigorous curriculum of gambling? At Hyakkaou Private Academy, the winners live like kings, and the losers are put through the wringer. But when Yumeko Jabami enrolls, she\'s gonna teach these kids what a high roller really looks like!'),
(1693, '91342', 'en', 'https://image.tmdb.org/t/p/w500/iVCfTtVDAECpbMSokSNilIR6wPr.jpg', 'Barbie in A Mermaid Tale 2', '44.93', '2012-02-22', 7, '328', '[\'Animation\', \'Family\']', 'Surf\'s up for Barbie as she returns as Merliah, the fun and fashionable surfing champion who\'s also a magical mermaid princess! In this exciting sea-quel, Merliah makes a splash when she heads to Australia for the ultimate surfing competition. When the evil mermaid Eris escapes from her whirlpool with plans to take over the throne of Oceana, Merliah and her sea friends dive in to stop her. It\'s a fresh new adventure where Merliah learns that anything is possible and she really can have the best of both worlds!'),
(1694, '657811', 'de', 'https://image.tmdb.org/t/p/w500/ffhVZGWhQdy2RY2EukRr4aQilu5.jpg', 'Lassie - Eine abenteuerliche Reise', '44.705', '2020-02-20', 6.6, '75', '[\'Adventure\', \'Family\', \'Drama\']', '12-year-old Florian and his beloved dog Lassie live in an idyllic village in the German countryside. When Florian\'s father loses his job, the family have to move into a small apartment where there are no dogs allowed. Lassie is given away to another family, but Florian and Lassie yearn to be reunited again so Florian sets out on an adventure to find his best friend.'),
(1695, '516486', 'en', 'https://image.tmdb.org/t/p/w500/kjMbDciooTbJPofVXgAoFjfX8Of.jpg', 'Greyhound', '30.205', '2020-07-10', 7.4, '1942', '[\'War\', \'Action\', \'Drama\']', 'A first-time captain leads a convoy of allied ships carrying thousands of soldiers across the treacherous waters of the “Black Pit” to the front lines of WW2. With no air cover protection for 5 days, the captain and his convoy must battle the surrounding enemy Nazi U-boats in order to give the allies a chance to win the war.'),
(1696, '25475', 'en', 'https://image.tmdb.org/t/p/w500/hg1959yuBkHb4BKbIvETQSfxGCT.jpg', 'Tinker Bell and the Lost Treasure', '40.67', '2009-09-03', 6.8, '733', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\']', 'A blue harvest moon will rise, allowing the fairies to use a precious moonstone to restore the Pixie Dust Tree, the source of all their magic. But when Tinker Bell accidentally puts all of Pixie Hollow in jeopardy, she must venture out across the sea on a secret quest to set things right.'),
(1697, '818809', 'en', 'https://image.tmdb.org/t/p/w500/vXIqSUpO84PMNt9JclXzCbPBslT.jpg', 'A Cinderella Story: Starstruck', '36.795', '2021-06-29', 7.4, '83', '[\'Romance\', \'Comedy\', \'Music\']', 'Finley Tremaine, a small-town farm girl, longs to spread her wings and soar as an aspiring performer. When a Hollywood film crew arrives in her sleepy town, she is determined to land a role in the production and capture the attention of handsome lead actor Jackson Stone. Unfortunately, a botched audition forces her to change course. Now, disguised as cowboy “Huck,” Finley finally gets her big break. But can she keep the charade a secret from everyone, including her evil stepmother and devious step-siblings?'),
(1698, '834500', 'en', 'https://image.tmdb.org/t/p/w500/1tpuwM9fZFcMNkkGU0WwqPAEaFz.jpg', 'Trippin’ with the Kandasamys', '38.772', '2021-06-04', 7.1, '33', '[\'Comedy\', \'Romance\']', 'To rekindle their marriages, best friends-turned-in-laws Shanthi and Jennifer plan a couples\' getaway. But it comes with all kinds of surprises.'),
(1699, '22804', 'en', 'https://image.tmdb.org/t/p/w500/9JtluosCbioSXJSABZByaODyPpa.jpg', 'Saw VI', '48.112', '2009-10-16', 6.3, '2337', '[\'Horror\', \'Mystery\']', 'Special Agent Strahm is dead, and Detective Hoffman has emerged as the unchallenged successor to Jigsaw\'s legacy. However, when the FBI draws closer to Hoffman, he is forced to set a game into motion, and Jigsaw\'s grand scheme is finally understood.'),
(1700, '19288', 'en', 'https://image.tmdb.org/t/p/w500/uBXtcz92oigWaWnFDyS8j5tMAc1.jpg', 'Leprechaun: Back 2 tha Hood', '39.408', '2003-12-30', 5.2, '114', '[\'Horror\', \'Comedy\']', 'When Emily Woodrow and her friends happen on a treasure chest full of gold coins, they fail to to heed the warnings of a wise old psychic who had foretold that they would encounter trouble with a very nasty and protective Leprechaun.'),
(1701, '397243', 'en', 'https://image.tmdb.org/t/p/w500/6K0wjP8kPCiPYy9PtXBGuypyt5I.jpg', 'The Autopsy of Jane Doe', '41.962', '2016-12-21', 6.7, '3118', '[\'Horror\', \'Mystery\']', 'Father and son coroners receive a mysterious unidentified corpse with no apparent cause of death. As they attempt to examine the beautiful young \"Jane Doe,\" they discover increasingly bizarre clues that hold the key to her terrifying secrets.'),
(1702, '49017', 'en', 'https://image.tmdb.org/t/p/w500/m5h3NtZ2ZfryIHl1MvatmANvIqQ.jpg', 'Dracula Untold', '44.35', '2014-10-01', 6.4, '5018', '[\'Horror\', \'Action\', \'Drama\', \'Fantasy\', \'War\']', 'Vlad Tepes is a great hero, but when he learns the Sultan is preparing for battle and needs to form an army of 1,000 boys, he vows to find a way to protect his family. Vlad turns to dark forces in order to get the power to destroy his enemies and agrees to go from hero to monster as he\'s turned into the mythological vampire, Dracula.'),
(1703, '276907', 'en', 'https://image.tmdb.org/t/p/w500/4shf5Alq4KWCKqrAAQe0JGJHYp5.jpg', 'Legend', '40.003', '2015-09-09', 6.9, '2638', '[\'Crime\', \'Thriller\']', 'Suave, charming and volatile, Reggie Kray and his unstable twin brother Ronnie start to leave their mark on the London underworld in the 1960s. Using violence to get what they want, the siblings orchestrate robberies and murders while running nightclubs and protection rackets. With police Detective Leonard \"Nipper\" Read hot on their heels, the brothers continue their rapid rise to power and achieve tabloid notoriety.'),
(1704, '4108', 'en', 'https://image.tmdb.org/t/p/w500/dncJ81z1BahrT3ogLvlxOUC5n4u.jpg', 'The Transporter', '40.244', '2002-10-02', 6.7, '4109', '[\'Action\', \'Crime\', \'Thriller\']', 'Former Special Forces officer, Frank Martin will deliver anything to anyone for the right price, and his no-questions-asked policy puts him in high demand. But when he realizes his latest cargo is alive, it sets in motion a dangerous chain of events. The bound and gagged Lai is being smuggled to France by a shady American businessman, and Frank works to save her as his own illegal activities are uncovered by a French detective.'),
(1705, '17899', 'es', 'https://image.tmdb.org/t/p/w500/8D16rdCmTYCg66EMwK1ZZDWiK3x.jpg', 'Mentiras y gordas', '43.878', '2009-03-27', 4.5, '111', '[\'Comedy\', \'Drama\']', 'A youth group is preparing for what will be the summer of their life, including secrets, lies, sex, confusion, evenings and holidays.'),
(1706, '154400', 'en', 'https://image.tmdb.org/t/p/w500/olQInYvVCW2wycMSU1ogo9Jshml.jpg', 'The Drop', '36.438', '2014-09-12', 6.7, '1708', '[\'Drama\', \'Crime\']', 'Bob Saginowski finds himself at the center of a robbery gone awry and entwined in an investigation that digs deep into the neighborhood\'s past where friends, families, and foes all work together to make a living - no matter the cost.'),
(1707, '14438', 'en', 'https://image.tmdb.org/t/p/w500/hfoCG75j1YaNyfZGPg0rWy3nFmU.jpg', 'Fireproof', '36.367', '2008-09-26', 7.5, '457', '[\'Drama\', \'Romance\']', 'Caleb Holt, a heroic fire captain who values dedication and service to others above all else. But the most important partnership in his life, his marriage, is about to go up in smoke. This gripping story follows one man\'s desire to transform his life and marriage through the healing power of faith and fully embrace the fireman\'s code: \"Never leave your partner behind.\"'),
(1708, '77931', 'en', 'https://image.tmdb.org/t/p/w500/tmjvgbEH4BKYFfHmWXjXrHgi8wT.jpg', 'The Smurfs 2', '41.12', '2013-07-30', 5.8, '1747', '[\'Fantasy\', \'Family\', \'Comedy\', \'Animation\']', 'The evil wizard Gargamel creates a couple of mischievous Smurf-like creatures called the Naughties that he hopes will let him harness the all-powerful, magical Smurf-essence. But when he discovers that only a real Smurf can give him what he wants, and only a secret spell that Smurfette knows can turn the Naughties into real Smurfs, Gargamel kidnaps Smurfette and brings her to Paris, where he has been winning the adoration of millions as the world¹s greatest sorcerer. It\'s up to Papa, Clumsy, Grouchy, and Vanity to return to our world, reunite with their human friends Patrick and Grace Winslow, and rescue her! Will Smurfette, who has always felt different from the other Smurfs, find a new connection with the Naughties Vexy and Hackus or will the Smurfs convince her that their love for her is True Blue?'),
(1709, '8913', 'en', 'https://image.tmdb.org/t/p/w500/a1gIACZb04bL8EvLqMpofW2Eqeo.jpg', 'Pet Sematary', '34.864', '1989-04-21', 6.6, '1555', '[\'Horror\']', 'Dr. Louis Creed\'s family moves into the country house of their dreams and discover a pet cemetery at the back of their property. The cursed burial ground deep in the woods brings the dead back to life -- with \"minor\" problems. At first, only the family\'s cat makes the return trip, but an accident forces a heartbroken father to contemplate the unthinkable.'),
(1710, '412520', 'fr', 'https://image.tmdb.org/t/p/w500/grWS1nNexgCQacAIF6Um5PS5N5y.jpg', 'Sex Doll', '40.054', '2016-12-07', 5.4, '98', '[\'Drama\', \'Thriller\', \'Mystery\']', 'Set in London\'s world of high class call girls, Amoureux Solitaires tells the story of London based French escort Virginie, and Rupert, a man who rescues trafficked girls.'),
(1711, '9340', 'en', 'https://image.tmdb.org/t/p/w500/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', 'The Goonies', '39.903', '1985-06-07', 7.5, '4433', '[\'Adventure\', \'Comedy\', \'Family\']', 'A young teenager named Mikey Walsh finds an old treasure map in his father\'s attic. Hoping to save their homes from demolition, Mikey and his friends Data Wang, Chunk Cohen, and Mouth Devereaux run off on a big quest to find the secret stash of Pirate One-Eyed Willie.'),
(1712, '1255', 'ko', 'https://image.tmdb.org/t/p/w500/m3OE5bpcGHMWYlPkYvgIrncuuGN.jpg', '괴물', '32.855', '2006-07-27', 7, '1989', '[\'Horror\', \'Drama\', \'Science Fiction\']', 'Following the dumping of gallons of toxic waste in the river, a giant mutated squid-like appears and begins attacking the populace. Gang-du\'s daughter Hyun-seo is snatched up by the creature; with his family to assist him, he sets off to find her.'),
(1713, '569016', 'ko', 'https://image.tmdb.org/t/p/w500/3KJVCVADvtZ6esjPWPHObjPMuK4.jpg', '언니', '34.546', '2019-01-01', 7.1, '81', '[\'Action\', \'Crime\', \'Thriller\', \'Mystery\']', 'A woman seeks to take revenge when her younger sister disappears and she finds out that her sister suffered violence and sexual abuse from school bullies.'),
(1714, '730028', 'en', 'https://image.tmdb.org/t/p/w500/hNlnSwj34gemONfbBxaG8Trd1vR.jpg', 'The Most Beautiful Boy in the World', '46.947', '2021-07-30', 7.6, '14', '[\'Documentary\']', 'In 1971, due to the world premiere of Death in Venice, Italian director Lucino Visconti proclaimed his Tadzio as the world’s most beautiful boy. A shadow that today, 50 years later, weighs Björn Andresen’s life.'),
(1715, '16007', 'ja', 'https://image.tmdb.org/t/p/w500/xiJPZntaz1BMooXfiwi2iZAMbhY.jpg', 'デスノート', '36.842', '2006-06-17', 7, '473', '[\'Fantasy\', \'Mystery\', \'Thriller\']', 'Light Yagami finds the \"Death Note,\" a notebook with the power to kill, and decides to create a Utopia by killing the world\'s criminals, and soon the world\'s greatest detective, \"L,\" is hired to find the mysterious murderer. An all out battle between the two greatest minds on earth begins and the winner will control the world.'),
(1716, '681429', 'es', 'https://image.tmdb.org/t/p/w500/lG6Wx5tWOEHkOuexEvNYha3ofvM.jpg', 'Cuidado con lo que deseas', '35.201', '2020-04-24', 6.7, '86', '[\'Horror\']', 'Pamela is an eight-year-old girl who loves horror movies and fairy tales. When his uncle gives her away a doll named \"Hellequin\" as a birthday gift, a tale of betrayal begins to unfold before her eyes.'),
(1717, '149', 'ja', 'https://image.tmdb.org/t/p/w500/y8jV1Ncv1IsP8bwu96jZZMt8rVY.jpg', 'アキラ', '43.538', '1988-07-16', 8, '2872', '[\'Animation\', \'Science Fiction\', \'Action\']', 'A secret military project endangers Neo-Tokyo when it turns a biker gang member into a rampaging psychic psychopath that only two teenagers and a group of psychics can stop.'),
(1718, '10992', 'en', 'https://image.tmdb.org/t/p/w500/wUWoat7L4vvQburQ8pVEJhRG9L5.jpg', 'Cats & Dogs', '38.437', '2001-07-04', 5.4, '1247', '[\'Family\', \'Comedy\']', 'When a professor develops a vaccine that eliminates human allergies to dogs, he unwittingly upsets the fragile balance of power between cats and dogs and touches off an epic battle for pet supremacy. The fur flies as the feline faction, led by Mr. Tinkles, squares off against wide-eyed puppy Lou and his canine cohorts.'),
(1719, '72358', 'en', 'https://image.tmdb.org/t/p/w500/hSxVSMHrW3epffELvi2CC5XdFXb.jpg', 'A Thousand Words', '31.029', '2012-03-07', 6.1, '1066', '[\'Drama\', \'Comedy\']', 'Jack McCall is a fast-talking literary agent, who can close any deal, any time, any way. He has set his sights on New Age guru Dr. Sinja for his own selfish purposes. But Dr. Sinja is on to him, and Jack’s life comes unglued after a magical Bodhi tree mysteriously appears in his backyard. With every word Jack speaks, a leaf falls from the tree and he realizes that when the last leaf falls, both he and the tree are toast. Words have never failed Jack McCall, but now he’s got to stop talking and conjure up some outrageous ways to communicate or he’s a goner.'),
(1720, '24831', 'en', 'https://image.tmdb.org/t/p/w500/oaz0Le3fT3R8jzlkXkNV7JAsd7x.jpg', 'Piranha', '33.572', '1978-08-03', 5.9, '429', '[\'Horror\', \'Comedy\']', 'When flesh-eating piranhas are accidently released into a summer resort\'s rivers, the guests become their next meal.'),
(1721, '320846', 'en', 'https://image.tmdb.org/t/p/w500/ihkbceq6vQlEVaIvHTu2tM6z0Do.jpg', 'Sky Sharks', '39.303', '2020-10-07', 5.1, '48', '[\'Horror\', \'Comedy\', \'Science Fiction\']', 'A team of Arctic geologists stumble across an abandoned laboratory in which the Nazis developed an incredible and brutal secret weapon during the final months of WW2. Deep in the ice, they accidentally awake a deadly army of flying zombie sharks ridden by genetically mutated, undead super-humans, who are unleashed into the skies, wreaking their bloodthirsty revenge on any aircraft that takes to the air. An elite task force is assembled to take on this deadly threat and stop the Sky Sharks from conquering the air, but as time runs out, the task force realises they will have to fight fire with fire, and the stage is set for the greatest flying super-mutant zombie shark air battle the world has ever seen....'),
(1722, '2109', 'en', 'https://image.tmdb.org/t/p/w500/3WsLE6FtxEPRa6U9sbY1ckrn39s.jpg', 'Rush Hour', '38.767', '1998-09-18', 6.9, '3448', '[\'Action\', \'Comedy\', \'Crime\']', 'When Hong Kong Inspector Lee is summoned to Los Angeles to investigate a kidnapping, the FBI doesn\'t want any outside help and assigns cocky LAPD Detective James Carter to distract Lee from the case. Not content to watch the action from the sidelines, Lee and Carter form an unlikely partnership and investigate the case themselves.'),
(1723, '12222', 'en', 'https://image.tmdb.org/t/p/w500/6k47Z3A5zI2rxubTMwiLyIqQLLr.jpg', 'Horton Hears a Who!', '36.268', '2008-03-03', 6.5, '2578', '[\'Animation\', \'Comedy\', \'Family\', \'Adventure\', \'Fantasy\']', 'One day, Horton the elephant hears a cry from help coming from a speck of dust. Even though he can\'t see anyone on the speck, he decides to help it. As it turns out, the speck of dust is home to the Whos, who live in their city of Whoville. Horton agrees to help protect the Whos and their home.'),
(1724, '256961', 'en', 'https://image.tmdb.org/t/p/w500/qML63w7vgspicwLK6xXGLK17cM0.jpg', 'Paul Blart: Mall Cop 2', '39.214', '2015-04-16', 5.2, '1257', '[\'Action\', \'Comedy\', \'Family\']', 'Security guard Paul Blart is headed to Las Vegas to attend a Security Guard Expo with his teenage daughter Maya before she departs for college. While at the convention, he inadvertently discovers a heist - and it\'s up to Blart to apprehend the criminals.'),
(1725, '443791', 'en', 'https://image.tmdb.org/t/p/w500/gzlbb3yeVISpQ3REd3Ga1scWGTU.jpg', 'Underwater', '41.779', '2020-01-08', 6.3, '2242', '[\'Action\', \'Horror\', \'Science Fiction\', \'Thriller\']', 'After an earthquake destroys their underwater station, six researchers must navigate two miles along the dangerous, unknown depths of the ocean floor to make it to safety in a race against time.'),
(1726, '733491', 'en', 'https://image.tmdb.org/t/p/w500/1GJLLFlUaPEok4y8TXk5erbryt9.jpg', 'They Live Inside Us', '36.667', '2020-10-06', 5.8, '19', '[\'Horror\']', 'Seeking inspiration for a new writing project, a man spends Halloween night in a notoriously haunted house. He soon realizes he is living in his own horror story.'),
(1727, '22538', 'en', 'https://image.tmdb.org/t/p/w500/g5IoYeudx9XBEfwNL0fHvSckLBz.jpg', 'Scott Pilgrim vs. the World', '38.803', '2010-08-12', 7.4, '5963', '[\'Comedy\', \'Action\', \'Romance\', \'Fantasy\']', 'As bass guitarist for a garage-rock band, Scott Pilgrim has never had trouble getting a girlfriend; usually, the problem is getting rid of them. But when Ramona Flowers skates into his heart, he finds she has the most troublesome baggage of all: an army of ex-boyfriends who will stop at nothing to eliminate him from her list of suitors.'),
(1728, '758510', 'pt', 'https://image.tmdb.org/t/p/w500/nBdoS8tjWubpEyQnqmM6tpZR3GU.jpg', 'A Gruta', '30.768', '2020-10-29', 6.4, '64', '[\'Horror\']', 'The only one survivor of a mysterious murderer that killed his wife, friends and the tourism guide who leaded them through a interdicted grotto, a boy become the only suspect to make the crime. He, however, claim for his innocence saying that your wife killed those people as she was possessed by an evil force. Refusing to talk to police officers who are in charge for the crime investigation, he asks for help to a nun.'),
(1729, '458253', 'en', 'https://image.tmdb.org/t/p/w500/bqQ38oKuROlAgyZcRII9tqtoPNi.jpg', 'Missing Link', '35.566', '2019-04-04', 7, '626', '[\'Family\', \'Animation\', \'Comedy\', \'Adventure\', \'Fantasy\']', 'The charismatic Sir Lionel Frost considers himself to be the world\'s foremost investigator of myths and monsters. Trouble is, none of his small-minded, high-society peers seems to recognize this. Hoping to finally gain acceptance from these fellow adventurers, Sir Lionel travels to the Pacific Northwest to prove the existence of a legendary creature known as the missing link.'),
(1730, '37165', 'en', 'https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg', 'The Truman Show', '35.746', '1998-06-04', 8.1, '13863', '[\'Comedy\', \'Drama\']', 'Truman Burbank is the star of The Truman Show, a 24-hour-a-day reality TV show that broadcasts every aspect of his life without his knowledge. His entire life has been an unending soap opera for consumption by the rest of the world. And everyone he knows, including his wife and his best friend is really an actor, paid to be part of his life.'),
(1731, '425134', 'en', 'https://image.tmdb.org/t/p/w500/tjCDa24gNZGhpsFRhKnN9x83rTj.jpg', 'How to Be a Latin Lover', '40.548', '2017-03-06', 6.9, '493', '[\'Comedy\']', 'An aging Latin lover gets dumped by his sugar mama and must fend for himself in a harsh world.'),
(1732, '205126', 'en', 'https://image.tmdb.org/t/p/w500/6jor0EqECPgHqu89GrQIy9Wetkf.jpg', 'Independence Daysaster', '46.838', '2013-06-27', 4.6, '60', '[\'Action\', \'Science Fiction\']', 'When Earth is attacked by a hostile alien force, a small town firefighter and a rogue SETI scientist team up to activate the only technology capable of defeating the invaders.'),
(1733, '30497', 'en', 'https://image.tmdb.org/t/p/w500/mpgkRPH1GNkMCgdPk2OMyHzAks7.jpg', 'The Texas Chain Saw Massacre', '38.28', '1974-10-01', 7.3, '2117', '[\'Horror\']', 'When Sally hears that her grandfather\'s grave may have been vandalized, she and her paraplegic brother, Franklin, set out with their friends to investigate. After a detour to their family\'s old farmhouse, they discover a group of crazed, murderous outcasts living next door. As the group is attacked one by one by the chainsaw-wielding Leatherface, who wears a mask of human skin, the survivors must do everything they can to escape.'),
(1734, '50765', 'en', 'https://image.tmdb.org/t/p/w500/yHBeLWuTLozNLAXFnbeG0P89h0.jpg', 'Ticking Clock', '39.129', '2011-01-04', 5.4, '45', '[\'Action\', \'Thriller\', \'Science Fiction\', \'Mystery\']', 'A reporter stumbles upon the journal of a murderer replete with plans to butcher specific people, and investigates on his own, finding that every trail leads to a 9-year-old orphan living in a group home.'),
(1735, '390062', 'en', 'https://image.tmdb.org/t/p/w500/tDgxknTVwrScxpCYyGUjXSn5NRk.jpg', 'Jungle', '38.483', '2017-06-27', 6.5, '1459', '[\'Adventure\', \'Drama\', \'Thriller\']', 'In 1981, an enthusiastic young adventurer follows his dreams into the Bolivian Amazon jungle with two friends and a guide with a mysterious past. Their journey quickly turns into a terrifying ordeal as the darkest elements of human nature and the deadliest threats of the wilderness lead to an all-out fight for survival.'),
(1736, '866343', 'es', 'https://image.tmdb.org/t/p/w500/56Dc9tOU7k6u0uaJlogpH9AXvq2.jpg', 'Torcidos', '28.894', '2021-08-27', 4.8, '4', '[\'Horror\']', ''),
(1737, '6145', 'en', 'https://image.tmdb.org/t/p/w500/qNen8x5gaikjIg9CFihgxYcJwQe.jpg', 'Fracture', '32.723', '2007-04-19', 7.3, '2950', '[\'Thriller\']', 'A husband is on trial for the attempted murder of his wife, in what is seemingly an open/shut case for the ambitious district attorney trying to put him away. However, there are surprises for both around every corner, and, as a suspenseful game of cat-and-mouse is played out, each must manipulate and outwit the other.'),
(1738, '340676', 'en', 'https://image.tmdb.org/t/p/w500/cdm6qZgmbaIwjKBZnUSGWS4eyM2.jpg', 'Personal Shopper', '34.278', '2016-10-19', 5.9, '960', '[\'Drama\', \'Mystery\', \'Thriller\']', 'A personal shopper in Paris refuses to leave the city until she makes contact with her twin brother who previously died there. Her life becomes more complicated when a mysterious person contacts her via text message.'),
(1739, '367816', 'en', 'https://image.tmdb.org/t/p/w500/7HqyHRvkKvf7X6FkBJOcqaSvred.jpg', 'Ghostheads', '33.394', '2016-04-23', 5.9, '29', '[\'Documentary\']', 'Ghostheads is a documentary that explores the extreme side of the Ghostbusters fandom. Join us as we travel the world meeting extreme Ghostbusters fans. Every Ghosthead is unique. Every Franchise is its own. Every pop culture fandom should learn how to give back to the community.'),
(1740, '586954', 'de', 'https://image.tmdb.org/t/p/w500/saxPKOrN6rNScTicLpBDZw58Cw.jpg', 'Latte Igel und der magische Wasserstein', '40.131', '2019-12-11', 6.7, '78', '[\'Animation\', \'Adventure\', \'Family\', \'Comedy\']', 'When a greedy bear steals a magic stone to keep the forest’s water for himself, a brave hedgehog and a timid squirrel must work together to retrieve it.'),
(1741, '454619', 'en', 'https://image.tmdb.org/t/p/w500/41Rzkgo9y7n6BNGD6O8j0LVs8Yu.jpg', 'Overboard', '40.574', '2018-04-13', 6.6, '1089', '[\'Romance\', \'Comedy\']', 'A spoiled, wealthy yacht owner is thrown overboard and becomes the target of revenge from his mistreated employee.'),
(1742, '257088', 'en', 'https://image.tmdb.org/t/p/w500/tlbERIghrQ4oofqlbF7H0K0EYnx.jpg', 'Point Break', '35.018', '2015-12-03', 5.9, '1886', '[\'Action\', \'Crime\', \'Thriller\']', 'A young undercover FBI agent infiltrates a gang of thieves who share a common interest in extreme sports. A remake of the 1991 film, \"Point Break\".'),
(1743, '1368', 'en', 'https://image.tmdb.org/t/p/w500/dR5fbo0ry5TsC7euEXFUkx2QzVk.jpg', 'First Blood', '43.661', '1982-10-22', 7.4, '4632', '[\'Action\', \'Adventure\', \'Thriller\', \'War\']', 'When former Green Beret John Rambo is harassed by local law enforcement and arrested for vagrancy, the Vietnam vet snaps, runs for the hills and rat-a-tat-tats his way into the action-movie hall of fame. Hounded by a relentless sheriff, Rambo employs heavy-handed guerilla tactics to shake the cops off his tail.'),
(1744, '1267', 'en', 'https://image.tmdb.org/t/p/w500/naya0zF4kT401Sx15AtwB9vpcJr.jpg', 'Meet the Robinsons', '41.41', '2007-03-23', 6.9, '2153', '[\'Animation\', \'Comedy\', \'Family\']', 'Lewis, a brilliant young inventor, is keen on creating a time machine to find his mother, who abandoned him in an orphanage. Things take a turn when he meets Wilbur Robinson and his family.'),
(1745, '157433', 'en', 'https://image.tmdb.org/t/p/w500/a1gIACZb04bL8EvLqMpofW2Eqeo.jpg', 'Pet Sematary', '35.473', '2019-04-04', 5.7, '2553', '[\'Horror\', \'Thriller\']', 'Dr. Louis Creed and his wife, Rachel, move from Boston to Ludlow, in rural Maine, with their two young children. Hidden in the woods near the new family home, Ellie, their eldest daughter, discovers a mysterious cemetery where the pets of community members are buried.'),
(1746, '10866', 'en', 'https://image.tmdb.org/t/p/w500/1LVGjf1QWgkNNPQssZtuT1GYKoP.jpg', 'Joy Ride', '28.006', '2001-10-05', 6.5, '862', '[\'Mystery\', \'Thriller\', \'Drama\']', 'Three young people on a road trip from Colorado to New Jersey talk to a trucker on their CB radio, then must escape when he turns out to be a psychotic killer.'),
(1747, '19286', 'en', 'https://image.tmdb.org/t/p/w500/z9NT2smK66pYOjBtmZuKFFTZ478.jpg', 'Leprechaun 3', '39.203', '1995-07-04', 5.9, '196', '[\'Comedy\', \'Fantasy\', \'Horror\']', 'It was a normal night in Las Vegas, Nevada, all the lights were flashing brightly, until a man with one hand, one eye, and one leg walks into a pawn shop with a statue of a hideous looking Leprechaun. The owner claims it\'s a good luck charm. The statue also wore a medallion around it\'s neck. The careless pawn shop owner took off the medallion setting the Leprechaun free...'),
(1748, '644495', 'en', 'https://image.tmdb.org/t/p/w500/oJCQjD2byiVF1EG408F9dBn9ndU.jpg', 'House of Gucci', '47.604', '2021-11-24', 0, '0', '[\'Crime\', \'Drama\']', 'The true story of how Patrizia Reggiani plotted to kill her husband Maurizio Gucci, the grandson of renowned fashion designer Guccio Gucci.'),
(1749, '333667', 'en', 'https://image.tmdb.org/t/p/w500/7RXi2afiNJGU8EB79SD8HYoSz4O.jpg', 'Rock Dog', '36.247', '2016-07-08', 6.1, '213', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\', \'Music\']', 'When a radio falls from the sky into the hands of a wide-eyed Tibetan Mastiff, he leaves home to fulfill his dream of becoming a musician, setting into motion a series of completely unexpected events.'),
(1750, '593655', 'en', 'https://image.tmdb.org/t/p/w500/HJEosQRIdBzAHEdZJCUF7e5FmF.jpg', 'Castle Freak', '39.435', '2020-12-04', 5.1, '30', '[\'Horror\']', 'After she’s permanently blinded in a tragic car accident, Rebecca receives some bizarre news: her long-lost mother has recently passed away, leaving her their family’s ancestral castle in rural Albania. Traveling to the estate with a group of friends, Rebecca hopes it will be an opportunity for her to reconnect with a past she never knew and a mother who seemingly left her behind. When mysterious events begin to occur and her friends begin to die, Rebecca must unravel the secrets of her family’s history before she too falls prey to the Castle Freak.'),
(1751, '718022', 'en', 'https://image.tmdb.org/t/p/w500/txaORGh8oqj9FITxOMg6JRPAwv2.jpg', 'Heks', '34.311', '2020-12-15', 6.3, '26', '[\'Horror\', \'Drama\']', 'A grieving British girl unravels her murdered mother\'s secrets connected to a South African witch doctor\'s curse. She wants to put an end to this haunting hex by traveling to South Africa, but instead it casts her deeper into sinister depths.'),
(1752, '15070', 'en', 'https://image.tmdb.org/t/p/w500/q8smM97IBBEWmkaUCmkPqysh7k7.jpg', 'Undisputed', '41.923', '2002-07-17', 6.5, '496', '[\'Action\', \'Adventure\', \'Drama\', \'Thriller\']', 'Monroe Hutchens is the heavyweight champion of Sweetwater, a maximum security prison. He was convicted to a life sentence due to a passionate crime. Iceman Chambers is the heavyweight champion, who lost his title due to a rape conviction to ten years in Sweetwater. WHen these two giants collide in the same prison, they fight against each other disputing who is the real champion.'),
(1753, '44874', 'en', 'https://image.tmdb.org/t/p/w500/bFnf8f8DXdCANQ7Y62djgubhh4P.jpg', 'Barbie: A Fashion Fairytale', '43.97', '2010-09-14', 7.2, '537', '[\'Family\', \'Animation\']', 'Join Barbie in a colourful, modern-day fairytale filled with fashion, friends and fun! Barbie and her dog Sequin jet off to visit her Aunt\'s amazing fashion house in Paris, and much to her surprise it\'s about to be shut down forever. After she discovers three enchanting Flairies with sparkle-magic powers, Barbie comes up with a brilliant idea to save the business. She even inspires Alice, a shy fashion designer, and together they create a dazzling runway fashion show. Barbie shows that magic happens when you believe in yourself.'),
(1754, '4011', 'en', 'https://image.tmdb.org/t/p/w500/nnl6OWkyPpuMm595hmAxNW3rZFn.jpg', 'Beetlejuice', '41.717', '1988-03-30', 7.4, '5068', '[\'Fantasy\', \'Comedy\']', 'Thanks to an untimely demise via drowning, a young couple end up as poltergeists in their New England farmhouse, where they fail to meet the challenge of scaring away the insufferable new owners, who want to make drastic changes. In desperation, the undead newlyweds turn to an expert frightmeister, but he\'s got a diabolical agenda of his own.'),
(1755, '36647', 'en', 'https://image.tmdb.org/t/p/w500/hx0sdduAsr4rq03RZKZzglR25z7.jpg', 'Blade', '46.018', '1998-08-21', 6.7, '4513', '[\'Horror\', \'Action\']', 'The Daywalker known as \"Blade\" - a half-vampire, half-mortal man - becomes the protector of humanity against an underground army of vampires.'),
(1756, '5175', 'en', 'https://image.tmdb.org/t/p/w500/aBQf2vMiCINeVC9v6BGVYKXurTh.jpg', 'Rush Hour 2', '34.665', '2001-08-03', 6.7, '2972', '[\'Action\', \'Comedy\', \'Crime\']', 'It\'s vacation time for Carter as he finds himself alongside Lee in Hong Kong wishing for more excitement. While Carter wants to party and meet the ladies, Lee is out to track down a Triad gang lord who may be responsible for killing two men at the American Embassy. Things get complicated as the pair stumble onto a counterfeiting plot. The boys are soon up to their necks in fist fights and life-threatening situations. A trip back to the U.S. may provide the answers about the bombing, the counterfeiting, and the true allegiance of sexy customs agent Isabella.'),
(1757, '8392', 'ja', 'https://image.tmdb.org/t/p/w500/rtGDOeG9LzoerkDGZF9dnVeLppL.jpg', 'となりのトトロ', '42.16', '1988-04-16', 8.1, '5731', '[\'Fantasy\', \'Animation\', \'Family\']', 'Two sisters move to the country with their father in order to be closer to their hospitalized mother, and discover the surrounding trees are inhabited by Totoros, magical spirits of the forest. When the youngest runs away from home, the older sister seeks help from the spirits to find her.'),
(1758, '180147', 'es', 'https://image.tmdb.org/t/p/w500/40JLnLz5KEQeZnUCKD3zf8sQJFx.jpg', 'Nosotros los nobles', '30.709', '2013-03-28', 7.8, '356', '[\'Comedy\']', 'Tells the \"riches to rags\" story of the Nobles, three upper-class twenty-somethings that appear to have no limits to their checkbooks, and no direction in their lives. Until one day, their father tries to teach them a lesson by staging a financial scandal that forces the whole family to escape to an old house in the poor side of town, and leads the \"kids\" to do what they haven\'t done before: get jobs.'),
(1759, '348350', 'en', 'https://image.tmdb.org/t/p/w500/4oD6VEccFkorEBTEDXtpLAaz0Rl.jpg', 'Solo: A Star Wars Story', '38.111', '2018-05-15', 6.6, '6612', '[\'Science Fiction\', \'Adventure\', \'Action\', \'Crime\']', 'Through a series of daring escapades deep within a dark and dangerous criminal underworld, Han Solo meets his mighty future copilot Chewbacca and encounters the notorious gambler Lando Calrissian.'),
(1760, '677430', 'en', 'https://image.tmdb.org/t/p/w500/23qwvuYDEzCDv3BlgKUfpuRukbm.jpg', 'Los 7 pecados capitales', '38.656', '1975-01-01', 5.8, '7', '[]', 'Mexican feature film'),
(1761, '82693', 'en', 'https://image.tmdb.org/t/p/w500/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg', 'Silver Linings Playbook', '39.397', '2012-09-08', 7.1, '10099', '[\'Drama\', \'Comedy\', \'Romance\']', 'After spending eight months in a mental institution, a former teacher moves back in with his parents and tries to reconcile with his ex-wife.'),
(1762, '842096', 'en', 'https://image.tmdb.org/t/p/w500/c0RwJWGu2urVpeVBABchemspdeE.jpg', 'Civil War (Or, Who Do We Think We Are)', '33.849', '2021-06-17', 2, '1', '[\'Documentary\']', 'A journey across the United States to explore the story of the Civil War of Americans from President Obama\'s final year in office through the present.'),
(1763, '643532', 'en', 'https://image.tmdb.org/t/p/w500/y5DNLVg0gPiGSkuK4yFc4fjQ42Q.jpg', 'The Card Counter', '34.567', '2021-09-03', 6.6, '201', '[\'Drama\', \'Thriller\', \'Crime\']', 'William Tell just wants to play cards. His spartan existence on the casino trail is shattered when he is approached by Cirk, a vulnerable and angry young man seeking help to execute his plan for revenge on a military colonel. Tell sees a chance at redemption through his relationship with Cirk. But keeping Cirk on the straight-and-narrow proves impossible, dragging Tell back into the darkness of his past.'),
(1764, '80410', 'en', 'https://image.tmdb.org/t/p/w500/kM9hjeGLtPZi9ExuBVwIFYrQbx0.jpg', 'In the Name of the King 2: Two Worlds', '42.894', '2011-11-03', 3.9, '90', '[\'Adventure\', \'Fantasy\', \'Drama\', \'Action\']', 'Granger, an ex-Special Forces soldier gets thrown back to medieval times to fulfill an ancient prophecy. Venturing through the now war torn Kingdom of Ehb, he teams up with an unlikely band of allies with the goal of slaying the leader of the \"Dark Ones\". Fighting against all odds, they must free the land from the grasp of the evil tyrant Raven and save the world.'),
(1765, '107985', 'en', 'https://image.tmdb.org/t/p/w500/kpglnOBYmKn0AkkWDzGxzKHDbds.jpg', 'The World\'s End', '34.941', '2013-07-18', 6.8, '4252', '[\'Comedy\', \'Action\', \'Science Fiction\']', 'Five friends who reunite in an attempt to top their epic pub crawl from 20 years earlier unwittingly become humankind\'s only hope for survival.'),
(1766, '764', 'en', 'https://image.tmdb.org/t/p/w500/54C1qdaiSijIU5NeNb4WsPJdNkG.jpg', 'The Evil Dead', '34.685', '1981-09-10', 7.3, '2699', '[\'Horror\']', 'When a group of college students finds a mysterious book and recording in the old wilderness cabin they\'ve rented for the weekend, they unwittingly unleash a demonic force from the surrounding forest.'),
(1767, '285812', 'ja', 'https://image.tmdb.org/t/p/w500/xKGMXQFGca4nKcO308aZ6nWz0Gc.jpg', '映画 ドラえもん 新・のび太の大魔境 〜ペコと5人の探検隊〜', '34.125', '2014-03-08', 7.1, '48', '[\'Family\', \'Animation\', \'Adventure\']', 'The film starts with Gian seeing some like spirit and it asks him to accomplish a task. The story starts when a stray dogs are searching some foods in the can. Then a dirty white dog comes out of nowhere. Just then, the dog creates a close stare to the stray dogs and forces to run away. But the dog is disappointed that he doesn\'t know what to do after searching the garbage, under the pouring rain. After that, Suneo starts saying about the discoverable places on Earth and him and Gian are totally disappointed about that. That then, they are asking favor to Nobita to take them to an undiscovered place to be seen by their naked eyes. Nobita refuses but tells he will try his best. He comes to upstairs to explain Doraemon what the problem is now.'),
(1768, '127533', 'ja', 'https://image.tmdb.org/t/p/w500/vo3Zs07PZfKNsTrU0pcPZONJcN5.jpg', 'るろうに剣心', '35.933', '2012-08-25', 7.6, '535', '[\'Adventure\', \'Action\', \'Drama\', \'History\']', 'Former legendary assassin Kenshin Himura has now become a wandering samurai. Offering aid & protecting those in need as atonement for his past deeds. During this time Kenshin Himura comes across and aides Kaoru Kamiya (Emi Takei). Her father opened the Kamiya Kasshin-ryu, a kendo school located in Tokyo and Kaoru is now an instructor there. Kaoru then invites Kenshin to stay at her dojo. Their relationship develops further, but Kenshin is still haunted by his violent past...'),
(1769, '4234', 'en', 'https://image.tmdb.org/t/p/w500/qpH8ToZVlFD1bakL04LkEKodyDI.jpg', 'Scream 3', '38.376', '2000-02-03', 5.9, '2207', '[\'Horror\', \'Mystery\']', 'A murdering spree begins to happen again, this time its targeted toward the original Woodsboro survivors and those associated with the movie inside a movie, \'Stab 3\'. Sydney must face the demons of her past to stop the killer.'),
(1770, '778730', 'es', 'https://image.tmdb.org/t/p/w500/6PbSSN2BT22ZMsMaD7m8cGaqk3L.jpg', 'Loco por ella', '35.245', '2021-02-26', 7.3, '340', '[\'Comedy\', \'Romance\']', 'After a magical night together, Adri voluntarily turns himself into the psychiatric institution where Carla lives.'),
(1771, '13788', 'en', 'https://image.tmdb.org/t/p/w500/42H2aaD5UubsHyWt6zfrFMRP8y1.jpg', 'The Unborn', '39.924', '2009-01-09', 5.2, '1077', '[\'Horror\', \'Thriller\', \'Mystery\']', 'A young woman fights the spirit that is slowly taking possession of her.'),
(1772, '614917', 'en', 'https://image.tmdb.org/t/p/w500/2dfujXrxePtYJPiPHj1HkAFQvpu.jpg', 'King Richard', '36.555', '2021-11-18', 0, '0', '[\'Drama\']', 'Richard Williams serves as a coach to his daughters Venus and Serena, who will soon become two of the most legendary tennis players in history.'),
(1773, '38199', 'en', 'https://image.tmdb.org/t/p/w500/6yQqguytl10FhImngDHV90Aqewa.jpg', 'Unthinkable', '31.173', '2010-06-14', 6.7, '880', '[\'Drama\', \'Thriller\']', 'The government gets wind of a plot to destroy America involving a trio of nuclear weapons for which the whereabouts are unknown. It\'s up to a seasoned interrogator and an FBI agent to find out exactly where the nukes are.'),
(1774, '68728', 'en', 'https://image.tmdb.org/t/p/w500/tkzfAUEKoUp4YFNbZV9hfpZOz0z.jpg', 'Oz the Great and Powerful', '44.82', '2013-03-07', 5.9, '5774', '[\'Fantasy\', \'Adventure\', \'Family\']', 'Oscar Diggs, a small-time circus illusionist and con-artist, is whisked from Kansas to the Land of Oz where the inhabitants assume he\'s the great wizard of prophecy, there to save Oz from the clutches of evil.'),
(1775, '300168', 'zh', 'https://image.tmdb.org/t/p/w500/m5yyMErIDbdzVLIDXVBG6EzM1oF.jpg', '天將雄師', '39.421', '2015-02-19', 6.3, '422', '[\'Action\', \'Drama\', \'Adventure\']', 'Huo An, the commander of the Protection Squad of the Western Regions, was framed by evil forces and becomes enslaved. On the other hand, a Roman general escapes to China after rescuing the Prince. The heroic duo meet in the Western Desert and a thrilling story unfolds.');
INSERT INTO `top_10000_movies` (`index`, `id_film`, `language`, `image_url`, `title`, `popularity`, `release_date`, `vote_average`, `vote_count`, `genre`, `overview`) VALUES
(1776, '95', 'en', 'https://image.tmdb.org/t/p/w500/eTM3qtGhDU8cvjpoa6KEt5E2auU.jpg', 'Armageddon', '38.165', '1998-07-01', 6.8, '6219', '[\'Action\', \'Thriller\', \'Science Fiction\', \'Adventure\']', 'When an asteroid threatens to collide with Earth, NASA honcho Dan Truman determines the only way to stop it is to drill into its surface and detonate a nuclear bomb. This leads him to renowned driller Harry Stamper, who agrees to helm the dangerous space mission provided he can bring along his own hotshot crew. Among them is the cocksure A.J. who Harry thinks isn\'t good enough for his daughter, until the mission proves otherwise.'),
(1777, '330459', 'en', 'https://image.tmdb.org/t/p/w500/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', 'Rogue One: A Star Wars Story', '41.013', '2016-12-14', 7.5, '12546', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.'),
(1778, '7191', 'en', 'https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg', 'Cloverfield', '35.099', '2008-01-15', 6.6, '5568', '[\'Action\', \'Thriller\', \'Science Fiction\']', 'Five young New Yorkers throw their friend a going-away party the night that a monster the size of a skyscraper descends upon the city. Told from the point of view of their video camera, the film is a document of their attempt to survive the most surreal, horrifying event of their lives.'),
(1779, '65759', 'en', 'https://image.tmdb.org/t/p/w500/2gWiQ4mn85jcXtREVePlVViupeV.jpg', 'Happy Feet Two', '43.149', '2011-11-18', 6.1, '1168', '[\'Animation\', \'Comedy\', \'Family\']', 'Mumble the penguin has a problem: his son Erik, who is reluctant to dance, encounters The Mighty Sven, a penguin who can fly! Things get worse for Mumble when the world is shaken by powerful forces, causing him to brings together the penguin nations and their allies to set things right.'),
(1780, '701524', 'es', 'https://image.tmdb.org/t/p/w500/hlq6tv7sFAA7LtNu7Rk8Fw6Kfu1.jpg', 'Una película de policías', '57.344', '2021-10-28', 7, '9', '[\'Documentary\']', 'This documentary walks the line between fact and fiction, delving into corruption in the Mexican police through the experiences of two officers.'),
(1781, '134162', 'ja', 'https://image.tmdb.org/t/p/w500/4rLQFXpnE4m87NS31CKwjRspGrd.jpg', '映画ドラえもん のび太と雲の王国', '35.594', '1992-03-07', 6.8, '15', '[\'Animation\']', 'Doraemon launches its ecological adventure to save Earth from a terrible threat with Nobita and his whole gang. This time Doraemon used his inventions to create, along with Nobita, his own world in the sky, a giant cloud. During their journey to the cloud are alien beings who seek to destroy civilization to chasten humans for their lack of commitment to the environment. Doraemon and the gang must find allies and convince the people of the clouds on Earth that there are people who fight for nature. In his adventure, meet good friends, raffled countless dangers, will encounter prehistoric animals and will give everything to defend our planet.'),
(1782, '393457', 'en', 'https://image.tmdb.org/t/p/w500/8NvnB8aeWQvBEz2ruN4g313j991.jpg', 'Fences', '35.149', '2016-12-16', 6.8, '2059', '[\'Drama\']', 'In 1950s Pittsburgh, a frustrated African-American father struggles with the constraints of poverty, racism, and his own inner demons as he tries to raise a family.'),
(1783, '79224', 'ko', 'https://image.tmdb.org/t/p/w500/iOTRRHt9GNbUfQhV3MhMCznjrPI.jpg', '최종병기 활', '30.39', '2011-08-10', 7.1, '175', '[\'Drama\', \'Action\', \'History\', \'Thriller\']', '13 years after the King Injo Revolt, the Chosun Dynasty is attacked by the Chung Dynasty of China. A young man named Na-mi leaves his demolished village to find his young sister, Ja-in, and her finance Su-koon, who were to wed on the very day of the attack. While on his mission to rescue her, he is being traced by Jushinta, a fierce Chung Warrior, and his band of malicious men who are out to stop him. Na-mi has but a day to rescue his sister before she is taken away to be a slave. When Na-mi finally finds his sister, Jushinta comes between them and a fierce battle between two of the finest warriors unfolds.'),
(1784, '807', 'en', 'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', 'Se7en', '39.431', '1995-09-22', 8.3, '16007', '[\'Crime\', \'Mystery\', \'Thriller\']', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the \"seven deadly sins\" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Sommerset researches each sin in an effort to get inside the killer\'s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.'),
(1785, '227973', 'en', 'https://image.tmdb.org/t/p/w500/aiwdwnl7RFs1vcBanOKr13ye3wE.jpg', 'The Peanuts Movie', '38.087', '2015-11-01', 6.8, '1259', '[\'Adventure\', \'Comedy\', \'Animation\', \'Family\']', 'Snoopy embarks upon his greatest mission as he and his team take to the skies to pursue their arch-nemesis, while his best pal Charlie Brown begins his own epic quest.'),
(1786, '98613', 'ja', 'https://image.tmdb.org/t/p/w500/kdBLKFviJckRXOCgPqkTQK16Rq0.jpg', '映画ドラえもん のび太とふしぎ風使い', '32.429', '2003-03-08', 7.1, '35', '[\'Animation\']', 'One day, Nobita runs into a creature-like ball of wind, which came from a faraway land, but blew into their neighbourhood following the recent typhoon that went through the area. Nobita names it Fuuko. Eventually, he, Doraemon and their friends take it to a vast countryside through the Anywhere Door. There, they learn about the Wind and Storm Villages, and Fuuko’s real identity. Soon, Nobita and his friends have to protect Fuuko from the Storm Village and a now-possessed Nobuo, who is being controlled by the spirit of the Storm Village’s former leader.'),
(1787, '616820', 'en', 'https://image.tmdb.org/t/p/w500/q06saepaXeBdkMibuN4R2fXmgIw.jpg', 'Halloween Ends', '32.685', '2022-10-13', 0, '0', '[\'Horror\', \'Thriller\']', 'Four years after the traumatic events of Halloween 2018, the nightmare ends as Laurie Strode comes face to face with Michael Myers, once and for all.'),
(1788, '601470', 'en', 'https://image.tmdb.org/t/p/w500/h09nsvxZH72zx2U8gS8vrg47aRk.jpg', 'The Eyes of Tammy Faye', '35.655', '2021-09-17', 6, '21', '[\'Drama\', \'History\']', 'In the 1970s and ’80s, Tammy Faye and Jim Bakker rose from humble beginnings to create the world’s largest religious broadcasting network and a theme park, and were revered for their message of love, acceptance, and prosperity.'),
(1789, '871', 'en', 'https://image.tmdb.org/t/p/w500/2r9iKnlSYEk4daQadsXfcjHfIjQ.jpg', 'Planet of the Apes', '34.377', '1968-02-07', 7.7, '2493', '[\'Science Fiction\', \'Adventure\', \'Drama\', \'Action\']', 'An  U.S. Spaceship lands on a desolate planet, stranding astronaut Taylor in a world dominated by apes, 2000 years into the future, who use a primitive race of humans for experimentation and sport. Soon Taylor finds himself among the hunted, his life in the hands of a benevolent chimpanzee scientist.'),
(1790, '254', 'en', 'https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', 'King Kong', '41.627', '2005-12-12', 6.8, '6275', '[\'Adventure\', \'Drama\', \'Action\']', 'In 1933 New York, an overly ambitious movie producer coerces his cast and hired ship crew to travel to mysterious Skull Island, where they encounter Kong, a giant ape who is immediately smitten with the leading lady.'),
(1791, '575774', 'en', 'https://image.tmdb.org/t/p/w500/mM1ELeOF4qmdIFbZh9VSBn685g.jpg', 'His House', '34.152', '2020-01-27', 6.5, '677', '[\'Drama\', \'Horror\', \'Thriller\']', 'After making a harrowing escape from war-torn South Sudan, a young refugee couple struggle to adjust to their new life in a small English town that has an unspeakable evil lurking beneath the surface.'),
(1792, '15512', 'en', 'https://image.tmdb.org/t/p/w500/hpHarddVj34j53T7NsoUGdKj4mP.jpg', 'Monsters vs Aliens', '31.325', '2009-03-19', 6.2, '3634', '[\'Animation\', \'Family\', \'Adventure\', \'Science Fiction\']', 'When Susan Murphy is unwittingly clobbered by a meteor full of outer space gunk on her wedding day, she mysteriously grows to 49-feet-11-inches. The military jumps into action and captures Susan, secreting her away to a covert government compound. She is renamed Ginormica and placed in confinement with a ragtag group of Monsters...'),
(1793, '1402', 'en', 'https://image.tmdb.org/t/p/w500/lBYOKAMcxIvuk9s9hMuecB9dPBV.jpg', 'The Pursuit of Happyness', '41.221', '2006-12-14', 7.9, '7797', '[\'Drama\']', 'A struggling salesman takes custody of his son as he\'s poised to begin a life-changing professional career.'),
(1794, '11621', 'ja', 'https://image.tmdb.org/t/p/w500/8mIvSvnVBApfORL9N6S38Q7wD6A.jpg', '紅の豚', '37.119', '1992-07-18', 7.8, '2276', '[\'Family\', \'Comedy\', \'Animation\', \'Adventure\']', 'In Italy in the 1930s, sky pirates in biplanes terrorize wealthy cruise ships as they sail the Adriatic Sea. The only pilot brave enough to stop the scourge is the mysterious Porco Rosso, a former World War I flying ace who was somehow turned into a pig during the war. As he prepares to battle the pirate crew\'s American ace, Porco Rosso enlists the help of spunky girl mechanic Fio Piccolo and his longtime friend Madame Gina.'),
(1795, '257211', 'en', 'https://image.tmdb.org/t/p/w500/bTQ46fupPbjBfFBHuzfD3hxxL0Q.jpg', 'The Intern', '39.925', '2015-09-24', 7.2, '5297', '[\'Comedy\']', '70-year-old widower Ben Whittaker has discovered that retirement isn\'t all it\'s cracked up to be. Seizing an opportunity to get back in the game, he becomes a senior intern at an online fashion site, founded and run by Jules Ostin.'),
(1796, '228967', 'en', 'https://image.tmdb.org/t/p/w500/tIDC4xT65l7a8qbgg8GvwD5g8c5.jpg', 'The Interview', '40.703', '2014-12-25', 6.2, '4712', '[\'Action\', \'Comedy\']', 'Dave Skylark and his producer Aaron Rapaport run the celebrity tabloid show \"Skylark Tonight\". When they land an interview with a surprise fan, North Korean dictator Kim Jong-un, they are recruited by the CIA to turn their trip to Pyongyang into an assassination mission.'),
(1797, '169', 'en', 'https://image.tmdb.org/t/p/w500/83X4VwY9sdSJykskmsplIVG0a4h.jpg', 'Predator 2', '40.014', '1990-11-20', 6.2, '2169', '[\'Science Fiction\', \'Action\', \'Thriller\']', 'A police chief in the war-torn streets of Los Angeles discovers that an extraterrestrial creature is hunting down residents - and that he is the next target.'),
(1798, '25259', 'es', 'https://image.tmdb.org/t/p/w500/iVpY6WbHE7DWphB5lBLKn4phaw1.jpg', '7 minutos', '39.041', '2009-06-12', 3.9, '6', '[\'Comedy\']', '¿Bastan 7 minutos para enamorarse? Los protagonistas de esta comedia coral y romántica no lo tienen claro. Pero lo van a intentar. Por eso acuden a una sesión de \"citas rápidas\", encuentros entre hombres y mujeres que quieren conocer gente, huir de la soledad y encontrar el amor.En estas veladas, cada uno tiene siete minutos para hablar con cada una, y viceversa. Luego, todos se van a casa y votan por Internet a aquellas personas que les han gustado. Si el voto es coincidente, la empresa que organiza los encuentros remite a los interesados los e-mails respectivos, y a partir de ahí, puede surgir o no una historia...'),
(1799, '5174', 'en', 'https://image.tmdb.org/t/p/w500/mp9CzKxLa2i7yblMXUrzVfGqsCo.jpg', 'Rush Hour 3', '34.557', '2007-08-08', 6.4, '2308', '[\'Action\', \'Comedy\', \'Crime\']', 'After a botched assassination attempt, the mismatched duo finds themselves in Paris, struggling to retrieve a precious list of names, as the murderous crime syndicate\'s henchmen try their best to stop them. Once more, Lee and Carter must fight their way through dangerous gangsters; however, this time, the past has come back to haunt Lee. Will the boys get the job done once and for all?'),
(1800, '638507', 'en', 'https://image.tmdb.org/t/p/w500/kXj2Qrfm994yLeuADqbOieU1mUH.jpg', 'How to Train Your Dragon: Homecoming', '37.622', '2019-10-25', 8.2, '627', '[\'Animation\', \'Fantasy\', \'Adventure\', \'Action\', \'Family\']', 'It\'s been ten years since the dragons moved to the Hidden World, and even though Toothless doesn\'t live in New Berk anymore, Hiccup continues the holiday traditions he once shared with his best friend. But the Vikings of New Berk were beginning to forget about their friendship with dragons. Hiccup, Astrid, and Gobber know just what to do to keep the dragons in the villagers\' hearts. And across the sea, the dragons have a plan of their own...'),
(1801, '78049', 'en', 'https://image.tmdb.org/t/p/w500/pmLWbxZhZADXk4gpzLiHs5blDkc.jpg', 'The Scorpion King 3: Battle for Redemption', '41.55', '2012-01-17', 4.5, '246', '[\'Action\', \'Adventure\', \'Fantasy\', \'Drama\']', 'Since his triumphant rise to power in the original blockbuster \"The Scorpion King\", Mathayus\' kingdom has fallen and he\'s lost his queen to plague. Now an assassin for hire, he must defend a kingdom from an evil tyrant and his ghost warriors for the chance to regain the power and glory he once knew. Starring Ron Perlman (\"Hellboy\") and Billy Zane (\"Titanic\"), and featuring 6-time WWE champion Dave Bautista and UFC star Kimbo Slice, \"The Scorpion King 3: Battle for Redemption\" takes \"The Mummy\" phenomenon to an all-new level of epic action and non-stop adventure.'),
(1802, '353491', 'en', 'https://image.tmdb.org/t/p/w500/i9GUSgddIqrroubiLsvvMRYyRy0.jpg', 'The Dark Tower', '35.001', '2017-08-03', 5.7, '4130', '[\'Fantasy\', \'Action\', \'Science Fiction\', \'Adventure\']', 'A boy haunted by visions of a parallel world aids its disillusioned guardian in preventing the destruction of the nexus of universes known as the Dark Tower.'),
(1803, '9679', 'en', 'https://image.tmdb.org/t/p/w500/fToQDmkBtiXYGh9xfgAh3gpo6GZ.jpg', 'Gone in Sixty Seconds', '40.838', '2000-06-09', 6.4, '3380', '[\'Action\', \'Crime\', \'Thriller\']', 'Upon learning that he has to come out of retirement to steal 50 cars in one night to save his brother Kip\'s life, former car thief Randall \"Memphis\" Raines enlists help from a few \"boost happy\" pals to accomplish a seemingly impossible feat. From countless car chases to relentless cops, the high-octane excitement builds as Randall swerves around more than a few roadblocks to keep Kip alive.'),
(1804, '277597', 'en', 'https://image.tmdb.org/t/p/w500/eba3J71GIIXncTVzS3fMqjdMzfz.jpg', 'Mercenaries', '40.321', '2014-08-05', 5.3, '91', '[\'Action\']', 'A diplomatic official is captured and imprisoned while touring a war zone, so a team of elite female commandos is assembled to infiltrate a women\'s prison for a daring rescue.'),
(1805, '17445', 'en', 'https://image.tmdb.org/t/p/w500/ii48ohKJrDPyrGGOBVJ8XSxr5Xk.jpg', 'Green Lantern: First Flight', '39.038', '2009-07-28', 6.9, '308', '[\'Action\', \'Adventure\', \'Animation\', \'Fantasy\', \'Science Fiction\']', 'Test pilot Hal Jordan finds himself recruited as the newest member of the intergalactic police force, The Green Lantern Corps.'),
(1806, '87827', 'en', 'https://image.tmdb.org/t/p/w500/iLgRu4hhSr6V1uManX6ukDriiSc.jpg', 'Life of Pi', '40.784', '2012-11-20', 7.4, '11142', '[\'Adventure\', \'Drama\', \'Action\']', 'The story of an Indian boy named Pi, a zookeeper\'s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.'),
(1807, '891657', 'en', 'https://image.tmdb.org/t/p/w500/yoDchepiE9Tcv36ivkzOF4z75ws.jpg', 'LEGO Hidden Side: Night of the Harbinger', '56.703', '2020-10-31', 3, '2', '[\'Animation\']', 'The boys want to seal a hole in Hidden Side when a ghost escapes covered in a silver substance and says  That your world is doomed'),
(1808, '785537', 'tr', 'https://image.tmdb.org/t/p/w500/AvWrbe0FxXKjytWaOzMGXaFzoz4.jpg', 'Geçen Yaz', '40.652', '2021-07-09', 5.8, '31', '[\'Romance\', \'Drama\']', 'For Deniz, a 16-year-old teenager, this summer is different from the others. Deniz, who goes to his family\'s summer house every year, falls in love with a young girl named Aslı. Trying to get closer to Aslı, Deniz realizes that a handsome young man, Burak, also likes Aslı.'),
(1809, '345911', 'en', 'https://image.tmdb.org/t/p/w500/8BnElzAQQpp7ZgdJJiAe1diomr4.jpg', 'Lights Out', '35.527', '2016-07-21', 6.3, '3122', '[\'Horror\', \'Thriller\', \'Mystery\']', 'Rebecca must unlock the terror behind her little brother\'s experiences that once tested her sanity, bringing her face to face with a supernatural spirit attached to their mother.'),
(1810, '496450', 'en', 'https://image.tmdb.org/t/p/w500/dQNJ8SdCMn3zWwHzzQD2xrphR1X.jpg', 'Ladybug & Cat Noir Awakening', '30.067', '', 0, '0', '[\'Action\', \'Romance\', \'Animation\', \'Music\', \'Fantasy\', \'Adventure\']', 'Ladybug & Cat Noir Awakening is an upcoming animated musical film based on the children\'s animated series Miraculous: Tales of Ladybug & Cat Noir. It will be released in 2021.'),
(1811, '459159', 'en', 'https://image.tmdb.org/t/p/w500/sNxIazoQqDQukfQqkYxTgx9DRbu.jpg', 'Hotel Transylvania: Puppy!', '33.578', '2017-07-28', 6.3, '122', '[\'Family\', \'Fantasy\', \'Animation\', \'Comedy\']', 'The residents of Hotel Transylvania find their world turned upside-down when youngster Dennis gets a surprise monster-sized pet.'),
(1812, '240', 'en', 'https://image.tmdb.org/t/p/w500/hek3koDUyRQk7FIhPXsa6mT2Zc3.jpg', 'The Godfather: Part II', '44.959', '1974-12-20', 8.6, '9028', '[\'Drama\', \'Crime\']', 'In the continuing saga of the Corleone crime family, a young Vito Corleone grows up in Sicily and in 1910s New York. In the 1950s, Michael Corleone attempts to expand the family business into Las Vegas, Hollywood and Cuba.'),
(1813, '11978', 'en', 'https://image.tmdb.org/t/p/w500/wNUAnXV1mzOOfvnVBIYsalkk078.jpg', 'Men of Honor', '34.759', '2000-09-13', 7.4, '1639', '[\'Drama\']', 'Against formidable odds -- and an old-school diving instructor embittered by the U.S. Navy\'s new, less prejudicial policies -- Carl Brashear sets his sights on becoming the Navy\'s first African-American master diver in this uplifting true story. Their relationship starts out on the rocks, but fate ultimately conspires to bring the men together into a setting of mutual respect, triumph and honor.'),
(1814, '300803', 'en', 'https://image.tmdb.org/t/p/w500/qPiyMWZHlRGgQ54roaraS3iJR12.jpg', 'Dragonheart 3: The Sorcerer\'s Curse', '36.01', '2015-02-24', 5.4, '193', '[\'Fantasy\']', 'When aspiring knight Gareth goes in search of a fallen comet rumored to contain gold, he is shocked to instead find the dragon Drago. After Drago saves Gareth\'s life the two become intricately bonded, and must work together to defeat an evil sorcerer and stop his reign of terror. Along the way, Gareth learns the true meaning of being a knight in this fantasy action-adventure for the ages.'),
(1815, '822010', 'en', 'https://image.tmdb.org/t/p/w500/lc1EVTeZzI4hgQQOXpEDzS26BZY.jpg', 'Danny Boy', '40.586', '2021-05-12', 7.8, '6', '[\'Drama\', \'War\', \'TV Movie\']', 'Soldier Brian Wood, is accused of war crimes in Iraq by the human rights lawyer Phil Shiner. The two men go head to head in a legal and moral conflict that takes us from the battlefield, at so-called Checkpoint Danny Boy, to the courtroom and one of Britain’s biggest ever public inquiries, the Al-Sweady Inquiry.'),
(1816, '72213', 'en', 'https://image.tmdb.org/t/p/w500/hVRkbZRCoHtnfi0V9GFZ3uXjCNp.jpg', 'Courageous', '39.255', '2011-09-30', 7.5, '249', '[\'Drama\']', 'Law enforcement officers Adam Mitchell, Nathan Hayes, and their partners stand up to the worst the streets have to offer with confidence and focus. Yet at the end of the day, they face a challenge that none of them are truly prepared to tackle: fatherhood. They know that God desires to turn the hearts of fathers to their children, but their children are beginning to drift further and further away from them. When tragedy hits home, these men are left wrestling with their hopes, their fears, their faith, and their fathering. Can a newfound urgency help these dads draw closer to God... and to their children?'),
(1817, '738652', 'en', 'https://image.tmdb.org/t/p/w500/9LEWWWEhS7SZXFDuH1YYhs0VFct.jpg', 'Copshop', '38.772', '2021-09-09', 6.2, '99', '[\'Action\', \'Thriller\', \'Crime\']', 'On the run from a lethal assassin, a wily con artist devises a scheme to hide out inside a small-town police station. However, when the hit man turns up at the precinct, an unsuspecting rookie cop finds herself caught in the crosshairs.'),
(1818, '277216', 'en', 'https://image.tmdb.org/t/p/w500/1CiLJx8Xtv3TbbFj6k7BboSmKgC.jpg', 'Straight Outta Compton', '41.804', '2015-08-11', 7.8, '2972', '[\'Drama\', \'Music\']', 'In 1987, five young men, using brutally honest rhymes and hardcore beats, put their frustration and anger about life in the most dangerous place in America into the most powerful weapon they had: their music.  Taking us back to where it all began, Straight Outta Compton tells the true story of how these cultural rebels—armed only with their lyrics, swagger, bravado and raw talent—stood up to the authorities that meant to keep them down and formed the world’s most dangerous group, N.W.A.  And as they spoke the truth that no one had before and exposed life in the hood, their voice ignited a social revolution that is still reverberating today.'),
(1819, '4233', 'en', 'https://image.tmdb.org/t/p/w500/dORlVasiaDkJXTqt9bdH7nFNs6C.jpg', 'Scream 2', '38.748', '1997-12-09', 6.4, '2592', '[\'Horror\', \'Mystery\']', 'Two years after the terrifying events that occurred in Woodsboro, Sidney is now attending Windsor College in Cincinnati, and Gale Weathers\' best selling book on Sidney\'s life has now been made into a major motion picture. When two college students are killed in a theatre while watching the new film \'Stab\', Sidney knows deep down that history is repeating itself.'),
(1820, '282035', 'en', 'https://image.tmdb.org/t/p/w500/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', 'The Mummy', '40.989', '2017-06-06', 5.5, '5940', '[\'Fantasy\', \'Thriller\', \'Action\', \'Adventure\', \'Horror\']', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.'),
(1821, '522627', 'en', 'https://image.tmdb.org/t/p/w500/jtrhTYB7xSrJxR1vusu99nvnZ1g.jpg', 'The Gentlemen', '38.567', '2019-12-03', 7.7, '3684', '[\'Action\', \'Crime\', \'Comedy\']', 'American expat Mickey Pearson has built a highly profitable marijuana empire in London. When word gets out that he’s looking to cash out of the business forever it triggers plots, schemes, bribery and blackmail in an attempt to steal his domain out from under him.'),
(1822, '206487', 'en', 'https://image.tmdb.org/t/p/w500/38Xr1JnV1ZcLQ55zmdSp6n475cZ.jpg', 'Predestination', '50.147', '2014-08-28', 7.4, '5008', '[\'Science Fiction\', \'Thriller\']', 'Predestination chronicles the life of a Temporal Agent sent on an intricate series of time-travel journeys designed to prevent future killers from committing their crimes. Now, on his final assignment, the Agent must stop the one criminal that has eluded him throughout time and prevent a devastating attack in which thousands of lives will be lost.'),
(1823, '10380', 'en', 'https://image.tmdb.org/t/p/w500/k4aLupAkHWwHiEDwvqsZFAnUYF.jpg', 'An American Tail: Fievel Goes West', '32.737', '1991-11-21', 6.4, '567', '[\'Adventure\', \'Animation\', \'Family\', \'Western\']', 'Some time after the Mousekewitz\'s have settled in America, they find that they are still having problems with the threat of cats. That makes them eager to try another home out in the west, where they are promised that mice and cats live in peace. Unfortunately, the one making this claim is an oily con artist named Cat R. Waul who is intent on his own sinister plan.'),
(1824, '429', 'it', 'https://image.tmdb.org/t/p/w500/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg', 'Il buono, il brutto, il cattivo', '42.433', '1966-12-23', 8.5, '6218', '[\'Western\']', 'While the Civil War rages between the Union and the Confederacy, three men – a quiet loner, a ruthless hit man and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.'),
(1825, '271969', 'en', 'https://image.tmdb.org/t/p/w500/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg', 'Ben-Hur', '35.235', '2016-08-17', 5.7, '1392', '[\'Action\', \'History\', \'Adventure\', \'Drama\']', 'A falsely accused nobleman survives years of slavery to take vengeance on his best friend who betrayed him.'),
(1826, '581734', 'en', 'https://image.tmdb.org/t/p/w500/dKT8rGDR55cM1vGn7QZLA9Tg9YC.jpg', 'Nomadland', '40.387', '2021-01-29', 7.3, '1773', '[\'Drama\']', 'A woman in her sixties embarks on a journey through the western United States after losing everything in the Great Recession, living as a van-dwelling modern-day nomad.'),
(1827, '407436', 'en', 'https://image.tmdb.org/t/p/w500/clRnzMsFoMIdC7I5JsG6dnnHH8l.jpg', 'Mowgli: Legend of the Jungle', '29.787', '2018-11-25', 6.5, '2081', '[\'Adventure\', \'Drama\']', 'A human child raised by wolves, must face off against a menacing tiger named Shere Khan, as well as his own origins.'),
(1828, '13179', 'en', 'https://image.tmdb.org/t/p/w500/3Ma0r1n8kfH7UaQMS7bJ9KsYUjT.jpg', 'Tinker Bell', '35.273', '2008-09-11', 6.7, '1049', '[\'Animation\', \'Family\', \'Adventure\', \'Fantasy\']', 'Journey into the secret world of Pixie Hollow and hear Tinker Bell speak for the very first time as the astonishing story of Disney\'s most famous fairy is finally revealed in the all-new motion picture \"Tinker Bell.\"'),
(1829, '357096', 'en', 'https://image.tmdb.org/t/p/w500/qosIFCddpZjoMdsrkcQWB4UGm3o.jpg', 'I Spit on Your Grave III: Vengeance is Mine', '34.773', '2015-10-01', 5.7, '707', '[\'Horror\', \'Thriller\']', 'Jennifer Hills is still tormented by the brutal sexual assault she endured years ago. She’s changed identities and cities, reluctantly joining a support group where she begins to piece together a new life. But when her new friend’s murderer goes free and the tales of serial rapists haunt her, Jennifer will hunt down the men responsible and do what the system won’t – make them pay for their crimes in the most horrific ways imaginable. Only this time, no jury may be able to save her.'),
(1830, '83542', 'en', 'https://image.tmdb.org/t/p/w500/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg', 'Cloud Atlas', '28.618', '2012-10-26', 6.9, '5870', '[\'Drama\', \'Science Fiction\']', 'A set of six nested stories spanning time between the 19th century and a distant post-apocalyptic future. Cloud Atlas explores how the actions and consequences of individual lives impact one another throughout the past, the present and the future. Action, mystery and romance weave through the story as one soul is shaped from a killer into a hero and a single act of kindness ripples across centuries to inspire a revolution in the distant future.  Based on the award winning novel by David Mitchell. Directed by Tom Tykwer and the Wachowskis.'),
(1831, '2668', 'en', 'https://image.tmdb.org/t/p/w500/1GuK965FLJxqUw9fd1pmvjbFAlv.jpg', 'Sleepy Hollow', '37.814', '1999-11-18', 7.1, '5202', '[\'Drama\', \'Fantasy\', \'Thriller\', \'Mystery\', \'Horror\']', 'New York detective Ichabod Crane is sent to Sleepy Hollow to investigate a series of mysterious deaths in which the victims are found beheaded. Locals believe the culprit to be none other than the legendary Headless Horseman.'),
(1832, '445651', 'en', 'https://image.tmdb.org/t/p/w500/8NdQneXBYVbBKt81bFhXiyThe0h.jpg', 'The Darkest Minds', '37.677', '2018-07-25', 7, '2162', '[\'Science Fiction\', \'Action\', \'Drama\', \'Romance\', \'Adventure\', \'Thriller\']', 'After a disease kills 98% of America\'s children, the surviving 2% develop superpowers and are placed in internment camps. A 16-year-old girl escapes her camp and joins a group of other teens on the run from the government.'),
(1833, '507086', 'en', 'https://image.tmdb.org/t/p/w500/jbAvCACjLf1ZG0unB2tdmx5HAf1.jpg', 'Jurassic World: Dominion', '36.101', '2022-06-08', 0, '0', '[\'Adventure\', \'Action\', \'Science Fiction\', \'Thriller\']', 'Plot unknown.'),
(1834, '10066', 'en', 'https://image.tmdb.org/t/p/w500/aCLSgw1DaqkRvosYc3YUttBTtpT.jpg', 'House of Wax', '34.261', '2005-04-30', 5.8, '2206', '[\'Horror\', \'Drama\']', 'A group of unwitting teens are stranded near a strange wax museum and soon must fight to survive and keep from becoming the next exhibit.'),
(1835, '532142', 'ja', 'https://image.tmdb.org/t/p/w500/r5B6wrcsDEomFJj9P0vR6tx4wfA.jpg', 'CRYING FREE SEX', '30.039', '2018-09-08', 7.8, '9', '[]', 'Cobra and Naomi are working under cover and infiltrating a secret organization. They get hyped up and have sex, and their genitals get stuck together. The two fight against enemies, remaining stuck together. Can they make it through?'),
(1836, '11969', 'en', 'https://image.tmdb.org/t/p/w500/wGFCvylul8iEQhJOKfwZGGvXMzA.jpg', 'Tombstone', '32.252', '1993-12-25', 7.6, '1444', '[\'Western\', \'Action\']', 'Legendary marshal Wyatt Earp, now a weary gunfighter, joins his brothers Morgan and Virgil to pursue their collective fortune in the thriving mining town of Tombstone. But Earp is forced to don a badge again and get help from his notorious pal Doc Holliday when a gang of renegade brigands and rustlers begins terrorizing the town.'),
(1837, '11281', 'en', 'https://image.tmdb.org/t/p/w500/xyBX7rFmNB4nM2RBW3042RQPFG2.jpg', 'Halloween II', '40.151', '1981-10-30', 6.6, '1373', '[\'Horror\', \'Thriller\']', 'After failing to kill stubborn survivor Laurie and taking a bullet or six from former psychiatrist Dr. Sam Loomis, Michael Myers has followed Laurie to the Haddonfield Memorial Hospital, where she\'s been admitted for Myers\' attempt on her life. The institution proves to be particularly suited to serial killers, however, as Myers cuts, stabs and slashes his way through hospital staff to reach his favorite victim.'),
(1838, '399019', 'en', 'https://image.tmdb.org/t/p/w500/x4R9jyiZhJzevASus5n6WyHQTdR.jpg', 'The Beguiled', '37.506', '2017-06-23', 5.9, '1816', '[\'Drama\']', 'During the Civil War, at a Southern girls’ boarding school, young women take in an injured enemy soldier. As they provide refuge and tend to his wounds, the house is taken over with sexual tension and dangerous rivalries, and taboos are broken in an unexpected turn of events.'),
(1839, '378236', 'en', 'https://image.tmdb.org/t/p/w500/60bTx5z9zL1AqCjZ0gmWoRMJ6Bb.jpg', 'The Emoji Movie', '40.907', '2017-07-23', 5.6, '2398', '[\'Animation\', \'Family\', \'Comedy\']', 'Gene, a multi-expressional emoji, sets out on a journey to become a normal emoji.'),
(1840, '452006', 'en', 'https://image.tmdb.org/t/p/w500/tJHHygwJl2YQ9oM0o9PPKup59Xe.jpg', 'Talk Sex', '40.294', '2001-01-01', 5.2, '10', '[\'Romance\', \'Drama\']', 'An attractive radio hot line worker becomes romantically involved with callers.'),
(1841, '346685', 'en', 'https://image.tmdb.org/t/p/w500/AhTO2QWG0tug7yDoh0XoaMhPt3J.jpg', 'The Girl on the Train', '36.598', '2016-10-05', 6.4, '4807', '[\'Crime\', \'Drama\', \'Mystery\', \'Thriller\']', 'Rachel Watson, devastated by her recent divorce, spends her daily commute fantasizing about the seemingly perfect couple who live in a house that her train passes every day, until one morning she sees something shocking happen there and becomes entangled in the mystery that unfolds.'),
(1842, '520725', 'fr', 'https://image.tmdb.org/t/p/w500/iFcSfoMu9hQIX4t0CxIkDJKgIES.jpg', 'Le prince oublié', '32.516', '2020-02-12', 5.8, '266', '[\'Fantasy\', \'Adventure\', \'Comedy\']', 'Djibi lives alone with Sofia, his 8-year-old daughter. Every night, he invents a story to put him to sleep. When Sofia falls asleep, these extraordinary stories come to life somewhere in an imaginary world inhabited by knights, pirates and other dragons. In this world that belongs only to them, Sofia is always the princess to save, and the brave Prince is none other than Djibi himself.  But 3 years later, the entry of Sofia to the college will mark the end of her childhood. To the despair of her father, she no longer needs her stories at night. On the one hand, Djibi will have to accept that his daughter will grow up and move away from him. On the other hand, in the World of Stories, the Prince will have to face the most epic of all his adventures. Find your destiny in a world where it no longer has a place.'),
(1843, '369299', 'es', 'https://image.tmdb.org/t/p/w500/zWp8QZ1KxNrirNK9MF1EAIHjqVw.jpg', '¿Qué culpa tiene el niño?', '37.745', '2016-05-13', 7.6, '477', '[\'Comedy\', \'Romance\']', 'After a one-night stand results in pregnancy, a young woman decides to become partners with the emotionally immature father-to-be.'),
(1844, '716799', 'ja', 'https://image.tmdb.org/t/p/w500/8msQPxuA6fLpdSgbqIGCdP5VAS0.jpg', '461個のおべんとう', '41.846', '2020-11-06', 5, '2', '[\'Drama\', \'Family\']', 'Kazuki Suzumoto is divorced and he lives with his 15-year-old son Kouki. Kouki is in a susceptible time. The father feels guilty about his son. Kouki then fails his high school entrance exam. In the spring of the following year, Kouki barely passes his high school entrance exam. Kouki mentions to Kazuki that he likes his father\'s lunch box. The father and son make a promise to each other. Kazuki promises that he will make a lunch box everyday for Kouki. Kouki promises that he will never skip school.'),
(1845, '506281', 'en', 'https://image.tmdb.org/t/p/w500/6GJQXJ96FUbXtB01VXAdp854qOt.jpg', 'The World to Come', '36.8', '2021-02-12', 7.2, '156', '[\'Romance\', \'Drama\', \'Western\']', 'In 1856, two women forge a close connection despite their isolation on the American frontier.'),
(1846, '324849', 'en', 'https://image.tmdb.org/t/p/w500/snGwr2gag4Fcgx2OGmH9otl6ofW.jpg', 'The Lego Batman Movie', '36.189', '2017-02-08', 7.2, '3881', '[\'Family\', \'Action\', \'Animation\', \'Comedy\', \'Fantasy\']', 'A cooler-than-ever Bruce Wayne must deal with the usual suspects as they plan to rule Gotham City, while discovering that he has accidentally adopted a teenage orphan who wishes to become his sidekick.'),
(1847, '36586', 'en', 'https://image.tmdb.org/t/p/w500/yDHwo3eWcMiy5LnnEnlGV9iLu9k.jpg', 'Blade II', '39.23', '2002-03-22', 6.5, '3603', '[\'Fantasy\', \'Horror\', \'Action\', \'Thriller\']', 'A rare mutation has occurred within the vampire community - The Reaper. A vampire so consumed with an insatiable bloodlust that they prey on vampires as well as humans, transforming victims who are unlucky enough to survive into Reapers themselves. Blade is asked by the Vampire Nation for his help in preventing a nightmare plague that would wipe out both humans and vampires.'),
(1848, '479957', 'es', 'https://image.tmdb.org/t/p/w500/jnTYASRVkL5QPLeM0FeojTGRbgV.jpg', 'Desearás al hombre de tu hermana', '37.987', '2017-10-05', 5.8, '104', '[\'Romance\', \'Drama\']', 'Lucía and Ofelia, two sisters, finally meet after 7 years of cold relationships upon Lucia \'s wedding. But when Juan, Lucia\'s husband, and Ofelia meet, they feel like a disruptive fantasy have enchanted their minds and bodies...'),
(1849, '483455', 'ja', 'https://image.tmdb.org/t/p/w500/7ueB7Kxq2GObp5aDw6rsdzVefzP.jpg', '文豪ストレイドッグス DEAD APPLE', '38.943', '2018-03-03', 8.2, '82', '[\'Animation\', \'Action\', \'Comedy\', \'Mystery\', \'Crime\', \'Fantasy\']', 'A large scale catastrophe is occurring across the planet. Ability users are discovered after the appearance of a mysterious fog, apparently having committed suicide, so the Armed Detective Agency sets out to investigate these mysterious deaths. The case seems to involve an unknown ability user referred to as \"Collector,\" a man who could be the mastermind behind the incident.\r Trust and courage are put to the test in order to save the city of Yokohama and ability users across the world from the grip of Collector where the Armed Detective Agency forms an unlikely partnership with the dangerous Port Mafia.'),
(1850, '244786', 'en', 'https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg', 'Whiplash', '36.716', '2014-10-10', 8.4, '11542', '[\'Drama\', \'Music\']', 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.'),
(1851, '571627', 'ko', 'https://image.tmdb.org/t/p/w500/9Z2qT9iZYLzzsCSYu7A4SEQsKX0.jpg', '사자', '42.516', '2019-07-31', 6.7, '172', '[\'Action\', \'Horror\']', 'After waking up with mysterious wounds on his hands, a champion fighter finds himself in an otherworldly battle against evil forces that wreak havoc in the human world.'),
(1852, '483906', 'en', 'https://image.tmdb.org/t/p/w500/qOBEpKVLl8Q9CZScbOcRRVISezV.jpg', 'Polar', '35.684', '2019-01-25', 6.3, '1629', '[\'Action\', \'Crime\', \'Drama\']', 'When a retiring assassin realizes that he is the target of a hit, he winds up back in the game going head to head with a gang of younger, ruthless killers.'),
(1853, '1690', 'en', 'https://image.tmdb.org/t/p/w500/dDrtuWUKhgUGp12kgUWuP0NpTdF.jpg', 'Hostel', '37.211', '2006-01-06', 5.9, '2736', '[\'Horror\']', 'Three backpackers head to a Slovakian city that promises to meet their hedonistic expectations, with no idea of the hell that awaits them.'),
(1854, '18009', 'en', 'https://image.tmdb.org/t/p/w500/fnCLZ3rpy3enYSHrzcBxnx3fozK.jpg', 'Leprechaun 2', '32.959', '1994-04-07', 5.5, '203', '[\'Comedy\', \'Horror\']', 'A thousand years ago, the Leprechaun left a bloody trail when he ripped through the countryside in search of his stolen gold. Now he\'s back in the big city using all of his deadly tricks to snare the girl of his nightmares. His bloody quest becomes more deadly when her boyfriend steals one of the Leprechaun\'s gold coins. The town soon discovers two dead bodies and a trail of gold dust leads them to the Leprechaun\'s lair.'),
(1855, '44728', 'ja', 'https://image.tmdb.org/t/p/w500/fSqxVnjHE7zGAdWkhnQNYLJ2FUj.jpg', 'ONE PIECE 呪われた聖剣', '33.456', '2004-03-06', 7, '133', '[\'Animation\', \'Adventure\', \'Action\']', 'The Straw Hat Pirates landed at Asuka Island, home of the most valuable sword in the world: The Seven Star Sword. Which was said to curse anyone who takes it in possession. When they got back to the Going Merry, they discovered that Zoro is missing from his guard duty. Before they could plan out a search party to relocate him. Luffy and friends escape from the port as Marines were on their tail. They found a new place to dock, which is near a village. Whose job is to keep the Seven Star Sword sealed. Soon it was attacked by the Marines, and among them is Zoro. Luffy and the others don\'t know why he\'s helping out the Marines. But it all comes to conclusion when Luffy encounters Saga: Zoro\'s childhood friend from Swordsman training.'),
(1856, '489', 'en', 'https://image.tmdb.org/t/p/w500/z2FnLKpFi1HPO7BEJxdkv6hpJSU.jpg', 'Good Will Hunting', '41.855', '1997-12-05', 8.1, '9054', '[\'Drama\']', 'Will Hunting has a genius-level IQ but chooses to work as a janitor at MIT. When he solves a difficult graduate-level math problem, his talents are discovered by Professor Gerald Lambeau, who decides to help the misguided youth reach his potential. When Will is arrested for attacking a police officer, Professor Lambeau makes a deal to get leniency for him if he will get treatment from therapist Sean Maguire.'),
(1857, '51540', 'en', 'https://image.tmdb.org/t/p/w500/uQkUwgyFHAm0jGQERPG6Z9o9Zbj.jpg', 'Horrible Bosses', '40.404', '2011-07-08', 6.6, '5203', '[\'Comedy\', \'Crime\']', 'For Nick, Kurt and Dale, the only thing that would make the daily grind more tolerable would be to grind their intolerable bosses into dust. Quitting is not an option, so, with the benefit of a few-too-many drinks and some dubious advice from a hustling ex-con, the three friends devise a convoluted and seemingly foolproof plan to rid themselves of their respective employers... permanently.'),
(1858, '182026', 'en', 'https://image.tmdb.org/t/p/w500/4TKdguyacjYrC1Hnbi3PjSP8r3M.jpg', 'Stranger Things', '36.278', '2013-04-05', 8.3, '36', '[\'Drama\']', 'Oona, a recent graduate in anthropology, has returned to her dead mother’s seaside cottage in southern England to prepare it for sale. Her arrival disturbs Mani, a wary vagrant who has been squatting on the property.'),
(1859, '76544', 'en', 'https://image.tmdb.org/t/p/w500/wnuT1D0fsFu7chFLtcQqwPBaBVg.jpg', 'Man of Tai Chi', '36.944', '2013-07-04', 6, '667', '[\'Action\', \'Drama\']', 'In Beijing, a young martial artist\'s skill places him in position to experience opportunities and sacrifices.'),
(1860, '11397', 'en', 'https://image.tmdb.org/t/p/w500/9ZaGxvj1mqdKVLpSloq4mzS7SK6.jpg', 'Not Another Teen Movie', '34.639', '2001-12-07', 5.7, '1494', '[\'Comedy\']', 'On a bet, a gridiron hero at John Hughes High School sets out to turn a bespectacled plain Jane into a beautiful and popular prom queen in this outrageous send-up of the teen movies of the 1980s and \'90s.'),
(1861, '615129', 'en', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTiov-E4M5Y5OJEPspZubXwQPhlOVNwnhq_lQ&s', 'Pokémon Detective Pikachu 2', '36.675', '', 0, '0', '[\'Action\', \'Adventure\', \'Fantasy\']', 'Sequel to the 2019 film Pokémon Detective Pikachu'),
(1862, '476299', 'en', 'https://image.tmdb.org/t/p/w500/ma9gY6OikBev8MsMaeA6h2EIdGo.jpg', 'Ghostland', '36.684', '2018-03-14', 7.3, '1749', '[\'Horror\', \'Mystery\', \'Thriller\']', 'A mother of two inherits a home from her aunt. On the first night in the new home she is confronted with murderous intruders and fights for her daughters’ lives. Sixteen years later the daughters reunite at the house, and that is when things get strange . . .'),
(1863, '187257', 'en', 'https://image.tmdb.org/t/p/w500/yuDMPJvdNv9ze4yUi53cdyyUZuV.jpg', 'Fucking Different XXX', '41.323', '2012-02-08', 5.7, '5', '[\'Drama\']', 'In Fucking Different XXX, the passion for explicit sex scenes brought eight international filmmakers together. The eight short films shot in Paris, Berlin and San Francisco are about intensive sex, quick sex, romantic sex, funny sex, the first sex, and the last sex. The range goes from a lesbian quickie in the toilet, a bloodthirsty orgy, romantic fisting all the way to wet teenage dreams. The result is a never seen before look upon sexual tastes and varieties, far from clichés, with a fresh and sometimes humorous approach.'),
(1864, '41513', 'en', 'https://image.tmdb.org/t/p/w500/vRhnslP2gW0QDym7BsMeSuioUfK.jpg', 'The Smurfs', '34.773', '2011-07-29', 5.8, '3007', '[\'Animation\', \'Family\', \'Adventure\', \'Comedy\', \'Fantasy\']', 'When the evil wizard Gargamel chases the tiny blue Smurfs out of their village, they tumble from their magical world and into ours -- in fact, smack dab in the middle of Central Park. Just three apples high and stuck in the Big Apple, the Smurfs must find a way to get back to their village before Gargamel tracks them down.'),
(1865, '13761', 'en', 'https://image.tmdb.org/t/p/w500/gAnmNjw1TCTzS702mj1OwwmXBpM.jpg', 'Pocahontas II: Journey to a New World', '41.069', '1998-08-04', 5.4, '1101', '[\'Family\', \'Adventure\', \'Animation\', \'Romance\']', 'When news of John Smith\'s death reaches America, Pocahontas is devastated. She sets off to London with John Rolfe, to meet with the King of England on a diplomatic mission: to create peace and respect between the two great lands. However, Governor Ratcliffe is still around; he wants to return to Jamestown and take over. He will stop at nothing to discredit the young princess.'),
(1866, '127380', 'en', 'https://image.tmdb.org/t/p/w500/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg', 'Finding Dory', '41.261', '2016-06-16', 7.1, '10184', '[\'Adventure\', \'Animation\', \'Comedy\', \'Family\']', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?'),
(1867, '74997', 'en', 'https://image.tmdb.org/t/p/w500/9YEUMnMhIjD5ek4zIqOhLSnTnJS.jpg', 'The Human Centipede 2 (Full Sequence)', '37.172', '2011-10-06', 4.7, '962', '[\'Drama\', \'Horror\', \'Crime\']', 'Inspired by the fictional Dr. Heiter, disturbed loner Martin dreams of creating a 12-person centipede and sets out to realize his sick fantasy.'),
(1868, '527435', 'en', 'https://image.tmdb.org/t/p/w500/5Il2EMSF2KecrUKZPuen6BZmaCP.jpg', 'The Christmas Chronicles', '38.384', '2018-11-22', 7.1, '1538', '[\'Comedy\', \'Adventure\', \'Family\', \'Fantasy\']', 'Siblings Kate and Teddy try to prove Santa Claus is real, but when they accidentally cause his sleigh to crash, they have to save Christmas.'),
(1869, '752', 'en', 'https://image.tmdb.org/t/p/w500/piZOwjyk1g51oPHonc7zaQY3WOv.jpg', 'V for Vendetta', '39.417', '2006-02-23', 7.9, '11644', '[\'Action\', \'Thriller\', \'Fantasy\']', 'In a world in which Great Britain has become a fascist state, a masked vigilante known only as “V” conducts guerrilla warfare against the oppressive British government. When V rescues a young woman from the secret police, he finds in her an ally with whom he can continue his fight to free the people of Britain.'),
(1870, '1417', 'es', 'https://image.tmdb.org/t/p/w500/z7xXihu5wHuSMWymq5VAulPVuvg.jpg', 'El laberinto del fauno', '38.466', '2006-08-25', 7.7, '8520', '[\'Fantasy\', \'Drama\', \'War\']', 'Living with her tyrannical stepfather in a new home with her pregnant mother, 10-year-old Ofelia feels alone until she explores a decaying labyrinth guarded by a mysterious faun who claims to know her destiny. If she wishes to return to her real father, Ofelia must complete three terrifying tasks.'),
(1871, '342473', 'en', 'https://image.tmdb.org/t/p/w500/2VUmvqsHb6cEtdfscEA6fqqVzLg.jpg', 'Ballerina', '40.772', '2016-12-14', 7.2, '1539', '[\'Animation\', \'Adventure\', \'Comedy\', \'Family\']', 'Set in 1879 Paris. An orphan girl dreams of becoming a ballerina and flees her rural Brittany for Paris, where she passes for someone else and accedes to the position of pupil at the Grand Opera house.'),
(1872, '286567', 'en', 'https://image.tmdb.org/t/p/w500/AuEzNLF8yvzd169guYEFisqvy5z.jpg', 'Max Steel', '47.422', '2016-10-14', 5.6, '601', '[\'Action\', \'Adventure\', \'Science Fiction\']', 'The adventures of teenager Max McGrath and alien companion Steel, who must harness and combine their tremendous new powers to evolve into the turbo-charged superhero Max Steel.'),
(1873, '397567', 'ko', 'https://image.tmdb.org/t/p/w500/gJSvIsI6oQfFim0PGyuuiCYfqKs.jpg', '신과함께-죄와 벌', '34.421', '2017-12-14', 8.1, '450', '[\'Drama\', \'Fantasy\', \'Action\']', 'Having died unexpectedly, firefighter Ja-hong is taken to the afterlife by 3 afterlife guardians. Only when he passes 7 trials over 49 days and proves he was innocent in human life, he’s able to reincarnate, and his 3 afterlife guardians are by his side to defend him in trial.'),
(1874, '585381', 'es', 'https://image.tmdb.org/t/p/w500/33dxxU2Z6eQM6VU7QPN8lZM5o9a.jpg', 'Souvenir', '32.232', '2021-03-04', 6.5, '25', '[\'Drama\']', 'The enigmatic Isabel decides to rent her belly to give birth to the baby of Sara and Joaquin, a possessive couple obsessed with the idea of starting a family.');
